(def no-dynamic-profiles #{:core :kernel :firmware :hardware})
(def no-scheduler-profiles #{:core :firmware :hardware})

(def profile-denied-effects
  {:core #{:io/write :filesystem/read :filesystem/write :network/http
           :thread/spawn :time/schedule :reflection/use :dynamic/eval}
   :firmware #{:io/write :network/http :thread/spawn :time/schedule
               :reflection/use :dynamic/eval}
   :hardware #{:io/write :network/http :thread/spawn :time/schedule
               :reflection/use :dynamic/eval :time/read}})

(def typed-internal-effects #{:control/recur :state/write :error/throw})

(defn stable-set
  [values]
  (set values))

(defn stable-vec
  [values]
  (vec (sort-by pr-str values)))

(defn provider-name
  [capability]
  (get-in provider-specs [capability :provider]))

(defn provider-version
  [capability]
  (get-in provider-specs [capability :version]))

(defn provider-trust-level
  [capability]
  (or (get-in provider-specs [capability :trust-level])
      :trusted-core))

(defn provider-artifact-schema
  [capability]
  (or (get-in provider-specs [capability :artifact-schema])
      (keyword "gravity.provider" (name capability))))

(defn provider-conformance-suite
  [capability]
  (or (get-in provider-specs [capability :conformance])
      (keyword "gravity.conformance" (name capability))))

(defn provider-contracts
  [capability]
  (or (get-in provider-specs [capability :contracts])
      #{'gravity.contracts/Provider}))

(defn provider-scope-kind
  [capability]
  (case capability
    :filesystem/read :filesystem
    :filesystem/write :filesystem
    :network/client :network
    :network/listener :network
    :ai/model :model
    :ai/tool :tool
    :ai/memory :memory-store
    :memory/allocator :memory
    :memory/raw :memory
    :compiler/ir :compiler
    :compiler/plugin :compiler
    :io/stdout :io
    :environment/read :environment
    :provider))

(defn typed-diagnostic!
  ([id message node remediation]
   (typed-diagnostic! id message node remediation {}))
  ([id message node remediation data]
   (fail! id message
          (merge {:source-span (:source-span node)
                  :analyzer-stage :typed-effected-core
                  :remediation remediation}
                 data))))

