                                 :profile (dispatch-arg-value args 2)
                                 :target (dispatch-arg-value args 3)
                                 :source (dispatch-arg-value args 4)
                                 :expected (dispatch-arg-value args 5)}))

        :safe16-expected-outcome
        (record-checker! checker :safe16-expected-outcome-manifests
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :document-id (dispatch-arg-value args 1)
                                 :expected-verdict (dispatch-arg-value args 2)
                                 :operation-outcome (dispatch-arg-value args 3)
                                 :diagnostic-id (dispatch-arg-value args 4)
                                 :artifact-inspections (or (dispatch-arg-value args 5) #{})}))

        :safe16-diagnostic-match
        (record-checker! checker :safe16-diagnostic-match-records
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :expected-diagnostic (dispatch-arg-value args 1)
                                 :actual-diagnostic (dispatch-arg-value args 2)
                                 :span-matched? (boolean (dispatch-arg-value args 3))
                                 :status :matched}))

        :safe16-runtime-check-inspection
        (record-checker! checker :safe16-runtime-check-inspections
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :check-record (dispatch-arg-value args 1)
                                 :expected-outcome (dispatch-arg-value args 2)
                                 :status :inspected}))

        :safe16-unsafe-audit-inspection
        (record-checker! checker :safe16-unsafe-audit-inspections
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :unsafe-island (dispatch-arg-value args 1)
                                 :audit-record (dispatch-arg-value args 2)
                                 :status :inspected}))

        :safe16-certificate-inspection
        (record-checker! checker :safe16-certificate-inspections
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :certificate-id (dispatch-arg-value args 1)
                                 :proof-id (dispatch-arg-value args 2)
                                 :status :inspected}))

        :safe16-profile-matrix
        (record-checker! checker :safe16-profile-matrix-reports
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :profiles (or (dispatch-arg-value args 1) #{})
                                 :expected-results (dispatch-arg-value args 2)
                                 :status :passed}))

        :safe16-backend-preservation
        (record-checker! checker :safe16-backend-preservation-reports
                         (merge record
                                {:fixture-id (dispatch-arg-value args 0)
                                 :backend (dispatch-arg-value args 1)
                                 :preserved-facts (or (dispatch-arg-value args 2) #{})
                                 :retained-checks (or (dispatch-arg-value args 3) #{})
                                 :status :passed}))

        :safe16-conformance-report
        (record-checker! checker :safe16-conformance-reports
                         (merge record
                                {:compiler-id (dispatch-arg-value args 0)
                                 :compiler-version (dispatch-arg-value args 1)
                                 :fixture-count (or (dispatch-arg-value args 2) 0)
                                 :diagnostics-matched (or (dispatch-arg-value args 3) 0)
                                 :artifacts-inspected (or (dispatch-arg-value args 4) 0)
                                 :status (or (dispatch-arg-value args 5)
                                             :passed)}))

        :safe16-conformance
        (record-checker! checker :safe16-conformance-records
                         (merge record
                                {:document :SAFE16
                                 :status (or (dispatch-arg-value args 0)
                                             :complete)
                                 :positive-fixtures :passed
                                 :negative-fixtures :passed}))

        nil)
      record)))

(defn check-call-node
  [checker ctx node]
  (let [operator (:operator node)]
    (call-specific-diagnostic! operator node)
    (cond
      (= 'effect/handle operator)
      (check-effect-handle-node checker ctx node)

      (= 'task/scope operator)
      (let [child (child-context ctx)]
        (swap! child assoc
               :in-task-scope? true
               :task-scope-id (:node-id node))
        (let [args (mapv #(check-typed-node checker child %) (:arguments node))
              effects (collect-fact-effects args)
              capabilities (collect-fact-capabilities args)
              spec (get call-specs operator)]
          (check-effects-and-capabilities! checker ctx node effects capabilities)
          (record-concurrency-call! checker child node operator args effects
                                    capabilities spec)
          (typed-fact checker node (:return-type spec) effects capabilities
                      {:children args
                       :callee operator})))
      :else
      (let [args (mapv #(check-typed-node checker ctx %) (:arguments node))
            spec (get call-specs operator)]
        (if (nil? spec)
          (do
            (when (contains? #{:native :kernel :firmware :hardware :formal} (:profile @ctx))
              (typed-diagnostic! "L5-ANNOTATION-REQUIRED"
                                 "constrained profile requires type facts for this call"
                                 node
                                 "Add a checked declaration or provider fact before using this call in a constrained profile."
                                 {:profile (:profile @ctx)
                                  :operator operator}))
            (typed-fact checker node "Dynamic"
                        (collect-fact-effects args)
                        (collect-fact-capabilities args)
                        {:children args
                         :callee operator}))
          (do
            (when (and (= 'dynamic/value operator)
                       (contains? no-dynamic-profiles (:profile @ctx)))
              (typed-diagnostic! "L5-DYNAMIC-FORBIDDEN"
                                 "dynamic value is forbidden in this profile"
                                 node
                                 "Use a statically typed value or add a profile-approved runtime check boundary."
                                 {:profile (:profile @ctx)}))
            (when (= 'typed/assert operator)
              (check-typed-assert! node args))
            (when (= 'typed/value operator)
              (check-typed-value! node args))
            (when (= 'typed/return operator)
              (check-typed-return! node args))
            (when (= 'raw/deref operator)
              (typed-diagnostic! "L10-RAW-SAFE"
                                 "raw pointer operation appears in safe core without an unsafe island"
                                 node
                                 "Wrap raw memory behind an audited unsafe island or safe checked API."))
            (when (= 'task/spawn operator)
              (when (contains? no-scheduler-profiles (:profile @ctx))
                (typed-diagnostic! "L11-SCHEDULER"
                                   "active profile lacks required scheduler/runtime support"
                                   node
                                   "Use a profile-supported scheduler provider or remove task spawning."
                                   {:profile (:profile @ctx)}))
              (when-not (:in-task-scope? @ctx)
                (typed-diagnostic! "L11-TASK-SCOPE"
                                   "task spawn escapes structured task scope"
                                   node
                                   "Spawn tasks inside task/scope or transfer the handle through an explicit contract.")))
            (when (= 'resource/close operator)
              (consume-linear-resource! checker ctx node args))
            (let [effects (set/union (collect-fact-effects args) (or (:effects spec) #{}))
                  capabilities (set/union (collect-fact-capabilities args) (or (:capabilities spec) #{}))
                  return-type (asserted-return-type operator args spec)]
              (when (:compile-time-kind spec)
                (check-compile-time-policy! ctx node args effects spec))
              (check-effects-and-capabilities! checker ctx node effects capabilities
                                               (select-keys spec [:capability-diagnostic
                                                                  :build-grant-diagnostic]))
              (record-memory-call! checker ctx node operator args effects
                                   capabilities return-type spec)
              (record-concurrency-call! checker ctx node operator args effects
                                        capabilities spec)
              (record-compile-time-call! checker ctx node operator args effects
                                         capabilities return-type spec)
	              (record-standard-library-call! checker ctx node operator args effects
	                                             capabilities return-type spec)
	              (record-facet-call! checker ctx node operator args effects
	                                  capabilities return-type spec)
	              (record-provider-call! checker ctx node operator args effects
	                                     capabilities return-type spec)
	              (record-alternative-macro-call! checker ctx node operator args effects
	                                              capabilities return-type spec)
	              (record-alternative-type-call! checker ctx node operator args effects
	                                             capabilities return-type spec)
	              (record-alternative-memory-call! checker ctx node operator args effects
	                                               capabilities return-type spec)
	              (record-interop-call! checker ctx node operator args effects
	                                    capabilities return-type spec)
	              (record-safe1-call! checker ctx node operator args effects
	                                  capabilities return-type spec)
	              (record-safe-memory-call! checker ctx node operator args effects
	                                        capabilities return-type spec)
	              (record-safe6-call! checker ctx node operator args effects
	                                  capabilities return-type spec)
	              (record-boundary-safety-call! checker ctx node operator args
	                                            effects capabilities
	                                            return-type spec)
		              (record-safe-capability-call! checker ctx node operator args
		                                            effects capabilities
		                                            return-type spec)
		              (record-safety-conformance-call! checker ctx node operator args
		                                               effects capabilities
		                                               return-type spec)
		              (when (or (= "Dynamic" return-type) (= 'dynamic/cast operator))
	                (record-checker! checker :dynamic-boundary-records
	                                 {:node-id (:node-id node)
                                  :profile (:profile @ctx)
                                  :boundary operator
                                  :effects (:effects spec #{})
                                  :runtime-check (when (= 'dynamic/cast operator) :checked)}))
              (when (= 'dynamic/cast operator)
                (record-checker! checker :runtime-check-records
                                 {:node-id (:node-id node)
                                  :kind :dynamic-cast
                                  :target-type return-type
                                  :source-type (:type (second args))
                                  :status :runtime-checked}))
              (when (contains? #{'schema/derive 'schema/validate} operator)
                (record-checker! checker :schema-type-links
                                 {:node-id (:node-id node)
                                  :schema (:value (first args))
                                  :type return-type
                                  :schema-identity (:value (first args))
                                  :validation-boundary (if (= 'schema/validate operator)
                                                         :validated
                                                         :preserved)
                                  :nullability :preserved
                                  :optionality :preserved
                                  :bounds :preserved
                                  :refinements :preserved
                                  :taint :preserved}))
              (when (= 'generic/id operator)
                (record-checker! checker :generic-instantiation-records
                                 {:node-id (:node-id node)
                                  :generic 'generic/id
                                  :type-arguments (mapv :type args)
                                  :result-type return-type}))
              (record-dispatch-call! checker node operator args effects capabilities)
              (record-error-call! checker node operator args effects capabilities)
              (typed-fact checker node return-type effects capabilities
                          {:children args
                           :callee operator}))))))))

(def l7-required-pattern-families
  [:literal :record :map :vector :constructor :enum :guard :default :schema
   :linear])

(defn wildcard-pattern?
  [pattern]
  (= '_ pattern))

(defn constructor-pattern?
  [pattern]
  (and (seq? pattern) (symbol? (first pattern))))

(defn constructor-name
  [pattern]
  (when (constructor-pattern? pattern)
    (name (first pattern))))

(defn pattern-kind
  [pattern]
  (cond
    (wildcard-pattern? pattern) :wildcard
    (vector? pattern) :vector
    (map? pattern) :map
    (constructor-pattern? pattern) :constructor
    (or (nil? pattern) (true? pattern) (false? pattern)
        (number? pattern) (string? pattern) (keyword? pattern)) :literal
    (symbol? pattern) :binding
    :else :unknown))

(defn pattern-family
  [pattern]
  (cond
    (wildcard-pattern? pattern) :default
    (and (constructor-pattern? pattern)
         (#{"Borrow" "MoveLinear"} (constructor-name pattern))) :linear
    (and (constructor-pattern? pattern)
         (#{"Vec3" "User"} (constructor-name pattern))) :record
    (constructor-pattern? pattern) :constructor
    (keyword? pattern) :enum
    :else (pattern-kind pattern)))

(defn pattern-bindings
  [pattern]
  (cond
    (or (wildcard-pattern? pattern)
        (nil? pattern)
        (true? pattern)
        (false? pattern)
        (number? pattern)
        (string? pattern)
        (keyword? pattern)) []
    (symbol? pattern) [pattern]
    (vector? pattern) (mapcat pattern-bindings pattern)
    (map? pattern) (mapcat pattern-bindings (vals pattern))
    (constructor-pattern? pattern) (mapcat pattern-bindings (rest pattern))
    :else []))

(defn duplicate-binding
  [pattern]
  (first (for [[binding n] (frequencies (pattern-bindings pattern))
               :when (> n 1)]
           binding)))

(defn literal-pattern-type
  [pattern]
  (when (= :literal (pattern-kind pattern))
    (literal-type pattern)))

(defn literal-pattern-incompatible?
  [scrutinee-type pattern]
  (let [pattern-type (literal-pattern-type pattern)]
    (and pattern-type
         (#{"Nil" "Boolean" "Integer" "String" "Keyword"} scrutinee-type)
         (not= pattern-type scrutinee-type))))

(defn untrusted-type?
  [type-name]
  (and (string? type-name) (str/starts-with? type-name "Untrusted[")))

(defn validated-type?
  [type-name]
  (and (string? type-name) (str/starts-with? type-name "Validated[")))

(defn narrowed-type
  [scrutinee-type pattern]
  (case (pattern-kind pattern)
    :wildcard scrutinee-type
    :binding scrutinee-type
    :literal (or (literal-pattern-type pattern) "Dynamic")
    :vector "Vector"
    :map "Map"
    :constructor (or (constructor-name pattern) "Constructor")
    "Dynamic"))

(defn all-registered-effects
  []
  (set (keys effect-registry)))

(defn all-registered-capabilities
  []
  (set (keys provider-specs)))

(defn permissive-pattern-context
  [ctx]
  (atom (assoc @ctx
               :declared-effects (all-registered-effects)
               :declared-capabilities (all-registered-capabilities))))

(defn guard-effects-illegal?
  [ctx guard-fact]
  (let [declared-effects (:declared-effects @ctx)
        declared-capabilities (:declared-capabilities @ctx)
        denied-effects (get profile-denied-effects (:profile @ctx) #{})]
    (or (some denied-effects (:effects guard-fact))
        (some #(not (contains? declared-effects %)) (:effects guard-fact))
        (some #(not (contains? declared-capabilities %)) (:capabilities guard-fact)))))

(defn constructor-coverage
  [patterns]
  (set (keep constructor-name patterns)))

(defn closed-result-match?
  [patterns]
  (seq (set/intersection #{"Ok" "Err"} (constructor-coverage patterns))))

(defn exhaustive-result-match?
  [patterns]
  (set/subset? #{"Ok" "Err"} (constructor-coverage patterns)))

(defn match-conformance-fixture
  [checker-state]
  (let [covered (->> (concat (mapcat :pattern-families (:match-decision-trees checker-state))
                             (when (seq (:branch-effect-summary checker-state)) [:guard])
                             (when (seq (:pattern-schema-validation-links checker-state)) [:schema])
                             (when (seq (:pattern-ownership-facts checker-state)) [:linear]))
                     (remove nil?)
                     set
                     (sort-by name)
                     vec)
        covered-set (set covered)
        missing (vec (remove covered-set l7-required-pattern-families))]
    {:required-families l7-required-pattern-families
     :covered-families covered
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(defn method-contract-value
  [items key default]
  (let [pairs (partition 2 2 nil items)]
    (or (some (fn [[k v]]
                (when (= key k) v))
              pairs)
        default)))

(defn parse-method-contract
  [protocol-name method-form]
  (let [[method-name params & tail] method-form
        return-type (if-let [marker-pos (first (keep-indexed (fn [idx value]
                                                               (when (= ':- value) idx))
                                                             tail))]
                      (type-form-name (nth tail (inc marker-pos)))
                      "Dynamic")
        metadata-tail (drop-while #(not (keyword? %)) tail)]
    {:protocol protocol-name
     :method method-name
     :arity (count params)
     :receiver-position 0
     :parameter-types (vec (repeat (count params) "Dynamic"))
     :return-type return-type
     :effects (method-contract-value metadata-tail :effects #{})
     :capabilities (method-contract-value metadata-tail :capabilities #{})
     :profile-restrictions #{}
     :default-implementation nil
     :stability :stage0
     :source-form method-form}))

(defn protocol-table-from-forms
  [forms]
  (->> forms
       (keep (fn [form]
               (when (and (seq? form) (= 'defprotocol (first form)))
                 (let [protocol-name (second form)
                       methods (mapv #(parse-method-contract protocol-name %) (drop 2 form))]
                   {:protocol protocol-name
                    :methods methods
                    :source-form form}))))
       vec))

(defn method-signature-records
  [protocol-table]
  (vec (mapcat :methods protocol-table)))

(defn find-method-contract
  [protocol-table protocol-name method-name]
  (some (fn [protocol]
          (when (= protocol-name (:protocol protocol))
            (some #(when (= method-name (:method %)) %) (:methods protocol))))
        protocol-table))

(defn implementation-table-from-forms
  [forms protocol-table]
  (->> forms
       (keep (fn [form]
               (when (and (seq? form) (= 'extend (first form)))
                 (let [type-name (second form)
                       protocol-name (nth form 2)
                       methods (drop 3 form)]
                   (mapv (fn [method-form]
                           (let [method-name (first method-form)
                                 contract (find-method-contract protocol-table protocol-name method-name)]
                             {:type type-name
                              :protocol protocol-name
                              :method method-name
                              :arity (count (second method-form))
                              :effects (or (:effects contract) #{})
                              :capabilities (or (:capabilities contract) #{})
                              :dispatch-mode :direct
                              :implementation (symbol (str type-name) (str method-name))
                              :source-form method-form}))
                         methods)))))
       (mapcat identity)
       vec))

(defn multimethod-tables-from-forms
  [forms]
  (->> forms
       (keep (fn [form]
               (when (and (seq? form) (= 'defmulti (first form)))
                 (let [name (second form)
                       metadata (if (map? (nth form 2 nil)) (nth form 2) {})]
                   {:multimethod name
                    :dispatch (:dispatch metadata)
                    :closed-cases (or (:closed-cases metadata) #{})
                    :dispatch-mode :multimethod
                    :source-form form}))))
       vec))

(defn interface-lowering-artifacts
  [implementation-table dispatch-mode-records]
  (vec (concat
        (map (fn [implementation]
               {:protocol (:protocol implementation)
                :type (:type implementation)
                :method (:method implementation)
                :lowering (:dispatch-mode implementation)
                :implementation (:implementation implementation)})
             implementation-table)
        (map (fn [record]
               {:protocol (:protocol record)
                :type (:receiver record)
                :method (:method record)
                :lowering (:dispatch-mode record)
                :implementation (:implementation record)})
             (filter #(contains? #{:dictionary :vtable :host-interface}
                                  (:dispatch-mode %))
                     dispatch-mode-records)))))

(def l8-required-dispatch-families
  [:protocol :implementation :method-signature :direct :dictionary :vtable
   :hosted-dynamic :multimethod :host-interop :tool :interface-lowering
   :method-effects])

(defn dispatch-conformance-fixture
  [protocol-table implementation-table method-signatures dispatch-records
   multimethods interface-artifacts host-records]
  (let [modes (set (map :dispatch-mode dispatch-records))
        covered (cond-> #{}
                  (seq protocol-table) (conj :protocol)
                  (seq implementation-table) (conj :implementation)
                  (seq method-signatures) (conj :method-signature)
                  (contains? modes :direct) (conj :direct)
                  (contains? modes :dictionary) (conj :dictionary)
                  (contains? modes :vtable) (conj :vtable)
                  (contains? modes :hosted-dynamic) (conj :hosted-dynamic)
                  (seq multimethods) (conj :multimethod)
                  (seq host-records) (conj :host-interop)
                  (contains? modes :artifact-boundary) (conj :tool)
                  (seq interface-artifacts) (conj :interface-lowering)
                  (some seq (map :effects dispatch-records)) (conj :method-effects))
        missing (vec (remove covered l8-required-dispatch-families))]
    {:required-families l8-required-dispatch-families
     :covered-families (vec (sort-by name covered))
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(def l9-required-error-families
  [:option :result :try :throw :panic :safety-check :host-error :ffi-error
   :workflow-error :ai-error])

(defn error-conformance-fixture
  [checker-state type-facts]
  (let [covered (cond-> #{}
                  (some #(= :option (:family %)) (:error-type-declarations checker-state)) (conj :option)
                  (some #(= :result (:family %)) (:error-type-declarations checker-state)) (conj :result)
                  (some #(= :try (:source-kind %)) type-facts) (conj :try)
                  (seq (:thrown-error-effect-records checker-state)) (conj :throw)
                  (seq (:panic-lowering-records checker-state)) (conj :panic)
                  (seq (:safety-check-failure-records checker-state)) (conj :safety-check)
                  (seq (:host-error-normalization-records checker-state)) (conj :host-error)
                  (seq (:ffi-error-mapping-artifacts checker-state)) (conj :ffi-error)
                  (seq (:workflow-failure-records checker-state)) (conj :workflow-error)
                  (seq (:ai-tool-error-records checker-state)) (conj :ai-error))
        missing (vec (remove covered l9-required-error-families))]
    {:required-families l9-required-error-families
     :covered-families (vec (sort-by name covered))
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(def l10-required-memory-families
  [:gc :ownership :borrow :region :arena :stack :static :linear :raw :mmio
   :gpu-device :host-managed :initialization :allocation-effect
   :allocator-runtime :bounds-check])

(defn memory-conformance-fixture
  [checker-state]
  (let [memory-families (set (keep :family (:memory-facts checker-state)))
        covered (cond-> memory-families
                  (seq (:linear-resource-table checker-state)) (conj :linear)
                  (seq (:allocation-effect-records checker-state)) (conj :allocation-effect)
                  (seq (:allocator-runtime-manifests checker-state)) (conj :allocator-runtime)
                  (some #(= :bounds (:kind %)) (:runtime-check-records checker-state)) (conj :bounds-check)
                  (seq (:unsafe-raw-memory-audit-records checker-state)) (conj :raw)
                  (seq (:mmio-capability-records checker-state)) (conj :mmio)
                  (seq (:initialization-facts checker-state)) (conj :initialization)
                  (seq (:lifetime-region-facts checker-state)) (into [:region :arena])
                  (seq (:ownership-borrow-facts checker-state)) (conj :ownership))
        missing (vec (remove covered l10-required-memory-families))]
    {:required-families l10-required-memory-families
     :covered-families (vec (sort-by name covered))
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(def l11-required-concurrency-families
  [:task-scope :structured-task :async-await :atomic :lock :channel :actor
   :ownership-transfer :immutable-sharing :workflow-replay :scheduler-runtime
   :hardware-state :gpu-kernel :race-analysis])

(defn concurrency-conformance-fixture
  [checker-state]
  (let [fact-families (set (keep :conformance-family (:concurrency-facts checker-state)))
        covered (cond-> fact-families
                  (seq (:task-scope-graphs checker-state)) (conj :task-scope)
                  (seq (:scheduler-runtime-manifests checker-state)) (conj :scheduler-runtime)
                  (seq (:workflow-replay-records checker-state)) (conj :workflow-replay)
                  (seq (:race-analysis-reports checker-state)) (conj :race-analysis)
                  (some #(= :atomic (:primitive %)) (:synchronization-facts checker-state)) (conj :atomic)
                  (some #(= :lock (:primitive %)) (:synchronization-facts checker-state)) (conj :lock)
                  (some #(= :hardware-state (:primitive %)) (:synchronization-facts checker-state)) (conj :hardware-state)
                  (some #(= :gpu-barrier (:primitive %)) (:synchronization-facts checker-state)) (conj :gpu-kernel)
                  (some #(= :channel (:kind %)) (:actor-channel-schemas checker-state)) (conj :channel)
                  (some #(= :actor (:kind %)) (:actor-channel-schemas checker-state)) (conj :actor)
                  (seq (:concurrency-ownership-transfer-records checker-state)) (conj :ownership-transfer))
        missing (vec (remove covered l11-required-concurrency-families))]
    {:required-families l11-required-concurrency-families
     :covered-families (vec (sort-by name covered))
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

(def l12-required-compile-time-families
  [:pure-constant :defconst :schema-loading :write-artifact :target-probe
   :generated-code :model-codegen :nondeterministic-replay :cache-decision
   :build-effect-log :grant-record :hermetic-replay :cache-key])

(defn compile-time-conformance-fixture
  [checker-state build-log]
  (let [trace-kinds (set (keep :compile-time-kind
                               (:compile-time-evaluation-trace checker-state)))
        covered (cond-> trace-kinds
                  (seq (:constant-value-table checker-state)) (conj :defconst)
                  (seq (:generated-form-provenance-records checker-state)) (conj :generated-code)
                  (seq build-log) (conj :build-effect-log)
                  (seq (:compile-time-capability-proof-records checker-state)) (conj :grant-record)
                  (seq (:hermetic-replay-records checker-state)) (conj :hermetic-replay)
                  (seq (:cache-key-records checker-state)) (conj :cache-key))
        missing (vec (remove covered l12-required-compile-time-families))]
    {:required-families l12-required-compile-time-families
     :covered-families (vec (sort-by name covered))
     :missing-families missing
     :status (if (empty? missing) :complete :incomplete)}))

