(def standard-profile-order
  [:core :meta :hosted :native :firmware :kernel :hardware :distributed :ai
   :gpu :formal])

(def p1-diagnostic-ids
  ["P1-MISSING-PROFILE" "P1-AMBIGUOUS-PROFILE" "P1-EFFECT"
   "P1-CAPABILITY" "P1-MEMORY" "P1-RUNTIME" "P1-CROSS-IMPORT"
   "P1-MACRO" "P1-FACET" "P1-BACKEND"])

(def p1-diagnostic-messages
  {"P1-MISSING-PROFILE" "namespace is missing an active profile declaration"
   "P1-AMBIGUOUS-PROFILE" "namespace has conflicting profile declarations"
   "P1-EFFECT" "effect is outside the effective profile authority"
   "P1-CAPABILITY" "capability authority is missing or narrowed"
   "P1-MEMORY" "memory regime is illegal for the active profile"
   "P1-RUNTIME" "runtime assumption is unavailable for the active profile"
   "P1-CROSS-IMPORT" "cross-profile import lacks a facade or artifact boundary"
   "P1-MACRO" "macro output violates the caller profile"
   "P1-FACET" "facet is outside active profile support"
   "P1-BACKEND" "backend or target is ineligible for the profile manifest"})

(def p1-underlying-diagnostic-map
  {"L3-NS-MISSING" "P1-MISSING-PROFILE"
   "L3-PROFILE-MULTIPLE" "P1-AMBIGUOUS-PROFILE"
   "L3-CROSS-PROFILE" "P1-CROSS-IMPORT"
   "L3-EFFECT-WIDEN" "P1-EFFECT"
   "L6-EFFECT-PROFILE" "P1-EFFECT"
   "L6-EFFECT-UNDECLARED" "P1-EFFECT"
   "L3-CAPABILITY-MISSING" "P1-CAPABILITY"
   "L6-EFFECT-CAPABILITY" "P1-CAPABILITY"
   "L15-CAPABILITY-MISSING" "P1-CAPABILITY"
   "L15-PROFILE" "P1-CAPABILITY"
   "L10-HIDDEN-ALLOC" "P1-MEMORY"
   "L10-RAW-SAFE" "P1-MEMORY"
   "L10-MMIO-CAP" "P1-MEMORY"
   "SAFE2-PROFILE" "P1-MEMORY"
   "L11-SCHEDULER" "P1-RUNTIME"
   "L11-TASK-SCOPE" "P1-RUNTIME"
   "L4-GENERATED-PROFILE" "P1-MACRO"
   "L4-GENERATED-UNSAFE" "P1-MACRO"
   "L14-PROFILE" "P1-FACET"
   "B1-TARGET-UNSUPPORTED" "P1-BACKEND"})

(def profile-memory-regimes
  {:core {:managed false
          :ownership true
          :regions false
          :hidden-allocation :forbidden
          :raw-memory :forbidden}
   :meta {:managed true
          :ownership false
          :regions false
          :hidden-allocation :declared
          :raw-memory :forbidden}
   :hosted {:managed true
            :ownership false
            :regions false
            :hidden-allocation :declared
            :raw-memory :unsafe-only}
   :native {:managed false
            :ownership true
            :regions true
            :hidden-allocation :declared
            :raw-memory :unsafe-only}
   :firmware {:managed false
              :ownership true
              :regions true
              :hidden-allocation :forbidden
              :raw-memory :unsafe-only}
   :kernel {:managed false
            :ownership true
            :regions true
            :hidden-allocation :forbidden
            :raw-memory :unsafe-only}
   :hardware {:managed false
              :ownership true
              :regions true
              :hidden-allocation :forbidden
              :raw-memory :unsafe-only}
   :distributed {:managed true
                 :ownership false
                 :regions false
                 :hidden-allocation :declared
                 :raw-memory :forbidden}
   :ai {:managed true
        :ownership false
        :regions false
        :hidden-allocation :declared
        :raw-memory :forbidden}
   :gpu {:managed false
         :ownership true
         :regions true
         :hidden-allocation :forbidden
         :raw-memory :unsafe-only}
   :formal {:managed false
            :ownership true
            :regions true
            :hidden-allocation :forbidden
            :raw-memory :proof-only}})

(def profile-runtime-assumptions
  {:core {:required false :providers #{}}
   :meta {:required true :providers #{:compiler :macro-engine}}
   :hosted {:required true :providers #{:host :stdio :allocator :scheduler}}
   :native {:required false :providers #{:allocator :threading}}
   :firmware {:required false :providers #{:interrupts :device-map}}
   :kernel {:required false :providers #{:scheduler :interrupts :device-map}}
   :hardware {:required false :providers #{:clock :device-map}}
   :distributed {:required true :providers #{:workflow :replay :scheduler}}
   :ai {:required true :providers #{:model :tool :memory :human-review}}
   :gpu {:required false :providers #{:device :kernel-launch}}
   :formal {:required false :providers #{:solver :certificate-checker}}})

(def profile-unsafe-policies
  {:core :forbidden
   :meta :trusted-compiler-only
   :hosted :audited
   :native :reviewed
   :firmware :systems-audited
   :kernel :systems-audited
   :hardware :systems-audited
   :distributed :forbidden
   :ai :generated-code-audited
   :gpu :systems-audited
   :formal :proof-required})

(def profile-artifact-boundaries
  {:core #{:schema :pure-core}
   :meta #{:syntax-object :compiler-artifact}
   :hosted #{:schema :ffi :host-object :package}
   :native #{:ffi :schema :native-object}
   :firmware #{:schema :device-map :binary-image}
   :kernel #{:schema :syscall :device-map}
   :hardware #{:schema :hdl :device-map}
   :distributed #{:schema :workflow-graph :replay-log}
   :ai #{:schema :tool-manifest :model-manifest :replay-log}
   :gpu #{:schema :gpu-kernel :device-buffer}
   :formal #{:schema :proof-certificate :solver-artifact}})

(defn profile-allowed-effects
  [profile]
  (->> effect-registry
       (keep (fn [[effect entry]]
               (when (or (contains? (:profiles entry #{}) profile)
                         (and (:requires-build-grant entry)
                              (contains? #{:meta :hosted} profile)))
                 effect)))
       stable-set))

(defn profile-capabilities
  [profile]
  (->> provider-specs
       (keep (fn [[capability spec]]
               (when (contains? (:profiles spec #{}) profile)
                 capability)))
       stable-set))

(defn profile-contract
  [profile]
  (let [allowed-effects (profile-allowed-effects profile)]
    {:profile profile
     :allowed-forms core-forms
     :allowed-effects allowed-effects
     :checked-effects (stable-set (for [[effect entry] effect-registry
                                        :when (and (contains? allowed-effects effect)
                                                   (or (:requires-capability entry)
                                                       (:requires-build-grant entry)))]
                                    effect))
     :forbidden-effects (set/difference (all-registered-effects) allowed-effects)
     :capabilities (profile-capabilities profile)
     :memory (profile-memory-regimes profile)
     :runtime (profile-runtime-assumptions profile)
     :nondeterminism (if (contains? #{:distributed :ai} profile)
                       :recorded-when-effectful
                       :profile-specific)
     :unsafe-policy (profile-unsafe-policies profile)
     :artifact-boundaries (profile-artifact-boundaries profile)}))

(defn profile-policy-layer
  [module metadata-key source-key default-value]
  (or (get-in module [:metadata metadata-key])
      (source-key module)
      default-value))

(defn profile-effective-effects
  [module inferred-effects]
  (let [source-effects (:effects module)
        profile-effects (profile-allowed-effects (:profile module))
        package-effects (profile-policy-layer module :package-allowed-effects :effects #{})
        provider-effects (profile-policy-layer module :provider-effect-grants :effects #{})
        deployment-effects (profile-policy-layer module :deployment-allowed-effects :effects #{})]
    {:source source-effects
     :inferred inferred-effects
     :profile profile-effects
     :package package-effects
     :provider provider-effects
     :deployment deployment-effects
     :effective (set/intersection source-effects profile-effects package-effects
                                  provider-effects deployment-effects)}))

(defn profile-effective-capabilities
  [module required-capabilities]
  (let [source-capabilities (:capabilities module)
        profile-caps (profile-capabilities (:profile module))
        package-caps (profile-policy-layer module :package-capabilities :capabilities #{})
        provider-caps (profile-policy-layer module :provider-capability-grants :capabilities #{})
        deployment-caps (profile-policy-layer module :deployment-capabilities :capabilities #{})]
    {:source source-capabilities
     :required required-capabilities
     :profile profile-caps
     :package package-caps
     :provider provider-caps
     :deployment deployment-caps
     :effective (set/intersection source-capabilities profile-caps package-caps
                                  provider-caps deployment-caps)}))

(defn effect-permission-table
  [module inferred-effects effective]
  (let [source-effects (:source effective)
        row-effects (set/union source-effects inferred-effects)]
    (mapv (fn [effect]
            (let [entry (effect-registry-entry effect)
                  profile-allowed? (contains? (:profile effective) effect)
                  package-allowed? (contains? (:package effective) effect)
                  provider-granted? (contains? (:provider effective) effect)
                  deployment-granted? (contains? (:deployment effective) effect)
                  effective? (contains? (:effective effective) effect)]
              {:effect effect
               :family (:family entry)
               :requires-capability (boolean (:requires-capability entry))
               :capability (:capability entry)
               :declared? (contains? source-effects effect)
               :inferred? (contains? inferred-effects effect)
               :profile-allowed? profile-allowed?
               :package-allowed? package-allowed?
               :provider-granted? provider-granted?
               :deployment-granted? deployment-granted?
               :effective? effective?
               :state (cond
                        effective? :allowed
                        (not profile-allowed?) :rejected
                        (or (not package-allowed?)
                            (not provider-granted?)
                            (not deployment-granted?)) :checked
                        :else :rejected)
               :policy-layer (cond
                               (not profile-allowed?) :profile
                               (not package-allowed?) :package
                               (not provider-granted?) :provider
                               (not deployment-granted?) :deployment
                               :else :effective)}))
          (stable-vec row-effects))))

(defn capability-permission-table
  [module required-capabilities effective]
  (let [source-capabilities (:source effective)
        row-capabilities (set/union source-capabilities required-capabilities)]
    (mapv (fn [capability]
            (let [profile-allowed? (contains? (:profile effective) capability)
                  package-allowed? (contains? (:package effective) capability)
                  provider-granted? (contains? (:provider effective) capability)
                  deployment-granted? (contains? (:deployment effective) capability)
                  effective? (contains? (:effective effective) capability)]
              {:capability capability
               :provider (provider-name capability)
               :declared? (contains? source-capabilities capability)
               :required? (contains? required-capabilities capability)
               :profile-allowed? profile-allowed?
               :package-allowed? package-allowed?
               :provider-granted? provider-granted?
               :deployment-granted? deployment-granted?
               :effective? effective?
               :state (cond
                        effective? :allowed
                        (not profile-allowed?) :rejected
                        (or (not package-allowed?)
                            (not provider-granted?)
                            (not deployment-granted?)) :checked
                        :else :rejected)
               :policy-layer (cond
                               (not profile-allowed?) :profile
                               (not package-allowed?) :package
                               (not provider-granted?) :provider
                               (not deployment-granted?) :deployment
                               :else :effective)}))
          (stable-vec row-capabilities))))

(defn backend-eligibility-report
  [module manifest]
  (let [eligible? (contains? supported-targets (:target module))]
    {:profile (:profile module)
     :target (:target module)
     :backend :clojure-stage0-jvm
     :eligible? eligible?
     :required-forms (:allowed-forms (:profile-contract manifest))
     :required-effects (:effective-effects manifest)
     :required-capabilities (:effective-capabilities manifest)
     :memory-regime (:memory-regime manifest)
     :runtime-assumptions (:runtime-assumptions manifest)
     :decision (if eligible? :eligible :rejected)
     :note "backend eligibility reports target support; it does not legalize profile-rejected behavior"}))

(defn profile-conformance-fixture
  [manifest effect-table capability-table dependency-graph backend-report]
  (let [required-fields [:profile :target :source-effects :inferred-effects
                         :effective-effects :source-capabilities
                         :required-capabilities :effective-capabilities
                         :memory-regime :runtime-assumptions :unsafe-policy
                         :dependencies :provider-selections]
        missing (vec (remove #(contains? manifest %) required-fields))]
    {:document :P1
     :required-fields required-fields
     :missing-fields missing
     :diagnostic-ids p1-diagnostic-ids
     :standard-profiles standard-profile-order
     :positive-fixtures :profile-manifest-suite
     :negative-fixtures :p1-diagnostic-suite
     :effect-permission-rows (count effect-table)
     :capability-permission-rows (count capability-table)
     :dependency-graph-status (if (:acyclic dependency-graph) :complete :incomplete)
     :backend-eligibility-status (if (:eligible? backend-report) :complete :rejected)
     :manifest-status (if (empty? missing) :complete :incomplete)
     :status (if (and (empty? missing) (:eligible? backend-report))
               :complete
               :incomplete)}))

(defn p1-diagnostic-id
  [data]
  (let [id (:id data)]
    (cond
      (and (= "L3-NS-MISSING" id)
           (not= :profile (:missing data))) nil
      :else (get p1-underlying-diagnostic-map id))))

(defn throw-p1-diagnostic!
  [ex]
  (let [data (ex-data ex)]
    (if-let [id (p1-diagnostic-id data)]
      (throw (diagnostic id
                         (get p1-diagnostic-messages id (:message data))
                         (merge (dissoc data :id :message)
                                {:underlying-diagnostic (:id data)
                                 :underlying-message (:message data)
                                 :active-profile (or (:active-profile data)
                                                     (:profile data))
                                 :target (:target data)
                                 :legal-alternative (:remediation data)
                                 :diagnostic-family :profile-validation})))
      (throw ex))))

(defn profile-manifest-source-artifact
  [source-path source-text]
  (try
    (let [typed-artifact (typed-source-artifact source-path source-text)
          module-artifact (module-source-artifact source-path source-text)
          module (:module typed-artifact)
          inferred-effects (or (get-in typed-artifact [:namespace-effect-summary :inferred])
                               (get-in module-artifact [:namespace-effect-summary :inferred])
                               #{})
          required-capabilities (set (map :capability
                                          (:provider-selection-records typed-artifact)))
          effect-authority (profile-effective-effects module inferred-effects)
          capability-authority (profile-effective-capabilities module
                                                               required-capabilities)
          effect-table (effect-permission-table module inferred-effects
                                                effect-authority)
          capability-table (capability-permission-table module
                                                        required-capabilities
                                                        capability-authority)
          contract (profile-contract (:profile module))
          memory-regime (merge (:memory contract)
                               (get-in module [:metadata :memory] {}))
          runtime-assumptions (merge (:runtime contract)
                                     (get-in module [:metadata :runtime] {}))
          dependency-graph (:module-dependency-graph module-artifact)
          provider-selections (distinct-records
                               (:provider-selection-records typed-artifact))
          manifest {:module (:module module)
                    :source-path source-path
                    :profile (:profile module)
                    :target (:target module)
                    :source-effects (:source effect-authority)
                    :inferred-effects inferred-effects
                    :effective-effects (:effective effect-authority)
                    :source-capabilities (:source capability-authority)
                    :required-capabilities required-capabilities
                    :effective-capabilities (:effective capability-authority)
                    :memory-regime memory-regime
                    :runtime-assumptions runtime-assumptions
                    :unsafe-policy (:unsafe-policy contract)
                    :dependencies dependency-graph
                    :provider-selections provider-selections
                    :safety (:safety module)
                    :metadata (:metadata module)
                    :policy-layers {:effects (select-keys effect-authority
                                                          [:source :profile
                                                           :package :provider
                                                           :deployment])
                                    :capabilities (select-keys capability-authority
                                                               [:source :profile
                                                                :package :provider
                                                                :deployment])}}
          manifest-with-contract (assoc manifest :profile-contract contract)
          backend-report (backend-eligibility-report module manifest-with-contract)
          conformance (profile-conformance-fixture manifest effect-table
                                                   capability-table
                                                   dependency-graph
                                                   backend-report)]
      {:kind :gravity/stage0-profile-manifest-artifact
       :document "P1"
       :pass {:name :profile-manifest-validation
              :input :typed-effected-core
              :output :profile-manifest
              :requires [:reader :namespace-analyzer :macro-expansion
                         :core-lowering :type-effect-capability-check]
              :preserves [:source-spans :generated-origin :profile :target
                          :effects :capabilities :metadata]
              :emits [:profile-manifest :effect-permission-table
                      :capability-permission-table :memory-regime-record
                      :runtime-assumption-record :cross-profile-dependency-graph
                      :backend-eligibility-report :profile-diagnostics
                      :profile-conformance-fixture]
              :rejects p1-diagnostic-ids}
       :typed-core-artifact-hash (str "sha256:"
                                      (sha256-hex (pr-str typed-artifact)))
       :profile-contract-schema {:portable-minimum-fields
                                 [:profile :allowed-forms :allowed-effects
                                  :checked-effects :forbidden-effects
                                  :capabilities :memory :runtime
                                  :nondeterminism :unsafe-policy
                                  :artifact-boundaries]
                                 :policy-layers [:source :profile :package
                                                 :provider :deployment]
                                 :status :complete}
       :profile-contract contract
       :profile-manifest manifest
       :effect-permission-table effect-table
       :capability-permission-table capability-table
       :memory-regime-record {:profile (:profile module)
                              :memory memory-regime}
       :runtime-assumption-record {:profile (:profile module)
                                   :runtime runtime-assumptions}
       :cross-profile-dependency-graph dependency-graph
       :profile-boundary-records (:profile-boundary-records module-artifact)
       :backend-eligibility-report backend-report
       :profile-diagnostics []
       :profile-conformance-fixture conformance
       :diagnostics []})
    (catch clojure.lang.ExceptionInfo ex
      (throw-p1-diagnostic! ex))))

(def first-profile-set-order
  [:core :meta :hosted :native])

(def profile-documents-by-profile
  {:core "P2"
   :meta "P3"
   :hosted "P4"
   :native "P5"})

(def profile-set-diagnostic-ids-by-document
  {"P2" ["P2-EFFECT" "P2-CAPABILITY" "P2-RUNTIME" "P2-MEMORY"
         "P2-UNSAFE" "P2-NONDETERMINISM" "P2-MACRO" "P2-IMPORT"
         "P2-BACKEND"]
   "P3" ["P3-BUILD-EFFECT" "P3-HERMETIC" "P3-COMPILER-CAPABILITY"
         "P3-PASS-CONTRACT" "P3-FACT-INVALIDATION"
         "P3-GENERATED-PROFILE" "P3-GENERATED-SAFETY" "P3-PHASE"
         "P3-SOURCE-MAP"]
   "P4" ["P4-HOST-EFFECT" "P4-HOST-CAPABILITY" "P4-REFLECTION"
         "P4-DYNAMIC" "P4-HOST-OBJECT" "P4-EXCEPTION" "P4-RESOURCE"
         "P4-RAW-MEMORY" "P4-CROSS-IMPORT" "P4-SOURCEMAP"]
   "P5" ["P5-ALLOC" "P5-MEMORY-PROVIDER" "P5-FFI" "P5-RAW-MEMORY"
         "P5-THREAD" "P5-ATOMIC" "P5-SIMD" "P5-NUMERIC"
         "P5-OPTIMIZATION" "P5-RUNTIME"]})

(def profile-set-diagnostic-ids
  (vec (mapcat profile-set-diagnostic-ids-by-document ["P2" "P3" "P4" "P5"])))

(def profile-set-diagnostic-mapping
  {[:core "P1-EFFECT"] "P2-EFFECT"
   [:core "P1-CAPABILITY"] "P2-CAPABILITY"
   [:core "P1-RUNTIME"] "P2-RUNTIME"
   [:core "P1-MEMORY"] "P2-MEMORY"
   [:core "P1-CROSS-IMPORT"] "P2-IMPORT"
   [:core "P1-MACRO"] "P2-MACRO"
   [:core "P1-BACKEND"] "P2-BACKEND"
   [:hosted "P1-EFFECT"] "P4-HOST-EFFECT"
   [:hosted "P1-CAPABILITY"] "P4-HOST-CAPABILITY"
   [:hosted "P1-MEMORY"] "P4-RAW-MEMORY"
   [:hosted "P1-CROSS-IMPORT"] "P4-CROSS-IMPORT"
   [:native "P1-MEMORY"] "P5-RAW-MEMORY"
   [:native "P1-RUNTIME"] "P5-RUNTIME"
   [:native "P1-CAPABILITY"] "P5-MEMORY-PROVIDER"
   [:native "P1-BACKEND"] "P5-SIMD"})

(defn profile-set-diagnostic-id
  [data]
  (let [id (:id data)]
    (cond
      (contains? (set profile-set-diagnostic-ids) id) id
      :else (get profile-set-diagnostic-mapping
                 [(or (:active-profile data) (:profile data)) id]))))

(defn throw-profile-set-diagnostic!
  [ex]
  (let [data (ex-data ex)]
    (if-let [id (profile-set-diagnostic-id data)]
      (throw (diagnostic id
                         (or (:message data)
                             (str "profile-set diagnostic " id))
                         (merge (dissoc data :id :message)
                                {:underlying-diagnostic (:id data)
                                 :underlying-message (:message data)
                                 :active-profile (or (:active-profile data)
                                                     (:profile data))
                                 :target (:target data)
                                 :legal-alternative (:remediation data)
                                 :diagnostic-family :profile-set-validation})))
      (throw ex))))

(defn profile-set-conformance-fixture
  [profile document effect-capability-matrix]
  {:documents ["P2" "P3" "P4" "P5"]
   :active-document document
   :active-profile profile
   :required-profiles first-profile-set-order
   :diagnostic-ids (get profile-set-diagnostic-ids-by-document document)
   :effective-effects (get-in effect-capability-matrix [:effects :effective])
   :effective-capabilities (get-in effect-capability-matrix
                                   [:capabilities :effective])
   :matrix-status :complete
   :status :complete})

(defn profile-set-source-artifact
  [source-path source-text]
  (try
    (let [manifest-artifact (profile-manifest-source-artifact source-path source-text)
          manifest (:profile-manifest manifest-artifact)
          profile (:profile manifest)
          document (profile-documents-by-profile profile)
          _ (when-not document
              (fail! "P1-PROFILE-UNSUPPORTED"
                     "profile-set covers only :core, :meta, :hosted, and :native"
                     {:source-span {:source source-path}
                      :profile profile
                      :supported first-profile-set-order
                      :remediation "Use profile-manifest for the generic P1 artifact or a later profile-set task."}))
          matrix {:profile profile
                  :document document
                  :effects {:source (:source-effects manifest)
                            :inferred (:inferred-effects manifest)
                            :effective (:effective-effects manifest)
                            :permission-table (:effect-permission-table
                                               manifest-artifact)}
                  :capabilities {:source (:source-capabilities manifest)
                                 :required (:required-capabilities manifest)
                                 :effective (:effective-capabilities manifest)
                                 :permission-table (:capability-permission-table
                                                    manifest-artifact)}
                  :memory (:memory-regime manifest)
                  :runtime (:runtime-assumptions manifest)}
          conformance (profile-set-conformance-fixture profile document matrix)]
      {:kind :gravity/stage0-profile-set-artifact
       :document-set ["P2" "P3" "P4" "P5"]
       :pass {:name :core-meta-hosted-native-profile-validation
              :input :profile-manifest
              :output :effect-capability-matrix
              :requires [:reader :namespace-analyzer :macro-expansion
                         :core-lowering :type-effect-capability-check
                         :profile-manifest-validation]
              :preserves [:source-spans :generated-origin :profile :target
                          :effects :capabilities :memory-regime
                          :runtime-assumptions]
              :emits [:profile-manifest :effect-capability-matrix
                      :profile-specific-report :profile-set-conformance-fixture]
              :rejects profile-set-diagnostic-ids}
       :profile-manifest-artifact-hash (str "sha256:"
                                            (sha256-hex
                                             (pr-str manifest-artifact)))
       :profile-manifest manifest
       :profile-contract (:profile-contract manifest-artifact)
       :effect-capability-matrix matrix
       :profile-specific-report {:document document
                                 :profile profile
                                 :memory-regime (:memory matrix)
                                 :runtime-assumptions (:runtime matrix)
                                 :backend-eligibility
                                 (:backend-eligibility-report
                                  manifest-artifact)
                                 :diagnostic-ids
                                 (get profile-set-diagnostic-ids-by-document
                                      document)
                                 :status :complete}
       :profile-set-conformance-fixture conformance
       :diagnostics []})
    (catch clojure.lang.ExceptionInfo ex
      (throw-profile-set-diagnostic! ex))))

