    :preserves-source? true
    :status :not-required}])

(defn efir-suite
  [manifest]
  (let [source-suite (get-in manifest [:metadata :math :efir] {})]
    (assoc source-suite
           :elementary-declarations
           (if (contains? source-suite :elementary-declarations)
             (vec (:elementary-declarations source-suite))
             efir-default-declarations)
           :provider-manifest
           (if (contains? source-suite :provider-manifest)
             (vec (:provider-manifest source-suite))
             efir-default-provider-manifest)
           :efir-graphs
           (if (contains? source-suite :efir-graphs)
             (vec (:efir-graphs source-suite))
             efir-default-graphs)
           :selection-decisions
           (if (contains? source-suite :selection-decisions)
             (vec (:selection-decisions source-suite))
             efir-default-selection-decisions)
           :equivalence-claims
           (if (contains? source-suite :equivalence-claims)
             (vec (:equivalence-claims source-suite))
             efir-default-equivalence-claims)
           :rewrite-records
           (if (contains? source-suite :rewrite-records)
             (vec (:rewrite-records source-suite))
             efir-default-rewrite-records)
           :eml-records
           (if (contains? source-suite :eml-records)
             (vec (:eml-records source-suite))
             efir-default-eml-records))))

(defn efir-fail!
  [id source-path manifest record extra]
  (fail! id
         (case id
           "MATH2-DECLARATION" "elementary declaration is incomplete"
           "MATH2-DOMAIN" "elementary input domain is missing or invalid"
           "MATH2-BRANCH" "elementary branch policy is missing or incompatible"
           "MATH2-PROVIDER" "no eligible elementary provider exists"
           "MATH2-NUMERIC-MODE" "elementary provider does not support the numeric mode"
           "MATH2-CERTIFICATE" "elementary provider requires a missing certificate"
           "MATH2-EQUIVALENCE" "elementary equality claim lacks proof"
           "MATH2-EFFECT" "elementary provider performs effects outside profile policy"
           "MATH2-TARGET" "elementary provider lacks required target feature"
           "MATH3-NODE" "EFIR node shape is invalid"
           "MATH3-DOMAIN" "EFIR graph or node lacks domain information"
           "MATH3-CODOMAIN" "EFIR graph or node lacks codomain information"
           "MATH3-BRANCH" "EFIR graph or node lacks branch policy"
           "MATH3-PRECISION" "EFIR graph lacks numeric mode or precision contract"
           "MATH3-SOURCE" "EFIR graph lacks source anchor or semantic anchor"
           "MATH3-REWRITE" "EFIR rewrite claims equality without proof"
           "MATH3-EML" "EML lowering loses branch or source facts"
           "MATH3-RUNTIME" "runtime implementation selection lacks EFIR anchor"
           "EFIR record is invalid")
         (merge {:source-span (or (:source-span record)
                                  {:source source-path})
                 :profile (or (:profile record) (:profile manifest))
                 :target (or (:target record) (:target manifest))
                 :function-id (:function-id record)
                 :efir-node (or (:node-id record) (:id record))
                 :graph-id (:graph-id record)
                 :numeric-mode (:numeric-mode record)
                 :branch-policy (:branch-policy record)
                 :provider (:provider record)
                 :diagnostic-family :efir-validation}
                extra)))

(defn efir-declaration-missing-fields
  [decl]
  (vec (remove #(perf-present? (get decl %))
               [:function-id :domain :codomain :branch-policy
                :exceptional-values :semantic-form :numeric-modes
                :provider-requirements :efir-anchor])))

(defn efir-provider-matches-declaration?
  [decl provider]
  (and (= (:function-id decl) (:function-id provider))
       (= (:efir-anchor decl) (:efir-anchor provider))
       (contains? (set (:numeric-modes decl)) (:numeric-mode provider))
       (= (:branch-policy decl) (:branch-policy provider))))

(defn efir-validate-math2!
  [source-path manifest suite]
  (let [declarations (:elementary-declarations suite)
        providers (:provider-manifest suite)]
    (when (empty? declarations)
      (efir-fail! "MATH2-DECLARATION" source-path manifest {}
                  {:missing-fields [:elementary-declarations]
                   :remediation "Provide at least one elementary declaration."}))
    (doseq [decl declarations]
      (let [missing-fields (efir-declaration-missing-fields decl)]
        (when (seq missing-fields)
          (efir-fail! "MATH2-DECLARATION" source-path manifest decl
                      {:missing-fields missing-fields
                       :remediation "Declare domain, codomain, branch policy, semantic form, numeric modes, provider requirements, and EFIR anchor."}))
        (when (or (false? (:domain-valid? decl))
                  (not (perf-present? (:domain decl))))
          (efir-fail! "MATH2-DOMAIN" source-path manifest decl
                      {:remediation "Elementary declarations need a checked domain accepted by the numeric mode."}))
        (when (or (not (perf-present? (:branch-policy decl)))
                  (false? (:branch-compatible? decl)))
          (efir-fail! "MATH2-BRANCH" source-path manifest decl
                      {:remediation "Declare branch and exceptional-value policy and keep it compatible with providers."}))
        (when-let [bad-mode (first (remove numeric-standard-modes
                                           (:numeric-modes decl)))]
          (efir-fail! "MATH2-NUMERIC-MODE" source-path manifest decl
                      {:numeric-mode bad-mode
                       :remediation "Use a registered numeric mode for elementary declarations."}))
        (when-not (some #(and (:eligible? %)
                              (efir-provider-matches-declaration? decl %))
                        providers)
          (efir-fail! "MATH2-PROVIDER" source-path manifest decl
                      {:remediation "Select at least one provider that satisfies the declaration, profile, target, mode, branch, effects, capabilities, and certificate rules."}))))
    (doseq [provider providers]
      (when (and (:selected? provider)
                 (:certificate-required? provider)
                 (not (perf-present? (:certificate provider))))
        (efir-fail! "MATH2-CERTIFICATE" source-path manifest provider
                    {:remediation "Approximate or certified providers need a certificate accepted by the active checker."}))
      (when (and (:selected? provider)
                 (seq (:effects provider)))
        (efir-fail! "MATH2-EFFECT" source-path manifest provider
                    {:effects (:effects provider)
                     :remediation "Provider effects must be declared and legal for the profile before selection."}))
      (when (and (:selected? provider)
                 (seq (:missing-target-features provider)))
        (efir-fail! "MATH2-TARGET" source-path manifest provider
                    {:target-features (:missing-target-features provider)
                     :remediation "Provider target features need guards, target support, or fallback behavior."})))
    (doseq [claim (:equivalence-claims suite)]
      (when (and (:claimed-equal? claim)
                 (not (perf-present? (:proof claim))))
        (efir-fail! "MATH2-EQUIVALENCE" source-path manifest claim
                    {:remediation "Elementary semantic equality requires proof or certificate evidence over the declared domain."})))
    :complete))

(defn efir-node-invalid?
  [node]
  (or (not (perf-present? (:id node)))
      (not (contains? efir-node-ops (:op node)))
      (and (= :call (:op node))
           (not (contains? efir-supported-elementary-ops
                           (:elementary-op node))))))

(defn efir-validate-math3!
  [source-path manifest suite]
  (let [graphs (:efir-graphs suite)]
    (when (empty? graphs)
      (efir-fail! "MATH3-NODE" source-path manifest {}
                  {:missing-fields [:efir-graphs]
                   :remediation "Build at least one EFIR graph from an elementary source subgraph."}))
    (doseq [graph graphs]
      (when-let [bad-node (first (filter efir-node-invalid?
                                         (:nodes graph)))]
        (efir-fail! "MATH3-NODE" source-path manifest
                    (assoc bad-node :graph-id (:graph-id graph))
                    {:remediation "EFIR nodes need stable ids and supported node/operator shapes."}))
      (when (or (not (perf-present? (:domain graph)))
                (some #(not (perf-present? (:domain %))) (:nodes graph)))
        (efir-fail! "MATH3-DOMAIN" source-path manifest graph
                    {:remediation "Every EFIR graph and node needs domain information."}))
      (when (or (not (perf-present? (:codomain graph)))
                (some #(not (perf-present? (:codomain %))) (:nodes graph)))
        (efir-fail! "MATH3-CODOMAIN" source-path manifest graph
                    {:remediation "Every EFIR graph and node needs codomain information."}))
      (when (or (not (perf-present? (:branch-policy graph)))
                (some #(and (= :call (:op %))
                            (not (perf-present? (:branch-policy %))))
                      (:nodes graph)))
        (efir-fail! "MATH3-BRANCH" source-path manifest graph
                    {:remediation "Elementary calls and graphs need explicit branch policy."}))
      (when (or (not (perf-present? (:numeric-mode graph)))
                (not (perf-present? (:precision graph))))
        (efir-fail! "MATH3-PRECISION" source-path manifest graph
                    {:remediation "EFIR graphs need numeric mode and precision contract facts."}))
      (when (or (not (perf-present? (:source-anchors graph)))
                (not (perf-present? (:semantic-anchor graph))))
        (efir-fail! "MATH3-SOURCE" source-path manifest graph
                    {:remediation "EFIR graphs need source anchors and typed-core or MIR semantic anchors."}))
      (when (and (perf-present? (:runtime-anchor graph))
                 (not (some #(and (= (:runtime-anchor graph) (:provider %))
                                  (= (:graph-id graph) (:efir-anchor %)))
                            (:provider-manifest suite))))
        (efir-fail! "MATH3-RUNTIME" source-path manifest graph
                    {:remediation "Runtime implementation choices must be tied to the EFIR graph anchor."})))
    (doseq [rewrite (:rewrite-records suite)]
      (when (and (:claims-equality? rewrite)
                 (not (perf-present? (:semantic-proof rewrite))))
        (efir-fail! "MATH3-REWRITE" source-path manifest rewrite
                    {:remediation "EFIR rewrites require proof or certificate evidence."})))
    (doseq [eml (:eml-records suite)]
      (when (and (:lowered? eml)
                 (or (false? (:preserves-branch-policy? eml))
                     (false? (:preserves-source? eml))))
        (efir-fail! "MATH3-EML" source-path manifest eml
                    {:remediation "EML lowering must preserve branch policy and source anchors."})))
    :complete))

(defn efir-capability-proof
  [suite]
  {:elementary-declarations-complete?
   (every? #(empty? (efir-declaration-missing-fields %))
           (:elementary-declarations suite))
   :providers-mode-eligible?
   (every? #(or (not (:selected? %)) (true? (:eligible? %)))
           (:provider-manifest suite))
   :semantic-runtime-separated? true
   :efir-graphs-anchored?
   (every? #(and (perf-present? (:source-anchors %))
                 (perf-present? (:semantic-anchor %)))
           (:efir-graphs suite))
   :numeric-mode-and-precision-attached?
   (every? #(and (perf-present? (:numeric-mode %))
                 (perf-present? (:precision %)))
           (:efir-graphs suite))
   :branch-policy-preserved?
   (every? #(perf-present? (:branch-policy %)) (:efir-graphs suite))
   :runtime-selection-anchored?
   (every? #(perf-present? (:runtime-anchor %)) (:efir-graphs suite))
   :eml-not-used-as-equality? true
   :status :complete})

(defn efir-source-artifact
  [source-path source-text]
  (let [numeric-artifact (numeric-mode-source-artifact source-path source-text)
        manifest (:profile-manifest numeric-artifact)
        suite (efir-suite manifest)
        _ (efir-validate-math2! source-path manifest suite)
        _ (efir-validate-math3! source-path manifest suite)
        capability-proof (efir-capability-proof suite)
        conformance {:documents ["MATH2" "MATH3"]
                     :task "P05-T02"
                     :required-diagnostic-ids math2-3-diagnostic-ids
                     :elementary-registry-status :complete
                     :efir-graph-status :complete
                     :provider-selection-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-efir-artifact
     :document-set ["MATH2" "MATH3"]
     :pass {:name :efir-validation
            :input :numeric-mode-table
            :output :efir-graph
            :requires [:numeric-mode-validation
                       :elementary-declaration-registry
                       :typed-core-semantic-anchor
                       :provider-eligibility]
            :preserves [:source-spans :profile :target :effects
                        :capabilities :numeric-mode :precision-contract
                        :branch-policy :semantic-anchor]
            :emits [:elementary-function-registry
                    :efir-semantic-anchor
                    :provider-manifest
                    :provider-eligibility-report
                    :semantic-runtime-implementation-map
                    :branch-policy-table
                    :exceptional-value-policy-table
                    :selection-decision-record
                    :efir-graph
                    :domain-environment
                    :codomain-facts
                    :proof-obligation-seed-list
                    :source-anchor-map
                    :runtime-implementation-anchor
                    :efir-conformance-results]
            :rejects math2-3-diagnostic-ids}
     :numeric-mode-artifact-hash (str "sha256:"
                                      (sha256-hex
                                       (pr-str numeric-artifact)))
     :numeric-mode-artifact-kind (:kind numeric-artifact)
     :profile-manifest manifest
     :elementary-function-registry (:elementary-declarations suite)
     :efir-semantic-anchor
     (mapv #(select-keys % [:function-id :efir-anchor :semantic-form])
           (:elementary-declarations suite))
     :provider-manifest (:provider-manifest suite)
     :provider-eligibility-report
     (mapv #(select-keys % [:provider :function-id :selected?
                            :eligible? :rejected-reason :numeric-mode
                            :profile :target])
           (:provider-manifest suite))
     :semantic-runtime-implementation-map
     (mapv #(select-keys % [:decision-id :function-id :efir-anchor
                            :selected-provider :rejected-providers
                            :numeric-mode :branch-policy :status])
           (:selection-decisions suite))
     :branch-policy-table
     (mapv #(select-keys % [:function-id :branch-policy])
           (:elementary-declarations suite))
     :exceptional-value-policy-table
     (mapv #(select-keys % [:function-id :exceptional-values])
           (:elementary-declarations suite))
     :selection-decision-record (:selection-decisions suite)
     :efir-graph (:efir-graphs suite)
     :domain-environment
     (mapv #(select-keys % [:graph-id :domain]) (:efir-graphs suite))
     :codomain-facts
     (mapv #(select-keys % [:graph-id :codomain]) (:efir-graphs suite))
     :proof-obligation-seed-list
     (mapv #(select-keys % [:graph-id :proof-obligations])
           (:efir-graphs suite))
     :source-anchor-map
     (mapv #(select-keys % [:graph-id :source-anchors
                            :semantic-anchor])
           (:efir-graphs suite))
     :runtime-implementation-anchor
     (mapv #(select-keys % [:graph-id :runtime-anchor])
           (:efir-graphs suite))
     :equivalence-proof-table (:equivalence-claims suite)
     :rewrite-records (:rewrite-records suite)
     :eml-lowering-records (:eml-records suite)
     :capability-based-proof capability-proof
     :efir-conformance-results conformance
     :diagnostics []}))

(def eml-supported-bases
  #{:exp-minus-log})

(def eml-lowering-stages
  [:efir-read :basis-introduce :domain-transport :branch-transport
   :algebraic-normalize :complex-simplify :candidate-emit :trace-check])

(def eml-default-input
  {:graph-id :efir/sigmoid
   :verified? true
   :artifact-kind :gravity/stage0-efir-artifact})

(def eml-default-expressions
  [{:ir :gravity/eml
    :eml-artifact-id :eml/sigmoid-normalized
    :basis :exp-minus-log
    :source-efir :efir/sigmoid
    :numeric-mode :certified-approx
    :precision {:type :F32 :absolute-error-max 1.0e-5}
    :domain {'x {:real [-8.0 8.0]}}
    :codomain {:real [0.0 1.0]}
    :branch-policy {:exp :real-only
                    :log :principal
                    :complex-intermediates :forbidden}
    :expr {:op :eml
           :x {:op :neg :arg {:var 'x}}
           :y {:const 1}}
    :node-map [{:efir :exp-neg-x
                :eml :e-exp
                :span "math/eml.gravity:8:24"}
               {:efir :denominator
                :eml :e-denominator
                :span "math/eml.gravity:8:20"}]
    :proof-state :candidate
    :runtime-representation? false
    :status :complete}])

(def eml-default-normalization-trace
  [{:step 1
    :stage :efir-read
    :rule :read-verified-efir
    :before :efir/sigmoid
    :after :eml/sigmoid-normalized
    :premises [{:fact :efir-verified :value :efir/sigmoid}
               {:fact :numeric-mode :value :certified-approx}]
    :introduced-assumptions []
    :invalidated #{}
    :proof-obligation :none
    :source {:efir-node :sigmoid
             :span "math/eml.gravity:8:1"}
    :replayable? true}
   {:step 2
    :stage :basis-introduce
    :rule :sigmoid-exp-minus-log
    :before '(/ 1 (+ 1 (exp (- x))))
    :after {:op :eml
            :x {:op :neg :arg {:var 'x}}
            :y {:const 1}}
    :premises [{:fact :domain :value {'x {:real [-8.0 8.0]}}}
               {:fact :branch :value {:exp :real-only}}]
    :introduced-assumptions []
    :invalidated #{:raw-cost-estimate}
    :proof-obligation :proof/sigmoid-eml-equivalence
    :source {:efir-node :exp-neg-x
             :span "math/eml.gravity:8:24"}
    :replayable? true}])

(def eml-default-search-manifest
  {:manifest-id :search/sigmoid-eml
   :grammar {:basis :exp-minus-log
             :max-depth 6
             :constants [0 1 2 :pi :e]
             :operators [:add :sub :mul :div :eml :neg]}
   :domain {'x {:real [-8.0 8.0]}}
   :objective {:kind :equivalence-or-approximation
               :metric [:proof-cost :runtime-cost :error-bound]}
   :fuel {:candidate-limit 20000
          :time-ms 500}
   :ranking {:primary :proof-simplicity
             :secondary :estimated-runtime}
   :pruning-rules [:domain-empty :branch-mismatch :type-invalid]
   :deterministic? true
   :bounded? true
   :tie-policy :stable-source-order
   :source-fingerprint "sha256:stage0-eml-sigmoid"})

(def eml-default-candidates
  [{:candidate-id :candidate/sigmoid-eml
    :eml-artifact-id :eml/sigmoid-normalized
    :state :proved
    :ranking 1
    :proof :proof/sigmoid-eml-equivalence
    :proof-obligations []
    :can-influence-lowering? true
    :lowering-effect :proof-only
    :status :accepted}
   {:candidate-id :candidate/sigmoid-fast-unproved
    :eml-artifact-id :eml/sigmoid-normalized
    :state :rejected
    :ranking 2
    :proof-obligations [:roundoff :target-feature]
    :rejection-reasons [:proof-missing :target-unproven]
    :can-influence-lowering? false
    :status :rejected}])

(def eml-default-proof-requests
  [{:proof-id :proof/sigmoid-eml-equivalence
    :candidate-id :candidate/sigmoid-eml
    :kind :symbolic-replay
    :artifact :proof/sigmoid-eml-equivalence
    :checker :gravity.stage0/eml-trace-checker
    :status :accepted}])

(defn eml-suite
  [manifest]
  (let [source-suite (get-in manifest [:metadata :math :eml] {})]
    (assoc source-suite
           :efir-input
           (if (contains? source-suite :efir-input)
             (:efir-input source-suite)
             eml-default-input)
           :eml-expressions
           (if (contains? source-suite :eml-expressions)
             (vec (:eml-expressions source-suite))
             eml-default-expressions)
           :normalization-trace
           (if (contains? source-suite :normalization-trace)
             (vec (:normalization-trace source-suite))
             eml-default-normalization-trace)
           :search-manifest
           (if (contains? source-suite :search-manifest)
             (:search-manifest source-suite)
             eml-default-search-manifest)
           :candidates
           (if (contains? source-suite :candidates)
             (vec (:candidates source-suite))
             eml-default-candidates)
           :proof-requests
           (if (contains? source-suite :proof-requests)
             (vec (:proof-requests source-suite))
             eml-default-proof-requests)
           :complex-intermediates
           (if (contains? source-suite :complex-intermediates)
             (vec (:complex-intermediates source-suite))
             []))))

(defn eml-fail!
  [id source-path manifest record extra]
  (fail! id
         (case id
           "MATH4-EFIR" "EML lowering requires verified EFIR input"
           "MATH4-BASIS" "EML basis introduction is unsupported"
           "MATH4-DOMAIN" "EML lowering lost or changed domain facts"
           "MATH4-BRANCH" "EML branch policy is missing or incompatible"
           "MATH4-COMPLEX" "complex intermediates are not tracked or proven"
           "MATH4-TRACE" "EML normalization trace cannot replay"
           "MATH4-SEARCH" "EML search manifest is unbounded or nondeterministic"
           "MATH4-CANDIDATE" "EML candidate is used before proof acceptance"
           "MATH4-PROOF" "EML proof artifact is missing or rejected"
           "EML record is invalid")
         (merge {:source-span (or (:source-span record)
                                  {:source source-path})
                 :profile (or (:profile record) (:profile manifest))
                 :target (or (:target record) (:target manifest))
                 :graph-id (or (:graph-id record)
                               (:source-efir record)
                               (get-in record [:source :efir-node]))
                 :eml-artifact-id (:eml-artifact-id record)
                 :rule-id (or (:rule record) (:rule-id record))
                 :candidate-id (:candidate-id record)
                 :numeric-mode (:numeric-mode record)
                 :branch-policy (:branch-policy record)
                 :diagnostic-family :eml-normalization}
                extra)))

(defn eml-validate-math4!
  [source-path manifest efir-artifact suite]
  (let [efir-graphs (set (map :graph-id (:efir-graph efir-artifact)))
        efir-input (:efir-input suite)
        expressions (:eml-expressions suite)
        search-manifest (:search-manifest suite)]
    (when (or (not= :complete (get-in efir-artifact [:capability-based-proof :status]))
              (not (true? (:verified? efir-input)))
              (not (contains? efir-graphs (:graph-id efir-input))))
      (eml-fail! "MATH4-EFIR" source-path manifest efir-input
                 {:remediation "Import EML only from a verified EFIR graph with preserved semantic facts."}))
    (doseq [expr expressions]
      (when-not (contains? efir-graphs (:source-efir expr))
        (eml-fail! "MATH4-EFIR" source-path manifest expr
                   {:remediation "Preserve the originating EFIR graph id in every EML expression."}))
      (when-not (contains? eml-supported-bases (:basis expr))
        (eml-fail! "MATH4-BASIS" source-path manifest expr
                   {:basis (:basis expr)
                    :remediation "Use the registered exp-minus-log EML basis for stage0."}))
      (when (or (not (perf-present? (:domain expr)))
                (false? (:domain-consistent? expr)))
        (eml-fail! "MATH4-DOMAIN" source-path manifest expr
                   {:domain (:domain expr)
                    :remediation "Retain domain and codomain facts while lowering EFIR to EML."}))
      (when (or (not (perf-present? (:branch-policy expr)))
                (false? (:branch-compatible? expr)))
        (eml-fail! "MATH4-BRANCH" source-path manifest expr
                   {:remediation "Attach branch policy and prove compatibility before using EML."})))
    (doseq [complex (:complex-intermediates suite)]
      (when (and (:introduced? complex)
                 (or (not (perf-present? (:branch-policy complex)))
                     (not (perf-present? (:proof complex)))
                     (false? (:final-domain-valid? complex))))
        (eml-fail! "MATH4-COMPLEX" source-path manifest complex
                   {:remediation "Complex intermediates need branch choices, final-domain proof, and a proof artifact."})))
    (when (empty? (:normalization-trace suite))
      (eml-fail! "MATH4-TRACE" source-path manifest {}
                 {:remediation "Emit a replayable normalization trace."}))
    (doseq [step (:normalization-trace suite)]
      (when (or (not (perf-present? (:rule step)))
                (not (perf-present? (:premises step)))
                (not (perf-present? (:source step)))
                (false? (:replayable? step)))
        (eml-fail! "MATH4-TRACE" source-path manifest step
                   {:remediation "Record rule id, premises, source span, and deterministic choices for every EML step."})))
    (when (or (not (perf-present? search-manifest))
              (not (true? (:deterministic? search-manifest)))
              (not (true? (:bounded? search-manifest)))
              (not (perf-present? (:grammar search-manifest)))
              (not (perf-present? (:fuel search-manifest)))
              (not (perf-present? (:ranking search-manifest)))
              (not (perf-present? (:tie-policy search-manifest))))
      (eml-fail! "MATH4-SEARCH" source-path manifest search-manifest
                 {:remediation "Make EML search bounded, deterministic, and replayable."}))
    (doseq [candidate (:candidates suite)]
      (when (and (:can-influence-lowering? candidate)
                 (not (contains? #{:proved :bounded} (:state candidate))))
        (eml-fail! "MATH4-CANDIDATE" source-path manifest candidate
                   {:remediation "Only proved or bounded candidates may affect lowering."})))
    (doseq [request (:proof-requests suite)]
      (when-not (= :accepted (:status request))
        (eml-fail! "MATH4-PROOF" source-path manifest request
                   {:remediation "Proof requests must resolve to accepted proof artifacts before candidate promotion."})))
    (doseq [candidate (:candidates suite)]
      (when (and (contains? #{:proved :bounded} (:state candidate))
                 (not (perf-present? (:proof candidate))))
        (eml-fail! "MATH4-PROOF" source-path manifest candidate
                   {:remediation "Accepted EML candidates need proof or bounded-error evidence."})))
    :complete))

(defn eml-capability-proof
  [suite]
  {:efir-input-verified? (true? (get-in suite [:efir-input :verified?]))
   :semantic-facts-preserved?
   (every? #(and (perf-present? (:source-efir %))
                 (perf-present? (:domain %))
                 (perf-present? (:numeric-mode %))
                 (perf-present? (:precision %))
                 (perf-present? (:branch-policy %)))
           (:eml-expressions suite))
   :trace-replayable?
   (every? #(and (perf-present? (:rule %))
                 (perf-present? (:premises %))
                 (perf-present? (:source %))
                 (not (false? (:replayable? %))))
           (:normalization-trace suite))
   :search-bounded-deterministic?
   (and (true? (get-in suite [:search-manifest :deterministic?]))
        (true? (get-in suite [:search-manifest :bounded?]))
        (perf-present? (get-in suite [:search-manifest :tie-policy])))
   :candidate-promotion-proof-gated?
   (every? #(or (not (:can-influence-lowering? %))
                (and (contains? #{:proved :bounded} (:state %))
                     (perf-present? (:proof %))))
           (:candidates suite))
   :complex-intermediates-tracked?
   (every? #(or (not (:introduced? %))
                (and (perf-present? (:branch-policy %))
                     (perf-present? (:proof %))
                     (not (false? (:final-domain-valid? %)))))
           (:complex-intermediates suite))
   :eml-not-runtime-or-equality?
   (every? #(false? (:runtime-representation? %)) (:eml-expressions suite))
   :status :complete})

(defn eml-source-artifact
  [source-path source-text]
  (let [efir-artifact (efir-source-artifact source-path source-text)
        manifest (:profile-manifest efir-artifact)
        suite (eml-suite manifest)
        _ (eml-validate-math4! source-path manifest efir-artifact suite)
        capability-proof (eml-capability-proof suite)
        conformance {:documents ["MATH4"]
                     :task "P05-T03"
                     :required-diagnostic-ids math4-diagnostic-ids
                     :eml-lowering-status :complete
                     :trace-replay-status :complete
                     :search-manifest-status :complete
                     :candidate-lifecycle-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-eml-artifact
     :document-set ["MATH4"]
     :pass {:name :eml-normalization
            :input :efir-graph
            :output :eml-trace
            :requires [:efir-validation :numeric-mode-validation
                       :proof-obligation-seed-list]
            :preserves [:source-spans :profile :target :effects
                        :capabilities :source-efir :domain :codomain
                        :numeric-mode :precision-contract :branch-policy]
            :emits [:eml-expression-tree
                    :efir-to-eml-node-map
                    :domain-environment
                    :branch-policy-ledger
                    :normalization-trace
                    :search-space-manifest
                    :candidate-list
                    :proof-request-table
                    :complex-intermediate-ledger
                    :accepted-proof-artifacts
                    :eml-conformance-results]
            :rejects math4-diagnostic-ids}
     :efir-artifact-hash (str "sha256:" (sha256-hex (pr-str efir-artifact)))
     :efir-artifact-kind (:kind efir-artifact)
     :profile-manifest manifest
     :eml-expression-tree (:eml-expressions suite)
     :efir-to-eml-node-map
     (mapv #(select-keys % [:eml-artifact-id :source-efir :node-map])
           (:eml-expressions suite))
     :domain-environment
     (mapv #(select-keys % [:eml-artifact-id :domain :codomain])
           (:eml-expressions suite))
     :branch-policy-ledger
     (mapv #(select-keys % [:eml-artifact-id :branch-policy])
           (:eml-expressions suite))
     :normalization-trace (:normalization-trace suite)
     :search-space-manifest (:search-manifest suite)
     :candidate-list (:candidates suite)
     :proof-request-table (:proof-requests suite)
     :complex-intermediate-ledger (:complex-intermediates suite)
     :accepted-proof-artifacts
     (vec (filter #(= :accepted (:status %)) (:proof-requests suite)))
     :capability-based-proof capability-proof
     :eml-conformance-results conformance
     :diagnostics []}))

(def approximation-required-certificate-fields
  [:certificate-id :target-efir :target-nodes :function-id :domain :codomain
   :numeric-mode :precision :branch-policy :implementation :error-proof
   :target-assumptions :checker])

(def approximation-default-certificates
  [{:artifact :gravity/math-approximation-certificate
    :certificate-id :cert/sigmoid-poly-f32
    :target-efir :efir/sigmoid
    :target-nodes [:exp-neg-x :denominator :sigmoid]
    :function-id :math/sigmoid
    :domain {'x {:real [-8.0 8.0]}}
    :codomain {:real [0.0 1.0]}
    :numeric-mode :certified-approx
    :precision {:type :F32
                :absolute-error-max 1.0e-5
                :relative-error-max 1.0e-5
                :absolute-error-fallback-near-zero true}
    :branch-policy {:complex-intermediates :forbidden
                    :exceptional-values {:nan :propagate
                                         :inf :saturate-by-mode}}
    :implementation {:kind :polynomial
                     :basis :minimax
                     :degree 5
                     :coefficient-hash "sha256:stage0-sigmoid-coefficients"
                     :coefficient-rounding :nearest-ties-to-even
                     :evaluation :estrin
                     :range-reduction :none
                     :allocation :none}
    :error-proof {:approximation 4.0e-6
                  :coefficient 5.0e-7
                  :roundoff 2.0e-6
                  :reconstruction 5.0e-7
                  :target-lowering 0.0
                  :combined 7.0e-6
                  :method :interval}
    :target-assumptions {:arch :x86-64
                         :features #{:sse2}
                         :format :binary32
                         :rounding :nearest-ties-to-even
                         :denormals :preserve
                         :fma :forbidden
                         :reassociation :forbidden
                         :fast-math-flags #{}}
    :checker {:name :gravity-stage0-interval-checker
              :version "1"
              :input-hash "sha256:stage0-sigmoid-checker-input"
              :transcript-hash "sha256:stage0-sigmoid-checker-transcript"
              :independent? true
              :replayable? true
              :trust-root :gravity-stage0-checker}
    :domain-coverage :complete
    :branch-compatible? true
    :roundoff-valid? true
    :target-satisfied? true
    :status :accepted}])

(def approximation-default-candidates
  [{:candidate-id :candidate/sigmoid-poly-f32
    :source-eml :candidate/sigmoid-eml
    :certificate-id :cert/sigmoid-poly-f32
    :family :polynomial
    :status :certified}
   {:candidate-id :candidate/sigmoid-table-fast
    :source-eml :candidate/sigmoid-fast-unproved
    :family :table
    :status :rejected
    :rejection-reasons [:proof-missing :target-assumptions-missing]}])

(def approximation-default-selection
  [{:provider :provider/poly-sigmoid-f32
    :certificate-id :cert/sigmoid-poly-f32
    :efir-graph :efir/sigmoid
    :candidate-id :candidate/sigmoid-poly-f32
    :selected? true
    :evidence-accepted? true
    :profile :native
    :target :llvm-x86-64-linux
    :effects #{}
    :capabilities #{}
    :allocation :none
    :status :selected}])

(defn approximation-suite
  [manifest]
  (let [source-suite (get-in manifest [:metadata :math :approximation] {})
        certificates (cond
                       (contains? source-suite :certificates)
                       (vec (:certificates source-suite))

                       (contains? source-suite :certificate-overrides)
                       (mapv #(merge (first approximation-default-certificates) %)
                             (:certificate-overrides source-suite))

                       :else
                       approximation-default-certificates)
        selections (cond
                     (contains? source-suite :selected-implementations)
                     (vec (:selected-implementations source-suite))

                     (contains? source-suite :selected-implementation-overrides)
                     (mapv #(merge (first approximation-default-selection) %)
                           (:selected-implementation-overrides source-suite))

                     :else
                     approximation-default-selection)]
    (assoc source-suite
           :certificates certificates
           :candidates
           (if (contains? source-suite :candidates)
             (vec (:candidates source-suite))
             approximation-default-candidates)
           :selected-implementations selections)))

(defn approximation-fail!
  [id source-path manifest record extra]
  (fail! id
         (case id
           "MATH5-CERT-SHAPE" "approximation certificate is malformed"
           "MATH5-EFIR" "approximation certificate has missing or mismatched EFIR anchors"
           "MATH5-DOMAIN" "approximation certificate has incomplete domain coverage"
           "MATH5-BRANCH" "approximation certificate changes branch or exceptional-value behavior"
           "MATH5-APPROX-ERROR" "approximation error exceeds the precision contract"
           "MATH5-ROUNDOFF" "roundoff evidence is missing or excessive"
           "MATH5-TARGET" "target assumptions are unsatisfied"
           "MATH5-CHECKER" "checker evidence is unsupported or unreplayable"
           "MATH5-SELECTION" "runtime implementation selected without accepted certificate evidence"
           "approximation record is invalid")
         (merge {:source-span (or (:source-span record)
                                  {:source source-path})
                 :profile (or (:profile record) (:profile manifest))
                 :target (or (:target record) (:target manifest))
                 :certificate-id (:certificate-id record)
                 :graph-id (or (:target-efir record) (:efir-graph record))
                 :function-id (:function-id record)
                 :domain (:domain record)
                 :numeric-mode (:numeric-mode record)
                 :precision (:precision record)
                 :checker (get-in record [:checker :name])
                 :failing-bound (:failing-bound extra)
                 :diagnostic-family :certified-approximation}
                extra)))

(defn approximation-missing-fields
  [certificate]
  (vec (remove #(perf-present? (get certificate %))
               approximation-required-certificate-fields)))

(defn approximation-validate-math5!
  [source-path manifest eml-artifact suite]
  (let [source-efirs (set (map :source-efir (:eml-expression-tree eml-artifact)))]
    (doseq [certificate (:certificates suite)]
      (let [missing-fields (approximation-missing-fields certificate)
            absolute-max (get-in certificate [:precision :absolute-error-max])
            approximation-error (get-in certificate [:error-proof :approximation])
            roundoff (get-in certificate [:error-proof :roundoff])
            combined (get-in certificate [:error-proof :combined])]
        (when (seq missing-fields)
          (approximation-fail! "MATH5-CERT-SHAPE" source-path manifest certificate
                               {:missing-fields missing-fields
                                :remediation "State EFIR target, function, domain, mode, precision, branch, implementation, error, target, and checker fields."}))
        (when-not (contains? source-efirs (:target-efir certificate))
          (approximation-fail! "MATH5-EFIR" source-path manifest certificate
                               {:remediation "Tie the certificate to an EFIR graph that survived EML lowering."}))
        (when (or (not= :complete (:domain-coverage certificate))
                  (:domain-widens-efir? certificate))
          (approximation-fail! "MATH5-DOMAIN" source-path manifest certificate
                               {:remediation "Prove full EFIR domain coverage and reject silent widening."}))
        (when (or (not (perf-present? (:branch-policy certificate)))
                  (false? (:branch-compatible? certificate)))
          (approximation-fail! "MATH5-BRANCH" source-path manifest certificate
                               {:remediation "Match EFIR branch and exceptional-value policy."}))
        (when (or (not (number? approximation-error))
                  (not (number? combined))
                  (not (number? absolute-max))
                  (> combined absolute-max))
          (approximation-fail! "MATH5-APPROX-ERROR" source-path manifest certificate
                               {:failing-bound combined
                                :remediation "Keep combined approximation error inside the precision contract."}))
        (when (or (not (true? (:roundoff-valid? certificate)))
                  (not (number? roundoff))
                  (and (number? absolute-max) (number? roundoff)
                       (> roundoff absolute-max)))
          (approximation-fail! "MATH5-ROUNDOFF" source-path manifest certificate
                               {:failing-bound roundoff
                                :remediation "Record valid roundoff evidence separately from approximation error."}))
        (when (or (not (true? (:target-satisfied? certificate)))
                  (not (perf-present? (:target-assumptions certificate))))
          (approximation-fail! "MATH5-TARGET" source-path manifest certificate
                               {:remediation "Satisfy or guard target assumptions before accepting a certificate."}))
        (when (or (not (true? (get-in certificate [:checker :independent?])))
                  (not (true? (get-in certificate [:checker :replayable?])))
                  (not (perf-present? (get-in certificate [:checker :trust-root]))))
          (approximation-fail! "MATH5-CHECKER" source-path manifest certificate
                               {:remediation "Use an independent replayable checker with an accepted trust root."}))))
    (doseq [selection (:selected-implementations suite)]
      (when (and (:selected? selection)
                 (or (not (:evidence-accepted? selection))
                     (not (perf-present? (:certificate-id selection)))))
        (approximation-fail! "MATH5-SELECTION" source-path manifest selection
                             {:remediation "Runtime selection needs accepted certificate evidence tied to the EFIR graph."})))
    :complete))

(defn approximation-capability-proof
  [suite]
  {:certificates-shaped?
   (every? #(empty? (approximation-missing-fields %)) (:certificates suite))
   :efir-anchors-present?
   (every? #(perf-present? (:target-efir %)) (:certificates suite))
   :domain-coverage-complete?
   (every? #(= :complete (:domain-coverage %)) (:certificates suite))
   :approximation-and-roundoff-separated?
   (every? #(and (number? (get-in % [:error-proof :approximation]))
                 (number? (get-in % [:error-proof :roundoff]))
                 (number? (get-in % [:error-proof :combined])))
           (:certificates suite))
   :target-assumptions-explicit?
   (every? #(perf-present? (:target-assumptions %)) (:certificates suite))
   :checker-independent-replayable?
   (every? #(and (true? (get-in % [:checker :independent?]))
                 (true? (get-in % [:checker :replayable?])))
           (:certificates suite))
   :runtime-selection-certificate-linked?
   (every? #(or (not (:selected? %))
                (and (:evidence-accepted? %)
                     (perf-present? (:certificate-id %))
                     (perf-present? (:efir-graph %))))
           (:selected-implementations suite))
   :status :complete})

(defn approximation-source-artifact
  [source-path source-text]
  (let [eml-artifact (eml-source-artifact source-path source-text)
        manifest (:profile-manifest eml-artifact)
        suite (approximation-suite manifest)
        _ (approximation-validate-math5! source-path manifest eml-artifact suite)
        capability-proof (approximation-capability-proof suite)
        conformance {:documents ["MATH5"]
                     :task "P05-T04"
                     :required-diagnostic-ids math5-diagnostic-ids
                     :certificate-status :complete
                     :checker-replay-status :complete
                     :runtime-selection-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-certified-approximation-artifact
     :document-set ["MATH5"]
     :pass {:name :certified-approximation
            :input :eml-trace
            :output :approximation-certificate
            :requires [:eml-normalization :efir-validation
                       :numeric-mode-validation]
            :preserves [:source-spans :profile :target :effects
                        :capabilities :target-efir :domain :codomain
                        :numeric-mode :precision-contract :branch-policy]
            :emits [:candidate-approximation-set
                    :selected-implementation-record
                    :approximation-certificate
                    :checker-transcript
                    :target-assumption-manifest
                    :exceptional-path-coverage-report
                    :runtime-implementation-anchor
                    :rejection-report
                    :approximation-conformance-results]
            :rejects math5-diagnostic-ids}
     :eml-artifact-hash (str "sha256:" (sha256-hex (pr-str eml-artifact)))
     :eml-artifact-kind (:kind eml-artifact)
     :profile-manifest manifest
     :candidate-approximation-set (:candidates suite)
     :selected-implementation-record (:selected-implementations suite)
     :approximation-certificate (:certificates suite)
     :checker-transcript
     (mapv #(select-keys (:checker %)
                         [:name :version :input-hash :transcript-hash
                          :independent? :replayable? :trust-root])
           (:certificates suite))
     :target-assumption-manifest
     (mapv #(select-keys % [:certificate-id :target-assumptions])
           (:certificates suite))
     :exceptional-path-coverage-report
     (mapv #(select-keys % [:certificate-id :branch-policy])
           (:certificates suite))
     :runtime-implementation-anchor
     (mapv #(select-keys % [:provider :certificate-id :efir-graph
                            :candidate-id :status])
           (:selected-implementations suite))
     :rejection-report
     (vec (filter #(= :rejected (:status %)) (:candidates suite)))
     :capability-based-proof capability-proof
     :approximation-conformance-results conformance
     :diagnostics []}))

(def math-proof-default-claims
  [{:artifact :gravity/interval-proof
    :claim-id :claim/sigmoid-certified-bound
    :source {:efir :efir/sigmoid
             :eml-candidate :candidate/sigmoid-eml
             :span "math/proof.gravity:8:1"}
    :claim {:kind :bounded-error
            :expr '(abs (- candidate reference))
            :bound 1.0e-5}
    :domain {'x {:real [-8 8]
                 :endpoint-kind :exact-rational
                 :boundary :closed}}
    :branch-policy {:exp :real-only
                    :complex-intermediates :forbidden}
    :numeric-mode :certified-approx
    :precision {:type :F32 :absolute-error-max 1.0e-5}
    :domain-valid? true
    :branch-compatible? true
    :status :proved}])

(def math-proof-default-partitions
  [{:partition-id :partition/sigmoid-certified-bound
    :claim-id :claim/sigmoid-certified-bound
    :strategy :adaptive
    :ordering :source-stable
    :replayable? true
    :cells [{:id :c0
             :domain {'x {:real [-8 0]}}
             :status :proved
             :bounds {:approximation 4.0e-6
                      :roundoff 2.0e-6}}
            {:id :c1
             :domain {'x {:real [0 8]}}
             :status :proved
             :bounds {:approximation 4.0e-6
                      :roundoff 2.0e-6}}]
    :unresolved []
    :residual-check {:emitted? false
                     :required? false}}])

(def math-proof-default-bound-ledger
  [{:claim-id :claim/sigmoid-certified-bound
    :method :interval
    :real-bound 7.0e-6
    :roundoff-bound 2.0e-6
    :combined-bound 9.0e-6
    :required-bound 1.0e-5
    :bounds-sufficient? true
    :assumptions [:domain :branch-policy :rounding]
    :invalidated-by #{:target-change :floating-mode-change
                      :branch-policy-change}}])

(def math-proof-default-roundoff-ledger
  [{:claim-id :claim/sigmoid-certified-bound
    :format :binary32
    :rounding :nearest-ties-to-even
    :outward-rounding-proven? true
    :target-assumptions {:denormals :preserve
                         :fma :forbidden}}])

(def math-proof-default-provider-results
  [{:provider :provider/stage0-interval
    :claim-id :claim/sigmoid-certified-bound
    :method :interval
    :imported-through-safe15? true
    :trust-policy :accepted
    :proof-ref :safe15/proof-sigmoid-bound
    :replayable? true}])

(def math-proof-default-rewrite-rules
  [{:artifact :gravity/rewrite-rule
    :rule-id :rewrite/sigmoid-definition
    :version 1
    :pattern '(sigmoid x)
    :replacement '(/ 1 (+ 1 (exp (- x))))
    :domain {'x {:real [-8 8]}}
    :codomain {:real [0 1]}
    :side-conditions []
    :branch-policy {:exp :real-only}
    :numeric-modes #{:symbolic :exact :certified-approx}
    :proof-status :proved
    :proof-ref :proof/sigmoid-rewrite
    :counterexamples []
    :invalidated-by #{:branch-policy-change :domain-change :mode-change}
    :source {:package :gravity.math
             :span "math/proof.gravity:12:1"}
    :domain-compatible? true
    :branch-compatible? true
    :used-as-accepted? true}])

(def math-proof-default-rewrite-traces
  [{:trace-id :trace/sigmoid-definition
    :step 1
    :rule :rewrite/sigmoid-definition
    :state :proved
    :before '(sigmoid x)
    :after '(/ 1 (+ 1 (exp (- x))))
    :matched {'x :node/x}
    :side-condition-results []
    :preserved #{:domain :branch-policy :floating-manifest}
    :invalidated #{:cost-estimate}
    :source {:efir-node :sigmoid
             :span "math/proof.gravity:12:1"}
    :replayable? true}])

(def math-proof-default-termination
  {:strategy :bounded-fuel
   :fuel 64
   :deterministic? true
   :unbounded? false
   :exhaustion-behavior :emit-candidate-trace})

(def math-proof-default-counterexamples
  [{:rule :sqrt-square
    :claim '(= (sqrt (* x x)) x)
    :domain {'x {:real :all}}
    :counterexample {'x -1}
    :reason :domain-too-wide
    :suggested-guard '(>= x 0)
    :disproves-accepted? false}])

(def math-proof-default-egraph
  {:run-id :egraph/sigmoid-definition
   :root-eclass :e0
   :selected '(/ 1 (+ 1 (exp (- x))))
   :cost-model {:id :math9-default-cost
                :version 1
                :weights {:operator-count 1
                          :runtime-check 4
                          :unproved-edge :forbidden}
                :tie-break [:proof-depth :source-order :node-id]}
   :bounds {:iterations 8
            :nodes 128
            :per-rule-fuel 16}
   :guards {:domain {'x {:real [-8 8]}}
            :branch-policy {:exp :real-only}}
   :analysis {:domain :consistent
              :branch-policy :consistent
              :proof-status :proved}
   :proof-replay [:trace/sigmoid-definition]
   :explanation :explain/sigmoid-definition
   :valid? true
   :status :proved})

(def math-proof-default-equality-claims
  [{:claim-id :equality/sigmoid-definition
    :source :proof-replay
    :accepted? true
    :proof-ref :proof/sigmoid-rewrite
    :status :proved}])

(defn math-proof-suite
  [manifest]
  (let [source-suite (get-in manifest [:metadata :math :proof] {})]
    (assoc source-suite
           :claims
           (if (contains? source-suite :claims)
             (vec (:claims source-suite))
             (if (contains? source-suite :claim-overrides)
               (mapv #(merge (first math-proof-default-claims) %)
                     (:claim-overrides source-suite))
               math-proof-default-claims))
           :partitions
           (if (contains? source-suite :partitions)
             (vec (:partitions source-suite))
             (if (contains? source-suite :partition-overrides)
               (mapv #(merge (first math-proof-default-partitions) %)
                     (:partition-overrides source-suite))
               math-proof-default-partitions))
           :bound-ledger
           (if (contains? source-suite :bound-ledger)
             (vec (:bound-ledger source-suite))
             (if (contains? source-suite :bound-overrides)
               (mapv #(merge (first math-proof-default-bound-ledger) %)
                     (:bound-overrides source-suite))
               math-proof-default-bound-ledger))
           :roundoff-ledger
           (if (contains? source-suite :roundoff-ledger)
             (vec (:roundoff-ledger source-suite))
             (if (contains? source-suite :roundoff-overrides)
               (mapv #(merge (first math-proof-default-roundoff-ledger) %)
                     (:roundoff-overrides source-suite))
               math-proof-default-roundoff-ledger))
           :provider-results
           (if (contains? source-suite :provider-results)
             (vec (:provider-results source-suite))
             (if (contains? source-suite :provider-overrides)
               (mapv #(merge (first math-proof-default-provider-results) %)
                     (:provider-overrides source-suite))
               math-proof-default-provider-results))
           :rewrite-rules
           (if (contains? source-suite :rewrite-rules)
             (vec (:rewrite-rules source-suite))
             (if (contains? source-suite :rewrite-rule-overrides)
               (mapv #(merge (first math-proof-default-rewrite-rules) %)
                     (:rewrite-rule-overrides source-suite))
               math-proof-default-rewrite-rules))
           :rewrite-traces
           (if (contains? source-suite :rewrite-traces)
             (vec (:rewrite-traces source-suite))
             (if (contains? source-suite :rewrite-trace-overrides)
               (mapv #(merge (first math-proof-default-rewrite-traces) %)
                     (:rewrite-trace-overrides source-suite))
               math-proof-default-rewrite-traces))
           :termination-report
           (if (contains? source-suite :termination-report)
             (:termination-report source-suite)
             math-proof-default-termination)
           :counterexamples
           (if (contains? source-suite :counterexamples)
             (vec (:counterexamples source-suite))
             math-proof-default-counterexamples)
           :egraph-report
           (if (contains? source-suite :egraph-report)
             (:egraph-report source-suite)
             math-proof-default-egraph)
           :equality-claims
           (if (contains? source-suite :equality-claims)
             (vec (:equality-claims source-suite))
             math-proof-default-equality-claims))))

(defn math-proof-fail!
  [id source-path manifest record extra]
  (fail! id
         (case id
           "MATH6-CLAIM" "interval proof claim is malformed or unsupported"
           "MATH6-DOMAIN" "interval proof domain is invalid"
           "MATH6-ROUNDING" "outward rounding assumptions are unproved"
           "MATH6-BRANCH" "interval proof branch policy is incompatible"
           "MATH6-PARTITION" "interval partition tree is unreplayable or incomplete"
           "MATH6-BOUND" "interval proof bounds are missing or insufficient"
           "MATH6-UNRESOLVED" "unresolved cells prevent certificate acceptance"
           "MATH6-PROVIDER" "real-proof provider output is outside trust policy"
           "MATH6-INVALIDATED" "proof artifact has been invalidated"
           "MATH9-RULE-SHAPE" "rewrite rule is malformed"
           "MATH9-DOMAIN" "rewrite rule domain is missing or incompatible"
           "MATH9-BRANCH" "rewrite rule branch policy is incompatible"
           "MATH9-SIDE-CONDITION" "rewrite side condition is undischarged"
           "MATH9-PROOF" "unproved rewrite was used as accepted"
           "MATH9-TRACE" "rewrite trace cannot replay"
           "MATH9-TERMINATION" "rewrite strategy is unbounded"
           "MATH9-COUNTEREXAMPLE" "accepted rewrite is disproved by counterexample"
           "MATH9-EGRAPH" "e-graph artifact has invalid analysis, guard, fuel, cost, or explanation"
           "MATH9-EQUALITY" "tree identity or unproved extraction was used as equality"
           "math proof record is invalid")
         (merge {:source-span (or (:source-span record)
                                  {:source source-path})
                 :profile (or (:profile record) (:profile manifest))
                 :target (or (:target record) (:target manifest))
                 :claim-id (:claim-id record)
                 :rule-id (:rule-id record)
                 :rule-version (:version record)
                 :expression-id (:expression-id record)
                 :graph-id (or (get-in record [:source :efir])
                               (:target-efir record))
                 :candidate-id (get-in record [:source :eml-candidate])
                 :domain (:domain record)
                 :branch-policy (:branch-policy record)
                 :numeric-mode (:numeric-mode record)
                 :bound (:bound record)
                 :checker (get-in record [:checker :name])
                 :provider (:provider record)
                 :diagnostic-family :math-proof}
                extra)))

(defn math6-claim-missing-fields
  [claim]
  (vec (remove #(perf-present? (get claim %))
               [:claim-id :source :claim :domain :branch-policy
                :numeric-mode :precision :status])))

(defn math9-rule-missing-fields
  [rule]
  (vec (remove #(perf-present? (get rule %))
               [:rule-id :version :pattern :replacement :domain
                :branch-policy :numeric-modes :proof-status :source])))

(defn math-proof-validate-math6!
  [source-path manifest suite]
  (doseq [claim (:claims suite)]
    (let [missing-fields (math6-claim-missing-fields claim)]
      (when (seq missing-fields)
        (math-proof-fail! "MATH6-CLAIM" source-path manifest claim
                          {:missing-fields missing-fields
                           :remediation "Emit complete claim, source, domain, mode, branch, precision, and status fields."}))
      (when (or (not (perf-present? (:domain claim)))
                (false? (:domain-valid? claim)))
        (math-proof-fail! "MATH6-DOMAIN" source-path manifest claim
                          {:remediation "Use exact rational interval endpoints or equivalent checker-exact domains."}))
      (when (or (not (perf-present? (:branch-policy claim)))
                (false? (:branch-compatible? claim)))
        (math-proof-fail! "MATH6-BRANCH" source-path manifest claim
                          {:remediation "Keep proof branch policy compatible with EFIR and EML facts."}))
      (when (or (:invalidated? claim) (= :invalidated (:status claim)))
        (math-proof-fail! "MATH6-INVALIDATED" source-path manifest claim
                          {:remediation "Reject stale proof artifacts after invalidating changes."}))))
  (doseq [roundoff (:roundoff-ledger suite)]
    (when-not (true? (:outward-rounding-proven? roundoff))
      (math-proof-fail! "MATH6-ROUNDING" source-path manifest roundoff
                        {:remediation "Prove outward rounding and record floating assumptions."})))
  (doseq [partition (:partitions suite)]
    (when (or (false? (:replayable? partition))
              (not (perf-present? (:cells partition))))
      (math-proof-fail! "MATH6-PARTITION" source-path manifest partition
                        {:remediation "Emit deterministic partition trees with replayable cell ordering."}))
    (when (and (seq (:unresolved partition))
               (not (and (get-in partition [:residual-check :permitted?])
                         (get-in partition [:residual-check :emitted?]))))
      (math-proof-fail! "MATH6-UNRESOLVED" source-path manifest partition
                        {:remediation "Unresolved cells require legal emitted residual checks or proof rejection."})))
  (doseq [bound (:bound-ledger suite)]
    (when (or (not (true? (:bounds-sufficient? bound)))
              (not (number? (:real-bound bound)))
              (not (number? (:roundoff-bound bound)))
              (not (number? (:combined-bound bound)))
              (and (number? (:combined-bound bound))
                   (number? (:required-bound bound))
                   (> (:combined-bound bound) (:required-bound bound))))
      (math-proof-fail! "MATH6-BOUND" source-path manifest bound
                        {:remediation "Record sufficient separate real and roundoff bounds."})))
  (doseq [provider (:provider-results suite)]
    (when (or (not (true? (:imported-through-safe15? provider)))
              (not= :accepted (:trust-policy provider))
              (not (true? (:replayable? provider))))
      (math-proof-fail! "MATH6-PROVIDER" source-path manifest provider
                        {:remediation "Import provider output through SAFE15 trust policy with replayable evidence."})))
  :complete)

(defn math-proof-validate-math9!
  [source-path manifest suite]
  (doseq [rule (:rewrite-rules suite)]
    (let [missing-fields (math9-rule-missing-fields rule)]
      (when (seq missing-fields)
        (math-proof-fail! "MATH9-RULE-SHAPE" source-path manifest rule
                          {:missing-fields missing-fields
                           :remediation "Rewrite rules need pattern, replacement, guards, modes, proof status, and source provenance."}))
      (when (or (not (perf-present? (:domain rule)))
                (false? (:domain-compatible? rule)))
        (math-proof-fail! "MATH9-DOMAIN" source-path manifest rule
                          {:remediation "Attach compatible domains to rewrite rules."}))
      (when (or (not (perf-present? (:branch-policy rule)))
                (false? (:branch-compatible? rule)))
        (math-proof-fail! "MATH9-BRANCH" source-path manifest rule
                          {:remediation "Attach compatible branch policy to rewrite rules."}))
      (when (and (:used-as-accepted? rule)
                 (not (contains? #{:proved :bounded} (:proof-status rule))))
        (math-proof-fail! "MATH9-PROOF" source-path manifest rule
                          {:remediation "Only proved or bounded rewrites may affect generated code."}))))
  (doseq [trace (:rewrite-traces suite)]
    (when (or (false? (:replayable? trace))
              (not (perf-present? (:rule trace)))
              (not (perf-present? (:source trace))))
      (math-proof-fail! "MATH9-TRACE" source-path manifest trace
                        {:remediation "Rewrite traces must replay without rerunning the optimizer."}))
    (when (some #(not= :proved (:result %))
                (:side-condition-results trace))
      (math-proof-fail! "MATH9-SIDE-CONDITION" source-path manifest trace
                        {:remediation "Discharge side conditions before accepting rewrite applications."})))
  (let [termination (:termination-report suite)]
    (when (or (:unbounded? termination)
              (not (true? (:deterministic? termination)))
              (not (perf-present? (:fuel termination))))
      (math-proof-fail! "MATH9-TERMINATION" source-path manifest termination
                        {:remediation "Bound rewrite application with deterministic fuel or proof-guided termination."})))
  (doseq [counterexample (:counterexamples suite)]
    (when (:disproves-accepted? counterexample)
      (math-proof-fail! "MATH9-COUNTEREXAMPLE" source-path manifest counterexample
                        {:remediation "Do not accept identities disproved by counterexample fixtures."})))
  (let [egraph (:egraph-report suite)]
    (when (or (false? (:valid? egraph))
              (not (perf-present? (:cost-model egraph)))
              (not (perf-present? (:bounds egraph)))
              (not (perf-present? (:proof-replay egraph)))
              (not (perf-present? (:explanation egraph))))
      (math-proof-fail! "MATH9-EGRAPH" source-path manifest egraph
                        {:remediation "E-graph extraction needs guards, bounded fuel, cost model, explanation, and proof replay."})))
  (doseq [claim (:equality-claims suite)]
    (when (and (:accepted? claim)
               (contains? #{:tree-identity :eclass-membership
                            :unproved-extraction}
                          (:source claim)))
      (math-proof-fail! "MATH9-EQUALITY" source-path manifest claim
                        {:remediation "Use proof replay, interval proof, or accepted certificate evidence for equality."})))
  :complete)

(defn math-proof-capability-proof
  [suite]
  {:interval-claims-complete?
   (every? #(empty? (math6-claim-missing-fields %)) (:claims suite))
   :exact-domains-and-branch-policy?
   (every? #(and (:domain-valid? %) (:branch-compatible? %)) (:claims suite))
   :partition-replayable?
   (every? #(and (:replayable? %) (perf-present? (:cells %)))
           (:partitions suite))
   :bounds-separated-and-sufficient?
   (every? #(and (:bounds-sufficient? %)
                 (number? (:real-bound %))
                 (number? (:roundoff-bound %)))
           (:bound-ledger suite))
   :providers-safe15-imported?
   (every? #(and (:imported-through-safe15? %)
                 (= :accepted (:trust-policy %)))
           (:provider-results suite))
   :rewrite-rules-proof-gated?
   (every? #(or (not (:used-as-accepted? %))
                (contains? #{:proved :bounded} (:proof-status %)))
           (:rewrite-rules suite))
   :rewrite-traces-replayable?
   (every? #(and (:replayable? %) (perf-present? (:source %)))
           (:rewrite-traces suite))
   :egraph-extraction-proof-backed?
   (let [egraph (:egraph-report suite)]
     (and (:valid? egraph)
          (perf-present? (:proof-replay egraph))
          (perf-present? (:explanation egraph))))
   :tree-identity-not-equality?
   (every? #(not (and (:accepted? %)
                      (contains? #{:tree-identity :eclass-membership
                                   :unproved-extraction}
                                 (:source %))))
           (:equality-claims suite))
   :status :complete})

(defn math-proof-source-artifact
  [source-path source-text]
  (let [approximation-artifact (approximation-source-artifact source-path source-text)
        manifest (:profile-manifest approximation-artifact)
        suite (math-proof-suite manifest)
        _ (math-proof-validate-math6! source-path manifest suite)
        _ (math-proof-validate-math9! source-path manifest suite)
        capability-proof (math-proof-capability-proof suite)
        conformance {:documents ["MATH6" "MATH9"]
                     :task "P05-T05"
                     :required-diagnostic-ids math6-9-diagnostic-ids
                     :interval-proof-status :complete
                     :symbolic-rewrite-status :complete
                     :egraph-status :complete
                     :status :complete}]
    {:kind :gravity/stage0-math-proof-artifact
     :document-set ["MATH6" "MATH9"]
     :pass {:name :interval-symbolic-proof
            :input :approximation-certificate
            :output :proof-and-rewrite-record
            :requires [:certified-approximation :eml-normalization
                       :efir-validation :safe15-proof-import]
            :preserves [:source-spans :profile :target :effects
                        :capabilities :domain :branch-policy :numeric-mode
                        :precision-contract :target-efir]
            :emits [:claim-record
                    :interval-domain-map
                    :partition-tree
                    :rational-bound-ledger
                    :roundoff-ledger
                    :branch-coverage-report
                    :unresolved-cell-report
                    :checker-transcript
                    :safe15-proof-reference
                    :rewrite-rule-registry
                    :rule-proof-artifact
                    :rewrite-application-trace
                    :counterexample-fixture
                    :termination-report
                    :egraph-saturation-report
                    :equality-explanation-trace
                    :math-proof-conformance-results]
            :rejects math6-9-diagnostic-ids}
     :approximation-artifact-hash
     (str "sha256:" (sha256-hex (pr-str approximation-artifact)))
     :approximation-artifact-kind (:kind approximation-artifact)
     :profile-manifest manifest
     :claim-record (:claims suite)
     :interval-domain-map
     (mapv #(select-keys % [:claim-id :domain]) (:claims suite))
     :partition-tree (:partitions suite)
     :rational-bound-ledger (:bound-ledger suite)
     :roundoff-ledger (:roundoff-ledger suite)
     :branch-coverage-report
     (mapv #(select-keys % [:claim-id :branch-policy]) (:claims suite))
     :unresolved-cell-report
     (mapv #(select-keys % [:partition-id :unresolved :residual-check])
           (:partitions suite))
     :checker-transcript (:provider-results suite)
     :safe15-proof-reference
     (mapv #(select-keys % [:claim-id :proof-ref :trust-policy])
           (:provider-results suite))
     :rewrite-rule-registry (:rewrite-rules suite)
     :rule-proof-artifact
     (mapv #(select-keys % [:rule-id :proof-status :proof-ref])
           (:rewrite-rules suite))
     :rewrite-application-trace (:rewrite-traces suite)
     :counterexample-fixture (:counterexamples suite)
     :termination-report (:termination-report suite)
     :egraph-saturation-report (:egraph-report suite)
     :equality-explanation-trace (:equality-claims suite)
     :capability-based-proof capability-proof
     :math-proof-conformance-results conformance
     :diagnostics []}))

