(defn c18-verification-validate!
  [source-path artifact]
  (let [risk-records (:pass-risk-classification artifact)
        risk-passes (set (map :pass risk-records))
        evidence-passes (set (map :pass (:pass-evidence-records artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:verification-diagnostic-stream
                                       :diagnostics])))
        trust-fields (set (keys (:compiler-trust-report artifact)))]
    (doseq [risk risk-records]
      (when-not (set/subset? (set c18-pass-risk-required-fields)
                             (set (keys risk)))
        (c18-verification-fail!
         "C18-RISK" source-path
         {:pass-id (:pass risk)
          :version (:version risk)
          :risk-class (:risk risk)
          :required-evidence (:minimum-evidence risk)
          :available-evidence #{}
          :affected-profiles (:affected-profiles risk)
          :affected-targets (:affected-targets risk)}
         {:missing-fields
          (vec (remove (set (keys risk))
                       c18-pass-risk-required-fields))})))
    (when-not (= risk-passes evidence-passes)
      (c18-verification-fail! "C18-EVIDENCE" source-path
                              (first risk-records)
                              {:missing-fields [:pass-evidence-records]}))
    (when-not (every? #(= :accepted (:result %))
                      (:translation-validation-logs artifact))
      (c18-verification-fail! "C18-VALIDATION" source-path
                              (first (:translation-validation-logs artifact))
                              {:missing-fields [:accepted-validation]}))
    (when-not (every? #(= :accepted (:status %))
                      (:proof-or-certificate-references artifact))
      (c18-verification-fail! "C18-PROOF" source-path
                              (first (:proof-or-certificate-references
                                      artifact))
                              {:missing-fields [:accepted-proof]}))
    (when-not (set/subset? (set c18-trust-report-required-fields)
                           trust-fields)
      (c18-verification-fail! "C18-TRUST-REPORT" source-path
                              (:compiler-trust-report artifact)
                              {:missing-fields
                               (vec (remove trust-fields
                                            c18-trust-report-required-fields))}))
    (when-not (every? #(= :blocked (:release-artifact-status %))
                      (:release-gate-failure-fixtures artifact))
      (c18-verification-fail! "C18-RELEASE-GATE" source-path
                              (first (:release-gate-failure-fixtures
                                      artifact))
                              {:missing-fields [:blocked-release]}))
    (when-not (every? #(and (= :captured (:status %))
                            (true? (:regression-fixture-created? %)))
                      (:counterexample-artifacts artifact))
      (c18-verification-fail! "C18-COUNTEREXAMPLE" source-path
                              (first (:counterexample-artifacts artifact))
                              {:missing-fields [:regression-fixture]}))
    (when-not (= :passed (get-in artifact [:plugin-evidence-report :status]))
      (c18-verification-fail! "C18-PLUGIN" source-path
                              (:plugin-evidence-report artifact)
                              {:missing-fields [:plugin-evidence-report]}))
    (when-not (every? #(= :passed (:status %))
                      (:target-lowering-conformance artifact))
      (c18-verification-fail! "C18-BACKEND" source-path
                              (first (:target-lowering-conformance artifact))
                              {:missing-fields [:target-lowering-conformance]}))
    (when-not (= (set c18-verification-diagnostic-ids) diagnostics)
      (c18-verification-fail! "C18-EVIDENCE" source-path
                              (:verification-diagnostic-stream artifact)
                              {:missing-fields [:verification-diagnostics]})))
  :complete)

(defn c18-verification-capability-proof
  [artifact]
  (let [risk-records (:pass-risk-classification artifact)
        evidence-records (:pass-evidence-records artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:verification-diagnostic-stream
                                       :diagnostics])))]
    {:c17-plugin-input-verified?
     (= :complete (get-in artifact
                          [:c17-plugin-artifact
                           :capability-based-proof :status]))
     :pass-risk-classification-complete?
     (every? #(set/subset? (set c18-pass-risk-required-fields)
                           (set (keys %)))
             risk-records)
     :high-risk-evidence-present?
     (every? (fn [risk]
               (let [record (first (filter #(= (:pass %)
                                               (:pass risk))
                                           evidence-records))]
                 (and record
                      (= :present (:status record))
                      (set/subset? (:minimum-evidence risk)
                                   (:evidence record)))))
             (filter #(#{:high :critical} (:risk %)) risk-records))
     :translation-validation-accepted?
     (every? #(= :accepted (:result %))
             (:translation-validation-logs artifact))
     :proofs-and-certificates-accepted?
     (every? #(= :accepted (:status %))
             (:proof-or-certificate-references artifact))
     :diagnostics-preserve-source-and-generated-origin?
     (every? #(and (get-in % [:primary :span])
                   (seq (:related %))
                   (seq (:origin-chain %)))
             (get-in artifact [:verification-diagnostic-stream
                               :diagnostics]))
     :differential-and-property-fixtures-passed?
     (= :passed (get-in artifact
                        [:differential-and-property-fixture-results
                         :status]))
     :trust-report-complete?
     (= :complete (get-in artifact [:compiler-trust-report :status]))
     :release-gate-blocks-missing-evidence?
     (every? #(= :blocked (:release-artifact-status %))
             (:release-gate-failure-fixtures artifact))
     :counterexample-regression-captured?
     (every? #(and (= :captured (:status %))
                   (true? (:regression-fixture-created? %)))
             (:counterexample-artifacts artifact))
     :experimental-gates-explicit?
     (every? #(= :explicit-feature-gate (:gate %))
             (:experimental-pass-gates artifact))
     :plugin-evidence-policy-passed?
     (= :passed (get-in artifact [:plugin-evidence-report :status]))
     :backend-conformance-passed?
     (every? #(= :passed (:status %))
             (:target-lowering-conformance artifact))
     :diagnostics-covered?
     (= (set c18-verification-diagnostic-ids) diagnostics)
     :status :complete}))

(defn compiler-c18-verification-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (c18-verification-source-overrides module)
        _ (c18-verification-validate-source-overrides! source-path
                                                       source-overrides)
        plugin-artifact (compiler-c17-plugin-source-artifact source-path
                                                             source-text)
        input-id (:artifact-id plugin-artifact)
        risk-records (c18-pass-risk-records)
        pass-evidence-records
        (mapv (fn [risk]
                {:artifact :gravity/pass-evidence
                 :pass (:pass risk)
                 :version (:version risk)
                 :risk (:risk risk)
                 :required (:minimum-evidence risk)
                 :evidence (:minimum-evidence risk)
                 :evidence-artifacts [(str "sha256:c18-evidence-"
                                           (name (:pass risk)))]
                 :status :present})
              risk-records)
        translation-validation-logs
        [{:artifact :gravity/translation-validation
          :pass :bounds-check-elide
          :input input-id
          :output "sha256:c18-bounds-check-elide-output"
          :changed-functions [:safe-index]
          :properties #{:same-observable-result :same-effects
                        :same-safety-outcomes}
          :method :symbolic-plus-fixtures
          :proofs [:proof/c18-bounds-check-dominance]
          :counterexamples []
          :result :accepted}
         {:artifact :gravity/translation-validation
          :pass :plugin-loop-fuser
          :input input-id
          :output "sha256:c18-loop-fuser-output"
          :changed-functions [:loop-body]
          :properties #{:same-observable-result :same-effects}
          :method :differential-fixtures
          :proofs [:proof/c18-loop-fuser-effect-order]
          :counterexamples []
          :result :accepted}]
        diagnostic-stream (c18-verification-diagnostic-stream source-path
                                                              input-id)
        artifact-base
        {:kind :gravity/stage0-c18-compiler-verification-artifact
         :task "P06-D097"
         :document-set ["C18"]
         :governing-document c18-verification-governing-document
         :pass {:name :c18-compiler-verification
                :input :compiler-plugin-artifact
                :output :compiler-verification-and-trust-artifact
                :requires [:c17-plugin-artifact :risk-policy
                           :evidence-policy :translation-validation
                           :proof-certificate-policy :trust-report-policy
                           :release-gate-policy]
                :preserves [:source-spans :generated-origins :profile
                            :target :diagnostics :proofs :capabilities]
                :emits [:compiler-verification-plan
                        :pass-risk-classification
                        :pass-evidence-records
                        :translation-validation-logs
                        :proof-or-certificate-references
                        :differential-and-property-fixture-results
                        :compiler-trust-report :release-gate-report
                        :release-gate-failure-fixtures
                        :counterexample-artifacts
                        :experimental-pass-gates
                        :plugin-evidence-report
                        :target-lowering-conformance
                        :verification-diagnostic-stream]
                :rejects c18-verification-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :c17-plugin-artifact
         (select-keys plugin-artifact
                      [:kind :task :artifact-id :governing-document
                       :capability-based-proof])
         :plugin-artifact-kind (:kind plugin-artifact)
         :plugin-artifact-hash input-id
         :compiler-verification-plan
         {:artifact :gravity/compiler-verification-plan
          :status :complete
          :evidence-policy :risk-based
          :passes (mapv :pass risk-records)
          :required-evidence-families
          #{:golden-fixtures :fuzz :translation-validation
            :proof-dominance-check :backend-conformance
            :differential-execution :sandbox-tests :contract-verifier}
          :release-policy :block-affected-profiles-on-failure}
         :pass-risk-classification risk-records
         :pass-evidence-records pass-evidence-records
         :stage-verifier-reports
         (mapv (fn [risk]
                 {:artifact :gravity/stage-verifier-report
                  :pass (:pass risk)
                  :artifact-kinds (:artifact-kinds risk)
                  :source-or-generated-origin-preserved? true
                  :status :passed})
               risk-records)
         :translation-validation-logs translation-validation-logs
         :proof-or-certificate-references
         [{:proof :proof/c18-bounds-check-dominance
           :pass :bounds-check-elide
           :status :accepted}
          {:certificate :cert/c18-safety-check-elision
           :pass :bounds-check-elide
           :status :accepted}
          {:proof :proof/c18-loop-fuser-effect-order
           :pass :plugin-loop-fuser
           :status :accepted}]
         :differential-and-property-fixture-results
         {:artifact :gravity/compiler-fixture-results
          :status :passed
          :families {:front-end {:golden 8 :fuzz 64 :status :passed}
                     :optimization {:translation-validation 2
                                    :property 12
                                    :status :passed}
                     :backend {:differential 5
                               :conformance 4
                               :status :passed}}}
         :compiler-trust-report
         {:artifact :gravity/compiler-trust-report
          :compiler "gravity-stage0-clojure"
          :profiles {:hosted {:required-evidence :high
                              :blocked-passes []}
                     :native {:required-evidence :critical
                              :blocked-passes [:gpu-lowering]}}
          :targets {:jvm {:required-evidence :high
                          :blocked-passes []}}
          :passes (mapv #(select-keys % [:pass :risk
                                          :minimum-evidence
                                          :release-gate])
                        risk-records)
          :artifact-kinds
          (set (mapcat :artifact-kinds risk-records))
          :known-gaps [{:pass :gpu-lowering
                        :profiles #{:gpu}
                        :targets #{:gpu}
                        :status :experimental
                        :gate :explicit-feature-gate}]
          :release-gates [:verifiers :high-risk-evidence
                          :target-lowering-conformance
                          :stale-proof-rejection
                          :diagnostic-goldens
                          :self-hosting-comparison]
          :status :complete}
         :release-gate-report
         {:artifact :gravity/release-gate-report
          :status :passed
          :checks [:verifier-pass-every-artifact
                   :no-active-critical-failures
                   :high-risk-evidence-present
                   :target-lowering-conformance
                   :stale-proof-and-certificate-rejection
                   :diagnostic-golden-fixtures]
          :release-artifacts :allowed-for-hosted-jvm
          :blocked-experimental-passes [:gpu-lowering]}
         :release-gate-failure-fixtures
         [{:artifact :gravity/release-gate-failure
           :pass :gpu-lowering
           :missing-evidence #{:backend-conformance
                               :differential-execution}
           :affected-profiles #{:gpu}
           :affected-targets #{:gpu}
           :diagnostic "C18-RELEASE-GATE"
           :release-artifact-status :blocked}]
         :counterexample-artifacts
         [{:artifact :gravity/counterexample
           :source-fixture "bootstrap/clojure/fixtures/rejected/compiler-verify-c18-validation.gravity"
           :input-artifact input-id
           :output-artifact "sha256:c18-invalid-optimization-output"
           :violated-property :same-safety-outcomes
           :diagnostic-stream :gravity/c18-verification-diagnostic-stream
           :minimized-reproducer "compiler-verify-c18-validation.gravity"
           :affected-pass :bounds-check-elide
           :pass-version "stage0-c18"
           :status :captured
           :regression-fixture-created? true}]
         :experimental-pass-gates
         [{:pass :gpu-lowering
           :profiles #{:gpu}
           :targets #{:gpu}
           :gate :explicit-feature-gate
           :release-default :disabled
           :artifact-status :not-release-quality}]
         :plugin-evidence-report
         {:artifact :gravity/plugin-evidence-report
          :plugin 'gravity.plugins.stage0/loop-fuser
          :required #{:sandbox-tests :contract-verifier
                      :fixture-suite}
          :available #{:sandbox-tests :contract-verifier
                       :fixture-suite}
          :status :passed}
         :target-lowering-conformance
         [{:artifact :gravity/target-lowering-conformance
           :target :jvm
           :profiles #{:hosted}
           :source-core-mir-intent #{:same-observable-result
                                     :same-effects
                                     :same-safety-outcomes}
           :emitted-artifact-behavior :matched
           :method :differential-execution
           :status :passed}]
         :verification-diagnostic-stream diagnostic-stream
         :c18-verification-results
         {:documents ["C18"]
          :task "P06-D097"
          :required-diagnostic-ids c18-verification-diagnostic-ids
          :c17-input-status :complete
          :plan-status :complete
          :risk-status :complete
          :evidence-status :complete
          :translation-validation-status :complete
          :proof-certificate-status :complete
          :fixture-status :complete
          :trust-report-status :complete
          :release-gate-status :complete
          :counterexample-status :complete
          :experimental-gate-status :complete
          :plugin-status :complete
          :backend-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (c18-verification-validate! source-path artifact-base)
        capability-proof (c18-verification-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn compiler-c18-verification-file-artifact
  [path]
  (compiler-c18-verification-source-artifact path (slurp path)))

(def backend-interface-governing-documents
  ["docs/phase-07-backend-architecture/098-b1-backend-interface-specification.md"
   "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"])

(def backend-interface-diagnostic-ids
  ["B1-INPUT"
   "B1-PROFILE"
   "B1-TARGET"
   "B1-ABI"
   "B1-RUNTIME"
   "B1-PROOF"
   "B1-CAPABILITY"
   "B1-UNSUPPORTED"
   "B1-METADATA"
   "B14-COVERAGE"
   "B14-METADATA"
   "B14-ARTIFACT"])

(def backend-interface-diagnostic-messages
  {"B1-INPUT" "backend input is unverified or incomplete"
   "B1-PROFILE" "backend profile compatibility failed"
   "B1-TARGET" "backend target feature is unsupported"
   "B1-ABI" "backend ABI or layout is not representable"
   "B1-RUNTIME" "backend runtime or provider dependency is missing or forbidden"
   "B1-PROOF" "backend target assumption lacks proof metadata"
   "B1-CAPABILITY" "backend provider selection loses required authority"
   "B1-UNSUPPORTED" "backend MIR operation or domain anchor is unsupported"
   "B1-METADATA" "backend artifact metadata is incomplete"
   "B14-COVERAGE" "backend conformance fixture coverage is incomplete"
   "B14-METADATA" "backend conformance metadata preservation failed"
   "B14-ARTIFACT" "backend artifact manifest validation failed"})

(def backend-interface-override-diagnostics
  {:b1-input ["B1-INPUT" :backend-input]
   :b1-profile ["B1-PROFILE" :profile-eligibility]
   :b1-target ["B1-TARGET" :target-eligibility]
   :b1-abi ["B1-ABI" :abi-layout]
   :b1-runtime ["B1-RUNTIME" :runtime-provider]
   :b1-proof ["B1-PROOF" :proof-metadata]
   :b1-capability ["B1-CAPABILITY" :capability-preservation]
   :b1-unsupported ["B1-UNSUPPORTED" :unsupported-operation]
   :b1-metadata ["B1-METADATA" :artifact-metadata]
   :b14-coverage ["B14-COVERAGE" :conformance-coverage]
   :b14-metadata ["B14-METADATA" :conformance-metadata]
   :b14-artifact ["B14-ARTIFACT" :conformance-artifact]})

(def backend-manifest-required-fields
  [:artifact :backend :version :accepts :emits :requires
   :supports-profiles :rejects])

(def backend-input-required-fields
  [:input :profile :target :abi :runtime :providers :effects
   :capabilities :safety :proofs :source-map :dependencies])

(defn backend-interface-source-overrides
  [module]
  (or (get-in module [:metadata :backend :interface])
      (get-in module [:metadata :backend])
      {}))

(defn backend-interface-fail!
  [id source-path subject extra]
  (fail! id
         (get backend-interface-diagnostic-messages id
              "backend interface validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :backend-interface
                 :stage (or (:stage subject) :backend-interface)
                 :backend-id (:backend-id subject)
                 :input-artifact-id (:input-artifact-id subject)
                 :mir-op (:mir-op subject)
                 :domain-anchor (:domain-anchor subject)
                 :profile (:profile subject)
                 :target (:target subject)
                 :missing-evidence (:missing-evidence subject)
                 :fallback-status (:fallback-status subject)
                 :remediation "Feed the backend only verified MIR or domain IR with profile, target, ABI, runtime, effects, capabilities, safety, proof, provenance, artifact, and conformance metadata."}
                extra)))

(defn backend-interface-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (let [[id subject-kind] (get backend-interface-override-diagnostics
                                 fail-kind)]
      (when id
        (backend-interface-fail!
         id source-path
         {:stage subject-kind
          :backend-id :gravity.backend/interface-v1
          :input-artifact-id (str "backend-input-" (name fail-kind))
          :mir-op :runtime-check
          :domain-anchor :efir
          :profile :hosted
          :target :jvm
          :missing-evidence [fail-kind]
          :fallback-status :unavailable}
         {:missing-fields [fail-kind]})))))

(defn backend-interface-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-diagnostic-stream
   :stage :backend-interface
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :backend-interface
            :message-key (keyword "backend"
                                  (str/lower-case
                                   (str/replace id #"_" "-")))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "backend-syntax-" index)
                      :artifact input-id}
            :backend-id :gravity.backend/interface-v1
            :input-artifact-id input-id
            :mir-op (if (= id "B1-UNSUPPORTED")
                      :target-specific-opcode
                      :runtime-check)
            :domain-anchor (if (= id "B1-UNSUPPORTED") :opaque-domain :efir)
            :profile :hosted
            :target :jvm
            :missing-evidence #{:proof-metadata :source-map}
            :fallback-status :recorded
            :facts {:rule id
                    :metadata-required? true
                    :safe-ub-policy :reject}
            :remediation [{:kind :provide-backend-evidence}
                          {:kind :select-supported-target}]
            :redactions []
            :ordering-key [id :gravity.backend/interface-v1 :jvm]})
         backend-interface-diagnostic-ids
         (range))
   :status :complete})

(defn backend-interface-validate!
  [source-path artifact]
  (let [manifest (:backend-manifest artifact)
        input-packet (:backend-input-packet artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:backend-diagnostic-stream
                                       :diagnostics])))]
    (when-not (set/subset? (set backend-manifest-required-fields)
                           (set (keys manifest)))
      (backend-interface-fail! "B1-INPUT" source-path manifest
                               {:missing-fields
                                (vec (remove (set (keys manifest))
                                             backend-manifest-required-fields))}))
    (when-not (set/subset? (set backend-input-required-fields)
                           (set (keys input-packet)))
      (backend-interface-fail! "B1-INPUT" source-path input-packet
                               {:missing-fields
                                (vec (remove (set (keys input-packet))
                                             backend-input-required-fields))}))
    (when-not (= :eligible (get-in artifact
                                   [:backend-input-eligibility-report
                                    :decision]))
      (backend-interface-fail! "B1-PROFILE" source-path
                               (:backend-input-eligibility-report artifact)
                               {:missing-fields [:eligibility]}))
    (when-not (every? #(= :passed (:status %))
                      (:eligibility-checks artifact))
      (backend-interface-fail! "B1-TARGET" source-path
                               (first (:eligibility-checks artifact))
                               {:missing-fields [:eligibility-checks]}))
    (when-not (= :accepted (get-in artifact
                                   [:proof-to-target-metadata-map :status]))
      (backend-interface-fail! "B1-PROOF" source-path
                               (:proof-to-target-metadata-map artifact)
                               {:missing-fields [:proof-to-target-metadata]}))
    (when-not (= :preserved (get-in artifact
                                    [:capability-preservation-report
                                     :status]))
      (backend-interface-fail! "B1-CAPABILITY" source-path
                               (:capability-preservation-report artifact)
                               {:missing-fields [:capability-preservation]}))
    (when-not (= :recorded (get-in artifact
                                   [:unsupported-feature-report :status]))
      (backend-interface-fail! "B1-UNSUPPORTED" source-path
                               (:unsupported-feature-report artifact)
                               {:missing-fields [:unsupported-feature-report]}))
    (when-not (every? #(and (:provenance %) (:source-debug-map %)
                            (:safety-evidence %) (:conformance %))
                      (:target-artifact-manifest artifact))
      (backend-interface-fail! "B1-METADATA" source-path
                               (first (:target-artifact-manifest artifact))
                               {:missing-fields [:target-artifact-metadata]}))
    (when-not (= :passed (get-in artifact
                                 [:backend-conformance-record :status]))
      (backend-interface-fail! "B14-COVERAGE" source-path
                               (:backend-conformance-record artifact)
                               {:missing-fields [:backend-conformance-record]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report :status]))
      (backend-interface-fail! "B14-METADATA" source-path
                               (:metadata-preservation-report artifact)
                               {:missing-fields [:metadata-preservation]}))
    (when-not (= :valid (get-in artifact
                                [:artifact-manifest-validation-report
                                 :status]))
      (backend-interface-fail! "B14-ARTIFACT" source-path
                               (:artifact-manifest-validation-report artifact)
                               {:missing-fields [:artifact-manifest-validation]}))
    (when-not (= (set backend-interface-diagnostic-ids) diagnostics)
      (backend-interface-fail! "B14-COVERAGE" source-path
                               (:backend-diagnostic-stream artifact)
                               {:missing-fields [:backend-diagnostics]})))
  :complete)

(defn backend-interface-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:backend-diagnostic-stream
                                       :diagnostics])))]
    {:c18-verification-input-verified?
     (= :complete (get-in artifact
                          [:c18-verification-artifact
                           :capability-based-proof :status]))
     :backend-manifest-complete?
     (set/subset? (set backend-manifest-required-fields)
                  (set (keys (:backend-manifest artifact))))
     :verified-input-packet-complete?
     (set/subset? (set backend-input-required-fields)
                  (set (keys (:backend-input-packet artifact))))
     :eligibility-passed?
     (and (= :eligible (get-in artifact
                               [:backend-input-eligibility-report
                                :decision]))
          (every? #(= :passed (:status %))
                  (:eligibility-checks artifact)))
     :unchecked-ir-rejected?
     (= :rejected (get-in artifact
                          [:unchecked-ir-rejection-record :status]))
     :undefined-behavior-rejected?
     (= :rejected (get-in artifact
                          [:undefined-behavior-rejection-record :status]))
     :proof-backed-target-metadata?
     (= :accepted (get-in artifact
                          [:proof-to-target-metadata-map :status]))
     :artifact-metadata-preserved?
     (and (every? #(and (:provenance %) (:source-debug-map %)
                        (:safety-evidence %) (:conformance %))
                  (:target-artifact-manifest artifact))
          (= :preserved (get-in artifact
                                [:metadata-preservation-report :status])))
     :capabilities-preserved?
     (= :preserved (get-in artifact
                           [:capability-preservation-report :status]))
     :unsupported-features-recorded?
     (= :recorded (get-in artifact
                          [:unsupported-feature-report :status]))
     :conformance-record-passed?
     (= :passed (get-in artifact
                        [:backend-conformance-record :status]))
     :artifact-manifest-valid?
     (= :valid (get-in artifact
                       [:artifact-manifest-validation-report :status]))
     :diagnostics-covered?
     (= (set backend-interface-diagnostic-ids) diagnostics)
     :status :complete}))

(defn backend-interface-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (backend-interface-source-overrides module)
        _ (backend-interface-validate-source-overrides! source-path
                                                        source-overrides)
        verification-artifact (compiler-c18-verification-source-artifact
                               source-path source-text)
        input-id (:artifact-id verification-artifact)
        diagnostic-stream (backend-interface-diagnostic-stream source-path
                                                               input-id)
        artifact-base
        {:kind :gravity/stage0-backend-interface-artifact
         :task "P07-T01"
         :document-set ["B1" "B14"]
         :governing-documents backend-interface-governing-documents
         :pass {:name :backend-interface
                :input :compiler-verification-and-trust-artifact
                :output :backend-interface-and-conformance-artifact
                :requires [:verified-mir-or-domain-ir :profile-manifest
                           :target-manifest :abi-policy :runtime-provider
                           :effects :capabilities :safety :proofs
                           :source-map :dependencies]
                :preserves [:source-spans :generated-origins :profile
                            :target :effects :capabilities :safety
                            :proofs :unsafe-audit-ids :provenance]
                :emits [:backend-manifest :backend-input-eligibility-report
                        :target-artifact-manifest :abi-layout-record
                        :runtime-provider-dependency-record
                        :proof-to-target-metadata-map :source-debug-map
                        :unsupported-feature-report
                        :backend-diagnostic-stream
                        :backend-conformance-record]
                :rejects backend-interface-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :c18-verification-artifact
         (select-keys verification-artifact
                      [:kind :task :artifact-id :governing-document
                       :capability-based-proof])
         :compiler-verification-artifact-kind (:kind verification-artifact)
         :compiler-verification-artifact-hash input-id
         :backend-manifest
         {:artifact :gravity/backend-manifest
          :backend :gravity.backend/interface-v1
          :version "1"
          :accepts #{:gravity/mir :gravity/domain-ir}
          :emits #{:object :library :bytecode :source
                   :workflow-graph :hdl :query-plan}
          :requires #{:profile :target :abi :runtime :effects
                      :capabilities :safety}
          :supports-profiles #{:core :hosted :native :firmware :kernel
                               :gpu :hardware :distributed :ai}
          :rejects #{:unverified-ir :unsupported-op :missing-proof
                     :implicit-ub :ambient-capability :profile-violation}
          :status :complete}
         :backend-input-packet
         {:input {:kind :gravity/mir
                  :id input-id
                  :verification-status :accepted}
          :profile "profile-manifest:hosted"
          :target "target-manifest:jvm"
          :abi "abi-policy:jvm-stage0"
          :runtime "runtime-manifest:clojure-jvm-stage0"
          :providers "provider-selection:stage0"
          :effects "effect-summary:stage0"
          :capabilities "capability-summary:stage0"
          :safety "safety-bundle:stage0"
          :proofs "proof-table:stage0"
          :source-map "source-map:stage0"
          :dependencies "dependency-graph:stage0"}
         :backend-input-eligibility-report
         {:artifact :gravity/backend-input-eligibility-report
          :backend :gravity.backend/interface-v1
          :input input-id
          :profile :hosted
          :target :jvm
          :decision :eligible
          :status :complete}
         :eligibility-checks
         [{:check :verified-input :status :passed}
          {:check :profile-backend-compatibility :status :passed}
          {:check :target-feature-support :status :passed}
          {:check :runtime-availability :status :passed}
          {:check :abi-representability :status :passed}
          {:check :layout-representability :status :passed}
          {:check :provider-availability :status :passed}
          {:check :effect-capability-preservation :status :passed}
          {:check :safety-bundle-completeness :status :passed}
          {:check :proof-validity :status :passed}
          {:check :source-debug-map-preservation :status :passed}]
         :unchecked-ir-rejection-record
         {:artifact :gravity/backend-rejection
          :diagnostic "B1-INPUT"
          :input :unverified-mir
          :status :rejected}
         :undefined-behavior-rejection-record
         {:artifact :gravity/backend-rejection
          :diagnostic "B1-PROOF"
          :assumption :signed-overflow-undefined
          :status :rejected}
         :target-artifact-manifest
         [{:artifact :gravity/target-artifact
           :kind :bytecode
           :digest "sha256:p07-stage0-jvm-bytecode-metadata"
           :backend :gravity.backend/interface-v1
           :backend-version "1"
           :source-input input-id
           :profile :hosted
           :target :jvm
           :abi-layout "abi-layout:jvm-stage0"
           :runtime-provider "runtime-provider:clojure-jvm-stage0"
           :safety-evidence "safety-bundle:stage0"
           :proof-summary "proof-table:stage0"
           :capability-summary "capability-summary:stage0"
           :source-debug-map "source-debug-map:stage0"
           :unsafe-audit-ids []
           :dependencies ["dependency-graph:stage0"]
           :conformance "backend-conformance:p07-t01"
           :provenance {:compiler "gravity-stage0-clojure"
                        :pass-history ["C18" "B1" "B14"]}}]
         :abi-layout-record
         {:artifact :gravity/abi-layout-record
          :target :jvm
          :layout-policy :managed-runtime
          :representability :passed
          :status :complete}
         :runtime-provider-dependency-record
         {:artifact :gravity/runtime-provider-dependency-record
          :runtime :clojure-jvm-stage0
          :providers [:stdout :checked-exception :managed-memory]
          :hidden-dependencies []
          :status :complete}
         :proof-to-target-metadata-map
         {:artifact :gravity/proof-to-target-metadata-map
          :status :accepted
          :assumptions [{:target-assumption :no-signed-overflow
                         :proof :proof/c18-bounds-check-dominance}
                        {:target-assumption :dereferenceable-managed-reference
                         :proof :proof/c18-safety-check-elision}
                        {:target-assumption :host-exception-mapping
                         :proof :proof/c18-loop-fuser-effect-order}]}
         :source-debug-map
         {:artifact :gravity/source-debug-map
          :input input-id
          :source-spans :preserved
          :generated-origin-chain :preserved
          :status :complete}
         :capability-preservation-report
         {:artifact :gravity/backend-capability-preservation
          :capabilities (:capabilities module)
          :provider-selection :stage0
          :status :preserved}
         :unsupported-feature-report
         {:artifact :gravity/unsupported-feature-report
          :status :recorded
          :unsupported [{:mir-op :target-specific-opcode
                         :diagnostic "B1-UNSUPPORTED"
                         :fallback :reject}]}
         :backend-diagnostic-stream diagnostic-stream
         :backend-conformance-record
         {:artifact :gravity/backend-conformance-record
          :status :passed
          :suite :p07-t01-backend-interface
          :positive-lowering-results [{:fixture :backend-interface-positive
                                       :status :passed}]
          :negative-diagnostic-results
          (mapv (fn [id]
                  {:diagnostic id :status :matched})
                backend-interface-diagnostic-ids)
          :target-availability {:jvm :available}
          :evidence-pack "backend-conformance-pack:p07-t01"}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :safety :proofs :unsafe-audit-ids
                   :profile :target :runtime :abi :conformance]}
         :artifact-manifest-validation-report
         {:artifact :gravity/artifact-manifest-validation-report
          :status :valid
          :validated-artifacts ["sha256:p07-stage0-jvm-bytecode-metadata"]}
         :backend-interface-results
         {:documents ["B1" "B14"]
          :task "P07-T01"
          :required-diagnostic-ids backend-interface-diagnostic-ids
          :c18-input-status :complete
          :manifest-status :complete
          :input-contract-status :complete
          :eligibility-status :complete
          :artifact-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (backend-interface-validate! source-path artifact-base)
        capability-proof (backend-interface-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn backend-interface-file-artifact
  [path]
  (backend-interface-source-artifact path (slurp path)))

