   "B6-MANIFEST"])

(def hosted-lowering-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             hosted-lowering-diagnostic-ids)))

(defn hosted-lowering-backend-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B4-") :gravity.backend/wasm
    (str/starts-with? id "B5-") :gravity.backend/jvm
    :else :gravity.backend/js-ts))

(defn hosted-lowering-stage-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B4-") :wasm-backend
    (str/starts-with? id "B5-") :jvm-backend
    :else :js-ts-backend))

(defn hosted-lowering-diagnostic-message
  [id]
  (cond
    (str/starts-with? id "B4-") "Wasm hosted boundary lowering contract failed"
    (str/starts-with? id "B5-") "JVM hosted boundary lowering contract failed"
    :else "JavaScript/TypeScript hosted boundary lowering contract failed"))

(defn hosted-lowering-source-overrides
  [module]
  (or (get-in module [:metadata :backend :hosted-lowering])
      (get-in module [:metadata :backend :hosted])
      {}))

(defn hosted-lowering-fail!
  [id source-path subject extra]
  (fail! id
         (hosted-lowering-diagnostic-message id)
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :hosted-backend-lowering
                 :stage (or (:stage subject)
                            (hosted-lowering-stage-for-diagnostic id))
                 :backend (or (:backend subject)
                              (hosted-lowering-backend-for-diagnostic id))
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :hosted-stage0)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :host-call)
                 :domain-anchor (:domain-anchor subject)
                 :host-symbol (:host-symbol subject)
                 :missing-evidence (:missing-evidence subject)
                 :target-construct (:target-construct subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Hosted backend lowerings must declare host authority, nullish/null and exception translation, dynamic loading, async/replay, schemas, runtime providers, source maps, artifact manifests, and capability evidence."}
                extra)))

(defn hosted-lowering-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get hosted-lowering-override-diagnostics fail-kind)]
      (hosted-lowering-fail!
       id source-path
       {:stage (hosted-lowering-stage-for-diagnostic id)
        :backend (hosted-lowering-backend-for-diagnostic id)
        :artifact-id (str "hosted-lowering-" (name fail-kind))
        :host-symbol fail-kind
        :missing-evidence [fail-kind]
        :target-construct fail-kind}
       {:missing-fields [fail-kind]}))))

(defn hosted-lowering-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-diagnostic-stream
   :stage :hosted-backend-lowering
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage (hosted-lowering-stage-for-diagnostic id)
            :backend (hosted-lowering-backend-for-diagnostic id)
            :message-key (keyword "backend-hosted" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "hosted-backend-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :hosted-stage0
            :mir-op (case id
                      "B5-NULL" :host-null-boundary
                      "B6-GLOBAL" :host-global-access
                      "B4-IMPORT" :wasm-host-import
                      :host-call)
            :domain-anchor nil
            :host-symbol id
            :missing-evidence #{:capability :schema :source-map
                                :runtime-provider}
            :target-construct id
            :fallback-status :rejected
            :facts {:ambient-authority-policy :reject
                    :nullish-policy :checked-boundary
                    :host-exception-policy :translate}
            :remediation [{:kind :declare-host-boundary}
                          {:kind :preserve-capability-and-schema}
                          {:kind :translate-host-failure}]
            :redactions []
            :ordering-key [id :hosted-backend-lowering :hosted-stage0]})
         hosted-lowering-diagnostic-ids
         (range))
   :status :complete})

(defn hosted-lowering-artifact-manifest
  [backend kind target content input-id evidence-id]
  {:schema-version 1
   :kind kind
   :backend backend
   :profile :hosted
   :target target
   :content-hash (c4-artifact-id content)
   :inputs {:source input-id
            :mir input-id
            :backend-interface input-id}
   :evidence {:safety "safety-bundle:stage0"
              :proofs evidence-id
              :capabilities "capability-summary:stage0"
              :effects "effect-summary:stage0"
              :conformance "backend-conformance-pack:p07-t03"}
   :provenance {:compiler "gravity-stage0-clojure"
                :passes ["C14" "B1" "B4/B5/B6" "B13" "B14"]
                :dependencies "dependency-graph:stage0"}
   :reproducibility {:timestamp-policy :none
                     :nondeterminism []
                     :status :recorded}})

(defn hosted-lowering-validate!
  [source-path artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:hosted-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    (when-not (= :complete (get-in artifact
                                   [:backend-interface-artifact
                                    :capability-based-proof :status]))
      (hosted-lowering-fail! "B5-MANIFEST" source-path
                             (:backend-interface-artifact artifact)
                             {:missing-fields [:backend-interface-proof]}))
    (when-not (= #{:gravity.backend/wasm :gravity.backend/jvm
                   :gravity.backend/js-ts}
                 (set (map :backend
                           (:target-lowering-manifest artifact))))
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (:target-lowering-manifest artifact)
                             {:missing-fields [:hosted-backends]}))
    (when-not (= :complete (get-in artifact [:wasm-backend :status]))
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (:wasm-backend artifact)
                             {:missing-fields [:wasm-backend]}))
    (when-not (= :declared (get-in artifact
                                   [:wasm-backend
                                    :import-capability-manifest
                                    :status]))
      (hosted-lowering-fail! "B4-IMPORT" source-path
                             (get-in artifact
                                     [:wasm-backend
                                      :import-capability-manifest])
                             {:missing-fields [:wasm-import-capabilities]}))
    (when-not (= :complete (get-in artifact [:jvm-backend :status]))
      (hosted-lowering-fail! "B5-MANIFEST" source-path
                             (:jvm-backend artifact)
                             {:missing-fields [:jvm-backend]}))
    (when-not (= :checked (get-in artifact
                                  [:jvm-backend :nullability-map
                                   :status]))
      (hosted-lowering-fail! "B5-NULL" source-path
                             (get-in artifact
                                     [:jvm-backend :nullability-map])
                             {:missing-fields [:jvm-nullability-map]}))
    (when-not (= :complete (get-in artifact [:js-ts-backend :status]))
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (:js-ts-backend artifact)
                             {:missing-fields [:js-ts-backend]}))
    (when-not (= :declared (get-in artifact
                                   [:js-ts-backend
                                    :capability-manifest :status]))
      (hosted-lowering-fail! "B6-GLOBAL" source-path
                             (get-in artifact
                                     [:js-ts-backend
                                      :capability-manifest])
                             {:missing-fields [:js-ts-capabilities]}))
    (when-not (every? #(set/subset?
                        (set native-artifact-manifest-required-fields)
                        (set (keys %)))
                      manifests)
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (first manifests)
                             {:missing-fields [:artifact-manifest]}))
    (when-not (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (first manifests)
                             {:missing-fields [:content-hash]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report
                                     :status]))
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (:metadata-preservation-report artifact)
                             {:missing-fields [:metadata-preservation]}))
    (when-not (= :passed (get-in artifact
                                 [:backend-conformance-record :status]))
      (hosted-lowering-fail! "B4-MANIFEST" source-path
                             (:backend-conformance-record artifact)
                             {:missing-fields [:conformance]}))
    (when-not (= (set hosted-lowering-diagnostic-ids) diagnostics)
      (hosted-lowering-fail! "B6-MANIFEST" source-path
                             (:hosted-diagnostic-stream artifact)
                             {:missing-fields [:hosted-diagnostics]})))
  :complete)

(defn hosted-lowering-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:hosted-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:backend-interface-artifact
                           :capability-based-proof :status]))
     :wasm-lowering-complete?
     (= :complete (get-in artifact [:wasm-backend :status]))
     :wasm-host-authority-declared?
     (= :declared (get-in artifact
                          [:wasm-backend
                           :import-capability-manifest :status]))
     :jvm-lowering-complete?
     (= :complete (get-in artifact [:jvm-backend :status]))
     :jvm-null-exception-boundaries-checked?
     (and (= :checked (get-in artifact
                              [:jvm-backend :nullability-map :status]))
          (= :translated (get-in artifact
                                 [:jvm-backend :exception-translation-map
                                  :status])))
     :js-ts-lowering-complete?
     (= :complete (get-in artifact [:js-ts-backend :status]))
     :js-ts-host-boundaries-declared?
     (= :declared (get-in artifact
                          [:js-ts-backend :capability-manifest :status]))
     :artifact-emission-complete?
     (and (= 3 (count manifests))
          (every? #(set/subset?
                    (set native-artifact-manifest-required-fields)
                    (set (keys %)))
                  manifests)
          (every? #(re-find #"^sha256:" (:content-hash %)) manifests))
     :source-proof-capability-metadata-preserved?
     (= :preserved (get-in artifact
                           [:metadata-preservation-report :status]))
     :conformance-record-passed?
     (= :passed (get-in artifact
                        [:backend-conformance-record :status]))
     :diagnostics-covered?
     (= (set hosted-lowering-diagnostic-ids) diagnostics)
     :status :complete}))

(defn hosted-lowering-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (hosted-lowering-source-overrides module)
        _ (hosted-lowering-validate-source-overrides! source-path
                                                      source-overrides)
        interface-artifact (backend-interface-source-artifact source-path
                                                              source-text)
        input-id (:artifact-id interface-artifact)
        wasm-module "(module (func $gravity_entry (param i64) (result i64) local.get 0))"
        jvm-class "class gravity.stage0.Hosted { static long entry(long x) { return x; } }"
        js-module "export function gravityEntry(x) { return x; }\n"
        ts-declarations "export declare function gravityEntry(x: bigint): bigint;\n"
        wasm-manifest (hosted-lowering-artifact-manifest
                       :gravity.backend/wasm :wasm-component
                       :wasm32-component wasm-module input-id
                       "proof-map:wasm-stage0")
        jvm-manifest (hosted-lowering-artifact-manifest
                      :gravity.backend/jvm :jar :jvm-21
                      jvm-class input-id "proof-map:jvm-stage0")
        js-manifest (hosted-lowering-artifact-manifest
                     :gravity.backend/js-ts :javascript-module
                     :browser-esm js-module input-id
                     "proof-map:js-ts-stage0")
        diagnostic-stream (hosted-lowering-diagnostic-stream source-path
                                                             input-id)
        artifact-base
        {:kind :gravity/stage0-hosted-lowering-artifact
         :task "P07-T03"
         :document-set ["B4" "B5" "B6" "B13" "B14"]
         :governing-documents hosted-lowering-governing-documents
         :pass {:name :hosted-lowering
                :input :backend-interface-and-conformance-artifact
                :output :hosted-wasm-jvm-js-ts-lowering-artifact
                :requires [:verified-backend-interface :host-boundary-schema
                           :runtime-provider :capability-summary
                           :effect-summary :source-debug-map
                           :artifact-manifest]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :safety :proofs
                            :profile :target :artifact-provenance]
                :emits [:wasm-component :jvm-class-and-jar
                        :javascript-module :typescript-declarations
                        :host-boundary-manifests
                        :artifact-manifests :backend-conformance-record]
                :rejects hosted-lowering-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :backend-interface-artifact
         (select-keys interface-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :backend-interface-results])
         :backend-interface-artifact-kind (:kind interface-artifact)
         :backend-interface-artifact-hash input-id
         :target-lowering-manifest
         [{:backend :gravity.backend/wasm
           :target :wasm32-component
           :artifact-kinds [:wasm-module :component-contract
                            :canonical-abi :wit-bindings]
           :status :complete}
          {:backend :gravity.backend/jvm
           :target :jvm-21
           :artifact-kinds [:class-files :jar :interop-descriptor
                            :debug-map]
           :status :complete}
          {:backend :gravity.backend/js-ts
           :target :browser-esm
           :artifact-kinds [:javascript :typescript-declarations
                            :source-map :package-manifest]
           :status :complete}]
         :wasm-backend
         {:artifact :gravity/wasm-backend-manifest
          :backend :gravity.backend/wasm
          :target-feature-record {:kind :component
                                  :memory :wasm32
                                  :component-model :wasi-0.3
                                  :async-abi #{:async-func :stream :future}
                                  :features #{:bulk-memory}
                                  :status :pinned}
          :wasm-modules [{:path "gravity_stage0.wat"
                          :content wasm-module
                          :hash (:content-hash wasm-manifest)}]
          :component-contract-manifest
          {:packages ["gravity:stage0/hosted"]
           :interfaces ["gravity-host"]
           :worlds [{:name "gravity-stage0"
                     :imports [:clock/now]
                     :exports [:gravity/entry]
                     :capabilities #{:time/read}
                     :replay-policy :recorded}]
           :status :complete}
          :canonical-abi-manifest
          {:records [:entry-params]
           :resources [:host-clock]
           :streams []
           :futures []
           :status :complete}
          :import-capability-manifest
          {:imports [{:symbol :clock/now
                      :effect :time/read
                      :capability :time/read
                      :schema :Instant
                      :provider :host/clock
                      :replay :recorded}]
           :status :declared}
          :export-schema-manifest
          {:exports [{:symbol :gravity/entry
                      :schema :I64
                      :ownership :copy}]
           :status :complete}
          :host-boundary-schema-manifest
          {:schemas [:Instant :I64]
           :taint-policy :validated
           :status :complete}
          :async-abi-manifest
          {:async-funcs [:clock/now]
           :completion :recorded
           :cancellation :declared
           :backpressure :not-applicable
           :status :complete}
          :replay-nondeterminism-record
          {:events [:clock/now]
           :policy :record
           :status :complete}
          :status :complete}
         :jvm-backend
         {:artifact :gravity/jvm-backend-manifest
          :backend :gravity.backend/jvm
          :classfile-target-record {:classfile 65
                                    :runtime :jvm-21
                                    :module-system :named
                                    :status :pinned}
          :class-files [{:path "gravity/stage0/Hosted.class"
                         :logical-content jvm-class
                         :hash (:content-hash jvm-manifest)}]
          :jar-artifact {:path "gravity-stage0-hosted.jar"
                         :entries ["gravity/stage0/Hosted.class"]
                         :hash (:content-hash jvm-manifest)
                         :status :complete}
          :java-interop-descriptor
          {:symbols [{:class "gravity.stage0.Hosted"
                      :method "entry"
                      :descriptor "(J)J"
                      :effects #{}
                      :capabilities #{}
                      :exceptions []}]
           :status :complete}
          :nullability-map {:entries [{:symbol "entry"
                                       :params [:nonnull]
                                       :returns :nonnull}]
                            :status :checked}
          :exception-translation-map {:host-exceptions []
                                      :panic-mapping :gravity/panic
                                      :status :translated}
          :reflection-dynamic-use-manifest
          {:reflection []
           :method-handles []
           :classloading :denied
           :status :declared}
          :runtime-helper-manifest
          {:gc :jvm
           :linear-cleanup :deterministic
           :thread-provider :declared
           :status :complete}
          :native-image-configuration
          {:reflection-config []
           :resource-config []
           :status :consistent}
          :status :complete}
         :js-ts-backend
         {:artifact :gravity/js-ts-backend-manifest
          :backend :gravity.backend/js-ts
          :runtime-target-record {:runtime :browser
                                  :ecmascript :es2022
                                  :module-format :esm
                                  :source-map :external
                                  :status :pinned}
          :javascript-modules [{:path "gravity-stage0.mjs"
                                :content js-module
                                :hash (:content-hash js-manifest)}]
          :typescript-declarations [{:path "gravity-stage0.d.ts"
                                     :content ts-declarations
                                     :hash (c4-artifact-id
                                            ts-declarations)}]
          :source-map {:source-spans :preserved
                       :generated-origin-chain :preserved
                       :status :complete}
          :capability-manifest
          {:host-globals [{:symbol "globalThis"
                           :effects #{}
                           :capabilities #{}
                           :schema :opaque-host-global}]
           :package-imports []
           :status :declared}
          :package-dependency-manifest
          {:dependencies []
           :side-effects :none
           :status :complete}
          :async-effect-boundary-map
          {:promises []
           :timers []
           :callbacks []
           :replay-policy :recorded
           :status :complete}
          :nullish-exception-translation-map
          {:nullish-policy :option-or-opaque
           :exception-policy :gravity-error-or-panic
           :status :checked}
          :numeric-representation-manifest
          {:I64 :BigInt
           :F64 :Number
           :checked-boundaries true
           :status :complete}
          :ui-component-metadata
          {:enabled false
           :status :not-applicable}
          :status :complete}
         :artifact-manifests [wasm-manifest jvm-manifest js-manifest]
         :artifact-graph
         {:artifact :gravity/artifact-graph
          :nodes [{:id input-id :kind :backend-interface}
                  {:id (:content-hash wasm-manifest)
                   :kind :wasm-component}
                  {:id (:content-hash jvm-manifest) :kind :jar}
                  {:id (:content-hash js-manifest)
                   :kind :javascript-module}]
          :edges [{:from input-id :to (:content-hash wasm-manifest)
                   :pass :wasm-backend}
                  {:from input-id :to (:content-hash jvm-manifest)
                   :pass :jvm-backend}
                  {:from input-id :to (:content-hash js-manifest)
                   :pass :js-ts-backend}]
          :status :complete}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :schemas :safety :proofs :profile :target
                   :runtime :artifact-graph :conformance]}
         :backend-conformance-record
         {:artifact :gravity/backend-conformance-record
          :suite :p07-t03-hosted-lowering
          :status :passed
          :positive-lowering-results
          [{:backend :wasm :fixture :hosted-positive :status :passed}
           {:backend :jvm :fixture :hosted-positive :status :passed}
           {:backend :js-ts :fixture :hosted-positive :status :passed}]
          :negative-diagnostic-results
          (mapv (fn [id] {:diagnostic id :status :matched})
                hosted-lowering-diagnostic-ids)
          :differential-results
          [{:backend :wasm :comparison :artifact-shape-vs-mir
            :status :matched}
           {:backend :jvm :comparison :artifact-shape-vs-mir
            :status :matched}
           {:backend :js-ts :comparison :artifact-shape-vs-mir
            :status :matched}]
          :target-availability {:wasm-toolchain :not-required-for-stage0
                                :jvm-toolchain :not-required-for-stage0
                                :js-runtime :not-required-for-stage0}
          :evidence-pack "backend-conformance-pack:p07-t03"}
         :hosted-diagnostic-stream diagnostic-stream
         :hosted-lowering-results
         {:documents ["B4" "B5" "B6" "B13" "B14"]
          :task "P07-T03"
          :backend-interface-input-status :complete
          :wasm-backend-status :complete
          :jvm-backend-status :complete
          :js-ts-backend-status :complete
          :artifact-emission-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (hosted-lowering-validate! source-path artifact-base)
        capability-proof (hosted-lowering-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn hosted-lowering-file-artifact
  [path]
  (hosted-lowering-source-artifact path (slurp path)))

