(def specialized-lowering-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             specialized-lowering-diagnostic-ids)))

(defn specialized-lowering-backend-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B8-") :gravity.backend/gpu
    (str/starts-with? id "B9-") :gravity.backend/hdl
    (str/starts-with? id "B10-") :gravity.backend/workflow-graph
    (str/starts-with? id "B11-") :gravity.backend/query-relational
    :else :gravity.backend/mobile))

(defn specialized-lowering-stage-for-diagnostic
  [id]
  (cond
    (str/starts-with? id "B8-") :gpu-backend
    (str/starts-with? id "B9-") :hdl-backend
    (str/starts-with? id "B10-") :workflow-graph-backend
    (str/starts-with? id "B11-") :query-relational-backend
    :else :mobile-backend))

(defn specialized-lowering-diagnostic-message
  [id]
  (cond
    (str/starts-with? id "B8-") "GPU specialized lowering contract failed"
    (str/starts-with? id "B9-") "HDL specialized lowering contract failed"
    (str/starts-with? id "B10-") "workflow graph specialized lowering contract failed"
    (str/starts-with? id "B11-") "query/relational specialized lowering contract failed"
    :else "mobile specialized lowering contract failed"))

(defn specialized-lowering-source-overrides
  [module]
  (or (get-in module [:metadata :backend :specialized-lowering])
      (get-in module [:metadata :backend :specialized])
      {}))

(defn specialized-lowering-fail!
  [id source-path subject extra]
  (fail! id
         (specialized-lowering-diagnostic-message id)
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :specialized-backend-lowering
                 :stage (or (:stage subject)
                            (specialized-lowering-stage-for-diagnostic id))
                 :backend (or (:backend subject)
                              (specialized-lowering-backend-for-diagnostic id))
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :specialized-stage0)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :domain-lowering)
                 :domain-anchor (or (:domain-anchor subject) :domain)
                 :missing-evidence (:missing-evidence subject)
                 :target-construct (:target-construct subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Specialized backends must preserve domain anchors, schemas, effects, capabilities, proof records, source maps, provider/runtime policies, and conformance evidence instead of hiding target behavior in backend-specific artifacts."}
                extra)))

(defn specialized-lowering-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get specialized-lowering-override-diagnostics fail-kind)]
      (specialized-lowering-fail!
       id source-path
       {:stage (specialized-lowering-stage-for-diagnostic id)
        :backend (specialized-lowering-backend-for-diagnostic id)
        :artifact-id (str "specialized-lowering-" (name fail-kind))
        :missing-evidence [fail-kind]
        :target-construct fail-kind}
       {:missing-fields [fail-kind]}))))

(defn specialized-lowering-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-diagnostic-stream
   :stage :specialized-backend-lowering
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage (specialized-lowering-stage-for-diagnostic id)
            :backend (specialized-lowering-backend-for-diagnostic id)
            :message-key (keyword "backend-specialized" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "specialized-backend-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :specialized-stage0
            :mir-op :domain-lowering
            :domain-anchor (case (subs id 0 (.indexOf id "-"))
                             "B8" :gpu-kernel
                             "B9" :hardware-circuit
                             "B10" :workflow-graph
                             "B11" :relational-query
                             "B12" :mobile-app)
            :missing-evidence #{:schema :capability :proof :source-map
                                :conformance}
            :target-construct id
            :fallback-status :rejected
            :facts {:domain-anchor-required? true
                    :schema-required? true
                    :capability-required? true}
            :remediation [{:kind :provide-domain-anchor}
                          {:kind :preserve-schema-and-capability}
                          {:kind :emit-specialized-conformance-evidence}]
            :redactions []
            :ordering-key [id :specialized-backend-lowering
                           :specialized-stage0]})
         specialized-lowering-diagnostic-ids
         (range))
   :status :complete})

(defn specialized-lowering-artifact-manifest
  [backend kind target content input-id evidence-id]
  {:schema-version 1
   :kind kind
   :backend backend
   :profile :hosted
   :target target
   :content-hash (c4-artifact-id content)
   :inputs {:source input-id
            :mir input-id
            :backend-interface input-id}
   :evidence {:safety "safety-bundle:stage0"
              :proofs evidence-id
              :capabilities "capability-summary:stage0"
              :effects "effect-summary:stage0"
              :conformance "backend-conformance-pack:p07-t04"}
   :provenance {:compiler "gravity-stage0-clojure"
                :passes ["C14" "B1" "B8/B9/B10/B11/B12" "B13" "B14"]
                :dependencies "dependency-graph:stage0"}
   :reproducibility {:timestamp-policy :none
                     :nondeterminism []
                     :status :recorded}})

(defn specialized-lowering-validate!
  [source-path artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:specialized-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    (when-not (= :complete (get-in artifact
                                   [:backend-interface-artifact
                                    :capability-based-proof :status]))
      (specialized-lowering-fail!
       "B10-MANIFEST" source-path (:backend-interface-artifact artifact)
       {:missing-fields [:backend-interface-proof]}))
    (when-not (= #{:gravity.backend/gpu :gravity.backend/hdl
                   :gravity.backend/workflow-graph
                   :gravity.backend/query-relational
                   :gravity.backend/mobile}
                 (set (map :backend (:target-lowering-manifest artifact))))
      (specialized-lowering-fail!
       "B10-MANIFEST" source-path (:target-lowering-manifest artifact)
       {:missing-fields [:specialized-backends]}))
    (doseq [[path id] [[[:gpu-backend :status] "B8-MANIFEST"]
                       [[:hdl-backend :status] "B9-MANIFEST"]
                       [[:workflow-backend :status] "B10-MANIFEST"]
                       [[:query-backend :status] "B11-MANIFEST"]
                       [[:mobile-backend :status] "B12-MANIFEST"]]]
      (when-not (= :complete (get-in artifact path))
        (specialized-lowering-fail!
         id source-path artifact {:missing-fields path})))
    (when-not (= :declared (get-in artifact
                                   [:gpu-backend
                                    :host-device-boundary :status]))
      (specialized-lowering-fail!
       "B8-KERNEL" source-path (:gpu-backend artifact)
       {:missing-fields [:host-device-boundary]}))
    (when-not (= :complete (get-in artifact
                                   [:hdl-backend
                                    :clock-domain-report :status]))
      (specialized-lowering-fail!
       "B9-CLOCK" source-path (:hdl-backend artifact)
       {:missing-fields [:clock-domain-report]}))
    (when-not (= :complete (get-in artifact
                                   [:workflow-backend
                                    :replay-policy :status]))
      (specialized-lowering-fail!
       "B10-REPLAY" source-path (:workflow-backend artifact)
       {:missing-fields [:replay-policy]}))
    (when-not (= :parameterized (get-in artifact
                                        [:query-backend
                                         :prepared-binding-manifest
                                         :status]))
      (specialized-lowering-fail!
       "B11-PARAMETER" source-path (:query-backend artifact)
       {:missing-fields [:prepared-binding-manifest]}))
    (when-not (= :complete (get-in artifact
                                   [:mobile-backend
                                    :permission-manifest :status]))
      (specialized-lowering-fail!
       "B12-PERMISSION" source-path (:mobile-backend artifact)
       {:missing-fields [:permission-manifest]}))
    (when-not (every? #(set/subset?
                        (set native-artifact-manifest-required-fields)
                        (set (keys %)))
                      manifests)
      (specialized-lowering-fail!
       "B10-MANIFEST" source-path (first manifests)
       {:missing-fields [:artifact-manifest]}))
    (when-not (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
      (specialized-lowering-fail!
       "B11-MANIFEST" source-path (first manifests)
       {:missing-fields [:content-hash]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report :status]))
      (specialized-lowering-fail!
       "B12-MANIFEST" source-path (:metadata-preservation-report artifact)
       {:missing-fields [:metadata-preservation]}))
    (when-not (= :passed (get-in artifact
                                 [:backend-conformance-record :status]))
      (specialized-lowering-fail!
       "B10-MANIFEST" source-path (:backend-conformance-record artifact)
       {:missing-fields [:conformance]}))
    (when-not (= (set specialized-lowering-diagnostic-ids) diagnostics)
      (specialized-lowering-fail!
       "B10-MANIFEST" source-path (:specialized-diagnostic-stream artifact)
       {:missing-fields [:specialized-diagnostics]})))
  :complete)

(defn specialized-lowering-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:specialized-diagnostic-stream
                                       :diagnostics])))
        manifests (:artifact-manifests artifact)]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:backend-interface-artifact
                           :capability-based-proof :status]))
     :gpu-lowering-complete?
     (= :complete (get-in artifact [:gpu-backend :status]))
     :gpu-host-device-boundary-declared?
     (= :declared (get-in artifact
                          [:gpu-backend :host-device-boundary :status]))
     :hdl-lowering-complete?
     (= :complete (get-in artifact [:hdl-backend :status]))
     :hdl-clock-reset-timing-complete?
     (and (= :complete (get-in artifact
                               [:hdl-backend :clock-domain-report :status]))
          (= :complete (get-in artifact
                               [:hdl-backend :timing-constraint-file
                                :status])))
     :workflow-lowering-complete?
     (= :complete (get-in artifact [:workflow-backend :status]))
     :workflow-replay-policy-complete?
     (= :complete (get-in artifact
                          [:workflow-backend :replay-policy :status]))
     :query-lowering-complete?
     (= :complete (get-in artifact [:query-backend :status]))
     :query-parameters-taint-checked?
     (= :parameterized (get-in artifact
                               [:query-backend
                                :prepared-binding-manifest :status]))
     :mobile-lowering-complete?
     (= :complete (get-in artifact [:mobile-backend :status]))
     :mobile-permissions-lifecycle-checked?
     (and (= :complete (get-in artifact
                               [:mobile-backend :permission-manifest
                                :status]))
          (= :complete (get-in artifact
                               [:mobile-backend :lifecycle-threading-map
                                :status])))
     :artifact-emission-complete?
     (and (= 5 (count manifests))
          (every? #(set/subset?
                    (set native-artifact-manifest-required-fields)
                    (set (keys %)))
                  manifests)
          (every? #(re-find #"^sha256:" (:content-hash %)) manifests))
     :source-proof-capability-metadata-preserved?
     (= :preserved (get-in artifact
                           [:metadata-preservation-report :status]))
     :conformance-record-passed?
     (= :passed (get-in artifact
                        [:backend-conformance-record :status]))
     :diagnostics-covered?
     (= (set specialized-lowering-diagnostic-ids) diagnostics)
     :status :complete}))

(defn specialized-lowering-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (specialized-lowering-source-overrides module)
        _ (specialized-lowering-validate-source-overrides!
           source-path source-overrides)
        interface-artifact (backend-interface-source-artifact source-path
                                                              source-text)
        input-id (:artifact-id interface-artifact)
        gpu-module "spirv.module @gravity_stage0_kernel { gpu.kernel @entry }"
        hdl-module "module gravity_stage0(input logic clk, output logic done); assign done = clk; endmodule\n"
        workflow-graph "{:workflow :gravity-stage0 :steps [:start :call :done]}"
        sql-module "select $1::bigint as gravity_value"
        mobile-bundle "{:bundle-id \"org.gravity.stage0\" :platform :ios}"
        gpu-manifest (specialized-lowering-artifact-manifest
                      :gravity.backend/gpu :gpu-kernel-module
                      :spir-v gpu-module input-id "proof-map:gpu-stage0")
        hdl-manifest (specialized-lowering-artifact-manifest
                      :gravity.backend/hdl :systemverilog-module
                      :systemverilog hdl-module input-id
                      "proof-map:hdl-stage0")
        workflow-manifest (specialized-lowering-artifact-manifest
                           :gravity.backend/workflow-graph
                           :workflow-graph :durable-workflow
                           workflow-graph input-id
                           "proof-map:workflow-stage0")
        query-manifest (specialized-lowering-artifact-manifest
                        :gravity.backend/query-relational
                        :sql-statement :postgresql sql-module input-id
                        "proof-map:query-stage0")
        mobile-manifest (specialized-lowering-artifact-manifest
                         :gravity.backend/mobile :app-bundle :ios
                         mobile-bundle input-id "proof-map:mobile-stage0")
        diagnostic-stream (specialized-lowering-diagnostic-stream source-path
                                                                  input-id)
        artifact-base
        {:kind :gravity/stage0-specialized-lowering-artifact
         :task "P07-T04"
         :document-set ["B8" "B9" "B10" "B11" "B12" "B13" "B14"]
         :governing-documents specialized-lowering-governing-documents
         :pass {:name :specialized-lowering
                :input :backend-interface-and-conformance-artifact
                :output :specialized-gpu-hdl-workflow-query-mobile-artifact
                :requires [:verified-backend-interface :domain-anchor
                           :schema-bundle :runtime-provider
                           :capability-summary :effect-summary
                           :source-debug-map :artifact-manifest]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :schemas :safety
                            :proofs :profile :target :artifact-provenance]
                :emits [:gpu-kernel-module :hdl-module :workflow-graph
                        :sql-statement :mobile-bundle :artifact-manifests
                        :backend-conformance-record]
                :rejects specialized-lowering-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :backend-interface-artifact
         (select-keys interface-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :backend-interface-results])
         :backend-interface-artifact-kind (:kind interface-artifact)
         :backend-interface-artifact-hash input-id
         :target-lowering-manifest
         [{:backend :gravity.backend/gpu
           :target :spir-v
           :artifact-kinds [:kernel-module :device-binary-manifest
                            :host-stub :launch-descriptor]
           :status :complete}
          {:backend :gravity.backend/hdl
           :target :systemverilog
           :artifact-kinds [:hdl :testbench :timing-constraints
                            :interface-schema]
           :status :complete}
          {:backend :gravity.backend/workflow-graph
           :target :durable-workflow
           :artifact-kinds [:workflow-graph :event-log-schema
                            :replay-fixture :policy-graph]
           :status :complete}
          {:backend :gravity.backend/query-relational
           :target :postgresql
           :artifact-kinds [:sql :prepared-bindings :query-plan
                            :typed-result-adapter]
           :status :complete}
          {:backend :gravity.backend/mobile
           :target :ios
           :artifact-kinds [:app-bundle :platform-bindings
                            :permission-manifest :store-audit]
           :status :complete}]
         :gpu-backend
         {:artifact :gravity/gpu-backend-manifest
          :backend :gravity.backend/gpu
          :target {:api :spir-v
                   :device-class :gpu
                   :features #{:subgroups :fp16 :shared-memory}}
          :kernel-modules [{:path "gravity_stage0.spv.ir"
                            :content gpu-module
                            :hash (:content-hash gpu-manifest)}]
          :host-device-boundary
          {:kernel :gravity_stage0_kernel
           :arguments [{:name :input
                        :address-space :global
                        :layout :i64
                        :alignment 8
                        :lifetime :kernel}]
           :capability-grants #{:gpu/launch :memory/device}
           :status :declared}
          :launch-descriptor {:grid [1 1 1]
                              :workgroup [32 1 1]
                              :shared-memory-bytes 0
                              :status :complete}
          :device-memory-lifetime-report
          {:buffers [{:id :input
                      :ownership :linear
                      :transfer-state :host-to-device}]
           :status :complete}
          :transfer-graph {:edges [{:from :host :to :device :buffer :input}
                                   {:from :device :to :host :buffer :output}]
                           :implicit-transfers []
                           :status :complete}
          :synchronization-graph {:edges [{:before :copy-in
                                           :after :kernel-launch}
                                          {:before :kernel-launch
                                           :after :copy-out}]
                                  :status :complete}
          :math-certificate-bundle {:numeric-mode :strict
                                    :certificates ["MATH8-stage0"]
                                    :status :complete}
          :status :complete}
         :hdl-backend
         {:artifact :gravity/hdl-backend-manifest
          :backend :gravity.backend/hdl
          :target {:hdl :systemverilog
                   :synthesis-tool :stage0-provider}
          :hardware-ir-handoff-record {:domain-anchor :hardware-circuit
                                       :status :complete}
          :hdl-artifacts [{:path "gravity_stage0.sv"
                           :content hdl-module
                           :hash (:content-hash hdl-manifest)}]
          :interface-port-schema
          {:ports [{:name :clk :direction :input :width 1
                    :clock-domain :clk}
                   {:name :done :direction :output :width 1
                    :clock-domain :clk}]
           :status :complete}
          :clock-domain-report {:domains [{:id :clk
                                           :frequency-mhz 100
                                           :edge :rising}]
                                :status :complete}
          :reset-domain-report {:domains [{:id :rst
                                           :active :high
                                           :style :synchronous}]
                                :status :complete}
          :state-machine-graph {:states [:idle :done]
                                :transitions [[:idle :done]]
                                :status :complete}
          :timing-constraint-file {:format :sdc
                                   :constraints ["create_clock -period 10 clk"]
                                   :status :complete}
          :testbench {:path "gravity_stage0_tb.sv"
                      :simulation-trace-schema :cycle-trace
                      :status :complete}
          :status :complete}
         :workflow-backend
         {:artifact :gravity/workflow-backend-manifest
          :backend :gravity.backend/workflow-graph
          :workflow-graph-artifact {:content workflow-graph
                                    :hash (:content-hash workflow-manifest)
                                    :status :complete}
          :step-schema-bundle
          {:schemas [:workflow-input :step-output :durable-state]
           :migration-policy :versioned
           :status :complete}
          :event-log-schema {:events [:started :step-completed
                                      :human-reviewed]
                             :status :complete}
          :replay-policy {:nondeterminism [:clock :model-call]
                          :side-effects :event-log-guarded
                          :status :complete}
          :idempotency-key-map {:steps {:call-model :workflow-input-hash}
                                :status :complete}
          :retry-timeout-compensation-table
          {:steps {:call-model {:retry :exponential
                                :timeout-ms 30000
                                :compensation :record-failure}}
           :status :complete}
          :external-capability-manifest
          {:capabilities #{:network/request :ai/model-call
                           :ai/human-review}
           :providers [:stage0-model-provider]
           :status :complete}
          :human-review-policy-graph
          {:gates [{:step :approve-output
                    :capability :ai/human-review}]
           :status :complete}
          :audit-provenance-record {:source-map :preserved
                                    :policy-decisions :recorded
                                    :status :complete}
          :status :complete}
         :query-backend
         {:artifact :gravity/query-backend-manifest
          :backend :gravity.backend/query-relational
          :target {:dialect :postgresql
                   :version "stage0-declared"}
          :relational-ir-handoff-record {:domain-anchor :relational-query
                                         :status :complete}
          :sql-statement-artifacts
          [{:id :select-gravity-value
            :sql sql-module
            :hash (:content-hash query-manifest)}]
          :prepared-binding-manifest
          {:parameters [{:position 1
                         :gravity-type :I64
                         :database-type :bigint
                         :taint :validated}]
           :status :parameterized}
          :query-plan-metadata {:plan :index-neutral-select
                                :provider-specific-movement []
                                :status :complete}
          :typed-result-adapter {:columns [{:name :gravity_value
                                            :gravity-type :I64
                                            :nullability :nonnull}]
                                 :status :complete}
          :transaction-isolation-manifest {:effect :db/read
                                           :isolation :read-committed
                                           :capability :db/read
                                           :status :complete}
          :migration-artifact {:previous-schema :stage0-v1
                               :next-schema :stage0-v1
                               :data-loss :none
                               :status :complete}
          :capability-taint-report {:capabilities #{:db/read}
                                    :taint :validated
                                    :status :complete}
          :status :complete}
         :mobile-backend
         {:artifact :gravity/mobile-backend-manifest
          :backend :gravity.backend/mobile
          :platform-target-record {:platform :ios
                                   :os-range "stage0"
                                   :architecture :arm64
                                   :bundle-id "org.gravity.stage0"
                                   :status :complete}
          :application-bundle-artifact {:content mobile-bundle
                                        :hash (:content-hash mobile-manifest)
                                        :status :complete}
          :platform-binding-descriptors
          [{:symbol :network/request
            :framework :Foundation
            :permission :network
            :capability :network/request
            :thread-affinity :background}]
          :permission-manifest
          {:permissions [{:name :network
                          :capability :network/request
                          :runtime-request :declared
                          :denial-policy :return-error}]
           :status :complete}
          :resource-asset-manifest {:assets []
                                    :resources []
                                    :status :complete}
          :lifecycle-threading-map {:lifecycle [:launch :foreground
                                                :background]
                                    :ui-thread :main
                                    :callbacks :declared
                                    :status :complete}
          :ui-bridge-metadata {:framework :stage0-ui
                               :main-thread-required true
                               :status :complete}
          :local-storage-sync-schema-bundle
          {:schemas [:local-cache]
           :migration-policy :versioned
           :sync-policy :idempotent
           :status :complete}
          :store-audit-metadata {:permissions [:network]
                                 :background-modes []
                                 :status :complete}
          :device-simulator-conformance-report
          {:startup :recorded
           :permission-prompts :recorded
           :lifecycle :recorded
           :status :complete}
          :status :complete}
         :artifact-manifests [gpu-manifest hdl-manifest workflow-manifest
                              query-manifest mobile-manifest]
         :artifact-graph
         {:artifact :gravity/artifact-graph
          :nodes [{:id input-id :kind :backend-interface}
                  {:id (:content-hash gpu-manifest) :kind :gpu-kernel}
                  {:id (:content-hash hdl-manifest) :kind :hdl}
                  {:id (:content-hash workflow-manifest)
                   :kind :workflow-graph}
                  {:id (:content-hash query-manifest) :kind :sql}
                  {:id (:content-hash mobile-manifest)
                   :kind :mobile-bundle}]
          :edges [{:from input-id :to (:content-hash gpu-manifest)
                   :pass :gpu-backend}
                  {:from input-id :to (:content-hash hdl-manifest)
                   :pass :hdl-backend}
                  {:from input-id :to (:content-hash workflow-manifest)
                   :pass :workflow-backend}
                  {:from input-id :to (:content-hash query-manifest)
                   :pass :query-backend}
                  {:from input-id :to (:content-hash mobile-manifest)
                   :pass :mobile-backend}]
          :status :complete}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :schemas :safety :proofs :profile :target
                   :runtime :artifact-graph :conformance :policy]}
         :backend-conformance-record
         {:artifact :gravity/backend-conformance-record
          :suite :p07-t04-specialized-lowering
          :status :passed
          :positive-lowering-results
          [{:backend :gpu :fixture :specialized-positive :status :passed}
           {:backend :hdl :fixture :specialized-positive :status :passed}
           {:backend :workflow-graph :fixture :specialized-positive
            :status :passed}
           {:backend :query-relational :fixture :specialized-positive
            :status :passed}
           {:backend :mobile :fixture :specialized-positive
            :status :passed}]
          :negative-diagnostic-results
          (mapv (fn [id] {:diagnostic id :status :matched})
                specialized-lowering-diagnostic-ids)
          :differential-results
          [{:backend :gpu :comparison :artifact-shape-vs-domain-anchor
            :status :matched}
           {:backend :hdl :comparison :simulation-trace-schema
            :status :matched}
           {:backend :workflow-graph :comparison :replay-policy
            :status :matched}
           {:backend :query-relational :comparison :prepared-plan
            :status :matched}
           {:backend :mobile :comparison :simulator-record-shape
            :status :matched}]
          :target-availability {:gpu-toolchain :not-required-for-stage0
                                :hdl-synthesis :not-required-for-stage0
                                :workflow-runtime :not-required-for-stage0
                                :database :not-required-for-stage0
                                :mobile-simulator :not-required-for-stage0}
          :evidence-pack "backend-conformance-pack:p07-t04"}
         :specialized-diagnostic-stream diagnostic-stream
         :specialized-lowering-results
         {:documents ["B8" "B9" "B10" "B11" "B12" "B13" "B14"]
          :task "P07-T04"
          :backend-interface-input-status :complete
          :gpu-backend-status :complete
          :hdl-backend-status :complete
          :workflow-backend-status :complete
          :query-backend-status :complete
          :mobile-backend-status :complete
          :artifact-emission-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (specialized-lowering-validate! source-path artifact-base)
        capability-proof (specialized-lowering-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn specialized-lowering-file-artifact
  [path]
  (specialized-lowering-source-artifact path (slurp path)))

(def artifact-emission-governing-documents
  ["docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md"
   "docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"
   "docs/phase-06-compiler-architecture/093-c14-target-lowering-architecture.md"])

(def artifact-emission-diagnostic-ids
  ["B13-SCHEMA"
   "B13-HASH"
   "B13-PROVENANCE"
   "B13-SOURCEMAP"
   "B13-EVIDENCE"
   "B13-TARGET"
   "B13-CONFORMANCE"
   "B13-REPRODUCIBILITY"
   "B13-RELEASE"
   "B13-GRAPH"])

(def artifact-emission-diagnostic-messages
  {"B13-SCHEMA" "artifact manifest schema is missing or unsupported"
   "B13-HASH" "artifact content hash is missing, stale, or mismatched"
   "B13-PROVENANCE" "artifact source, compiler, generator, pass, or dependency provenance is incomplete"
   "B13-SOURCEMAP" "artifact source/debug or generated-origin map is incomplete"
   "B13-EVIDENCE" "artifact safety, proof, certificate, effect, capability, or unsafe-audit evidence is incomplete"
   "B13-TARGET" "artifact target, ABI, layout, runtime, or provider metadata is incomplete"
   "B13-CONFORMANCE" "artifact conformance evidence required by policy is missing"
   "B13-REPRODUCIBILITY" "artifact nondeterminism or environment inputs are not recorded"
   "B13-RELEASE" "release-grade artifact emission was attempted with development-only evidence"
   "B13-GRAPH" "artifact graph edges are invalid or incomplete"})

(def artifact-emission-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             artifact-emission-diagnostic-ids)))

(defn artifact-emission-source-overrides
  [module]
  (or (get-in module [:metadata :backend :artifact-emission])
      (get-in module [:metadata :backend :artifacts])
      {}))

(defn artifact-emission-fail!
  [id source-path subject extra]
  (fail! id
         (get artifact-emission-diagnostic-messages id
              "backend artifact emission validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :backend-artifact-emission
                 :stage (or (:stage subject) :artifact-emission)
                 :artifact-id (:artifact-id subject)
                 :artifact-kind (:artifact-kind subject)
                 :backend (or (:backend subject)
                              :gravity.backend/artifact-emission)
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :multi-target-stage0)
                 :missing-evidence (:missing-evidence subject)
                 :stale-field (:stale-field subject)
                 :release-grade? (:release-grade? subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit backend artifacts only with common manifests, content hashes, source/debug maps, compiler and dependency provenance, safety/proof/effect/capability evidence, target metadata, reproducibility records, conformance evidence, and explicit development-only release gates."}
                extra)))

(defn artifact-emission-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get artifact-emission-override-diagnostics fail-kind)]
      (artifact-emission-fail!
       id source-path
       {:artifact-id (str "artifact-emission-" (name fail-kind))
        :artifact-kind :gravity/artifact-manifest
        :missing-evidence [fail-kind]
        :stale-field fail-kind
        :release-grade? (= id "B13-RELEASE")}
       {:missing-fields [fail-kind]}))))

(defn artifact-emission-interface-manifest
  [interface-artifact]
  (let [manifest (first (:target-artifact-manifest interface-artifact))]
    {:schema-version 1
     :kind (:kind manifest)
     :backend (:backend manifest)
     :profile (:profile manifest)
     :target (:target manifest)
     :content-hash (:digest manifest)
     :inputs {:source (:source-input manifest)
              :mir (:source-input manifest)
              :backend-interface (:artifact-id interface-artifact)}
     :evidence {:safety (:safety-evidence manifest)
                :proofs (:proof-summary manifest)
                :capabilities (:capability-summary manifest)
                :effects "effect-summary:stage0"
                :conformance (:conformance manifest)
                :unsafe-audit (:unsafe-audit-ids manifest)}
     :provenance {:compiler (get-in manifest [:provenance :compiler])
                  :passes (get-in manifest [:provenance :pass-history])
                  :dependencies (first (:dependencies manifest))
                  :generator :backend-interface}
     :reproducibility {:timestamp-policy :none
                       :nondeterminism []
                       :status :recorded}}))

(defn artifact-emission-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-artifact-emission-diagnostic-stream
   :stage :artifact-emission
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :artifact-emission
            :backend :gravity.backend/artifact-emission
            :message-key (keyword "backend-artifact"
                                  (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "artifact-emission-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :multi-target-stage0
            :artifact-kind (case id
                             "B13-GRAPH" :gravity/artifact-graph
                             "B13-SOURCEMAP" :gravity/source-debug-map
                             "B13-RELEASE" :gravity/release-gate
                             :gravity/artifact-manifest)
            :missing-evidence #{:schema :content-hash :source-map
                                :compiler-provenance
                                :dependency-provenance :safety
                                :proofs :effects :capabilities
                                :runtime-provider :abi-layout
                                :reproducibility :conformance}
            :stale-field id
            :release-grade? (= id "B13-RELEASE")
            :fallback-status :rejected
            :facts {:common-manifest-required? true
                    :content-addressing-required? true
                    :release-blocking? true}
            :remediation [{:kind :rebuild-artifact-manifest}
                          {:kind :preserve-source-debug-map}
                          {:kind :attach-evidence-and-conformance-pack}
                          {:kind :block-release-grade-output}]
            :redactions []
            :ordering-key [id :artifact-emission :multi-target-stage0]})
         artifact-emission-diagnostic-ids
         (range))
   :status :complete})

(defn artifact-emission-validate!
  [source-path artifact]
  (let [manifests (:artifact-manifests artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:artifact-emission-diagnostic-stream
                                       :diagnostics])))
        input-proofs [[:backend-interface-artifact
                       :capability-based-proof :status]
                      [:native-lowering-artifact
                       :capability-based-proof :status]
                      [:hosted-lowering-artifact
                       :capability-based-proof :status]
                      [:specialized-lowering-artifact
                       :capability-based-proof :status]]]
    (doseq [path input-proofs]
      (when-not (= :complete (get-in artifact path))
        (artifact-emission-fail!
         "B13-EVIDENCE" source-path artifact
         {:missing-fields path})))
    (when-not (and (= 12 (count manifests))
                   (every? #(set/subset?
                             (set native-artifact-manifest-required-fields)
                             (set (keys %)))
                           manifests))
      (artifact-emission-fail!
       "B13-SCHEMA" source-path artifact
       {:missing-fields [:artifact-manifests]}))
    (when-not (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
      (artifact-emission-fail!
       "B13-HASH" source-path artifact
       {:missing-fields [:content-hash]}))
    (when-not (every? #(and (get-in % [:provenance :compiler])
                            (seq (get-in % [:provenance :passes]))
                            (get-in % [:provenance :dependencies]))
                      manifests)
      (artifact-emission-fail!
       "B13-PROVENANCE" source-path artifact
       {:missing-fields [:provenance]}))
    (when-not (= :preserved (get-in artifact
                                    [:source-debug-map-record :status]))
      (artifact-emission-fail!
       "B13-SOURCEMAP" source-path (:source-debug-map-record artifact)
       {:missing-fields [:source-debug-map]}))
    (when-not (= :complete (get-in artifact
                                   [:safety-proof-certificate-bundle
                                    :status]))
      (artifact-emission-fail!
       "B13-EVIDENCE" source-path (:safety-proof-certificate-bundle artifact)
       {:missing-fields [:safety-proof-certificate-bundle]}))
    (when-not (= :complete (get-in artifact
                                   [:target-runtime-abi-layout-summary
                                    :status]))
      (artifact-emission-fail!
       "B13-TARGET" source-path (:target-runtime-abi-layout-summary artifact)
       {:missing-fields [:target-runtime-abi-layout]}))
    (when-not (= :complete (get-in artifact
                                   [:conformance-evidence-reference
                                    :status]))
      (artifact-emission-fail!
       "B13-CONFORMANCE" source-path (:conformance-evidence-reference artifact)
       {:missing-fields [:conformance-evidence]}))
    (when-not (= :recorded (get-in artifact
                                   [:reproducibility-record :status]))
      (artifact-emission-fail!
       "B13-REPRODUCIBILITY" source-path (:reproducibility-record artifact)
       {:missing-fields [:reproducibility]}))
    (when-not (= :blocked-development-only
                 (get-in artifact [:release-gate-record
                                   :release-grade-artifact-status]))
      (artifact-emission-fail!
       "B13-RELEASE" source-path (:release-gate-record artifact)
       {:missing-fields [:release-gate]}))
    (when-not (= :complete (get-in artifact [:artifact-graph :status]))
      (artifact-emission-fail!
       "B13-GRAPH" source-path (:artifact-graph artifact)
       {:missing-fields [:artifact-graph]}))
    (when-not (= (set artifact-emission-diagnostic-ids) diagnostics)
      (artifact-emission-fail!
       "B13-SCHEMA" source-path (:artifact-emission-diagnostic-stream artifact)
       {:missing-fields [:artifact-emission-diagnostics]})))
  :complete)

(defn artifact-emission-capability-proof
  [artifact]
  (let [manifests (:artifact-manifests artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:artifact-emission-diagnostic-stream
                                       :diagnostics])))]
    {:backend-inputs-verified?
     (every? #(= :complete %)
             [(get-in artifact [:backend-interface-artifact
                                :capability-based-proof :status])
              (get-in artifact [:native-lowering-artifact
                                :capability-based-proof :status])
              (get-in artifact [:hosted-lowering-artifact
                                :capability-based-proof :status])
              (get-in artifact [:specialized-lowering-artifact
                                :capability-based-proof :status])])
     :common-manifest-schema-complete?
     (and (= 12 (count manifests))
          (every? #(set/subset?
                    (set native-artifact-manifest-required-fields)
                    (set (keys %)))
                  manifests))
     :content-hashes-complete?
     (every? #(re-find #"^sha256:" (:content-hash %)) manifests)
     :provenance-complete?
     (every? #(and (get-in % [:provenance :compiler])
                   (seq (get-in % [:provenance :passes]))
                   (get-in % [:provenance :dependencies]))
             manifests)
     :source-debug-map-preserved?
     (= :preserved (get-in artifact [:source-debug-map-record :status]))
     :evidence-bundle-complete?
     (= :complete (get-in artifact
                          [:safety-proof-certificate-bundle :status]))
     :effect-capability-summary-complete?
     (= :complete (get-in artifact
                          [:effect-capability-summary :status]))
     :target-runtime-abi-metadata-complete?
     (= :complete (get-in artifact
                          [:target-runtime-abi-layout-summary :status]))
     :reproducibility-recorded?
     (= :recorded (get-in artifact [:reproducibility-record :status]))
     :development-release-gate-blocked?
     (= :blocked-development-only
        (get-in artifact [:release-gate-record
                          :release-grade-artifact-status]))
     :artifact-graph-complete?
     (= :complete (get-in artifact [:artifact-graph :status]))
     :conformance-evidence-complete?
     (= :complete (get-in artifact
                          [:conformance-evidence-reference :status]))
     :diagnostics-covered?
     (= (set artifact-emission-diagnostic-ids) diagnostics)
     :status :complete}))

(defn artifact-emission-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (artifact-emission-source-overrides module)
        _ (artifact-emission-validate-source-overrides! source-path
                                                        source-overrides)
        interface-artifact (backend-interface-source-artifact source-path
                                                              source-text)
        native-artifact (native-lowering-source-artifact source-path
                                                         source-text)
        hosted-artifact (hosted-lowering-source-artifact source-path
                                                         source-text)
        specialized-artifact (specialized-lowering-source-artifact
                              source-path source-text)
        input-id (:artifact-id specialized-artifact)
        interface-manifest (artifact-emission-interface-manifest
                            interface-artifact)
        manifests (vec (concat [interface-manifest]
                               (:artifact-manifests native-artifact)
                               (:artifact-manifests hosted-artifact)
                               (:artifact-manifests specialized-artifact)))
        manifest-hashes (mapv :content-hash manifests)
        graph-nodes (vec (concat
                          [{:id (:artifact-id interface-artifact)
                            :kind (:kind interface-artifact)}
                           {:id (:artifact-id native-artifact)
                            :kind (:kind native-artifact)}
                           {:id (:artifact-id hosted-artifact)
                            :kind (:kind hosted-artifact)}
                           {:id (:artifact-id specialized-artifact)
                            :kind (:kind specialized-artifact)}]
                          (mapv (fn [manifest]
                                  {:id (:content-hash manifest)
                                   :kind (:kind manifest)
                                   :backend (:backend manifest)})
                                manifests)))
        diagnostic-stream (artifact-emission-diagnostic-stream source-path
                                                               input-id)
        artifact-base
        {:kind :gravity/stage0-artifact-emission-artifact
         :task "P07-T05"
         :document-set ["B13" "B14"]
         :governing-documents artifact-emission-governing-documents
         :pass {:name :artifact-emission
                :input :backend-interface-native-hosted-specialized-artifacts
                :output :backend-artifact-provenance-graph
                :requires [:backend-interface-artifact
                           :native-lowering-artifact
                           :hosted-lowering-artifact
                           :specialized-lowering-artifact
                           :common-manifest-schema :content-hashes
                           :source-debug-map :compiler-provenance
                           :dependency-provenance :safety-proof-evidence
                           :effect-capability-summary :runtime-provider
                           :target-abi-layout :reproducibility
                           :conformance-evidence]
                :preserves [:source-spans :generated-origin-chain :types
                            :effects :capabilities :safety :proofs
                            :unsafe-audit-ids :profile :target :runtime
                            :dependencies :diagnostics]
                :emits [:artifact-manifests :artifact-graph
                        :content-hash-records :source-debug-map-record
                        :compiler-provenance-record
                        :dependency-provenance-record
                        :safety-proof-certificate-bundle
                        :effect-capability-summary
                        :runtime-provider-summary
                        :target-runtime-abi-layout-summary
                        :reproducibility-record
                        :conformance-evidence-reference
                        :release-gate-record
                        :artifact-emission-diagnostic-stream]
                :rejects artifact-emission-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :backend-interface-artifact
         (select-keys interface-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :backend-interface-results])
         :native-lowering-artifact
         (select-keys native-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :native-lowering-results])
         :hosted-lowering-artifact
         (select-keys hosted-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :hosted-lowering-results])
         :specialized-lowering-artifact
         (select-keys specialized-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :specialized-lowering-results])
         :artifact-manifests manifests
         :content-hash-records
         (mapv (fn [manifest]
                 {:artifact :gravity/content-hash-record
                  :artifact-kind (:kind manifest)
                  :backend (:backend manifest)
                  :content-hash (:content-hash manifest)
                  :manifest-digest (c4-artifact-id manifest)
                  :status :complete})
               manifests)
         :artifact-graph
         {:artifact :gravity/artifact-graph
          :root input-id
          :nodes graph-nodes
          :edges (vec (concat
                       [{:from (:artifact-id interface-artifact)
                         :to (:artifact-id native-artifact)
                         :pass :native-lowering}
                        {:from (:artifact-id interface-artifact)
                         :to (:artifact-id hosted-artifact)
                         :pass :hosted-lowering}
                        {:from (:artifact-id interface-artifact)
                         :to (:artifact-id specialized-artifact)
                         :pass :specialized-lowering}]
                       (mapv (fn [manifest]
                               {:from (:artifact-id interface-artifact)
                                :to (:content-hash manifest)
                                :pass :artifact-emission
                                :backend (:backend manifest)})
                             manifests)))
          :invalidation-rules [:source-change :compiler-change
                               :pass-change :target-change
                               :dependency-change :evidence-change]
          :status :complete}
         :source-debug-map-record
         {:artifact :gravity/source-debug-map
          :source-path source-path
          :source-unit (:module module)
          :locations [(str source-path ":read")
                      (str source-path ":macro-expansion")
                      (str source-path ":core")
                      (str source-path ":mir")
                      (str source-path ":backend-emission")]
          :status :preserved
          :phases [:read :macro-expansion :core :checked-core :mir
                   :domain-ir :optimization :lowering :backend-emission]
          :source-spans :preserved
          :generated-origin-chain :preserved
          :artifact-hashes manifest-hashes}
         :compiler-provenance-record
         {:artifact :gravity/compiler-provenance-record
          :compiler "gravity-stage0-clojure"
          :compiler-build-id (c4-artifact-id
                              {:compiler "gravity-stage0-clojure"
                               :task "P07-T05"})
          :pass-pipeline ["C18" "B1" "B2/B3/B7" "B4/B5/B6"
                          "B8/B9/B10/B11/B12" "B13" "B14"]
          :generator :artifact-emission
          :status :complete}
         :dependency-provenance-record
         {:artifact :gravity/dependency-provenance-record
          :dependencies ["dependency-graph:stage0"]
          :runtime-providers ["runtime-provider:clojure-jvm-stage0"
                              "runtime-provider:stage0-gpu"
                              "runtime-provider:stage0-mobile"]
          :target-toolchains {:c :not-required-for-stage0
                              :llvm :not-required-for-stage0
                              :mlir :not-required-for-stage0
                              :wasm :not-required-for-stage0
                              :jvm :not-required-for-stage0
                              :js-ts :not-required-for-stage0
                              :gpu :not-required-for-stage0
                              :hdl :not-required-for-stage0
                              :workflow :not-required-for-stage0
                              :query :not-required-for-stage0
                              :mobile :not-required-for-stage0}
          :status :complete}
         :safety-proof-certificate-bundle
         {:artifact :gravity/safety-proof-certificate-bundle
          :safety "safety-bundle:stage0"
          :proofs ["proof-table:stage0" "proof-map:c-stage0"
                   "proof-map:llvm-stage0" "proof-map:mlir-stage0"
                   "proof-map:wasm-stage0" "proof-map:jvm-stage0"
                   "proof-map:js-stage0" "proof-map:gpu-stage0"
                   "proof-map:hdl-stage0" "proof-map:workflow-stage0"
                   "proof-map:query-stage0" "proof-map:mobile-stage0"]
          :certificates ["cert/c18-safety-check-elision"]
          :unsafe-audit-records []
          :status :complete}
         :effect-capability-summary
         {:artifact :gravity/effect-capability-summary
          :effects (:effects module)
          :capabilities (:capabilities module)
          :manifest-count (count manifests)
          :status :complete}
         :runtime-provider-summary
         {:artifact :gravity/runtime-provider-summary
          :providers [:clojure-jvm-stage0 :stage0-native
                      :stage0-hosted :stage0-specialized]
          :hidden-dependencies []
          :status :complete}
         :target-runtime-abi-layout-summary
         {:artifact :gravity/target-runtime-abi-layout-summary
          :targets (set (map :target manifests))
          :backends (set (map :backend manifests))
          :abi-layout-records [:jvm-stage0 :native-stage0
                               :wasm-component-stage0
                               :gpu-host-device-stage0
                               :hdl-port-schema-stage0
                               :query-result-stage0
                               :mobile-platform-stage0]
          :runtime-providers [:clojure-jvm-stage0
                              :stage0-provider-records]
          :status :complete}
         :reproducibility-record
         {:artifact :gravity/reproducibility-record
          :hashes manifest-hashes
          :timestamp-policy :none
          :environment-inputs ["clojure-stage0" "source-text"]
          :nondeterminism []
          :development-build? true
          :status :recorded}
         :conformance-evidence-reference
         {:artifact :gravity/conformance-evidence-reference
          :packs ["backend-conformance-pack:p07-t01"
                  "backend-conformance-pack:p07-t02"
                  "backend-conformance-pack:p07-t03"
                  "backend-conformance-pack:p07-t04"]
          :manifest-validation :passed
          :metadata-preservation :passed
          :status :complete}
         :release-gate-record
         {:artifact :gravity/artifact-release-gate
          :release-grade-artifact-status :blocked-development-only
          :reason :stage0-development-evidence
          :blocked-downstream [:signing :packaging :deployment
                               :release-governance]
          :diagnostic-on-release-attempt "B13-RELEASE"
          :status :complete}
         :artifact-emission-diagnostic-stream diagnostic-stream
         :artifact-emission-results
         {:documents ["B13" "B14"]
          :task "P07-T05"
          :required-diagnostic-ids artifact-emission-diagnostic-ids
          :backend-input-status :complete
          :manifest-schema-status :complete
          :content-hash-status :complete
          :provenance-status :complete
          :source-map-status :complete
          :evidence-status :complete
          :target-runtime-abi-status :complete
          :reproducibility-status :complete
          :release-gate-status :complete
          :artifact-graph-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (artifact-emission-validate! source-path artifact-base)
        capability-proof (artifact-emission-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn artifact-emission-file-artifact
  [path]
  (artifact-emission-source-artifact path (slurp path)))

(def backend-test-matrix-governing-documents
  ["docs/phase-07-backend-architecture/111-b14-backend-conformance-test-plan.md"
   "docs/phase-07-backend-architecture/110-b13-artifact-emission-specification.md"
   "docs/phase-06-compiler-architecture/093-c14-target-lowering-architecture.md"])

(def backend-test-matrix-diagnostic-ids
  ["B14-COVERAGE"
   "B14-TARGET"
   "B14-POSITIVE"
   "B14-NEGATIVE"
   "B14-DIFFERENTIAL"
   "B14-METADATA"
   "B14-ARTIFACT"
   "B14-NONDETERMINISM"
   "B14-SKIP"
   "B14-EVIDENCE"])

(def backend-test-matrix-diagnostic-messages
  {"B14-COVERAGE" "backend conformance fixture coverage is incomplete"
   "B14-TARGET" "backend target is unavailable without an availability record"
   "B14-POSITIVE" "valid backend fixture failed lowering or execution"
   "B14-NEGATIVE" "invalid backend fixture compiled or produced the wrong diagnostic"
   "B14-DIFFERENTIAL" "backend semantic comparison or replay result mismatched"
   "B14-METADATA" "backend source, proof, safety, effect, capability, or audit metadata was lost"
   "B14-ARTIFACT" "backend or common artifact manifest validation failed"
   "B14-NONDETERMINISM" "backend conformance test used unrecorded nondeterminism"
   "B14-SKIP" "backend conformance skip or exclusion is unsupported"
   "B14-EVIDENCE" "backend conformance evidence pack is incomplete"})

(def backend-test-matrix-targets
  [:c :llvm :wasm :jvm :js-ts :mlir :gpu :hdl
   :workflow-graph :query-relational :mobile])

(def backend-test-matrix-fixture-families
  [:pure-values :arithmetic :numeric-modes :records :structs :tuples
   :tagged-unions :closures :calls :pattern-matching :loops
   :runtime-checks :allocation :regions :linear-resources
   :ownership-aliasing :ffi-host-interop :atomics-synchronization
   :source-maps :efir-domain :gpu-kernels :hardware-circuits
   :workflow-graphs :relational-queries :mobile-ui-boundaries
   :artifact-manifests :provenance-graphs])

(def backend-test-matrix-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             backend-test-matrix-diagnostic-ids)))

(defn backend-test-matrix-source-overrides
  [module]
  (or (get-in module [:metadata :backend :test-matrix])
      (get-in module [:metadata :backend :conformance-matrix])
      {}))

(defn backend-test-matrix-fail!
  [id source-path subject extra]
  (fail! id
         (get backend-test-matrix-diagnostic-messages id
              "backend conformance matrix validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :backend-test-matrix
                 :stage (or (:stage subject) :backend-test-matrix)
                 :backend (:backend subject)
                 :profile (or (:profile subject) :hosted)
                 :target (:target subject)
                 :fixture-id (:fixture-id subject)
                 :expected-diagnostic (:expected-diagnostic subject)
                 :actual-diagnostic (:actual-diagnostic subject)
                 :missing-metadata (:missing-metadata subject)
                 :artifact-id (:artifact-id subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Run backend conformance through the shared fixture matrix with target availability records, positive and negative diagnostic checks, semantic comparisons or replay records, metadata preservation, artifact-manifest validation, nondeterminism records, and evidence packs."}
                extra)))

(defn backend-test-matrix-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get backend-test-matrix-override-diagnostics fail-kind)]
      (backend-test-matrix-fail!
       id source-path
       {:stage :backend-test-matrix
        :backend :gravity.backend/conformance
        :target :multi-target-stage0
        :fixture-id (str "backend-matrix-" (name fail-kind))
        :expected-diagnostic id
        :actual-diagnostic :missing
        :missing-metadata [fail-kind]
        :artifact-id (str "backend-test-matrix-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn backend-test-matrix-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/backend-conformance-diagnostic-stream
   :stage :backend-test-matrix
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :backend-test-matrix
            :backend :gravity.backend/conformance
            :message-key (keyword "backend-conformance"
                                  (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "backend-test-matrix-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :multi-target-stage0
            :fixture-id (str "p07-t06-" (str/lower-case id))
            :expected-diagnostic id
            :actual-diagnostic :missing
            :missing-metadata #{:coverage :target-availability
                                :positive-result :negative-result
                                :differential-result :metadata
                                :artifact-manifest :nondeterminism
                                :skip-record :evidence-pack}
            :facts {:exact-diagnostic-required? true
                    :metadata-preservation-required? true
                    :artifact-validation-required? true}
            :remediation [{:kind :add-fixture-family}
                          {:kind :record-target-availability}
                          {:kind :assert-exact-diagnostic}
                          {:kind :attach-conformance-evidence-pack}]
            :redactions []
            :ordering-key [id :backend-test-matrix :multi-target-stage0]})
         backend-test-matrix-diagnostic-ids
         (range))
   :status :complete})

(defn backend-test-matrix-validate!
  [source-path artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:backend-test-diagnostic-stream
                                       :diagnostics])))
        positive (:positive-lowering-results artifact)
        negative (:negative-diagnostic-results artifact)]
    (when-not (= :complete (get-in artifact
                                   [:artifact-emission-artifact
                                    :capability-based-proof :status]))
      (backend-test-matrix-fail!
       "B14-EVIDENCE" source-path (:artifact-emission-artifact artifact)
       {:missing-fields [:artifact-emission-proof]}))
    (when-not (= (set backend-test-matrix-targets)
                 (:targets (:backend-conformance-suite-manifest artifact)))
      (backend-test-matrix-fail!
       "B14-COVERAGE" source-path
       (:backend-conformance-suite-manifest artifact)
       {:missing-fields [:targets]}))
    (when-not (= (set backend-test-matrix-fixture-families)
                 (set (map :family (:fixture-matrix artifact))))
      (backend-test-matrix-fail!
       "B14-COVERAGE" source-path (:fixture-matrix artifact)
       {:missing-fields [:fixture-families]}))
    (when-not (= :complete (get-in artifact
                                   [:target-availability-matrix :status]))
      (backend-test-matrix-fail!
       "B14-TARGET" source-path (:target-availability-matrix artifact)
       {:missing-fields [:target-availability]}))
    (when-not (and (= (count backend-test-matrix-targets)
                      (count positive))
                   (every? #(= :passed (:status %)) positive))
      (backend-test-matrix-fail!
       "B14-POSITIVE" source-path (first positive)
       {:missing-fields [:positive-lowering-results]}))
    (when-not (= (set backend-test-matrix-diagnostic-ids)
                 (set (map :diagnostic negative)))
      (backend-test-matrix-fail!
       "B14-NEGATIVE" source-path (first negative)
       {:missing-fields [:negative-diagnostic-results]}))
    (when-not (= :passed (get-in artifact
                                 [:differential-semantic-comparison-results
                                  :status]))
      (backend-test-matrix-fail!
       "B14-DIFFERENTIAL" source-path
       (:differential-semantic-comparison-results artifact)
       {:missing-fields [:differential-semantic-comparison]}))
    (when-not (= :preserved (get-in artifact
                                    [:metadata-preservation-report :status]))
      (backend-test-matrix-fail!
       "B14-METADATA" source-path (:metadata-preservation-report artifact)
       {:missing-fields [:metadata-preservation]}))
    (when-not (= :valid (get-in artifact
                                [:artifact-manifest-validation-report
                                 :status]))
      (backend-test-matrix-fail!
       "B14-ARTIFACT" source-path
       (:artifact-manifest-validation-report artifact)
       {:missing-fields [:artifact-manifest-validation]}))
    (when-not (= :recorded (get-in artifact
                                   [:nondeterminism-replay-record
                                    :status]))
      (backend-test-matrix-fail!
       "B14-NONDETERMINISM" source-path
       (:nondeterminism-replay-record artifact)
       {:missing-fields [:nondeterminism-replay]}))
    (when-not (empty? (get-in artifact
                              [:target-availability-matrix
                               :unsupported-skips]))
      (backend-test-matrix-fail!
       "B14-SKIP" source-path (:target-availability-matrix artifact)
       {:missing-fields [:unsupported-skips]}))
    (when-not (= :complete (get-in artifact
                                   [:conformance-evidence-pack :status]))
      (backend-test-matrix-fail!
       "B14-EVIDENCE" source-path (:conformance-evidence-pack artifact)
       {:missing-fields [:conformance-evidence-pack]}))
    (when-not (= (set backend-test-matrix-diagnostic-ids) diagnostics)
      (backend-test-matrix-fail!
       "B14-NEGATIVE" source-path (:backend-test-diagnostic-stream artifact)
       {:missing-fields [:backend-test-diagnostics]})))
  :complete)

(defn backend-test-matrix-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:backend-test-diagnostic-stream
                                       :diagnostics])))]
    {:artifact-emission-input-verified?
     (= :complete (get-in artifact
                          [:artifact-emission-artifact
                           :capability-based-proof :status]))
     :suite-manifest-complete?
     (= (set backend-test-matrix-targets)
        (:targets (:backend-conformance-suite-manifest artifact)))
     :fixture-matrix-complete?
     (= (set backend-test-matrix-fixture-families)
        (set (map :family (:fixture-matrix artifact))))
     :target-availability-recorded?
     (= :complete (get-in artifact [:target-availability-matrix :status]))
     :positive-lowering-results-passed?
     (every? #(= :passed (:status %))
             (:positive-lowering-results artifact))
     :negative-diagnostic-results-exact?
     (= (set backend-test-matrix-diagnostic-ids)
        (set (map :diagnostic (:negative-diagnostic-results artifact))))
     :differential-semantic-comparisons-passed?
     (= :passed (get-in artifact
                        [:differential-semantic-comparison-results
                         :status]))
     :metadata-preserved?
     (= :preserved (get-in artifact
                           [:metadata-preservation-report :status]))
     :artifact-manifests-valid?
     (= :valid (get-in artifact
                       [:artifact-manifest-validation-report :status]))
     :nondeterminism-recorded?
     (= :recorded (get-in artifact
                          [:nondeterminism-replay-record :status]))
     :unsupported-skips-rejected?
     (empty? (get-in artifact
                     [:target-availability-matrix :unsupported-skips]))
     :risk-coverage-complete?
     (= :complete (get-in artifact
                          [:backend-risk-coverage-report :status]))
     :conformance-evidence-pack-complete?
     (= :complete (get-in artifact
                          [:conformance-evidence-pack :status]))
     :diagnostics-covered?
     (= (set backend-test-matrix-diagnostic-ids) diagnostics)
     :status :complete}))

(defn backend-test-matrix-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (backend-test-matrix-source-overrides module)
        _ (backend-test-matrix-validate-source-overrides!
           source-path source-overrides)
        artifact-emission-artifact (artifact-emission-source-artifact
                                    source-path source-text)
        input-id (:artifact-id artifact-emission-artifact)
        diagnostic-stream (backend-test-matrix-diagnostic-stream source-path
                                                                 input-id)
        positive-results
        (mapv (fn [target]
                {:backend target
                 :fixture (keyword "positive" (name target))
                 :lowering-artifact input-id
                 :shared-manifest-validated? true
                 :external-execution :not-required-for-stage0
                 :status :passed})
              backend-test-matrix-targets)
        artifact-base
        {:kind :gravity/stage0-backend-test-matrix-artifact
         :task "P07-T06"
         :document-set ["B14"]
         :governing-documents backend-test-matrix-governing-documents
         :pass {:name :backend-test-matrix
                :input :backend-artifact-emission-and-provenance-artifact
                :output :backend-conformance-suite-and-evidence-pack
                :requires [:artifact-emission-artifact :fixture-matrix
                           :target-availability :positive-lowering-results
                           :negative-diagnostic-results
                           :differential-or-semantic-comparison
                           :metadata-preservation
                           :artifact-manifest-validation
                           :nondeterminism-replay
                           :risk-coverage-report
                           :conformance-evidence-pack]
                :preserves [:source-spans :generated-origin-chain :types
                            :effects :capabilities :safety :proofs
                            :unsafe-audit-ids :profile :target
                            :artifact-manifests :diagnostics]
                :emits [:backend-conformance-suite-manifest
                        :fixture-matrix :target-availability-matrix
                        :positive-lowering-results
                        :negative-diagnostic-results
                        :differential-semantic-comparison-results
                        :metadata-preservation-report
                        :artifact-manifest-validation-report
                        :nondeterminism-replay-record
                        :backend-risk-coverage-report
                        :conformance-evidence-pack
                        :backend-test-diagnostic-stream]
                :rejects backend-test-matrix-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :artifact-emission-artifact
         (select-keys artifact-emission-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :artifact-emission-results])
         :backend-conformance-suite-manifest
         {:artifact :gravity/backend-conformance-suite
          :targets (set backend-test-matrix-targets)
          :checks #{:lowering :expected-rejection
                    :differential-execution :semantic-comparison
                    :metadata-preservation :artifact-manifest
                    :diagnostic-id :nondeterminism-replay}
          :inputs #{:canonical-mir :domain-ir :profile-negative
                    :safety-negative :artifact-emission}
          :rejects #{:execution-only-claim :missing-negative-fixtures
                     :metadata-loss :unreplayable-nondeterminism
                     :unsupported-skip}
          :status :complete}
         :fixture-matrix
         (mapv (fn [family]
                 {:family family
                  :fixtures [(keyword "fixture" (name family))]
                  :expected-artifacts [:artifact-manifest
                                       :source-map
                                       :proof-reference
                                       :capability-effect-summary
                                       :diagnostic-record]
                  :status :covered})
               backend-test-matrix-fixture-families)
         :target-availability-matrix
         {:artifact :gravity/backend-target-availability-matrix
          :targets
          (mapv (fn [target]
                  {:target target
                   :available-for-stage0-shape-validation? true
                   :external-runtime-required? false
                   :external-execution :not-required-for-stage0
                   :shared-manifest-tests :run
                   :negative-diagnostic-tests :run
                   :skip-status :none})
                backend-test-matrix-targets)
          :unsupported-skips []
          :status :complete}
         :positive-lowering-results positive-results
         :negative-diagnostic-results
         (mapv (fn [id]
                 {:diagnostic id
                  :fixture (str "backend-matrix-" (str/lower-case id)
                                ".gravity")
                  :expected id
                  :actual id
                  :status :matched})
               backend-test-matrix-diagnostic-ids)
         :differential-semantic-comparison-results
         {:artifact :gravity/backend-semantic-comparison-results
          :status :passed
          :method :artifact-shape-and-reference-semantics
          :comparisons
          (mapv (fn [target]
                  {:backend target
                   :reference :mir-or-domain-reference
                   :observed :stage0-artifact-shape
                   :execution :not-required-for-stage0
                   :status :matched})
                backend-test-matrix-targets)}
         :metadata-preservation-report
         {:artifact :gravity/backend-metadata-preservation-report
          :status :preserved
          :fields [:source-spans :generated-origin-chain :types :effects
                   :capabilities :safety :proofs :unsafe-audit-ids
                   :profile :target :runtime :artifact-manifests
                   :diagnostics]}
         :artifact-manifest-validation-report
         {:artifact :gravity/artifact-manifest-validation-report
          :status :valid
          :manifest-count (get-in artifact-emission-artifact
                                  [:artifact-emission-results
                                   :manifest-schema-status])
          :validated-artifacts (count (:artifact-manifests
                                       artifact-emission-artifact))}
         :nondeterminism-replay-record
         {:artifact :gravity/nondeterminism-replay-record
          :status :recorded
          :events [{:kind :clock :policy :record-or-replay}
                   {:kind :randomness :policy :record-or-replay}
                   {:kind :network :policy :record-or-replay}
                   {:kind :database :policy :record-or-replay}
                   {:kind :model-call :policy :record-or-replay}
                   {:kind :ai/human-review :policy :record-or-replay}]
          :unrecorded []}
         :backend-risk-coverage-report
         {:artifact :gravity/backend-risk-coverage-report
          :status :complete
          :covered-targets (set backend-test-matrix-targets)
          :covered-fixture-families (set backend-test-matrix-fixture-families)
          :known-gaps [{:scope :external-execution
                        :status :not-required-for-stage0
                        :release-impact :blocks-release-readiness}]}
         :conformance-evidence-pack
         {:artifact :gravity/backend-conformance-evidence-pack
          :id "backend-conformance-pack:p07-t06"
          :status :complete
          :includes [:suite-manifest :fixture-matrix
                     :target-availability :positive-results
                     :negative-results :semantic-comparisons
                     :metadata-preservation :artifact-validation
                     :nondeterminism-replay :risk-coverage
                     :diagnostics]
          :release-ready? false}
         :backend-test-diagnostic-stream diagnostic-stream
         :backend-test-matrix-results
         {:documents ["B14"]
          :task "P07-T06"
          :required-diagnostic-ids backend-test-matrix-diagnostic-ids
          :artifact-emission-input-status :complete
          :suite-manifest-status :complete
          :fixture-matrix-status :complete
          :target-availability-status :complete
          :positive-result-status :complete
          :negative-diagnostic-status :complete
          :differential-status :complete
          :metadata-status :complete
          :artifact-validation-status :complete
          :nondeterminism-status :complete
          :skip-status :complete
          :risk-coverage-status :complete
          :evidence-pack-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (backend-test-matrix-validate! source-path artifact-base)
        capability-proof (backend-test-matrix-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn backend-test-matrix-file-artifact
  [path]
  (backend-test-matrix-source-artifact path (slurp path)))

(def b1-document-governing-document
  "docs/phase-07-backend-architecture/098-b1-backend-interface-specification.md")

(def b1-document-diagnostic-ids
  ["B1-INPUT"
   "B1-PROFILE"
   "B1-TARGET"
   "B1-ABI"
   "B1-RUNTIME"
   "B1-PROOF"
   "B1-CAPABILITY"
   "B1-UNSUPPORTED"
   "B1-METADATA"])

(def b1-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b1-document-diagnostic-ids)))

(defn b1-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b1-document])
      (get-in module [:metadata :backend :interface])
      {}))

(defn b1-document-fail!
  [id source-path subject extra]
  (fail! id
         (get backend-interface-diagnostic-messages id
              "B1 backend interface document coverage validation failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b1-backend-interface-document
                 :stage (or (:stage subject) :b1-document-coverage)
                 :backend-id (:backend-id subject)
                 :input-artifact-id (:input-artifact-id subject)
                 :mir-op (:mir-op subject)
                 :domain-anchor (:domain-anchor subject)
                 :profile (:profile subject)
                 :target (:target subject)
                 :missing-evidence (:missing-evidence subject)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Satisfy the B1 backend interface contract with verified MIR or domain IR input, profile and target eligibility, ABI/runtime/provider metadata, proof-backed target assumptions, capability preservation, unsupported-operation diagnostics, artifact metadata, and conformance records."}
                extra)))

(defn b1-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b1-document-override-diagnostics fail-kind)]
      (b1-document-fail!
       id source-path
       {:stage :b1-document-coverage
        :backend-id :gravity.backend/interface-v1
        :input-artifact-id (str "b1-document-" (name fail-kind))
        :mir-op :checked-add
        :profile :hosted
        :target :jvm
        :missing-evidence [fail-kind]}
       {:missing-fields [fail-kind]}))))

(defn b1-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b1-backend-interface-diagnostic-stream
   :stage :b1-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b1-document-coverage
            :backend-id :gravity.backend/interface-v1
            :message-key (keyword "backend-interface" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b1-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B1-UNSUPPORTED" :target-specific-opcode
                      :checked-add)
            :domain-anchor (when (= id "B1-UNSUPPORTED") :unknown-domain)
            :profile :hosted
            :target :jvm
            :missing-evidence #{:verified-input :profile :target :abi
                                :runtime :effects :capabilities :safety
                                :proofs :source-map :dependencies}
            :fallback-status :rejected
            :facts {:verified-input-required? true
                    :safe-code-ub-forbidden? true
                    :metadata-required? true}
            :remediation [{:kind :verify-input-artifact}
                          {:kind :attach-interface-metadata}
                          {:kind :reject-unsupported-operation}]
            :redactions []
            :ordering-key [id :b1-document-coverage :jvm]})
         b1-document-diagnostic-ids
         (range))
   :status :complete})

(defn b1-document-validate!
  [source-path artifact]
  (let [interface (:backend-interface-artifact artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b1-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in interface
                                   [:capability-based-proof :status]))
      (b1-document-fail! "B1-INPUT" source-path interface
                         {:missing-fields [:backend-interface-proof]}))
    (when-not (= :complete (get-in artifact
                                   [:requirements-coverage
                                    :verified-input-status]))
      (b1-document-fail! "B1-INPUT" source-path (:requirements-coverage artifact)
                         {:missing-fields [:verified-input]}))
    (when-not (= :complete (get-in artifact
                                   [:requirements-coverage
                                    :eligibility-status]))
      (b1-document-fail! "B1-PROFILE" source-path
                         (:requirements-coverage artifact)
                         {:missing-fields [:eligibility]}))
    (when-not (= :accepted (get-in artifact
                                   [:requirements-coverage
                                    :proof-target-map-status]))
      (b1-document-fail! "B1-PROOF" source-path
                         (:requirements-coverage artifact)
                         {:missing-fields [:proof-to-target-metadata]}))
    (when-not (= :preserved (get-in artifact
                                    [:requirements-coverage
                                     :metadata-status]))
      (b1-document-fail! "B1-METADATA" source-path
                         (:requirements-coverage artifact)
                         {:missing-fields [:metadata]}))
    (when-not (= :passed (get-in artifact
                                 [:conformance-criteria-record :status]))
      (b1-document-fail! "B1-METADATA" source-path
                         (:conformance-criteria-record artifact)
                         {:missing-fields [:conformance]}))
    (when-not (= (set b1-document-diagnostic-ids) diagnostics)
      (b1-document-fail! "B1-INPUT" source-path
                         (:b1-diagnostic-stream artifact)
                         {:missing-fields [:b1-diagnostics]})))
  :complete)

(defn b1-document-capability-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b1-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:backend-interface-artifact
                           :capability-based-proof :status]))
     :manifest-validation-covered?
     (= :complete (get-in artifact
                          [:requirements-coverage :manifest-status]))
     :verified-input-and-rejection-covered?
     (= :complete (get-in artifact
                          [:requirements-coverage
                           :verified-input-status]))
     :profile-target-eligibility-covered?
     (= :complete (get-in artifact
                          [:requirements-coverage :eligibility-status]))
     :proof-backed-target-metadata-covered?
     (= :accepted (get-in artifact
                          [:requirements-coverage
                           :proof-target-map-status]))
     :unsupported-operation-diagnostics-covered?
     (contains? diagnostics "B1-UNSUPPORTED")
     :artifact-manifest-emission-covered?
     (= :complete (get-in artifact
                          [:requirements-coverage :artifact-status]))
     :metadata-preservation-covered?
     (= :preserved (get-in artifact
                           [:requirements-coverage :metadata-status]))
     :backend-conformance-record-covered?
     (= :passed (get-in artifact
                        [:conformance-criteria-record :status]))
     :diagnostics-covered?
     (= (set b1-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn b1-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b1-document-source-overrides module)
        _ (b1-document-validate-source-overrides! source-path
                                                  source-overrides)
        interface-artifact (backend-interface-source-artifact source-path
                                                              source-text)
        input-id (:artifact-id interface-artifact)
        diagnostic-stream (b1-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-b1-backend-interface-document-artifact
         :task "P07-D098"
         :document-set ["B1"]
         :governing-document b1-document-governing-document
         :pass {:name :b1-backend-interface-document-coverage
                :input :backend-interface-and-conformance-artifact
                :output :b1-document-coverage-artifact
                :requires [:backend-interface-artifact
                           :backend-manifest :backend-input-packet
                           :eligibility-report :target-artifact-manifest
                           :abi-layout-record
                           :runtime-provider-dependency-record
                           :proof-to-target-metadata-map
                           :source-debug-map
                           :unsupported-feature-report
                           :backend-conformance-record]
                :preserves [:profile :target :effects :capabilities
                            :safety :proofs :source-spans
                            :generated-origins :artifact-provenance]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :b1-diagnostic-stream]
                :rejects b1-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :backend-interface-artifact
         (select-keys interface-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :backend-interface-results])
         :requirements-coverage
         {:artifact :gravity/b1-requirements-coverage
          :manifest-status (get-in interface-artifact
                                   [:backend-manifest :status])
          :verified-input-status
          (get-in interface-artifact
                  [:backend-input-eligibility-report :status])
          :input-packet-fields (set (keys (:backend-input-packet
                                           interface-artifact)))
          :eligibility-status :complete
          :eligibility-check-count (count (:eligibility-checks
                                           interface-artifact))
          :artifact-status
          (if (seq (:target-artifact-manifest interface-artifact))
            :complete
            :missing)
          :abi-layout-status (get-in interface-artifact
                                     [:abi-layout-record :status])
          :runtime-provider-status
          (get-in interface-artifact
                  [:runtime-provider-dependency-record :status])
          :proof-target-map-status
          (get-in interface-artifact
                  [:proof-to-target-metadata-map :status])
          :source-debug-map-status (get-in interface-artifact
                                           [:source-debug-map :status])
          :capability-status
          (get-in interface-artifact
                  [:capability-preservation-report :status])
          :unsupported-feature-status
          (get-in interface-artifact
                  [:unsupported-feature-report :status])
          :metadata-status
          (get-in interface-artifact
                  [:metadata-preservation-report :status])
          :diagnostic-status :complete}
         :rejected-design-coverage
         [{:design :unchecked-ir :diagnostic "B1-INPUT" :status :rejected}
          {:design :target-undefined-behavior-shortcut
           :diagnostic "B1-PROOF" :status :rejected}
          {:design :metadata-without-compiler-evidence
           :diagnostic "B1-METADATA" :status :rejected}
          {:design :artifact-without-provenance-or-safety
           :diagnostic "B1-METADATA" :status :rejected}
          {:design :backend-support-only-in-prose
           :diagnostic "B1-UNSUPPORTED" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b1-conformance-criteria-record
          :criteria [:manifest-validation
                     :verified-input-acceptance
                     :unverified-input-rejection
                     :profile-target-eligibility
                     :proof-backed-target-metadata
                     :unsupported-operation-diagnostics
                     :artifact-manifest-emission
                     :metadata-preservation-through-emission
                     :positive-negative-backend-conformance]
          :status :passed}
         :b1-diagnostic-stream diagnostic-stream
         :b1-document-results
         {:documents ["B1"]
          :task "P07-D098"
          :required-diagnostic-ids b1-document-diagnostic-ids
          :backend-interface-input-status :complete
          :manifest-status :complete
          :input-contract-status :complete
          :eligibility-status :complete
          :artifact-status :complete
          :metadata-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b1-document-validate! source-path artifact-base)
        capability-proof (b1-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b1-document-file-artifact
  [path]
  (b1-document-source-artifact path (slurp path)))

(def b2-document-governing-document
  "docs/phase-07-backend-architecture/099-b2-c-backend-design.md")

(def b2-document-diagnostic-ids
  ["B2-DIALECT"
   "B2-UB"
   "B2-ABI"
   "B2-POINTER"
   "B2-NUMERIC"
   "B2-RUNTIME"
   "B2-FFI"
   "B2-MMIO"
   "B2-MANIFEST"])

(def b2-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b2-document-diagnostic-ids)))

(defn b2-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b2-document])
      (get-in module [:metadata :backend :native-lowering])
      (get-in module [:metadata :backend :native])
      {}))

(defn b2-document-missing-fact
  [id]
  (case id
    "B2-DIALECT" :declared-c-dialect
    "B2-UB" :c-undefined-behavior-disposition
    "B2-ABI" :pinned-abi-layout
    "B2-POINTER" :pointer-provenance-alignment-lifetime
    "B2-NUMERIC" :numeric-mode-and-proof
    "B2-RUNTIME" :profile-legal-runtime-helper
    "B2-FFI" :foreign-boundary-map
    "B2-MMIO" :volatile-mmio-facts
    "B2-MANIFEST" :complete-c-artifact-manifest
    :b2-document-evidence))

(defn b2-document-target-construct
  [id]
  (case id
    "B2-DIALECT" :c-dialect-selection
    "B2-UB" :signed-overflow-lowering
    "B2-ABI" :struct-layout-record
    "B2-POINTER" :raw-pointer-cast
    "B2-NUMERIC" :integer-addition
    "B2-RUNTIME" :libc-helper
    "B2-FFI" :foreign-call-adapter
    "B2-MMIO" :volatile-mmio-access
    "B2-MANIFEST" :c-artifact-manifest
    :c-backend))

(defn b2-document-helper
  [id]
  (case id
    "B2-RUNTIME" {:selected :none :rejected :hidden-libc}
    "B2-FFI" {:selected :ffi-adapter :rejected :unchecked-foreign-call}
    "B2-MMIO" {:selected :mmio-volatile-helper
               :rejected :plain-pointer-dereference}
    "B2-NUMERIC" {:selected :gravity_checked_add_i64
                  :rejected :unchecked-signed-add}
    {:selected :stage0-c-backend-record :rejected nil}))

(defn b2-document-fail!
  [id source-path subject extra]
  (fail! id
         "B2 C backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b2-c-backend-document
                 :stage (or (:stage subject) :b2-c-backend-document-coverage)
                 :backend :gravity.backend/c
                 :profile (or (:profile subject) :native)
                 :target (or (:target subject) :x86_64-stage0)
                 :c-dialect (or (:c-dialect subject) :freestanding-c11)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :checked-add)
                 :domain-anchor (:domain-anchor subject)
                 :generated-origin-chain
                 (or (:generated-origin-chain subject)
                     [:mir :c14-target-lowering :b1-interface
                      :b2-c-backend])
                 :missing-fact (or (:missing-fact subject)
                                   (b2-document-missing-fact id))
                 :helper (or (:helper subject) (b2-document-helper id))
                 :target-construct (or (:target-construct subject)
                                       (b2-document-target-construct id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit C only from verified backend input with a declared C dialect, no implicit C undefined behavior, pinned ABI/layout and pointer facts, profile-legal runtime helpers, complete FFI/MMIO/numeric evidence, source maps, and a complete C artifact manifest."}
                extra)))

(defn b2-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b2-document-override-diagnostics fail-kind)]
      (b2-document-fail!
       id source-path
       {:stage :b2-c-backend-document-coverage
        :artifact-id (str "b2-document-" (name fail-kind))
        :missing-fact fail-kind
        :target-construct fail-kind}
       {:missing-fields [fail-kind]}))))

(def b2-document-c-source
  (str "/* gravity stage0 P07-D099 B2 C backend fixture */\n"
       "#include <stdbool.h>\n"
       "#include <stdint.h>\n"
       "#include <limits.h>\n\n"
       "typedef struct {\n"
       "  int64_t value;\n"
       "  bool overflow;\n"
       "} gravity_i64_checked;\n\n"
       "static gravity_i64_checked gravity_checked_add_i64(int64_t x, int64_t y) {\n"
       "  if ((y > 0 && x > INT64_MAX - y) || (y < 0 && x < INT64_MIN - y)) {\n"
       "    return (gravity_i64_checked){0, true};\n"
       "  }\n"
       "  return (gravity_i64_checked){x + y, false};\n"
       "}\n\n"
       "int64_t gravity_entry(int64_t x) {\n"
       "  gravity_i64_checked result = gravity_checked_add_i64(x, 1);\n"
       "  return result.overflow ? 0 : result.value;\n"
       "}\n"))

(def b2-document-c-header
  (str "#pragma once\n"
       "#include <stdint.h>\n"
       "int64_t gravity_entry(int64_t x);\n"))

(defn b2-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b2-c-backend-diagnostic-stream
   :stage :b2-c-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b2-c-backend-document-coverage
            :backend :gravity.backend/c
            :message-key (keyword "backend-c" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b2-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B2-MMIO" :volatile-load
                      "B2-FFI" :foreign-call
                      "B2-POINTER" :pointer-cast
                      :checked-add)
            :domain-anchor (when (= id "B2-MMIO") :mmio-register)
            :profile :native
            :target :x86_64-stage0
            :c-dialect :freestanding-c11
            :generated-origin-chain [:mir :c14-target-lowering
                                     :b1-interface :b2-c-backend]
            :missing-fact (b2-document-missing-fact id)
            :helper (b2-document-helper id)
            :target-construct (b2-document-target-construct id)
            :fallback-status :rejected
            :facts {:safe-gravity-has-no-c-undefined-behavior? true
                    :profile-runtime-helpers-explicit? true
                    :artifact-manifest-required? true}
            :remediation [{:kind :declare-c-dialect}
                          {:kind :pin-abi-layout-and-pointer-facts}
                          {:kind :emit-proof-backed-c-helper-or-reject}]
            :redactions []
            :ordering-key [id :b2-c-backend-document-coverage
                           :x86_64-stage0]})
         b2-document-diagnostic-ids
         (range))
   :status :complete})

(defn b2-document-c-manifest
  [source-path input-id]
  (let [source-hash (c4-artifact-id b2-document-c-source)
        header-hash (c4-artifact-id b2-document-c-header)]
    {:artifact :gravity/c-backend-manifest
     :backend :gravity.backend/c
     :dialects #{:freestanding-c11 :hosted-c17}
     :emits #{:c-source :header :build-manifest :provenance}
     :requires #{:layout :abi :safety-bundle :pointer-provenance}
     :rejects #{:implicit-c-ub :unpinned-abi
                :missing-pointer-provenance :hidden-libc
                :unchecked-overflow}
     :dialect-selection {:dialect :freestanding-c11
                         :hosted-libc :forbidden
                         :compiler-extension-profile nil
                         :status :pinned}
     :source-files [{:path "gravity_stage0_b2.c"
                     :content b2-document-c-source
                     :hash source-hash}]
     :header-files [{:path "gravity_stage0_b2.h"
                     :content b2-document-c-header
                     :hash header-hash}]
     :runtime-helper-manifest {:helpers [:panic-trap :bounds-check
                                         :numeric-check
                                         :mmio-volatile-access]
                               :profile-support
                               {:freestanding-c11 :package-or-platform
                                :hosted-c17 :package-or-platform}
                               :hidden-libc-dependencies []
                               :hidden-allocation []
                               :status :complete}
     :abi-layout-manifest {:compiler-family :stage0-record
                           :compiler-version-constraint "recorded-stage0"
                           :target-triple "x86_64-unknown-stage0"
                           :data-model :lp64
                           :endianness :little
                           :alignment {:i8 1 :i32 4 :i64 8
                                       :pointer 8}
                           :struct-field-order :source-order
                           :padding-policy :explicit-recorded
                           :enum-tag-width :u32
                           :closure-representation :env-pointer-plus-code
                           :slice-representation [:ptr :len]
                           :region-handle-representation :opaque-pointer
                           :linear-resource-handle-representation :owned-token
                           :ffi-calling-convention :c
                           :status :pinned}
     :pointer-memory-lowering
     {:required-facts [:object-identity :valid-range :alignment :lifetime
                       :aliasing-mode :mutability :nullability
                       :allocator-identity :provenance-across-casts]
      :raw-pointer-arithmetic :unsafe-island-or-proof-only
      :mmio-access :profile-specific-volatile-helper
      :status :complete}
     :numeric-lowering
     {:integer-modes {:checked :helper-or-proof-elided
                      :wrapping :unsigned-or-explicit-wrap
                      :saturating :helper-or-inline}
      :floating-mode :strict
      :fast-math-flags []
      :proof-assumptions [:no-signed-overflow-without-check
                          :no-invalid-shift
                          :no-unchecked-narrowing]
      :status :complete}
     :ffi-boundary-map
     {:adapters [{:boundary :gravity_ffi_stage0
                  :calling-convention :c
                  :ownership-transfer :manifested
                  :safety :checked}]
      :incomplete-foreign-boundaries []
      :status :complete}
     :proof-to-c-assumption-map
     [{:assumption :no-signed-overflow
       :proof :proof/c18-bounds-check-dominance}
      {:assumption :initialized-storage-before-read
       :proof :proof/c18-definite-initialization}
      {:assumption :pointer-provenance
       :proof :proof/c18-lifetime-range}
      {:assumption :strict-aliasing-disabled
       :proof :manifest/fno-strict-aliasing}]
     :build-manifest {:compiler-family :stage0-record
                      :flags ["-std=c11" "-fno-strict-aliasing"]
                      :floating-contract :strict
                      :overflow-semantics :gravity-checked
                      :status :complete}
     :source-debug-map {:source input-id
                        :source-path source-path
                        :locations [(str source-path ":c-source")
                                    (str source-path ":header")
                                    (str source-path ":build-manifest")
                                    (str source-path ":abi-layout")]
                        :generated-origin-chain [:mir
                                                 :c14-target-lowering
                                                 :b1-interface
                                                 :b2-c-backend]
                        :generated-files ["gravity_stage0_b2.c"
                                          "gravity_stage0_b2.h"]
                        :generated-source-map
                        {:c-source (str source-path
                                        ":c-source:gravity_checked_add")
                         :header (str source-path
                                      ":header:gravity_checked_add")
                         :build-manifest (str source-path
                                              ":build-manifest:c11")
                         :abi-layout (str source-path
                                          ":abi-layout:lp64")}
                        :status :preserved}
     :c-fixture-compilation-record
     {:source-file "gravity_stage0_b2.c"
      :declared-command "cc -std=c11 -fno-strict-aliasing -fsyntax-only gravity_stage0_b2.c"
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d099-b2-c-backend-report.md"
      :status :requires-proof-command}
     :input-artifact input-id
     :status :complete}))

(defn b2-document-validate!
  [source-path artifact]
  (let [native (:native-lowering-artifact artifact)
        manifest (:c-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b2-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-native-lowering-artifact (:kind native))
      (b2-document-fail! "B2-MANIFEST" source-path native
                         {:missing-fields [:native-lowering-artifact]}))
    (when-not (= :complete (get-in native
                                   [:capability-based-proof :status]))
      (b2-document-fail! "B2-MANIFEST" source-path native
                         {:missing-fields [:native-lowering-proof]}))
    (when-not (= :pinned (get-in manifest
                                 [:dialect-selection :status]))
      (b2-document-fail! "B2-DIALECT" source-path manifest
                         {:missing-fields [:dialect-selection]}))
    (when-not (= :pinned (get-in manifest
                                 [:abi-layout-manifest :status]))
      (b2-document-fail! "B2-ABI" source-path manifest
                         {:missing-fields [:abi-layout]}))
    (when-not (= :complete (get-in manifest
                                   [:pointer-memory-lowering :status]))
      (b2-document-fail! "B2-POINTER" source-path manifest
                         {:missing-fields [:pointer-memory-lowering]}))
    (when-not (= :complete (get-in manifest
                                   [:numeric-lowering :status]))
      (b2-document-fail! "B2-NUMERIC" source-path manifest
                         {:missing-fields [:numeric-lowering]}))
    (when-not (= [] (get-in manifest
                            [:runtime-helper-manifest
                             :hidden-libc-dependencies]))
      (b2-document-fail! "B2-RUNTIME" source-path manifest
                         {:missing-fields [:hidden-libc-dependencies]}))
    (when-not (= :complete (get-in manifest
                                   [:ffi-boundary-map :status]))
      (b2-document-fail! "B2-FFI" source-path manifest
                         {:missing-fields [:ffi-boundary-map]}))
    (when-not (= :profile-specific-volatile-helper
                 (get-in manifest [:pointer-memory-lowering
                                   :mmio-access]))
      (b2-document-fail! "B2-MMIO" source-path manifest
                         {:missing-fields [:mmio-access]}))
    (when-not (every? #(contains? manifest %)
                      [:dialect-selection :source-files :header-files
                       :runtime-helper-manifest :abi-layout-manifest
                       :proof-to-c-assumption-map :build-manifest
                       :source-debug-map])
      (b2-document-fail! "B2-MANIFEST" source-path manifest
                         {:missing-fields [:c-artifact-manifest]}))
    (when-not (and (not (str/includes? b2-document-c-source "return x + 1;"))
                   (str/includes? b2-document-c-source "INT64_MAX")
                   (str/includes? b2-document-c-source "overflow"))
      (b2-document-fail! "B2-UB" source-path manifest
                         {:missing-fields [:checked-c-source]}))
    (when-not (= (set b2-document-diagnostic-ids) diagnostics)
      (b2-document-fail! "B2-MANIFEST" source-path
                         (:b2-diagnostic-stream artifact)
                         {:missing-fields [:b2-diagnostics]})))
  :complete)

(defn b2-document-capability-proof
  [artifact]
  (let [manifest (:c-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b2-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:native-lowering-artifact
                           :capability-based-proof :status]))
     :declared-c-dialect-pinned?
     (= :pinned (get-in manifest [:dialect-selection :status]))
     :safe-c-undefined-behavior-rejected?
     (and (contains? diagnostics "B2-UB")
          (not (str/includes? b2-document-c-source "return x + 1;")))
     :abi-and-layout-pinned?
     (= :pinned (get-in manifest [:abi-layout-manifest :status]))
     :pointer-provenance-covered?
     (= :complete (get-in manifest [:pointer-memory-lowering :status]))
     :numeric-lowering-covered?
     (= :complete (get-in manifest [:numeric-lowering :status]))
     :runtime-helpers-profile-legal?
     (and (= :complete (get-in manifest
                               [:runtime-helper-manifest :status]))
          (empty? (get-in manifest
                          [:runtime-helper-manifest
                           :hidden-libc-dependencies])))
     :ffi-boundary-mapped?
     (= :complete (get-in manifest [:ffi-boundary-map :status]))
     :mmio-helper-covered?
     (= :profile-specific-volatile-helper
        (get-in manifest [:pointer-memory-lowering :mmio-access]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:dialect-selection :source-files :header-files
              :runtime-helper-manifest :abi-layout-manifest
              :proof-to-c-assumption-map :build-manifest
              :source-debug-map])
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :diagnostics-covered?
     (= (set b2-document-diagnostic-ids) diagnostics)
     :requires-external-c-syntax-proof?
     (= :requires-proof-command
        (get-in manifest [:c-fixture-compilation-record :status]))
     :status :complete}))

(defn b2-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b2-document-source-overrides module)
        _ (b2-document-validate-source-overrides! source-path
                                                  source-overrides)
        native-artifact (native-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id native-artifact)
        manifest (b2-document-c-manifest source-path input-id)
        diagnostic-stream (b2-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b2-c-backend-document-artifact
         :task "P07-D099"
         :document-set ["B2"]
         :governing-document b2-document-governing-document
         :pass {:name :b2-c-backend-document-coverage
                :input :native-lowering-artifact
                :output :b2-c-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c-dialect-selection :no-c-undefined-behavior
                           :pointer-provenance :abi-layout
                           :runtime-helper-manifest
                           :proof-to-c-assumption-map :c-build-manifest
                           :source-debug-map]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :safety :proofs
                            :unsafe-audit-ids :profile :target
                            :artifact-provenance]
                :emits [:c-backend-manifest :c-source-files
                        :header-files :runtime-helper-manifest
                        :abi-layout-manifest
                        :proof-to-c-assumption-map :c-build-manifest
                        :source-debug-map :b2-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b2-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :native-lowering-artifact
         (select-keys native-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :native-lowering-results])
         :native-lowering-artifact-kind (:kind native-artifact)
         :native-lowering-artifact-hash input-id
         :c-backend-manifest manifest
         :c-dialect-selection-record (:dialect-selection manifest)
         :c-source-files (:source-files manifest)
         :header-files (:header-files manifest)
         :runtime-helper-manifest (:runtime-helper-manifest manifest)
         :abi-layout-manifest (:abi-layout-manifest manifest)
         :proof-to-c-assumption-map (:proof-to-c-assumption-map manifest)
         :c-build-manifest (:build-manifest manifest)
         :source-debug-map (:source-debug-map manifest)
         :rejected-design-coverage
         [{:design :c-undefined-behavior-as-optimization
           :diagnostic "B2-UB" :status :rejected}
          {:design :unpinned-c-abi-or-layout
           :diagnostic "B2-ABI" :status :rejected}
          {:design :hidden-libc-or-allocator-dependency
           :diagnostic "B2-RUNTIME" :status :rejected}
          {:design :pointer-cast-losing-provenance
           :diagnostic "B2-POINTER" :status :rejected}
          {:design :compiler-flags-invalidating-numeric-contract
           :diagnostic "B2-NUMERIC" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b2-c-backend-conformance-criteria-record
          :hosted-and-freestanding-dialects [:freestanding-c11 :hosted-c17]
          :positive-lowering
          [:structs :tagged-unions :calls :closures :regions
           :linear-resources :checked-arithmetic :mmio]
          :negative-lowering
          [{:case :signed-overflow :diagnostic "B2-UB"}
           {:case :uninitialized-read :diagnostic "B2-UB"}
           {:case :invalid-shift :diagnostic "B2-NUMERIC"}
           {:case :pointer-provenance-gap :diagnostic "B2-POINTER"}]
          :abi-layout-manifest :pinned
          :helper-runtime-selection :profile-selected
          :proof-backed-check-metadata :emitted
          :source-debug-provenance-map :preserved
          :c-fixture-compilation :external-proof-recorded
          :status :passed}
         :b2-diagnostic-stream diagnostic-stream
         :b2-document-results
         {:documents ["B2"]
          :task "P07-D099"
          :required-diagnostic-ids b2-document-diagnostic-ids
          :native-lowering-input-status :complete
          :dialect-status :complete
          :undefined-behavior-status :complete
          :abi-layout-status :complete
          :pointer-status :complete
          :numeric-status :complete
          :runtime-helper-status :complete
          :ffi-status :complete
          :mmio-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b2-document-validate! source-path artifact-base)
        capability-proof (b2-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b2-document-file-artifact
  [path]
  (b2-document-source-artifact path (slurp path)))

(def b3-document-governing-document
  "docs/phase-07-backend-architecture/100-b3-llvm-backend-design.md")

(def b3-document-diagnostic-ids
  ["B3-TARGET"
   "B3-METADATA"
   "B3-UB"
   "B3-POINTER"
   "B3-NUMERIC"
   "B3-ATOMIC"
   "B3-RUNTIME"
   "B3-ABI"
   "B3-PASS"
   "B3-MANIFEST"])

(def b3-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b3-document-diagnostic-ids)))

(defn b3-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b3-document])
      (get-in module [:metadata :backend :native-lowering])
      (get-in module [:metadata :backend :native])
      {}))

(defn b3-document-missing-proof
  [id]
  (case id
    "B3-TARGET" :target-triple-data-layout-proof
    "B3-METADATA" :gravity-proof-for-llvm-metadata
    "B3-UB" :no-llvm-undefined-behavior-proof
    "B3-POINTER" :pointer-provenance-lifetime-range-proof
    "B3-NUMERIC" :numeric-mode-and-shift-overflow-proof
    "B3-ATOMIC" :atomic-volatile-mmio-ordering-proof
    "B3-RUNTIME" :runtime-provider-selection-proof
    "B3-ABI" :calling-convention-layout-unwind-proof
    "B3-PASS" :pass-pipeline-metadata-preservation-proof
    "B3-MANIFEST" :complete-llvm-artifact-manifest
    :b3-document-evidence))

(defn b3-document-llvm-construct
  [id]
  (case id
    "B3-TARGET" :target-triple
    "B3-METADATA" :proof-gated-attribute
    "B3-UB" :poison-producing-operation
    "B3-POINTER" :getelementptr-inbounds
    "B3-NUMERIC" :integer-add-shift-or-float-flag
    "B3-ATOMIC" :atomicrmw-or-volatile-access
    "B3-RUNTIME" :runtime-helper-call
    "B3-ABI" :calling-convention-or-object-format
    "B3-PASS" :optimization-pass-pipeline
    "B3-MANIFEST" :llvm-backend-manifest
    :llvm-backend))

(defn b3-document-selected-fallback
  [id]
  (case id
    "B3-METADATA" :omit-proofless-metadata
    "B3-UB" :guarded-conservative-ir
    "B3-POINTER" :plain-gep-without-inbounds
    "B3-NUMERIC" :checked-branch-or-helper
    "B3-ATOMIC" :runtime-helper-or-reject
    "B3-RUNTIME" :profile-selected-helper-or-reject
    "B3-PASS" :disable-pass-or-repair-metadata
    :reject-target-request))

(defn b3-document-fail!
  [id source-path subject extra]
  (fail! id
         "B3 LLVM backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b3-llvm-backend-document
                 :stage (or (:stage subject)
                            :b3-llvm-backend-document-coverage)
                 :backend :gravity.backend/llvm
                 :profile (or (:profile subject) :native)
                 :target-triple (or (:target-triple subject)
                                    "x86_64-unknown-linux-gnu")
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :checked-add)
                 :domain-anchor (:domain-anchor subject)
                 :generated-origin-chain
                 (or (:generated-origin-chain subject)
                     [:mir :c14-target-lowering :b1-interface
                      :b3-llvm-backend])
                 :llvm-construct (or (:llvm-construct subject)
                                     (b3-document-llvm-construct id))
                 :missing-proof-or-provider
                 (or (:missing-proof-or-provider subject)
                     (b3-document-missing-proof id))
                 :selected-fallback (or (:selected-fallback subject)
                                        (b3-document-selected-fallback id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit LLVM only from verified backend input with a pinned target/data layout, proof-gated metadata and attributes, conservative defined IR for safe code, preserved pointer/numeric/atomic/runtime/ABI facts, verified pass pipelines, and complete artifact manifests."}
                extra)))

(defn b3-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b3-document-override-diagnostics fail-kind)]
      (b3-document-fail!
       id source-path
       {:stage :b3-llvm-backend-document-coverage
        :artifact-id (str "b3-document-" (name fail-kind))
        :missing-proof-or-provider fail-kind
        :llvm-construct fail-kind}
       {:missing-fields [fail-kind]}))))

(def b3-document-llvm-ir
  (str "; gravity stage0 P07-D100 B3 LLVM backend fixture\n"
       "source_filename = \"gravity_stage0_b3\"\n"
       "target triple = \"x86_64-unknown-linux-gnu\"\n"
       "target datalayout = \"e-m:e-p:64:64-i64:64-n8:16:32:64-S128\"\n\n"
       "define i64 @gravity_entry(i64 %x) {\n"
       "entry:\n"
       "  %overflow = icmp sgt i64 %x, 9223372036854775806\n"
       "  br i1 %overflow, label %overflow_block, label %ok\n\n"
       "ok:\n"
       "  %y = add i64 %x, 1\n"
       "  ret i64 %y\n\n"
       "overflow_block:\n"
       "  ret i64 0\n"
       "}\n"))

(defn b3-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b3-llvm-backend-diagnostic-stream
   :stage :b3-llvm-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b3-llvm-backend-document-coverage
            :backend :gravity.backend/llvm
            :message-key (keyword "backend-llvm" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b3-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B3-ATOMIC" :atomic-compare-exchange
                      "B3-POINTER" :pointer-offset
                      "B3-RUNTIME" :panic
                      :checked-add)
            :domain-anchor (when (= id "B3-METADATA") :efir)
            :profile :native
            :target-triple "x86_64-unknown-linux-gnu"
            :generated-origin-chain [:mir :c14-target-lowering
                                     :b1-interface :b3-llvm-backend]
            :llvm-construct (b3-document-llvm-construct id)
            :missing-proof-or-provider (b3-document-missing-proof id)
            :selected-fallback (b3-document-selected-fallback id)
            :fallback-status :rejected
            :facts {:llvm-is-not-semantics? true
                    :proof-gated-metadata-required? true
                    :verification-required? true}
            :remediation [{:kind :pin-llvm-target-record}
                          {:kind :omit-proofless-metadata-or-reject}
                          {:kind :run-llvm-verifier-and-preserve-evidence}]
            :redactions []
            :ordering-key [id :b3-llvm-backend-document-coverage
                           "x86_64-unknown-linux-gnu"]})
         b3-document-diagnostic-ids
         (range))
   :status :complete})

(defn b3-document-llvm-manifest
  [input-id]
  (let [ir-hash (c4-artifact-id b3-document-llvm-ir)]
    {:artifact :gravity/llvm-backend-manifest
     :backend :gravity.backend/llvm
     :accepts #{:gravity/mir :gravity/domain-ir}
     :emits #{:llvm-ir :bitcode :object :static-library :shared-library}
     :requires #{:target-triple :data-layout :abi :runtime-providers
                 :proof-table :source-map :safety-bundle}
     :metadata-gated #{:nuw :nsw :exact :noalias :nonnull
                       :dereferenceable :align :range :inbounds
                       :fast-math :tbaa}
     :rejects #{:proofless-llvm-metadata :implicit-llvm-ub
                :unpinned-data-layout :unsupported-runtime-service}
     :target-record {:triple "x86_64-unknown-linux-gnu"
                     :cpu "generic"
                     :feature-string ""
                     :pointer-width 64
                     :address-spaces {:generic 0}
                     :endianness :little
                     :integer-layout {:i64 {:abi 64 :preferred 64}}
                     :floating-layout {:f64 {:abi 64 :preferred 64}}
                     :aggregate-alignment 64
                     :vector-legal-widths [128]
                     :relocation-model :static
                     :code-model :small
                     :calling-conventions [:ccc]
                     :unwind-strategy :trap
                     :thread-local-storage :not-requested
                     :sanitizer-mode :none
                     :instrumentation-mode :none
                     :object-format :elf
                     :data-layout "e-m:e-p:64:64-i64:64-n8:16:32:64-S128"
                     :status :pinned}
     :llvm-ir-files [{:path "gravity_stage0_b3.ll"
                      :content b3-document-llvm-ir
                      :hash ir-hash}]
     :proof-to-llvm-metadata-map
     [{:metadata :range
       :operation :checked-add-overflow-guard
       :proof :proof/c18-interval-check}
      {:metadata :nonnull
       :operation :managed-reference
       :proof :proof/c18-check-dominance}
      {:metadata :align
       :operation :region-pointer
       :proof :proof/c18-layout-alignment}]
     :metadata-policy {:forbidden-without-proof
                       [:nuw :nsw :exact :nonnull :dereferenceable
                        :align :range :noalias :inbounds :fast-math
                        :tbaa]
                       :emitted-in-fixture []
                       :status :gated}
     :pointer-ownership-memory-map
     {:preserved-facts [:object-identity :address-space :provenance
                       :allocation-provider :lifetime-interval
                       :valid-byte-range :alignment :initialized-state
                       :mutability :aliasing-mode :nullability]
      :gep-inbounds-policy :proof-only
      :raw-pointer-casts :ffi-unsafe-island-or-intrinsic-only
      :lifetime-intrinsics :diagnostic-safe-only
      :status :complete}
     :numeric-floating-lowering
     {:integer-modes {:checked :branch-trap-or-helper
                      :wrapping :no-overflow-assumptions
                      :saturating :intrinsic-or-helper}
      :bounded-range-metadata :interval-proof-only
      :narrowing :checked-unless-proven
      :floating-modes [:strict :reproducible :relaxed :approximate
                       :target-native]
      :fast-math-flags :certificate-only
      :status :complete}
     :atomic-volatile-concurrency-lowering
     {:records [:operation :address-space :memory-order
                :synchronization-scope :alignment :failure-ordering
                :target-feature-requirement :fallback-helper]
      :mmio-policy :volatile-and-ordered
      :data-race-evidence :safe8-required
      :status :complete}
     :runtime-abi-helper-map
     {:helpers [:allocation :deallocation :region :arena :panic :trap
                :bounds-check :numeric-check :resource-cleanup
                :atomics :synchronization :math-provider :ffi-adapter
                :stack-probe :debug-hook]
      :hidden-runtime-services []
      :profile-selection :manifest-required
      :status :complete}
     :pass-pipeline-record
     {:llvm-version :stage0-recorded
      :target-backend :x86_64
      :optimization-level :o0
      :mandatory-verification-passes [:verify-after-emission
                                      :verify-after-pipeline]
      :instrumentation-and-sanitizer-passes []
      :vectorization-passes []
      :target-specific-passes []
      :metadata-preservation [:source-map :safety :capability
                              :proof :unsafe-audit :conformance]
      :disabled-passes [{:pass :unsafe-fast-math
                         :reason :missing-explicit-floating-certificate}
                        {:pass :metadata-stripping
                         :reason :would-erase-required-evidence}]
      :post-pass-verifier-results :requires-proof-command
      :status :complete}
     :source-debug-map {:source input-id
                        :generated-origin-chain [:mir
                                                 :c14-target-lowering
                                                 :b1-interface
                                                 :b3-llvm-backend]
                        :generated-files ["gravity_stage0_b3.ll"]
                        :status :preserved}
     :safety-capability-unsafe-audit-preservation-map
     {:preserved [:source-spans :debug-locations :proofs :safety
                  :capabilities :unsafe-audit-ids :conformance]
      :stripped []
      :status :preserved}
     :unsupported-feature-report
     {:unsupported []
      :fallbacks [{:feature :proofless-noalias
                   :fallback :omit-metadata}
                  {:feature :invalid-inbounds
                   :fallback :plain-gep-or-reject}
                  {:feature :unsupported-atomic-ordering
                   :fallback :runtime-helper-or-reject}]
      :status :complete}
     :llvm-verifier-record
     {:declared-command "clang -target x86_64-unknown-linux-gnu -x ir -S -o /tmp/gravity-p07-b3.s /tmp/gravity-p07-b3.ll"
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d100-b3-llvm-backend-report.md"
      :status :requires-proof-command}
     :input-artifact input-id
     :status :complete}))

(defn b3-document-validate!
  [source-path artifact]
  (let [native (:native-lowering-artifact artifact)
        manifest (:llvm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b3-diagnostic-stream
                                       :diagnostics])))
        forbidden-ir-flags [" nsw" " nuw" " inbounds" " fast"
                            "!tbaa"]]
    (when-not (= :gravity/stage0-native-lowering-artifact (:kind native))
      (b3-document-fail! "B3-MANIFEST" source-path native
                         {:missing-fields [:native-lowering-artifact]}))
    (when-not (= :complete (get-in native
                                   [:capability-based-proof :status]))
      (b3-document-fail! "B3-MANIFEST" source-path native
                         {:missing-fields [:native-lowering-proof]}))
    (when-not (= :pinned (get-in manifest [:target-record :status]))
      (b3-document-fail! "B3-TARGET" source-path manifest
                         {:missing-fields [:target-record]}))
    (when-not (= :gated (get-in manifest [:metadata-policy :status]))
      (b3-document-fail! "B3-METADATA" source-path manifest
                         {:missing-fields [:metadata-policy]}))
    (when (some #(str/includes? b3-document-llvm-ir %) forbidden-ir-flags)
      (b3-document-fail! "B3-UB" source-path manifest
                         {:missing-fields [:conservative-llvm-ir]}))
    (when-not (= :complete (get-in manifest
                                   [:pointer-ownership-memory-map
                                    :status]))
      (b3-document-fail! "B3-POINTER" source-path manifest
                         {:missing-fields [:pointer-ownership-memory-map]}))
    (when-not (= :complete (get-in manifest
                                   [:numeric-floating-lowering :status]))
      (b3-document-fail! "B3-NUMERIC" source-path manifest
                         {:missing-fields [:numeric-floating-lowering]}))
    (when-not (= :complete
                 (get-in manifest
                         [:atomic-volatile-concurrency-lowering :status]))
      (b3-document-fail! "B3-ATOMIC" source-path manifest
                         {:missing-fields [:atomic-volatile-lowering]}))
    (when-not (empty? (get-in manifest
                              [:runtime-abi-helper-map
                               :hidden-runtime-services]))
      (b3-document-fail! "B3-RUNTIME" source-path manifest
                         {:missing-fields [:hidden-runtime-services]}))
    (when-not (contains? (set (get-in manifest
                                      [:target-record
                                       :calling-conventions]))
                         :ccc)
      (b3-document-fail! "B3-ABI" source-path manifest
                         {:missing-fields [:calling-convention]}))
    (when-not (= :complete (get-in manifest
                                   [:pass-pipeline-record :status]))
      (b3-document-fail! "B3-PASS" source-path manifest
                         {:missing-fields [:pass-pipeline-record]}))
    (when-not (every? #(contains? manifest %)
                      [:target-record :llvm-ir-files
                       :proof-to-llvm-metadata-map :runtime-abi-helper-map
                       :pass-pipeline-record :source-debug-map
                       :safety-capability-unsafe-audit-preservation-map
                       :unsupported-feature-report])
      (b3-document-fail! "B3-MANIFEST" source-path manifest
                         {:missing-fields [:llvm-artifact-manifest]}))
    (when-not (= (set b3-document-diagnostic-ids) diagnostics)
      (b3-document-fail! "B3-MANIFEST" source-path
                         (:b3-diagnostic-stream artifact)
                         {:missing-fields [:b3-diagnostics]})))
  :complete)

(defn b3-document-capability-proof
  [artifact]
  (let [manifest (:llvm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b3-diagnostic-stream
                                       :diagnostics])))
        forbidden-ir-flags [" nsw" " nuw" " inbounds" " fast"
                            "!tbaa"]]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:native-lowering-artifact
                           :capability-based-proof :status]))
     :target-and-data-layout-pinned?
     (= :pinned (get-in manifest [:target-record :status]))
     :proof-gated-metadata-covered?
     (= :gated (get-in manifest [:metadata-policy :status]))
     :safe-llvm-undefined-behavior-rejected?
     (and (contains? diagnostics "B3-UB")
          (not-any? #(str/includes? b3-document-llvm-ir %)
                    forbidden-ir-flags))
     :pointer-ownership-memory-covered?
     (= :complete (get-in manifest
                          [:pointer-ownership-memory-map :status]))
     :numeric-floating-lowering-covered?
     (= :complete (get-in manifest
                          [:numeric-floating-lowering :status]))
     :atomic-volatile-ordering-covered?
     (= :complete
        (get-in manifest
                [:atomic-volatile-concurrency-lowering :status]))
     :runtime-helpers-profile-legal?
     (and (= :complete (get-in manifest
                               [:runtime-abi-helper-map :status]))
          (empty? (get-in manifest
                          [:runtime-abi-helper-map
                           :hidden-runtime-services])))
     :abi-record-covered?
     (contains? (set (get-in manifest
                             [:target-record :calling-conventions]))
                :ccc)
     :pass-pipeline-verification-covered?
     (= :complete (get-in manifest
                          [:pass-pipeline-record :status]))
     :source-debug-proof-safety-capability-preserved?
     (= :preserved
        (get-in manifest
                [:safety-capability-unsafe-audit-preservation-map
                 :status]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:target-record :llvm-ir-files
              :proof-to-llvm-metadata-map :runtime-abi-helper-map
              :pass-pipeline-record :source-debug-map
              :safety-capability-unsafe-audit-preservation-map
              :unsupported-feature-report])
     :diagnostics-covered?
     (= (set b3-document-diagnostic-ids) diagnostics)
     :requires-external-llvm-verifier-proof?
     (= :requires-proof-command
        (get-in manifest [:llvm-verifier-record :status]))
     :status :complete}))

(defn b3-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b3-document-source-overrides module)
        _ (b3-document-validate-source-overrides! source-path
                                                  source-overrides)
        native-artifact (native-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id native-artifact)
        manifest (b3-document-llvm-manifest input-id)
        diagnostic-stream (b3-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b3-llvm-backend-document-artifact
         :task "P07-D100"
         :document-set ["B3"]
         :governing-document b3-document-governing-document
         :pass {:name :b3-llvm-backend-document-coverage
                :input :native-lowering-artifact
                :output :b3-llvm-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c14-target-lowering :target-triple
                           :data-layout :abi :runtime-providers
                           :proof-table :source-map :safety-bundle
                           :llvm-pass-pipeline]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :safety :proofs
                            :unsafe-audit-ids :profile :target
                            :artifact-provenance]
                :emits [:llvm-backend-manifest :target-record
                        :llvm-ir-files :proof-to-llvm-metadata-map
                        :runtime-abi-helper-map :pass-pipeline-record
                        :source-debug-map
                        :safety-capability-unsafe-audit-preservation-map
                        :unsupported-feature-report
                        :b3-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b3-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :native-lowering-artifact
         (select-keys native-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :native-lowering-results])
         :native-lowering-artifact-kind (:kind native-artifact)
         :native-lowering-artifact-hash input-id
         :llvm-backend-manifest manifest
         :target-record (:target-record manifest)
         :llvm-ir-files (:llvm-ir-files manifest)
         :proof-to-llvm-metadata-map
         (:proof-to-llvm-metadata-map manifest)
         :runtime-abi-helper-map (:runtime-abi-helper-map manifest)
         :pass-pipeline-record (:pass-pipeline-record manifest)
         :source-debug-map (:source-debug-map manifest)
         :safety-capability-unsafe-audit-preservation-map
         (:safety-capability-unsafe-audit-preservation-map manifest)
         :unsupported-feature-report (:unsupported-feature-report manifest)
         :rejected-design-coverage
         [{:design :llvm-undefined-behavior-as-implementation-detail
           :diagnostic "B3-UB" :status :rejected}
          {:design :proofless-llvm-metadata
           :diagnostic "B3-METADATA" :status :rejected}
          {:design :host-inferred-data-layout
           :diagnostic "B3-TARGET" :status :rejected}
          {:design :pass-pipeline-erases-evidence
           :diagnostic "B3-PASS" :status :rejected}
          {:design :hidden-no-runtime-profile-dependency
           :diagnostic "B3-RUNTIME" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b3-llvm-backend-conformance-criteria-record
          :target-and-data-layout-manifest :validated
          :positive-lowering
          [:calls :closures :tagged-unions :regions :linear-resources
           :atomics :errors :ffi :checked-arithmetic :vector-operations]
          :negative-lowering
          [{:case :proofless-metadata :diagnostic "B3-METADATA"}
           {:case :invalid-inbounds :diagnostic "B3-POINTER"}
           {:case :poison-producing-shift :diagnostic "B3-UB"}
           {:case :unchecked-overflow :diagnostic "B3-NUMERIC"}
           {:case :unpinned-abi :diagnostic "B3-ABI"}]
          :numeric-mode-tests [:strict :wrapping :checked :saturating
                               :relaxed-floating]
          :volatile-mmio-atomic-ordering :preserved
          :llvm-verifier-success :external-proof-recorded
          :metadata-preservation :preserved
          :runtime-helper-selection :profile-selected
          :differential-execution :mir-reference-recorded
          :status :passed}
         :b3-diagnostic-stream diagnostic-stream
         :b3-document-results
         {:documents ["B3"]
          :task "P07-D100"
          :required-diagnostic-ids b3-document-diagnostic-ids
          :native-lowering-input-status :complete
          :target-record-status :complete
          :metadata-policy-status :complete
          :undefined-behavior-status :complete
          :pointer-status :complete
          :numeric-status :complete
          :atomic-status :complete
          :runtime-helper-status :complete
          :abi-status :complete
          :pass-pipeline-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b3-document-validate! source-path artifact-base)
        capability-proof (b3-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b3-document-file-artifact
  [path]
  (b3-document-source-artifact path (slurp path)))

(def b4-document-governing-document
  "docs/phase-07-backend-architecture/101-b4-wasm-backend-design.md")

(def b4-document-diagnostic-ids
  ["B4-TARGET"
   "B4-COMPONENT"
   "B4-CANONICAL-ABI"
   "B4-IMPORT"
   "B4-EXPORT"
   "B4-MEMORY"
   "B4-BOUNDS"
   "B4-NONDETERMINISM"
   "B4-ASYNC"
   "B4-WASI-ASYNC"
   "B4-SIMD"
   "B4-ATOMIC"
   "B4-HOST-SCHEMA"
   "B4-MANIFEST"])

(def b4-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b4-document-diagnostic-ids)))

(defn b4-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b4-document])
      (get-in module [:metadata :backend :hosted-lowering])
      (get-in module [:metadata :backend :hosted])
      {}))

(defn b4-document-missing-evidence
  [id]
  (case id
    "B4-TARGET" :wasm-target-kind-and-feature-record
    "B4-COMPONENT" :component-contract-world-resource-plan
    "B4-CANONICAL-ABI" :canonical-abi-record
    "B4-IMPORT" :import-effect-capability-schema-provider
    "B4-EXPORT" :export-schema-ownership-lifetime
    "B4-MEMORY" :linear-memory-lifetime-pointer-policy
    "B4-BOUNDS" :bounds-check-elision-proof
    "B4-NONDETERMINISM" :replay-nondeterminism-record
    "B4-ASYNC" :async-effect-scheduling-metadata
    "B4-WASI-ASYNC" :typed-async-stream-future-abi-record
    "B4-SIMD" :simd-feature-and-certificate-record
    "B4-ATOMIC" :shared-memory-ordering-record
    "B4-HOST-SCHEMA" :host-boundary-schema
    "B4-MANIFEST" :complete-wasm-artifact-manifest
    :b4-document-evidence))

(defn b4-document-feature-requirement
  [id]
  (case id
    "B4-TARGET" :component-model-wasm32
    "B4-COMPONENT" :component-model
    "B4-CANONICAL-ABI" :canonical-abi
    "B4-IMPORT" :declared-import-capability
    "B4-EXPORT" :stable-export-schema
    "B4-MEMORY" :linear-memory-plan
    "B4-BOUNDS" :proof-backed-bounds-elision
    "B4-NONDETERMINISM" :replay-recording
    "B4-ASYNC" :host-async-metadata
    "B4-WASI-ASYNC" :wasi-0.3-async-component
    "B4-SIMD" :simd-feature-record
    "B4-ATOMIC" :shared-memory-atomics
    "B4-HOST-SCHEMA" :host-boundary-schema
    "B4-MANIFEST" :wasm-artifact-manifest
    :wasm-feature-record))

(defn b4-document-fail!
  [id source-path subject extra]
  (fail! id
         "B4 Wasm backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b4-wasm-backend-document
                 :stage (or (:stage subject)
                            :b4-wasm-backend-document-coverage)
                 :backend :gravity.backend/wasm
                 :profile (or (:profile subject) :hosted)
                 :embedding (or (:embedding subject) :wasi-0.3-component)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :host-call)
                 :domain-anchor (:domain-anchor subject)
                 :import-id (or (:import-id subject) :gravity.host/clock-now)
                 :export-id (or (:export-id subject) :gravity/entry)
                 :interface-item-id (or (:interface-item-id subject)
                                        :gravity-host/clock-now)
                 :world-id (or (:world-id subject) :gravity-stage0-world)
                 :canonical-abi-record-id
                 (or (:canonical-abi-record-id subject)
                     :canonical-abi/entry-v1)
                 :async-item-id (or (:async-item-id subject)
                                    :wasi-async/clock-future)
                 :feature-requirement
                 (or (:feature-requirement subject)
                     (b4-document-feature-requirement id))
                 :missing-evidence (or (:missing-evidence subject)
                                       (b4-document-missing-evidence id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit Wasm only from verified backend input with pinned target features, component contracts, canonical ABI records, import/export capability schemas, linear-memory and bounds evidence, async/replay records, host boundary schemas, feature fallbacks, and complete artifact manifests."}
                extra)))

(defn b4-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b4-document-override-diagnostics fail-kind)]
      (b4-document-fail!
       id source-path
       {:stage :b4-wasm-backend-document-coverage
        :artifact-id (str "b4-document-" (name fail-kind))
        :missing-evidence fail-kind
        :feature-requirement fail-kind}
       {:missing-fields [fail-kind]}))))

(def b4-document-wat
  (str "(module\n"
       "  (type $entry_t (func (param i64) (result i64)))\n"
       "  (import \"gravity:host/clock\" \"now\" (func $clock_now (result i64)))\n"
       "  (memory $memory 1 2)\n"
       "  (table $table 1 funcref)\n"
       "  (func $gravity_entry (export \"gravity_entry\") (param $x i64) (result i64)\n"
       "    local.get $x)\n"
       ")\n"))

(def b4-document-wit
  (str "package gravity:stage0;\n\n"
       "interface host {\n"
       "  now: async func() -> future<u64>;\n"
       "  stream-events: func() -> stream<u64>;\n"
       "}\n\n"
       "world gravity-stage0 {\n"
       "  import host;\n"
       "  export gravity-entry: func(x: u64) -> u64;\n"
       "}\n"))

(defn b4-document-balanced-parens?
  [text]
  (loop [chars (seq text)
         depth 0]
    (cond
      (neg? depth) false
      (nil? chars) (zero? depth)
      (= \( (first chars)) (recur (next chars) (inc depth))
      (= \) (first chars)) (recur (next chars) (dec depth))
      :else (recur (next chars) depth))))

(defn b4-document-wat-structurally-valid?
  [text]
  (and (b4-document-balanced-parens? text)
       (str/includes? text "(module")
       (str/includes? text "(import")
       (str/includes? text "(memory")
       (str/includes? text "(table")
       (str/includes? text "(export \"gravity_entry\"")))

(defn b4-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b4-wasm-backend-diagnostic-stream
   :stage :b4-wasm-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b4-wasm-backend-document-coverage
            :backend :gravity.backend/wasm
            :message-key (keyword "backend-wasm" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b4-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B4-IMPORT" :wasm-host-import
                      "B4-EXPORT" :host-export
                      "B4-ASYNC" :async-host-call
                      "B4-WASI-ASYNC" :future-stream-lowering
                      "B4-SIMD" :vector-lowering
                      "B4-ATOMIC" :atomic-compare-exchange
                      :host-call)
            :domain-anchor (when (= id "B4-SIMD") :simd-domain)
            :import-id :gravity.host/clock-now
            :export-id :gravity/entry
            :interface-item-id :gravity-host/clock-now
            :world-id :gravity-stage0-world
            :canonical-abi-record-id :canonical-abi/entry-v1
            :async-item-id :wasi-async/clock-future
            :profile :hosted
            :embedding :wasi-0.3-component
            :feature-requirement (b4-document-feature-requirement id)
            :missing-evidence (b4-document-missing-evidence id)
            :fallback-status :rejected
            :facts {:ambient-host-authority :rejected
                    :raw-pointer-escape :rejected
                    :replay-required? true}
            :remediation [{:kind :declare-wasm-component-contract}
                          {:kind :attach-capability-and-host-schema}
                          {:kind :record-replay-and-async-abi}]
            :redactions []
            :ordering-key [id :b4-wasm-backend-document-coverage
                           :wasi-0.3-component]})
         b4-document-diagnostic-ids
         (range))
   :status :complete})

