(defn b4-document-validate!
  [source-path artifact]
  (let [hosted (:hosted-lowering-artifact artifact)
        manifest (:wasm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b4-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-hosted-lowering-artifact (:kind hosted))
      (b4-document-fail! "B4-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-artifact]}))
    (when-not (= :complete (get-in hosted
                                   [:capability-based-proof :status]))
      (b4-document-fail! "B4-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-proof]}))
    (when-not (= :pinned (get-in manifest
                                 [:target-feature-record :status]))
      (b4-document-fail! "B4-TARGET" source-path manifest
                         {:missing-fields [:target-feature-record]}))
    (when-not (= :complete (get-in manifest
                                   [:component-contract-manifest :status]))
      (b4-document-fail! "B4-COMPONENT" source-path manifest
                         {:missing-fields [:component-contract]}))
    (when-not (= :complete (get-in manifest
                                   [:canonical-abi-manifest :status]))
      (b4-document-fail! "B4-CANONICAL-ABI" source-path manifest
                         {:missing-fields [:canonical-abi]}))
    (when-not (= :declared (get-in manifest
                                   [:import-capability-manifest :status]))
      (b4-document-fail! "B4-IMPORT" source-path manifest
                         {:missing-fields [:import-capabilities]}))
    (when-not (= :complete (get-in manifest
                                   [:export-schema-manifest :status]))
      (b4-document-fail! "B4-EXPORT" source-path manifest
                         {:missing-fields [:export-schemas]}))
    (when-not (= :complete (get-in manifest
                                   [:linear-memory-and-table-plan :status]))
      (b4-document-fail! "B4-MEMORY" source-path manifest
                         {:missing-fields [:linear-memory-plan]}))
    (when-not (= [:safe2-bounds :safe2-lifetime]
                 (get-in manifest
                         [:linear-memory-and-table-plan
                          :bounds-and-lifetime-proofs]))
      (b4-document-fail! "B4-BOUNDS" source-path manifest
                         {:missing-fields [:bounds-proof]}))
    (when-not (= :complete (get-in manifest
                                   [:replay-and-nondeterminism-record
                                    :status]))
      (b4-document-fail! "B4-NONDETERMINISM" source-path manifest
                         {:missing-fields [:replay-record]}))
    (when-not (= :complete (get-in manifest
                                   [:wasi-component-async-abi-manifest
                                    :status]))
      (b4-document-fail! "B4-WASI-ASYNC" source-path manifest
                         {:missing-fields [:wasi-async-abi]}))
    (when-not (= :complete (get-in manifest
                                   [:simd-feature-record :status]))
      (b4-document-fail! "B4-SIMD" source-path manifest
                         {:missing-fields [:simd-feature-record]}))
    (when-not (= :complete (get-in manifest
                                   [:atomic-feature-record :status]))
      (b4-document-fail! "B4-ATOMIC" source-path manifest
                         {:missing-fields [:atomic-feature-record]}))
    (when-not (= :complete (get-in manifest
                                   [:host-boundary-schema-manifest :status]))
      (b4-document-fail! "B4-HOST-SCHEMA" source-path manifest
                         {:missing-fields [:host-boundary-schema]}))
    (when-not (b4-document-wat-structurally-valid? b4-document-wat)
      (b4-document-fail! "B4-MANIFEST" source-path manifest
                         {:missing-fields [:wat-structural-validation]}))
    (when-not (every? #(contains? manifest %)
                      [:target-feature-record
                       :linear-memory-and-table-plan
                       :wasm-modules
                       :component-model-artifact
                       :component-contract-manifest
                       :canonical-abi-manifest
                       :import-capability-manifest
                       :export-schema-manifest
                       :host-boundary-schema-manifest
                       :wasi-component-async-abi-manifest
                       :component-composition-plan
                       :host-binding-stubs
                       :runtime-helper-manifest
                       :source-map-and-generated-origin-map
                       :replay-and-nondeterminism-record])
      (b4-document-fail! "B4-MANIFEST" source-path manifest
                         {:missing-fields [:wasm-artifact-manifest]}))
    (when-not (= (set b4-document-diagnostic-ids) diagnostics)
      (b4-document-fail! "B4-MANIFEST" source-path
                         (:b4-diagnostic-stream artifact)
                         {:missing-fields [:b4-diagnostics]})))
  :complete)

(defn b4-document-capability-proof
  [artifact]
  (let [manifest (:wasm-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b4-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:hosted-lowering-artifact
                           :capability-based-proof :status]))
     :target-feature-record-pinned?
     (= :pinned (get-in manifest [:target-feature-record :status]))
     :component-contract-covered?
     (= :complete (get-in manifest
                          [:component-contract-manifest :status]))
     :canonical-abi-covered?
     (= :complete (get-in manifest
                          [:canonical-abi-manifest :status]))
     :imports-capability-declared?
     (= :declared (get-in manifest
                          [:import-capability-manifest :status]))
     :exports-schema-declared?
     (= :complete (get-in manifest
                          [:export-schema-manifest :status]))
     :linear-memory-pointer-policy-covered?
     (= :complete (get-in manifest
                          [:linear-memory-and-table-plan :status]))
     :bounds-proof-covered?
     (= [:safe2-bounds :safe2-lifetime]
        (get-in manifest
                [:linear-memory-and-table-plan
                 :bounds-and-lifetime-proofs]))
     :replay-nondeterminism-covered?
     (= :complete (get-in manifest
                          [:replay-and-nondeterminism-record :status]))
     :async-and-wasi-async-covered?
     (= :complete (get-in manifest
                          [:wasi-component-async-abi-manifest :status]))
     :simd-feature-covered?
     (= :complete (get-in manifest [:simd-feature-record :status]))
     :atomic-feature-covered?
     (= :complete (get-in manifest [:atomic-feature-record :status]))
     :host-boundary-schema-covered?
     (= :complete (get-in manifest
                          [:host-boundary-schema-manifest :status]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:target-feature-record
              :linear-memory-and-table-plan
              :wasm-modules
              :component-model-artifact
              :component-contract-manifest
              :canonical-abi-manifest
              :import-capability-manifest
              :export-schema-manifest
              :host-boundary-schema-manifest
              :wasi-component-async-abi-manifest
              :component-composition-plan
              :host-binding-stubs
              :runtime-helper-manifest
              :source-map-and-generated-origin-map
              :replay-and-nondeterminism-record])
     :wat-structurally-valid?
     (b4-document-wat-structurally-valid? b4-document-wat)
     :diagnostics-covered?
     (= (set b4-document-diagnostic-ids) diagnostics)
     :external-wasm-toolchain-validation?
     :not-available-in-current-environment
     :status :complete}))

(defn b4-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b4-document-source-overrides module)
        _ (b4-document-validate-source-overrides! source-path
                                                  source-overrides)
        hosted-artifact (hosted-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id hosted-artifact)
        manifest (b4-document-wasm-manifest input-id)
        diagnostic-stream (b4-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b4-wasm-backend-document-artifact
         :task "P07-D101"
         :document-set ["B4"]
         :governing-document b4-document-governing-document
         :pass {:name :b4-wasm-backend-document-coverage
                :input :hosted-lowering-artifact
                :output :b4-wasm-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c14-target-lowering :wasm-target-features
                           :component-contracts :canonical-abi
                           :import-capabilities :export-schemas
                           :host-boundary-schemas :async-abi
                           :replay-record :linear-memory-plan]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :schemas :safety
                            :proofs :profile :target
                            :artifact-provenance]
                :emits [:wasm-backend-manifest :target-feature-record
                        :linear-memory-and-table-plan :wasm-modules
                        :component-model-artifact
                        :component-contract-manifest
                        :canonical-abi-manifest
                        :import-capability-manifest
                        :export-schema-manifest
                        :host-boundary-schema-manifest
                        :wasi-component-async-abi-manifest
                        :component-composition-plan
                        :replay-and-nondeterminism-record
                        :b4-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b4-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :hosted-lowering-artifact
         (select-keys hosted-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :hosted-lowering-results])
         :hosted-lowering-artifact-kind (:kind hosted-artifact)
         :hosted-lowering-artifact-hash input-id
         :wasm-backend-manifest manifest
         :target-feature-record (:target-feature-record manifest)
         :linear-memory-and-table-plan
         (:linear-memory-and-table-plan manifest)
         :wasm-modules (:wasm-modules manifest)
         :component-model-artifact (:component-model-artifact manifest)
         :component-contract-manifest
         (:component-contract-manifest manifest)
         :canonical-abi-manifest (:canonical-abi-manifest manifest)
         :import-capability-manifest
         (:import-capability-manifest manifest)
         :export-schema-manifest (:export-schema-manifest manifest)
         :host-boundary-schema-manifest
         (:host-boundary-schema-manifest manifest)
         :wasi-component-async-abi-manifest
         (:wasi-component-async-abi-manifest manifest)
         :component-composition-plan
         (:component-composition-plan manifest)
         :replay-and-nondeterminism-record
         (:replay-and-nondeterminism-record manifest)
         :rejected-design-coverage
         [{:design :ambient-host-import
           :diagnostic "B4-IMPORT" :status :rejected}
          {:design :raw-linear-memory-offset-export
           :diagnostic "B4-MEMORY" :status :rejected}
          {:design :sandbox-as-capability-check-substitute
           :diagnostic "B4-IMPORT" :status :rejected}
          {:design :unrecorded-nondeterministic-host-call
           :diagnostic "B4-NONDETERMINISM" :status :rejected}
          {:design :runtime-feature-probing-for-eligible-profile
           :diagnostic "B4-TARGET" :status :rejected}
          {:design :authority-amplifying-composition
           :diagnostic "B4-COMPONENT" :status :rejected}
          {:design :opaque-host-promise-for-wasi-async
           :diagnostic "B4-WASI-ASYNC" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b4-wasm-backend-conformance-criteria-record
          :core-module-and-component-model :emitted
          :wit-contracts :emitted
          :canonical-abi-validation :complete
          :wasi-async-fixtures [:async-func :stream :future]
          :import-capability-manifests [:browser :wasi :custom]
          :composition-capability-preservation :complete
          :export-schema-validation :complete
          :host-boundary-schema-validation :complete
          :pointer-handle-lifetime-tests :recorded
          :memory-growth-bounds-check-behavior :recorded
          :rejected-ambient-imports-and-pointer-escape :covered
          :invalid-contract-diagnostics :covered
          :replay-records :covered
          :async-replay-cancellation-ordering-backpressure :covered
          :simd-and-atomics-feature-records :covered
          :metadata-preservation :preserved
          :differential-execution :mir-reference-recorded
          :status :passed}
         :b4-diagnostic-stream diagnostic-stream
         :b4-document-results
         {:documents ["B4"]
          :task "P07-D101"
          :required-diagnostic-ids b4-document-diagnostic-ids
          :hosted-lowering-input-status :complete
          :target-feature-status :complete
          :component-contract-status :complete
          :canonical-abi-status :complete
          :import-status :complete
          :export-status :complete
          :linear-memory-status :complete
          :bounds-status :complete
          :replay-status :complete
          :async-status :complete
          :wasi-async-status :complete
          :simd-status :complete
          :atomic-status :complete
          :host-schema-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b4-document-validate! source-path artifact-base)
        capability-proof (b4-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b4-document-file-artifact
  [path]
  (b4-document-source-artifact path (slurp path)))

(def b5-document-governing-document
  "docs/phase-07-backend-architecture/102-b5-jvm-backend-design.md")

(def b5-document-diagnostic-ids
  ["B5-TARGET"
   "B5-NULL"
   "B5-EXCEPTION"
   "B5-REFLECTION"
   "B5-CLASSLOADING"
   "B5-INTEROP"
   "B5-RESOURCE"
   "B5-THREAD"
   "B5-NATIVE-IMAGE"
   "B5-PROFILE"
   "B5-MANIFEST"])

(def b5-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b5-document-diagnostic-ids)))

(defn b5-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b5-document])
      (get-in module [:metadata :backend :hosted-lowering])
      (get-in module [:metadata :backend :hosted])
      {}))

(defn b5-document-missing-fact
  [id]
  (case id
    "B5-TARGET" :classfile-jvm-module-packaging-target
    "B5-NULL" :nullability-wrapper-or-opaque-check
    "B5-EXCEPTION" :host-exception-translation
    "B5-REFLECTION" :reflection-dynamic-policy-capability
    "B5-CLASSLOADING" :classloader-policy
    "B5-INTEROP" :java-boundary-descriptor
    "B5-RESOURCE" :deterministic-linear-resource-cleanup
    "B5-THREAD" :thread-monitor-scheduler-effect-record
    "B5-NATIVE-IMAGE" :native-image-configuration
    "B5-PROFILE" :hosted-profile-boundary
    "B5-MANIFEST" :complete-jvm-artifact-manifest
    :b5-document-evidence))

(defn b5-document-jvm-symbol
  [id]
  (case id
    "B5-TARGET" "gravity.stage0.Hosted"
    "B5-NULL" "gravity.stage0.Hosted.nullable"
    "B5-EXCEPTION" "gravity.stage0.Hosted.translateException"
    "B5-REFLECTION" "java.lang.reflect.Method"
    "B5-CLASSLOADING" "java.lang.ClassLoader#defineClass"
    "B5-INTEROP" "gravity.stage0.Hosted.entry"
    "B5-RESOURCE" "gravity.stage0.Hosted.Resource"
    "B5-THREAD" "java.lang.Thread"
    "B5-NATIVE-IMAGE" "native-image-config"
    "B5-PROFILE" "gravity.lower-profile.export"
    "B5-MANIFEST" "gravity/jvm-backend-manifest"
    "gravity.stage0.Hosted"))

(defn b5-document-selected-adapter
  [id]
  (case id
    "B5-NULL" :option-wrapper
    "B5-EXCEPTION" :gravity-error-or-panic-adapter
    "B5-REFLECTION" :declared-reflection-manifest-or-reject
    "B5-CLASSLOADING" :direct-call-or-reject
    "B5-RESOURCE" :auto-closeable-safe5-cleanup
    "B5-THREAD" :runtime-scheduler-provider
    "B5-NATIVE-IMAGE" :generated-native-image-config
    "B5-PROFILE" :profile-boundary-rejection
    :jvm-backend-record))

(defn b5-document-fail!
  [id source-path subject extra]
  (fail! id
         "B5 JVM backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b5-jvm-backend-document
                 :stage (or (:stage subject)
                            :b5-jvm-backend-document-coverage)
                 :backend :gravity.backend/jvm
                 :profile (or (:profile subject) :hosted)
                 :classfile-target (or (:classfile-target subject) 65)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :host-call)
                 :domain-anchor (:domain-anchor subject)
                 :jvm-symbol (or (:jvm-symbol subject)
                                 (b5-document-jvm-symbol id))
                 :missing-type-effect-capability-cleanup-fact
                 (or (:missing-type-effect-capability-cleanup-fact subject)
                     (b5-document-missing-fact id))
                 :selected-adapter-or-rejection
                 (or (:selected-adapter-or-rejection subject)
                     (b5-document-selected-adapter id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit JVM artifacts only from verified hosted backend input with pinned classfile/JVM/module/package policy, nullability and exception maps, explicit reflection/classloading/thread/native-image capabilities, deterministic resource cleanup, profile boundary checks, source maps, and complete JVM manifests."}
                extra)))

(defn b5-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b5-document-override-diagnostics fail-kind)]
      (b5-document-fail!
       id source-path
       {:stage :b5-jvm-backend-document-coverage
        :artifact-id (str "b5-document-" (name fail-kind))
        :missing-type-effect-capability-cleanup-fact fail-kind
        :jvm-symbol (name fail-kind)}
       {:missing-fields [fail-kind]}))))

(def b5-document-java-source
  (str "package gravity.stage0;\n\n"
       "import java.util.Optional;\n"
       "import java.util.concurrent.Callable;\n\n"
       "public final class Hosted {\n"
       "  private Hosted() {}\n\n"
       "  public static long entry(long x) {\n"
       "    return x;\n"
       "  }\n\n"
       "  public static Optional<String> nullable(String value) {\n"
       "    return Optional.ofNullable(value);\n"
       "  }\n\n"
       "  public static String translateException(Callable<String> thunk) {\n"
       "    try {\n"
       "      return thunk.call();\n"
       "    } catch (Exception ex) {\n"
       "      throw new GravityPanic(ex);\n"
       "    }\n"
       "  }\n\n"
       "  public static Resource openResource() {\n"
       "    return new Resource();\n"
       "  }\n\n"
       "  public static final class GravityPanic extends RuntimeException {\n"
       "    public GravityPanic(Throwable cause) {\n"
       "      super(cause);\n"
       "    }\n"
       "  }\n\n"
       "  public static final class Resource implements AutoCloseable {\n"
       "    private boolean closed;\n\n"
       "    @Override\n"
       "    public void close() {\n"
       "      closed = true;\n"
       "    }\n\n"
       "    public boolean isClosed() {\n"
       "      return closed;\n"
       "    }\n"
       "  }\n"
       "}\n"))

(def b5-document-module-info
  (str "module gravity.stage {\n"
       "  exports gravity.stage0;\n"
       "}\n"))

(defn b5-document-java-structurally-valid?
  [source]
  (and (str/includes? source "package gravity.stage0;")
       (str/includes? source "public final class Hosted")
       (str/includes? source "Optional<String>")
       (str/includes? source "GravityPanic")
       (str/includes? source "implements AutoCloseable")
       (str/includes? source "Callable<String>")))

(defn b5-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b5-jvm-backend-diagnostic-stream
   :stage :b5-jvm-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b5-jvm-backend-document-coverage
            :backend :gravity.backend/jvm
            :message-key (keyword "backend-jvm" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b5-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B5-NULL" :host-null-boundary
                      "B5-EXCEPTION" :host-exception-boundary
                      "B5-RESOURCE" :linear-resource-cleanup
                      "B5-THREAD" :host-thread-call
                      :host-call)
            :domain-anchor (when (= id "B5-INTEROP") :java-interop)
            :jvm-symbol (b5-document-jvm-symbol id)
            :classfile-target 65
            :profile :hosted
            :missing-type-effect-capability-cleanup-fact
            (b5-document-missing-fact id)
            :selected-adapter-or-rejection (b5-document-selected-adapter id)
            :fallback-status :rejected
            :facts {:java-null-policy :option-result-checked-or-opaque
                    :host-exception-policy :translate
                    :hidden-dynamic-behavior :rejected}
            :remediation [{:kind :pin-jvm-target-record}
                          {:kind :attach-java-interop-descriptor}
                          {:kind :translate-null-exception-resource-boundary}]
            :redactions []
            :ordering-key [id :b5-jvm-backend-document-coverage
                           :jvm-21]})
         b5-document-diagnostic-ids
         (range))
   :status :complete})

(defn b5-document-jvm-manifest
  [input-id]
  (let [source-hash (c4-artifact-id b5-document-java-source)
        module-hash (c4-artifact-id b5-document-module-info)]
    {:artifact :gravity/jvm-backend-manifest
     :backend :gravity.backend/jvm
     :target {:classfile 65
              :runtime :jvm-21
              :module-system :named
              :status :pinned}
     :emits #{:class-files :jar :interop-descriptors :debug-map}
     :requires #{:hosted-profile :exception-map :nullability-map
                 :runtime-provider-manifest}
