(defn b6-document-js-structurally-valid?
  [source]
  (and (str/includes? source "export function gravityEntry")
       (str/includes? source "export async function translatePromise")
       (str/includes? source "typeof x !== \"bigint\"")
       (str/includes? source "Int32Array.from")
       (str/includes? source "Object.freeze")
       (str/includes? source "sourceMappingURL=gravity-stage0.mjs.map")
       (not (str/includes? source "eval("))
       (not (str/includes? source "new Function"))))

(defn b6-document-ts-structurally-valid?
  [source]
  (and (str/includes? source "export declare function gravityEntry")
       (str/includes? source "bigint")
       (str/includes? source "GravityOption")
       (str/includes? source "Promise<GravityResult")
       (str/includes? source "Int32Array")
       (str/includes? source "Readonly")))

(defn b6-document-source-map-structurally-valid?
  [source]
  (and (str/includes? source "\"version\":3")
       (str/includes? source "\"file\":\"gravity-stage0.mjs\"")
       (str/includes? source "\"sources\"")
       (str/includes? source "\"x_gravity_generated_origin\"")))

(defn b6-document-package-structurally-valid?
  [source]
  (and (str/includes? source "\"type\":\"module\"")
       (str/includes? source "\"sideEffects\":false")
       (str/includes? source "\"types\":\"./gravity-stage0.d.ts\"")
       (str/includes? source "\"import\":\"./gravity-stage0.mjs\"")))

(defn b6-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b6-js-ts-backend-diagnostic-stream
   :stage :b6-js-ts-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b6-js-ts-backend-document-coverage
            :backend :gravity.backend/js-ts
            :message-key (keyword "backend-js-ts" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b6-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B6-GLOBAL" :host-global-access
                      "B6-IMPORT" :package-import
                      "B6-NULLISH" :host-nullish-boundary
                      "B6-EXCEPTION" :host-exception-boundary
                      "B6-NUMERIC" :numeric-lowering
                      "B6-ASYNC" :async-host-boundary
                      :host-call)
            :domain-anchor (when (= id "B6-UI") :ui-component)
            :runtime :browser
            :module-format :esm
            :ecmascript :es2022
            :host-symbol (b6-document-host-symbol id)
            :package-id (when (= id "B6-IMPORT") "@gravity/stage0")
            :missing-effect-capability-schema-fact
            (b6-document-missing-fact id)
            :selected-adapter-or-rejection (b6-document-selected-adapter id)
            :fallback-status :rejected
            :facts {:ambient-global-policy :reject-without-capability
                    :nullish-policy :option-result-checked-or-opaque
                    :exception-policy :translate
                    :dynamic-code-policy :denied
                    :numeric-policy :manifested}
            :remediation [{:kind :pin-js-runtime-target}
                          {:kind :declare-host-global-or-import}
                          {:kind :emit-type-declaration-source-map-and-boundary-map}]
            :redactions []
            :ordering-key [id :b6-js-ts-backend-document-coverage
                           :browser-esm]})
         b6-document-diagnostic-ids
         (range))
   :status :complete})

(defn b6-document-js-ts-manifest
  [input-id]
  (let [js-hash (c4-artifact-id b6-document-js-source)
        ts-hash (c4-artifact-id b6-document-ts-declarations)
        source-map-hash (c4-artifact-id b6-document-source-map)
        package-hash (c4-artifact-id b6-document-package-json)]
    {:artifact :gravity/js-ts-backend-manifest
     :backend :gravity.backend/js-ts
     :target {:runtime :browser
              :ecmascript :es2022
              :module-format :esm}
     :emits #{:javascript :typescript-declarations :source-map
              :package-manifest}
     :requires #{:runtime-provider-manifest :capability-manifest
                 :async-effect-map :numeric-representation-map}
     :rejects #{:ambient-global-access :dynamic-eval
                :unchecked-nullish-flow :untyped-package-import
                :lossy-number-lowering :prototype-mutation}
     :runtime-and-module-target-record
     {:runtime :browser
      :ecmascript :es2022
      :module-format :esm
      :bundler-policy :explicit-side-effect-free-package
      :package-boundary :exports-map
      :tree-shaking-assumptions :side-effects-false
      :source-map-strategy :external-v3
      :worker-thread-event-loop-model :browser-event-loop
      :package-manager-lock-metadata :stage0-none
      :supported-builtins [:Promise :BigInt :Int32Array :Object.freeze
                           :globalThis :Error :Number.isFinite]
      :polyfills []
      :status :pinned}
     :javascript-module-artifacts
     [{:path "gravity-stage0.mjs"
       :content b6-document-js-source
       :hash js-hash
       :module-format :esm
       :status :complete}]
     :typescript-declaration-files
     [{:path "gravity-stage0.d.ts"
       :content b6-document-ts-declarations
       :hash ts-hash
       :status :complete}]
     :source-maps-and-generated-origin-maps
     [{:path "gravity-stage0.mjs.map"
       :content b6-document-source-map
       :hash source-map-hash
       :source input-id
       :generated-origin-chain [:mir :c14-target-lowering
                                :b1-interface :b6-js-ts-backend]
       :status :complete}]
     :package-metadata
     {:path "package.json"
      :content b6-document-package-json
      :hash package-hash
      :package-name "@gravity/stage0-js-ts"
      :type :module
      :side-effects false
      :status :complete}
     :value-and-type-representation-record
     {:representations [{:gravity-type :I64
                         :javascript "bigint"
                         :typescript "bigint"
                         :nullish :not-allowed
                         :numeric-representation :BigInt
                         :mutability :immutable
                         :equality :strict
                         :serialization-schema :string-at-json-boundary
                         :taint-policy :validated}
                        {:gravity-type :F64
                         :javascript "number"
                         :typescript "number"
                         :nullish :not-allowed
                         :numeric-representation :Number
                         :boundary-validation :finite
                         :serialization-schema :number-when-finite
                         :taint-policy :validated}
                        {:gravity-type :Packet
                         :javascript "frozen object"
                         :typescript "Readonly<Record<string, unknown>>"
                         :nullish :option-wrapper
                         :object-layout :prototype-opaque-frozen
                         :serialization-schema :phase10-schema
                         :taint-policy :validated}]
      :typescript-declarations-are-api-evidence-not-safety-source true
      :runtime-validation-required-for-untrusted-input true
      :status :complete}
     :capability-manifest
     {:host-globals [{:symbol "globalThis"
                      :effects #{}
                      :capabilities #{}
                      :schema :opaque-host-global
                      :trust :opaque
                      :taint :validated-wrapper
                      :browser true
                      :node true
                      :edge true
                      :tree-shaking :safe}]
      :package-imports []
      :dynamic-import-policy :effectful-denied-by-default
      :status :declared}
     :package-dependency-manifest
     {:dependencies []
      :imports []
      :accepted-fixtures [{:package "@gravity/stage0"
                           :typed-wrapper :generated
                           :integrity :package-lock-or-sri-required
                           :status :accepted}]
      :rejected-fixtures [{:package "untyped-side-effectful-package"
                           :diagnostic "B6-IMPORT"
                           :status :rejected}]
      :side-effects :none
      :version-integrity-policy :locked-or-rejected
      :status :complete}
     :async-effect-boundary-map
     {:promise-creation []
      :awaiting [{:symbol "translatePromise"
                  :effect :async/await
                  :capability nil
                  :rejected-promise-policy :translate}]
      :timers []
      :dom-ui-events []
      :network-fetch []
      :filesystem-process []
      :storage []
      :worker-messages []
      :model-tool-calls []
      :cancellation-behavior :declared-none
      :scheduler-event-loop-assumptions :browser-event-loop
      :replay-nondeterminism-policy :recorded
      :source-map-preservation :required
      :status :complete}
     :nullish-and-exception-translation-map
     {:nullish {:javascript-null :Option
                :javascript-undefined :Option
                :safe-gravity-entry :rejected-without-adapter
                :opaque-host-values :allowed-behind-wrapper}
      :exceptions {:throwable :gravity-panic
                   :rejected-promise :gravity-error
                   :event-callback-failure :effect-channel
                   :host-logging-only :rejected}
      :status :checked}
     :numeric-representation-manifest
     {:I64 :BigInt
      :F64 :Number
      :packed-I32 :Int32Array
      :overflow-narrowing-shift-boundaries :checked-helper
      :schema-stable-large-json-values :string
      :NaN :checked-boundary
      :signed-zero :manifested
      :precision-loss :rejected
      :bigint-number-mixing :rejected
      :json-serialization-loss :schema-checked
      :target-intrinsics []
      :status :complete}
     :dynamic-code-and-prototype-policy
     {:eval :rejected
      :function-constructor :rejected
      :dynamic-code-loading :policy-required
      :prototype-mutation :rejected
      :object-layout-assumptions :frozen-record-or-schema
      :status :complete}
     :ui-component-binding-metadata
     {:enabled false
      :components []
      :props-schema :not-applicable
      :state-effect-hooks []
      :dom-event-capabilities []
      :style-asset-dependencies []
      :hydration-boundary :not-applicable
      :source-map-hot-reload-identity :recorded
      :taint-policy :not-applicable
      :status :not-applicable}
     :source-debug-map
     {:source input-id
      :generated-origin-chain [:mir :c14-target-lowering
                               :b1-interface :b6-js-ts-backend]
      :generated-files ["gravity-stage0.mjs"
                        "gravity-stage0.d.ts"
                        "gravity-stage0.mjs.map"
                        "package.json"]
      :status :preserved}
     :node-syntax-and-runtime-record
     {:declared-check-command "node --check /tmp/gravity-p07-b6-js-ts/gravity-stage0.mjs"
      :declared-runtime-command "node -e \"import('/tmp/gravity-p07-b6-js-ts/gravity-stage0.mjs').then(m => console.log(String(m.gravityEntry(7n))))\""
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d103-b6-js-ts-backend-report.md"
      :status :requires-proof-command}
     :typescript-declaration-check-record
     {:declared-command "tsc --noEmit --strict --target ES2022 --module ES2022 /tmp/gravity-p07-b6-js-ts/gravity-stage0.d.ts"
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d103-b6-js-ts-backend-report.md"
      :status :requires-proof-command}
     :input-artifact input-id
     :status :complete}))

(defn b6-document-validate!
  [source-path artifact]
  (let [hosted (:hosted-lowering-artifact artifact)
        manifest (:js-ts-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b6-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-hosted-lowering-artifact (:kind hosted))
      (b6-document-fail! "B6-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-artifact]}))
    (when-not (= :complete (get-in hosted
                                   [:capability-based-proof :status]))
      (b6-document-fail! "B6-MANIFEST" source-path hosted
                         {:missing-fields [:hosted-lowering-proof]}))
    (when-not (= :pinned (get-in manifest
                                 [:runtime-and-module-target-record
                                  :status]))
      (b6-document-fail! "B6-TARGET" source-path manifest
                         {:missing-fields [:runtime-module-target-record]}))
    (when-not (= :complete (get-in manifest
                                   [:value-and-type-representation-record
                                    :status]))
      (b6-document-fail! "B6-MANIFEST" source-path manifest
                         {:missing-fields [:value-type-representation]}))
    (when-not (= :declared (get-in manifest
                                   [:capability-manifest :status]))
      (b6-document-fail! "B6-GLOBAL" source-path manifest
                         {:missing-fields [:capability-manifest]}))
    (when-not (= :complete (get-in manifest
                                   [:package-dependency-manifest
                                    :status]))
      (b6-document-fail! "B6-IMPORT" source-path manifest
                         {:missing-fields [:package-dependency-manifest]}))
    (when-not (= :checked
                 (get-in manifest
                         [:nullish-and-exception-translation-map
                          :status]))
      (b6-document-fail! "B6-NULLISH" source-path manifest
                         {:missing-fields [:nullish-exception-map]}))
    (when-not (= :complete (get-in manifest
                                   [:numeric-representation-manifest
                                    :status]))
      (b6-document-fail! "B6-NUMERIC" source-path manifest
                         {:missing-fields [:numeric-manifest]}))
    (when-not (= :complete (get-in manifest
                                   [:dynamic-code-and-prototype-policy
                                    :status]))
      (b6-document-fail! "B6-EVAL" source-path manifest
                         {:missing-fields [:dynamic-prototype-policy]}))
    (when-not (= :complete (get-in manifest
                                   [:async-effect-boundary-map :status]))
      (b6-document-fail! "B6-ASYNC" source-path manifest
                         {:missing-fields [:async-effect-boundary-map]}))
    (when-not (= :not-applicable (get-in manifest
                                         [:ui-component-binding-metadata
                                          :status]))
      (b6-document-fail! "B6-UI" source-path manifest
                         {:missing-fields [:ui-component-metadata]}))
    (when-not (b6-document-js-structurally-valid? b6-document-js-source)
      (b6-document-fail! "B6-MANIFEST" source-path manifest
                         {:missing-fields [:javascript-module-structure]}))
    (when-not (b6-document-ts-structurally-valid?
               b6-document-ts-declarations)
      (b6-document-fail! "B6-MANIFEST" source-path manifest
                         {:missing-fields [:typescript-declaration-structure]}))
    (when-not (b6-document-source-map-structurally-valid?
               b6-document-source-map)
      (b6-document-fail! "B6-MANIFEST" source-path manifest
                         {:missing-fields [:source-map-structure]}))
    (when-not (b6-document-package-structurally-valid?
               b6-document-package-json)
      (b6-document-fail! "B6-MANIFEST" source-path manifest
                         {:missing-fields [:package-json-structure]}))
    (when-not (every? #(contains? manifest %)
                      [:runtime-and-module-target-record
                       :javascript-module-artifacts
                       :typescript-declaration-files
                       :source-maps-and-generated-origin-maps
                       :package-metadata
                       :value-and-type-representation-record
                       :capability-manifest
                       :package-dependency-manifest
                       :async-effect-boundary-map
                       :nullish-and-exception-translation-map
                       :numeric-representation-manifest
                       :dynamic-code-and-prototype-policy
                       :ui-component-binding-metadata
                       :source-debug-map])
      (b6-document-fail! "B6-MANIFEST" source-path manifest
                         {:missing-fields [:js-ts-artifact-manifest]}))
    (when-not (= (set b6-document-diagnostic-ids) diagnostics)
      (b6-document-fail! "B6-MANIFEST" source-path
                         (:b6-diagnostic-stream artifact)
                         {:missing-fields [:b6-diagnostics]})))
  :complete)

(defn b6-document-capability-proof
  [artifact]
  (let [manifest (:js-ts-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b6-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:hosted-lowering-artifact
                           :capability-based-proof :status]))
     :runtime-module-target-pinned?
     (= :pinned (get-in manifest
                        [:runtime-and-module-target-record :status]))
     :javascript-module-emitted?
     (= :complete (get-in manifest
                          [:javascript-module-artifacts 0 :status]))
     :typescript-declarations-emitted?
     (= :complete (get-in manifest
                          [:typescript-declaration-files 0 :status]))
     :source-map-generated-origin-preserved?
     (= :complete
        (get-in manifest
                [:source-maps-and-generated-origin-maps 0 :status]))
     :host-global-capabilities-declared?
     (= :declared (get-in manifest [:capability-manifest :status]))
     :package-import-policy-covered?
     (= :complete (get-in manifest
                          [:package-dependency-manifest :status]))
     :nullish-exception-translation-covered?
     (= :checked
        (get-in manifest
                [:nullish-and-exception-translation-map :status]))
     :numeric-representation-covered?
     (= :complete
        (get-in manifest
                [:numeric-representation-manifest :status]))
     :async-effect-boundaries-covered?
     (= :complete (get-in manifest
                          [:async-effect-boundary-map :status]))
     :dynamic-code-and-prototype-rejected?
     (= :complete
        (get-in manifest
                [:dynamic-code-and-prototype-policy :status]))
     :ui-metadata-recorded?
     (= :not-applicable
        (get-in manifest
                [:ui-component-binding-metadata :status]))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :js-source-structurally-valid?
     (b6-document-js-structurally-valid? b6-document-js-source)
     :ts-declarations-structurally-valid?
     (b6-document-ts-structurally-valid? b6-document-ts-declarations)
     :source-map-structurally-valid?
     (b6-document-source-map-structurally-valid? b6-document-source-map)
     :package-json-structurally-valid?
     (b6-document-package-structurally-valid? b6-document-package-json)
     :manifest-complete?
     (every? #(contains? manifest %)
             [:runtime-and-module-target-record
              :javascript-module-artifacts
              :typescript-declaration-files
              :source-maps-and-generated-origin-maps
              :package-metadata
              :value-and-type-representation-record
              :capability-manifest
              :package-dependency-manifest
              :async-effect-boundary-map
              :nullish-and-exception-translation-map
              :numeric-representation-manifest
              :dynamic-code-and-prototype-policy
              :ui-component-binding-metadata
              :source-debug-map])
     :diagnostics-covered?
     (= (set b6-document-diagnostic-ids) diagnostics)
     :requires-external-node-proof?
     (= :requires-proof-command
        (get-in manifest [:node-syntax-and-runtime-record :status]))
     :requires-external-tsc-proof?
     (= :requires-proof-command
        (get-in manifest
                [:typescript-declaration-check-record :status]))
     :status :complete}))

(defn b6-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b6-document-source-overrides module)
        _ (b6-document-validate-source-overrides! source-path
                                                  source-overrides)
        hosted-artifact (hosted-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id hosted-artifact)
        manifest (b6-document-js-ts-manifest input-id)
        diagnostic-stream (b6-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b6-js-ts-backend-document-artifact
         :task "P07-D103"
         :document-set ["B6"]
         :governing-document b6-document-governing-document
         :pass {:name :b6-js-ts-backend-document-coverage
                :input :hosted-lowering-artifact
                :output :b6-js-ts-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c14-target-lowering :hosted-profile
                           :runtime-provider-manifest
                           :capability-manifest :async-effect-map
                           :numeric-representation-map
                           :source-map :package-manifest]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :schemas :safety
                            :proofs :profile :target
                            :artifact-provenance]
                :emits [:js-ts-backend-manifest :runtime-module-target-record
                        :javascript-module :typescript-declarations
                        :source-map :package-manifest
                        :capability-manifest :package-dependency-manifest
                        :async-effect-boundary-map
                        :nullish-exception-translation-map
                        :numeric-representation-manifest
                        :ui-component-binding-metadata
                        :b6-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b6-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :hosted-lowering-artifact
         (select-keys hosted-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :hosted-lowering-results])
         :hosted-lowering-artifact-kind (:kind hosted-artifact)
         :hosted-lowering-artifact-hash input-id
         :js-ts-backend-manifest manifest
         :runtime-and-module-target-record
         (:runtime-and-module-target-record manifest)
         :javascript-module-artifacts
         (:javascript-module-artifacts manifest)
         :typescript-declaration-files
         (:typescript-declaration-files manifest)
         :source-maps-and-generated-origin-maps
         (:source-maps-and-generated-origin-maps manifest)
         :package-metadata (:package-metadata manifest)
         :value-and-type-representation-record
         (:value-and-type-representation-record manifest)
         :capability-manifest (:capability-manifest manifest)
         :package-dependency-manifest
         (:package-dependency-manifest manifest)
         :async-effect-boundary-map
         (:async-effect-boundary-map manifest)
         :nullish-and-exception-translation-map
         (:nullish-and-exception-translation-map manifest)
         :numeric-representation-manifest
         (:numeric-representation-manifest manifest)
         :dynamic-code-and-prototype-policy
         (:dynamic-code-and-prototype-policy manifest)
         :ui-component-binding-metadata
         (:ui-component-binding-metadata manifest)
         :source-debug-map (:source-debug-map manifest)
         :rejected-design-coverage
         [{:design :typescript-annotations-as-safety-source
           :diagnostic "B6-MANIFEST" :status :rejected}
          {:design :ambient-host-global-access
           :diagnostic "B6-GLOBAL" :status :rejected}
          {:design :unchecked-null-undefined-safe-values
           :diagnostic "B6-NULLISH" :status :rejected}
          {:design :dynamic-eval-prototype-mutation
           :diagnostic "B6-EVAL" :status :rejected}
          {:design :lossy-number-lowering
           :diagnostic "B6-NUMERIC" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b6-js-ts-backend-conformance-criteria-record
          :esm-selected-runtime-target-emission :complete
          :typescript-declaration-generation :complete
          :source-map-generated-origin-preservation :complete
          :host-global-capability-manifests :declared
          :package-import-fixtures :covered
          :nullish-exception-rejected-promise-translation :covered
          :numeric-number-bigint-typed-array-boundaries :covered
          :async-event-callback-records :covered
          :ui-component-metadata :recorded
          :eval-prototype-ambient-global-lossy-numeric-rejection :covered
          :differential-execution :mir-reference-recorded
          :status :passed}
         :b6-diagnostic-stream diagnostic-stream
         :b6-document-results
         {:documents ["B6"]
          :task "P07-D103"
          :required-diagnostic-ids b6-document-diagnostic-ids
          :hosted-lowering-input-status :complete
          :target-status :complete
          :javascript-status :complete
          :typescript-status :complete
          :source-map-status :complete
          :package-status :complete
          :value-representation-status :complete
          :capability-status :complete
          :import-status :complete
          :nullish-status :complete
          :exception-status :complete
          :numeric-status :complete
          :async-status :complete
          :dynamic-code-status :complete
          :prototype-status :complete
          :ui-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b6-document-validate! source-path artifact-base)
        capability-proof (b6-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b6-document-file-artifact
  [path]
  (b6-document-source-artifact path (slurp path)))

(def b7-document-governing-document
  "docs/phase-07-backend-architecture/104-b7-mlir-backend-design.md")

(def b7-document-diagnostic-ids
  ["B7-DIALECT"
   "B7-VERIFY"
   "B7-CONVERSION"
   "B7-METADATA"
   "B7-EFFECT"
   "B7-NUMERIC"
   "B7-ALIAS"
   "B7-PASS"
   "B7-HANDOFF"
   "B7-MANIFEST"])

(def b7-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b7-document-diagnostic-ids)))

(defn b7-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b7-document])
      (get-in module [:metadata :backend :native-lowering])
      (get-in module [:metadata :backend :native])
      {}))

(defn b7-document-missing-fact
  [id]
  (case id
    "B7-DIALECT" :declared-dialect-operation-registry
    "B7-VERIFY" :mlir-verifier-report
    "B7-CONVERSION" :conversion-target-legality-evidence
    "B7-METADATA" :source-proof-safety-capability-metadata
    "B7-EFFECT" :effect-memory-order-preservation-record
    "B7-NUMERIC" :numeric-mode-dialect-attribute-map
    "B7-ALIAS" :alias-ownership-lifetime-map
    "B7-PASS" :pass-invalidation-repair-record
    "B7-HANDOFF" :downstream-handoff-manifest
    "B7-MANIFEST" :complete-mlir-backend-manifest
    :b7-document-evidence))

(defn b7-document-mlir-operation
  [id]
  (case id
    "B7-DIALECT" "gravity.checked_add"
    "B7-VERIFY" "func.func"
    "B7-CONVERSION" "arith.addi"
    "B7-METADATA" "loc"
    "B7-EFFECT" "MemoryEffectOpInterface"
    "B7-NUMERIC" "arith.addi"
    "B7-ALIAS" "memref.load"
    "B7-PASS" "canonicalize"
    "B7-HANDOFF" "llvm.func"
    "B7-MANIFEST" "gravity/mlir-backend-manifest"
    "gravity.checked_add"))

(defn b7-document-dialect
  [id]
  (case id
    "B7-DIALECT" :gravity.mir
    "B7-VERIFY" :func
    "B7-CONVERSION" :llvm
    "B7-METADATA" :builtin
    "B7-EFFECT" :memref
    "B7-NUMERIC" :arith
    "B7-ALIAS" :memref
    "B7-PASS" :canonicalize
    "B7-HANDOFF" :llvm
    "B7-MANIFEST" :gravity.backend/mlir
    :gravity.mir))

(defn b7-document-fail!
  [id source-path subject extra]
  (fail! id
         "B7 MLIR backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b7-mlir-backend-document
                 :stage (or (:stage subject)
                            :b7-mlir-backend-document-coverage)
                 :backend :gravity.backend/mlir
                 :profile (or (:profile subject) :native)
                 :artifact-id (:artifact-id subject)
                 :mir-op (or (:mir-op subject) :checked-add)
                 :domain-anchor (or (:domain-anchor subject) :mir)
                 :mlir-operation (or (:mlir-operation subject)
                                     (b7-document-mlir-operation id))
                 :dialect (or (:dialect subject)
                              (b7-document-dialect id))
                 :pass-name (or (:pass-name subject) :canonicalize)
                 :missing-or-invalidated-fact
                 (or (:missing-or-invalidated-fact subject)
                     (b7-document-missing-fact id))
                 :downstream-target
                 (or (:downstream-target subject) :gravity.backend/llvm)
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit MLIR only from verified MIR/domain IR with declared dialect registry, operation schemas, verifier and conversion legality reports, pass invalidation/repair logs, proof-to-dialect mappings, source/debug preservation, and complete downstream handoff manifests."}
                extra)))

(defn b7-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b7-document-override-diagnostics fail-kind)]
      (b7-document-fail!
       id source-path
       {:stage :b7-mlir-backend-document-coverage
        :artifact-id (str "b7-document-" (name fail-kind))
        :missing-or-invalidated-fact fail-kind
        :mlir-operation (name fail-kind)
        :dialect fail-kind}
       {:missing-fields [fail-kind]}))))

(def b7-document-mlir-module
  (str "module attributes {gravity.profile = \"native\", gravity.target = \"x86_64-stage0\"} {\n"
       "  func.func @gravity_entry(%x: i64 loc(\"backend-native-lowering.gravity:entry\")) -> i64\n"
       "      attributes {gravity.effect = \"pure\", gravity.capability = \"none\", gravity.profile = \"native\"} {\n"
       "    %c1 = arith.constant 1 : i64 loc(\"proof/c18-bounds-check-dominance\")\n"
       "    %y = arith.addi %x, %c1 : i64\n"
       "      {gravity.numeric_mode = \"checked-i64\", gravity.proof = \"proof/c18-bounds-check-dominance\", gravity.source_span = \"backend-native-lowering.gravity:entry\"}\n"
       "      loc(\"backend-native-lowering.gravity:checked-add\")\n"
       "    return %y : i64 loc(\"backend-native-lowering.gravity:return\")\n"
       "  } loc(\"backend-native-lowering.gravity:function\")\n"
       "} loc(\"backend-native-lowering.gravity:module\")\n"))

(defn b7-document-mlir-structurally-valid?
  [source]
  (and (str/includes? source "module attributes")
       (str/includes? source "func.func @gravity_entry")
       (str/includes? source "arith.constant")
       (str/includes? source "arith.addi")
       (str/includes? source "gravity.numeric_mode")
       (str/includes? source "gravity.proof")
       (str/includes? source "gravity.source_span")
       (str/includes? source "loc(")))

(defn b7-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b7-mlir-backend-diagnostic-stream
   :stage :b7-mlir-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b7-mlir-backend-document-coverage
            :backend :gravity.backend/mlir
            :message-key (keyword "backend-mlir" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b7-document-syntax-" index)
                      :artifact input-id}
            :mir-op (case id
                      "B7-CONVERSION" :domain-anchor-lowering
                      "B7-EFFECT" :memory-effect-change
                      "B7-NUMERIC" :numeric-lowering
                      "B7-ALIAS" :ownership-alias-lowering
                      :checked-add)
            :domain-anchor (case id
                             "B7-HANDOFF" :downstream-llvm
                             "B7-NUMERIC" :efir
                             :mir)
            :mlir-operation (b7-document-mlir-operation id)
            :dialect (b7-document-dialect id)
            :pass-name (case id
                         "B7-PASS" :canonicalize
                         "B7-CONVERSION" :convert-func-to-llvm
                         :verify)
            :missing-or-invalidated-fact (b7-document-missing-fact id)
            :downstream-target (case id
                                 "B7-HANDOFF" :gravity.backend/gpu
                                 :gravity.backend/llvm)
            :fallback-status :rejected
            :facts {:dialect-verifier-is-not-gravity-proof true
                    :metadata-loss-policy :backend-error
                    :pass-invalidation-policy :repair-or-reject
                    :conversion-legality-policy :verifier-gated}
            :remediation [{:kind :declare-dialect-schema}
                          {:kind :preserve-gravity-metadata}
                          {:kind :run-conversion-and-handoff-gates}]
            :redactions []
            :ordering-key [id :b7-mlir-backend-document-coverage
                           :x86_64-stage0]})
         b7-document-diagnostic-ids
         (range))
   :status :complete})

(defn b7-document-mlir-manifest
  [input-id]
  (let [module-hash (c4-artifact-id b7-document-mlir-module)]
    {:artifact :gravity/mlir-backend-manifest
     :backend :gravity.backend/mlir
     :mlir-version "stage0-recorded"
     :dialects #{:gravity.mir :gravity.efir :func :arith :scf :cf
                 :memref :affine :vector :gpu :llvm}
     :emits #{:mlir-module :verifier-report :pass-log
              :handoff-manifest}
     :requires #{:dialect-registry :conversion-legality :proof-map
                 :metadata-preservation-policy}
     :rejects #{:metadata-loss :unverified-effect-change :dialect-ub
                :illegal-conversion-target}
     :dialect-registry-manifest
     {:mlir-version "stage0-recorded"
      :dialects [:gravity.mir :gravity.efir :func :arith :scf :cf
                 :memref :affine :vector :gpu :llvm]
      :operation-coverage {:gravity.mir [:gravity.checked_add
                                         :gravity.return]
                           :func [:func.func :func.return]
                           :arith [:arith.constant :arith.addi]
                           :memref []
                           :llvm [:llvm.func]
                           :gpu [:gpu.module]}
      :verifier-hooks [:types :effects :memory-regions :ownership
                       :capabilities :profile-legality :proof-references]
      :status :complete}
     :gravity-dialect-operation-schema
     {:operations [{:operation :gravity.checked_add
                    :operands [:I64 :I64]
                    :results [:I64]
                    :attributes [:source-span :generated-origin
                                 :effect :capability :ownership
                                 :safety-outcome :proof :profile
                                 :diagnostic-back-edge]}
                   {:operation :gravity.return
                    :operands [:I64]
                    :results []
                    :attributes [:source-span :generated-origin
                                 :effect :capability :profile]}]
      :type-schema [:I64 :F64 :Option :Result :opaque-host]
      :effect-interfaces [:MemoryEffectOpInterface]
      :capability-attribute :gravity.capability
      :proof-attribute :gravity.proof
      :profile-attribute :gravity.profile
      :status :complete}
     :standard-dialect-fact-mapping
     {:arith {:numeric-mode :gravity.numeric_mode
              :range-proof :arith.no_overflow}
      :memref {:alias-facts :gravity.alias_set
               :ownership :gravity.owner}
      :func {:source-spans :loc
             :effect-summary :gravity.effect}
      :gpu {:synchronization :gpu.barrier
            :capability :gravity.capability}
      :llvm {:proof-references :gravity.proof
             :debug-metadata :loc}
      :status :complete}
     :operation-and-type-mapping-record
     {:mappings [{:mir-operation :checked-add
                  :mlir-operation :arith.addi
                  :operand-types [:I64 :I64]
                  :result-types [:I64]
                  :memory-effect :none
                  :control-flow-region :single-block
                  :source-span "backend-native-lowering.gravity:entry"
                  :generated-origin-chain [:mir :c14-target-lowering
                                           :b1-interface
                                           :b7-mlir-backend]
                  :ownership-lifetime [:copy]
                  :capabilities #{}
                  :effects #{}
                  :safety-outcome :proven-safe
                  :proof "proof/c18-bounds-check-dominance"
                  :diagnostic-back-edge "B7-NUMERIC"}]
      :compiler-introduced-temporaries
      [{:value "%c1"
        :origin :constant-introduced-by-b7
        :source-back-edge "backend-native-lowering.gravity:entry"}]
      :status :complete}
     :mlir-modules [{:path "gravity_stage0.mlir"
                     :content b7-document-mlir-module
                     :hash module-hash
                     :status :complete}]
     :conversion-target-and-legality-report
     {:targets [:llvm :gpu]
      :legality-checks [{:target :llvm
                         :remaining-illegal-operations []
                         :verifier-status :passed}
                        {:target :gpu
                         :remaining-illegal-operations []
                         :verifier-status :passed}]
      :fallbacks []
      :status :passed}
     :pass-pipeline-log
     [{:pass :canonicalize
       :version "stage0"
       :input-dialects [:gravity.mir :func :arith]
       :output-dialects [:func :arith]
       :legality-conditions [:metadata-preserved :effects-unchanged]
       :facts-preserved [:source-span :generated-origin :types
                         :effects :capabilities :safety-outcome :proof
                         :profile]
       :facts-invalidated []
       :repair-passes []
       :verifier-before :passed
       :verifier-after :passed
       :downstream-handoff-target :gravity.backend/llvm}
      {:pass :convert-func-to-llvm
       :version "stage0"
       :input-dialects [:func :arith]
       :output-dialects [:llvm]
       :legality-conditions [:conversion-target-legal
                             :proof-map-retained]
       :facts-preserved [:source-span :proof :capability
                         :numeric-mode]
       :facts-invalidated [:high-level-function-region]
       :repair-passes [:source-debug-side-table]
       :verifier-before :passed
       :verifier-after :passed
       :downstream-handoff-target :gravity.backend/llvm}]
     :mlir-verifier-report
     {:structural-verifier :passed
      :external-toolchain :not-available-in-current-environment
      :declared-command "mlir-opt --verify-diagnostics /tmp/gravity-p07-b7.mlir"
      :checked [:dialect-registry :operation-schema
                :metadata-preservation :conversion-legality]
      :status :passed}
     :proof-to-dialect-attribute-map
     [{:proof :proof/c18-bounds-check-dominance
       :gravity-fact :range
       :dialect :arith
       :attribute :arith.no_overflow
       :operation :arith.addi}
      {:proof :proof/c18-lifetime-range
       :gravity-fact :alias
       :dialect :memref
       :attribute :gravity.alias_set}
      {:proof :proof/c18-capability-preservation
       :gravity-fact :capability
       :dialect :func
       :attribute :gravity.capability}
      {:proof :proof/math-numeric-mode
       :gravity-fact :numeric-mode
       :dialect :arith
       :attribute :gravity.numeric_mode}]
     :source-debug-map
     {:source input-id
      :locations ["backend-native-lowering.gravity:module"
                  "backend-native-lowering.gravity:function"
                  "backend-native-lowering.gravity:checked-add"]
      :generated-origin-chain [:mir :c14-target-lowering
                               :b1-interface :b7-mlir-backend]
      :unsafe-audit-ids []
      :proof-references ["proof/c18-bounds-check-dominance"]
      :status :preserved}
     :downstream-handoff-manifests
     [{:destination :gravity.backend/llvm
       :accepted-dialects [:func :arith :llvm]
       :remaining-illegal-operations []
       :conversion-target-status :passed
       :verifier-status :passed
       :source-proof-safety-capability-map :preserved
       :abi-runtime-provider-assumptions [:lp64 :stage0-runtime]
       :target-features #{}
       :rejected-or-deferred-constructs []
       :status :complete}
      {:destination :gravity.backend/gpu
       :accepted-dialects [:gpu :func :arith :memref]
       :remaining-illegal-operations []
       :conversion-target-status :passed
       :verifier-status :passed
       :source-proof-safety-capability-map :preserved
       :abi-runtime-provider-assumptions [:gpu-provider-manifest]
       :target-features #{:generic-gpu}
       :rejected-or-deferred-constructs []
       :status :complete}]
     :metadata-preservation-policy
     {:required [:source-span :unsafe-audit-id :capability
                 :effect :numeric-mode :alias-fact :proof
                 :profile :diagnostic-back-edge]
      :loss-policy :backend-error
      :status :complete}
     :semantic-authority-record
     {:mlir-verifier-is-gravity-proof false
      :gravity-proof-remains-authoritative true
      :dialect-ub-not-used-for-safe-gravity true
      :round-trip-target-behavior-to-mir :rejected
      :status :complete}
     :input-artifact input-id
     :status :complete}))

(defn b7-document-validate!
  [source-path artifact]
  (let [native (:native-lowering-artifact artifact)
        manifest (:mlir-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b7-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-native-lowering-artifact (:kind native))
      (b7-document-fail! "B7-MANIFEST" source-path native
                         {:missing-fields [:native-lowering-artifact]}))
    (when-not (= :complete (get-in native
                                   [:capability-based-proof :status]))
      (b7-document-fail! "B7-MANIFEST" source-path native
                         {:missing-fields [:native-lowering-proof]}))
    (when-not (= :complete (get-in manifest
                                   [:dialect-registry-manifest
                                    :status]))
      (b7-document-fail! "B7-DIALECT" source-path manifest
                         {:missing-fields [:dialect-registry]}))
    (when-not (= :complete (get-in manifest
                                   [:gravity-dialect-operation-schema
                                    :status]))
      (b7-document-fail! "B7-DIALECT" source-path manifest
                         {:missing-fields [:operation-schema]}))
    (when-not (= :complete (get-in manifest
                                   [:standard-dialect-fact-mapping
                                    :status]))
      (b7-document-fail! "B7-METADATA" source-path manifest
                         {:missing-fields [:standard-dialect-mapping]}))
    (when-not (= :complete (get-in manifest
                                   [:operation-and-type-mapping-record
                                    :status]))
      (b7-document-fail! "B7-METADATA" source-path manifest
                         {:missing-fields [:operation-type-mapping]}))
    (when-not (= :passed (get-in manifest
                                 [:conversion-target-and-legality-report
                                  :status]))
      (b7-document-fail! "B7-CONVERSION" source-path manifest
                         {:missing-fields [:conversion-legality]}))
    (when-not (= :passed (get-in manifest
                                 [:mlir-verifier-report :status]))
      (b7-document-fail! "B7-VERIFY" source-path manifest
                         {:missing-fields [:verifier-report]}))
    (when-not (= :complete (get-in manifest
                                   [:metadata-preservation-policy
                                    :status]))
      (b7-document-fail! "B7-METADATA" source-path manifest
                         {:missing-fields [:metadata-policy]}))
    (when-not (every? #(= :complete (:status %))
                      (:downstream-handoff-manifests manifest))
      (b7-document-fail! "B7-HANDOFF" source-path manifest
                         {:missing-fields [:downstream-handoff]}))
    (when-not (every? #(and (= :passed (:verifier-before %))
                            (= :passed (:verifier-after %))
                            (contains? % :facts-preserved)
                            (contains? % :facts-invalidated))
                      (:pass-pipeline-log manifest))
      (b7-document-fail! "B7-PASS" source-path manifest
                         {:missing-fields [:pass-pipeline-log]}))
    (when-not (b7-document-mlir-structurally-valid?
               b7-document-mlir-module)
      (b7-document-fail! "B7-VERIFY" source-path manifest
                         {:missing-fields [:mlir-module-structure]}))
    (when-not (every? #(contains? manifest %)
                      [:dialect-registry-manifest
                       :gravity-dialect-operation-schema
                       :standard-dialect-fact-mapping
                       :operation-and-type-mapping-record
                       :mlir-modules
                       :conversion-target-and-legality-report
                       :pass-pipeline-log
                       :mlir-verifier-report
                       :proof-to-dialect-attribute-map
                       :source-debug-map
                       :downstream-handoff-manifests
                       :metadata-preservation-policy
                       :semantic-authority-record])
      (b7-document-fail! "B7-MANIFEST" source-path manifest
                         {:missing-fields [:mlir-artifact-manifest]}))
    (when-not (= (set b7-document-diagnostic-ids) diagnostics)
      (b7-document-fail! "B7-MANIFEST" source-path
                         (:b7-diagnostic-stream artifact)
                         {:missing-fields [:b7-diagnostics]})))
  :complete)

(defn b7-document-capability-proof
  [artifact]
  (let [manifest (:mlir-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b7-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:native-lowering-artifact
                           :capability-based-proof :status]))
     :dialect-registry-covered?
     (= :complete (get-in manifest
                          [:dialect-registry-manifest :status]))
     :gravity-operation-schema-covered?
     (= :complete (get-in manifest
                          [:gravity-dialect-operation-schema :status]))
     :standard-dialect-fact-mapping-covered?
     (= :complete (get-in manifest
                          [:standard-dialect-fact-mapping :status]))
     :operation-type-mapping-covered?
     (= :complete (get-in manifest
                          [:operation-and-type-mapping-record :status]))
     :mlir-module-emitted?
     (= :complete (get-in manifest [:mlir-modules 0 :status]))
     :conversion-legality-passed?
     (= :passed (get-in manifest
                        [:conversion-target-and-legality-report :status]))
     :pass-pipeline-verified?
     (every? #(and (= :passed (:verifier-before %))
                   (= :passed (:verifier-after %)))
             (:pass-pipeline-log manifest))
     :mlir-verifier-report-passed?
     (= :passed (get-in manifest [:mlir-verifier-report :status]))
     :proof-to-dialect-map-covered?
     (boolean (seq (:proof-to-dialect-attribute-map manifest)))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :downstream-handoff-covered?
     (= #{:gravity.backend/llvm :gravity.backend/gpu}
        (set (map :destination
                  (:downstream-handoff-manifests manifest))))
     :metadata-preservation-policy-covered?
     (= :complete (get-in manifest
                          [:metadata-preservation-policy :status]))
     :semantic-authority-preserved?
     (= :complete (get-in manifest
                          [:semantic-authority-record :status]))
     :mlir-structurally-valid?
     (b7-document-mlir-structurally-valid? b7-document-mlir-module)
     :manifest-complete?
     (every? #(contains? manifest %)
             [:dialect-registry-manifest
              :gravity-dialect-operation-schema
              :standard-dialect-fact-mapping
              :operation-and-type-mapping-record
              :mlir-modules
              :conversion-target-and-legality-report
              :pass-pipeline-log
              :mlir-verifier-report
              :proof-to-dialect-attribute-map
              :source-debug-map
              :downstream-handoff-manifests
              :metadata-preservation-policy
              :semantic-authority-record])
     :diagnostics-covered?
     (= (set b7-document-diagnostic-ids) diagnostics)
     :external-mlir-toolchain-validation?
     (get-in manifest [:mlir-verifier-report :external-toolchain])
     :status :complete}))

(defn b7-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b7-document-source-overrides module)
        _ (b7-document-validate-source-overrides! source-path
                                                  source-overrides)
        native-artifact (native-lowering-source-artifact source-path
                                                         source-text)
        input-id (:artifact-id native-artifact)
        manifest (b7-document-mlir-manifest input-id)
        diagnostic-stream (b7-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b7-mlir-backend-document-artifact
         :task "P07-D104"
         :document-set ["B7"]
         :governing-document b7-document-governing-document
         :pass {:name :b7-mlir-backend-document-coverage
                :input :native-lowering-artifact
                :output :b7-mlir-backend-document-artifact
                :requires [:verified-mir-or-domain-ir :b1-backend-interface
                           :c11-mir :c12-domain-ir :c13-invalidation
                           :c14-target-lowering :dialect-registry
                           :conversion-legality :proof-map
                           :metadata-preservation-policy]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :ownership
                            :safety :proofs :profile :target
                            :diagnostics :artifact-provenance]
                :emits [:mlir-backend-manifest :dialect-registry
                        :gravity-dialect-operation-schema :mlir-module
                        :conversion-legality-report :pass-pipeline-log
                        :mlir-verifier-report
                        :proof-to-dialect-attribute-map
                        :source-debug-map :downstream-handoff-manifest
                        :b7-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b7-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :native-lowering-artifact
         (select-keys native-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :native-lowering-results])
         :native-lowering-artifact-kind (:kind native-artifact)
         :native-lowering-artifact-hash input-id
         :mlir-backend-manifest manifest
         :dialect-registry-manifest
         (:dialect-registry-manifest manifest)
         :gravity-dialect-operation-schema
         (:gravity-dialect-operation-schema manifest)
         :standard-dialect-fact-mapping
         (:standard-dialect-fact-mapping manifest)
         :operation-and-type-mapping-record
         (:operation-and-type-mapping-record manifest)
         :mlir-modules (:mlir-modules manifest)
         :conversion-target-and-legality-report
         (:conversion-target-and-legality-report manifest)
         :pass-pipeline-log (:pass-pipeline-log manifest)
         :mlir-verifier-report (:mlir-verifier-report manifest)
         :proof-to-dialect-attribute-map
         (:proof-to-dialect-attribute-map manifest)
         :source-debug-map (:source-debug-map manifest)
         :downstream-handoff-manifests
         (:downstream-handoff-manifests manifest)
         :metadata-preservation-policy
         (:metadata-preservation-policy manifest)
         :semantic-authority-record
         (:semantic-authority-record manifest)
         :rejected-design-coverage
         [{:design :mlir-verifier-as-gravity-proof
           :diagnostic "B7-VERIFY" :status :rejected}
          {:design :silent-effect-memory-numeric-capability-change
           :diagnostic "B7-EFFECT" :status :rejected}
          {:design :dialect-boundary-metadata-loss
           :diagnostic "B7-METADATA" :status :rejected}
          {:design :downstream-handoff-without-legality
           :diagnostic "B7-HANDOFF" :status :rejected}
          {:design :target-behavior-round-trip-into-generic-mir
           :diagnostic "B7-CONVERSION" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b7-mlir-backend-conformance-criteria-record
          :gravity-dialect-operation-type-schemas :complete
          :standard-dialect-metadata-mapping :complete
          :mlir-verifier-acceptance-rejection-fixtures :covered
          :pass-pipeline-preservation-invalidation-logs :complete
          :proof-to-dialect-attribute-maps :complete
          :downstream-llvm-gpu-handoff-fixtures :complete
          :metadata-loss-illegal-conversion-effect-pass-rejection :covered
          :differential-execution :mir-domain-reference-recorded
          :status :passed}
         :b7-diagnostic-stream diagnostic-stream
         :b7-document-results
         {:documents ["B7"]
          :task "P07-D104"
          :required-diagnostic-ids b7-document-diagnostic-ids
          :native-lowering-input-status :complete
          :dialect-status :complete
          :operation-schema-status :complete
          :standard-dialect-mapping-status :complete
          :operation-type-mapping-status :complete
          :module-status :complete
          :conversion-status :complete
          :pass-status :complete
          :verifier-status :complete
          :proof-map-status :complete
          :source-debug-status :complete
          :handoff-status :complete
          :metadata-status :complete
          :semantic-authority-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b7-document-validate! source-path artifact-base)
        capability-proof (b7-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b7-document-file-artifact
  [path]
  (b7-document-source-artifact path (slurp path)))

(def b8-document-governing-document
  "docs/phase-07-backend-architecture/105-b8-gpu-backend-design.md")

(def b8-document-diagnostic-ids
  ["B8-TARGET"
   "B8-KERNEL"
   "B8-HOST-EFFECT"
   "B8-MEMORY"
   "B8-TRANSFER"
   "B8-SYNC"
   "B8-ATOMIC"
   "B8-LAUNCH"
   "B8-MATH"
   "B8-MANIFEST"])

(def b8-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b8-document-diagnostic-ids)))

(defn b8-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b8-document])
      (get-in module [:metadata :backend :specialized-lowering])
      (get-in module [:metadata :backend :specialized])
      {}))

(defn b8-document-missing-fact
  [id]
  (case id
    "B8-TARGET" :gpu-api-device-feature-binary-format
    "B8-KERNEL" :gpu-profile-kernel-legality
    "B8-HOST-EFFECT" :host-effect-absence-proof
    "B8-MEMORY" :device-memory-lifetime-layout-address-space
    "B8-TRANSFER" :explicit-transfer-graph
    "B8-SYNC" :synchronization-graph-barrier-fence
    "B8-ATOMIC" :atomic-order-memory-scope-map
    "B8-LAUNCH" :launch-geometry-occupancy-shared-memory-record
    "B8-MATH" :numeric-mode-math-certificate
    "B8-MANIFEST" :complete-gpu-artifact-manifest
    :b8-document-evidence))

(defn b8-document-kernel-id
  [id]
  (case id
    "B8-TARGET" :gravity_stage0_kernel
    "B8-KERNEL" :gravity_stage0_kernel
    "B8-HOST-EFFECT" :gravity_stage0_kernel
    "B8-MEMORY" :gravity_stage0_kernel
    "B8-TRANSFER" :gravity_stage0_kernel
    "B8-SYNC" :gravity_stage0_kernel
    "B8-ATOMIC" :gravity_stage0_atomic
    "B8-LAUNCH" :gravity_stage0_kernel
    "B8-MATH" :gravity_stage0_reduce
    "B8-MANIFEST" :gravity_stage0_kernel
    :gravity_stage0_kernel))

(defn b8-document-fail!
  [id source-path subject extra]
  (fail! id
         "B8 GPU backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b8-gpu-backend-document
                 :stage (or (:stage subject)
                            :b8-gpu-backend-document-coverage)
                 :backend :gravity.backend/gpu
                 :profile (or (:profile subject) :gpu)
                 :kernel-id (or (:kernel-id subject)
                                (b8-document-kernel-id id))
                 :mir-op (or (:mir-op subject) :gpu-kernel)
                 :domain-anchor (or (:domain-anchor subject) :gpu-kernel)
                 :device-target (or (:device-target subject) :spir-v)
                 :address-space (or (:address-space subject) :global)
                 :buffer-id (or (:buffer-id subject) :input)
                 :launch-descriptor
                 (or (:launch-descriptor subject)
                     {:grid [1 1 1] :workgroup [32 1 1]})
                 :missing-proof-or-feature
                 (or (:missing-proof-or-feature subject)
                     (b8-document-missing-fact id))
                 :fallback-status (or (:fallback-status subject) :rejected)
                 :remediation "Emit GPU artifacts only from verified GPU/domain IR with explicit host/device boundaries, kernel legality, device memory lifetimes, transfer and synchronization graphs, atomic scope maps, launch descriptors, target features, numeric certificates, source/debug maps, and complete GPU manifests."}
                extra)))

(defn b8-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b8-document-override-diagnostics fail-kind)]
      (b8-document-fail!
       id source-path
       {:stage :b8-gpu-backend-document-coverage
        :artifact-id (str "b8-document-" (name fail-kind))
        :missing-proof-or-feature fail-kind
        :kernel-id (keyword (str "b8-document-" (name fail-kind)))}
       {:missing-fields [fail-kind]}))))

(def b8-document-kernel-module
  (str "spirv.module @gravity_stage0_gpu attributes {gravity.profile = \"gpu\", gravity.target = \"spir-v\"} {\n"
       "  gpu.module @kernels {\n"
       "    gpu.func @gravity_stage0_kernel(%input: memref<1024xi32, 1>, %output: memref<1024xi32, 1>) kernel\n"
       "        attributes {gravity.effect = \"device\", gravity.capability = \"gpu/launch\", gravity.proof = \"proof/gpu-stage0-memory-sync\"} {\n"
       "      %lane = gpu.thread_id x\n"
       "      %value = memref.load %input[%lane] : memref<1024xi32, 1>\n"
       "      gpu.barrier\n"
       "      memref.store %value, %output[%lane] : memref<1024xi32, 1>\n"
       "      gpu.return\n"
       "    }\n"
       "  }\n"
       "}\n"))

(def b8-document-host-stub
  (str "void gravity_stage0_launch(GravityGpuQueue queue, GravityGpuBuffer input, GravityGpuBuffer output) {\n"
       "  gravity_gpu_copy_host_to_device(queue, input);\n"
       "  gravity_gpu_launch(queue, \"gravity_stage0_kernel\", 1, 1, 1, 32, 1, 1);\n"
       "  gravity_gpu_copy_device_to_host(queue, output);\n"
       "}\n"))

(defn b8-document-kernel-structurally-valid?
  [source]
  (and (str/includes? source "spirv.module")
       (str/includes? source "gpu.func @gravity_stage0_kernel")
       (str/includes? source "gravity.profile = \"gpu\"")
       (str/includes? source "gravity.proof")
       (str/includes? source "memref.load")
       (str/includes? source "gpu.barrier")
       (str/includes? source "memref.store")
       (not (str/includes? source "host_alloc"))
       (not (str/includes? source "throw"))
       (not (str/includes? source "eval"))))

(defn b8-document-host-stub-structurally-valid?
  [source]
  (and (str/includes? source "gravity_gpu_copy_host_to_device")
       (str/includes? source "gravity_gpu_launch")
       (str/includes? source "gravity_gpu_copy_device_to_host")
       (not (str/includes? source "malloc"))))

(defn b8-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b8-gpu-backend-diagnostic-stream
   :stage :b8-gpu-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b8-gpu-backend-document-coverage
            :backend :gravity.backend/gpu
            :message-key (keyword "backend-gpu" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b8-document-syntax-" index)
                      :artifact input-id}
            :kernel-id (b8-document-kernel-id id)
            :mir-op (case id
                      "B8-HOST-EFFECT" :host-effect-capture
                      "B8-MEMORY" :device-buffer
                      "B8-TRANSFER" :host-device-transfer
                      "B8-SYNC" :gpu-barrier
                      "B8-ATOMIC" :gpu-atomic
                      "B8-LAUNCH" :kernel-launch
                      "B8-MATH" :gpu-numeric-lowering
                      :gpu-kernel)
            :domain-anchor :gpu-kernel
            :device-target :spir-v
            :address-space (case id
                             "B8-SYNC" :shared
                             "B8-ATOMIC" :global
                             :global)
            :buffer-id (case id
                         "B8-MEMORY" :input
                         "B8-TRANSFER" :output
                         :input)
            :launch-descriptor {:grid [1 1 1]
                                :workgroup [32 1 1]
                                :shared-memory-bytes 0}
            :missing-proof-or-feature (b8-document-missing-fact id)
            :fallback-status :rejected
            :facts {:host-device-boundary-required true
                    :implicit-transfer-policy :rejected
                    :device-buffer-policy :linear
                    :numeric-policy :certificate-required}
            :remediation [{:kind :declare-gpu-target-and-kernel}
                          {:kind :emit-device-memory-transfer-sync-graphs}
                          {:kind :attach-launch-and-math-certificate-records}]
            :redactions []
            :ordering-key [id :b8-gpu-backend-document-coverage
                           :spir-v]})
         b8-document-diagnostic-ids
         (range))
   :status :complete})

(defn b8-document-gpu-manifest
  [source-path input-id]
  (let [kernel-hash (c4-artifact-id b8-document-kernel-module)
        host-stub-hash (c4-artifact-id b8-document-host-stub)]
    {:artifact :gravity/gpu-backend-manifest
     :backend :gravity.backend/gpu
     :target {:api :spir-v
              :device-class :gpu
              :features #{:subgroups :fp16 :shared-memory}
              :binary-format :spir-v-ir}
     :emits #{:kernel-module :device-binary :host-stub
              :launch-descriptor}
     :requires #{:host-device-boundary :device-memory-lifetimes
                 :transfer-graph :sync-graph :numeric-mode}
     :rejects #{:host-effect-in-kernel :implicit-transfer
                :shared-state-without-sync :uncertified-fast-math}
     :host-device-boundary-artifact
     {:host-profile :native
      :host-provider :stage0-gpu-runtime
      :device-target :spir-v
      :feature-set #{:subgroups :fp16 :shared-memory}
      :kernel-symbol :gravity_stage0_kernel
      :argument-schemas [{:name :input
                          :gravity-type :DeviceBuffer/I32
                          :address-space :global
                          :layout :i32
                          :alignment 4
                          :aliasing :noalias
                          :lifetime :linear-kernel
                          :mutability :read-only
                          :transfer-state :host-to-device}
                         {:name :output
                          :gravity-type :DeviceBuffer/I32
                          :address-space :global
                          :layout :i32
                          :alignment 4
                          :aliasing :noalias
                          :lifetime :linear-kernel
                          :mutability :write-only
                          :transfer-state :device-to-host}]
      :device-buffer-ownership :linear
      :transfer-direction [:host-to-device :device-to-host]
      :synchronization-edges [[:copy-in :kernel-launch]
                              [:kernel-launch :copy-out]]
      :launch-order [:copy-in :kernel-launch :copy-out]
      :capability-grants #{:gpu/launch :memory/device}
      :source-generated-origin-links [:mir :c14-target-lowering
                                      :b1-interface :b8-gpu-backend]
      :status :declared}
     :kernel-ir-or-target-modules
     [{:path "gravity_stage0_gpu.spvasm"
       :content b8-document-kernel-module
       :hash kernel-hash
       :kernel :gravity_stage0_kernel
       :status :complete}]
     :device-binary-or-intermediate-artifacts
     [{:path "gravity_stage0_gpu.spv"
