      :status :complete}
     :source-debug-map
     {:source input-id
      :kernel :gravity_stage0_kernel
      :generated-origin-chain [:mir :c14-target-lowering
                               :b1-interface :b8-gpu-backend]
      :source-spans [(str source-path ":kernel")
                     (str source-path ":transfer")
                     (str source-path ":sync")]
      :proof-references ["proof/gpu-stage0-memory-sync"
                         "MATH8-stage0-strict-integer"]
      :capability-references [:gpu/launch :memory/device]
      :status :preserved}
     :spirv-validation-record
     {:declared-command "spirv-val /tmp/gravity-p07-b8-gpu.spvasm"
      :proof-artifact "docs/artifacts/phase-07/reports/p07-d105-b8-gpu-backend-report.md"
      :status :not-available-in-current-environment}
     :input-artifact input-id
     :status :complete}))

(defn b8-document-validate!
  [source-path artifact]
  (let [specialized (:specialized-lowering-artifact artifact)
        manifest (:gpu-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b8-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-specialized-lowering-artifact
                 (:kind specialized))
      (b8-document-fail! "B8-MANIFEST" source-path specialized
                         {:missing-fields [:specialized-lowering-artifact]}))
    (when-not (= :complete (get-in specialized
                                   [:capability-based-proof :status]))
      (b8-document-fail! "B8-MANIFEST" source-path specialized
                         {:missing-fields [:specialized-lowering-proof]}))
    (when-not (= :spir-v (get-in manifest [:target :api]))
      (b8-document-fail! "B8-TARGET" source-path manifest
                         {:missing-fields [:target-api]}))
    (when-not (= :declared (get-in manifest
                                   [:host-device-boundary-artifact
                                    :status]))
      (b8-document-fail! "B8-KERNEL" source-path manifest
                         {:missing-fields [:host-device-boundary]}))
    (when-not (= :complete (get-in manifest
                                   [:kernel-lowering-map :status]))
      (b8-document-fail! "B8-KERNEL" source-path manifest
                         {:missing-fields [:kernel-lowering-map]}))
    (when-not (= :complete (get-in manifest
                                   [:device-memory-lifetime-report
                                    :status]))
      (b8-document-fail! "B8-MEMORY" source-path manifest
                         {:missing-fields [:device-memory-lifetime]}))
    (when-not (= :complete (get-in manifest [:transfer-graph :status]))
      (b8-document-fail! "B8-TRANSFER" source-path manifest
                         {:missing-fields [:transfer-graph]}))
    (when-not (= :complete (get-in manifest
                                   [:synchronization-graph :status]))
      (b8-document-fail! "B8-SYNC" source-path manifest
                         {:missing-fields [:synchronization-graph]}))
    (when-not (seq (get-in manifest
                           [:synchronization-graph :atomics]))
      (b8-document-fail! "B8-ATOMIC" source-path manifest
                         {:missing-fields [:atomic-memory-scope]}))
    (when-not (= :complete (get-in manifest [:launch-descriptor :status]))
      (b8-document-fail! "B8-LAUNCH" source-path manifest
                         {:missing-fields [:launch-descriptor]}))
    (when-not (= :complete
                 (get-in manifest
                         [:target-feature-and-occupancy-report
                          :status]))
      (b8-document-fail! "B8-LAUNCH" source-path manifest
                         {:missing-fields [:occupancy-report]}))
    (when-not (= :complete (get-in manifest
                                   [:math-certificate-bundle :status]))
      (b8-document-fail! "B8-MATH" source-path manifest
                         {:missing-fields [:math-certificate-bundle]}))
    (when-not (= :preserved (get-in manifest [:source-debug-map :status]))
      (b8-document-fail! "B8-MANIFEST" source-path manifest
                         {:missing-fields [:source-debug-map]}))
    (when-not (b8-document-kernel-structurally-valid?
               b8-document-kernel-module)
      (b8-document-fail! "B8-KERNEL" source-path manifest
                         {:missing-fields [:kernel-module-structure]}))
    (when-not (b8-document-host-stub-structurally-valid?
               b8-document-host-stub)
      (b8-document-fail! "B8-MANIFEST" source-path manifest
                         {:missing-fields [:host-stub-structure]}))
    (when-not (every? #(contains? manifest %)
                      [:host-device-boundary-artifact
                       :kernel-ir-or-target-modules
                       :device-binary-or-intermediate-artifacts
                       :host-stub-artifact
                       :kernel-lowering-map
                       :device-memory-lifetime-report
                       :transfer-graph
                       :synchronization-graph
                       :launch-descriptor
                       :target-feature-and-occupancy-report
                       :math-certificate-bundle
                       :source-debug-map
                       :spirv-validation-record])
      (b8-document-fail! "B8-MANIFEST" source-path manifest
                         {:missing-fields [:gpu-artifact-manifest]}))
    (when-not (= (set b8-document-diagnostic-ids) diagnostics)
      (b8-document-fail! "B8-MANIFEST" source-path
                         (:b8-diagnostic-stream artifact)
                         {:missing-fields [:b8-diagnostics]})))
  :complete)

(defn b8-document-capability-proof
  [artifact]
  (let [manifest (:gpu-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b8-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:specialized-lowering-artifact
                           :capability-based-proof :status]))
     :target-feature-binary-format-covered?
     (= :spir-v (get-in manifest [:target :api]))
     :host-device-boundary-declared?
     (= :declared (get-in manifest
                          [:host-device-boundary-artifact :status]))
     :kernel-legality-covered?
     (= :complete (get-in manifest [:kernel-lowering-map :status]))
     :host-effect-absence-covered?
     (not (str/includes? b8-document-kernel-module "host_alloc"))
     :device-memory-lifetimes-covered?
     (= :complete (get-in manifest
                          [:device-memory-lifetime-report :status]))
     :explicit-transfer-graph-covered?
     (= :complete (get-in manifest [:transfer-graph :status]))
     :synchronization-graph-covered?
     (= :complete (get-in manifest [:synchronization-graph :status]))
     :atomics-memory-scope-covered?
     (boolean (seq (get-in manifest
                           [:synchronization-graph :atomics])))
     :launch-occupancy-covered?
     (and (= :complete (get-in manifest [:launch-descriptor :status]))
          (= :complete
             (get-in manifest
                     [:target-feature-and-occupancy-report :status])))
     :math-certificate-covered?
     (= :complete (get-in manifest [:math-certificate-bundle :status]))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :kernel-structurally-valid?
     (b8-document-kernel-structurally-valid? b8-document-kernel-module)
     :host-stub-structurally-valid?
     (b8-document-host-stub-structurally-valid? b8-document-host-stub)
     :manifest-complete?
     (every? #(contains? manifest %)
             [:host-device-boundary-artifact
              :kernel-ir-or-target-modules
              :device-binary-or-intermediate-artifacts
              :host-stub-artifact
              :kernel-lowering-map
              :device-memory-lifetime-report
              :transfer-graph
              :synchronization-graph
              :launch-descriptor
              :target-feature-and-occupancy-report
              :math-certificate-bundle
              :source-debug-map
              :spirv-validation-record])
     :diagnostics-covered?
     (= (set b8-document-diagnostic-ids) diagnostics)
     :external-spirv-validation?
     (get-in manifest [:spirv-validation-record :status])
     :status :complete}))

(defn b8-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b8-document-source-overrides module)
        _ (b8-document-validate-source-overrides! source-path
                                                  source-overrides)
        specialized-artifact (specialized-lowering-source-artifact source-path
                                                                   source-text)
        input-id (:artifact-id specialized-artifact)
        manifest (b8-document-gpu-manifest source-path input-id)
        diagnostic-stream (b8-document-diagnostic-stream source-path
                                                         input-id)
        artifact-base
        {:kind :gravity/stage0-b8-gpu-backend-document-artifact
         :task "P07-D105"
         :document-set ["B8"]
         :governing-document b8-document-governing-document
         :pass {:name :b8-gpu-backend-document-coverage
                :input :specialized-lowering-artifact
                :output :b8-gpu-backend-document-artifact
                :requires [:verified-mir-or-gpu-domain-ir
                           :b1-backend-interface :c14-target-lowering
                           :gpu-profile :host-device-boundary
                           :device-memory-lifetimes :transfer-graph
                           :sync-graph :numeric-mode
                           :math-certificate]
                :preserves [:source-spans :generated-origins :types
                            :effects :capabilities :memory-lifetimes
                            :synchronization :numeric-modes :safety
                            :proofs :profile :target
                            :artifact-provenance]
                :emits [:gpu-backend-manifest :kernel-module
                        :device-binary :host-stub :launch-descriptor
                        :device-memory-lifetime-report :transfer-graph
                        :synchronization-graph
                        :target-feature-occupancy-report
                        :math-certificate-bundle :source-debug-map
                        :b8-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b8-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :specialized-lowering-artifact
         (select-keys specialized-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :specialized-lowering-results])
         :specialized-lowering-artifact-kind (:kind specialized-artifact)
         :specialized-lowering-artifact-hash input-id
         :gpu-backend-manifest manifest
         :host-device-boundary-artifact
         (:host-device-boundary-artifact manifest)
         :kernel-ir-or-target-modules
         (:kernel-ir-or-target-modules manifest)
         :device-binary-or-intermediate-artifacts
         (:device-binary-or-intermediate-artifacts manifest)
         :host-stub-artifact (:host-stub-artifact manifest)
         :kernel-lowering-map (:kernel-lowering-map manifest)
         :device-memory-lifetime-report
         (:device-memory-lifetime-report manifest)
         :transfer-graph (:transfer-graph manifest)
         :synchronization-graph (:synchronization-graph manifest)
         :launch-descriptor (:launch-descriptor manifest)
         :target-feature-and-occupancy-report
         (:target-feature-and-occupancy-report manifest)
         :math-certificate-bundle (:math-certificate-bundle manifest)
         :source-debug-map (:source-debug-map manifest)
         :rejected-design-coverage
         [{:design :gpu-kernel-as-host-function
           :diagnostic "B8-KERNEL" :status :rejected}
          {:design :implicit-host-device-transfer
           :diagnostic "B8-TRANSFER" :status :rejected}
          {:design :host-effect-blocking-io-dynamic-eval-in-kernel
           :diagnostic "B8-HOST-EFFECT" :status :rejected}
          {:design :unchecked-device-aliasing-shared-mutable-state
           :diagnostic "B8-MEMORY" :status :rejected}
          {:design :backend-specific-approximate-math-without-certificate
           :diagnostic "B8-MATH" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b8-gpu-backend-conformance-criteria-record
          :host-device-boundary-artifacts :complete
          :accepted-rejected-kernel-feature-fixtures :covered
          :device-memory-lifetime-linear-resource-checks :complete
          :explicit-transfer-graph-validation :complete
          :synchronization-graph-validation :complete
          :atomics-memory-scope-mapping :complete
          :target-feature-launch-configuration-acceptance-rejection :complete
          :strict-approximate-math-certificate-fixtures :complete
          :source-proof-safety-capability-metadata-preservation :complete
          :differential-execution :mir-reference-recorded
          :status :passed}
         :b8-diagnostic-stream diagnostic-stream
         :b8-document-results
         {:documents ["B8"]
          :task "P07-D105"
          :required-diagnostic-ids b8-document-diagnostic-ids
          :specialized-lowering-input-status :complete
          :target-status :complete
          :kernel-status :complete
          :host-effect-status :complete
          :memory-status :complete
          :transfer-status :complete
          :sync-status :complete
          :atomic-status :complete
          :launch-status :complete
          :math-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b8-document-validate! source-path artifact-base)
        capability-proof (b8-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b8-document-file-artifact
  [path]
  (b8-document-source-artifact path (slurp path)))

(def b9-document-governing-document
  "docs/phase-07-backend-architecture/106-b9-hdl-backend-design.md")

(def b9-document-diagnostic-ids
  ["B9-TARGET"
   "B9-WIDTH"
   "B9-CLOCK"
   "B9-RESET"
   "B9-CDC"
   "B9-RUNTIME"
   "B9-UNBOUNDED"
   "B9-INTERFACE"
   "B9-TIMING"
   "B9-MANIFEST"])

(def b9-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             b9-document-diagnostic-ids)))

(defn b9-document-source-overrides
  [module]
  (or (get-in module [:metadata :backend :b9-document])
      (get-in module [:metadata :backend :specialized-lowering])
      (get-in module [:metadata :backend :specialized])
      {}))

(defn b9-document-missing-fact
  [id]
  (case id
    "B9-TARGET" :hdl-target-provider-constraint-format
    "B9-WIDTH" :fixed-width-signedness-truncation-proof
    "B9-CLOCK" :clock-domain-record
    "B9-RESET" :reset-domain-record
    "B9-CDC" :cdc-synchronizer-or-waiver-proof
    "B9-RUNTIME" :hardware-runtime-construct-rejection-proof
    "B9-UNBOUNDED" :finite-state-static-control-proof
    "B9-INTERFACE" :port-bus-protocol-capability-schema
    "B9-TIMING" :timing-constraint-and-provider-report
    :hdl-artifact-manifest))

(defn b9-document-signal-id
  [id]
  (case id
    "B9-CLOCK" :clk
    "B9-RESET" :rst
    "B9-CDC" :cdc_handshake
    "B9-INTERFACE" :ready_valid
    "B9-WIDTH" :accumulator
    "B9-TIMING" :clk_to_done
    "B9-RUNTIME" :runtime_call
    "B9-UNBOUNDED" :control_loop
    :gravity_stage0_hdl))

(defn b9-document-fail!
  [id source-path subject extra]
  (fail! id
         "B9 HDL backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b9-hdl-backend-document
                 :stage :b9-hdl-backend-document-coverage
                 :backend :gravity.backend/hdl
                 :profile :hardware
                 :target :systemverilog
                 :hardware-module :gravity_stage0_hdl
                 :signal-or-state-id (b9-document-signal-id id)
                 :clock-domain :clk
                 :reset-domain :rst
                 :missing-proof-or-constraint
                 (b9-document-missing-fact id)
                 :fallback-status :rejected
                 :remediation "B9 requires verified hardware IR, fixed-width layout, explicit clock/reset and CDC records, finite-state control, hardware interface schemas, timing constraints, testbench/simulation trace evidence, source maps, and HDL artifact provenance."}
                extra)))

(defn b9-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b9-document-override-diagnostics fail-kind)]
      (b9-document-fail!
       id source-path
       {:artifact-id (str "b9-document-" (name fail-kind))
        :signal-or-state-id (keyword (str "b9-document-" (name fail-kind)))}
       {:missing-fields [fail-kind]}))))

(def b9-document-hdl-module
  (str
   "module gravity_stage0_hdl(\n"
   "  input logic clk,\n"
   "  input logic rst,\n"
   "  input logic input_valid,\n"
   "  input logic [31:0] input_data,\n"
   "  output logic output_ready,\n"
   "  output logic done\n"
   ");\n"
   "  typedef enum logic [1:0] {IDLE, ACCUMULATE, DONE} state_t;\n"
   "  state_t state;\n"
   "  logic [31:0] accumulator;\n"
   "  always_ff @(posedge clk) begin\n"
   "    if (rst) begin\n"
   "      state <= IDLE;\n"
   "      accumulator <= 32'd0;\n"
   "      done <= 1'b0;\n"
   "    end else begin\n"
   "      case (state)\n"
   "        IDLE: if (input_valid) begin accumulator <= input_data; state <= ACCUMULATE; end\n"
   "        ACCUMULATE: begin accumulator <= accumulator + 32'd1; state <= DONE; end\n"
   "        DONE: begin done <= 1'b1; state <= DONE; end\n"
   "      endcase\n"
   "    end\n"
   "  end\n"
   "  assign output_ready = (state == DONE);\n"
   "endmodule\n"))

(def b9-document-testbench
  (str
   "module gravity_stage0_hdl_tb;\n"
   "  logic clk = 1'b0;\n"
   "  logic rst = 1'b1;\n"
   "  logic input_valid = 1'b0;\n"
   "  logic [31:0] input_data = 32'd7;\n"
   "  logic output_ready;\n"
   "  logic done;\n"
   "  gravity_stage0_hdl dut(clk, rst, input_valid, input_data, output_ready, done);\n"
   "  always #5 clk = ~clk;\n"
   "  initial begin\n"
   "    repeat (2) @(posedge clk);\n"
   "    rst = 1'b0;\n"
   "    input_valid = 1'b1;\n"
   "    repeat (4) @(posedge clk);\n"
   "    $finish;\n"
   "  end\n"
   "endmodule\n"))

(def b9-document-timing-constraints
  (str
   "create_clock -name clk -period 10 [get_ports clk]\n"
   "set_input_delay 1 -clock clk [get_ports input_data]\n"
   "set_output_delay 1 -clock clk [get_ports done]\n"))

(defn b9-document-hdl-structurally-valid?
  [text]
  (and (str/includes? text "module gravity_stage0_hdl")
       (str/includes? text "typedef enum logic [1:0]")
       (str/includes? text "always_ff @(posedge clk)")
       (str/includes? text "if (rst)")
       (str/includes? text "assign output_ready")))

(defn b9-document-testbench-structurally-valid?
  [text]
  (and (str/includes? text "module gravity_stage0_hdl_tb")
       (str/includes? text "gravity_stage0_hdl dut")
       (str/includes? text "repeat (")
       (str/includes? text "$finish")))

(defn b9-document-timing-structurally-valid?
  [text]
  (and (str/includes? text "create_clock")
       (str/includes? text "set_input_delay")
       (str/includes? text "set_output_delay")))

(defn b9-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b9-hdl-backend-diagnostic-stream
   :stage :b9-hdl-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b9-hdl-backend-document-coverage
            :backend :gravity.backend/hdl
            :message-key (keyword "backend-hdl" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b9-document-syntax-" index)
                      :artifact input-id}
            :profile :hardware
            :target :systemverilog
            :hardware-module :gravity_stage0_hdl
            :signal-or-state-id (b9-document-signal-id id)
            :clock-domain :clk
            :reset-domain :rst
            :missing-proof-or-constraint (b9-document-missing-fact id)
            :source-generated-origin-chain
            [:mir :c12-hardware-domain-ir :c14-target-lowering
             :b1-interface :b9-hdl-backend]
            :fallback-status :rejected
            :facts {:fixed-widths-required true
                    :implicit-runtime-rejected true
                    :unmediated-cdc-rejected true
                    :timing-constraints-required true}
            :remediation [{:kind :declare-hdl-target-provider-and-constraints}
                          {:kind :attach-fixed-width-clock-reset-cdc-records}
                          {:kind :emit-testbench-and-simulation-trace}]
            :redactions []
            :ordering-key [id :b9-hdl-backend-document-coverage
                           :systemverilog]})
         b9-document-diagnostic-ids
         (range))
   :status :complete})

(defn b9-document-hdl-manifest
