                 :accumulate "2'b01"
                 :done "2'b10"}
      :transitions [{:from :idle :to :accumulate
                     :condition :input_valid}
                    {:from :accumulate :to :done
                     :condition :next-cycle}
                    {:from :done :to :done
                     :condition :terminal}]
      :finite-control-proof "SAFE15-stage0-finite-state"
      :status :complete}
     :memory-block-manifest
     {:blocks [{:id :accumulator
                :kind :register
                :width 32
                :depth 1
                :clock-domain :clk
                :reset-domain :rst}
               {:id :state
                :kind :register
                :width 2
                :depth 1
                :clock-domain :clk
                :reset-domain :rst}]
      :heap-allocation :rejected
      :status :complete}
     :cdc-report
