      :ordering [:started :model-output-recorded :tool-output-recorded
                 :human-reviewed :external-write-idempotent]
      :status :complete}
     :replay-policy
     {:mode :event-log
      :nondeterminism [:clock :random :network-response
                       :database-result :model-output :tool-output
                       :human-review-decision]
      :recorded-values [:clock :model-output :tool-output
                        :human-review-decision :service-response]
      :side-effects :not-reissued-without-idempotency
      :replay-safe-steps #{:start :approve-output :done}
      :status :complete}
     :replay-fixtures
     [{:path "gravity_stage0_workflow_replay.edn"
       :content b10-document-replay-fixture
       :hash replay-hash
       :status :complete}]
     :idempotency-key-map
     {:steps {:call-model "workflow-input-digest:call-model"
              :call-tool "workflow-input-digest:call-tool"
              :write-ticket "workflow-input-hash:ticket-id"}
      :side-effecting-steps [:call-model :call-tool :write-ticket]
      :status :complete}
     :retry-timeout-cancellation-compensation-table
     {:steps {:call-model {:retry :bounded-exponential
                           :timeout-ms 30000
                           :cancellation :cancel-provider-request
                           :failure-map {:timeout :retryable
                                         :policy-denied :terminal}
                           :compensation :record-model-call-cancelled}
              :call-tool {:retry :bounded-linear
                          :timeout-ms 15000
                          :cancellation :cancel-tool-request
                          :failure-map {:tool-error :manual-review}
                          :compensation :record-tool-call-cancelled}
              :write-ticket {:retry :bounded-exponential
                             :timeout-ms 10000
                             :cancellation :idempotency-key-cancel
                             :failure-map {:conflict :replay-existing
                                           :service-down :retryable}
                             :compensation :compensate-ticket}}
      :status :complete}
     :external-capability-manifest
     {:capabilities #{:network/request :db/write :ai/model-call
                      :ai/tool-call :memory/read :secret/read
                      :ai/human-review}
      :providers [{:id :stage0-model-provider
                   :kind :model
                   :model "gravity-stage0-model"
                   :prompt-digest "sha256:prompt-stage0"}
                  {:id :stage0-tool-provider
                   :kind :tool
                   :tool-version "stage0-tool-v1"}
                  {:id :stage0-ticket-service
                   :kind :external-service
                   :endpoint-digest "sha256:ticket-service-stage0"}]
      :ambient-authority :rejected
      :prompt-created-authority :rejected
      :status :complete}
     :tool-model-provider-manifest
     {:model-calls [{:step :call-model
                     :provider :stage0-model-provider
                     :model "gravity-stage0-model"
                     :prompt-digest "sha256:prompt-stage0"
                     :message-digest "sha256:message-stage0"
                     :evaluation-evidence "eval:stage0-workflow"}]
      :tool-calls [{:step :call-tool
                    :provider :stage0-tool-provider
                    :tool-version "stage0-tool-v1"
                    :input-digest "sha256:tool-input-stage0"
                    :output-digest "sha256:tool-output-stage0"}]
      :provider-substitution-policy :policy-pinned
      :status :complete}
     :human-review-policy-graph
     {:gates [{:step :approve-output
               :capability :ai/human-review
               :required-before [:write-ticket]
               :records [:reviewer-id :decision :timestamp :rationale]}]
      :trusted-after-validation [:approved-ticket-payload]
      :status :complete}
     :policy-graph
     {:budget {:model-tokens 2048
               :tool-calls 1
               :external-writes 1}
      :rate-policy {:call-model :bounded
                    :call-tool :bounded}
      :provider-policy {:call-model :stage0-model-provider
                        :call-tool :stage0-tool-provider}
      :human-review-required [:write-ticket]
      :status :complete}
     :taint-validation-report
     {:tainted-sources [:model-output :tool-output :external-response]
      :validated-sinks [{:sink :write-ticket
                         :requires [:schema-validation
                                    :human-review
                                    :policy-approval]}]
      :unvalidated-trusted-sinks []
      :status :complete}
     :audit-provenance-record
     {:source-map :preserved
      :generated-origin-chain [:mir :c11-mir :c12-workflow-domain-ir
                               :c14-target-lowering :b1-interface
                               :b10-workflow-graph-backend]
      :policy-decisions [:provider-pinned :human-review-required
                         :taint-validated]
      :human-review-records [:approve-output]
      :artifact-provenance {:graph graph-hash
                            :replay replay-hash}
      :status :complete}
     :graph-validation-report
     {:nodes [:start :call-model :call-tool :approve-output
              :write-ticket :compensate-ticket :done]
      :edges [[:start :call-model]
              [:call-model :call-tool]
              [:call-tool :approve-output]
              [:approve-output :write-ticket]
              [:write-ticket :done]
              [:write-ticket :compensate-ticket]]
      :invalid-cycles []
      :unreachable-compensation []
      :bounded-cycles []
      :status :complete}
     :differential-replay-record
     {:reference :recorded-event-log
      :candidate :workflow-graph-replay
      :matched-events [:started :model-output-recorded
                       :tool-output-recorded :human-reviewed
                       :external-write-idempotent]
      :status :matched}
     :source-debug-map
     {:source input-id
      :locations [(str source-path ":workflow")
                  (str source-path ":steps")
                  (str source-path ":policy")
                  (str source-path ":replay")]
      :generated-origin-chain [:mir :c11-mir :c12-workflow-domain-ir
                               :c14-target-lowering :b1-interface
                               :b10-workflow-graph-backend]
      :step-source-map {:call-model "workflow:call-model"
                        :call-tool "workflow:call-tool"
                        :approve-output "workflow:approve-output"
                        :write-ticket "workflow:write-ticket"}
      :policy-source-map {:human-review "workflow:approve-output"
                          :taint-validation "workflow:trusted-sink"}
      :status :preserved}
     :external-runtime-validation-record
     {:declared-command
      "gravity-workflow-replay --manifest /tmp/gravity-p07-b10-workflow/gravity_stage0_workflow.edn"
      :proof-artifact
      "docs/artifacts/phase-07/reports/p07-d107-b10-workflow-graph-backend-report.md"
      :status :not-available-in-current-environment}
     :status :complete}))

(defn b10-document-validate!
  [source-path artifact]
  (let [specialized (:specialized-lowering-artifact artifact)
        manifest (:workflow-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b10-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-specialized-lowering-artifact
                 (:kind specialized))
      (b10-document-fail! "B10-MANIFEST" source-path specialized
                          {:missing-fields [:specialized-lowering-artifact]}))
    (when-not (= :complete (get-in specialized
                                   [:capability-based-proof :status]))
      (b10-document-fail! "B10-MANIFEST" source-path specialized
                          {:missing-fields [:specialized-lowering-proof]}))
    (when-not (= :durable-workflow (get-in manifest [:target :runtime]))
      (b10-document-fail! "B10-MANIFEST" source-path manifest
                          {:missing-fields [:target-runtime]}))
    (when-not (= :complete (get-in manifest
                                   [:workflow-ir-handoff-record :status]))
      (b10-document-fail! "B10-MANIFEST" source-path manifest
                          {:missing-fields [:workflow-ir-handoff-record]}))
    (when-not (= :complete (get-in manifest
                                   [:workflow-graph-artifact :status]))
      (b10-document-fail! "B10-GRAPH" source-path manifest
                          {:missing-fields [:workflow-graph-artifact]}))
    (when-not (b10-document-workflow-graph-structurally-valid?
               b10-document-workflow-graph)
      (b10-document-fail! "B10-GRAPH" source-path manifest
                          {:missing-fields [:workflow-graph-structure]}))
    (when-not (= :complete (get-in manifest
                                   [:step-schema-bundle :status]))
      (b10-document-fail! "B10-SCHEMA" source-path manifest
                          {:missing-fields [:step-schema-bundle]}))
    (when-not (= :complete (get-in manifest
                                   [:event-log-schema :status]))
      (b10-document-fail! "B10-REPLAY" source-path manifest
                          {:missing-fields [:event-log-schema]}))
    (when-not (= :complete (get-in manifest [:replay-policy :status]))
      (b10-document-fail! "B10-REPLAY" source-path manifest
                          {:missing-fields [:replay-policy]}))
    (when-not (b10-document-replay-fixture-structurally-valid?
               b10-document-replay-fixture)
      (b10-document-fail! "B10-REPLAY" source-path manifest
                          {:missing-fields [:replay-fixture-structure]}))
    (when-not (= :complete (get-in manifest
                                   [:idempotency-key-map :status]))
      (b10-document-fail! "B10-IDEMPOTENCY" source-path manifest
                          {:missing-fields [:idempotency-key-map]}))
    (when-not (= :complete
                 (get-in manifest
                         [:retry-timeout-cancellation-compensation-table
                          :status]))
      (b10-document-fail! "B10-RETRY" source-path manifest
                          {:missing-fields [:retry-timeout-cancellation]}))
    (when-not (every? #(contains? % :compensation)
                      (vals (get-in manifest
                                    [:retry-timeout-cancellation-compensation-table
                                     :steps])))
      (b10-document-fail! "B10-COMPENSATION" source-path manifest
                          {:missing-fields [:compensation-handlers]}))
    (when-not (= :complete (get-in manifest
                                   [:external-capability-manifest
                                    :status]))
      (b10-document-fail! "B10-CAPABILITY" source-path manifest
                          {:missing-fields [:external-capability-manifest]}))
    (when-not (= :rejected (get-in manifest
                                   [:external-capability-manifest
                                    :ambient-authority]))
      (b10-document-fail! "B10-CAPABILITY" source-path manifest
                          {:missing-fields [:ambient-authority-rejection]}))
    (when-not (= :complete (get-in manifest [:policy-graph :status]))
      (b10-document-fail! "B10-POLICY" source-path manifest
                          {:missing-fields [:policy-graph]}))
    (when-not (= :complete (get-in manifest
                                   [:human-review-policy-graph
                                    :status]))
      (b10-document-fail! "B10-POLICY" source-path manifest
                          {:missing-fields [:human-review-policy-graph]}))
    (when-not (= :complete (get-in manifest
                                   [:taint-validation-report :status]))
      (b10-document-fail! "B10-TAINT" source-path manifest
                          {:missing-fields [:taint-validation-report]}))
    (when-not (empty? (get-in manifest
                              [:taint-validation-report
                               :unvalidated-trusted-sinks]))
      (b10-document-fail! "B10-TAINT" source-path manifest
                          {:missing-fields [:validated-trusted-sinks]}))
    (when-not (= :complete (get-in manifest
                                   [:graph-validation-report :status]))
      (b10-document-fail! "B10-GRAPH" source-path manifest
                          {:missing-fields [:graph-validation-report]}))
    (when-not (= :matched (get-in manifest
                                  [:differential-replay-record :status]))
      (b10-document-fail! "B10-REPLAY" source-path manifest
                          {:missing-fields [:differential-replay-record]}))
    (when-not (= :complete (get-in manifest
                                   [:audit-provenance-record :status]))
      (b10-document-fail! "B10-MANIFEST" source-path manifest
                          {:missing-fields [:audit-provenance-record]}))
    (when-not (= :preserved (get-in manifest [:source-debug-map :status]))
      (b10-document-fail! "B10-MANIFEST" source-path manifest
                          {:missing-fields [:source-debug-map]}))
    (when-not (every? #(contains? manifest %)
                      [:workflow-ir-handoff-record
                       :workflow-graph-artifact
                       :step-schema-bundle
                       :event-log-schema
                       :replay-policy
                       :replay-fixtures
                       :idempotency-key-map
                       :retry-timeout-cancellation-compensation-table
                       :external-capability-manifest
                       :tool-model-provider-manifest
                       :human-review-policy-graph
                       :policy-graph
                       :taint-validation-report
                       :audit-provenance-record
                       :graph-validation-report
                       :differential-replay-record
                       :source-debug-map
                       :external-runtime-validation-record])
      (b10-document-fail! "B10-MANIFEST" source-path manifest
                          {:missing-fields [:workflow-artifact-manifest]}))
    (when-not (= (set b10-document-diagnostic-ids) diagnostics)
      (b10-document-fail! "B10-MANIFEST" source-path
                          (:b10-diagnostic-stream artifact)
                          {:missing-fields [:b10-diagnostics]})))
  :complete)

(defn b10-document-capability-proof
  [artifact]
  (let [manifest (:workflow-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b10-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:specialized-lowering-artifact
                           :capability-based-proof :status]))
     :workflow-ir-handoff-covered?
     (= :complete (get-in manifest
                          [:workflow-ir-handoff-record :status]))
     :workflow-graph-emitted?
     (= :complete (get-in manifest
                          [:workflow-graph-artifact :status]))
     :workflow-graph-structurally-valid?
     (b10-document-workflow-graph-structurally-valid?
      b10-document-workflow-graph)
     :schema-bundle-covered?
     (= :complete (get-in manifest [:step-schema-bundle :status]))
     :event-log-schema-covered?
     (= :complete (get-in manifest [:event-log-schema :status]))
     :replay-policy-covered?
     (= :complete (get-in manifest [:replay-policy :status]))
     :replay-fixture-covered?
     (and (= :complete (get-in manifest [:replay-fixtures 0 :status]))
          (b10-document-replay-fixture-structurally-valid?
           b10-document-replay-fixture))
     :idempotency-covered?
     (= :complete (get-in manifest [:idempotency-key-map :status]))
     :retry-timeout-cancellation-covered?
     (= :complete
        (get-in manifest
                [:retry-timeout-cancellation-compensation-table
                 :status]))
     :compensation-covered?
     (every? #(contains? % :compensation)
             (vals (get-in manifest
                           [:retry-timeout-cancellation-compensation-table
                            :steps])))
     :capability-manifest-covered?
     (= :complete (get-in manifest
                          [:external-capability-manifest :status]))
     :ambient-authority-rejected?
     (= :rejected (get-in manifest
                          [:external-capability-manifest
                           :ambient-authority]))
     :tool-model-provider-manifest-covered?
     (= :complete (get-in manifest
                          [:tool-model-provider-manifest :status]))
     :human-review-policy-covered?
     (= :complete (get-in manifest
                          [:human-review-policy-graph :status]))
     :policy-graph-covered?
     (= :complete (get-in manifest [:policy-graph :status]))
     :taint-validation-covered?
     (and (= :complete (get-in manifest
                               [:taint-validation-report :status]))
          (empty? (get-in manifest
                          [:taint-validation-report
                           :unvalidated-trusted-sinks])))
     :audit-provenance-preserved?
     (= :complete (get-in manifest
                          [:audit-provenance-record :status]))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :differential-replay-matched?
     (= :matched (get-in manifest
                         [:differential-replay-record :status]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:workflow-ir-handoff-record
              :workflow-graph-artifact
              :step-schema-bundle
              :event-log-schema
              :replay-policy
              :replay-fixtures
              :idempotency-key-map
              :retry-timeout-cancellation-compensation-table
              :external-capability-manifest
              :tool-model-provider-manifest
              :human-review-policy-graph
              :policy-graph
              :taint-validation-report
              :audit-provenance-record
              :graph-validation-report
              :differential-replay-record
              :source-debug-map
              :external-runtime-validation-record])
     :diagnostics-covered?
     (= (set b10-document-diagnostic-ids) diagnostics)
     :external-runtime-validation?
     (get-in manifest [:external-runtime-validation-record :status])
     :status :complete}))

(defn b10-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b10-document-source-overrides module)
        _ (b10-document-validate-source-overrides! source-path
                                                   source-overrides)
        specialized-artifact (specialized-lowering-source-artifact source-path
                                                                   source-text)
        input-id (:artifact-id specialized-artifact)
        manifest (b10-document-workflow-manifest source-path input-id)
        diagnostic-stream (b10-document-diagnostic-stream source-path
                                                          input-id)
        artifact-base
        {:kind :gravity/stage0-b10-workflow-graph-backend-document-artifact
         :task "P07-D107"
         :document-set ["B10"]
         :governing-document b10-document-governing-document
         :pass {:name :b10-workflow-graph-backend-document-coverage
                :input :specialized-lowering-artifact
                :output :b10-workflow-graph-backend-document-artifact
                :requires [:verified-mir-or-workflow-domain-ir
                           :b1-backend-interface :c11-mir
                           :c12-domain-ir :c14-target-lowering
                           :distributed-profile :ai-profile
                           :step-schemas :event-log-schema
                           :replay-policy :idempotency
                           :retry-timeout-cancellation
                           :compensation :capability-manifest
                           :human-review-policy]
                :preserves [:source-spans :generated-origins :schemas
                            :effects :capabilities :policy-decisions
                            :human-review-records :taint-facts
                            :audit-metadata :safety :proofs
                            :profile :target :artifact-provenance]
                :emits [:workflow-backend-manifest
                        :workflow-graph-artifact
                        :step-schema-bundle :event-log-schema
                        :replay-policy :replay-fixture
                        :idempotency-key-map
                        :retry-timeout-cancellation-compensation-table
                        :external-capability-manifest
                        :tool-model-provider-manifest
                        :human-review-policy-graph :policy-graph
                        :taint-validation-report
                        :audit-provenance-record
                        :differential-replay-record
                        :b10-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b10-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :specialized-lowering-artifact
         (select-keys specialized-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :specialized-lowering-results])
         :specialized-lowering-artifact-kind (:kind specialized-artifact)
         :specialized-lowering-artifact-hash input-id
         :workflow-backend-manifest manifest
         :workflow-ir-handoff-record
         (:workflow-ir-handoff-record manifest)
         :workflow-graph-artifact
         (:workflow-graph-artifact manifest)
         :step-schema-bundle (:step-schema-bundle manifest)
         :event-log-schema (:event-log-schema manifest)
         :replay-policy (:replay-policy manifest)
         :replay-fixtures (:replay-fixtures manifest)
         :idempotency-key-map (:idempotency-key-map manifest)
         :retry-timeout-cancellation-compensation-table
         (:retry-timeout-cancellation-compensation-table manifest)
         :external-capability-manifest
         (:external-capability-manifest manifest)
         :tool-model-provider-manifest
         (:tool-model-provider-manifest manifest)
         :human-review-policy-graph
         (:human-review-policy-graph manifest)
         :policy-graph (:policy-graph manifest)
         :taint-validation-report (:taint-validation-report manifest)
         :audit-provenance-record (:audit-provenance-record manifest)
         :graph-validation-report (:graph-validation-report manifest)
         :differential-replay-record
         (:differential-replay-record manifest)
         :source-debug-map (:source-debug-map manifest)
         :rejected-design-coverage
         [{:design :unrecorded-nondeterministic-workflow
           :diagnostic "B10-REPLAY" :status :rejected}
          {:design :schema-less-workflow-step-or-message
           :diagnostic "B10-SCHEMA" :status :rejected}
          {:design :ambient-tool-service-database-model-access
           :diagnostic "B10-CAPABILITY" :status :rejected}
          {:design :side-effecting-replay-without-idempotency
           :diagnostic "B10-IDEMPOTENCY" :status :rejected}
          {:design :prompt-or-model-output-as-policy-authority
           :diagnostic "B10-POLICY" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b10-workflow-graph-backend-conformance-criteria-record
          :workflow-graph-emission-from-mir-domain-anchors :complete
          :workflow-step-message-state-schema-bundles :complete
          :replay-rejection-for-unrecorded-nondeterminism :covered
          :idempotency-retry-timeout-cancellation-compensation-fixtures
          :complete
          :service-database-model-tool-memory-secret-human-review-capability-checks
          :complete
          :taint-validation-for_model_tool_external_outputs :complete
          :event-log-schema-and-replay-fixture-generation :complete
          :source-provenance-policy-audit-metadata-preservation :complete
          :differential-replay-against-recorded-traces :matched
          :status :passed}
         :b10-diagnostic-stream diagnostic-stream
         :b10-document-results
         {:documents ["B10"]
          :task "P07-D107"
          :required-diagnostic-ids b10-document-diagnostic-ids
          :specialized-lowering-input-status :complete
          :workflow-ir-status :complete
          :graph-status :complete
          :schema-status :complete
          :event-log-status :complete
          :replay-status :complete
          :idempotency-status :complete
          :retry-timeout-cancellation-status :complete
          :compensation-status :complete
          :capability-status :complete
          :tool-model-provider-status :complete
          :human-review-policy-status :complete
          :taint-status :complete
          :audit-status :complete
          :differential-replay-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b10-document-validate! source-path artifact-base)
        capability-proof (b10-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b10-document-file-artifact
  [path]
  (b10-document-source-artifact path (slurp path)))

(def b11-document-governing-document
  "docs/phase-07-backend-architecture/108-b11-query-relational-backend-design.md")

(def b11-document-diagnostic-ids
  ["B11-DIALECT"
   "B11-SCHEMA"
   "B11-TAINT"
   "B11-PARAMETER"
   "B11-CAPABILITY"
   "B11-TRANSACTION"
   "B11-NULL"
   "B11-MIGRATION"
   "B11-RESULT"
   "B11-PLAN"
   "B11-MANIFEST"])

(def b11-document-override-diagnostics
  {:b11-dialect "B11-DIALECT"
   :b11-schema "B11-SCHEMA"
   :b11-taint "B11-TAINT"
   :b11-parameter "B11-PARAMETER"
   :b11-capability "B11-CAPABILITY"
   :b11-transaction "B11-TRANSACTION"
   :b11-null "B11-NULL"
   :b11-migration "B11-MIGRATION"
   :b11-result "B11-RESULT"
   :b11-plan "B11-PLAN"
   :b11-manifest "B11-MANIFEST"})

(defn b11-document-source-overrides
  [module]
  (get-in module [:metadata :backend :specialized-lowering] {}))

(defn b11-document-missing-policy
  [id]
  (case id
    "B11-DIALECT" :dialect-version-type-map
    "B11-SCHEMA" :schema-version-compatibility
    "B11-TAINT" :taint-proof-for-sql-syntax
    "B11-PARAMETER" :prepared-parameter-bindings
    "B11-CAPABILITY" :database-authority-grant
    "B11-TRANSACTION" :transaction-isolation-retry-timeout
    "B11-NULL" :sql-null-three-valued-logic-map
    "B11-MIGRATION" :migration-compatibility-and-data-loss-policy
    "B11-RESULT" :typed-result-adapter-validation
    "B11-PLAN" :provider-plan-semantic-equivalence
    :query-artifact-manifest))

(defn b11-document-query-id
  [id]
  (case id
    "B11-DIALECT" :dialect-map
    "B11-SCHEMA" :schema-map
    "B11-TAINT" :dynamic-sql
    "B11-PARAMETER" :select-gravity-value
    "B11-CAPABILITY" :write-gravity-value
    "B11-TRANSACTION" :transaction-record
    "B11-NULL" :null-semantics
    "B11-MIGRATION" :stage0-migration
    "B11-RESULT" :gravity-value-adapter
    "B11-PLAN" :provider-plan
    :query-manifest))

(defn b11-document-fail!
  [id source-path subject extra]
  (fail! id
         "B11 query/relational backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b11-query-relational-backend-document
                 :stage :b11-query-relational-backend-document-coverage
                 :backend :gravity.backend/query-relational
                 :profile :hosted
                 :target :postgresql
                 :query-id (or (:query-id subject)
                               (b11-document-query-id id))
                 :schema-id (or (:schema-id subject) :stage0-v1)
                 :dialect (or (:dialect subject) :postgresql)
                 :parameter-id (or (:parameter-id subject) :gravity-value)
                 :column-id (or (:column-id subject) :gravity_value)
                 :effect (or (:effect subject) :db/read)
                 :capability (or (:capability subject) :db/read)
                 :taint-category (or (:taint-category subject)
                                     :external-input)
                 :migration-state (or (:migration-state subject)
                                      :compatible)
                 :missing-policy (b11-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "B11 requires verified relational IR, explicit dialect/schema/version/provider records, parameterized SQL, capability and taint evidence, transaction and migration policy, null/type/result adapters, provider-plan evidence, and a complete query artifact manifest."}
                extra)))

(defn b11-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b11-document-override-diagnostics fail-kind)]
      (b11-document-fail!
       id source-path
       {:artifact-id (str "b11-document-" (name fail-kind))
        :query-id (keyword (str "b11-document-" (name fail-kind)))}
       {:missing-fields [fail-kind]}))))

(def b11-document-sql-statement
  "select $1::bigint as gravity_value\n")

(def b11-document-migration-sql
  (str
   "-- gravity stage0 schema compatibility migration\n"
   "-- no data rewrite; schema id remains stage0-v1\n"
   "select 1 as gravity_stage0_migration_noop;\n"))

(def b11-document-result-adapter-fixture
  (str
   "{:adapter :gravity-stage0-value-row\n"
   " :columns [{:name :gravity_value\n"
   "            :gravity-type :I64\n"
   "            :database-type :bigint\n"
   "            :nullability :nonnull\n"
   "            :validation :checked}]\n"
   " :taint-policy :validated\n"
   " :status :complete}\n"))

(defn b11-document-sql-structurally-valid?
  [text]
  (and (str/includes? text "$1::bigint")
       (str/includes? text "gravity_value")
       (not (str/includes? text "||"))
       (not (str/includes? text "${"))
       (not (str/includes? text "concat("))))

(defn b11-document-result-adapter-structurally-valid?
  [text]
  (and (str/includes? text ":gravity-type :I64")
       (str/includes? text ":database-type :bigint")
       (str/includes? text ":nullability :nonnull")
       (str/includes? text ":validation :checked")
       (str/includes? text ":taint-policy :validated")))

(defn b11-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/b11-query-relational-backend-diagnostic-stream
   :stage :b11-query-relational-backend-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :b11-query-relational-backend-document-coverage
            :backend :gravity.backend/query-relational
            :message-key (keyword "backend-query" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "b11-document-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :postgresql
            :query-id (b11-document-query-id id)
            :schema-id :stage0-v1
            :dialect :postgresql
            :parameter-id (case id
                            "B11-PARAMETER" :gravity-value
                            "B11-TAINT" :dynamic-fragment
                            :gravity-value)
            :column-id (case id
                         "B11-RESULT" :gravity_value
                         "B11-NULL" :gravity_value
                         :gravity_value)
            :effect (case id
                      "B11-CAPABILITY" :db/write
                      "B11-MIGRATION" :db/migrate
                      "B11-TRANSACTION" :db/read
                      :db/read)
            :capability (case id
                          "B11-CAPABILITY" :db/write
                          "B11-MIGRATION" :db/migrate
                          :db/read)
            :taint-category (case id
                              "B11-TAINT" :external-input
                              "B11-PARAMETER" :external-input
                              :validated)
            :migration-state (case id
                               "B11-MIGRATION" :drift-without-policy
                               :compatible)
            :missing-policy (b11-document-missing-policy id)
            :source-generated-origin-chain
            [:mir :c11-mir :c12-query-domain-ir
             :c14-target-lowering :b1-interface
             :b11-query-relational-backend]
            :fallback-status :rejected
            :facts {:prepared-statements-required true
                    :dynamic-tainted-sql-rejected true
                    :result-adapter-validation-required true
                    :migration-data-loss-requires-policy true
                    :provider-plan-movement-requires-evidence true}
            :remediation [{:kind :declare-dialect-schema-provider}
                          {:kind :parameterize-query-inputs}
                          {:kind :attach-capability-taint-policy}
                          {:kind :record-transaction-migration-adapter-plan}]
            :redactions []
            :ordering-key [id :b11-query-relational-backend-document-coverage
                           :postgresql]})
         b11-document-diagnostic-ids
         (range))
   :status :complete})

(defn b11-document-query-manifest
  [source-path input-id]
  (let [sql-hash (c4-artifact-id b11-document-sql-statement)
        migration-hash (c4-artifact-id b11-document-migration-sql)
        adapter-hash (c4-artifact-id b11-document-result-adapter-fixture)]
    {:artifact :gravity/query-backend-manifest
     :backend :gravity.backend/query-relational
     :target {:dialect :postgresql
              :version "stage0-declared"
              :schema-version :stage0-v1
              :provider :stage0-postgres-provider
              :parameter-style :postgres-numbered}
     :input-artifact input-id
     :relational-ir-handoff-record
     {:domain-anchor :relational-query
      :source-artifact input-id
      :accepted-by [:b1-backend-interface :c11-mir
                    :c12-domain-ir :c14-target-lowering
                    :p4-hosted-profile :p9-distributed-profile
                    :safe10-capability :safe11-taint]
      :status :complete}
     :dialect-schema-mapping
     {:engine :postgresql
      :version "stage0-declared"
      :features #{:prepared-statements :transactions :jsonb
                  :arrays :enums :collations}
      :type-mapping {:I64 :bigint
                     :String :text
                     :Bool :boolean
                     :Json :jsonb}
      :null-semantics :three-valued-logic-explicit
      :collation :declared
      :timezone :utc
      :numeric-precision {:bigint :exact
                          :numeric :declared-scale}
      :identifier-quoting :double-quote
      :parameter-style :postgres-numbered
      :transaction-support #{:read-committed :repeatable-read
                             :serializable}
      :status :complete}
     :schema-mapping-record
     {:schema-id :stage0-v1
      :version :stage0-v1
      :tables [{:name "gravity_values"
                :gravity-record :GravityValue
                :columns [{:name "gravity_value"
                           :gravity-type :I64
                           :database-type :bigint
                           :nullable false}]
                :constraints [:primary-key]
                :indexes [:gravity_values_pk]}]
      :views []
      :computed-fields []
      :compatibility :compatible
      :status :complete}
     :sql-statement-artifacts
     [{:id :select-gravity-value
       :path "gravity_stage0_query.sql"
       :sql b11-document-sql-statement
       :hash sql-hash
       :kind :prepared-select
       :evaluation-boundary :database
       :status :complete}]
     :prepared-binding-manifest
     {:parameters [{:position 1
                    :name :gravity-value
                    :source-expression "input.gravity_value"
                    :source-span (str source-path ":query")
                    :gravity-type :I64
                    :database-type :bigint
                    :taint-category :external-input
                    :validation-schema :stage0-value-parameter
                    :escaping :driver-bound
                    :capability :db/read
                    :binding-style :prepared-position}]
      :dynamic-string-construction :rejected
      :status :complete}
     :query-plan-metadata
     {:plan :index-neutral-select
      :provider :stage0-postgres-provider
      :evaluation-boundary :database
      :provider-specific-movement []
      :semantic-equivalence-evidence :not-required-no-provider-movement
      :taint-null-collation-evidence :preserved
      :status :complete}
     :typed-result-adapter
     {:path "gravity_stage0_result_adapter.edn"
      :content b11-document-result-adapter-fixture
      :hash adapter-hash
      :columns [{:name :gravity_value
                 :gravity-type :I64
                 :database-type :bigint
                 :nullability :nonnull
                 :conversion :checked
                 :taint-policy :validated}]
      :row-shape-validation :checked
      :enum-validation :not-applicable
      :json-validation :not-applicable
      :timezone-conversion :utc
      :status :complete}
     :transaction-isolation-manifest
     {:effect :db/read
      :capabilities #{:db/read}
      :isolation :read-committed
      :retry-policy :bounded
      :lock-behavior :none
      :timeout-ms 5000
      :idempotency-key :query-input-digest
      :savepoints :not-required
      :consistency-assumptions [:single-statement-read]
      :error-mapping {:timeout :retryable
                      :serialization-failure :retryable
                      :constraint-violation :terminal}
      :status :complete}
     :migration-artifact
     {:path "gravity_stage0_migration.sql"
      :content b11-document-migration-sql
      :hash migration-hash
      :previous-schema :stage0-v1
      :next-schema :stage0-v1
      :compatibility-policy :data-preserving
      :data-preserving-proof :same-schema-noop
      :data-loss :none
      :backfill-plan :not-required
      :rollback-policy :no-op
      :deployment-ordering [:validate-schema :run-noop-migration
                            :validate-queries]
      :validation-queries ["select 1 as gravity_stage0_migration_noop"]
      :status :complete}
     :schema-diff-compatibility-report
     {:previous-schema :stage0-v1
      :next-schema :stage0-v1
      :changes []
      :compatibility :compatible
      :data-loss-risk :none
      :status :complete}
     :capability-taint-report
     {:required-capabilities #{:db/read}
      :granted-capabilities #{:db/read}
      :denied-capabilities #{:db/write :db/migrate :db/admin}
      :taint-policy :validated
      :parameter-taint {:gravity-value :validated-by-schema}
      :tainted-string-query :rejected
      :write-without-capability :rejected
      :migration-without-capability :rejected
      :status :complete}
     :null-collation-timezone-numeric-json-enum-behavior
     {:null-semantics :three-valued-logic-explicit
      :nonnull-columns [:gravity_value]
      :collation :declared
      :timezone :utc
      :numeric-precision {:gravity_value :exact-bigint}
      :json-behavior :schema-validated
      :array-behavior :declared
      :enum-behavior :validated
      :vendor-specific-types :manifested
      :status :complete}
     :distributed-workflow-integration-record
     {:workflow-backend-step :query-database
      :connects-to [:replay-policy :idempotency-key-map
                    :retry-timeout-cancellation-compensation-table]
      :side-effects :event-log-guarded
      :status :complete}
     :source-debug-map
     {:source input-id
      :locations [(str source-path ":query")
                  (str source-path ":bindings")
                  (str source-path ":migration")
                  (str source-path ":adapter")]
      :generated-origin-chain [:mir :c11-mir :c12-query-domain-ir
                               :c14-target-lowering :b1-interface
                               :b11-query-relational-backend]
      :query-source-map
      {:select-gravity-value (str source-path ":query:select-gravity-value")}
      :parameter-source-map
      {:gravity-value (str source-path ":query:parameter:1")}
      :adapter-source-map
      {:gravity_value (str source-path ":query:result:gravity_value")}
      :status :preserved}
     :external-database-validation-record
     {:declared-command
      "gravity-query-runner --manifest /tmp/gravity-p07-b11-query/gravity_stage0_query.sql"
      :proof-artifact
      "docs/artifacts/phase-07/reports/p07-d108-b11-query-relational-backend-report.md"
      :status :not-available-in-current-environment}
     :status :complete}))

(defn b11-document-validate!
  [source-path artifact]
  (let [specialized (:specialized-lowering-artifact artifact)
        manifest (:query-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b11-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :gravity/stage0-specialized-lowering-artifact
                 (:kind specialized))
      (b11-document-fail! "B11-MANIFEST" source-path specialized
                          {:missing-fields [:specialized-lowering-artifact]}))
    (when-not (= :complete (get-in specialized
                                   [:capability-based-proof :status]))
      (b11-document-fail! "B11-MANIFEST" source-path specialized
                          {:missing-fields [:specialized-lowering-proof]}))
    (when-not (= :postgresql (get-in manifest [:target :dialect]))
      (b11-document-fail! "B11-DIALECT" source-path manifest
                          {:missing-fields [:target-dialect]}))
    (when-not (= :complete (get-in manifest
                                   [:relational-ir-handoff-record :status]))
      (b11-document-fail! "B11-MANIFEST" source-path manifest
                          {:missing-fields [:relational-ir-handoff-record]}))
    (when-not (= :complete (get-in manifest
                                   [:dialect-schema-mapping :status]))
      (b11-document-fail! "B11-DIALECT" source-path manifest
                          {:missing-fields [:dialect-schema-mapping]}))
    (when-not (= :complete (get-in manifest
                                   [:schema-mapping-record :status]))
      (b11-document-fail! "B11-SCHEMA" source-path manifest
                          {:missing-fields [:schema-mapping-record]}))
    (when-not (= :complete (get-in manifest
                                   [:sql-statement-artifacts 0 :status]))
      (b11-document-fail! "B11-MANIFEST" source-path manifest
                          {:missing-fields [:sql-statement-artifacts]}))
    (when-not (b11-document-sql-structurally-valid?
               b11-document-sql-statement)
      (b11-document-fail! "B11-TAINT" source-path manifest
                          {:missing-fields [:parameterized-sql]}))
    (when-not (= :complete (get-in manifest
                                   [:prepared-binding-manifest :status]))
      (b11-document-fail! "B11-PARAMETER" source-path manifest
                          {:missing-fields [:prepared-binding-manifest]}))
    (when-not (= :rejected (get-in manifest
                                   [:prepared-binding-manifest
                                    :dynamic-string-construction]))
      (b11-document-fail! "B11-TAINT" source-path manifest
                          {:missing-fields [:dynamic-string-rejection]}))
    (when-not (= :complete (get-in manifest
                                   [:query-plan-metadata :status]))
      (b11-document-fail! "B11-PLAN" source-path manifest
                          {:missing-fields [:query-plan-metadata]}))
    (when-not (empty? (get-in manifest
                              [:query-plan-metadata
                               :provider-specific-movement]))
      (b11-document-fail! "B11-PLAN" source-path manifest
                          {:missing-fields [:provider-plan-equivalence]}))
    (when-not (= :complete (get-in manifest
                                   [:typed-result-adapter :status]))
      (b11-document-fail! "B11-RESULT" source-path manifest
                          {:missing-fields [:typed-result-adapter]}))
    (when-not (b11-document-result-adapter-structurally-valid?
               b11-document-result-adapter-fixture)
      (b11-document-fail! "B11-RESULT" source-path manifest
                          {:missing-fields [:result-adapter-validation]}))
    (when-not (= :complete (get-in manifest
                                   [:transaction-isolation-manifest
                                    :status]))
      (b11-document-fail! "B11-TRANSACTION" source-path manifest
                          {:missing-fields [:transaction-isolation-manifest]}))
    (when-not (= :complete (get-in manifest [:migration-artifact :status]))
      (b11-document-fail! "B11-MIGRATION" source-path manifest
                          {:missing-fields [:migration-artifact]}))
    (when-not (= :none (get-in manifest [:migration-artifact :data-loss]))
      (b11-document-fail! "B11-MIGRATION" source-path manifest
                          {:missing-fields [:data-loss-policy]}))
    (when-not (= :complete (get-in manifest
                                   [:schema-diff-compatibility-report
                                    :status]))
      (b11-document-fail! "B11-SCHEMA" source-path manifest
                          {:missing-fields [:schema-diff-compatibility]}))
    (when-not (= :complete (get-in manifest
                                   [:capability-taint-report :status]))
      (b11-document-fail! "B11-CAPABILITY" source-path manifest
                          {:missing-fields [:capability-taint-report]}))
    (when-not (= :rejected (get-in manifest
                                   [:capability-taint-report
                                    :tainted-string-query]))
      (b11-document-fail! "B11-TAINT" source-path manifest
                          {:missing-fields [:tainted-string-query-rejection]}))
    (when-not (= :complete
                 (get-in manifest
                         [:null-collation-timezone-numeric-json-enum-behavior
                          :status]))
      (b11-document-fail! "B11-NULL" source-path manifest
                          {:missing-fields [:null-type-behavior-map]}))
    (when-not (= :complete (get-in manifest
                                   [:distributed-workflow-integration-record
                                    :status]))
      (b11-document-fail! "B11-TRANSACTION" source-path manifest
                          {:missing-fields [:workflow-integration-record]}))
    (when-not (= :preserved (get-in manifest [:source-debug-map :status]))
      (b11-document-fail! "B11-MANIFEST" source-path manifest
                          {:missing-fields [:source-debug-map]}))
    (when-not (every? #(contains? manifest %)
                      [:relational-ir-handoff-record
                       :dialect-schema-mapping
                       :schema-mapping-record
                       :sql-statement-artifacts
                       :prepared-binding-manifest
                       :query-plan-metadata
                       :typed-result-adapter
                       :transaction-isolation-manifest
                       :migration-artifact
                       :schema-diff-compatibility-report
                       :capability-taint-report
                       :null-collation-timezone-numeric-json-enum-behavior
                       :distributed-workflow-integration-record
                       :source-debug-map
                       :external-database-validation-record])
      (b11-document-fail! "B11-MANIFEST" source-path manifest
                          {:missing-fields [:query-artifact-manifest]}))
    (when-not (= (set b11-document-diagnostic-ids) diagnostics)
      (b11-document-fail! "B11-MANIFEST" source-path
                          (:b11-diagnostic-stream artifact)
                          {:missing-fields [:b11-diagnostics]})))
  :complete)

(defn b11-document-capability-proof
  [artifact]
  (let [manifest (:query-backend-manifest artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:b11-diagnostic-stream
                                       :diagnostics])))]
    {:backend-interface-input-verified?
     (= :complete (get-in artifact
                          [:specialized-lowering-artifact
                           :capability-based-proof :status]))
     :relational-ir-handoff-covered?
     (= :complete (get-in manifest
                          [:relational-ir-handoff-record :status]))
     :dialect-and-schema-mapped?
     (and (= :complete (get-in manifest
                               [:dialect-schema-mapping :status]))
          (= :complete (get-in manifest
                               [:schema-mapping-record :status])))
     :sql-statement-emitted?
     (= :complete (get-in manifest [:sql-statement-artifacts 0 :status]))
     :sql-parameterized?
     (b11-document-sql-structurally-valid? b11-document-sql-statement)
     :prepared-bindings-covered?
     (= :complete (get-in manifest [:prepared-binding-manifest :status]))
     :tainted-dynamic-sql-rejected?
     (and (= :rejected (get-in manifest
                               [:prepared-binding-manifest
                                :dynamic-string-construction]))
          (= :rejected (get-in manifest
                               [:capability-taint-report
                                :tainted-string-query])))
     :query-plan-covered?
     (and (= :complete (get-in manifest [:query-plan-metadata :status]))
          (empty? (get-in manifest
                          [:query-plan-metadata
                           :provider-specific-movement])))
     :typed-result-adapter-covered?
     (and (= :complete (get-in manifest [:typed-result-adapter :status]))
          (b11-document-result-adapter-structurally-valid?
           b11-document-result-adapter-fixture))
     :transaction-and-isolation-covered?
     (= :complete (get-in manifest
                          [:transaction-isolation-manifest :status]))
     :migration-and-compatibility-covered?
     (and (= :complete (get-in manifest [:migration-artifact :status]))
          (= :none (get-in manifest [:migration-artifact :data-loss]))
          (= :complete (get-in manifest
                               [:schema-diff-compatibility-report
                                :status])))
     :capability-and-taint-covered?
     (= :complete (get-in manifest [:capability-taint-report :status]))
     :null-and-type-behavior-covered?
     (= :complete
        (get-in manifest
                [:null-collation-timezone-numeric-json-enum-behavior
                 :status]))
     :workflow-integration-covered?
     (= :complete (get-in manifest
                          [:distributed-workflow-integration-record
                           :status]))
     :source-debug-map-preserved?
     (= :preserved (get-in manifest [:source-debug-map :status]))
     :manifest-complete?
     (every? #(contains? manifest %)
             [:relational-ir-handoff-record
              :dialect-schema-mapping
              :schema-mapping-record
              :sql-statement-artifacts
              :prepared-binding-manifest
              :query-plan-metadata
              :typed-result-adapter
              :transaction-isolation-manifest
              :migration-artifact
              :schema-diff-compatibility-report
              :capability-taint-report
              :null-collation-timezone-numeric-json-enum-behavior
              :distributed-workflow-integration-record
              :source-debug-map
              :external-database-validation-record])
     :diagnostics-covered?
     (= (set b11-document-diagnostic-ids) diagnostics)
     :external-database-validation?
     (get-in manifest [:external-database-validation-record :status])
     :status :complete}))

(defn b11-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (b11-document-source-overrides module)
        _ (b11-document-validate-source-overrides! source-path
                                                   source-overrides)
        specialized-artifact (specialized-lowering-source-artifact source-path
                                                                   source-text)
        input-id (:artifact-id specialized-artifact)
        manifest (b11-document-query-manifest source-path input-id)
        diagnostic-stream (b11-document-diagnostic-stream source-path
                                                          input-id)
        artifact-base
        {:kind :gravity/stage0-b11-query-relational-backend-document-artifact
         :task "P07-D108"
         :document-set ["B11"]
         :governing-document b11-document-governing-document
         :pass {:name :b11-query-relational-backend-document-coverage
                :input :specialized-lowering-artifact
                :output :b11-query-relational-backend-document-artifact
                :requires [:verified-relational-ir-or-schema-domain-ir
                           :b1-backend-interface :c11-mir
                           :c12-domain-ir :c14-target-lowering
                           :schema-version :transaction-policy
                           :capability-manifest :taint-proof
                           :dialect-map :migration-policy
                           :typed-result-adapter]
                :preserves [:source-spans :generated-origins :schemas
                            :effects :capabilities :taint-facts
                            :transactions :migrations :query-plans
                            :safety :proofs :profile :target
                            :artifact-provenance]
                :emits [:query-backend-manifest
                        :relational-ir-handoff-record
                        :dialect-schema-mapping
                        :schema-mapping-record
                        :sql-statement-artifacts
                        :prepared-binding-manifest
                        :query-plan-metadata
                        :typed-result-adapter
                        :transaction-isolation-manifest
                        :migration-artifact
                        :schema-diff-compatibility-report
                        :capability-taint-report
                        :null-type-behavior-record
                        :source-debug-map
                        :b11-diagnostic-stream
                        :conformance-criteria-record]
                :rejects b11-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :specialized-lowering-artifact
         (select-keys specialized-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :query-backend :specialized-lowering-results])
         :specialized-lowering-artifact-kind (:kind specialized-artifact)
         :specialized-lowering-artifact-hash input-id
         :query-backend-manifest manifest
         :relational-ir-handoff-record
         (:relational-ir-handoff-record manifest)
         :dialect-schema-mapping (:dialect-schema-mapping manifest)
         :schema-mapping-record (:schema-mapping-record manifest)
         :sql-statement-artifacts (:sql-statement-artifacts manifest)
         :prepared-binding-manifest (:prepared-binding-manifest manifest)
         :query-plan-metadata (:query-plan-metadata manifest)
         :typed-result-adapter (:typed-result-adapter manifest)
         :transaction-isolation-manifest
         (:transaction-isolation-manifest manifest)
         :migration-artifact (:migration-artifact manifest)
         :schema-diff-compatibility-report
         (:schema-diff-compatibility-report manifest)
         :capability-taint-report (:capability-taint-report manifest)
         :null-collation-timezone-numeric-json-enum-behavior
         (:null-collation-timezone-numeric-json-enum-behavior manifest)
         :distributed-workflow-integration-record
         (:distributed-workflow-integration-record manifest)
         :source-debug-map (:source-debug-map manifest)
         :rejected-design-coverage
         [{:design :string-built-sql-with-tainted-input
           :diagnostic "B11-TAINT" :status :rejected}
          {:design :database-write-or-migration-without-capability
           :diagnostic "B11-CAPABILITY" :status :rejected}
          {:design :schema-drift-without-migration-records
           :diagnostic "B11-MIGRATION" :status :rejected}
          {:design :unchecked-result-adapter-trusting-rows
           :diagnostic "B11-RESULT" :status :rejected}
          {:design :provider-specific-sql-as-portable-semantics
           :diagnostic "B11-PLAN" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/b11-query-relational-backend-conformance-criteria-record
          :dialect-and-schema-mapping-artifacts :complete
          :prepared-statement-and-parameter-binding-fixtures :complete
          :tainted-dynamic-query-rejection :covered
          :read-write-transaction-migration-capability-checks :complete
          :null-collation-timezone-numeric-json-enum-fixtures :complete
          :result-adapter-validation :complete
          :migration-compatibility-and-data-loss-rejection :covered
          :distributed-workflow-integration-for-database-steps :complete
          :source-provenance-effect-capability-metadata-preservation :complete
          :database-execution-or-plan-simulation-reference-fixture :simulated
          :status :passed}
         :b11-diagnostic-stream diagnostic-stream
         :b11-document-results
         {:documents ["B11"]
          :task "P07-D108"
          :required-diagnostic-ids b11-document-diagnostic-ids
          :specialized-lowering-input-status :complete
          :relational-ir-status :complete
          :dialect-status :complete
          :schema-status :complete
          :sql-status :complete
          :parameter-status :complete
          :taint-status :complete
          :plan-status :complete
          :result-adapter-status :complete
          :transaction-status :complete
          :migration-status :complete
          :null-type-status :complete
          :capability-status :complete
          :workflow-integration-status :complete
          :manifest-status :complete
          :conformance-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (b11-document-validate! source-path artifact-base)
        capability-proof (b11-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn b11-document-file-artifact
  [path]
  (b11-document-source-artifact path (slurp path)))

(def b12-document-governing-document
  "docs/phase-07-backend-architecture/109-b12-mobile-backend-design.md")

(def b12-document-diagnostic-ids
  ["B12-TARGET"
   "B12-PERMISSION"
   "B12-LIFECYCLE"
   "B12-THREAD"
   "B12-NULL"
   "B12-ERROR"
   "B12-BACKGROUND"
   "B12-STORAGE"
   "B12-RESOURCE"
   "B12-MANIFEST"])

(def b12-document-override-diagnostics
  {:b12-target "B12-TARGET"
   :b12-permission "B12-PERMISSION"
   :b12-lifecycle "B12-LIFECYCLE"
   :b12-thread "B12-THREAD"
   :b12-null "B12-NULL"
   :b12-error "B12-ERROR"
   :b12-background "B12-BACKGROUND"
   :b12-storage "B12-STORAGE"
   :b12-resource "B12-RESOURCE"
   :b12-manifest "B12-MANIFEST"})

(defn b12-document-source-overrides
  [module]
  (get-in module [:metadata :backend :specialized-lowering] {}))

(defn b12-document-missing-policy
  [id]
  (case id
    "B12-TARGET" :platform-os-architecture-bundle-ui-target
    "B12-PERMISSION" :permission-capability-runtime-denial-policy
    "B12-LIFECYCLE" :lifecycle-state-model
    "B12-THREAD" :main-thread-actor-callback-affinity
    "B12-NULL" :platform-nullability-adapter
    "B12-ERROR" :platform-exception-callback-error-map
    "B12-BACKGROUND" :background-execution-deployment-policy
    "B12-STORAGE" :local-storage-sync-schema-migration
    "B12-RESOURCE" :asset-resource-bundle-metadata
    :mobile-artifact-manifest))

(defn b12-document-domain-anchor
  [id]
  (case id
    "B12-TARGET" :mobile-platform-target
    "B12-PERMISSION" :platform-api-binding
    "B12-LIFECYCLE" :app-lifecycle
    "B12-THREAD" :ui-thread-update
    "B12-NULL" :platform-null-adapter
    "B12-ERROR" :platform-error-adapter
    "B12-BACKGROUND" :background-task
    "B12-STORAGE" :local-sync-store
    "B12-RESOURCE" :resource-bundle
    :mobile-manifest))

(defn b12-document-fail!
  [id source-path subject extra]
  (fail! id
         "B12 mobile backend design document coverage validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :b12-mobile-backend-document
                 :stage :b12-mobile-backend-document-coverage
                 :backend :gravity.backend/mobile
                 :profile :hosted
                 :target :ios
                 :domain-anchor (or (:domain-anchor subject)
                                    (b12-document-domain-anchor id))
                 :platform (or (:platform subject) :ios)
                 :api-symbol (or (:api-symbol subject)
                                 'Foundation/URLSession.data)
                 :lifecycle-state (or (:lifecycle-state subject)
                                      :foreground)
                 :thread-actor (or (:thread-actor subject) :main)
                 :permission (or (:permission subject) :network)
                 :capability (or (:capability subject) :network/request)
                 :missing-policy (b12-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "B12 requires verified mobile/platform IR, explicit platform target and bundle metadata, permission and capability manifests, lifecycle and threading maps, null/error adapters, storage/sync schemas, resource manifests, store-audit metadata, source maps, and simulator/device conformance records."}
                extra)))

(defn b12-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get b12-document-override-diagnostics fail-kind)]
      (b12-document-fail!
       id source-path
       {:artifact-id (str "b12-document-" (name fail-kind))
        :domain-anchor (keyword (str "b12-document-" (name fail-kind)))}
       {:missing-fields [fail-kind]}))))

