          :generated #{:ffi-marshalling}
          :delegated #{:host-ffi-adapter}
          :external #{}
          :forbidden #{:firmware-safe-default}}
    :model {:linked #{}
            :generated #{}
            :delegated #{:model-provider-adapter}
            :external #{:ai/model-provider}
