(def concurrency-distributed-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             concurrency-distributed-diagnostic-ids)))

(defn concurrency-distributed-source-overrides
  [module]
  (get-in module [:metadata :runtime :concurrency] {}))

(defn concurrency-distributed-missing-policy
  [id]
  (case id
    "R6-SCHEDULER" :declared-scheduler-thread-provider
    "R6-RACE" :synchronization-or-ownership-transfer-evidence
    "R6-ATOMIC" :supported-atomic-order-scope-alignment
    "R6-TASK" :structured-task-parent-or-lifecycle-owner
    "R6-CANCEL" :cancellation-cleanup-failure-policy
    "R6-ACTOR" :actor-channel-schema-and-transfer-rules
    "R6-BLOCKING" :blocking-effect-runtime-support
    "R6-CAPABILITY" :concurrent-effect-authority
    "R6-REPLAY" :replay-safe-concurrent-side-effect-record
    "R6-MANIFEST" :complete-concurrency-runtime-artifact
    "R7-TOPOLOGY" :service-topology-record
    "R7-SCHEMA" :message-state-actor-service-schema
    "R7-REPLAY" :event-log-and-replay-log-record
    "R7-IDEMPOTENCY" :idempotency-record-for-side-effecting-step
    "R7-RETRY" :retry-timeout-cancellation-failure-policy
    "R7-COMPENSATION" :compensation-record
    "R7-CAPABILITY" :distributed-effect-authority
    "R7-MIGRATION" :schema-event-log-migration-policy
    "R7-ACTOR" :actor-state-mailbox-snapshot-delivery-policy
    :complete-distributed-runtime-artifact))

(defn concurrency-distributed-fail!
  [id source-path subject extra]
  (fail! id
         "P08 concurrency, distributed, and replay runtime validation failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :concurrency-distributed-runtime
                 :stage :concurrency-distributed-runtime
                 :profile (or (:profile subject) :distributed)
                 :target (or (:target subject) :jvm)
                 :runtime-family (if (str/starts-with? id "R7")
                                   :distributed
                                   :concurrency)
                 :scheduler (:scheduler subject)
                 :task-id (:task-id subject)
                 :actor-id (:actor-id subject)
                 :channel-id (:channel-id subject)
                 :workflow-id (:workflow-id subject)
                 :service-id (:service-id subject)
                 :schema-id (:schema-id subject)
                 :event-id (:event-id subject)
                 :provider (:provider subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :synchronization-object (:synchronization-object subject)
                 :missing-proof (:missing-proof subject)
                 :missing-schema (:missing-schema subject)
                 :replay-policy (:replay-policy subject)
                 :missing-policy (concurrency-distributed-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-T04 requires explicit scheduler, task, atomic, synchronization, actor/channel, cancellation, distributed topology, schema, event-log, replay, idempotency, retry, compensation, capability, migration, observability, and audit records."}
                extra)))

(defn concurrency-distributed-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get concurrency-distributed-override-diagnostics fail-kind)]
      (concurrency-distributed-fail!
       id source-path
       {:scheduler fail-kind
        :task-id (str "task-" (name fail-kind))
        :actor-id (str "actor-" (name fail-kind))
        :channel-id (str "channel-" (name fail-kind))
        :workflow-id (str "workflow-" (name fail-kind))
        :service-id fail-kind
        :schema-id (str "schema-" (name fail-kind))
        :event-id (str "event-" (name fail-kind))
        :provider fail-kind
        :effect fail-kind
        :capability fail-kind
        :synchronization-object fail-kind
        :missing-proof fail-kind
        :missing-schema fail-kind
        :replay-policy fail-kind}
       {:missing-fields [fail-kind]}))))

(defn concurrency-distributed-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/concurrency-distributed-diagnostic-stream
   :stage :concurrency-distributed-runtime
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :concurrency-distributed-runtime
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-concurrency-distributed-syntax-"
                                      index)
                      :artifact input-id}
            :profile (if (str/starts-with? id "R7")
                       :distributed
                       :hosted)
            :target :jvm
            :runtime-family (if (str/starts-with? id "R7")
                              :distributed
                              :concurrency)
            :scheduler (case id
                         "R6-SCHEDULER" :missing-scheduler
                         "R6-TASK" :structured-task-scheduler
                         "R7-RETRY" :durable-workflow-scheduler
                         :stage0-scheduler)
            :task-id (case id
                       "R6-TASK" "task/orphan"
                       "R6-CANCEL" "task/cancel-missing-cleanup"
                       "R6-REPLAY" "task/replay-side-effect"
                       nil)
            :actor-id (case id
                        "R6-ACTOR" "actor/schema-missing"
                        "R7-ACTOR" "actor/snapshot-missing"
                        nil)
            :channel-id (when (= "R6-ACTOR" id) "channel/commands")
            :workflow-id (when (str/starts-with? id "R7") "workflow/order")
            :service-id (case id
                          "R7-TOPOLOGY" :order-service
                          "R7-CAPABILITY" :payment-service
                          nil)
            :schema-id (case id
                         "R7-SCHEMA" "schema/missing"
                         "R7-MIGRATION" "schema/v1-to-v2"
                         nil)
            :event-id (case id
                        "R7-REPLAY" "event/random"
                        "R12-REPLAY" "event/replay"
                        nil)
            :provider (case id
                        "R6-SCHEDULER" :host-thread-pool
                        "R7-TOPOLOGY" :durable-provider
                        "R7-CAPABILITY" :network-provider
                        nil)
            :effect (case id
                      "R6-BLOCKING" :filesystem/read
                      "R6-CAPABILITY" :network/http
                      "R7-CAPABILITY" :database/write
                      "R7-IDEMPOTENCY" :network/http
                      "R7-REPLAY" :time/now
                      nil)
            :capability (case id
                          "R6-CAPABILITY" :http/client
                          "R7-CAPABILITY" :db/write
                          "R7-IDEMPOTENCY" :http/client
                          nil)
            :synchronization-object (case id
                                      "R6-RACE" :unprotected-cell
                                      "R6-ATOMIC" :atomic-counter
                                      nil)
            :missing-proof (case id
                             "R6-RACE" :safe8-race-proof
                             "R6-ATOMIC" :target-memory-order-proof
                             "R6-REPLAY" :replay-safe-side-effect-proof
                             nil)
            :missing-schema (case id
                              "R6-ACTOR" :message-schema
                              "R7-SCHEMA" :state-schema
                              "R7-ACTOR" :actor-snapshot-schema
                              nil)
            :replay-policy (case id
                             "R6-REPLAY" :missing
                             "R7-REPLAY" :unrecorded-nondeterminism
                             "R7-MIGRATION" :incompatible-upgrade
                             :recorded)
            :missing-policy (concurrency-distributed-missing-policy id)
            :source-generated-origin-chain
            [:runtime-selection :managed-runtime
             :concurrency-distributed-runtime]
            :facts {:structured-concurrency-required true
                    :nondeterminism-recorded-for-replay true
                    :external-effects-capability-checked true
                    :observability-events-redacted true}
            :remediation [{:kind :declare-runtime-manifest}
                          {:kind :attach-schema-or-proof}
                          {:kind :record-event-log-and-replay-policy}
                          {:kind :reject-unsafe-concurrency-or-replay}]
            :redactions []
            :ordering-key [id :concurrency-distributed-runtime]})
         concurrency-distributed-diagnostic-ids
         (range))
   :status :complete})

