                        :retry-timeout-cancellation-compensation-records
                        :idempotency-record
                        :distributed-capability-enforcement-table
                        :schema-event-log-migration-policy
                        :runtime-trace-audit-records
                        :concurrency-distributed-diagnostic-stream
                        :conformance-criteria-record]
                :rejects concurrency-distributed-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :managed-runtime-artifact
         (select-keys upstream-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :managed-runtime-results])
         :managed-runtime-artifact-kind (:kind upstream-artifact)
         :managed-runtime-artifact-hash input-id
         :upstream-artifact-source
         concurrency-distributed-upstream-artifact-path
         :concurrency-runtime-manifest concurrency
         :scheduler-delegation-record scheduler
         :task-tree-record task-tree
         :cancellation-and-failure-policy cancellation
         :atomic-support-table atomics
         :synchronization-graph sync-graph
         :actor-channel-schema-bundle actor-channel
         :ownership-transfer-report ownership
         :durable-concurrency-replay-record durable-replay
         :distributed-runtime-manifest distributed
         :service-topology-manifest topology
         :message-state-schema-bundle schemas
         :event-log-schema event-log
         :replay-log-schema replay-log
         :actor-snapshot-schema actor-snapshot
         :retry-timeout-cancellation-compensation-records retry-compensation
         :idempotency-record idempotency
         :distributed-capability-enforcement-table capability
         :schema-event-log-migration-policy migration
         :runtime-trace-audit-records trace
         :rejected-design-coverage
         [{:design :missing-scheduler-provider
           :diagnostic "R6-SCHEDULER" :status :rejected}
          {:design :unsynchronized-shared-mutable-state
           :diagnostic "R6-RACE" :status :rejected}
          {:design :unsupported-atomic-order
           :diagnostic "R6-ATOMIC" :status :rejected}
          {:design :orphan-detached-task
           :diagnostic "R6-TASK" :status :rejected}
          {:design :missing-cancellation-cleanup
           :diagnostic "R6-CANCEL" :status :rejected}
          {:design :actor-channel-without-schema
           :diagnostic "R6-ACTOR" :status :rejected}
          {:design :blocking-effect-without-runtime-support
           :diagnostic "R6-BLOCKING" :status :rejected}
          {:design :concurrent-effect-without-authority
           :diagnostic "R6-CAPABILITY" :status :rejected}
          {:design :replay-sensitive-concurrency-repeats-effect
           :diagnostic "R6-REPLAY" :status :rejected}
          {:design :incomplete-concurrency-runtime-artifact
           :diagnostic "R6-MANIFEST" :status :rejected}
          {:design :missing-service-topology
           :diagnostic "R7-TOPOLOGY" :status :rejected}
          {:design :schema-less-message-or-state
           :diagnostic "R7-SCHEMA" :status :rejected}
          {:design :unrecorded-distributed-nondeterminism
           :diagnostic "R7-REPLAY" :status :rejected}
          {:design :side-effect-without-idempotency
           :diagnostic "R7-IDEMPOTENCY" :status :rejected}
          {:design :unbounded-retry-or-missing-timeout
           :diagnostic "R7-RETRY" :status :rejected}
          {:design :missing-compensation-for-side-effect
           :diagnostic "R7-COMPENSATION" :status :rejected}
          {:design :ambient-distributed-service-access
           :diagnostic "R7-CAPABILITY" :status :rejected}
          {:design :unsafe-schema-or-event-log-upgrade
           :diagnostic "R7-MIGRATION" :status :rejected}
          {:design :invalid-actor-state-mailbox-snapshot
           :diagnostic "R7-ACTOR" :status :rejected}
          {:design :incomplete-distributed-runtime-artifact
           :diagnostic "R7-MANIFEST" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/concurrency-distributed-conformance-record
          :scheduler-and-execution-model-manifests :complete
          :structured-task-and-cancellation-fixtures :complete
          :atomics-locks-channels-actor-schemas :complete
          :race-orphan-unsupported-atomic-rejection :complete
          :capability-checks-for-concurrent-effects :complete
          :service-topology-and-provider-manifests :complete
          :message-state-actor-service-schemas :complete
          :event-log-and-replay-fixtures :complete
          :idempotency-retry-timeout-compensation :complete
          :schema-event-log-migration-checks :complete
          :observability-audit-links :complete
          :status :passed}
         :concurrency-distributed-diagnostic-stream diagnostic-stream
         :concurrency-distributed-results
         {:documents ["R6" "R7"]
          :task "P08-T04"
          :required-diagnostic-ids concurrency-distributed-diagnostic-ids
          :managed-runtime-input-status :complete
          :scheduler-status :complete
          :task-tree-status :complete
          :cancellation-status :complete
          :atomic-status :complete
          :synchronization-status :complete
          :actor-channel-status :complete
          :ownership-transfer-status :complete
          :concurrency-replay-status :complete
          :distributed-manifest-status :complete
          :topology-status :complete
          :schema-status :complete
          :event-log-status :complete
          :replay-log-status :complete
          :idempotency-status :complete
          :retry-compensation-status :complete
          :capability-status :complete
          :migration-status :complete
          :audit-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (concurrency-distributed-validate! source-path artifact-base)
        capability-proof
        (concurrency-distributed-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn concurrency-distributed-file-artifact
  [path]
  (concurrency-distributed-source-artifact path (slurp path)))

(def r6-document-governing-document
  "docs/phase-08-runtime-architecture/117-r6-concurrency-runtime-design.md")

(def r6-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-concurrency-distributed.gravity")

(def r6-document-diagnostic-ids
  ["R6-SCHEDULER"
   "R6-RACE"
   "R6-ATOMIC"
   "R6-TASK"
   "R6-CANCEL"
   "R6-ACTOR"
   "R6-BLOCKING"
   "R6-CAPABILITY"
   "R6-REPLAY"
   "R6-MANIFEST"])

(def r6-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r6-document-diagnostic-ids)))

(defn r6-document-source-overrides
  [module]
  (or (get-in module [:metadata :runtime :r6-document])
      (get-in module [:metadata :runtime :concurrency])
      {}))

(defn r6-document-missing-policy
  [id]
  (case id
    "R6-SCHEDULER" :declared-scheduler-thread-provider
    "R6-RACE" :synchronization-or-ownership-transfer-evidence
    "R6-ATOMIC" :supported-atomic-order-scope-alignment
    "R6-TASK" :structured-task-parent-or-lifecycle-owner
    "R6-CANCEL" :cancellation-cleanup-failure-policy
    "R6-ACTOR" :actor-channel-schema-and-transfer-rules
    "R6-BLOCKING" :blocking-effect-runtime-support
    "R6-CAPABILITY" :concurrent-effect-authority
    "R6-REPLAY" :replay-safe-concurrent-side-effect-record
    :complete-concurrency-runtime-artifact))

(defn r6-document-fail!
  [id source-path subject extra]
  (fail! id
         "R6 concurrency runtime document coverage failed"
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :r6-concurrency-runtime-document
                 :stage :r6-document-coverage
                 :document-id "R6"
                 :profile (or (:profile subject) :hosted)
                 :target (or (:target subject) :jvm)
                 :runtime-family :concurrency
                 :scheduler (:scheduler subject)
                 :task-id (:task-id subject)
                 :actor-id (:actor-id subject)
                 :channel-id (:channel-id subject)
                 :effect (:effect subject)
                 :capability (:capability subject)
                 :synchronization-object (:synchronization-object subject)
                 :missing-proof (:missing-proof subject)
                 :missing-schema (:missing-schema subject)
                 :replay-policy (:replay-policy subject)
                 :artifact-id (:artifact-id subject)
                 :missing-policy (r6-document-missing-policy id)
                 :fallback-status :rejected
                 :remediation "P08-D117 requires scheduler/thread manifests, structured tasks, cancellation cleanup, atomics, synchronization and ownership-transfer evidence, actor/channel schemas, effect/capability checks, replay-safe concurrency records, and R6 conformance evidence."}
                extra)))

(defn r6-document-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get r6-document-override-diagnostics fail-kind)]
      (r6-document-fail!
       id source-path
       {:scheduler fail-kind
        :task-id (str "task-" (name fail-kind))
        :actor-id (str "actor-" (name fail-kind))
        :channel-id (str "channel-" (name fail-kind))
        :effect fail-kind
        :capability fail-kind
        :synchronization-object fail-kind
        :missing-proof fail-kind
        :missing-schema fail-kind
        :replay-policy fail-kind
        :artifact-id (str "r6-document-" (name fail-kind))}
       {:missing-fields [fail-kind]}))))

(defn r6-document-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/r6-concurrency-runtime-diagnostic-stream
   :stage :r6-document-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
            :diagnostic id
            :rule id
            :severity :error
            :stage :r6-document-coverage
            :document-id "R6"
            :message-key (keyword "runtime" (str/lower-case id))
            :primary {:span (source-span source-path index)
                      :syntax-id (str "p08-r6-document-syntax-" index)
                      :artifact input-id}
            :profile :hosted
            :target :jvm
            :runtime-family :concurrency
            :scheduler (case id
                         "R6-SCHEDULER" :missing-scheduler
                         "R6-TASK" :structured-task-scheduler
                         :stage0-scheduler)
            :task-id (case id
                       "R6-TASK" "task/orphan"
                       "R6-CANCEL" "task/cancel-missing-cleanup"
                       "R6-REPLAY" "task/replay-side-effect"
                       nil)
            :actor-id (when (= "R6-ACTOR" id) "actor/schema-missing")
            :channel-id (when (= "R6-ACTOR" id) "channel/commands")
            :effect (case id
                      "R6-BLOCKING" :filesystem/read
                      "R6-CAPABILITY" :network/http
                      nil)
            :capability (when (= "R6-CAPABILITY" id) :http/client)
            :synchronization-object (case id
                                      "R6-RACE" :unprotected-cell
                                      "R6-ATOMIC" :atomic-counter
                                      nil)
            :missing-proof (case id
                             "R6-RACE" :safe8-race-proof
                             "R6-ATOMIC" :target-memory-order-proof
                             "R6-REPLAY" :replay-safe-side-effect-proof
                             nil)
            :missing-schema (when (= "R6-ACTOR" id) :message-schema)
            :replay-policy (if (= "R6-REPLAY" id) :missing :recorded)
            :missing-policy (r6-document-missing-policy id)
            :source-generated-origin-chain
            [:managed-runtime :concurrency-distributed-runtime
             :r6-document-coverage]
            :facts {:structured-concurrency-required true
                    :shared-mutation-requires-sync-or-transfer true
                    :blocking-effects-require-capabilities true
                    :replay-sensitive-concurrency-recorded true}
            :remediation [{:kind :declare-scheduler-provider}
                          {:kind :attach-task-lifecycle}
                          {:kind :attach-sync-or-transfer-proof}
                          {:kind :record-replay-safe-concurrency}]
            :redactions []
            :ordering-key [id :r6-document-coverage]})
         r6-document-diagnostic-ids
         (range))
   :status :complete})

(defn r6-document-requirements-coverage
  [concurrency-artifact]
  (let [concurrency (:concurrency-runtime-manifest concurrency-artifact)
        scheduler (:scheduler-delegation-record concurrency-artifact)
        task-tree (:task-tree-record concurrency-artifact)
        cancellation (:cancellation-and-failure-policy concurrency-artifact)
        atomics (:atomic-support-table concurrency-artifact)
        sync-graph (:synchronization-graph concurrency-artifact)
        actor-channel (:actor-channel-schema-bundle concurrency-artifact)
        ownership (:ownership-transfer-report concurrency-artifact)
        durable-replay (:durable-concurrency-replay-record concurrency-artifact)
        capability (:distributed-capability-enforcement-table
                    concurrency-artifact)]
    {:artifact :gravity/r6-concurrency-runtime-requirements-coverage
     :concurrency-runtime-input (:artifact-id concurrency-artifact)
     :manifest-status (:status concurrency)
     :family (:family concurrency)
     :models (:models concurrency)
     :scheduler-status (:status scheduler)
     :scheduler (:scheduler scheduler)
     :thread-provider (:thread-provider scheduler)
     :blocking-policy (:blocking-policy scheduler)
     :task-tree-status (:status task-tree)
     :task-count (count (:tasks task-tree))
     :orphan-tasks (:orphan-tasks task-tree)
     :leaked-tasks (:leaked-tasks task-tree)
     :cancellation-status (:status cancellation)
     :cleanup-handlers (:cleanup-handlers cancellation)
     :atomic-status (:status atomics)
     :unsupported-atomics (:unsupported atomics)
     :synchronization-status (:status sync-graph)
     :unprotected-shared-mutable-state
     (:unprotected-shared-mutable-state sync-graph)
     :actor-channel-status (:status actor-channel)
     :missing-schemas (:missing-schemas actor-channel)
     :ownership-transfer-status (:status ownership)
     :borrow-escapes (:borrow-escapes ownership)
     :concurrency-replay-status (:status durable-replay)
     :unrecorded-nondeterminism (:unrecorded-nondeterminism durable-replay)
     :capability-status (:status capability)
     :deny-by-default? (:deny-by-default? capability)
     :status :complete}))

(defn r6-document-validate!
  [source-path artifact]
  (let [concurrency-artifact (:concurrency-distributed-artifact artifact)
        coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r6-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= :complete (get-in concurrency-artifact
                                   [:capability-based-proof :status]))
      (r6-document-fail! "R6-MANIFEST" source-path concurrency-artifact
                         {:missing-fields [:concurrency-proof]}))
    (when-not (and (= :complete (:manifest-status coverage))
                   (= :concurrency (:family coverage)))
      (r6-document-fail! "R6-MANIFEST" source-path coverage
                         {:missing-fields [:concurrency-manifest]}))
    (when-not (= :complete (:scheduler-status coverage))
      (r6-document-fail! "R6-SCHEDULER" source-path coverage
                         {:missing-fields [:scheduler]}))
    (when (seq (:unprotected-shared-mutable-state coverage))
      (r6-document-fail! "R6-RACE" source-path coverage
                         {:missing-fields [:sync-evidence]}))
    (when (seq (:unsupported-atomics coverage))
      (r6-document-fail! "R6-ATOMIC" source-path coverage
                         {:missing-fields [:atomic-support]}))
    (when (or (seq (:orphan-tasks coverage))
              (seq (:leaked-tasks coverage)))
      (r6-document-fail! "R6-TASK" source-path coverage
                         {:missing-fields [:task-lifecycle]}))
    (when-not (= :complete (:cancellation-status coverage))
      (r6-document-fail! "R6-CANCEL" source-path coverage
                         {:missing-fields [:cancellation]}))
    (when (seq (:missing-schemas coverage))
      (r6-document-fail! "R6-ACTOR" source-path coverage
                         {:missing-fields [:actor-channel-schema]}))
    (when-not (= :requires-effect-and-capability
                 (:blocking-policy coverage))
      (r6-document-fail! "R6-BLOCKING" source-path coverage
                         {:missing-fields [:blocking-policy]}))
    (when-not (true? (:deny-by-default? coverage))
      (r6-document-fail! "R6-CAPABILITY" source-path coverage
                         {:missing-fields [:deny-by-default]}))
    (when (seq (:unrecorded-nondeterminism coverage))
      (r6-document-fail! "R6-REPLAY" source-path coverage
                         {:missing-fields [:replay-record]}))
    (when-not (= (set r6-document-diagnostic-ids) diagnostics)
      (r6-document-fail! "R6-MANIFEST" source-path
                         (:r6-diagnostic-stream artifact)
                         {:missing-fields [:r6-diagnostics]})))
  :complete)

(defn r6-document-capability-proof
  [artifact]
  (let [coverage (:requirements-coverage artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:r6-diagnostic-stream
                                       :diagnostics])))]
    {:concurrency-runtime-input-verified?
     (= :complete (get-in artifact
                          [:concurrency-distributed-artifact
                           :capability-based-proof :status]))
     :scheduler-and-execution-models-declared?
     (and (= :complete (:scheduler-status coverage))
          (contains? (:models coverage) :structured-tasks)
          (contains? (:models coverage) :atomics)
          (contains? (:models coverage) :channels)
          (contains? (:models coverage) :actors))
     :structured-tasks-owned-and-joined?
     (and (= :complete (:task-tree-status coverage))
          (pos? (:task-count coverage))
          (empty? (:orphan-tasks coverage))
          (empty? (:leaked-tasks coverage)))
     :cancellation-cleanup-covered?
     (and (= :complete (:cancellation-status coverage))
          (boolean (seq (:cleanup-handlers coverage))))
     :atomics-target-supported?
     (and (= :complete (:atomic-status coverage))
          (empty? (:unsupported-atomics coverage)))
     :shared-state-synchronized-or-transferred?
     (and (= :complete (:synchronization-status coverage))
          (= :complete (:ownership-transfer-status coverage))
          (empty? (:unprotected-shared-mutable-state coverage))
          (empty? (:borrow-escapes coverage)))
     :actor-channel-schemas-complete?
     (and (= :complete (:actor-channel-status coverage))
          (empty? (:missing-schemas coverage)))
     :blocking-and-concurrent-effects-authorized?
     (and (= :requires-effect-and-capability (:blocking-policy coverage))
          (true? (:deny-by-default? coverage)))
     :replay-sensitive-concurrency-safe?
     (and (= :complete (:concurrency-replay-status coverage))
          (empty? (:unrecorded-nondeterminism coverage)))
     :diagnostics-covered?
     (= (set r6-document-diagnostic-ids) diagnostics)
     :status :complete}))

(defn r6-document-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (r6-document-source-overrides module)
        _ (r6-document-validate-source-overrides! source-path
                                                  source-overrides)
        concurrency-artifact
        (concurrency-distributed-file-artifact
         r6-document-upstream-artifact-path)
        input-id (:artifact-id concurrency-artifact)
        diagnostic-stream (r6-document-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-r6-concurrency-runtime-document-artifact
         :task "P08-D117"
         :document-set ["R6"]
         :governing-document r6-document-governing-document
         :pass {:name :r6-concurrency-runtime-document-coverage
                :input :concurrency-distributed-runtime-artifact
                :output :r6-document-coverage-artifact
                :requires [:concurrency-runtime-manifest
                           :scheduler-delegation-record
                           :task-tree-record
                           :cancellation-and-failure-policy
                           :atomic-support-table
                           :synchronization-graph
                           :actor-channel-schema-bundle
                           :ownership-transfer-report
                           :durable-concurrency-replay-record]
                :preserves [:source-spans :ownership-transfers :cleanup
                            :effects :capabilities :replay-records
                            :runtime-diagnostics]
                :emits [:requirements-coverage
                        :rejected-design-coverage
                        :conformance-criteria-record
                        :r6-diagnostic-stream]
                :rejects r6-document-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :concurrency-distributed-artifact
         (select-keys concurrency-artifact
                      [:kind :task :artifact-id :capability-based-proof
                       :concurrency-distributed-results])
         :concurrency-distributed-artifact-kind (:kind concurrency-artifact)
         :concurrency-distributed-artifact-hash input-id
         :upstream-artifact-source r6-document-upstream-artifact-path
         :requirements-coverage
         (r6-document-requirements-coverage concurrency-artifact)
         :rejected-design-coverage
         [{:design :unstructured-concurrency-default
           :diagnostic "R6-TASK" :status :rejected}
          {:design :shared_mutable_state_without_sync_or_transfer
           :diagnostic "R6-RACE" :status :rejected}
          {:design :detached_task_without_lifecycle_owner
           :diagnostic "R6-TASK" :status :rejected}
          {:design :unsupported_atomic_memory_order
           :diagnostic "R6-ATOMIC" :status :rejected}
          {:design :replay_sensitive_concurrency_repeats_side_effect
           :diagnostic "R6-REPLAY" :status :rejected}]
         :conformance-criteria-record
         {:artifact :gravity/r6-concurrency-runtime-conformance-record
          :scheduler_and_execution_model_manifests :complete
          :structured_task_and_cancellation_fixtures :complete
          :atomics_locks_channels_actor_schema_fixtures :complete
          :race_orphan_unsupported_atomic_missing_schema_rejection :complete
          :capability_checks_for_concurrent_effects :complete
          :replay_safe_workflow_concurrency_fixtures :complete
          :source_ownership_cleanup_metadata_preserved :complete
          :status :passed}
         :r6-diagnostic-stream diagnostic-stream
         :r6-document-results
         {:documents ["R6"]
          :task "P08-D117"
          :required-diagnostic-ids r6-document-diagnostic-ids
          :concurrency-runtime-input-status :complete
          :manifest-status :complete
          :scheduler-status :complete
          :task-tree-status :complete
          :cancellation-status :complete
          :atomic-status :complete
          :synchronization-status :complete
          :actor-channel-status :complete
          :ownership-transfer-status :complete
          :replay-status :complete
          :capability-status :complete
          :diagnostic-status :complete
          :status :complete}
         :diagnostics []}
        _ (r6-document-validate! source-path artifact-base)
        capability-proof (r6-document-capability-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn r6-document-file-artifact
  [path]
  (r6-document-source-artifact path (slurp path)))

(def r7-document-governing-document
  "docs/phase-08-runtime-architecture/118-r7-distributed-runtime-design.md")

(def r7-document-upstream-artifact-path
  "bootstrap/clojure/fixtures/accepted/runtime-concurrency-distributed.gravity")

(def r7-document-diagnostic-ids
  ["R7-TOPOLOGY"
   "R7-SCHEMA"
   "R7-REPLAY"
   "R7-IDEMPOTENCY"
   "R7-RETRY"
   "R7-COMPENSATION"
   "R7-CAPABILITY"
   "R7-MIGRATION"
   "R7-ACTOR"
   "R7-MANIFEST"])

(def r7-document-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             r7-document-diagnostic-ids)))

(defn r7-document-source-overrides
  [module]
