            :rejects #{:untyped-edge :hidden-effect :visual-authority :diagnostic-without-node-map}
            :dependencies #{"B10" "R7" "R8" "PHASE11" "SCHEMA" "SAFE10" "SAFE11" "SAFE12" "TOOLING"}}})

(def p09-domain-rejected-diagnostics
  {"DOM1" "DOM1-WIDTH"
   "DOM2" "DOM2-MMIO"
   "DOM3" "DOM3-RAW"
   "DOM4" "DOM4-DMA"
   "DOM5" "DOM5-OPTIMIZATION"
   "DOM6" "DOM6-TAINT"
   "DOM7" "DOM7-PERMISSION"
   "DOM8" "DOM8-SCHEMA"
   "DOM9" "DOM9-CONVERGENCE"
   "DOM10" "DOM10-QUERY"
   "DOM11" "DOM11-LINEAGE"
   "DOM12" "DOM12-CERTIFICATE"
   "DOM13" "DOM13-HOST-EFFECT"
   "DOM14" "DOM14-DETERMINISM"
   "DOM15" "DOM15-BOUNDARY"
   "DOM16" "DOM16-AA-PROFILE"
   "DOM17" "DOM17-METADATA"
   "DOM18" "DOM18-TOOL"
   "DOM19" "DOM19-ZK-SETUP"
   "DOM20" "DOM20-TAINT"
   "DOM21" "DOM21-EDGE"})

(def p09-domain-diagnostic-ids
  (vec
   (distinct
    (concat
     (mapcat
      (fn [document]
        (map (comp first val)
             (sort-by (comp name key) (p09-domain-contracts document))))
      p09-domain-documents)
     ["P09-MANIFEST" "P09-ACCEPTED" "P09-REJECTED"
      "P09-CLAIM" "P09-CONFORMANCE"]))))

(def p09-domain-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             p09-domain-diagnostic-ids)))

(defn p09-document-number
  [document]
  (Integer/parseInt (subs document 3)))

(defn p09-task-id
  [document]
  (str "P09-D" (+ 123 (p09-document-number document))))

(defn p09-domain-source-overrides
  [module]
  (get-in module [:metadata :domain :coverage] {}))

(defn p09-domain-diagnostic-document
  [diagnostic-id]
  (some (fn [document]
          (when (some #(= diagnostic-id (first %))
                      (vals (p09-domain-contracts document)))
            document))
        p09-domain-documents))

(defn p09-domain-fail!
  [id source-path subject extra]
  (let [document (or (:document-id subject)
                     (p09-domain-diagnostic-document id))]
    (fail! id
           "P09 domain coverage validation failed"
           (merge {:source-span (or (:source-span subject)
                                    (source-span source-path 0))
                   :diagnostic-family :phase09-domain-coverage
                   :stage :domain-coverage
                   :document-id document
                   :task (when document (p09-task-id document))
                   :domain (:domain subject)
                   :profile (or (:profile subject) :hosted)
                   :target (or (:target subject) :jvm)
                   :artifact-id (:artifact-id subject)
                   :claim-id (:claim-id subject)
                   :missing-fact (:missing-fact subject)
                   :fallback-status :rejected
                   :remediation "Phase 09 requires a slice-scoped domain manifest with profiles, backends, runtime services, effects, capabilities, artifacts, accepted and rejected fixtures, replacement claim boundaries, conformance evidence, and stable DOM diagnostics."}
                  extra))))

(defn p09-domain-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (when-let [id (get p09-domain-override-diagnostics fail-kind)]
      (p09-domain-fail!
       id source-path
       {:artifact-id (str "p09-domain-" (name fail-kind))
        :claim-id (when (= id "P09-CLAIM") "phase09-broad-replacement")
        :document-id (p09-domain-diagnostic-document id)
        :missing-fact fail-kind}
       {:missing-fields [fail-kind]}))))

(defn p09-contract-diagnostics
  [document]
  (mapv (comp first val)
        (sort-by (comp name key) (p09-domain-contracts document))))

(defn p09-contract-evidence
  [document]
  (into {}
        (map (fn [[fact [diagnostic missing-fact]]]
               [fact {:diagnostic diagnostic
                      :missing-fact missing-fact
                      :source :governing-document
                      :status :present}])
             (sort-by (comp name key) (p09-domain-contracts document)))))

(defn p09-domain-record
  [document]
  (let [summary (p09-domain-summaries document)
        diagnostic (p09-domain-rejected-diagnostics document)]
    (merge
     {:document document
      :task-id (p09-task-id document)
      :governing-doc (p09-domain-governing-documents document)
      :diagnostics (p09-contract-diagnostics document)
      :evidence (p09-contract-evidence document)
      :replacement-scope
      {:claim-status :slice-supported
       :scope (str "Phase 09 " document " implementable vertical slice")
       :provider-boundaries #{:host-runtime :backend-provider
                              :external-toolchain :platform-provider}
       :claim-limits #{:no-platform-wide-replacement
                       :no-provider-replacement
                       :requires-fixture-evidence}}
      :conformance
      {:accepted-fixture "bootstrap/clojure/fixtures/accepted/domain-coverage.gravity"
       :rejected-fixture (str "bootstrap/clojure/fixtures/rejected/domain-"
                              (str/lower-case document) "-"
                              (str/lower-case diagnostic)
                              ".gravity")
       :artifact-evidence :domain-coverage-artifact
       :validation-command "clojure -M:test"
       :status :complete}}
     summary)))

(defn p09-domain-records
  []
  (into {} (map (fn [document] [document (p09-domain-record document)])
                p09-domain-documents)))

(defn p09-domain-slice-manifest
  [input-id]
  {:artifact :gravity/domain-slice-manifest
   :input-artifact input-id
   :documents p09-domain-documents
   :packet [:incumbent-comparison :profiles :backends :runtime-services
            :effects :capabilities :examples :artifacts :proof-gaps
            :replacement-scope :conformance-evidence]
   :incumbent-comparison :recorded-per-domain
   :profile-matrix :profile-target-backend-runtime-separated
   :artifact-packet :manifest-fixtures-diagnostics-conformance
   :proof-gaps :recorded-as-later-phase-dependencies
   :replacement-claim-policy :slice-scoped-only
   :status :complete})

(defn p09-accepted-domain-fixtures
  []
  (mapv (fn [document]
          {:document document
           :fixture "bootstrap/clojure/fixtures/accepted/domain-coverage.gravity"
           :artifact :domain-slice-manifest
           :evidence [(p09-task-id document)
                      (p09-domain-governing-documents document)]
           :status :accepted})
        p09-domain-documents))

(defn p09-rejected-domain-fixtures
  []
  (mapv (fn [document]
          (let [diagnostic (p09-domain-rejected-diagnostics document)]
            {:document document
             :fixture (str "bootstrap/clojure/fixtures/rejected/domain-"
                           (str/lower-case document) "-"
                           (str/lower-case diagnostic)
                           ".gravity")
             :artifact :stable-domain-diagnostic
             :diagnostic diagnostic
             :evidence [(p09-task-id document)
                        (p09-domain-governing-documents document)]
             :status :rejected}))
        p09-domain-documents))

(defn p09-replacement-claim-records
  []
  (mapv (fn [document]
          {:document document
           :claim-id (str "phase09-" (str/lower-case document) "-slice-claim")
           :claim-status :slice-supported
           :evidence-refs [(p09-task-id document)
                           "bootstrap/clojure/fixtures/accepted/domain-coverage.gravity"
                           (str "diagnostic:" (p09-domain-rejected-diagnostics document))]
           :excluded-provider-boundaries #{:host-platform :cloud-provider
                                           :browser-engine :mobile-os
                                           :chain-consensus :proof-provider}
           :status :complete})
        p09-domain-documents))

(defn p09-domain-conformance-evidence
  []
  (mapv (fn [document]
          {:document document
           :accepted-behavior :slice-manifest-accepted
           :rejected-behavior (p09-domain-rejected-diagnostics document)
           :artifacts [:domain-slice-manifest :domain-contract
                       :replacement-claim-record :diagnostic-stream]
           :validation ["clojure -M:test"
                        "clojure -M:gravity domain-coverage bootstrap/clojure/fixtures/accepted/domain-coverage.gravity"]
           :status :complete})
        p09-domain-documents))

(defn p09-domain-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/phase09-domain-diagnostic-stream
   :stage :domain-coverage
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           (let [document (p09-domain-diagnostic-document id)]
             {:artifact :gravity/diagnostic
              :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
              :diagnostic id
              :rule id
              :severity :error
              :stage :domain-coverage
              :document-id document
              :task (when document (p09-task-id document))
              :primary {:span (source-span source-path index)
                        :syntax-id (str "p09-domain-syntax-" index)
                        :artifact input-id}
              :missing-fact (or (some (fn [[_ [diagnostic missing-fact]]]
                                         (when (= id diagnostic) missing-fact))
                                       (get p09-domain-contracts document))
                                :domain_coverage_manifest)
              :remediation [{:kind :complete-domain-packet}
                            {:kind :attach-accepted-and-rejected-fixtures}
                            {:kind :scope-replacement-claim}
                            {:kind :record-conformance-evidence}]
              :ordering-key [id :domain-coverage]}))
         p09-domain-diagnostic-ids
         (range))
   :status :complete})

(defn p09-present?
  [value]
  (if (coll? value)
    (seq value)
    (some? value)))

(defn p09-domain-validate!
  [source-path artifact]
  (let [manifest (:domain-slice-manifest artifact)
        domains (:domain-contracts artifact)
        accepted (:accepted-domain-fixtures artifact)
        rejected (:rejected-domain-fixtures artifact)
        claims (:replacement-claim-records artifact)
        conformance (:domain-conformance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:domain-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= (set p09-domain-documents) (set (:documents manifest)))
      (p09-domain-fail! "P09-MANIFEST" source-path manifest
                        {:missing-fields [:documents]}))
    (when-not (every? #(contains? domains %) p09-domain-documents)
      (p09-domain-fail! "P09-MANIFEST" source-path domains
                        {:missing-fields [:domain-contracts]}))
    (doseq [document p09-domain-documents
            :let [record (get domains document)
                  summary (p09-domain-summaries document)
                  contract (p09-domain-contracts document)]]
      (doseq [field [:domain :profiles :backends :runtime-services
                     :schemas :capabilities :effects :artifacts :examples
                     :rejects :dependencies :replacement-scope :conformance
                     :evidence]]
        (when-not (p09-present? (get record field))
          (p09-domain-fail! "P09-MANIFEST" source-path record
                            {:missing-fields [field]})))
      (when-not (= (:domain summary) (:domain record))
        (p09-domain-fail! "P09-MANIFEST" source-path record
                          {:missing-fields [:domain]}))
      (doseq [[fact [diagnostic _]] contract]
        (when-not (and (contains? (set (:diagnostics record)) diagnostic)
                       (get-in record [:evidence fact]))
          (p09-domain-fail! diagnostic source-path record
                            {:missing-fields [fact]})))
      (when (= :full-replacement
               (get-in record [:replacement-scope :claim-status]))
        (p09-domain-fail! "P09-CLAIM" source-path record
                          {:missing-fields [:slice-supported]})))
    (when-not (= (set p09-domain-documents)
                 (set (map :document accepted)))
      (p09-domain-fail! "P09-ACCEPTED" source-path accepted
                        {:missing-fields [:accepted-domain-fixtures]}))
    (when-not (= (set p09-domain-documents)
                 (set (map :document rejected)))
      (p09-domain-fail! "P09-REJECTED" source-path rejected
                        {:missing-fields [:rejected-domain-fixtures]}))
    (when-not (= (set p09-domain-documents)
                 (set (map :document claims)))
      (p09-domain-fail! "P09-CLAIM" source-path claims
                        {:missing-fields [:replacement-claim-records]}))
    (doseq [claim claims]
      (when-not (and (= :slice-supported (:claim-status claim))
                     (seq (:evidence-refs claim))
                     (seq (:excluded-provider-boundaries claim)))
        (p09-domain-fail! "P09-CLAIM" source-path claim
                          {:missing-fields [:evidence-refs]})))
    (when-not (= (set p09-domain-documents)
                 (set (map :document conformance)))
      (p09-domain-fail! "P09-CONFORMANCE" source-path conformance
                        {:missing-fields [:domain-conformance-evidence]}))
    (when-not (every? #(and (:accepted-behavior %)
                            (:rejected-behavior %)
                            (seq (:artifacts %))
                            (seq (:validation %)))
                      conformance)
      (p09-domain-fail! "P09-CONFORMANCE" source-path conformance
                        {:missing-fields [:conformance-record]}))
    (when-not (set/subset? (set p09-domain-diagnostic-ids) diagnostics)
      (p09-domain-fail! "P09-MANIFEST" source-path
                        (:domain-diagnostic-stream artifact)
                        {:missing-fields [:diagnostics]})))
  :complete)

(defn p09-task-statuses
  []
  (merge (zipmap ["P09-T01" "P09-T02" "P09-T03"
                  "P09-T04" "P09-T05" "P09-T06"]
                 (repeat :complete))
         (zipmap (map p09-task-id p09-domain-documents)
                 (repeat :complete))))

(defn p09-domain-proof
  [artifact]
  (let [domains (:domain-contracts artifact)
        accepted-docs (set (map :document (:accepted-domain-fixtures artifact)))
        rejected-docs (set (map :document (:rejected-domain-fixtures artifact)))
        claim-statuses (set (map :claim-status (:replacement-claim-records artifact)))
        conformance-docs (set (map :document (:domain-conformance-evidence artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:domain-diagnostic-stream
                                       :diagnostics])))]
    {:domain-slice-template-covered?
     (= :complete (get-in artifact [:domain-slice-manifest :status]))
     :systems-domains-covered?
     (every? #(contains? domains %) ["DOM1" "DOM2" "DOM3" "DOM4"
                                     "DOM5" "DOM13" "DOM15" "DOM19"])
     :application-domains-covered?
     (every? #(contains? domains %) ["DOM6" "DOM7" "DOM8" "DOM14"
                                     "DOM20" "DOM21"])
     :data-and-distributed-domains-covered?
     (every? #(contains? domains %) ["DOM9" "DOM10" "DOM11"])
     :ai-and-tooling-domains-covered?
     (every? #(contains? domains %) ["DOM17" "DOM18" "DOM21"])
     :domain-claim-governance-covered?
     (= claim-statuses #{:slice-supported})
     :document-coverage-complete?
     (= (set p09-domain-documents) (set (keys domains)))
     :accepted-fixtures-covered?
     (= (set p09-domain-documents) accepted-docs)
     :rejected-fixtures-covered?
     (= (set p09-domain-documents) rejected-docs)
     :conformance-evidence-covered?
     (= (set p09-domain-documents) conformance-docs)
     :special-domain-obligations-covered?
     (and (contains? (set (get-in domains ["DOM15" :diagnostics]))
                     "DOM15-PASSKEY")
          (contains? (set (get-in domains ["DOM15" :diagnostics]))
                     "DOM15-PRIVATE-COMPUTE")
          (contains? (set (get-in domains ["DOM16" :diagnostics]))
                     "DOM16-ERC4337")
          (contains? (set (get-in domains ["DOM16" :diagnostics]))
                     "DOM16-EIP7702")
          (contains? (set (get-in domains ["DOM16" :diagnostics]))
                     "DOM16-ERC7579")
          (contains? (set (get-in domains ["DOM19" :diagnostics]))
                     "DOM19-ZK-PRIVACY"))
     :diagnostics-covered?
     (set/subset? (set p09-domain-diagnostic-ids) diagnostics)
     :task-statuses (p09-task-statuses)
     :status :complete}))

(defn domain-coverage-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (p09-domain-source-overrides module)
        _ (p09-domain-validate-source-overrides! source-path source-overrides)
        input-id (c4-artifact-id {:source-path source-path
                                  :module (:module module)
                                  :task "P09-T01-T06"
                                  :documents p09-domain-documents})
        diagnostic-stream (p09-domain-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-domain-coverage-artifact
         :phase "09"
         :task "P09-T01-T06"
         :document-set p09-domain-documents
         :governing-documents p09-domain-phase-governing-documents
         :pass {:name :phase09-domain-coverage
                :input :ordinary-gravity-source
                :output :domain-coverage-artifact
                :requires [:domain-slice-manifest :domain-contracts
                           :accepted-domain-fixtures
                           :rejected-domain-fixtures
                           :replacement-claim-records
                           :domain-conformance-evidence]
                :preserves [:profile :target :backend :runtime
                            :effect :capability :artifact
                            :source-spans :metadata :provider-boundaries]
                :emits [:domain-slice-manifest :domain-contracts
                        :accepted-domain-fixtures
                        :rejected-domain-fixtures
                        :replacement-claim-records
                        :domain-conformance-evidence
                        :domain-diagnostic-stream]
                :rejects p09-domain-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :domain-slice-manifest (p09-domain-slice-manifest input-id)
         :domain-contracts (p09-domain-records)
         :accepted-domain-fixtures (p09-accepted-domain-fixtures)
         :rejected-domain-fixtures (p09-rejected-domain-fixtures)
         :replacement-claim-records (p09-replacement-claim-records)
         :domain-conformance-evidence (p09-domain-conformance-evidence)
         :domain-diagnostic-stream diagnostic-stream
         :domain-coverage-results
         {:documents p09-domain-documents
          :tasks (p09-task-statuses)
          :domain-records 21
          :accepted-fixtures 21
          :rejected-fixtures 21
          :replacement-claims 21
          :conformance-records 21
          :diagnostic-count (count p09-domain-diagnostic-ids)
          :status :complete}
         :diagnostics []}
        _ (p09-domain-validate! source-path artifact-base)
        capability-proof (p09-domain-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn domain-coverage-file-artifact
  [path]
  (domain-coverage-source-artifact path (slurp path)))

