(defn p10-document-record
  [document]
  (let [summary (p10-document-summaries document)]
    (merge
     {:document document
      :task-id (p10-task-id document)
      :governing-doc (p10-schema-governing-documents document)
      :schema-id (:schema-id p10-source-schema-contract)
      :schema-version (:schema-version p10-source-schema-contract)
      :schema-hash p10-schema-hash
      :diagnostics (p10-contract-diagnostics document)
      :evidence (p10-contract-evidence document)
      :conformance
      {:accepted-fixture "bootstrap/clojure/fixtures/accepted/schema-interop.gravity"
       :rejected-fixture (str "bootstrap/clojure/fixtures/rejected/"
                              (p10-rejected-fixture-name document))
       :artifact-evidence :schema-interop-artifact
       :validation-command "clojure -M:test"
       :status :complete}}
     summary)))

(defn p10-document-records
  []
  (into {} (map (fn [document] [document (p10-document-record document)])
                p10-schema-documents)))

(defn p10-accepted-schema-fixtures
  []
  (mapv (fn [document]
          {:document document
           :fixture "bootstrap/clojure/fixtures/accepted/schema-interop.gravity"
           :artifact (get-in (p10-document-summaries document) [:owned-surface])
           :evidence [(p10-task-id document)
                      (p10-schema-governing-documents document)]
           :status :accepted})
        p10-schema-documents))

(defn p10-rejected-schema-fixtures
  []
  (mapv (fn [document]
          (let [diagnostic (p10-schema-rejected-diagnostics document)]
            {:document document
             :fixture (str "bootstrap/clojure/fixtures/rejected/"
                           (p10-rejected-fixture-name document))
             :artifact :stable-schema-interop-diagnostic
             :diagnostic diagnostic
             :evidence [(p10-task-id document)
                        (p10-schema-governing-documents document)]
             :status :rejected}))
        p10-schema-documents))

(defn p10-schema-conformance-evidence
  []
  (mapv (fn [document]
          {:document document
           :accepted-behavior (get-in (p10-document-summaries document)
                                      [:accepted-behavior])
           :rejected-behavior (p10-schema-rejected-diagnostics document)
           :artifacts (get-in (p10-document-summaries document)
                              [:artifact-keys])
           :validation ["clojure -M:test"
                        "clojure -M:gravity schema-interop bootstrap/clojure/fixtures/accepted/schema-interop.gravity"]
           :status :complete})
        p10-schema-documents))

(defn p10-schema-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/phase10-schema-interop-diagnostic-stream
   :stage :schema-interop
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           (let [document (p10-schema-diagnostic-document id)]
             {:artifact :gravity/diagnostic
              :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
              :diagnostic id
              :rule id
              :severity :error
              :stage :schema-interop
              :document-id document
              :task (when document (p10-task-id document))
              :primary {:span (source-span source-path index)
                        :syntax-id (str "p10-schema-syntax-" index)
                        :artifact input-id}
              :missing-fact (or (some (fn [[_ [diagnostic missing-fact]]]
                                         (when (= id diagnostic) missing-fact))
                                       (get p10-schema-contracts document))
                                :schema_interop_manifest)
              :remediation [{:kind :preserve-source-schema-authority}
                            {:kind :attach-schema-hash-and-source-span}
                            {:kind :preserve-taint-effects-capabilities}
                            {:kind :add-accepted-and-rejected-fixtures}]
              :ordering-key [id :schema-interop]}))
         p10-schema-diagnostic-ids
         (range))
   :status :complete})

(defn p10-present?
  [value]
  (if (coll? value)
    (seq value)
    (some? value)))

(defn p10-schema-validate!
  [source-path artifact]
  (let [documents (:document-contracts artifact)
        accepted (:accepted-schema-fixtures artifact)
        rejected (:rejected-schema-fixtures artifact)
        conformance (:schema-conformance-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:schema-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= (set p10-schema-documents) (set (:document-set artifact)))
      (p10-schema-fail! "P10-MANIFEST" source-path artifact
                        {:missing-fields [:document-set]}))
    (when-not (every? #(contains? documents %) p10-schema-documents)
      (p10-schema-fail! "P10-MANIFEST" source-path documents
                        {:missing-fields [:document-contracts]}))
    (doseq [artifact-key p10-schema-artifact-keys
            :let [schema-artifact (get artifact artifact-key)]]
      (when-not (p10-present? schema-artifact)
        (p10-schema-fail! "P10-MANIFEST" source-path artifact
                          {:missing-fields [artifact-key]}))
      (when-not (= p10-schema-hash (:schema-hash schema-artifact))
        (p10-schema-fail! "S1-MANIFEST" source-path schema-artifact
                          {:missing-fields [:schema-hash]})))
    (when-not (every? #(= :complete (:status (get artifact %)))
                      p10-generated-artifact-keys)
      (p10-schema-fail! "P10-MANIFEST" source-path artifact
                        {:missing-fields [:generated-artifact-status]}))
    (doseq [document p10-schema-documents
            :let [record (get documents document)
                  summary (p10-document-summaries document)
                  contract (p10-schema-contracts document)]]
      (doseq [field [:document :task-id :governing-doc :schema-id
                     :schema-version :schema-hash :diagnostics :evidence
                     :owned-surface :accepted-behavior :rejected-behavior
                     :artifact-keys :conformance]]
        (when-not (p10-present? (get record field))
          (p10-schema-fail! "P10-MANIFEST" source-path record
                            {:missing-fields [field]})))
      (when-not (= (:owned-surface summary) (:owned-surface record))
        (p10-schema-fail! "P10-MANIFEST" source-path record
                          {:missing-fields [:owned-surface]}))
      (doseq [[fact [diagnostic _]] contract]
        (when-not (and (contains? (set (:diagnostics record)) diagnostic)
                       (get-in record [:evidence fact]))
          (p10-schema-fail! diagnostic source-path record
                            {:missing-fields [fact]}))))
    (when-not (= (set p10-schema-documents)
                 (set (map :document accepted)))
      (p10-schema-fail! "P10-ACCEPTED" source-path accepted
                        {:missing-fields [:accepted-schema-fixtures]}))
    (when-not (= (set p10-schema-documents)
                 (set (map :document rejected)))
      (p10-schema-fail! "P10-REJECTED" source-path rejected
                        {:missing-fields [:rejected-schema-fixtures]}))
    (when-not (= (set p10-schema-documents)
                 (set (map :document conformance)))
      (p10-schema-fail! "P10-CONFORMANCE" source-path conformance
                        {:missing-fields [:schema-conformance-evidence]}))
    (when-not (every? #(and (:accepted-behavior %)
                            (:rejected-behavior %)
                            (seq (:artifacts %))
                            (seq (:validation %)))
                      conformance)
      (p10-schema-fail! "P10-CONFORMANCE" source-path conformance
                        {:missing-fields [:conformance-record]}))
    (when-not (= :gravity-source-schema
                 (get-in artifact [:graphql-generation :source-authority]))
      (p10-schema-fail! "S4-MAPPING" source-path
                        (:graphql-generation artifact)
                        {:missing-fields [:source-authority]}))
    (when-not (= :gravity-route-and-schema-source
                 (get-in artifact [:openapi-generation :source-authority]))
      (p10-schema-fail! "S5-SCHEMA" source-path
                        (:openapi-generation artifact)
                        {:missing-fields [:source-authority]}))
    (when-not (= :no-data-loss
                 (get-in artifact
                         [:database-mapping :data-loss-report :policy]))
      (p10-schema-fail! "S6-DATA-LOSS" source-path
                        (:database-mapping artifact)
                        {:missing-fields [:data-loss-policy]}))
    (when-not (= :no-raw-pointers-in-stable-record
                 (get-in artifact [:binary-abi-schema :pointer-policy]))
      (p10-schema-fail! "S7-POINTER" source-path
                        (:binary-abi-schema artifact)
                        {:missing-fields [:pointer-policy]}))
    (when-not (= :redacted
                 (get-in artifact
                         [:typed-config :redaction-report :database-url]))
      (p10-schema-fail! "S8-SECRET" source-path
                        (:typed-config artifact)
                        {:missing-fields [:secret-redaction]}))
    (when-not (set/subset? #{:types :effects :capabilities :safety
                             :proofs :tests :diagnostics :conformance}
                           (set (get-in artifact
                                        [:artifact-schema-registry
                                         :evidence-schema])))
      (p10-schema-fail! "S9-EVIDENCE" source-path
                        (:artifact-schema-registry artifact)
                        {:missing-fields [:evidence-schema]}))
    (when-not (set/subset? (set p10-schema-diagnostic-ids) diagnostics)
      (p10-schema-fail! "P10-MANIFEST" source-path
                        (:schema-diagnostic-stream artifact)
                        {:missing-fields [:diagnostics]})))
  :complete)

(defn p10-task-statuses
  []
  (merge (zipmap ["P10-T01" "P10-T02" "P10-T03"
                  "P10-T04" "P10-T05" "P10-T06"]
                 (repeat :complete))
         (zipmap (map p10-task-id p10-schema-documents)
                 (repeat :complete))))

(defn p10-schema-proof
  [artifact]
  (let [documents (:document-contracts artifact)
        accepted-docs (set (map :document (:accepted-schema-fixtures artifact)))
        rejected-docs (set (map :document (:rejected-schema-fixtures artifact)))
        conformance-docs (set (map :document (:schema-conformance-evidence artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:schema-diagnostic-stream
                                       :diagnostics])))]
    {:source-schema-authority-covered?
     (= (:schema-hash (:source-schema-ir artifact))
        p10-schema-hash)
     :validator-boundaries-covered?
     (set/subset? #{:api-input :database-row :model-output
                    :configuration :artifact-manifest}
                  (:clears-taint-for (:validator-artifact artifact)))
     :serialization-and-canonical-covered?
     (and (= :untrusted
             (:decoded-trust (:serialization-fixture artifact)))
          (true? (:schema-hash-included (:canonical-format artifact))))
     :api-projections-covered?
     (and (= :gravity-source-schema
             (get-in artifact [:graphql-generation :source-authority]))
          (= :gravity-route-and-schema-source
             (get-in artifact [:openapi-generation :source-authority])))
     :database-migration-covered?
     (= :rollback-supported
        (:rollback-or-forward-policy (:database-mapping artifact)))
     :abi-and-config-covered?
     (and (= :no-raw-pointers-in-stable-record
             (:pointer-policy (:binary-abi-schema artifact)))
          (= :redacted
             (get-in artifact [:typed-config :redaction-report
                               :database-url])))
     :artifact-and-ai-schema-covered?
     (and (contains? (set (get-in artifact
                                  [:artifact-schema-registry
                                   :evidence-schema]))
                     :conformance)
          (= :tainted-until-schema-validation
             (:provider-output-trust
              (:ai-structured-output-contract artifact))))
     :document-coverage-complete?
     (= (set p10-schema-documents) (set (keys documents)))
     :accepted-fixtures-covered?
     (= (set p10-schema-documents) accepted-docs)
     :rejected-fixtures-covered?
     (= (set p10-schema-documents) rejected-docs)
     :conformance-evidence-covered?
     (= (set p10-schema-documents) conformance-docs)
     :diagnostics-covered?
     (set/subset? (set p10-schema-diagnostic-ids) diagnostics)
     :task-statuses (p10-task-statuses)
     :status :complete}))

(defn schema-interop-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (p10-schema-source-overrides module)
        _ (p10-schema-validate-source-overrides! source-path source-overrides)
        input-id (c4-artifact-id {:source-path source-path
                                  :module (:module module)
                                  :task "P10-T01-T06"
                                  :documents p10-schema-documents})
        source-schema (p10-source-schema-ir source-path input-id)
        diagnostic-stream (p10-schema-diagnostic-stream source-path input-id)
        artifact-base
        {:kind :gravity/stage0-schema-interop-artifact
         :phase "10"
         :task "P10-T01-T06"
         :document-set p10-schema-documents
         :governing-documents p10-schema-phase-governing-documents
         :pass {:name :phase10-schema-interop
                :input :ordinary-gravity-source
                :output :schema-interop-artifact
                :requires [:source-schema-ir :validator-artifact
                           :serialization-fixture :canonical-format
                           :graphql-generation :openapi-generation
                           :database-mapping :binary-abi-schema
                           :typed-config :artifact-schema-registry
                           :ai-structured-output-contract]
                :preserves [:schema-id :schema-version :schema-hash
                            :source-spans :compatibility-policy
                            :validation-boundary :taint :effects
                            :capabilities :profile :target :provenance]
                :emits [:document-contracts :accepted-schema-fixtures
                        :rejected-schema-fixtures :schema-conformance-evidence
                        :schema-diagnostic-stream]
                :rejects p10-schema-diagnostic-ids}
         :source-overrides source-overrides
         :module (select-keys module [:module :source-path :profile :target
                                      :effects :capabilities :safety
                                      :metadata])
         :source-schema-ir source-schema
         :validator-artifact (p10-validator-artifact source-schema)
         :serialization-fixture (p10-serialization-fixture source-schema)
         :canonical-format (p10-canonical-format source-schema)
         :graphql-generation (p10-graphql-generation source-schema)
         :openapi-generation (p10-openapi-generation source-schema)
         :database-mapping (p10-database-mapping source-schema)
         :binary-abi-schema (p10-binary-abi-schema source-schema)
         :typed-config (p10-typed-config source-schema)
         :artifact-schema-registry (p10-artifact-schema-registry source-schema)
         :ai-structured-output-contract (p10-ai-structured-output-contract
                                         source-schema)
         :document-contracts (p10-document-records)
         :accepted-schema-fixtures (p10-accepted-schema-fixtures)
         :rejected-schema-fixtures (p10-rejected-schema-fixtures)
         :schema-conformance-evidence (p10-schema-conformance-evidence)
         :schema-diagnostic-stream diagnostic-stream
         :schema-interop-results
         {:documents p10-schema-documents
          :tasks (p10-task-statuses)
          :document-contracts 9
          :generated-artifact-families (count p10-generated-artifact-keys)
          :accepted-fixtures 9
          :rejected-fixtures 9
          :conformance-records 9
          :diagnostic-count (count p10-schema-diagnostic-ids)
          :status :complete}
         :diagnostics []}
        _ (p10-schema-validate! source-path artifact-base)
        capability-proof (p10-schema-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn schema-interop-file-artifact
  [path]
  (schema-interop-source-artifact path (slurp path)))

