  {"STAGE1001" "stage1 Gravity bootstrap source must declare Gravity ownership"
   "STAGE1002" "stage1 Gravity bootstrap source must use the meta profile and stage1 marker"
   "STAGE1003" "stage1 Gravity bootstrap source must deny ambient authority"
   "STAGE1004" "stage1 Gravity bootstrap source must record seed and stage lineage"
   "STAGE1005" "stage1 Gravity bootstrap source must preserve required compiler facts"
   "STAGE1006" "stage1 Gravity bootstrap source set is incomplete"})

(def stage1-bootstrap-diagnostic-ids
  ["STAGE1001" "STAGE1002" "STAGE1003"
   "STAGE1004" "STAGE1005" "STAGE1006"])

(def stage1-bootstrap-rejected-fixture-records
  [{:fixture "bootstrap/clojure/fixtures/rejected/stage1-bootstrap-missing-owner.gravity"
    :diagnostic "STAGE1001"
    :rejected-behavior :missing-gravity-source-owner}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-bootstrap-wrong-profile.gravity"
    :diagnostic "STAGE1002"
    :rejected-behavior :wrong-bootstrap-profile}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-bootstrap-ambient-authority.gravity"
    :diagnostic "STAGE1003"
    :rejected-behavior :ambient-authority}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-bootstrap-missing-lineage.gravity"
    :diagnostic "STAGE1004"
    :rejected-behavior :missing-bootstrap-lineage}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-bootstrap-missing-preserved-fact.gravity"
    :diagnostic "STAGE1005"
    :rejected-behavior :missing-preserved-fact}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-bootstrap-incomplete-source-set.gravity"
    :diagnostic "STAGE1006"
    :rejected-behavior :incomplete-source-set}])

(defn stage1-bootstrap-fail!
  [id source-path value data]
  (fail! id
         (get stage1-bootstrap-diagnostic-messages
              id
              "stage1 Gravity bootstrap source is invalid")
         (merge {:source-span {:source source-path}
                 :stage :stage1-bootstrap-source
                 :diagnostic-family :stage1-bootstrap-source
                 :value value
                 :remediation "Keep stage1 bootstrap source in Gravity, keep the Clojure seed explicit, deny ambient authority, preserve compiler facts, and include the reader, syntax, diagnostics, source-frontend, syntax-object-model, and compiler-diagnostics components."}
                data)))

(defn stage1-bootstrap-source-files
  [path]
  (let [root (java.io.File. path)]
    (cond
      (.isDirectory root)
      (let [files (->> (file-seq root)
                       (filter #(.isFile %))
                       (filter #(qst-or-gravity-source? (.getName %)))
                       (sort-by #(.getPath %))
                       (mapv #(.getPath %)))]
        (when-not (seq files)
          (stage1-bootstrap-fail! "STAGE1006" path nil
                                  {:missing-fields [:gravity-source-files]}))
        files)

      (.isFile root) [(.getPath root)]

      :else
      (stage1-bootstrap-fail! "STAGE1006" path nil
                              {:missing-fields [:gravity-source-root]}))))

(defn stage1-bootstrap-module-metadata
  [source-path module]
  (let [metadata (get-in module [:metadata :bootstrap])]
    (when-not (map? metadata)
      (stage1-bootstrap-fail! "STAGE1001" source-path metadata
                              {:module (:module module)
                               :missing-fields [:metadata :bootstrap]}))
    metadata))

(defn stage1-bootstrap-validate-module!
  [source-path module metadata]
  (when-not (= :gravity-source (:owner metadata))
    (stage1-bootstrap-fail! "STAGE1001" source-path metadata
                            {:module (:module module)
                             :missing-fields [:owner]}))
  (when-not (and (= :meta (:profile module))
                 (= :stage1 (:stage metadata)))
    (stage1-bootstrap-fail! "STAGE1002" source-path metadata
                            {:module (:module module)
                             :profile (:profile module)
                             :expected-profile :meta
                             :missing-fields [:stage]}))
  (when-not (and (empty? (:effects module))
                 (empty? (:capabilities module))
                 (true? (:ambient-authority-denied metadata)))
    (stage1-bootstrap-fail! "STAGE1003" source-path metadata
                            {:module (:module module)
                             :denied-effects (:effects module)
                             :denied-capabilities (:capabilities module)
                             :missing-fields [:ambient-authority-denied]}))
  (when-not (and (= :gravity (:source-language metadata))
                 (= :clojure-stage0 (:seed metadata))
                 (= :replace-clojure-seed
                    (:retirement-objective metadata))
                 (= :clojure-stage0 (get-in metadata
                                             [:lineage :verified-by]))
                 (= :stage1 (get-in metadata [:lineage :next-stage])))
    (stage1-bootstrap-fail! "STAGE1004" source-path metadata
                            {:module (:module module)
                             :missing-fields [:source-language :seed
                                              :retirement-objective
                                              :lineage]}))
  (when-not (set/subset? stage1-bootstrap-required-preserved-facts
                         (set (:preserves metadata)))
    (stage1-bootstrap-fail! "STAGE1005" source-path metadata
                            {:module (:module module)
                             :missing-fields [:preserves]
                             :missing-fact
                             (vec (sort (set/difference
                                          stage1-bootstrap-required-preserved-facts
                                          (set (:preserves metadata)))))}))
  :complete)

(defn stage1-bootstrap-module-record
  [source-path]
  (let [source-text (slurp source-path)
        records (read-source-form-records source-path source-text)
        forms (mapv :form records)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        syntax (syntax-object-stream source-path records module)
        metadata (stage1-bootstrap-module-metadata source-path module)
        _ (stage1-bootstrap-validate-module! source-path module metadata)]
    {:module (:module module)
     :source-path source-path
     :source-language (:source-language metadata)
     :profile (:profile module)
     :target (:target module)
     :effects (:effects module)
     :capabilities (:capabilities module)
     :safety (:safety module)
     :component (:component metadata)
     :implements (vec (:implements metadata))
     :preserves (vec (sort (:preserves metadata)))
     :documents (vec (:documents metadata))
     :lineage (:lineage metadata)
     :definitions (definition-table syntax module)
     :form-count (count forms)
     :syntax-object-count (count syntax)
     :source-hash (str "sha256:" (sha256-hex source-text))
     :metadata metadata}))

(defn stage1-bootstrap-diagnostic-stream
  [source-root source-set-id]
  {:artifact :gravity/stage1-bootstrap-source-diagnostic-stream
   :stage :stage1-bootstrap-source
   :source-root source-root
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id) "-stage1")
            :diagnostic id
            :severity :error
            :stage :stage1-bootstrap-source
            :artifact :gravity/diagnostic
            :input-artifact-id source-set-id
            :message (stage1-bootstrap-diagnostic-messages id)
            :remediation [{:kind :keep-gravity-owned-source}
                          {:kind :deny-ambient-authority}
                          {:kind :preserve-compiler-facts}
                          {:kind :record-bootstrap-lineage}]})
         stage1-bootstrap-diagnostic-ids)
   :status :complete})

(defn stage1-bootstrap-validate-source-set!
  [source-root module-records]
  (let [components (set (map :component module-records))
        documents (set (mapcat :documents module-records))]
    (when-not (set/subset? stage1-bootstrap-required-components components)
      (stage1-bootstrap-fail! "STAGE1006" source-root components
                              {:missing-fields [:components]
                               :missing-fact
                               (vec (sort (set/difference
                                            stage1-bootstrap-required-components
                                            components)))}))
    (when-not (set/subset? (set stage1-bootstrap-documents) documents)
      (stage1-bootstrap-fail! "STAGE1006" source-root documents
                              {:missing-fields [:documents]
                               :missing-documents
                               (vec (sort (set/difference
                                            (set stage1-bootstrap-documents)
                                            documents)))})))
  :complete)

(defn stage1-bootstrap-proof
  [artifact]
  (let [modules (:modules artifact)
        components (set (map :component modules))
        documents (set (mapcat :documents modules))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:stage1-diagnostic-stream
                                       :diagnostics])))]
    {:gravity-authored-source?
     (every? #(= :gravity (:source-language %)) modules)
     :clojure-seed-boundary-explicit?
     (= :clojure-stage0 (get-in artifact [:seed-boundary :verified-by]))
     :component-coverage?
     (set/subset? stage1-bootstrap-required-components components)
     :ambient-authority-denied?
     (every? #(and (empty? (:effects %))
                   (empty? (:capabilities %)))
             modules)
     :lineage-covered?
     (every? #(= :clojure-stage0 (get-in % [:lineage :verified-by]))
             modules)
     :preserved-facts-covered?
     (every? #(set/subset? stage1-bootstrap-required-preserved-facts
                           (set (:preserves %)))
             modules)
     :documents-covered?
     (set/subset? (set stage1-bootstrap-documents) documents)
     :accepted-fixtures-covered?
     (seq (:accepted-stage1-bootstrap-source-fixtures artifact))
     :rejected-fixtures-covered?
     (= (set stage1-bootstrap-diagnostic-ids) diagnostics)
     :limitations
     {:self-hosted-compiler-complete? false
      :clojure-seed-retired? false
      :production-release? false
      :next-required-capability
      :execute-gravity-authored-reader-without-clojure-compiler-logic}
     :status :complete}))

(defn stage1-bootstrap-source-artifact
  [source-root]
  (let [source-files (stage1-bootstrap-source-files source-root)
        module-records (mapv stage1-bootstrap-module-record source-files)
        _ (stage1-bootstrap-validate-source-set! source-root module-records)
        source-set-id (str "sha256:"
                           (sha256-hex
                            (str/join "\n"
                                      (map #(str (:source-path %)
                                                 ":"
                                                 (:source-hash %))
                                           module-records))))
        artifact-base
        {:kind :gravity/stage1-bootstrap-source-artifact
         :phase "15"
         :task "P15-STAGE1-SOURCE"
         :stage :stage1-bootstrap-source
         :source-root source-root
         :source-files source-files
         :source-set-id source-set-id
         :document-set stage1-bootstrap-documents
         :governing-documents stage1-bootstrap-governing-documents
         :seed-boundary
         {:seed-language :clojure
          :verified-by :clojure-stage0
          :role :trusted-seed-verifier
          :retirement-objective :replace-clojure-seed
          :still-trusted? true}
         :pass {:name :stage1-bootstrap-source
                :input :gravity-source-set
                :output :stage1-bootstrap-source-artifact
                :requires [:gravity-owned-source :stage-lineage
                           :ambient-authority-denial
                           :preserved-compiler-facts
                           :component-coverage]
                :preserves [:source-hash :source-spans :syntax-identity
                            :diagnostic-code :artifact-provenance
                            :stage-lineage]
                :emits [:modules :accepted-stage1-bootstrap-source-fixtures
                        :rejected-stage1-bootstrap-source-fixtures
                        :stage1-diagnostic-stream]
                :rejects stage1-bootstrap-diagnostic-ids}
         :modules module-records
         :accepted-stage1-bootstrap-source-fixtures
         [{:fixture "bootstrap/gravity/src"
           :components (vec (sort stage1-bootstrap-required-components))
           :status :accepted}]
         :rejected-stage1-bootstrap-source-fixtures
         stage1-bootstrap-rejected-fixture-records
         :stage1-diagnostic-stream
         (stage1-bootstrap-diagnostic-stream source-root source-set-id)
         :stage1-bootstrap-source-results
         {:module-count (count module-records)
          :component-count (count stage1-bootstrap-required-components)
          :accepted-fixtures 1
          :rejected-fixtures (count stage1-bootstrap-rejected-fixture-records)
          :diagnostic-count (count stage1-bootstrap-diagnostic-ids)
          :status :complete}
         :diagnostics []}
        capability-proof (stage1-bootstrap-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn stage1-bootstrap-source-file-artifact
  [path]
  (stage1-bootstrap-source-artifact path))

(def stage1-reader-source-path
  "bootstrap/gravity/src/gravity/bootstrap/reader.gravity")

(def stage1-reader-bootstrap-source-root
  "bootstrap/gravity/src")

(def stage1-reader-execution-diagnostic-messages
  {"STAGE1READER001" "stage1 reader table rejected an unexpected close delimiter"
   "STAGE1READER002" "stage1 reader table rejected an unclosed delimited form"
   "STAGE1READER003" "stage1 reader table rejected an unclosed string"
   "STAGE1READER004" "stage1 reader table rejected unsupported dispatch syntax"
   "STAGE1READER005" "stage1 reader table rejected a map with an odd entry count"
   "STAGE1READER006" "stage1 reader table is missing or malformed"
   "STAGE1READER007" "stage1 reader rejected a malformed numeric lexeme"})

(def stage1-reader-execution-diagnostic-ids
  ["STAGE1READER001" "STAGE1READER002" "STAGE1READER003"
   "STAGE1READER004" "STAGE1READER005" "STAGE1READER006"])

(def stage1-reader-execution-rejected-fixture-records
  [{:fixture "bootstrap/clojure/fixtures/rejected/stage1-reader-unexpected-close.gravity"
    :diagnostic "STAGE1READER001"
    :rejected-behavior :unexpected-close-delimiter}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-list.gravity"
    :diagnostic "STAGE1READER002"
    :rejected-behavior :unclosed-delimited-form}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-string.gravity"
    :diagnostic "STAGE1READER003"
    :rejected-behavior :unclosed-string}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-reader-unsupported-dispatch.gravity"
    :diagnostic "STAGE1READER004"
    :rejected-behavior :unsupported-dispatch}
   {:fixture "bootstrap/clojure/fixtures/rejected/stage1-reader-odd-map.gravity"
    :diagnostic "STAGE1READER005"
    :rejected-behavior :odd-map-entries}])

(defn stage1-reader-fail!
  [id source-path value data]
  (fail! id
         (get stage1-reader-execution-diagnostic-messages
              id
              "stage1 reader execution failed")
         (merge {:source-span {:source source-path}
                 :stage :stage1-reader-execution
                 :diagnostic-family :stage1-reader-execution
                 :value value
                 :remediation "Keep the reader table in Gravity source, use supported stage1 reader syntax, and preserve source spans and diagnostics."}
                data)))

(defn stage1-reader-classpath-project-root
  []
  (when-let [resource (io/resource "gravity/bootstrap.clj")]
    (when (= "file" (.getProtocol resource))
      (loop [candidate (.getParentFile (.getCanonicalFile (io/file resource)))]
        (when candidate
          (if (.isFile (io/file candidate "deps.edn"))
            candidate
            (recur (.getParentFile candidate))))))))

(defn stage1-reader-owned-source-file
  [logical-path]
  (let [classpath-root (stage1-reader-classpath-project-root)
        candidates (if classpath-root
                     [(io/file classpath-root logical-path)]
                     [(io/file logical-path)])]
    (or (some #(when (.isFile %) (.getCanonicalFile %)) candidates)
        (stage1-reader-fail!
         "STAGE1READER006" logical-path nil
         {:missing-fields [:owned-reader-source]
          :facts {:logical-path logical-path
                  :resolution-bases
                  (if classpath-root
                    [:bootstrap-classpath-root]
                    [:process-working-directory-fallback])}}))))

(defn stage1-reader-table-form
  [source-path]
  (let [source-file (stage1-reader-owned-source-file source-path)
        forms (mapv :form (read-source-form-records source-path
                                                     (slurp source-file)))
        table-form (first (filter #(and (seq? %)
                                        (= 'def (first %))
                                        (= 'stage1-reader-table (second %)))
                                  forms))]
    (when-not (and table-form (= 3 (count table-form)) (map? (nth table-form 2)))
      (stage1-reader-fail! "STAGE1READER006" source-path table-form
                           {:missing-fields [:stage1-reader-table]}))
    (nth table-form 2)))

(defn stage1-reader-validate-table!
  [source-path table]
  (let [diagnostics (:diagnostics table)
        missing (remove #(contains? diagnostics %)
                        [:unexpected-close :unclosed-form :unclosed-string
                         :unsupported-dispatch :odd-map :missing-table])]
    (when-not (= :gravity-reader-table-v1 (:engine table))
      (stage1-reader-fail! "STAGE1READER006" source-path table
                           {:missing-fields [:engine]}))
    (doseq [field [:line-comment :string-delimiter :whitespace :delimiters
                   :dispatch :literal-kinds :diagnostics
                   :accepted-fixture :rejected-fixtures]]
      (when-not (contains? table field)
        (stage1-reader-fail! "STAGE1READER006" source-path table
                             {:missing-fields [field]})))
    (when (seq missing)
      (stage1-reader-fail! "STAGE1READER006" source-path diagnostics
                           {:missing-fields (vec missing)})))
  :complete)

(defn stage1-reader-location
  [source-text line-starts idx]
  (let [idx (min idx (count source-text))
        line-number (loop [line 0]
                      (if (and (< (inc line) (count line-starts))
                               (<= (line-starts (inc line)) idx))
                        (recur (inc line))
                        (inc line)))
        line-start (line-starts (dec line-number))
        line-prefix (subs source-text line-start idx)
        column (inc (.codePointCount line-prefix 0 (.length line-prefix)))]
    {:line line-number
     :column column
     :column-unit :unicode-scalar
     :char idx
     :byte (utf8-byte-count (subs source-text 0 idx))}))

(defn stage1-reader-span
  [source-path source-text line-starts start end]
  (let [start-location (stage1-reader-location source-text line-starts start)
        end-location (stage1-reader-location source-text line-starts end)]
    {:source source-path
     :start start-location
     :end end-location
     :byte-start (:byte start-location)
     :byte-end (:byte end-location)}))

(defn stage1-reader-table
  []
  (let [table (stage1-reader-table-form stage1-reader-source-path)]
    (stage1-reader-validate-table! stage1-reader-source-path table)
    table))

(defn stage1-reader-token-kind
  [token]
  (cond
    (= token "nil") :nil
    (= token "true") :boolean
    (= token "false") :boolean
    (str/starts-with? token ":") :keyword
    (re-matches #"[+-]?(?:0[xX][0-9A-Fa-f]+|0[bB][01]+|[0-9]+)" token)
    :integer
    (re-matches #"[+-]?[0-9]+/[0-9]+" token) :ratio
    (re-matches #"[+-]?(?:(?:(?:[0-9]+\.[0-9]*)|(?:[0-9]*\.[0-9]+))(?:[eE][+-]?[0-9]+)?|(?:[0-9]+[eE][+-]?[0-9]+))"
                token)
    :decimal
    (re-find #"^[+-]?[0-9]" token) :malformed-number
    :else :symbol))

(defn stage1-reader-malformed-numeric!
  [source-path raw span token-id cause]
  (stage1-reader-fail!
   "STAGE1READER007" source-path raw
   {:source-span span
    :token-id token-id
    :raw raw
    :cause-message cause
    :facts {:literal-kind :numeric
            :raw-spelling raw
            :normative-c2-mapping :unassigned
            :catalog-gap true}}))

(defn stage1-reader-decode-atom
  [source-path kind raw span token-id]
  (try
    (case kind
      :nil nil
      :boolean (= "true" raw)
      :keyword (keyword (subs raw 1))
      :integer
      (let [negative? (str/starts-with? raw "-")
            positive? (str/starts-with? raw "+")
            unsigned (if (or negative? positive?) (subs raw 1) raw)
            [radix digits] (cond
                             (re-find #"^0[xX]" unsigned)
                             [16 (subs unsigned 2)]
                             (re-find #"^0[bB]" unsigned)
                             [2 (subs unsigned 2)]
                             :else [10 unsigned])
            value (bigint (java.math.BigInteger. digits radix))]
        (if negative? (- value) value))
      :ratio
      (let [[numerator-spelling denominator-spelling] (str/split raw #"/" 2)
            numerator (bigint numerator-spelling)
            denominator (bigint denominator-spelling)]
        (if (zero? denominator)
          {:artifact :gravity/deferred-ratio-literal
           :kind :ratio
           :raw raw
           :numerator-spelling numerator-spelling
           :denominator-spelling denominator-spelling
           :numerator numerator
           :denominator denominator
           :semantic-validation :deferred
           :reason :zero-denominator}
          (/ numerator denominator)))
      :decimal (Double/parseDouble raw)
      :malformed-number
      (stage1-reader-malformed-numeric!
       source-path raw span token-id
       "numeric lexeme does not match a declared Gravity numeric shape")
      :symbol (symbol raw)
      raw)
    (catch NumberFormatException ex
      (stage1-reader-malformed-numeric! source-path raw span token-id
                                        (.getMessage ex)))
    (catch ArithmeticException ex
      (stage1-reader-malformed-numeric! source-path raw span token-id
                                        (.getMessage ex)))))

(defn stage1-reader-decode-string
  [source-path raw span token-id]
  (try
    (binding [*read-eval* false]
      (read-string raw))
    (catch Exception ex
      (stage1-reader-fail! "STAGE1READER003" source-path raw
                           {:source-span span
                            :token-id token-id
                            :raw raw
                            :cause-message (.getMessage ex)}))))

(defn stage1-reader-decode-character
  [source-path raw span token-id]
  (try
    (let [value (binding [*read-eval* false]
                  (read-string raw))]
      (when-not (char? value)
        (throw (ex-info "reader character token did not decode to a character"
                        {:raw raw})))
      value)
    (catch Exception ex
      (stage1-reader-fail! "STAGE1READER003" source-path raw
                           {:source-span span
                            :token-id token-id
                            :raw raw
                            :cause-message (.getMessage ex)}))))

(defn stage1-reader-token-stream
  ([source-path source-text table]
   (stage1-reader-token-stream source-path source-text table
                               {:retain-comments false}))
  ([source-path source-text table reader-options]
  (let [line-starts (line-start-indices source-text)
        whitespace (set (:whitespace table))
        delimiters (:delimiters table)
        dispatch (:dispatch table)
        comment-marker (:line-comment table)
        string-delimiter (:string-delimiter table)
        retain-trivia? (true? (:retain-comments reader-options))
        source-length (count source-text)
        table-id (str "sha256:" (sha256-hex (pr-str table)))]
    (letfn [(char-string [idx]
              (str (.charAt source-text idx)))
            (ignored? [idx]
              (and (< idx source-length)
                   (contains? whitespace (char-string idx))))
            (comment? [idx]
              (and (< idx source-length)
                   (= comment-marker (char-string idx))))
            (skip-ignored [idx]
              (loop [idx idx]
                (cond
                  (>= idx source-length) idx
                  (ignored? idx) (recur (inc idx))
                  (comment? idx) (recur (loop [j idx]
                                          (if (and (< j source-length)
                                                   (not (line-terminator-char?
                                                         (.charAt source-text j))))
                                            (recur (inc j))
                                            j)))
                  :else idx)))
            (read-whitespace-token [idx token-index]
              (let [end (loop [end idx]
                          (if (and (< end source-length) (ignored? end))
                            (recur (inc end))
                            end))
                    raw (subs source-text idx end)]
                [{:index token-index
                  :kind :whitespace
                  :lexeme raw
                  :raw raw
                  :decoded nil
                  :trivia? true
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx end)}
                 end]))
            (read-comment-token [idx token-index]
              (let [end (loop [end idx]
                          (if (and (< end source-length)
                                   (not (line-terminator-char?
                                         (.charAt source-text end))))
                            (recur (inc end))
                            end))
                    raw (subs source-text idx end)]
                [{:index token-index
                  :kind :comment
                  :lexeme raw
                  :raw raw
                  :decoded nil
                  :trivia? true
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx end)}
                 end]))
            (read-string-token [idx token-index]
              (let [start idx]
                (loop [idx (inc idx)]
                  (cond
                    (>= idx source-length)
                    (stage1-reader-fail! "STAGE1READER003" source-path nil
                                         {:source-span
                                          (stage1-reader-span source-path
                                                              source-text
                                                              line-starts
                                                              start idx)
                                          :token-id
                                          (keyword (str "tok-" token-index))
                                          :raw (subs source-text start idx)})

                    (= string-delimiter (char-string idx))
                    (let [end (inc idx)
                          raw (subs source-text start end)
                          span (stage1-reader-span source-path source-text
                                                  line-starts start end)
                          decoded (stage1-reader-decode-string source-path
                                                               raw span
                                                               (keyword
                                                                (str "tok-"
                                                                     token-index)))]
                      [{:index token-index
                        :kind :string
                        :lexeme decoded
                        :raw raw
                        :decoded decoded
                        :span span}
                       end])

                    (= \\ (.charAt source-text idx))
                    (if (< (inc idx) source-length)
                      (recur (+ idx 2))
                      (stage1-reader-fail! "STAGE1READER003" source-path nil
                                           {:source-span
                                            (stage1-reader-span source-path
                                                                source-text
                                                                line-starts
                                                                start idx)
                                            :token-id
                                            (keyword (str "tok-" token-index))
                                            :raw (subs source-text start idx)}))
                    :else (recur (inc idx))))))
            (atom-end [idx]
              (loop [idx idx]
                (if (or (>= idx source-length)
                        (ignored? idx)
                        (comment? idx)
                        (= string-delimiter (char-string idx))
                        (contains? #{"'" "`" "~" "^" "@" "\\"}
                                   (char-string idx))
                        (contains? delimiters (char-string idx))
                        (contains? dispatch (char-string idx)))
                  idx
                  (recur (inc idx)))))
            (read-atom-token [idx token-index]
              (let [start idx
                    end (atom-end idx)
                    token (subs source-text start end)
                    kind (stage1-reader-token-kind token)
                    token-id (keyword (str "tok-" token-index))
                    span (stage1-reader-span source-path source-text
                                             line-starts start end)]
                [{:index token-index
                  :kind kind
                  :lexeme token
                  :raw token
                  :decoded (stage1-reader-decode-atom source-path kind token
                                                      span token-id)
                  :span span}
                 end]))
            (read-character-token [idx token-index]
              (let [word-start (inc idx)
                    end (cond
                          (>= word-start source-length) word-start
                          (or (ignored? word-start)
                              (comment? word-start)) word-start
                          (contains? delimiters (char-string word-start))
                          (inc word-start)
                          :else (atom-end word-start))
                    raw (subs source-text idx end)
                    span (stage1-reader-span source-path source-text
                                             line-starts idx end)
                    decoded (stage1-reader-decode-character source-path
                                                             raw span
                                                             (keyword
                                                              (str "tok-"
                                                                   token-index)))]
                [{:index token-index
                  :kind :character
                  :lexeme decoded
                  :raw raw
                  :decoded decoded
                  :span span}
                 end]))
            (read-abbreviation-token [idx token-index]
              (let [splice? (and (= "~" (char-string idx))
                                 (< (inc idx) source-length)
                                 (= "@" (char-string (inc idx))))
                    end (+ idx (if splice? 2 1))
                    raw (subs source-text idx end)
                    abbrev (case raw
                             "'" :quote
                             "`" :syntax-quote
                             "~" :unquote
                             "~@" :splice-unquote
                             "^" :metadata
                             "@" :deref)]
                [{:index token-index
                  :kind :abbreviation
                  :abbrev abbrev
                  :lexeme raw
                  :raw raw
                  :decoded abbrev
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx end)}
                 end]))
            (read-dispatch-token [idx token-index]
              (let [dispatch-token (char-string idx)
                    next-token (when (< (inc idx) source-length)
                                 (char-string (inc idx)))
                    dispatch-entry (get-in dispatch [dispatch-token next-token])]
                (if (= :set-open (:kind dispatch-entry))
                  (let [end (+ idx 2)]
                    [{:index token-index
                      :kind (:kind dispatch-entry)
                      :lexeme (str dispatch-token next-token)
                      :raw (str dispatch-token next-token)
                      :decoded :set
                      :dispatch dispatch-token
                      :close-token (:closes dispatch-entry)
                      :span (stage1-reader-span source-path source-text
                                                line-starts idx end)}
                     end])
                  (let [end (atom-end (inc idx))
                        raw (subs source-text idx end)
                        tag (subs raw 1)]
                    (if (contains? #{"inst" "uuid"} tag)
                      [{:index token-index
                        :kind :tag
                        :tag (symbol tag)
                        :lexeme raw
                        :raw raw
                        :decoded (symbol tag)
                        :span (stage1-reader-span source-path source-text
                                                  line-starts idx end)}
                       end]
                      (stage1-reader-fail!
                       "STAGE1READER004" source-path dispatch-token
                       {:source-span
                        (stage1-reader-span source-path source-text
                                            line-starts idx
                                            (min source-length
                                                 (max (inc idx) end)))
                        :token-id (keyword (str "tok-" token-index))
                        :raw raw
                        :extension-tag (when (seq tag) (symbol tag))}))))))
            (read-delimiter-token [idx token-index delimiter]
              (let [token (char-string idx)]
                [{:index token-index
                  :kind (:kind delimiter)
                  :lexeme token
                  :raw token
                  :decoded token
                  :close-token (:closes delimiter)
                  :span (stage1-reader-span source-path source-text
                                            line-starts idx (inc idx))}
                 (inc idx)]))]
      (loop [idx 0
             token-index 0
             tokens []]
        (let [idx (if retain-trivia? idx (skip-ignored idx))]
          (if (>= idx source-length)
            {:kind :gravity/stage1-reader-token-stream
             :source-path source-path
             :source-id (str "sha256:" (sha256-hex source-text))
             :reader-table-id table-id
             :token-count (count tokens)
             :tokens tokens
             :status :complete}
            (let [token (char-string idx)
                  delimiter (get delimiters token)
                  [token-record next-idx]
                  (cond
                    (and retain-trivia? (ignored? idx))
                    (read-whitespace-token idx token-index)

                    (and retain-trivia? (comment? idx))
                    (read-comment-token idx token-index)

                    (= string-delimiter token)
                    (read-string-token idx token-index)

                    (= "\\" token)
                    (read-character-token idx token-index)

                    (contains? #{"'" "`" "~" "^" "@"} token)
                    (read-abbreviation-token idx token-index)

                    (contains? dispatch token)
                    (read-dispatch-token idx token-index)

                    delimiter
                    (read-delimiter-token idx token-index delimiter)

                    :else
                    (read-atom-token idx token-index))]
              (recur next-idx
                     (inc token-index)
                     (conj tokens token-record))))))))))

(declare stage1-reader-character-pipeline-fail!
         stage1-reader-token-classifier-pipeline-fail!
         stage1-reader-token-realizer-pipeline-fail!
         stage1-reader-token-automaton-pipeline-fail!
         stage1-reader-form-builder-pipeline-fail!
         stage1-reader-executor-pipeline-fail!
         stage1-reader-runtime-pipeline-fail!
         stage1-reader-compiled-pipeline-fail!
         stage1-reader-binary-pipeline-fail!
         stage1-reader-self-hosted-runtime-fail!
         stage1-reader-core-bootstrap-fail!
         stage1-reader-compiler-driver-fail!
         stage1-reader-runtime-entrypoint-fail!
         stage1-reader-runtime-image-fail!
         stage1-reader-verified-boot-chain-fail!
         stage1-reader-diverse-bootstrap-verification-fail!
         stage1-reader-release-attestation-seed-retirement-fail!
         stage1-reader-pipeline-fail!
         reader-canonical-hash
         ^:dynamic *stage1-reader-pipeline-trace*)

(defn stage1-reader-character-stream
  [source-path source-text]
  (let [line-starts (line-start-indices source-text)
        source-id (str "sha256:" (sha256-hex source-text))
        source-length (count source-text)
        characters
        (loop [char-offset 0
               scalar-index 0
               records []]
          (if (>= char-offset source-length)
            records
            (let [codepoint (.codePointAt source-text char-offset)
                  char-width (Character/charCount codepoint)
                  end-offset (+ char-offset char-width)
                  raw (subs source-text char-offset end-offset)]
              (recur end-offset
                     (inc scalar-index)
                     (conj records
                           {:index scalar-index
                            :char raw
                            :raw raw
                            :codepoint codepoint
                            :span (stage1-reader-span
                                   source-path source-text line-starts
                                   char-offset end-offset)})))))]
    {:kind :gravity/stage1-reader-character-stream
     :source-path source-path
     :source-id source-id
     :character-count (count characters)
     :utf16-unit-count source-length
     :characters characters
     :status :complete}))

(defn stage1-reader-token-stream-from-characters
  [source-path source-text table character-stream]
  (let [source-id (str "sha256:" (sha256-hex source-text))
        characters (:characters character-stream)]
    (when-not (= :gravity/stage1-reader-character-stream
                 (:kind character-stream))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path character-stream))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields [:source-path]}))
    (when-not (= source-id (:source-id character-stream))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields [:source-id]}))
    (when-not (and (vector? characters)
                   (= (count characters)
                      (:character-count character-stream)))
      (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                              character-stream
                                              {:missing-fields
                                               [:characters
                                                :character-count]}))
    (let [source-from-characters (apply str (map :char characters))]
      (when-not (= source-text source-from-characters)
        (stage1-reader-character-pipeline-fail! "STAGE1CHAR004" source-path
                                                character-stream
                                                {:missing-fields
                                                 [:source-character-parity]}))
      (stage1-reader-token-stream source-path source-from-characters table))))

(defn stage1-reader-table-from-token-classifier
  [source-path classifier]
  (let [diagnostics (:diagnostics classifier)
        missing (remove #(contains? diagnostics %)
                        [:unexpected-close :unclosed-form :unclosed-string
                         :unsupported-dispatch :odd-map
                         :invalid-classifier])]
    (when-not (= :gravity-reader-token-classifier-v1 (:engine classifier))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path classifier
       {:missing-fields [:engine]}))
    (doseq [field [:derived-from :whitespace :line-comment :string-delimiter
                   :delimiters :dispatch :literal-kinds :diagnostics
                   :provenance]]
      (when-not (contains? classifier field)
        (stage1-reader-token-classifier-pipeline-fail!
         "STAGE1CLASS004" source-path classifier
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-table (:derived-from classifier))
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path classifier
       {:missing-fields [:derived-from]}))
    (when (seq missing)
      (stage1-reader-token-classifier-pipeline-fail!
       "STAGE1CLASS004" source-path diagnostics
       {:missing-fields (vec missing)}))
    {:engine :gravity-reader-table-v1
     :line-comment (:line-comment classifier)
     :string-delimiter (:string-delimiter classifier)
     :whitespace (:whitespace classifier)
     :delimiters (:delimiters classifier)
     :dispatch (:dispatch classifier)
     :literal-kinds (:literal-kinds classifier)
     :diagnostics (assoc (select-keys diagnostics
                                      [:unexpected-close :unclosed-form
                                       :unclosed-string :unsupported-dispatch
                                       :odd-map])
                         :missing-table "STAGE1READER006")
     :accepted-fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
     :rejected-fixtures {"bootstrap/clojure/fixtures/rejected/stage1-reader-unexpected-close.gravity"
                         "STAGE1READER001"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-list.gravity"
                         "STAGE1READER002"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unclosed-string.gravity"
                         "STAGE1READER003"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-unsupported-dispatch.gravity"
                         "STAGE1READER004"
                         "bootstrap/clojure/fixtures/rejected/stage1-reader-odd-map.gravity"
                         "STAGE1READER005"}}))

