(defn stage1-reader-products-from-token-stream
  [source-path source-text table token-stream]
  (let [expected-source-id (str "sha256:" (sha256-hex source-text))
        expected-table-id (str "sha256:" (sha256-hex (pr-str table)))
        tokens (:tokens token-stream)]
    (when-not (= :gravity/stage1-reader-token-stream (:kind token-stream))
      (stage1-reader-pipeline-fail! "STAGE1PIPE004" source-path token-stream
                                    {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path token-stream))
      (stage1-reader-pipeline-fail! "STAGE1PIPE004" source-path token-stream
                                    {:missing-fields [:source-path]}))
    (when-not (= expected-source-id (:source-id token-stream))
      (stage1-reader-pipeline-fail! "STAGE1PIPE004" source-path token-stream
                                    {:missing-fields [:source-id]}))
    (when-not (= expected-table-id (:reader-table-id token-stream))
      (stage1-reader-pipeline-fail! "STAGE1PIPE004" source-path token-stream
                                    {:missing-fields [:reader-table-id]}))
    (when-not (and (vector? tokens)
                   (= (count tokens) (:token-count token-stream)))
      (stage1-reader-pipeline-fail! "STAGE1PIPE004" source-path token-stream
                                    {:missing-fields [:tokens
                                                      :token-count]}))
    (let [line-starts (line-start-indices source-text)
          token-count (count tokens)
          nodes (atom {})
          form-order (atom [])
          next-form-index (atom 0)]
      (letfn [(token-id [token]
                (or (:token-id token)
                    (keyword (str "tok-" (:index token)))))
              (new-form-id []
                (let [idx (swap! next-form-index inc)
                      id (keyword (str "form-" (dec idx)))]
                  (swap! form-order conj id)
                  id))
              (combined-span [start-token end-token]
                (stage1-reader-span source-path
                                    source-text
                                    line-starts
                                    (get-in start-token [:span :start :char])
                                    (get-in end-token [:span :end :char])))
              (trivia-token? [token]
                (true? (:trivia? token)))
              (skip-trivia [idx]
                (loop [idx idx
                       trivia []]
                  (if (and (< idx token-count)
                           (trivia-token? (tokens idx)))
                    (recur (inc idx) (conj trivia (token-id (tokens idx))))
                    [idx trivia])))
              (trivia-hash [ids]
                (let [by-id (into {} (map (juxt token-id identity) tokens))]
                  (reader-canonical-hash
                   (mapv (fn [id]
                           (let [token (by-id id)]
                             {:kind (:kind token)
                              :raw (:raw token)
                              :span (dissoc (:span token) :source :file)}))
                         ids))))
              (parse-token-literal [token]
                (if (contains? token :decoded)
                  (:decoded token)
                  (stage1-reader-decode-atom
                   source-path (:kind token) (:lexeme token) (:span token)
                   (token-id token))))
              (literal-set-key? [node]
                (or (contains? #{:nil :boolean :integer :ratio :decimal
                                 :string :character :symbol :keyword
                                 :tagged-literal}
                               (:kind node))
                    (and (contains? #{:list :vector :map :set
                                     :abbreviation :metadata-wrapper}
                                   (:kind node))
                         (every? #(literal-set-key? (@nodes %))
                                 (:children node)))))
              (set-value [child-ids values]
                (loop [pairs (map vector child-ids values)
                       seen {}]
                  (if-let [[child-id value] (first pairs)]
                    (let [node (@nodes child-id)]
                      (if (and (literal-set-key? node)
                               (contains? seen value))
                        (let [first-id (seen value)
                              first-node (@nodes first-id)]
                          (stage1-reader-fail!
                           "C2-SET" source-path value
                           {:source-span (:span node)
                            :token-id (:open-token node)
                            :form-id child-id
                            :raw (:raw node)
                            :related [{:role :first-literal
                                       :span (:span first-node)
                                       :artifact first-id}]
                            :facts {:duplicate-value (pr-str value)
                                    :first-form-id first-id
                                    :duplicate-form-id child-id}}))
                        (recur (rest pairs)
                               (if (literal-set-key? node)
                                 (assoc seen value child-id)
                                 seen))))
                    (set values))))
              (metadata-map [value node]
                (cond
                  (map? value) value
                  (keyword? value) {value true}
                  (or (symbol? value) (string? value)) {:tag value}
                  :else
                  (stage1-reader-fail!
                   "C2-METADATA" source-path value
                   {:source-span (:span node)
                    :token-id (:open-token node)
                    :form-id (:form-id node)
                    :raw (:raw node)
                    :facts {:metadata-kind (:kind node)}})))
              (attach-metadata [metadata target target-node]
                (if (instance? clojure.lang.IObj target)
                  (with-meta target (merge (meta target) metadata))
                  (stage1-reader-fail!
                   "C2-METADATA" source-path target
                   {:source-span (:span target-node)
                    :token-id (:open-token target-node)
                    :form-id (:form-id target-node)
                    :raw (:raw target-node)
                    :facts {:target-kind (:kind target-node)}})))
              (read-delimited [idx collection-kind close-token open-token
                               leading-trivia form-id]
                (loop [idx idx
                       child-ids []
                       values []]
                  (let [[idx between-trivia] (skip-trivia idx)]
                    (if (>= idx token-count)
                      (let [eof-span (stage1-reader-span
                                      source-path source-text line-starts
                                      (count source-text) (count source-text))]
                        (stage1-reader-fail!
                         "STAGE1READER002" source-path nil
                         {:source-span eof-span
                          :token-id (token-id open-token)
                          :form-id form-id
                          :raw (:raw open-token)
                          :expected close-token
                          :facts {:expected-delimiter close-token
                                  :open-token (token-id open-token)}}))
                      (let [token (tokens idx)]
                        (cond
                          (and (= :close (:kind token))
                               (= close-token (:lexeme token)))
                          (let [span (combined-span open-token token)
                                value (case collection-kind
                                        :list (apply list values)
                                        :vector (vec values)
                                        :set (set-value child-ids values)
                                        :map (do
                                               (when (odd? (count values))
                                                 (stage1-reader-fail!
                                                  "STAGE1READER005"
                                                  source-path values
                                                  {:source-span span
                                                   :token-id (token-id token)
                                                   :form-id form-id
                                                   :raw (:raw token)
                                                   :facts
                                                   {:entry-count (count values)}}))
                                               (apply hash-map values)))
                                node {:form-id form-id
                                      :kind collection-kind
                                      :collection-kind collection-kind
                                      :open-token (token-id open-token)
                                      :close-token (token-id token)
                                      :children child-ids
                                      :span span
                                      :metadata {}
                                      :origin {:kind :source
                                               :reader :stage1-token-parser}
                                      :leading-trivia-token-ids leading-trivia
                                      :leading-trivia-hash
                                      (trivia-hash leading-trivia)
                                      :trailing-trivia-token-ids between-trivia
                                      :trailing-trivia-hash
                                      (trivia-hash between-trivia)
                                      :raw (subs source-text
                                                 (get-in open-token
                                                         [:span :start :char])
                                                 (get-in token
                                                         [:span :end :char]))
                                      :value value}]
                            (swap! nodes assoc form-id node)
                            [value (inc idx) span form-id])

                          (= :close (:kind token))
                          (stage1-reader-fail!
                           "STAGE1READER001" source-path (:lexeme token)
                           {:source-span (:span token)
                            :token-id (token-id token)
                            :form-id form-id
                            :raw (:raw token)
                            :expected close-token
                            :actual (:lexeme token)
                            :facts {:expected-delimiter close-token
                                    :actual-delimiter (:lexeme token)}})

                          :else
                          (let [[value next-idx _span child-id]
                                (read-form idx between-trivia)]
                            (recur next-idx
                                   (conj child-ids child-id)
                                   (conj values value)))))))))
              (read-abbreviation [idx token leading-trivia form-id]
                (let [abbrev (:abbrev token)
                      [metadata-value metadata-end _ metadata-id]
                      (when (= :metadata abbrev)
                        (let [[child-idx child-trivia] (skip-trivia (inc idx))]
                          (when (>= child-idx token-count)
                            (stage1-reader-fail!
                             "C2-METADATA" source-path abbrev
                             {:source-span (:span token)
                              :token-id (token-id token)
                              :form-id form-id
                              :raw (:raw token)
                              :facts {:abbreviation abbrev}}))
                          (read-form child-idx child-trivia)))
                      next-start (if (= :metadata abbrev)
                                   metadata-end
                                   (inc idx))
                      [child-idx child-trivia] (skip-trivia next-start)]
                  (when (>= child-idx token-count)
                    (stage1-reader-fail!
                     (if (= :metadata abbrev)
                       "C2-METADATA"
                       "C2-ABBREV")
                     source-path abbrev
                     {:source-span (:span token)
                      :token-id (token-id token)
                      :form-id form-id
                      :raw (:raw token)
                      :facts {:abbreviation abbrev}}))
                  (let [[child-value next-idx child-span child-id]
                        (read-form child-idx child-trivia)
                        child-node (@nodes child-id)
                        metadata-node (when metadata-id (@nodes metadata-id))
                        metadata (when metadata-id
                                   (metadata-map metadata-value metadata-node))
                        value (case abbrev
                                :quote (list 'quote child-value)
                                :syntax-quote (list 'syntax-quote child-value)
                                :unquote (list 'unquote child-value)
                                :splice-unquote (list 'splice-unquote
                                                       child-value)
                                :deref (list 'deref child-value)
                                :metadata (attach-metadata metadata child-value
                                                           child-node))
                        span (combined-span token (tokens (dec next-idx)))
                        children (cond-> []
                                   metadata-id (conj metadata-id)
                                   true (conj child-id))
                        node {:form-id form-id
                              :kind (if (= :metadata abbrev)
                                      :metadata-wrapper
                                      :abbreviation)
                              :abbrev abbrev
                              :open-token (token-id token)
                              :close-token (:close-token child-node)
                              :children children
                              :span span
                              :surface-span (:span token)
                              :metadata (or metadata {})
                              :origin {:kind :source
                                       :reader :stage1-token-parser}
                              :generated-origin
                              [{:kind :generated
                                :producer :reader-abbreviation
                                :reason abbrev
                                :from (:span token)
                                :child-form-id child-id}]
                              :leading-trivia-token-ids leading-trivia
                              :leading-trivia-hash (trivia-hash leading-trivia)
                              :raw (subs source-text
                                         (get-in token [:span :start :char])
                                         (get-in child-span [:end :char]))
                              :expanded-form value
                              :value value}]
                    (swap! nodes assoc form-id node)
                    [value next-idx span form-id])))
              (read-form [idx leading-trivia]
                (when (>= idx token-count)
                  (stage1-reader-fail! "STAGE1READER002" source-path nil
                                       {:source-span {:source source-path}
                                        :expected :form}))
                (let [token (tokens idx)
                      form-id (new-form-id)]
                  (case (:kind token)
                    :close
                    (stage1-reader-fail!
                     "STAGE1READER001" source-path (:lexeme token)
                     {:source-span (:span token)
                      :token-id (token-id token)
                      :form-id form-id
                      :raw (:raw token)
                      :actual (:lexeme token)
                      :facts {:actual-delimiter (:lexeme token)}})

                    :list-open
                    (read-delimited (inc idx) :list (:close-token token)
                                    token leading-trivia form-id)

                    :vector-open
                    (read-delimited (inc idx) :vector (:close-token token)
                                    token leading-trivia form-id)

                    :map-open
                    (read-delimited (inc idx) :map (:close-token token)
                                    token leading-trivia form-id)

                    :set-open
                    (read-delimited (inc idx) :set (:close-token token)
                                    token leading-trivia form-id)

                    :abbreviation
                    (read-abbreviation idx token leading-trivia form-id)

                    :tag
                    (let [[child-idx child-trivia] (skip-trivia (inc idx))]
                      (when (>= child-idx token-count)
                        (stage1-reader-fail!
                         "STAGE1READER004" source-path (:raw token)
                         {:source-span (:span token)
                          :token-id (token-id token)
                          :form-id form-id
                          :raw (:raw token)
                          :extension-tag (:tag token)}))
                      (let [[child-value next-idx child-span child-id]
                            (read-form child-idx child-trivia)
                            child-node (@nodes child-id)
                            raw (str (:raw token) " " (pr-str child-value))
                            value (try
                                    (edn/read-string raw)
                                    (catch Exception ex
                                      (stage1-reader-fail!
                                       "STAGE1READER004" source-path raw
                                       {:source-span (:span token)
                                        :token-id (token-id token)
                                        :form-id form-id
                                        :raw raw
                                        :extension-tag (:tag token)
                                        :cause-message (.getMessage ex)})))
                            span (combined-span token (tokens (dec next-idx)))
                            node {:form-id form-id
                                  :kind :tagged-literal
                                  :tag (:tag token)
                                  :open-token (token-id token)
                                  :close-token (:close-token child-node)
                                  :children [child-id]
                                  :span span
                                  :metadata {}
                                  :origin {:kind :source
                                           :reader :stage1-token-parser}
                                  :leading-trivia-token-ids leading-trivia
                                  :leading-trivia-hash
                                  (trivia-hash leading-trivia)
                                  :raw (subs source-text
                                             (get-in token [:span :start :char])
                                             (get-in child-span [:end :char]))
                                  :value value}]
                        (swap! nodes assoc form-id node)
                        [value next-idx span form-id]))

                    (let [value (parse-token-literal token)
                          span (:span token)
                          node {:form-id form-id
                                :kind (:kind token)
                                :open-token (token-id token)
                                :close-token (token-id token)
                                :token-id (token-id token)
                                :children []
                                :span span
                                :metadata {}
                                :origin {:kind :source
                                         :reader :stage1-token-parser}
                                :leading-trivia-token-ids leading-trivia
                                :leading-trivia-hash
                                (trivia-hash leading-trivia)
                                :raw (:raw token)
                                :value value}]
                      (swap! nodes assoc form-id node)
                      [value (inc idx) span form-id]))))]
        (loop [idx 0
               form-index 0
               root-ids []
               records []]
          (let [[idx leading-trivia] (skip-trivia idx)]
            (if (>= idx token-count)
              (let [raw-tree (mapv @nodes @form-order)
                    parent-by-child
                    (reduce (fn [parents parent]
                              (reduce #(assoc %1 %2 (:form-id parent))
                                      parents
                                      (:children parent)))
                            {}
                            raw-tree)
                    form-tree
                    (mapv #(assoc % :parent-form-id
                                  (get parent-by-child (:form-id %)))
                          raw-tree)
                    node-by-id (into {} (map (juxt :form-id identity)
                                             form-tree))
                    records
                    (mapv (fn [record]
                            (assoc record
                                   :kind (:kind (node-by-id (:form-id record)))
                                   :parent-form-id nil))
                          records)]
                {:records records
                 :form-tree form-tree
                 :root-form-ids root-ids
                 :parsed-values (mapv :form records)})
              (let [[form next-idx span form-id]
                    (read-form idx leading-trivia)]
                (recur next-idx
                       (inc form-index)
                       (conj root-ids form-id)
                       (conj records
                             {:form form
                              :kind (form-kind form)
                              :form-id form-id
                              :span (assoc span :form-index form-index)}))))))))))

(defn stage1-reader-records-from-token-stream
  [source-path source-text table token-stream]
  (:records (stage1-reader-products-from-token-stream
             source-path source-text table token-stream)))

(defn stage1-reader-table-from-form-builder
  [source-path classifier realizer automaton form-builder]
  (let [table (stage1-reader-table-from-token-automaton source-path
                                                        classifier
                                                        realizer
                                                        automaton)
        builder-diagnostics (:diagnostics form-builder)
        missing-builder (remove #(contains? builder-diagnostics %)
                                [:unexpected-close :unclosed-form
                                 :unclosed-string :unsupported-dispatch
                                 :odd-map :invalid-form-builder])
        required-collections #{:list :vector :map :set}
        required-operations #{:build-list-form :build-vector-form
                              :build-map-form :build-set-form
                              :build-atom-form :build-string-form
                              :validate-delimiters :validate-map-arity}]
    (when-not (= :gravity-reader-form-builder-v1 (:engine form-builder))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:engine]}))
    (doseq [field [:derived-from :token-automaton-engine
                   :table-derived-from :input :emits
                   :collection-kinds :operations :form-record-fields
                   :preserves :diagnostics :provenance]]
      (when-not (contains? form-builder field)
        (stage1-reader-form-builder-pipeline-fail!
         "STAGE1FORM004" source-path form-builder
         {:missing-fields [field]})))
    (when-not (= :stage1-reader-token-automaton
                 (:derived-from form-builder))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:derived-from]}))
    (when-not (= (:engine automaton)
                 (:token-automaton-engine form-builder))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:token-automaton-engine]}))
    (when-not (= :stage1-reader-table (:table-derived-from form-builder))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:table-derived-from]}))
    (when-not (= :gravity/stage1-reader-token-stream (:input form-builder))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:emits form-builder))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:emits]}))
    (when-not (set/subset? required-collections
                           (set (:collection-kinds form-builder)))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:collection-kinds]}))
    (when-not (set/subset? required-operations
                           (set (:operations form-builder)))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path form-builder
       {:missing-fields [:operations]}))
    (when (seq missing-builder)
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path builder-diagnostics
       {:missing-fields (vec missing-builder)}))
    table))

(defn stage1-reader-records-from-form-builder
  [source-path source-text classifier realizer automaton form-builder
   token-stream]
  (let [expected-source-id (str "sha256:" (sha256-hex source-text))
        table (stage1-reader-table-from-form-builder source-path
                                                     classifier
                                                     realizer
                                                     automaton
                                                     form-builder)
        expected-table-id (str "sha256:" (sha256-hex (pr-str table)))]
    (when-not (= :gravity/stage1-reader-token-stream (:kind token-stream))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path token-stream
       {:missing-fields [:kind]}))
    (when-not (= source-path (:source-path token-stream))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path token-stream
       {:missing-fields [:source-path]}))
    (when-not (= expected-source-id (:source-id token-stream))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path token-stream
       {:missing-fields [:source-id]}))
    (when-not (= expected-table-id (:reader-table-id token-stream))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path token-stream
       {:missing-fields [:reader-table-id]}))
    (when-not (= (:engine automaton)
                 (:token-automaton-engine token-stream))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path token-stream
       {:missing-fields [:token-automaton-engine]}))
    (when-not (and (vector? (:tokens token-stream))
                   (= (count (:tokens token-stream))
                      (:token-count token-stream)))
      (stage1-reader-form-builder-pipeline-fail!
       "STAGE1FORM004" source-path token-stream
       {:missing-fields [:tokens :token-count]}))
    (stage1-reader-records-from-token-stream source-path
                                             source-text
                                             table
                                             token-stream)))

(defn stage1-reader-token-stream-from-executor
  [source-path source-text classifier realizer automaton executor
   character-stream]
  (let [diagnostics (:diagnostics executor)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:unexpected-close :unclosed-form
                                     :unclosed-string :unsupported-dispatch
                                     :invalid-executor])
        required-operations #{:skip-whitespace :skip-line-comment
                              :read-string-token :read-dispatch-token
                              :read-delimiter-token :read-atom-token}]
    (when-not (= :gravity-reader-token-automaton-executor-v1
                 (:engine executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:token-automaton-executor-engine]}))
    (doseq [field [:executes :derived-from :input :emits :operations
                   :preserves :diagnostics :provenance]]
      (when-not (contains? executor field)
        (stage1-reader-executor-pipeline-fail!
         "STAGE1EXEC004" source-path executor
         {:missing-fields [field]})))
    (when-not (= (:engine automaton) (:executes executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:executes]}))
    (when-not (= :stage1-reader-token-automaton (:derived-from executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:derived-from]}))
    (when-not (= :gravity/stage1-reader-character-stream (:input executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-token-stream (:emits executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:emits]}))
    (when-not (set/subset? required-operations (set (:operations executor)))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:operations]}))
    (when (seq missing-diagnostics)
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (let [executor-id (str "sha256:" (sha256-hex (pr-str executor)))
          token-stream (stage1-reader-token-stream-from-automaton
                        source-path source-text classifier realizer automaton
                        character-stream)]
      (assoc token-stream
             :token-automaton-executor-id executor-id
             :token-automaton-executor-engine (:engine executor)
             :gravity-executor :stage1-reader-token-automaton-executor))))

(defn stage1-reader-records-from-executor
  [source-path source-text classifier realizer automaton form-builder
   executor token-stream]
  (let [diagnostics (:diagnostics executor)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:unexpected-close :unclosed-form
                                     :unclosed-string :unsupported-dispatch
                                     :odd-map :invalid-executor])
        required-operations #{:build-list-form :build-vector-form
                              :build-map-form :build-set-form
                              :build-atom-form :build-string-form
                              :validate-delimiters :validate-map-arity}]
    (when-not (= :gravity-reader-form-builder-executor-v1 (:engine executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:form-builder-executor-engine]}))
    (doseq [field [:executes :derived-from :input :emits :operations
                   :preserves :diagnostics :provenance]]
      (when-not (contains? executor field)
        (stage1-reader-executor-pipeline-fail!
         "STAGE1EXEC004" source-path executor
         {:missing-fields [field]})))
    (when-not (= (:engine form-builder) (:executes executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:executes]}))
    (when-not (= :stage1-reader-form-builder (:derived-from executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:derived-from]}))
    (when-not (= :gravity/stage1-reader-token-stream (:input executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:emits executor))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:emits]}))
    (when-not (set/subset? required-operations (set (:operations executor)))
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path executor
       {:missing-fields [:operations]}))
    (when (seq missing-diagnostics)
      (stage1-reader-executor-pipeline-fail!
       "STAGE1EXEC004" source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (mapv #(assoc % :form-builder-executor-engine (:engine executor))
          (stage1-reader-records-from-form-builder
           source-path source-text classifier realizer automaton form-builder
           token-stream))))

(defn stage1-reader-character-stream-from-runtime
  [source-path source-text source-runtime]
  (let [diagnostics (:diagnostics source-runtime)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:invalid-runtime :source-divergence])
        required-generated #{:source-character-stream :source-span-index
                             :source-id}
        required-forbidden #{:filesystem :network :shell :environment
                             :dynamic-eval}
        required-operations #{:decode-source-text :index-source-characters
                              :attach-source-spans :compute-source-id}]
    (when-not (= :gravity-reader-source-runtime-v1 (:engine source-runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:source-runtime-engine]}))
    (doseq [field [:family :input :emits :services :operations
                   :effects :capabilities :preserves :diagnostics
                   :provenance]]
      (when-not (contains? source-runtime field)
        (stage1-reader-runtime-pipeline-fail!
         "STAGE1RUN004" source-path source-runtime
         {:missing-fields [field]})))
    (when-not (= :bootstrap-reader (:family source-runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:family]}))
    (when-not (= :gravity/source-text (:input source-runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-character-stream
                 (:emits source-runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:emits]}))
    (when-not (set/subset? required-generated
                           (set (get-in source-runtime
                                        [:services :generated])))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:services :generated]}))
    (when-not (empty? (get-in source-runtime [:services :delegated]))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:services :delegated]}))
    (when-not (set/subset? required-forbidden
                           (set (get-in source-runtime
                                        [:services :forbidden])))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:services :forbidden]}))
    (when-not (set/subset? required-operations
                           (set (:operations source-runtime)))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path source-runtime
       {:missing-fields [:operations]}))
    (when (seq missing-diagnostics)
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (let [source-runtime-id (str "sha256:"
                                 (sha256-hex (pr-str source-runtime)))
          character-stream (stage1-reader-character-stream source-path
                                                           source-text)]
      (assoc character-stream
             :source-runtime-id source-runtime-id
             :source-runtime-engine (:engine source-runtime)
             :gravity-runtime :stage1-reader-source-runtime))))

(defn stage1-reader-evaluator-runtime-from-definitions
  [reader-source-path definitions]
  (let [runtime-form (:value-form (get definitions
                                       'stage1-reader-evaluator-runtime))
        runtime runtime-form
        diagnostics (:diagnostics runtime)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:missing-entrypoint :unsupported-form
                                     :unsupported-host-primitive
                                     :invalid-runtime :stage0-divergence])
        required-services #{:stage1-reader-source-runtime
                            :stage1-reader-token-automaton-executor
                            :stage1-reader-form-builder-executor}
        required-evaluator-forms #{:let :function-call :def :defn :quote}]
    (when-not (map? runtime)
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:stage1-reader-evaluator-runtime]}))
    (when-not (= :gravity-reader-evaluator-runtime-v1 (:engine runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:evaluator-runtime-engine]}))
    (doseq [field [:family :executes :evaluates :runtime-services
                   :remaining-trusted-implementation :effects
                   :capabilities :preserves :diagnostics :provenance]]
      (when-not (contains? runtime field)
        (stage1-reader-runtime-pipeline-fail!
         "STAGE1RUN004" reader-source-path runtime
         {:missing-fields [field]})))
    (when-not (= :bootstrap-reader (:family runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:family]}))
    (when-not (= :stage1-read-source-runtime-pipeline (:executes runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:executes]}))
    (when-not (set/subset? required-evaluator-forms
                           (set (:evaluates runtime)))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:evaluates]}))
    (when-not (set/subset? required-services
                           (set (:runtime-services runtime)))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:runtime-services]}))
    (when-not (= :clojure-stage0 (:remaining-trusted-implementation runtime))
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path runtime
       {:missing-fields [:remaining-trusted-implementation]}))
    (when (seq missing-diagnostics)
      (stage1-reader-runtime-pipeline-fail!
       "STAGE1RUN004" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc runtime
           :evaluator-runtime-id
           (str "sha256:" (sha256-hex (pr-str runtime))))))

(defn stage1-reader-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-compiled-program-from-definitions
  [reader-source-path definitions]
  (let [program (stage1-reader-literal-definition-value
                 reader-source-path definitions
                 'stage1-reader-compiled-program)
        diagnostics (:diagnostics program)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:missing-entrypoint :unsupported-form
                                     :unsupported-host-primitive
                                     :invalid-program :stage0-divergence])
        required-instructions [:stage1-create-character-stream
                               :stage1-execute-token-automaton
                               :stage1-execute-form-builder]
        required-runtimes #{:stage1-reader-source-runtime}
        required-executors #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
        instructions (:instructions program)]
    (when-not (map? program)
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:stage1-reader-compiled-program]}))
    (when-not (= :gravity-reader-compiled-program-v1 (:engine program))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:engine]}))
    (doseq [field [:entrypoint :compiled-from :input :output
                   :instructions :uses-runtimes :uses-executors
                   :preserves :diagnostics :provenance]]
      (when-not (contains? program field)
        (stage1-reader-compiled-pipeline-fail!
         "STAGE1COMP004" reader-source-path program
         {:missing-fields [field]})))
    (when-not (= :stage1-read-source-compiled-pipeline
                 (:entrypoint program))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:entrypoint]}))
    (when-not (= :stage1-read-source-runtime-pipeline
                 (:compiled-from program))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:compiled-from]}))
    (when-not (= [:source-path :source-text] (:input program))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:output program))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:output]}))
    (when-not (and (vector? instructions)
                   (= required-instructions
                      (mapv :op instructions)))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:instructions]}))
    (when-not (set/subset? required-runtimes
                           (set (:uses-runtimes program)))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? required-executors
                           (set (:uses-executors program)))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path program
       {:missing-fields [:uses-executors]}))
    (when (seq missing-diagnostics)
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc program
           :compiled-program-id
           (str "sha256:" (sha256-hex (pr-str program))))))

(defn stage1-reader-compiled-entrypoint-valid?
  [definitions]
  (let [definition (get definitions stage1-reader-compiled-pipeline-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-compiled-program
               source-path
               source-text
               stage1-reader-compiled-program))
            (:body definition)))))

(defn stage1-reader-compiled-ref
  [reader-source-path definitions env ref]
  (cond
    (contains? env ref) (get env ref)
    (keyword? ref)
    (stage1-reader-literal-definition-value
     reader-source-path
     definitions
     (symbol (name ref)))
    :else
    (stage1-reader-compiled-pipeline-fail!
     "STAGE1COMP004" reader-source-path ref
     {:missing-fields [:compiled-program-ref]})))

(defn stage1-reader-execute-compiled-program
  [reader-source-path definitions source-path source-text compiled-program]
  (loop [env {:source-path source-path
              :source-text source-text}
         instructions (:instructions compiled-program)]
    (if (empty? instructions)
      (let [records (:forms env)]
        (when-not (vector? records)
          (stage1-reader-compiled-pipeline-fail!
           "STAGE1COMP004" source-path env
           {:missing-fields [:forms]}))
        records)
      (let [instruction (first instructions)]
        (case (:op instruction)
          :stage1-create-character-stream
          (let [source-runtime (stage1-reader-compiled-ref
                                reader-source-path definitions env
                                (:runtime instruction))
                character-stream
                (stage1-reader-character-stream-from-runtime
                 source-path source-text source-runtime)]
            (when *stage1-reader-pipeline-trace*
              (swap! *stage1-reader-pipeline-trace*
                     (fn [trace]
                       (-> (or trace {})
                           (update :gravity-runtimes (fnil conj [])
                                   :stage1-reader-source-runtime)
                           (assoc :compiled-program compiled-program)
                           (assoc :source-runtime source-runtime)
                           (assoc :character-stream character-stream)
                           (assoc :source-runtime-created
                                  {:character-count
                                   (:character-count character-stream)
                                   :source-runtime-engine
                                   (:source-runtime-engine
                                    character-stream)})))))
            (recur (assoc env (:label instruction) character-stream)
                   (rest instructions)))

          :stage1-execute-token-automaton
          (let [classifier (stage1-reader-compiled-ref
                            reader-source-path definitions env
                            (:classifier instruction))
                realizer (stage1-reader-compiled-ref
                          reader-source-path definitions env
                          (:realizer instruction))
                automaton (stage1-reader-compiled-ref
                           reader-source-path definitions env
                           (:automaton instruction))
                executor (stage1-reader-compiled-ref
                          reader-source-path definitions env
                          (:executor instruction))
                character-stream (stage1-reader-compiled-ref
                                  reader-source-path definitions env
                                  (:character-stream instruction))
                token-stream
                (stage1-reader-token-stream-from-executor
                 source-path source-text classifier realizer automaton
                 executor character-stream)]
            (when *stage1-reader-pipeline-trace*
              (swap! *stage1-reader-pipeline-trace*
                     (fn [trace]
                       (-> (or trace {})
                           (update :gravity-executors (fnil conj [])
                                   :stage1-reader-token-automaton-executor)
                           (assoc :token-classifier classifier)
                           (assoc :token-realizer realizer)
                           (assoc :token-automaton automaton)
                           (assoc :token-automaton-executor executor)
                           (assoc :token-stream token-stream)
                           (assoc :token-automaton-executed
                                  {:character-count
                                   (:character-count character-stream)
                                   :token-count (:token-count token-stream)
                                   :operation-count
                                   (count (:executed-operations
                                           token-stream))})))))
            (recur (assoc env (:label instruction) token-stream)
                   (rest instructions)))

          :stage1-execute-form-builder
          (let [classifier (stage1-reader-compiled-ref
                            reader-source-path definitions env
                            (:classifier instruction))
                realizer (stage1-reader-compiled-ref
                          reader-source-path definitions env
                          (:realizer instruction))
                automaton (stage1-reader-compiled-ref
                           reader-source-path definitions env
                           (:automaton instruction))
                form-builder (stage1-reader-compiled-ref
                              reader-source-path definitions env
                              (:form-builder instruction))
                executor (stage1-reader-compiled-ref
                          reader-source-path definitions env
                          (:executor instruction))
                token-stream (stage1-reader-compiled-ref
                              reader-source-path definitions env
                              (:token-stream instruction))
                records (stage1-reader-records-from-executor
                         source-path source-text classifier realizer automaton
                         form-builder executor token-stream)]
            (when *stage1-reader-pipeline-trace*
              (swap! *stage1-reader-pipeline-trace*
                     (fn [trace]
                       (-> (or trace {})
                           (update :gravity-executors (fnil conj [])
                                   :stage1-reader-form-builder-executor)
                           (assoc :token-classifier classifier)
                           (assoc :token-realizer realizer)
                           (assoc :token-automaton automaton)
                           (assoc :form-builder form-builder)
                           (assoc :form-builder-executor executor)
                           (assoc :forms-built
                                  {:token-count (:token-count token-stream)
                                   :form-count (count records)})))))
            (recur (assoc env (:label instruction) records)
                   (rest instructions)))

          (stage1-reader-compiled-pipeline-fail!
           "STAGE1COMP004" reader-source-path instruction
           {:missing-fields [:op]}))))))

(def ^:dynamic *stage1-reader-pipeline-trace*
  nil)

(def stage1-reader-algorithm-entrypoint
  'stage1-read-source)

(def stage1-reader-algorithm-diagnostic-messages
  {"STAGE1ALGO001" "stage1 reader algorithm entrypoint is missing"
   "STAGE1ALGO002" "stage1 reader algorithm used unsupported executable Gravity"
   "STAGE1ALGO003" "stage1 reader algorithm requested an unsupported host primitive"
   "STAGE1ALGO004" "stage1 reader algorithm output diverged from stage0 reader forms"})

(def stage1-reader-algorithm-diagnostic-ids
  ["STAGE1ALGO001" "STAGE1ALGO002" "STAGE1ALGO003" "STAGE1ALGO004"])

(def stage1-reader-algorithm-rejected-fixture-records
  (vec
   (concat
    stage1-reader-execution-rejected-fixture-records
    [{:fixture stage1-reader-source-path
      :diagnostic "STAGE1ALGO001"
      :rejected-behavior :missing-gravity-reader-entrypoint}
     {:fixture stage1-reader-source-path
      :diagnostic "STAGE1ALGO002"
      :rejected-behavior :unsupported-gravity-reader-form}
     {:fixture stage1-reader-source-path
      :diagnostic "STAGE1ALGO003"
      :rejected-behavior :unsupported-host-primitive}
     {:fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
      :diagnostic "STAGE1ALGO004"
      :rejected-behavior :stage0-reader-divergence}])))

(defn stage1-reader-algorithm-fail!
  [id source-path value data]
  (fail! id
         (get stage1-reader-algorithm-diagnostic-messages
              id
              "stage1 reader algorithm execution failed")
         (merge {:source-span {:source source-path}
                 :stage :stage1-reader-algorithm
                 :diagnostic-family :stage1-reader-algorithm
                 :value value
                 :remediation "Keep the reader algorithm entrypoint in executable Gravity source and preserve stage0 reader form parity until the Clojure seed is retired."}
                data)))

(defn stage1-reader-source-forms
  [reader-source-path]
  (mapv :form (read-source-form-records reader-source-path
                                         (slurp reader-source-path))))

(defn stage1-reader-definition-map
  [reader-source-path forms]
  (into {}
        (keep (fn [form]
                (when (seq? form)
                  (case (first form)
                    def
                    (do
                      (when-not (symbol? (second form))
                        (stage1-reader-algorithm-fail!
                         "STAGE1ALGO002" reader-source-path form
                         {:missing-fields [:def-name]}))
                      [(second form) {:kind :def
                                      :form form
                                      :value-form (nth form 2 nil)}])
                    defn
                    (do
                      (when-not (and (symbol? (second form))
                                     (vector? (nth form 2 nil)))
                        (stage1-reader-algorithm-fail!
                         "STAGE1ALGO002" reader-source-path form
                         {:missing-fields [:defn-name :params]}))
                      [(second form) {:kind :defn
                                      :form form
                                      :params (nth form 2)
                                      :body (drop 3 form)}])
                    nil))))
        forms))

(declare stage1-reader-eval-gravity)

(defn stage1-reader-eval-body
  [reader-source-path definitions env body]
  (reduce (fn [_ form]
            (stage1-reader-eval-gravity reader-source-path definitions env form))
          nil
          body))

(defn stage1-reader-execute-gravity-function
  [reader-source-path definitions function-symbol args]
  (let [definition (get definitions function-symbol)]
    (when-not (= :defn (:kind definition))
      (stage1-reader-algorithm-fail!
       "STAGE1ALGO001" reader-source-path function-symbol
       {:missing-fields [function-symbol]}))
    (let [params (:params definition)]
      (when-not (= (count params) (count args))
        (stage1-reader-algorithm-fail!
         "STAGE1ALGO002" reader-source-path (:form definition)
         {:params params :actual-count (count args)}))
      (cond
        (= function-symbol 'stage1-create-character-stream)
        (let [[source-path source-text source-runtime] args
              character-stream (stage1-reader-character-stream-from-runtime
                                source-path source-text source-runtime)]
          (when *stage1-reader-pipeline-trace*
            (swap! *stage1-reader-pipeline-trace*
                   (fn [trace]
                     (-> (or trace {})
                         (update :gravity-runtimes (fnil conj [])
                                 :stage1-reader-source-runtime)
                         (assoc :source-runtime source-runtime)
                         (assoc :character-stream character-stream)
                         (assoc :source-runtime-created
                                {:character-count
                                 (:character-count character-stream)
                                 :source-runtime-engine
                                 (:source-runtime-engine
                                  character-stream)})))))
          character-stream)

        (= function-symbol 'stage1-execute-token-automaton)
        (let [[source-path source-text classifier realizer automaton
               executor character-stream] args
              token-stream (stage1-reader-token-stream-from-executor
                            source-path source-text classifier realizer
                            automaton executor character-stream)]
          (when *stage1-reader-pipeline-trace*
            (swap! *stage1-reader-pipeline-trace*
                   (fn [trace]
                     (-> (or trace {})
                         (update :gravity-executors (fnil conj [])
                                 :stage1-reader-token-automaton-executor)
                         (assoc :token-classifier classifier)
                         (assoc :token-realizer realizer)
                         (assoc :token-automaton automaton)
                         (assoc :token-automaton-executor executor)
                         (assoc :token-stream token-stream)
                         (assoc :token-automaton-executed
                                {:character-count
                                 (get character-stream :character-count)
                                 :token-count (:token-count token-stream)
                                 :operation-count
                                 (count (:executed-operations token-stream))})))))
          token-stream)

        (= function-symbol 'stage1-execute-form-builder)
        (let [[source-path source-text classifier realizer automaton
               form-builder executor token-stream] args
              records (stage1-reader-records-from-executor
                       source-path source-text classifier realizer automaton
                       form-builder executor token-stream)]
          (when *stage1-reader-pipeline-trace*
            (swap! *stage1-reader-pipeline-trace*
                   (fn [trace]
                     (-> (or trace {})
                         (update :gravity-executors (fnil conj [])
                                 :stage1-reader-form-builder-executor)
                         (assoc :token-classifier classifier)
                         (assoc :token-realizer realizer)
                         (assoc :token-automaton automaton)
                         (assoc :form-builder form-builder)
                         (assoc :form-builder-executor executor)
                         (assoc :forms-built
                                {:token-count (:token-count token-stream)
                                 :form-count (count records)})))))
          records)

        :else
        (stage1-reader-eval-body reader-source-path
                                 definitions
                                 (zipmap params args)
                                 (:body definition))))))

(defn stage1-reader-eval-gravity
  [reader-source-path definitions env form]
  (cond
    (symbol? form)
    (cond
      (contains? env form) (get env form)
      (#{stage1-reader-algorithm-entrypoint
         stage1-reader-pipeline-entrypoint
         stage1-reader-character-pipeline-entrypoint
         stage1-reader-token-classifier-pipeline-entrypoint
         stage1-reader-token-realizer-pipeline-entrypoint
         stage1-reader-token-automaton-pipeline-entrypoint
         stage1-reader-form-builder-pipeline-entrypoint
         stage1-reader-executor-pipeline-entrypoint
         stage1-reader-runtime-pipeline-entrypoint
         stage1-reader-compiled-pipeline-entrypoint
         stage1-reader-binary-pipeline-entrypoint
         stage1-reader-self-hosted-runtime-entrypoint} form)
      (get definitions form)
      (contains? definitions form)
      (let [definition (get definitions form)]
        (case (:kind definition)
          :def (stage1-reader-eval-gravity reader-source-path definitions
                                           env (:value-form definition))
          :defn definition))
      :else
      (stage1-reader-algorithm-fail!
       "STAGE1ALGO002" reader-source-path form
       {:symbol form}))

    (or (keyword? form) (string? form) (number? form)
        (true? form) (false? form) (nil? form) (map? form)
        (vector? form) (set? form))
    form

    (seq? form)
    (case (first form)
      quote (second form)
      do (stage1-reader-eval-body reader-source-path definitions env (rest form))
      let (let [[_ bindings & body] form]
            (when-not (and (vector? bindings) (even? (count bindings)))
              (stage1-reader-algorithm-fail!
               "STAGE1ALGO002" reader-source-path form
               {:missing-fields [:let-bindings]}))
            (let [env (reduce (fn [env [name expr]]
                                (when-not (symbol? name)
                                  (stage1-reader-algorithm-fail!
                                   "STAGE1ALGO002" reader-source-path form
                                   {:missing-fields [:binding-symbol]}))
                                (assoc env name
                                       (stage1-reader-eval-gravity
                                        reader-source-path definitions env expr)))
                              env
                              (partition 2 bindings))]
              (stage1-reader-eval-body reader-source-path definitions env body)))
      if (let [[_ test then else] form]
           (if (stage1-reader-eval-gravity reader-source-path definitions
                                           env test)
             (stage1-reader-eval-gravity reader-source-path definitions
                                         env then)
             (stage1-reader-eval-gravity reader-source-path definitions
                                         env else)))
      reader/read-with-table
      (let [[_ source-path-expr source-text-expr table-expr] form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            table (stage1-reader-eval-gravity reader-source-path
                                              definitions env
                                              table-expr)]
        (stage1-reader-table-driven-records source-path source-text table))
      reader/scan-tokens
      (let [[_ source-path-expr source-text-expr table-expr] form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            table (stage1-reader-eval-gravity reader-source-path
                                              definitions env
                                              table-expr)
            token-stream (stage1-reader-token-stream source-path source-text
                                                     table)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/scan-tokens)
                       (assoc :token-stream token-stream)))))
        token-stream)
      reader/source-characters
      (let [[_ source-path-expr source-text-expr] form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            character-stream (stage1-reader-character-stream source-path
                                                             source-text)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/source-characters)
                       (assoc :character-stream character-stream)))))
        character-stream)
      reader/tokens-from-characters
      (let [[_ source-path-expr source-text-expr table-expr
             character-stream-expr]
            form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            table (stage1-reader-eval-gravity reader-source-path
                                              definitions env
                                              table-expr)
            character-stream (stage1-reader-eval-gravity
                              reader-source-path definitions env
                              character-stream-expr)
            token-stream (stage1-reader-token-stream-from-characters
                          source-path source-text table character-stream)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/tokens-from-characters)
                       (assoc :token-stream token-stream)
                       (assoc :tokens-from-characters
                              {:character-count
                               (:character-count character-stream)
                               :token-count (:token-count token-stream)})))))
        token-stream)
      reader/tokens-from-classifier
      (let [[_ source-path-expr source-text-expr classifier-expr
             character-stream-expr]
            form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            classifier (stage1-reader-eval-gravity reader-source-path
                                                   definitions env
                                                   classifier-expr)
            character-stream (stage1-reader-eval-gravity
                              reader-source-path definitions env
                              character-stream-expr)
            token-stream (stage1-reader-token-stream-from-classifier
                          source-path source-text classifier character-stream)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/tokens-from-classifier)
                       (assoc :token-classifier classifier)
                       (assoc :token-stream token-stream)
                       (assoc :tokens-from-classifier
                              {:character-count
                               (:character-count character-stream)
                               :token-count (:token-count token-stream)})))))
        token-stream)
      reader/realize-tokens
      (let [[_ source-path-expr source-text-expr classifier-expr
             realizer-expr character-stream-expr]
            form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            classifier (stage1-reader-eval-gravity reader-source-path
                                                   definitions env
                                                   classifier-expr)
            realizer (stage1-reader-eval-gravity reader-source-path
                                                 definitions env
                                                 realizer-expr)
            character-stream (stage1-reader-eval-gravity
                              reader-source-path definitions env
                              character-stream-expr)
            token-stream (stage1-reader-token-stream-from-realizer
                          source-path source-text classifier realizer
                          character-stream)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/realize-tokens)
                       (assoc :token-classifier classifier)
                       (assoc :token-realizer realizer)
                       (assoc :token-stream token-stream)
                       (assoc :tokens-realized
                              {:character-count
                               (:character-count character-stream)
                               :token-count (:token-count token-stream)})))))
        token-stream)
      reader/run-token-automaton
      (let [[_ source-path-expr source-text-expr classifier-expr
             realizer-expr automaton-expr character-stream-expr]
            form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            classifier (stage1-reader-eval-gravity reader-source-path
                                                   definitions env
                                                   classifier-expr)
            realizer (stage1-reader-eval-gravity reader-source-path
                                                 definitions env
                                                 realizer-expr)
            automaton (stage1-reader-eval-gravity reader-source-path
                                                  definitions env
                                                  automaton-expr)
            character-stream (stage1-reader-eval-gravity
                              reader-source-path definitions env
                              character-stream-expr)
            token-stream (stage1-reader-token-stream-from-automaton
                          source-path source-text classifier realizer
                          automaton character-stream)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/run-token-automaton)
                       (assoc :token-classifier classifier)
                       (assoc :token-realizer realizer)
                       (assoc :token-automaton automaton)
                       (assoc :token-stream token-stream)
                       (assoc :token-automaton-ran
                              {:character-count
                               (:character-count character-stream)
                               :token-count (:token-count token-stream)
                               :operation-count
                               (count (:executed-operations token-stream))})))))
        token-stream)
      reader/forms-from-tokens
      (let [[_ source-path-expr source-text-expr table-expr token-stream-expr]
            form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            table (stage1-reader-eval-gravity reader-source-path
                                              definitions env
                                              table-expr)
            token-stream (stage1-reader-eval-gravity reader-source-path
                                                     definitions env
                                                     token-stream-expr)
            records (stage1-reader-records-from-token-stream source-path
                                                             source-text
                                                             table
                                                             token-stream)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/forms-from-tokens)
                       (assoc :forms-from-tokens
                              {:token-count (:token-count token-stream)
                               :form-count (count records)})))))
        records)
      reader/build-forms
      (let [[_ source-path-expr source-text-expr classifier-expr
             realizer-expr automaton-expr form-builder-expr
             token-stream-expr]
            form
            source-path (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-path-expr)
            source-text (stage1-reader-eval-gravity reader-source-path
                                                    definitions env
                                                    source-text-expr)
            classifier (stage1-reader-eval-gravity reader-source-path
                                                   definitions env
                                                   classifier-expr)
            realizer (stage1-reader-eval-gravity reader-source-path
                                                 definitions env
                                                 realizer-expr)
            automaton (stage1-reader-eval-gravity reader-source-path
                                                  definitions env
                                                  automaton-expr)
            form-builder (stage1-reader-eval-gravity reader-source-path
                                                     definitions env
                                                     form-builder-expr)
            token-stream (stage1-reader-eval-gravity reader-source-path
                                                     definitions env
                                                     token-stream-expr)
            records (stage1-reader-records-from-form-builder
                     source-path source-text classifier realizer automaton
                     form-builder token-stream)]
        (when *stage1-reader-pipeline-trace*
          (swap! *stage1-reader-pipeline-trace*
                 (fn [trace]
                   (-> (or trace {})
                       (update :host-primitives (fnil conj [])
                               :reader/build-forms)
                       (assoc :token-classifier classifier)
                       (assoc :token-realizer realizer)
                       (assoc :token-automaton automaton)
                       (assoc :form-builder form-builder)
                       (assoc :forms-built
                              {:token-count (:token-count token-stream)
                               :form-count (count records)})))))
        records)
      (let [operator (first form)]
        (if (contains? definitions operator)
          (stage1-reader-execute-gravity-function
           reader-source-path definitions operator
           (mapv #(stage1-reader-eval-gravity reader-source-path
                                              definitions env %)
                 (rest form)))
          (stage1-reader-algorithm-fail!
           "STAGE1ALGO003" reader-source-path form
           {:operator operator}))))

    :else
    (stage1-reader-algorithm-fail!
     "STAGE1ALGO002" reader-source-path form
     {:form-kind (form-kind form)})))

(defn stage1-reader-execute-gravity-algorithm
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)]
    (stage1-reader-execute-gravity-function
     reader-source-path definitions stage1-reader-algorithm-entrypoint
     [source-path source-text])))

(defn stage1-reader-algorithm-diagnostic-stream
  [source-path algorithm-id]
  {:artifact :gravity/stage1-reader-algorithm-diagnostic-stream
   :stage :stage1-reader-algorithm
   :source-path source-path
   :algorithm-id algorithm-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-algorithm
            :artifact :gravity/diagnostic
            :message (or (stage1-reader-algorithm-diagnostic-messages id)
                         (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-algorithm-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-algorithm-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:stage1-reader-algorithm-diagnostic-stream
                                       :diagnostics])))]
    {:gravity-reader-entrypoint-executed?
     (= stage1-reader-algorithm-entrypoint (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :gravity-reader-algorithm-authored?
     true
     :host-primitive-boundary-explicit?
     (= [:reader/read-with-table] (:host-primitives artifact))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) (:stage1-reader-records artifact))
     :diagnostics-covered?
     (set/subset? (set (concat stage1-reader-algorithm-diagnostic-ids
                                (butlast stage1-reader-execution-diagnostic-ids)))
                  diagnostics)
     :limitations
     {:clojure-seed-evaluator? true
      :host-character-scanner? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-reader-read-with-table-primitive-with-gravity-code}
     :status :complete}))

(defn stage1-reader-algorithm-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        stage1-records (stage1-reader-execute-gravity-algorithm
                        stage1-reader-source-path source-path source-text)
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        algorithm-id (str "sha256:"
                          (sha256-hex
                           (pr-str {:reader-source stage1-reader-source-path
                                    :entrypoint stage1-reader-algorithm-entrypoint
                                    :forms (stage1-reader-source-forms
                                            stage1-reader-source-path)})))
        artifact-base
        {:kind :gravity/stage1-reader-algorithm-artifact
         :phase "15"
         :task "P15-S3"
         :stage :stage1-reader-algorithm
         :source-path source-path
         :reader-source-path stage1-reader-source-path
         :gravity-entrypoint stage1-reader-algorithm-entrypoint
         :algorithm-id algorithm-id
         :host-primitives [:reader/read-with-table]
         :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
         :stage1-reader-records stage1-records
         :stage0-comparison comparison
         :accepted-stage1-reader-algorithm-fixtures
         [{:fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
           :status :accepted
           :comparison comparison}]
         :rejected-stage1-reader-algorithm-fixtures
         stage1-reader-algorithm-rejected-fixture-records
         :stage1-reader-algorithm-diagnostic-stream
         (stage1-reader-algorithm-diagnostic-stream source-path algorithm-id)
         :stage1-reader-algorithm-results
         {:accepted-fixtures 1
          :rejected-fixtures (count stage1-reader-algorithm-rejected-fixture-records)
          :diagnostic-count (+ (count stage1-reader-algorithm-diagnostic-ids)
                               (dec (count stage1-reader-execution-diagnostic-ids)))
          :form-count (count stage1-records)
          :status :complete}
         :diagnostics []}
        capability-proof (stage1-reader-algorithm-proof artifact-base)]
    (when-not (:forms-equal? comparison)
      (stage1-reader-algorithm-fail!
       "STAGE1ALGO004" source-path comparison
       {:missing-fields [:stage0-form-parity]}))
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn stage1-reader-algorithm-file-artifact
  [path]
  (stage1-reader-algorithm-source-artifact path (slurp path)))

(defn stage1-reader-execute-gravity-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)]
    (when-not (= :defn (:kind (get definitions
                                    stage1-reader-pipeline-entrypoint)))
      (stage1-reader-pipeline-fail!
       "STAGE1PIPE001" reader-source-path stage1-reader-pipeline-entrypoint
       {:missing-fields [stage1-reader-pipeline-entrypoint]}))
    (stage1-reader-execute-gravity-function
     reader-source-path definitions stage1-reader-pipeline-entrypoint
     [source-path source-text])))

