          (= :gravity-source (get-in token-automaton [:provenance :owner]))
          (contains? (:diagnostics token-automaton) :invalid-automaton))
     :form-builder-covered?
     (and (= :gravity-reader-form-builder-v1 (:engine form-builder))
          (= :stage1-reader-token-automaton (:derived-from form-builder))
          (= (:engine token-automaton)
             (:token-automaton-engine form-builder))
          (= :gravity-source (get-in form-builder [:provenance :owner]))
          (contains? (:diagnostics form-builder) :invalid-form-builder)
          (set/subset? #{:list :vector :map :set}
                       (set (:collection-kinds form-builder)))
          (set/subset? #{:build-list-form :build-vector-form
                         :build-map-form :build-set-form
