     (not-any? #{:reader/tokens-from-classifier} (:host-primitives artifact))
     :tokens-from-characters-host-primitive-removed?
     (not-any? #{:reader/tokens-from-characters} (:host-primitives artifact))
     :scan-tokens-host-primitive-removed?
     (not-any? #{:reader/scan-tokens} (:host-primitives artifact))
     :whole-reader-host-primitive-removed?
     (not-any? #{:reader/read-with-table} (:host-primitives artifact))
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-source-runtime-v1
             (:source-runtime-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream)))
          (every? #(get-in % [:span :source])
                  (:characters character-stream)))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-token-automaton-executor-v1
             (:token-automaton-executor-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(= :gravity-reader-form-builder-executor-v1
                      (:form-builder-executor-engine %))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset? (set (concat stage1-reader-compiled-pipeline-diagnostic-ids
                                (butlast stage1-reader-execution-diagnostic-ids)))
                  diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? true
      :clojure-character-stream-implementation? true
      :clojure-seed-builtins? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-clojure-instruction-executor-with-gravity-emitted-reader-binary}
     :status :complete}))

(defn stage1-reader-compiled-pipeline-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        compiled-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-compiled-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records compiled-result)
        trace-value @trace
        compiled-program (:compiled-program compiled-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        compiled-pipeline-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-compiled-pipeline-entrypoint
                       :compiled-program compiled-program})))
        artifact-base
        {:kind :gravity/stage1-reader-compiled-pipeline-artifact
         :phase "15"
         :task "P15-S12"
         :stage :stage1-reader-compiled-pipeline
         :source-path source-path
         :reader-source-path stage1-reader-source-path
         :gravity-entrypoint stage1-reader-compiled-pipeline-entrypoint
         :compiled-pipeline-id compiled-pipeline-id
         :host-primitives host-primitives
         :gravity-runtimes gravity-runtimes
         :gravity-executors gravity-executors
         :trusted-boundary
         {:clojure-runtime-interpreter? false
          :clojure-instruction-executor? true
          :clojure-character-stream-implementation? true}
         :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
         :stage1-reader-compiled-program compiled-program
         :stage1-reader-source-runtime source-runtime
         :stage1-reader-character-stream character-stream
         :stage1-reader-token-classifier token-classifier
         :stage1-reader-token-realizer token-realizer
         :stage1-reader-token-automaton token-automaton
         :stage1-reader-token-automaton-executor
         token-automaton-executor
         :stage1-reader-form-builder form-builder
         :stage1-reader-form-builder-executor form-builder-executor
         :stage1-reader-token-stream token-stream
         :stage1-reader-records stage1-records
         :stage1-reader-compiled-pipeline-trace
         (dissoc trace-value :character-stream :token-stream
                 :token-classifier :token-realizer :token-automaton
                 :token-automaton-executor :form-builder
                 :form-builder-executor :source-runtime
                 :compiled-program)
         :stage0-comparison comparison
         :accepted-stage1-reader-compiled-pipeline-fixtures
         [{:fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
           :status :accepted
           :comparison comparison
           :character-count (:character-count character-stream)
           :token-count (:token-count token-stream)
           :form-count (count stage1-records)}]
         :rejected-stage1-reader-compiled-pipeline-fixtures
         stage1-reader-compiled-pipeline-rejected-fixture-records
         :stage1-reader-compiled-pipeline-diagnostic-stream
         (stage1-reader-compiled-pipeline-diagnostic-stream
          source-path compiled-pipeline-id)
         :stage1-reader-compiled-pipeline-results
         {:accepted-fixtures 1
          :rejected-fixtures
          (count stage1-reader-compiled-pipeline-rejected-fixture-records)
          :diagnostic-count
          (+ (count stage1-reader-compiled-pipeline-diagnostic-ids)
             (dec (count stage1-reader-execution-diagnostic-ids)))
          :character-count (:character-count character-stream)
          :token-count (:token-count token-stream)
          :form-count (count stage1-records)
          :status :complete}
         :diagnostics []}
        capability-proof (stage1-reader-compiled-pipeline-proof artifact-base)]
    (when-not (:forms-equal? comparison)
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP005" source-path comparison
       {:missing-fields [:stage0-form-parity]}))
    (when (seq host-primitives)
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP003" source-path trace-value
       {:host-primitives host-primitives}))
    (when-not (false? (get-in artifact-base
                              [:trusted-boundary
                               :clojure-runtime-interpreter?]))
      (stage1-reader-compiled-pipeline-fail!
       "STAGE1COMP004" source-path artifact-base
       {:missing-fields [:trusted-boundary]}))
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn stage1-reader-compiled-pipeline-file-artifact
  [path]
  (stage1-reader-compiled-pipeline-source-artifact path (slurp path)))

(defn stage1-reader-binary-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-emitted-binary-from-definitions
  [reader-source-path definitions compiled-program]
  (let [binary (stage1-reader-binary-literal-definition-value
                reader-source-path definitions
                'stage1-reader-emitted-binary)
        diagnostics (:diagnostics binary)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:missing-entrypoint :unsupported-form
                                     :unsupported-host-primitive
                                     :invalid-binary :stage0-divergence])
        required-stages [:stage1-binary-create-character-stream
                         :stage1-binary-execute-token-automaton
                         :stage1-binary-execute-form-builder]
        required-runtimes #{:stage1-reader-source-runtime}
        required-executors #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
        direct-stages (:direct-stages binary)]
    (when-not (map? binary)
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:stage1-reader-emitted-binary]}))
    (when-not (= :gravity-reader-binary-v1 (:engine binary))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:engine]}))
    (doseq [field [:entrypoint :emitted-from :compiled-entrypoint
                   :input :output :direct-stages :uses-runtimes
                   :uses-executors :preserves :diagnostics :provenance]]
      (when-not (contains? binary field)
        (stage1-reader-binary-pipeline-fail!
         "STAGE1BIN004" reader-source-path binary
         {:missing-fields [field]})))
    (when-not (= :stage1-read-source-binary-pipeline (:entrypoint binary))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:entrypoint]}))
    (when-not (= :stage1-reader-compiled-program (:emitted-from binary))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:emitted-from]}))
    (when-not (= (:entrypoint compiled-program)
                 (:compiled-entrypoint binary))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:compiled-entrypoint]}))
    (when-not (= [:source-path :source-text] (:input binary))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:output binary))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:output]}))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? required-runtimes (set (:uses-runtimes binary)))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? required-executors (set (:uses-executors binary)))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source (get-in binary [:provenance :owner]))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:provenance :owner]}))
    (when-not (= :replace-clojure-instruction-executor
                 (get-in binary [:provenance :retirement-objective]))
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path binary
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN004" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc binary
           :emitted-binary-id
           (str "sha256:" (sha256-hex (pr-str binary)))
           :linked-compiled-program-id
           (:compiled-program-id compiled-program))))

(defn stage1-reader-binary-entrypoint-valid?
  [definitions]
  (let [definition (get definitions stage1-reader-binary-pipeline-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-binary
               source-path
               source-text
               stage1-reader-emitted-binary))
            (:body definition)))))

(defn stage1-reader-execute-emitted-binary
  [reader-source-path definitions source-path source-text emitted-binary]
  (let [source-runtime (stage1-reader-binary-literal-definition-value
                        reader-source-path definitions
                        'stage1-reader-source-runtime)
        classifier (stage1-reader-binary-literal-definition-value
                    reader-source-path definitions
                    'stage1-reader-token-classifier)
        realizer (stage1-reader-binary-literal-definition-value
                  reader-source-path definitions
                  'stage1-reader-token-realizer)
        automaton (stage1-reader-binary-literal-definition-value
                   reader-source-path definitions
                   'stage1-reader-token-automaton)
        token-executor (stage1-reader-binary-literal-definition-value
                        reader-source-path definitions
                        'stage1-reader-token-automaton-executor)
        form-builder (stage1-reader-binary-literal-definition-value
                      reader-source-path definitions
                      'stage1-reader-form-builder)
        form-executor (stage1-reader-binary-literal-definition-value
                       reader-source-path definitions
                       'stage1-reader-form-builder-executor)
        character-stream (stage1-reader-character-stream-from-runtime
                          source-path source-text source-runtime)
        token-stream (stage1-reader-token-stream-from-executor
                      source-path source-text classifier realizer automaton
                      token-executor character-stream)
        records (stage1-reader-records-from-executor
                 source-path source-text classifier realizer automaton
                 form-builder form-executor token-stream)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (-> (or trace {})
                   (assoc :emitted-reader-binary emitted-binary)
                   (assoc :reader-binary-direct-stages
                          (mapv :op (:direct-stages emitted-binary)))
                   (update :gravity-runtimes (fnil conj [])
                           :stage1-reader-source-runtime)
                   (update :gravity-executors (fnil conj [])
                           :stage1-reader-token-automaton-executor)
                   (update :gravity-executors (fnil conj [])
                           :stage1-reader-form-builder-executor)
                   (assoc :source-runtime source-runtime)
                   (assoc :character-stream character-stream)
                   (assoc :token-classifier classifier)
                   (assoc :token-realizer realizer)
                   (assoc :token-automaton automaton)
                   (assoc :token-automaton-executor token-executor)
                   (assoc :form-builder form-builder)
                   (assoc :form-builder-executor form-executor)
                   (assoc :token-stream token-stream)
                   (assoc :source-runtime-created
                          {:character-count
                           (:character-count character-stream)
                           :source-runtime-engine
                           (:source-runtime-engine character-stream)})
                   (assoc :token-automaton-executed
                          {:character-count
                           (:character-count character-stream)
                           :token-count (:token-count token-stream)
                           :operation-count
                           (count (:executed-operations token-stream))})
                   (assoc :forms-built
                          {:token-count (:token-count token-stream)
                           :form-count (count records)})))))
    records))

(defn stage1-reader-execute-binary-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        compiled-program
        (stage1-reader-compiled-program-from-definitions reader-source-path
                                                         definitions)
        emitted-binary
        (stage1-reader-emitted-binary-from-definitions
         reader-source-path definitions compiled-program)]
    (when-not (stage1-reader-binary-entrypoint-valid? definitions)
      (stage1-reader-binary-pipeline-fail!
       "STAGE1BIN001" reader-source-path
       stage1-reader-binary-pipeline-entrypoint
       {:missing-fields [stage1-reader-binary-pipeline-entrypoint]}))
    {:records
     (stage1-reader-execute-emitted-binary
      reader-source-path definitions source-path source-text emitted-binary)
     :compiled-program compiled-program
     :emitted-binary emitted-binary}))

(defn stage1-reader-binary-pipeline-diagnostic-stream
  [source-path binary-pipeline-id]
  {:artifact :gravity/stage1-reader-binary-pipeline-diagnostic-stream
   :stage :stage1-reader-binary-pipeline
   :source-path source-path
   :binary-pipeline-id binary-pipeline-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-binary-pipeline
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-binary-pipeline-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-binary-pipeline-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-binary-pipeline-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:stage1-reader-binary-pipeline-diagnostic-stream
                                       :diagnostics])))
        emitted-binary (:stage1-reader-emitted-binary artifact)
        compiled-program (:stage1-reader-compiled-program artifact)
        source-runtime (:stage1-reader-source-runtime artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        direct-stages (mapv :op (:direct-stages emitted-binary))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-binary-pipeline-entrypoint-verified?
     (= stage1-reader-binary-pipeline-entrypoint (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :gravity-emitted-binary-authored?
     (and (= :gravity-reader-binary-v1 (:engine emitted-binary))
          (= :gravity-source (get-in emitted-binary [:provenance :owner]))
          (= :reader-emitted-binary
             (get-in emitted-binary [:provenance :purpose])))
     :gravity-emitted-binary-direct-stages-covered?
     (= [:stage1-binary-create-character-stream
         :stage1-binary-execute-token-automaton
         :stage1-binary-execute-form-builder]
        direct-stages)
     :gravity-compiled-program-linked?
     (and (= :gravity-reader-compiled-program-v1 (:engine compiled-program))
          (= :stage1-reader-compiled-program
             (:emitted-from emitted-binary))
          (= (:compiled-program-id compiled-program)
             (:linked-compiled-program-id emitted-binary)))
     :gravity-source-runtime-authored?
     (and (= :gravity-reader-source-runtime-v1 (:engine source-runtime))
          (= :gravity-source (get-in source-runtime [:provenance :owner])))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-source-runtime} gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :runtime-interpreter-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-runtime-interpreter?]))
     :instruction-executor-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-instruction-executor?]))
     :binary-runner-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :clojure-binary-runner?]))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :source-characters-host-primitive-removed?
     (not-any? #{:reader/source-characters} (:host-primitives artifact))
     :run-token-automaton-host-primitive-removed?
     (not-any? #{:reader/run-token-automaton} (:host-primitives artifact))
     :build-forms-host-primitive-removed?
     (not-any? #{:reader/build-forms} (:host-primitives artifact))
     :forms-from-tokens-host-primitive-removed?
     (not-any? #{:reader/forms-from-tokens} (:host-primitives artifact))
     :realize-tokens-host-primitive-removed?
     (not-any? #{:reader/realize-tokens} (:host-primitives artifact))
     :tokens-from-classifier-host-primitive-removed?
     (not-any? #{:reader/tokens-from-classifier} (:host-primitives artifact))
     :tokens-from-characters-host-primitive-removed?
     (not-any? #{:reader/tokens-from-characters} (:host-primitives artifact))
     :scan-tokens-host-primitive-removed?
     (not-any? #{:reader/scan-tokens} (:host-primitives artifact))
     :whole-reader-host-primitive-removed?
     (not-any? #{:reader/read-with-table} (:host-primitives artifact))
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-source-runtime-v1
             (:source-runtime-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream)))
          (every? #(get-in % [:span :source])
                  (:characters character-stream)))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-token-automaton-executor-v1
             (:token-automaton-executor-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(= :gravity-reader-form-builder-executor-v1
                      (:form-builder-executor-engine %))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset? (set (concat stage1-reader-binary-pipeline-diagnostic-ids
                                (butlast stage1-reader-execution-diagnostic-ids)))
                  diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? true
      :clojure-character-stream-implementation? true
      :clojure-seed-builtins? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-clojure-binary-runner-and-character-stream-with-self-hosted-reader-runtime}
     :status :complete}))

(defn stage1-reader-binary-pipeline-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        binary-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-binary-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records binary-result)
        trace-value @trace
        emitted-binary (:emitted-binary binary-result)
        compiled-program (:compiled-program binary-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        binary-pipeline-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint stage1-reader-binary-pipeline-entrypoint
                       :emitted-binary emitted-binary
                       :compiled-program-id
                       (:compiled-program-id compiled-program)})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-binary-pipeline-artifact
         :phase "15"
         :task "P15-S13"
         :stage :stage1-reader-binary-pipeline
         :source-path source-path
         :reader-source-path stage1-reader-source-path
         :gravity-entrypoint stage1-reader-binary-pipeline-entrypoint
         :binary-pipeline-id binary-pipeline-id
         :reader-binary-id (:emitted-binary-id emitted-binary)
         :host-primitives host-primitives
         :gravity-runtimes gravity-runtimes
         :gravity-executors gravity-executors
         :trusted-boundary
         {:clojure-runtime-interpreter? false
          :clojure-instruction-executor? false
          :clojure-binary-runner? true
          :clojure-character-stream-implementation? true}
         :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
         :stage1-reader-compiled-program compiled-program
         :stage1-reader-emitted-binary emitted-binary
         :stage1-reader-source-runtime source-runtime
         :stage1-reader-character-stream character-stream
         :stage1-reader-token-classifier token-classifier
         :stage1-reader-token-realizer token-realizer
         :stage1-reader-token-automaton token-automaton
         :stage1-reader-token-automaton-executor
         token-automaton-executor
         :stage1-reader-form-builder form-builder
         :stage1-reader-form-builder-executor form-builder-executor
         :stage1-reader-token-stream token-stream
         :stage1-reader-records stage1-records
         :stage1-reader-binary-pipeline-trace
         (dissoc trace-value :character-stream :token-stream
                 :token-classifier :token-realizer :token-automaton
                 :token-automaton-executor :form-builder
                 :form-builder-executor :source-runtime
                 :emitted-reader-binary)
         :stage0-comparison comparison
         :accepted-stage1-reader-binary-pipeline-fixtures
         [{:fixture "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
           :status :accepted
           :comparison comparison
           :character-count (:character-count character-stream)
           :token-count (:token-count token-stream)
           :form-count (count stage1-records)}]
         :rejected-stage1-reader-binary-pipeline-fixtures
         stage1-reader-binary-pipeline-rejected-fixture-records
         :stage1-reader-binary-pipeline-diagnostic-stream
         (stage1-reader-binary-pipeline-diagnostic-stream
          source-path binary-pipeline-id)
         :stage1-reader-binary-pipeline-results
         {:accepted-fixtures 1
          :rejected-fixtures
          (count stage1-reader-binary-pipeline-rejected-fixture-records)
          :diagnostic-count
          (+ (count stage1-reader-binary-pipeline-diagnostic-ids)
             (dec (count stage1-reader-execution-diagnostic-ids)))
	         :character-count (:character-count character-stream)
	          :token-count (:token-count token-stream)
	         :form-count (count stage1-records)
	          :status :complete}
	         :diagnostics []}]
	      (when-not (:forms-equal? comparison)
	        (stage1-reader-binary-pipeline-fail!
	         "STAGE1BIN005" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when (seq host-primitives)
        (stage1-reader-binary-pipeline-fail!
         "STAGE1BIN003" source-path trace-value
         {:host-primitives host-primitives}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-runtime-interpreter?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-instruction-executor?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :clojure-binary-runner?])))
	        (stage1-reader-binary-pipeline-fail!
	         "STAGE1BIN004" source-path artifact-base
	         {:missing-fields [:trusted-boundary]}))
	      (let [capability-proof
	            (stage1-reader-binary-pipeline-proof artifact-base)]
	        (assoc artifact-base
	               :capability-based-proof capability-proof
	               :artifact-id (c4-artifact-id (assoc artifact-base
	                                                   :capability-based-proof
	                                                   capability-proof)))))))

(defn stage1-reader-binary-pipeline-file-artifact
  [path]
  (stage1-reader-binary-pipeline-source-artifact path (slurp path)))

(defn stage1-reader-self-hosted-runtime-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-self-hosted-runtime-from-definitions
  [reader-source-path definitions]
  (let [runtime (stage1-reader-self-hosted-runtime-literal-definition-value
                 reader-source-path definitions
                 'stage1-reader-self-hosted-runtime)
        diagnostics (:diagnostics runtime)
        missing-diagnostics (remove #(contains? diagnostics %)
                                    [:missing-entrypoint :unsupported-form
                                     :unsupported-host-primitive
                                     :invalid-runtime :stage0-divergence])
        required-stages [:stage1-self-hosted-create-character-stream
                         :stage1-self-hosted-execute-token-automaton
                         :stage1-self-hosted-execute-form-builder]
        required-replacements #{:clojure-binary-runner
                                :clojure-character-stream-implementation}
        required-runtimes #{:stage1-reader-self-hosted-runtime
                            :stage1-reader-source-runtime}
        required-executors #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
        direct-stages (:direct-stages runtime)]
    (when-not (map? runtime)
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:stage1-reader-self-hosted-runtime]}))
    (when-not (= :gravity-reader-self-hosted-runtime-v1 (:engine runtime))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:engine]}))
    (doseq [field [:entrypoint :replaces :input :output :source-runtime
                   :direct-stages :uses-runtimes :uses-executors
                   :preserves :diagnostics :provenance]]
      (when-not (contains? runtime field)
        (stage1-reader-self-hosted-runtime-fail!
         "STAGE1SELF004" reader-source-path runtime
         {:missing-fields [field]})))
    (when-not (= :stage1-read-source-self-hosted-runtime
                 (:entrypoint runtime))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? required-replacements
                           (set (:replaces runtime)))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:replaces]}))
    (when-not (= [:source-path :source-text] (:input runtime))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:output runtime))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:output]}))
    (when-not (= :stage1-reader-source-runtime (:source-runtime runtime))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:source-runtime]}))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? required-runtimes
                           (set (:uses-runtimes runtime)))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? required-executors
                           (set (:uses-executors runtime)))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source (get-in runtime [:provenance :owner]))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-self-hosted-runtime
                 (get-in runtime [:provenance :purpose]))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-clojure-binary-runner-and-character-stream
                 (get-in runtime [:provenance :retirement-objective]))
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path runtime
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF004" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc runtime
           :self-hosted-runtime-id
           (str "sha256:" (sha256-hex (pr-str runtime))))))

(defn stage1-reader-self-hosted-runtime-entrypoint-valid?
  [definitions]
  (let [definition (get definitions
                        stage1-reader-self-hosted-runtime-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-self-hosted-runtime
               source-path
               source-text
               stage1-reader-self-hosted-runtime))
            (:body definition)))))

(defn stage1-reader-execute-self-hosted-runtime
  [reader-source-path definitions source-path source-text self-hosted-runtime]
  (let [source-runtime
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions 'stage1-reader-source-runtime)
        classifier
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions 'stage1-reader-token-classifier)
        realizer
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions 'stage1-reader-token-realizer)
        automaton
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions 'stage1-reader-token-automaton)
        token-executor
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions
         'stage1-reader-token-automaton-executor)
        form-builder
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions 'stage1-reader-form-builder)
        form-executor
        (stage1-reader-self-hosted-runtime-literal-definition-value
         reader-source-path definitions
         'stage1-reader-form-builder-executor)
        character-stream
        (assoc (stage1-reader-character-stream-from-runtime
                source-path source-text source-runtime)
               :gravity-runtime :stage1-reader-self-hosted-runtime
               :self-hosted-runtime-id
               (:self-hosted-runtime-id self-hosted-runtime)
               :self-hosted-runtime-engine (:engine self-hosted-runtime))
        token-stream (stage1-reader-token-stream-from-executor
                      source-path source-text classifier realizer automaton
                      token-executor character-stream)
        records (stage1-reader-records-from-executor
                 source-path source-text classifier realizer automaton
                 form-builder form-executor token-stream)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (-> (or trace {})
                   (assoc :self-hosted-reader-runtime self-hosted-runtime)
                   (assoc :reader-self-hosted-direct-stages
                          (mapv :op (:direct-stages self-hosted-runtime)))
                   (update :gravity-runtimes (fnil conj [])
                           :stage1-reader-self-hosted-runtime)
                   (update :gravity-runtimes (fnil conj [])
                           :stage1-reader-source-runtime)
                   (update :gravity-executors (fnil conj [])
                           :stage1-reader-token-automaton-executor)
                   (update :gravity-executors (fnil conj [])
                           :stage1-reader-form-builder-executor)
                   (assoc :source-runtime source-runtime)
                   (assoc :character-stream character-stream)
                   (assoc :token-classifier classifier)
                   (assoc :token-realizer realizer)
                   (assoc :token-automaton automaton)
                   (assoc :token-automaton-executor token-executor)
                   (assoc :form-builder form-builder)
                   (assoc :form-builder-executor form-executor)
                   (assoc :token-stream token-stream)
                   (assoc :self-hosted-runtime-created
                          {:character-count
                           (:character-count character-stream)
                           :source-runtime-engine
                           (:source-runtime-engine character-stream)
                           :self-hosted-runtime-engine
                           (:self-hosted-runtime-engine character-stream)})
                   (assoc :token-automaton-executed
                          {:character-count
                           (:character-count character-stream)
                           :token-count (:token-count token-stream)
                           :operation-count
                           (count (:executed-operations token-stream))})
                   (assoc :forms-built
                          {:token-count (:token-count token-stream)
                           :form-count (count records)})))))
    records))

(defn stage1-reader-execute-self-hosted-runtime-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-self-hosted-runtime-entrypoint-valid?
               definitions)
      (stage1-reader-self-hosted-runtime-fail!
       "STAGE1SELF001" reader-source-path
       stage1-reader-self-hosted-runtime-entrypoint
       {:missing-fields
        [stage1-reader-self-hosted-runtime-entrypoint]}))
    {:records
     (stage1-reader-execute-self-hosted-runtime
      reader-source-path definitions source-path source-text
      self-hosted-runtime)
     :self-hosted-runtime self-hosted-runtime}))

(defn stage1-reader-self-hosted-runtime-diagnostic-stream
  [source-path self-hosted-runtime-id]
  {:artifact :gravity/stage1-reader-self-hosted-runtime-diagnostic-stream
   :stage :stage1-reader-self-hosted-runtime
   :source-path source-path
   :self-hosted-runtime-id self-hosted-runtime-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-self-hosted-runtime
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-self-hosted-runtime-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-self-hosted-runtime-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-self-hosted-runtime-proof
  [artifact]
  (let [diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:stage1-reader-self-hosted-runtime-diagnostic-stream
                                       :diagnostics])))
        runtime (:stage1-reader-self-hosted-runtime artifact)
        source-runtime (:stage1-reader-source-runtime artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        direct-stages (mapv :op (:direct-stages runtime))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-self-hosted-entrypoint-verified?
     (= stage1-reader-self-hosted-runtime-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :gravity-self-hosted-runtime-authored?
     (and (= :gravity-reader-self-hosted-runtime-v1 (:engine runtime))
          (= :gravity-source (get-in runtime [:provenance :owner]))
          (= :reader-self-hosted-runtime
             (get-in runtime [:provenance :purpose])))
     :gravity-self-hosted-runtime-direct-stages-covered?
     (= [:stage1-self-hosted-create-character-stream
         :stage1-self-hosted-execute-token-automaton
         :stage1-self-hosted-execute-form-builder]
        direct-stages)
     :binary-runner-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-binary-runner?]))
     :character-stream-implementation-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-character-stream-implementation?]))
     :runtime-interpreter-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-runtime-interpreter?]))
     :instruction-executor-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-instruction-executor?]))
     :seed-builtin-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :clojure-seed-builtins?]))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :gravity-source-runtime-authored?
     (and (= :gravity-reader-source-runtime-v1 (:engine source-runtime))
          (= :gravity-source (get-in source-runtime [:provenance :owner])))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-source-runtime-v1
             (:source-runtime-engine character-stream))
          (= :gravity-reader-self-hosted-runtime-v1
             (:self-hosted-runtime-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream)))
          (every? #(get-in % [:span :source])
                  (:characters character-stream)))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-token-automaton-executor-v1
             (:token-automaton-executor-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(= :gravity-reader-form-builder-executor-v1
                      (:form-builder-executor-engine %))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-self-hosted-runtime-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-clojure-seed-builtins-with-gravity-core-bootstrap}
     :status :complete}))

(defn stage1-reader-self-hosted-runtime-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-self-hosted-runtime-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        self-hosted-runtime-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-self-hosted-runtime-entrypoint
                       :self-hosted-runtime self-hosted-runtime})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-self-hosted-runtime-artifact
           :phase "15"
           :task "P15-S14"
           :stage :stage1-reader-self-hosted-runtime
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint stage1-reader-self-hosted-runtime-entrypoint
           :self-hosted-runtime-id self-hosted-runtime-id
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-self-hosted-runtime-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime)
           :stage0-comparison comparison
           :accepted-stage1-reader-self-hosted-runtime-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)}]
           :rejected-stage1-reader-self-hosted-runtime-fixtures
           stage1-reader-self-hosted-runtime-rejected-fixture-records
           :stage1-reader-self-hosted-runtime-diagnostic-stream
           (stage1-reader-self-hosted-runtime-diagnostic-stream
            source-path self-hosted-runtime-id)
           :stage1-reader-self-hosted-runtime-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-self-hosted-runtime-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-self-hosted-runtime-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-self-hosted-runtime-fail!
         "STAGE1SELF005" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when (seq host-primitives)
        (stage1-reader-self-hosted-runtime-fail!
         "STAGE1SELF003" source-path trace-value
         {:host-primitives host-primitives}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-runtime-interpreter?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-instruction-executor?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-binary-runner?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-character-stream-implementation?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :clojure-seed-builtins?])))
        (stage1-reader-self-hosted-runtime-fail!
         "STAGE1SELF004" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-self-hosted-runtime-proof artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id (c4-artifact-id (assoc artifact-base
                                                   :capability-based-proof
                                                   capability-proof)))))))

(defn stage1-reader-self-hosted-runtime-file-artifact
  [path]
  (stage1-reader-self-hosted-runtime-source-artifact path (slurp path)))

(def stage1-reader-core-bootstrap-required-operations
  [:source-character-stream
   :token-classifier
   :token-realizer
   :token-automaton-executor
   :form-builder-executor
   :stage0-form-parity
   :diagnostic-stream
   :artifact-provenance])

(defn stage1-reader-core-bootstrap-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-core-bootstrap-builtins-from-definitions
  [reader-source-path definitions]
  (let [builtins
        (stage1-reader-core-bootstrap-literal-definition-value
         reader-source-path definitions
         'stage1-reader-core-bootstrap-builtins)]
    (when-not (map? builtins)
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:stage1-reader-core-bootstrap-builtins]}))
    (doseq [field [:engine :profile :owner :replaces :host-fallbacks
                   :effects :capabilities :operations :preserves
                   :provenance]]
      (when-not (contains? builtins field)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE003" reader-source-path builtins
         {:missing-fields [field]})))
    (when-not (= :gravity-core-bootstrap-builtins-v1 (:engine builtins))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:engine]}))
    (when-not (= :meta (:profile builtins))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:profile]}))
    (when-not (= :gravity-source (:owner builtins))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:owner]}))
    (when-not (contains? (set (:replaces builtins))
                         :clojure-seed-builtins)
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:replaces]}))
    (when-not (= [] (:host-fallbacks builtins))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE005" reader-source-path builtins
       {:host-fallbacks (:host-fallbacks builtins)}))
    (when-not (empty? (:effects builtins))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE005" reader-source-path builtins
       {:effects (:effects builtins)}))
    (when-not (empty? (:capabilities builtins))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE005" reader-source-path builtins
       {:capabilities (:capabilities builtins)}))
    (let [operations (:operations builtins)
          operation-names (set (map :op operations))
          required-operation-set
          (set stage1-reader-core-bootstrap-required-operations)]
      (when-not (vector? operations)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE003" reader-source-path builtins
         {:missing-fields [:operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE002" reader-source-path operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-core-bootstrap-required-operations))}))
      (doseq [operation operations]
        (when-not (= :gravity-source (:implemented-by operation))
          (stage1-reader-core-bootstrap-fail!
           "STAGE1CORE005" reader-source-path operation
           {:missing-fields [:implemented-by]}))))
    (when-not (= :gravity-source (get-in builtins [:provenance :owner]))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-core-bootstrap-builtin-replacement
                 (get-in builtins [:provenance :purpose]))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-clojure-seed-builtins-with-gravity-core-bootstrap
                 (get-in builtins [:provenance :retirement-objective]))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE003" reader-source-path builtins
       {:missing-fields [:provenance :retirement-objective]}))
    (assoc builtins
           :core-bootstrap-builtins-id
           (str "sha256:" (sha256-hex (pr-str builtins))))))

(defn stage1-reader-core-bootstrap-runtime-from-definitions
  [reader-source-path definitions]
  (let [runtime
        (stage1-reader-core-bootstrap-literal-definition-value
         reader-source-path definitions
         'stage1-reader-core-bootstrap-runtime)
        diagnostics (:diagnostics runtime)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint :unsupported-builtin-operation
                 :missing-builtin-record :builtin-runtime-divergence
                 :illegal-host-fallback
                 :invalid-core-bootstrap-runtime])
        required-stages
        [:stage1-core-bootstrap-create-character-stream
         :stage1-core-bootstrap-execute-token-automaton
         :stage1-core-bootstrap-execute-form-builder
         :stage1-core-bootstrap-compare-stage0]
        direct-stages (:direct-stages runtime)]
    (when-not (map? runtime)
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:stage1-reader-core-bootstrap-runtime]}))
    (doseq [field [:engine :entrypoint :replaces :base-runtime
                   :core-bootstrap-builtins :input :output
                   :direct-stages :uses-runtimes :uses-builtins
                   :uses-executors :preserves :diagnostics
                   :provenance]]
      (when-not (contains? runtime field)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE006" reader-source-path runtime
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-core-bootstrap-runtime-v1
                 (:engine runtime))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-core-bootstrap
                 (:entrypoint runtime))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:entrypoint]}))
    (when-not (contains? (set (:replaces runtime))
                         :clojure-seed-builtins)
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-self-hosted-runtime
                 (:base-runtime runtime))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:base-runtime]}))
    (when-not (= :stage1-reader-core-bootstrap-builtins
                 (:core-bootstrap-builtins runtime))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:core-bootstrap-builtins]}))
    (when-not (= [:source-path :source-text] (:input runtime))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:output runtime))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:output]}))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? #{:stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes runtime)))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins runtime)))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors runtime)))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source (get-in runtime [:provenance :owner]))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-core-bootstrap-runtime
                 (get-in runtime [:provenance :purpose]))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-clojure-seed-builtins-with-gravity-core-bootstrap
                 (get-in runtime [:provenance :retirement-objective]))
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path runtime
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE006" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc runtime
           :core-bootstrap-runtime-id
           (str "sha256:" (sha256-hex (pr-str runtime))))))

(defn stage1-reader-core-bootstrap-entrypoint-valid?
  [definitions]
  (let [definition (get definitions
                        stage1-reader-core-bootstrap-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-core-bootstrap-runtime
               source-path
               source-text
               stage1-reader-core-bootstrap-runtime
               stage1-reader-core-bootstrap-builtins))
            (:body definition)))))

(defn stage1-reader-execute-core-bootstrap-runtime
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins]
  (let [builtins-id (:core-bootstrap-builtins-id core-bootstrap-builtins)
        runtime-id (:core-bootstrap-runtime-id core-bootstrap-runtime)
        operation-names (mapv :op (:operations core-bootstrap-builtins))
        annotate-with-core
        (fn [record]
          (assoc record
                 :core-bootstrap-runtime-id runtime-id
                 :core-bootstrap-builtins-id builtins-id
                 :core-bootstrap-builtins-engine
                 (:engine core-bootstrap-builtins)
                 :seed-builtin-replacement
                 :gravity-core-bootstrap-builtins-v1))
        records
        (stage1-reader-execute-self-hosted-runtime
         reader-source-path definitions source-path source-text
         self-hosted-runtime)
        annotated-records (mapv annotate-with-core records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (-> (or trace {})
                   (assoc :core-bootstrap-runtime
                          core-bootstrap-runtime)
                   (assoc :core-bootstrap-builtins
                          core-bootstrap-builtins)
                   (assoc :core-bootstrap-operation-coverage
                          {:required
                           stage1-reader-core-bootstrap-required-operations
                           :provided operation-names
                           :covered?
                           (set/subset?
                            (set stage1-reader-core-bootstrap-required-operations)
                            (set operation-names))})
                   (assoc :seed-builtin-fallbacks [])
                   (update :gravity-runtimes (fnil conj [])
                           :stage1-reader-core-bootstrap-runtime)
                   (update :character-stream annotate-with-core)
                   (update :token-stream annotate-with-core)
                   (assoc :core-bootstrap-builtins-applied
                          {:runtime-id runtime-id
                           :builtins-id builtins-id
                           :operation-count (count operation-names)
                           :host-fallbacks (:host-fallbacks
                                            core-bootstrap-builtins)})))))
    annotated-records))

(defn stage1-reader-execute-core-bootstrap-runtime-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-core-bootstrap-entrypoint-valid?
               definitions)
      (stage1-reader-core-bootstrap-fail!
       "STAGE1CORE001" reader-source-path
       stage1-reader-core-bootstrap-entrypoint
       {:missing-fields [stage1-reader-core-bootstrap-entrypoint]}))
    {:records
     (stage1-reader-execute-core-bootstrap-runtime
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins}))

(defn stage1-reader-core-bootstrap-diagnostic-stream
  [source-path core-bootstrap-runtime-id core-bootstrap-builtins-id]
  {:artifact :gravity/stage1-reader-core-bootstrap-diagnostic-stream
   :stage :stage1-reader-core-bootstrap
   :source-path source-path
   :core-bootstrap-runtime-id core-bootstrap-runtime-id
   :core-bootstrap-builtins-id core-bootstrap-builtins-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-core-bootstrap
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-core-bootstrap-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-core-bootstrap-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-core-bootstrap-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-core-bootstrap-diagnostic-stream
                           :diagnostics])))
        runtime (:stage1-reader-core-bootstrap-runtime artifact)
        builtins (:stage1-reader-core-bootstrap-builtins artifact)
        source-runtime (:stage1-reader-source-runtime artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names (set (map :op (:operations builtins)))
        direct-stages (mapv :op (:direct-stages runtime))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-core-bootstrap-entrypoint-verified?
     (= stage1-reader-core-bootstrap-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :core-bootstrap-runtime-authored?
     (and (= :gravity-reader-core-bootstrap-runtime-v1
             (:engine runtime))
          (= :gravity-source (get-in runtime [:provenance :owner]))
          (= :reader-core-bootstrap-runtime
             (get-in runtime [:provenance :purpose])))
     :core-bootstrap-runtime-direct-stages-covered?
     (= [:stage1-core-bootstrap-create-character-stream
         :stage1-core-bootstrap-execute-token-automaton
         :stage1-core-bootstrap-execute-form-builder
         :stage1-core-bootstrap-compare-stage0]
        direct-stages)
     :core-bootstrap-builtins-authored?
     (and (= :gravity-core-bootstrap-builtins-v1 (:engine builtins))
          (= :gravity-source (:owner builtins))
          (= :reader-core-bootstrap-builtin-replacement
             (get-in builtins [:provenance :purpose])))
     :core-bootstrap-operations-covered?
     (set/subset?
      (set stage1-reader-core-bootstrap-required-operations)
      operation-names)
     :core-bootstrap-runtime-links-builtins?
     (= :stage1-reader-core-bootstrap-builtins
        (:core-bootstrap-builtins runtime))
     :seed-builtins-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-seed-builtins?]))
     :clojure-seed-orchestration-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :clojure-seed-orchestration?]))
     :binary-runner-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-binary-runner?]))
     :character-stream-implementation-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-character-stream-implementation?]))
     :runtime-interpreter-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-runtime-interpreter?]))
     :instruction-executor-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-instruction-executor?]))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :gravity-source-runtime-authored?
     (and (= :gravity-reader-source-runtime-v1 (:engine source-runtime))
          (= :gravity-source (get-in source-runtime [:provenance :owner])))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-source-runtime-v1
             (:source-runtime-engine character-stream))
          (= :gravity-reader-self-hosted-runtime-v1
             (:self-hosted-runtime-engine character-stream))
          (= :gravity-core-bootstrap-builtins-v1
             (:core-bootstrap-builtins-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-token-automaton-executor-v1
             (:token-automaton-executor-engine token-stream))
          (= :gravity-core-bootstrap-builtins-v1
             (:core-bootstrap-builtins-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-form-builder-executor-v1
                           (:form-builder-executor-engine %))
                        (= :gravity-core-bootstrap-builtins-v1
                           (:core-bootstrap-builtins-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-core-bootstrap-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-clojure-seed-orchestration-with-gravity-compiler-driver}
     :status :complete}))

(defn stage1-reader-core-bootstrap-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-core-bootstrap-runtime-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        core-bootstrap-runtime (:core-bootstrap-runtime runtime-result)
        core-bootstrap-builtins (:core-bootstrap-builtins runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        seed-builtin-fallbacks
        (vec (distinct (:seed-builtin-fallbacks trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        core-bootstrap-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-core-bootstrap-entrypoint
                       :core-bootstrap-runtime
                       core-bootstrap-runtime
                       :core-bootstrap-builtins
                       core-bootstrap-builtins})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-core-bootstrap-artifact
           :phase "15"
           :task "P15-S15"
           :stage :stage1-reader-core-bootstrap
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint stage1-reader-core-bootstrap-entrypoint
           :core-bootstrap-artifact-id core-bootstrap-artifact-id
           :reader-core-bootstrap-runtime-id
           (:core-bootstrap-runtime-id core-bootstrap-runtime)
           :reader-core-bootstrap-builtins-id
           (:core-bootstrap-builtins-id core-bootstrap-builtins)
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :seed-builtin-fallbacks seed-builtin-fallbacks
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? false
            :clojure-seed-orchestration? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-core-bootstrap-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins)
           :stage0-comparison comparison
           :accepted-stage1-reader-core-bootstrap-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :core-bootstrap-builtins-id
             (:core-bootstrap-builtins-id core-bootstrap-builtins)}]
           :rejected-stage1-reader-core-bootstrap-fixtures
           stage1-reader-core-bootstrap-rejected-fixture-records
           :stage1-reader-core-bootstrap-diagnostic-stream
           (stage1-reader-core-bootstrap-diagnostic-stream
            source-path
            (:core-bootstrap-runtime-id core-bootstrap-runtime)
            (:core-bootstrap-builtins-id core-bootstrap-builtins))
           :stage1-reader-core-bootstrap-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-core-bootstrap-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-core-bootstrap-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE004" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when (seq host-primitives)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE005" source-path trace-value
         {:host-primitives host-primitives}))
      (when (seq seed-builtin-fallbacks)
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE005" source-path trace-value
         {:seed-builtin-fallbacks seed-builtin-fallbacks}))
      (when (seq (:host-fallbacks core-bootstrap-builtins))
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE005" source-path core-bootstrap-builtins
         {:host-fallbacks (:host-fallbacks core-bootstrap-builtins)}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-runtime-interpreter?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-instruction-executor?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-binary-runner?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-character-stream-implementation?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-seed-builtins?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :clojure-seed-orchestration?])))
        (stage1-reader-core-bootstrap-fail!
         "STAGE1CORE006" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-core-bootstrap-proof artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id (c4-artifact-id (assoc artifact-base
                                                   :capability-based-proof
                                                   capability-proof)))))))

(defn stage1-reader-core-bootstrap-file-artifact
  [path]
  (stage1-reader-core-bootstrap-source-artifact path (slurp path)))

(def stage1-reader-compiler-driver-required-operations
  [:load-reader-source
   :resolve-stage1-entrypoint
   :route-source-text
   :execute-core-bootstrap-runtime
   :emit-diagnostic-stream
   :emit-proof-artifact
   :compare-stage0
   :record-provenance])

(defn stage1-reader-compiler-driver-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-compiler-driver-from-definitions
  [reader-source-path definitions]
  (let [driver
        (stage1-reader-compiler-driver-literal-definition-value
         reader-source-path definitions
         'stage1-reader-compiler-driver)
        diagnostics (:diagnostics driver)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint :unsupported-driver-operation
                 :missing-driver-record :artifact-routing-divergence
                 :diagnostic-stream-divergence
                 :illegal-seed-orchestration-fallback
                 :invalid-compiler-driver])
        required-stages
        [:stage1-driver-load-reader-source
         :stage1-driver-resolve-entrypoint
         :stage1-driver-execute-core-bootstrap-runtime
         :stage1-driver-emit-diagnostic-stream
         :stage1-driver-emit-proof-artifact
         :stage1-driver-record-provenance]
        direct-stages (:direct-stages driver)]
    (when-not (map? driver)
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV003" reader-source-path driver
       {:missing-fields [:stage1-reader-compiler-driver]}))
    (doseq [field [:engine :entrypoint :replaces :base-runtime
                   :core-bootstrap-builtins :input :output :artifact
                   :diagnostic-stream :proof-kind :host-boundaries
                   :seed-orchestration-fallbacks :driver-operations
                   :direct-stages :uses-runtimes :uses-builtins
                   :uses-executors :preserves :diagnostics
                   :provenance]]
      (when-not (contains? driver field)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV007" reader-source-path driver
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-compiler-driver-v1 (:engine driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-compiler-driver
                 (:entrypoint driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:entrypoint]}))
    (when-not (contains? (set (:replaces driver))
                         :clojure-seed-orchestration)
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-core-bootstrap-runtime
                 (:base-runtime driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:base-runtime]}))
    (when-not (= :stage1-reader-core-bootstrap-builtins
                 (:core-bootstrap-builtins driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:core-bootstrap-builtins]}))
    (when-not (= [:source-path :source-text] (:input driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records (:output driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-compiler-driver-artifact
                 (:artifact driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV004" reader-source-path driver
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-compiler-driver-diagnostic-stream
                 (:diagnostic-stream driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV005" reader-source-path driver
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-compiler-driver-proof
                 (:proof-kind driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV004" reader-source-path driver
       {:missing-fields [:proof-kind]}))
    (when-not (set/subset? #{:host-command-invocation
                             :host-file-read}
                           (set (:host-boundaries driver)))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:host-boundaries]}))
    (when-not (= [] (:seed-orchestration-fallbacks driver))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV006" reader-source-path driver
       {:seed-orchestration-fallbacks
        (:seed-orchestration-fallbacks driver)}))
    (let [driver-operations (:driver-operations driver)
          operation-names (set driver-operations)
          required-operation-set
          (set stage1-reader-compiler-driver-required-operations)]
      (when-not (vector? driver-operations)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV003" reader-source-path driver
         {:missing-fields [:driver-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV002" reader-source-path driver-operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-compiler-driver-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? #{:stage1-reader-compiler-driver
                             :stage1-reader-core-bootstrap-runtime
                             :stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes driver)))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins driver)))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors driver)))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source (get-in driver [:provenance :owner]))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-compiler-driver-orchestration-replacement
                 (get-in driver [:provenance :purpose]))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-clojure-seed-orchestration-with-gravity-compiler-driver
                 (get-in driver [:provenance :retirement-objective]))
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path driver
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV007" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc driver
           :compiler-driver-id
           (str "sha256:" (sha256-hex (pr-str driver))))))

(defn stage1-reader-compiler-driver-entrypoint-valid?
  [definitions]
  (let [definition (get definitions
                        stage1-reader-compiler-driver-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-compiler-driver
               source-path
               source-text
               stage1-reader-compiler-driver
               stage1-reader-core-bootstrap-runtime
               stage1-reader-core-bootstrap-builtins))
            (:body definition)))))

(defn stage1-reader-execute-compiler-driver
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver]
  (let [driver-id (:compiler-driver-id compiler-driver)
        driver-operations (:driver-operations compiler-driver)
        annotate-with-driver
        (fn [record]
          (assoc record
                 :compiler-driver-id driver-id
                 :compiler-driver-engine (:engine compiler-driver)
                 :seed-orchestration-replacement
                 :gravity-reader-compiler-driver-v1))
        records
        (stage1-reader-execute-core-bootstrap-runtime
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins)
        annotated-records (mapv annotate-with-driver records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (-> (or trace {})
                   (assoc :compiler-driver compiler-driver)
                   (assoc :compiler-driver-operation-coverage
                          {:required
                           stage1-reader-compiler-driver-required-operations
                           :provided driver-operations
                           :covered?
                           (set/subset?
                            (set stage1-reader-compiler-driver-required-operations)
                            (set driver-operations))})
                   (assoc :seed-orchestration-fallbacks
                          (:seed-orchestration-fallbacks compiler-driver))
                   (assoc :host-command-boundaries
                          (:host-boundaries compiler-driver))
                   (assoc :artifact-routing
                          {:artifact (:artifact compiler-driver)
                           :diagnostic-stream
                           (:diagnostic-stream compiler-driver)
                           :proof-kind (:proof-kind compiler-driver)})
                   (update :gravity-runtimes (fnil conj [])
                           :stage1-reader-compiler-driver)
                   (update :character-stream annotate-with-driver)
                   (update :token-stream annotate-with-driver)
                   (assoc :compiler-driver-applied
                          {:driver-id driver-id
                           :operation-count (count driver-operations)
                           :host-boundaries
                           (:host-boundaries compiler-driver)
                           :seed-orchestration-fallbacks
                           (:seed-orchestration-fallbacks
                            compiler-driver)})))))
    annotated-records))

(defn stage1-reader-execute-compiler-driver-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-compiler-driver-entrypoint-valid?
               definitions)
      (stage1-reader-compiler-driver-fail!
       "STAGE1DRV001" reader-source-path
       stage1-reader-compiler-driver-entrypoint
       {:missing-fields [stage1-reader-compiler-driver-entrypoint]}))
    {:records
     (stage1-reader-execute-compiler-driver
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins
      compiler-driver)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins
     :compiler-driver compiler-driver}))

(defn stage1-reader-compiler-driver-diagnostic-stream
  [source-path compiler-driver-id]
  {:artifact :gravity/stage1-reader-compiler-driver-diagnostic-stream
   :stage :stage1-reader-compiler-driver
   :source-path source-path
   :compiler-driver-id compiler-driver-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-compiler-driver
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-compiler-driver-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-compiler-driver-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-compiler-driver-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-compiler-driver-diagnostic-stream
                           :diagnostics])))
        driver (:stage1-reader-compiler-driver artifact)
        runtime (:stage1-reader-core-bootstrap-runtime artifact)
        builtins (:stage1-reader-core-bootstrap-builtins artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names (set (:driver-operations driver))
        direct-stages (mapv :op (:direct-stages driver))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-compiler-driver-entrypoint-verified?
     (= stage1-reader-compiler-driver-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :compiler-driver-authored?
     (and (= :gravity-reader-compiler-driver-v1 (:engine driver))
          (= :gravity-source (get-in driver [:provenance :owner]))
          (= :reader-compiler-driver-orchestration-replacement
             (get-in driver [:provenance :purpose])))
     :compiler-driver-direct-stages-covered?
     (= [:stage1-driver-load-reader-source
         :stage1-driver-resolve-entrypoint
         :stage1-driver-execute-core-bootstrap-runtime
         :stage1-driver-emit-diagnostic-stream
         :stage1-driver-emit-proof-artifact
         :stage1-driver-record-provenance]
        direct-stages)
     :compiler-driver-operations-covered?
     (set/subset?
      (set stage1-reader-compiler-driver-required-operations)
      operation-names)
     :compiler-driver-links-runtime?
     (= :stage1-reader-core-bootstrap-runtime
        (:base-runtime driver))
     :compiler-driver-links-builtins?
     (= :stage1-reader-core-bootstrap-builtins
        (:core-bootstrap-builtins driver))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-compiler-driver-artifact
        (:artifact driver)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-compiler-driver-diagnostic-stream
        (:diagnostic-stream driver)
        (get-in artifact
                [:stage1-reader-compiler-driver-diagnostic-stream
                 :artifact]))
     :core-bootstrap-runtime-authored?
     (= :gravity-reader-core-bootstrap-runtime-v1 (:engine runtime))
     :core-bootstrap-builtins-authored?
     (= :gravity-core-bootstrap-builtins-v1 (:engine builtins))
     :seed-builtins-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-seed-builtins?]))
     :seed-orchestration-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-seed-orchestration?]))
     :clojure-driver-runner-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :clojure-driver-runner?]))
     :host-command-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :host-command-invocation?]))
     :host-file-read-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :host-file-read?]))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-compiler-driver
                    :stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-compiler-driver-v1
             (:compiler-driver-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-compiler-driver-v1
             (:compiler-driver-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-core-bootstrap-builtins-v1
                           (:core-bootstrap-builtins-engine %))
                        (= :gravity-reader-compiler-driver-v1
                           (:compiler-driver-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-compiler-driver-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? true
      :host-command-invocation? true
      :host-file-read? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-clojure-driver-runner-and-host-io-with-gravity-runtime-entrypoint}
     :status :complete}))

(defn stage1-reader-compiler-driver-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-compiler-driver-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        core-bootstrap-runtime (:core-bootstrap-runtime runtime-result)
        core-bootstrap-builtins (:core-bootstrap-builtins runtime-result)
        compiler-driver (:compiler-driver runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        seed-builtin-fallbacks
        (vec (distinct (:seed-builtin-fallbacks trace-value)))
        seed-orchestration-fallbacks
        (vec (distinct (:seed-orchestration-fallbacks trace-value)))
        host-command-boundaries
        (vec (distinct (:host-command-boundaries trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        compiler-driver-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-compiler-driver-entrypoint
                       :compiler-driver compiler-driver
                       :core-bootstrap-runtime
                       core-bootstrap-runtime
                       :core-bootstrap-builtins
                       core-bootstrap-builtins})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-compiler-driver-artifact
           :phase "15"
           :task "P15-S16"
           :stage :stage1-reader-compiler-driver
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint stage1-reader-compiler-driver-entrypoint
           :compiler-driver-artifact-id compiler-driver-artifact-id
           :reader-compiler-driver-id
           (:compiler-driver-id compiler-driver)
           :reader-core-bootstrap-runtime-id
           (:core-bootstrap-runtime-id core-bootstrap-runtime)
           :reader-core-bootstrap-builtins-id
           (:core-bootstrap-builtins-id core-bootstrap-builtins)
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :seed-builtin-fallbacks seed-builtin-fallbacks
           :seed-orchestration-fallbacks
           seed-orchestration-fallbacks
           :host-command-boundaries host-command-boundaries
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? false
            :clojure-seed-orchestration? false
            :clojure-driver-runner? true
            :host-command-invocation? true
            :host-file-read? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-compiler-driver compiler-driver
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-compiler-driver-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins
                   :compiler-driver)
           :stage0-comparison comparison
           :accepted-stage1-reader-compiler-driver-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :compiler-driver-id (:compiler-driver-id compiler-driver)}]
           :rejected-stage1-reader-compiler-driver-fixtures
           stage1-reader-compiler-driver-rejected-fixture-records
           :stage1-reader-compiler-driver-diagnostic-stream
           (stage1-reader-compiler-driver-diagnostic-stream
            source-path
            (:compiler-driver-id compiler-driver))
           :stage1-reader-compiler-driver-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-compiler-driver-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-compiler-driver-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV004" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact compiler-driver) (:kind artifact-base))
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV004" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream compiler-driver)
                   (get-in artifact-base
                           [:stage1-reader-compiler-driver-diagnostic-stream
                            :artifact]))
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV005" source-path artifact-base
         {:missing-fields [:diagnostic-stream]}))
      (when (seq host-primitives)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV006" source-path trace-value
         {:host-primitives host-primitives}))
      (when (seq seed-builtin-fallbacks)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV006" source-path trace-value
         {:seed-builtin-fallbacks seed-builtin-fallbacks}))
      (when (seq seed-orchestration-fallbacks)
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV006" source-path trace-value
         {:seed-orchestration-fallbacks
          seed-orchestration-fallbacks}))
      (when (seq (:seed-orchestration-fallbacks compiler-driver))
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV006" source-path compiler-driver
         {:seed-orchestration-fallbacks
          (:seed-orchestration-fallbacks compiler-driver)}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-runtime-interpreter?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-instruction-executor?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-binary-runner?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-character-stream-implementation?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-seed-builtins?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-seed-orchestration?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :clojure-driver-runner?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :host-command-invocation?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :host-file-read?])))
        (stage1-reader-compiler-driver-fail!
         "STAGE1DRV007" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-compiler-driver-proof artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id (c4-artifact-id (assoc artifact-base
                                                   :capability-based-proof
                                                   capability-proof)))))))

(defn stage1-reader-compiler-driver-file-artifact
  [path]
  (stage1-reader-compiler-driver-source-artifact path (slurp path)))

(def stage1-reader-runtime-entrypoint-required-operations
  [:decode-command
   :open-source-file
   :deliver-source-bytes
   :execute-compiler-driver
   :route-artifact-output
   :map-process-exit
   :record-os-boundary])

(defn stage1-reader-runtime-entrypoint-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-runtime-entrypoint-from-definitions
  [reader-source-path definitions]
  (let [runtime-entrypoint
        (stage1-reader-runtime-entrypoint-literal-definition-value
         reader-source-path definitions
         'stage1-reader-runtime-entrypoint)
        diagnostics (:diagnostics runtime-entrypoint)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint :unsupported-runtime-operation
                 :missing-runtime-entrypoint-record
                 :source-routing-divergence :artifact-output-divergence
                 :process-exit-divergence :illegal-runner-fallback
                 :invalid-runtime-entrypoint])
        required-stages
        [:stage1-runtime-entrypoint-decode-command
         :stage1-runtime-entrypoint-open-source
         :stage1-runtime-entrypoint-deliver-source
         :stage1-runtime-entrypoint-execute-driver
         :stage1-runtime-entrypoint-route-artifact
         :stage1-runtime-entrypoint-map-exit]
        direct-stages (:direct-stages runtime-entrypoint)]
    (when-not (map? runtime-entrypoint)
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE003" reader-source-path runtime-entrypoint
       {:missing-fields [:stage1-reader-runtime-entrypoint]}))
    (doseq [field [:engine :entrypoint :replaces :compiler-driver
                   :input :output :artifact :diagnostic-stream
                   :proof-kind :os-boundaries :runner-fallbacks
                   :entrypoint-operations :direct-stages
                   :uses-runtimes :uses-builtins :uses-executors
                   :preserves :diagnostics :provenance]]
      (when-not (contains? runtime-entrypoint field)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE008" reader-source-path runtime-entrypoint
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-runtime-entrypoint-v1
                 (:engine runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-runtime-entrypoint
                 (:entrypoint runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? #{:clojure-driver-runner
                             :host-command-invocation
                             :host-file-read}
                           (set (:replaces runtime-entrypoint)))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-compiler-driver
                 (:compiler-driver runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:compiler-driver]}))
    (when-not (= [:source-path :source-text] (:input runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records
                 (:output runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-runtime-entrypoint-artifact
                 (:artifact runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE005" reader-source-path runtime-entrypoint
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-runtime-entrypoint-diagnostic-stream
                 (:diagnostic-stream runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-runtime-entrypoint-proof
                 (:proof-kind runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE005" reader-source-path runtime-entrypoint
       {:missing-fields [:proof-kind]}))
    (when-not (set/subset? #{:os-process-launch
                             :os-filesystem-read
                             :stdout-stream}
                           (set (:os-boundaries runtime-entrypoint)))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:os-boundaries]}))
    (when-not (= [] (:runner-fallbacks runtime-entrypoint))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE007" reader-source-path runtime-entrypoint
       {:runner-fallbacks (:runner-fallbacks runtime-entrypoint)}))
    (let [entrypoint-operations (:entrypoint-operations runtime-entrypoint)
          operation-names (set entrypoint-operations)
          required-operation-set
          (set stage1-reader-runtime-entrypoint-required-operations)]
      (when-not (vector? entrypoint-operations)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE003" reader-source-path runtime-entrypoint
         {:missing-fields [:entrypoint-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE002" reader-source-path entrypoint-operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-runtime-entrypoint-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? #{:stage1-reader-runtime-entrypoint
                             :stage1-reader-compiler-driver
                             :stage1-reader-core-bootstrap-runtime
                             :stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes runtime-entrypoint)))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins runtime-entrypoint)))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors runtime-entrypoint)))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source
                 (get-in runtime-entrypoint [:provenance :owner]))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-runtime-entrypoint-host-runner-replacement
                 (get-in runtime-entrypoint [:provenance :purpose]))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-clojure-driver-runner-and-host-io-with-gravity-runtime-entrypoint
                 (get-in runtime-entrypoint
                         [:provenance :retirement-objective]))
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path runtime-entrypoint
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE008" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc runtime-entrypoint
           :runtime-entrypoint-id
           (str "sha256:" (sha256-hex (pr-str runtime-entrypoint))))))

(defn stage1-reader-runtime-entrypoint-entrypoint-valid?
  [definitions]
  (let [definition (get definitions
                        stage1-reader-runtime-entrypoint-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-runtime-entrypoint
               source-path
               source-text
               stage1-reader-runtime-entrypoint
               stage1-reader-compiler-driver))
            (:body definition)))))

(defn stage1-reader-execute-runtime-entrypoint
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver
   runtime-entrypoint]
  (let [runtime-entrypoint-id (:runtime-entrypoint-id runtime-entrypoint)
        entrypoint-operations (:entrypoint-operations runtime-entrypoint)
        annotate-with-entrypoint
        (fn [record]
          (assoc record
                 :runtime-entrypoint-id runtime-entrypoint-id
                 :runtime-entrypoint-engine (:engine runtime-entrypoint)
                 :host-runner-replacement
                 :gravity-reader-runtime-entrypoint-v1))
        records
        (stage1-reader-execute-compiler-driver
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins
         compiler-driver)
        annotated-records (mapv annotate-with-entrypoint records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (-> (or trace {})
                   (assoc :runtime-entrypoint runtime-entrypoint)
                   (assoc :runtime-entrypoint-operation-coverage
                          {:required
                           stage1-reader-runtime-entrypoint-required-operations
                           :provided entrypoint-operations
                           :covered?
                           (set/subset?
                            (set stage1-reader-runtime-entrypoint-required-operations)
                            (set entrypoint-operations))})
                   (assoc :runner-fallbacks
                          (:runner-fallbacks runtime-entrypoint))
                   (assoc :os-boundaries
                          (:os-boundaries runtime-entrypoint))
                   (assoc :runtime-artifact-routing
                          {:artifact (:artifact runtime-entrypoint)
                           :diagnostic-stream
                           (:diagnostic-stream runtime-entrypoint)
                           :proof-kind (:proof-kind runtime-entrypoint)})
                   (update :gravity-runtimes (fnil conj [])
                           :stage1-reader-runtime-entrypoint)
                   (update :character-stream annotate-with-entrypoint)
                   (update :token-stream annotate-with-entrypoint)
                   (assoc :runtime-entrypoint-applied
                          {:runtime-entrypoint-id runtime-entrypoint-id
                           :operation-count (count entrypoint-operations)
                           :os-boundaries (:os-boundaries runtime-entrypoint)
                           :runner-fallbacks
                           (:runner-fallbacks runtime-entrypoint)})))))
    annotated-records))

(defn stage1-reader-execute-runtime-entrypoint-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)
        runtime-entrypoint
        (stage1-reader-runtime-entrypoint-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-runtime-entrypoint-entrypoint-valid?
               definitions)
      (stage1-reader-runtime-entrypoint-fail!
       "STAGE1RTE001" reader-source-path
       stage1-reader-runtime-entrypoint-entrypoint
       {:missing-fields [stage1-reader-runtime-entrypoint-entrypoint]}))
    {:records
     (stage1-reader-execute-runtime-entrypoint
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins
      compiler-driver
      runtime-entrypoint)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins
     :compiler-driver compiler-driver
     :runtime-entrypoint runtime-entrypoint}))

(defn stage1-reader-runtime-entrypoint-diagnostic-stream
  [source-path runtime-entrypoint-id]
  {:artifact :gravity/stage1-reader-runtime-entrypoint-diagnostic-stream
   :stage :stage1-reader-runtime-entrypoint
   :source-path source-path
   :runtime-entrypoint-id runtime-entrypoint-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-runtime-entrypoint
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-runtime-entrypoint-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-runtime-entrypoint-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-runtime-entrypoint-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-runtime-entrypoint-diagnostic-stream
                           :diagnostics])))
        runtime-entrypoint (:stage1-reader-runtime-entrypoint artifact)
        compiler-driver (:stage1-reader-compiler-driver artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names (set (:entrypoint-operations runtime-entrypoint))
        direct-stages (mapv :op (:direct-stages runtime-entrypoint))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-runtime-entrypoint-verified?
     (= stage1-reader-runtime-entrypoint-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :runtime-entrypoint-authored?
     (and (= :gravity-reader-runtime-entrypoint-v1
             (:engine runtime-entrypoint))
          (= :gravity-source
             (get-in runtime-entrypoint [:provenance :owner]))
          (= :reader-runtime-entrypoint-host-runner-replacement
             (get-in runtime-entrypoint [:provenance :purpose])))
     :runtime-entrypoint-direct-stages-covered?
     (= [:stage1-runtime-entrypoint-decode-command
         :stage1-runtime-entrypoint-open-source
         :stage1-runtime-entrypoint-deliver-source
         :stage1-runtime-entrypoint-execute-driver
         :stage1-runtime-entrypoint-route-artifact
         :stage1-runtime-entrypoint-map-exit]
        direct-stages)
     :runtime-entrypoint-operations-covered?
     (set/subset?
      (set stage1-reader-runtime-entrypoint-required-operations)
      operation-names)
     :runtime-entrypoint-links-driver?
     (= :stage1-reader-compiler-driver
        (:compiler-driver runtime-entrypoint))
     :compiler-driver-authored?
     (= :gravity-reader-compiler-driver-v1 (:engine compiler-driver))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-runtime-entrypoint-artifact
        (:artifact runtime-entrypoint)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-runtime-entrypoint-diagnostic-stream
        (:diagnostic-stream runtime-entrypoint)
        (get-in artifact
                [:stage1-reader-runtime-entrypoint-diagnostic-stream
                 :artifact]))
     :seed-builtins-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-seed-builtins?]))
     :seed-orchestration-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-seed-orchestration?]))
     :clojure-driver-runner-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :clojure-driver-runner?]))
     :host-command-invocation-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :host-command-invocation?]))
     :host-file-read-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :host-file-read?]))
     :os-process-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :os-process-boundary?]))
     :os-filesystem-read-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :os-filesystem-read-boundary?]))
     :stdout-boundary-explicit?
     (true? (get-in artifact [:trusted-boundary
                              :stdout-boundary?]))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :runner-fallbacks-empty?
     (= [] (:runner-fallbacks artifact))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-runtime-entrypoint
                    :stage1-reader-compiler-driver
                    :stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-runtime-entrypoint-v1
             (:runtime-entrypoint-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-runtime-entrypoint-v1
             (:runtime-entrypoint-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-compiler-driver-v1
                           (:compiler-driver-engine %))
                        (= :gravity-reader-runtime-entrypoint-v1
                           (:runtime-entrypoint-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-runtime-entrypoint-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? false
      :host-command-invocation? false
      :host-file-read? false
      :os-process-boundary? true
      :os-filesystem-read-boundary? true
      :stdout-boundary? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-os-process-filesystem-and-stdout-boundaries-with-bootstrapped-runtime-image}
     :status :complete}))

(defn stage1-reader-runtime-entrypoint-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-runtime-entrypoint-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        core-bootstrap-runtime (:core-bootstrap-runtime runtime-result)
        core-bootstrap-builtins (:core-bootstrap-builtins runtime-result)
        compiler-driver (:compiler-driver runtime-result)
        runtime-entrypoint (:runtime-entrypoint runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        seed-builtin-fallbacks
        (vec (distinct (:seed-builtin-fallbacks trace-value)))
        seed-orchestration-fallbacks
        (vec (distinct (:seed-orchestration-fallbacks trace-value)))
        runner-fallbacks (vec (distinct (:runner-fallbacks trace-value)))
        os-boundaries (vec (distinct (:os-boundaries trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        runtime-entrypoint-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-runtime-entrypoint-entrypoint
                       :runtime-entrypoint runtime-entrypoint
                       :compiler-driver compiler-driver
                       :core-bootstrap-runtime core-bootstrap-runtime
                       :core-bootstrap-builtins
                       core-bootstrap-builtins})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-runtime-entrypoint-artifact
           :phase "15"
           :task "P15-S17"
           :stage :stage1-reader-runtime-entrypoint
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint
           stage1-reader-runtime-entrypoint-entrypoint
           :runtime-entrypoint-artifact-id
           runtime-entrypoint-artifact-id
           :reader-runtime-entrypoint-id
           (:runtime-entrypoint-id runtime-entrypoint)
           :reader-compiler-driver-id
           (:compiler-driver-id compiler-driver)
           :reader-core-bootstrap-runtime-id
           (:core-bootstrap-runtime-id core-bootstrap-runtime)
           :reader-core-bootstrap-builtins-id
           (:core-bootstrap-builtins-id core-bootstrap-builtins)
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :seed-builtin-fallbacks seed-builtin-fallbacks
           :seed-orchestration-fallbacks
           seed-orchestration-fallbacks
           :runner-fallbacks runner-fallbacks
           :os-boundaries os-boundaries
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? false
            :clojure-seed-orchestration? false
            :clojure-driver-runner? false
            :host-command-invocation? false
            :host-file-read? false
            :os-process-boundary? true
            :os-filesystem-read-boundary? true
            :stdout-boundary? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-runtime-entrypoint runtime-entrypoint
           :stage1-reader-compiler-driver compiler-driver
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-runtime-entrypoint-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins
                   :compiler-driver
                   :runtime-entrypoint)
           :stage0-comparison comparison
           :accepted-stage1-reader-runtime-entrypoint-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :runtime-entrypoint-id
             (:runtime-entrypoint-id runtime-entrypoint)}]
           :rejected-stage1-reader-runtime-entrypoint-fixtures
           stage1-reader-runtime-entrypoint-rejected-fixture-records
           :stage1-reader-runtime-entrypoint-diagnostic-stream
           (stage1-reader-runtime-entrypoint-diagnostic-stream
            source-path
            (:runtime-entrypoint-id runtime-entrypoint))
           :stage1-reader-runtime-entrypoint-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-runtime-entrypoint-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-runtime-entrypoint-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE004" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact runtime-entrypoint) (:kind artifact-base))
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE005" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream runtime-entrypoint)
                   (get-in artifact-base
                           [:stage1-reader-runtime-entrypoint-diagnostic-stream
                            :artifact]))
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE008" source-path artifact-base
         {:missing-fields [:diagnostic-stream]}))
      (when (seq host-primitives)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE007" source-path trace-value
         {:host-primitives host-primitives}))
      (when (seq seed-builtin-fallbacks)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE007" source-path trace-value
         {:seed-builtin-fallbacks seed-builtin-fallbacks}))
      (when (seq seed-orchestration-fallbacks)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE007" source-path trace-value
         {:seed-orchestration-fallbacks
          seed-orchestration-fallbacks}))
      (when (seq runner-fallbacks)
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE007" source-path trace-value
         {:runner-fallbacks runner-fallbacks}))
      (when (seq (:runner-fallbacks runtime-entrypoint))
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE007" source-path runtime-entrypoint
         {:runner-fallbacks (:runner-fallbacks runtime-entrypoint)}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :clojure-driver-runner?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :host-command-invocation?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :host-file-read?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :os-process-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :os-filesystem-read-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :stdout-boundary?])))
        (stage1-reader-runtime-entrypoint-fail!
         "STAGE1RTE008" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-runtime-entrypoint-proof artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id (c4-artifact-id (assoc artifact-base
                                                   :capability-based-proof
                                                   capability-proof)))))))

(defn stage1-reader-runtime-entrypoint-file-artifact
  [path]
  (stage1-reader-runtime-entrypoint-source-artifact path (slurp path)))

(def stage1-reader-runtime-image-required-operations
  [:load-runtime-image
   :install-runtime-entrypoint
   :mount-source-bytes
   :execute-runtime-entrypoint
   :route-stdout-stream
   :emit-runtime-artifact
   :record-machine-boundary])

(defn stage1-reader-runtime-image-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-runtime-image-from-definitions
  [reader-source-path definitions]
  (let [runtime-image
        (stage1-reader-runtime-image-literal-definition-value
         reader-source-path definitions
         'stage1-reader-runtime-image)
        diagnostics (:diagnostics runtime-image)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint
                 :unsupported-runtime-image-operation
                 :missing-runtime-image-record
                 :filesystem-authority-divergence
                 :stdout-routing-divergence
                 :runtime-image-provenance-gap
                 :illegal-os-boundary-fallback
                 :invalid-runtime-image])
        required-stages
        [:stage1-runtime-image-load
         :stage1-runtime-image-install-entrypoint
         :stage1-runtime-image-mount-source
         :stage1-runtime-image-execute-entrypoint
         :stage1-runtime-image-route-stdout
         :stage1-runtime-image-emit-artifact
         :stage1-runtime-image-record-machine-boundary]
        direct-stages (:direct-stages runtime-image)]
    (when-not (map? runtime-image)
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG003" reader-source-path runtime-image
       {:missing-fields [:stage1-reader-runtime-image]}))
    (doseq [field [:engine :entrypoint :replaces :runtime-entrypoint
                   :input :output :artifact :diagnostic-stream
                   :proof-kind :os-boundaries :machine-boundaries
                   :image-fallbacks :runtime-image-operations
                   :direct-stages :uses-runtimes :uses-builtins
                   :uses-executors :preserves :diagnostics :provenance]]
      (when-not (contains? runtime-image field)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG008" reader-source-path runtime-image
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-runtime-image-v1 (:engine runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-runtime-image
                 (:entrypoint runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? #{:os-process-launch
                             :os-filesystem-read
                             :stdout-stream}
                           (set (:replaces runtime-image)))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-runtime-entrypoint
                 (:runtime-entrypoint runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:runtime-entrypoint]}))
    (when-not (= [:runtime-image :source-path :source-text]
                 (:input runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records
                 (:output runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-runtime-image-artifact
                 (:artifact runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG004" reader-source-path runtime-image
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-runtime-image-diagnostic-stream
                 (:diagnostic-stream runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-runtime-image-proof
                 (:proof-kind runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG006" reader-source-path runtime-image
       {:missing-fields [:proof-kind]}))
    (when-not (= [] (:os-boundaries runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG007" reader-source-path runtime-image
       {:os-boundaries (:os-boundaries runtime-image)}))
    (when-not (set/subset? #{:machine-instruction-dispatch
                             :kernel-process-scheduler
                             :artifact-loader}
                           (set (:machine-boundaries runtime-image)))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG006" reader-source-path runtime-image
       {:missing-fields [:machine-boundaries]}))
    (when-not (= [] (:image-fallbacks runtime-image))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG007" reader-source-path runtime-image
       {:image-fallbacks (:image-fallbacks runtime-image)}))
    (let [runtime-image-operations (:runtime-image-operations runtime-image)
          operation-names (set runtime-image-operations)
          required-operation-set
          (set stage1-reader-runtime-image-required-operations)]
      (when-not (vector? runtime-image-operations)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG003" reader-source-path runtime-image
         {:missing-fields [:runtime-image-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG002" reader-source-path runtime-image-operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-runtime-image-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? #{:stage1-reader-runtime-image
                             :stage1-reader-runtime-entrypoint
                             :stage1-reader-compiler-driver
                             :stage1-reader-core-bootstrap-runtime
                             :stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes runtime-image)))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins runtime-image)))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors runtime-image)))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path runtime-image
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source
                 (get-in runtime-image [:provenance :owner]))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG006" reader-source-path runtime-image
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-runtime-image-os-boundary-replacement
                 (get-in runtime-image [:provenance :purpose]))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG006" reader-source-path runtime-image
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-os-process-filesystem-and-stdout-boundaries-with-bootstrapped-runtime-image
                 (get-in runtime-image
                         [:provenance :retirement-objective]))
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG006" reader-source-path runtime-image
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG008" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc runtime-image
           :runtime-image-id
           (str "sha256:" (sha256-hex (pr-str runtime-image))))))

(defn stage1-reader-runtime-image-entrypoint-valid?
  [definitions]
  (let [definition (get definitions stage1-reader-runtime-image-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-runtime-image
               source-path
               source-text
               stage1-reader-runtime-image
               stage1-reader-runtime-entrypoint))
            (:body definition)))))

(defn stage1-reader-execute-runtime-image
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver
   runtime-entrypoint
   runtime-image]
  (let [runtime-image-id (:runtime-image-id runtime-image)
        runtime-image-operations (:runtime-image-operations runtime-image)
        annotate-with-runtime-image
        (fn [record]
          (assoc record
                 :runtime-image-id runtime-image-id
                 :runtime-image-engine (:engine runtime-image)
                 :bootstrapped-runtime-image
                 :gravity-reader-runtime-image-v1))
        records
        (stage1-reader-execute-runtime-entrypoint
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins
         compiler-driver
         runtime-entrypoint)
        annotated-records (mapv annotate-with-runtime-image records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (let [prior-os-boundaries (:os-boundaries trace)]
                 (-> (or trace {})
                     (assoc :runtime-image runtime-image)
                     (assoc :runtime-image-operation-coverage
                            {:required
                             stage1-reader-runtime-image-required-operations
                             :provided runtime-image-operations
                             :covered?
                             (set/subset?
                              (set stage1-reader-runtime-image-required-operations)
                              (set runtime-image-operations))})
                     (assoc :replaced-os-boundaries prior-os-boundaries)
                     (assoc :os-boundaries (:os-boundaries runtime-image))
                     (assoc :machine-boundaries
                            (:machine-boundaries runtime-image))
                     (assoc :image-fallbacks
                            (:image-fallbacks runtime-image))
                     (assoc :runtime-image-artifact-routing
                            {:artifact (:artifact runtime-image)
                             :diagnostic-stream
                             (:diagnostic-stream runtime-image)
                             :proof-kind (:proof-kind runtime-image)})
                     (update :gravity-runtimes (fnil conj [])
                             :stage1-reader-runtime-image)
                     (update :character-stream annotate-with-runtime-image)
                     (update :token-stream annotate-with-runtime-image)
                     (assoc :runtime-image-applied
                            {:runtime-image-id runtime-image-id
                             :operation-count
                             (count runtime-image-operations)
                             :replaced-os-boundaries prior-os-boundaries
                             :machine-boundaries
                             (:machine-boundaries runtime-image)
                             :image-fallbacks
                             (:image-fallbacks runtime-image)}))))))
    annotated-records))

(defn stage1-reader-execute-runtime-image-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)
        runtime-entrypoint
        (stage1-reader-runtime-entrypoint-from-definitions
         reader-source-path definitions)
        runtime-image
        (stage1-reader-runtime-image-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-runtime-image-entrypoint-valid? definitions)
      (stage1-reader-runtime-image-fail!
       "STAGE1IMG001" reader-source-path
       stage1-reader-runtime-image-entrypoint
       {:missing-fields [stage1-reader-runtime-image-entrypoint]}))
    {:records
     (stage1-reader-execute-runtime-image
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins
      compiler-driver
      runtime-entrypoint
      runtime-image)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins
     :compiler-driver compiler-driver
     :runtime-entrypoint runtime-entrypoint
     :runtime-image runtime-image}))

(defn stage1-reader-runtime-image-diagnostic-stream
  [source-path runtime-image-id]
  {:artifact :gravity/stage1-reader-runtime-image-diagnostic-stream
   :stage :stage1-reader-runtime-image
   :source-path source-path
   :runtime-image-id runtime-image-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-runtime-image
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-runtime-image-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-runtime-image-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-runtime-image-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-runtime-image-diagnostic-stream
                           :diagnostics])))
        runtime-image (:stage1-reader-runtime-image artifact)
        runtime-entrypoint (:stage1-reader-runtime-entrypoint artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names (set (:runtime-image-operations runtime-image))
        direct-stages (mapv :op (:direct-stages runtime-image))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-runtime-image-verified?
     (= stage1-reader-runtime-image-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :runtime-image-authored?
     (and (= :gravity-reader-runtime-image-v1
             (:engine runtime-image))
          (= :gravity-source
             (get-in runtime-image [:provenance :owner]))
          (= :reader-runtime-image-os-boundary-replacement
             (get-in runtime-image [:provenance :purpose])))
     :runtime-image-direct-stages-covered?
     (= [:stage1-runtime-image-load
         :stage1-runtime-image-install-entrypoint
         :stage1-runtime-image-mount-source
         :stage1-runtime-image-execute-entrypoint
         :stage1-runtime-image-route-stdout
         :stage1-runtime-image-emit-artifact
         :stage1-runtime-image-record-machine-boundary]
        direct-stages)
     :runtime-image-operations-covered?
     (set/subset?
      (set stage1-reader-runtime-image-required-operations)
      operation-names)
     :runtime-image-links-entrypoint?
     (= :stage1-reader-runtime-entrypoint
        (:runtime-entrypoint runtime-image))
     :runtime-entrypoint-authored?
     (= :gravity-reader-runtime-entrypoint-v1 (:engine runtime-entrypoint))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-runtime-image-artifact
        (:artifact runtime-image)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-runtime-image-diagnostic-stream
        (:diagnostic-stream runtime-image)
        (get-in artifact
                [:stage1-reader-runtime-image-diagnostic-stream
                 :artifact]))
     :os-process-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :os-process-boundary?]))
     :os-filesystem-read-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :os-filesystem-read-boundary?]))
     :stdout-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :stdout-boundary?]))
     :machine-boundaries-explicit?
     (and (true? (get-in artifact [:trusted-boundary
                                   :machine-boundary?]))
          (true? (get-in artifact [:trusted-boundary
                                   :kernel-process-scheduler-boundary?]))
          (true? (get-in artifact [:trusted-boundary
                                   :artifact-loader-boundary?])))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :runner-fallbacks-empty?
     (= [] (:runner-fallbacks artifact))
     :os-boundaries-empty?
     (= [] (:os-boundaries artifact))
     :image-fallbacks-empty?
     (= [] (:image-fallbacks artifact))
     :replaced-os-boundaries-recorded?
     (= #{:os-process-launch :os-filesystem-read :stdout-stream}
        (set (:replaced-os-boundaries artifact)))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-runtime-image
                    :stage1-reader-runtime-entrypoint
                    :stage1-reader-compiler-driver
                    :stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-runtime-image-v1
             (:runtime-image-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-runtime-image-v1
             (:runtime-image-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-runtime-entrypoint-v1
                           (:runtime-entrypoint-engine %))
                        (= :gravity-reader-runtime-image-v1
                           (:runtime-image-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-runtime-image-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? false
      :host-command-invocation? false
      :host-file-read? false
      :os-process-boundary? false
      :os-filesystem-read-boundary? false
      :stdout-boundary? false
      :machine-boundary? true
      :kernel-process-scheduler-boundary? true
      :artifact-loader-boundary? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-machine-kernel-and-artifact-loader-boundaries-with-verified-boot-chain}
     :status :complete}))

(defn stage1-reader-runtime-image-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-runtime-image-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        core-bootstrap-runtime (:core-bootstrap-runtime runtime-result)
        core-bootstrap-builtins (:core-bootstrap-builtins runtime-result)
        compiler-driver (:compiler-driver runtime-result)
        runtime-entrypoint (:runtime-entrypoint runtime-result)
        runtime-image (:runtime-image runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        seed-builtin-fallbacks
        (vec (distinct (:seed-builtin-fallbacks trace-value)))
        seed-orchestration-fallbacks
        (vec (distinct (:seed-orchestration-fallbacks trace-value)))
        runner-fallbacks (vec (distinct (:runner-fallbacks trace-value)))
        os-boundaries (vec (distinct (:os-boundaries trace-value)))
        replaced-os-boundaries
        (vec (distinct (:replaced-os-boundaries trace-value)))
        machine-boundaries (vec (distinct (:machine-boundaries trace-value)))
        image-fallbacks (vec (distinct (:image-fallbacks trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        runtime-image-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint stage1-reader-runtime-image-entrypoint
                       :runtime-image runtime-image
                       :runtime-entrypoint runtime-entrypoint
                       :compiler-driver compiler-driver
                       :core-bootstrap-runtime core-bootstrap-runtime
                       :core-bootstrap-builtins
                       core-bootstrap-builtins})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-runtime-image-artifact
           :phase "15"
           :task "P15-S18"
           :stage :stage1-reader-runtime-image
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint stage1-reader-runtime-image-entrypoint
           :runtime-image-artifact-id runtime-image-artifact-id
           :reader-runtime-image-id
           (:runtime-image-id runtime-image)
           :reader-runtime-entrypoint-id
           (:runtime-entrypoint-id runtime-entrypoint)
           :reader-compiler-driver-id
           (:compiler-driver-id compiler-driver)
           :reader-core-bootstrap-runtime-id
           (:core-bootstrap-runtime-id core-bootstrap-runtime)
           :reader-core-bootstrap-builtins-id
           (:core-bootstrap-builtins-id core-bootstrap-builtins)
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :seed-builtin-fallbacks seed-builtin-fallbacks
           :seed-orchestration-fallbacks
           seed-orchestration-fallbacks
           :runner-fallbacks runner-fallbacks
           :os-boundaries os-boundaries
           :replaced-os-boundaries replaced-os-boundaries
           :machine-boundaries machine-boundaries
           :image-fallbacks image-fallbacks
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? false
            :clojure-seed-orchestration? false
            :clojure-driver-runner? false
            :host-command-invocation? false
            :host-file-read? false
            :os-process-boundary? false
            :os-filesystem-read-boundary? false
            :stdout-boundary? false
            :machine-boundary? true
            :kernel-process-scheduler-boundary? true
            :artifact-loader-boundary? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-runtime-image runtime-image
           :stage1-reader-runtime-entrypoint runtime-entrypoint
           :stage1-reader-compiler-driver compiler-driver
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-runtime-image-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins
                   :compiler-driver
                   :runtime-entrypoint
                   :runtime-image)
           :stage0-comparison comparison
           :accepted-stage1-reader-runtime-image-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :runtime-image-id (:runtime-image-id runtime-image)}]
           :rejected-stage1-reader-runtime-image-fixtures
           stage1-reader-runtime-image-rejected-fixture-records
           :stage1-reader-runtime-image-diagnostic-stream
           (stage1-reader-runtime-image-diagnostic-stream
            source-path
            (:runtime-image-id runtime-image))
           :stage1-reader-runtime-image-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-runtime-image-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-runtime-image-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG004" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact runtime-image) (:kind artifact-base))
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG004" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream runtime-image)
                   (get-in artifact-base
                           [:stage1-reader-runtime-image-diagnostic-stream
                            :artifact]))
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG008" source-path artifact-base
         {:missing-fields [:diagnostic-stream]}))
      (when (seq host-primitives)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG007" source-path trace-value
         {:host-primitives host-primitives}))
      (when (seq seed-builtin-fallbacks)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG007" source-path trace-value
         {:seed-builtin-fallbacks seed-builtin-fallbacks}))
      (when (seq seed-orchestration-fallbacks)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG007" source-path trace-value
         {:seed-orchestration-fallbacks
          seed-orchestration-fallbacks}))
      (when (seq runner-fallbacks)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG007" source-path trace-value
         {:runner-fallbacks runner-fallbacks}))
      (when (seq os-boundaries)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG007" source-path trace-value
         {:os-boundaries os-boundaries}))
      (when (seq image-fallbacks)
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG007" source-path trace-value
         {:image-fallbacks image-fallbacks}))
      (when-not (= #{:os-process-launch :os-filesystem-read :stdout-stream}
                   (set replaced-os-boundaries))
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG004" source-path trace-value
         {:replaced-os-boundaries replaced-os-boundaries}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :os-process-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :os-filesystem-read-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :stdout-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :machine-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :kernel-process-scheduler-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :artifact-loader-boundary?])))
        (stage1-reader-runtime-image-fail!
         "STAGE1IMG008" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-runtime-image-proof artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id (c4-artifact-id (assoc artifact-base
                                                   :capability-based-proof
                                                   capability-proof)))))))

(defn stage1-reader-runtime-image-file-artifact
  [path]
  (stage1-reader-runtime-image-source-artifact path (slurp path)))

(def stage1-reader-verified-boot-chain-required-operations
  [:verify-boot-chain
   :load-runtime-image
   :activate-runtime-image
   :dispatch-machine-instructions
   :schedule-kernel-process
   :load-artifact
   :record-trust-anchor])

(defn stage1-reader-verified-boot-chain-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-verified-boot-chain-from-definitions
  [reader-source-path definitions]
  (let [boot-chain
        (stage1-reader-verified-boot-chain-literal-definition-value
         reader-source-path definitions
         'stage1-reader-verified-boot-chain)
        diagnostics (:diagnostics boot-chain)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint
                 :unsupported-boot-operation
                 :missing-boot-chain-record
                 :artifact-loader-divergence
                 :scheduler-authority-divergence
                 :unreproducible-boot-provenance
                 :illegal-machine-kernel-fallback
                 :invalid-verified-boot-chain])
        required-stages
        [:stage1-boot-chain-verify
         :stage1-boot-chain-load-runtime-image
         :stage1-boot-chain-activate-runtime-image
         :stage1-boot-chain-dispatch-machine-instructions
         :stage1-boot-chain-schedule-kernel-process
         :stage1-boot-chain-load-artifact
         :stage1-boot-chain-record-trust-anchor]
        direct-stages (:direct-stages boot-chain)]
    (when-not (map? boot-chain)
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT003" reader-source-path boot-chain
       {:missing-fields [:stage1-reader-verified-boot-chain]}))
    (doseq [field [:engine :entrypoint :replaces :runtime-image
                   :input :output :artifact :diagnostic-stream
                   :proof-kind :machine-boundaries
                   :trust-anchor-boundaries :boot-chain-fallbacks
                   :boot-chain-operations :direct-stages
                   :uses-runtimes :uses-builtins :uses-executors
                   :preserves :diagnostics :provenance]]
      (when-not (contains? boot-chain field)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT008" reader-source-path boot-chain
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-verified-boot-chain-v1
                 (:engine boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-verified-boot-chain
                 (:entrypoint boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? #{:machine-instruction-dispatch
                             :kernel-process-scheduler
                             :artifact-loader}
                           (set (:replaces boot-chain)))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-runtime-image
                 (:runtime-image boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:runtime-image]}))
    (when-not (= [:verified-boot-chain :runtime-image
                  :source-path :source-text]
                 (:input boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records
                 (:output boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-verified-boot-chain-artifact
                 (:artifact boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT004" reader-source-path boot-chain
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-verified-boot-chain-diagnostic-stream
                 (:diagnostic-stream boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-verified-boot-chain-proof
                 (:proof-kind boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT006" reader-source-path boot-chain
       {:missing-fields [:proof-kind]}))
    (when-not (= [] (:machine-boundaries boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT007" reader-source-path boot-chain
       {:machine-boundaries (:machine-boundaries boot-chain)}))
    (when-not (set/subset? #{:hardware-reset-vector
                             :firmware-root-of-trust
                             :external-auditor-key}
                           (set (:trust-anchor-boundaries boot-chain)))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT006" reader-source-path boot-chain
       {:missing-fields [:trust-anchor-boundaries]}))
    (when-not (= [] (:boot-chain-fallbacks boot-chain))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT007" reader-source-path boot-chain
       {:boot-chain-fallbacks (:boot-chain-fallbacks boot-chain)}))
    (let [boot-chain-operations (:boot-chain-operations boot-chain)
          operation-names (set boot-chain-operations)
          required-operation-set
          (set stage1-reader-verified-boot-chain-required-operations)]
      (when-not (vector? boot-chain-operations)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT003" reader-source-path boot-chain
         {:missing-fields [:boot-chain-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT002" reader-source-path boot-chain-operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-verified-boot-chain-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:direct-stages]}))
    (when-not (set/subset? #{:stage1-reader-verified-boot-chain
                             :stage1-reader-runtime-image
                             :stage1-reader-runtime-entrypoint
                             :stage1-reader-compiler-driver
                             :stage1-reader-core-bootstrap-runtime
                             :stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes boot-chain)))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins boot-chain)))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors boot-chain)))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path boot-chain
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source
                 (get-in boot-chain [:provenance :owner]))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT006" reader-source-path boot-chain
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-verified-boot-chain-machine-boundary-replacement
                 (get-in boot-chain [:provenance :purpose]))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT006" reader-source-path boot-chain
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-machine-kernel-and-artifact-loader-boundaries-with-verified-boot-chain
                 (get-in boot-chain
                         [:provenance :retirement-objective]))
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT006" reader-source-path boot-chain
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT008" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc boot-chain
           :verified-boot-chain-id
           (str "sha256:" (sha256-hex (pr-str boot-chain))))))

(defn stage1-reader-verified-boot-chain-entrypoint-valid?
  [definitions]
  (let [definition (get definitions
                        stage1-reader-verified-boot-chain-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-verified-boot-chain
               source-path
               source-text
               stage1-reader-verified-boot-chain
               stage1-reader-runtime-image))
            (:body definition)))))

(defn stage1-reader-execute-verified-boot-chain
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver
   runtime-entrypoint
   runtime-image
   boot-chain]
  (let [boot-chain-id (:verified-boot-chain-id boot-chain)
        boot-chain-operations (:boot-chain-operations boot-chain)
        annotate-with-boot-chain
        (fn [record]
          (assoc record
                 :verified-boot-chain-id boot-chain-id
                 :verified-boot-chain-engine (:engine boot-chain)
                 :verified-boot-chain
                 :gravity-reader-verified-boot-chain-v1))
        records
        (stage1-reader-execute-runtime-image
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins
         compiler-driver
         runtime-entrypoint
         runtime-image)
        annotated-records (mapv annotate-with-boot-chain records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (let [prior-machine-boundaries (:machine-boundaries trace)]
                 (-> (or trace {})
                     (assoc :verified-boot-chain boot-chain)
                     (assoc :verified-boot-chain-operation-coverage
                            {:required
                             stage1-reader-verified-boot-chain-required-operations
                             :provided boot-chain-operations
                             :covered?
                             (set/subset?
                              (set stage1-reader-verified-boot-chain-required-operations)
                              (set boot-chain-operations))})
                     (assoc :replaced-machine-boundaries
                            prior-machine-boundaries)
                     (assoc :machine-boundaries
                            (:machine-boundaries boot-chain))
                     (assoc :trust-anchor-boundaries
                            (:trust-anchor-boundaries boot-chain))
                     (assoc :boot-chain-fallbacks
                            (:boot-chain-fallbacks boot-chain))
                     (assoc :verified-boot-chain-artifact-routing
                            {:artifact (:artifact boot-chain)
                             :diagnostic-stream
                             (:diagnostic-stream boot-chain)
                             :proof-kind (:proof-kind boot-chain)})
                     (update :gravity-runtimes (fnil conj [])
                             :stage1-reader-verified-boot-chain)
                     (update :character-stream annotate-with-boot-chain)
                     (update :token-stream annotate-with-boot-chain)
                     (assoc :verified-boot-chain-applied
                            {:verified-boot-chain-id boot-chain-id
                             :operation-count
                             (count boot-chain-operations)
                             :replaced-machine-boundaries
                             prior-machine-boundaries
                             :trust-anchor-boundaries
                             (:trust-anchor-boundaries boot-chain)
                             :boot-chain-fallbacks
                             (:boot-chain-fallbacks boot-chain)}))))))
    annotated-records))

(defn stage1-reader-execute-verified-boot-chain-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)
        runtime-entrypoint
        (stage1-reader-runtime-entrypoint-from-definitions
         reader-source-path definitions)
        runtime-image
        (stage1-reader-runtime-image-from-definitions
         reader-source-path definitions)
        boot-chain
        (stage1-reader-verified-boot-chain-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-verified-boot-chain-entrypoint-valid?
               definitions)
      (stage1-reader-verified-boot-chain-fail!
       "STAGE1BOOT001" reader-source-path
       stage1-reader-verified-boot-chain-entrypoint
       {:missing-fields [stage1-reader-verified-boot-chain-entrypoint]}))
    {:records
     (stage1-reader-execute-verified-boot-chain
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins
      compiler-driver
      runtime-entrypoint
      runtime-image
      boot-chain)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins
     :compiler-driver compiler-driver
     :runtime-entrypoint runtime-entrypoint
     :runtime-image runtime-image
     :verified-boot-chain boot-chain}))

(defn stage1-reader-verified-boot-chain-diagnostic-stream
  [source-path boot-chain-id]
  {:artifact :gravity/stage1-reader-verified-boot-chain-diagnostic-stream
   :stage :stage1-reader-verified-boot-chain
   :source-path source-path
   :verified-boot-chain-id boot-chain-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-verified-boot-chain
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-verified-boot-chain-diagnostic-messages id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-verified-boot-chain-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-verified-boot-chain-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-verified-boot-chain-diagnostic-stream
                           :diagnostics])))
        boot-chain (:stage1-reader-verified-boot-chain artifact)
        runtime-image (:stage1-reader-runtime-image artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names (set (:boot-chain-operations boot-chain))
        direct-stages (mapv :op (:direct-stages boot-chain))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))]
    {:gravity-reader-verified-boot-chain-verified?
     (= stage1-reader-verified-boot-chain-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :verified-boot-chain-authored?
     (and (= :gravity-reader-verified-boot-chain-v1
             (:engine boot-chain))
          (= :gravity-source
             (get-in boot-chain [:provenance :owner]))
          (= :reader-verified-boot-chain-machine-boundary-replacement
             (get-in boot-chain [:provenance :purpose])))
     :verified-boot-chain-direct-stages-covered?
     (= [:stage1-boot-chain-verify
         :stage1-boot-chain-load-runtime-image
         :stage1-boot-chain-activate-runtime-image
         :stage1-boot-chain-dispatch-machine-instructions
         :stage1-boot-chain-schedule-kernel-process
         :stage1-boot-chain-load-artifact
         :stage1-boot-chain-record-trust-anchor]
        direct-stages)
     :verified-boot-chain-operations-covered?
     (set/subset?
      (set stage1-reader-verified-boot-chain-required-operations)
      operation-names)
     :verified-boot-chain-links-runtime-image?
     (= :stage1-reader-runtime-image
        (:runtime-image boot-chain))
     :runtime-image-authored?
     (= :gravity-reader-runtime-image-v1 (:engine runtime-image))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-verified-boot-chain-artifact
        (:artifact boot-chain)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-verified-boot-chain-diagnostic-stream
        (:diagnostic-stream boot-chain)
        (get-in artifact
                [:stage1-reader-verified-boot-chain-diagnostic-stream
                 :artifact]))
     :machine-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :machine-boundary?]))
     :kernel-process-scheduler-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :kernel-process-scheduler-boundary?]))
     :artifact-loader-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :artifact-loader-boundary?]))
     :trust-anchor-boundaries-explicit?
     (and (true? (get-in artifact [:trusted-boundary
                                   :hardware-reset-vector-boundary?]))
          (true? (get-in artifact [:trusted-boundary
                                   :firmware-root-of-trust-boundary?]))
          (true? (get-in artifact [:trusted-boundary
                                   :external-auditor-key-boundary?])))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :runner-fallbacks-empty?
     (= [] (:runner-fallbacks artifact))
     :os-boundaries-empty?
     (= [] (:os-boundaries artifact))
     :image-fallbacks-empty?
     (= [] (:image-fallbacks artifact))
     :machine-boundaries-empty?
     (= [] (:machine-boundaries artifact))
     :boot-chain-fallbacks-empty?
     (= [] (:boot-chain-fallbacks artifact))
     :replaced-machine-boundaries-recorded?
     (= #{:machine-instruction-dispatch
          :kernel-process-scheduler
          :artifact-loader}
        (set (:replaced-machine-boundaries artifact)))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-verified-boot-chain
                    :stage1-reader-runtime-image
                    :stage1-reader-runtime-entrypoint
                    :stage1-reader-compiler-driver
                    :stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-verified-boot-chain-v1
             (:verified-boot-chain-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-verified-boot-chain-v1
             (:verified-boot-chain-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-runtime-image-v1
                           (:runtime-image-engine %))
                        (= :gravity-reader-verified-boot-chain-v1
                           (:verified-boot-chain-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-verified-boot-chain-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? false
      :host-command-invocation? false
      :host-file-read? false
      :os-process-boundary? false
      :os-filesystem-read-boundary? false
      :stdout-boundary? false
      :machine-boundary? false
      :kernel-process-scheduler-boundary? false
      :artifact-loader-boundary? false
      :hardware-reset-vector-boundary? true
      :firmware-root-of-trust-boundary? true
      :external-auditor-key-boundary? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-hardware-firmware-and-external-trust-anchors-with-diverse-self-hosted-bootstrap-verification}
     :status :complete}))

(defn stage1-reader-verified-boot-chain-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-verified-boot-chain-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        core-bootstrap-runtime (:core-bootstrap-runtime runtime-result)
        core-bootstrap-builtins (:core-bootstrap-builtins runtime-result)
        compiler-driver (:compiler-driver runtime-result)
        runtime-entrypoint (:runtime-entrypoint runtime-result)
        runtime-image (:runtime-image runtime-result)
        boot-chain (:verified-boot-chain runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        seed-builtin-fallbacks
        (vec (distinct (:seed-builtin-fallbacks trace-value)))
        seed-orchestration-fallbacks
        (vec (distinct (:seed-orchestration-fallbacks trace-value)))
        runner-fallbacks (vec (distinct (:runner-fallbacks trace-value)))
        os-boundaries (vec (distinct (:os-boundaries trace-value)))
        replaced-os-boundaries
        (vec (distinct (:replaced-os-boundaries trace-value)))
        machine-boundaries (vec (distinct (:machine-boundaries trace-value)))
        replaced-machine-boundaries
        (vec (distinct (:replaced-machine-boundaries trace-value)))
        trust-anchor-boundaries
        (vec (distinct (:trust-anchor-boundaries trace-value)))
        image-fallbacks (vec (distinct (:image-fallbacks trace-value)))
        boot-chain-fallbacks
        (vec (distinct (:boot-chain-fallbacks trace-value)))
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        verified-boot-chain-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-verified-boot-chain-entrypoint
                       :verified-boot-chain boot-chain
                       :runtime-image runtime-image
                       :runtime-entrypoint runtime-entrypoint
                       :compiler-driver compiler-driver
                       :core-bootstrap-runtime core-bootstrap-runtime
                       :core-bootstrap-builtins
                       core-bootstrap-builtins})))]
    (let [artifact-base
          {:kind :gravity/stage1-reader-verified-boot-chain-artifact
           :phase "15"
           :task "P15-S19"
           :stage :stage1-reader-verified-boot-chain
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint
           stage1-reader-verified-boot-chain-entrypoint
           :verified-boot-chain-artifact-id
           verified-boot-chain-artifact-id
           :reader-verified-boot-chain-id
           (:verified-boot-chain-id boot-chain)
           :reader-runtime-image-id
           (:runtime-image-id runtime-image)
           :reader-runtime-entrypoint-id
           (:runtime-entrypoint-id runtime-entrypoint)
           :reader-compiler-driver-id
           (:compiler-driver-id compiler-driver)
           :reader-core-bootstrap-runtime-id
           (:core-bootstrap-runtime-id core-bootstrap-runtime)
           :reader-core-bootstrap-builtins-id
           (:core-bootstrap-builtins-id core-bootstrap-builtins)
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :seed-builtin-fallbacks seed-builtin-fallbacks
           :seed-orchestration-fallbacks
           seed-orchestration-fallbacks
           :runner-fallbacks runner-fallbacks
           :os-boundaries os-boundaries
           :replaced-os-boundaries replaced-os-boundaries
           :machine-boundaries machine-boundaries
           :replaced-machine-boundaries replaced-machine-boundaries
           :trust-anchor-boundaries trust-anchor-boundaries
           :image-fallbacks image-fallbacks
           :boot-chain-fallbacks boot-chain-fallbacks
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? false
            :clojure-seed-orchestration? false
            :clojure-driver-runner? false
            :host-command-invocation? false
            :host-file-read? false
            :os-process-boundary? false
            :os-filesystem-read-boundary? false
            :stdout-boundary? false
            :machine-boundary? false
            :kernel-process-scheduler-boundary? false
            :artifact-loader-boundary? false
            :hardware-reset-vector-boundary? true
            :firmware-root-of-trust-boundary? true
            :external-auditor-key-boundary? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-verified-boot-chain boot-chain
           :stage1-reader-runtime-image runtime-image
           :stage1-reader-runtime-entrypoint runtime-entrypoint
           :stage1-reader-compiler-driver compiler-driver
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-verified-boot-chain-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins
                   :compiler-driver
                   :runtime-entrypoint
                   :runtime-image
                   :verified-boot-chain)
           :stage0-comparison comparison
           :accepted-stage1-reader-verified-boot-chain-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :verified-boot-chain-id
             (:verified-boot-chain-id boot-chain)}]
           :rejected-stage1-reader-verified-boot-chain-fixtures
           stage1-reader-verified-boot-chain-rejected-fixture-records
           :stage1-reader-verified-boot-chain-diagnostic-stream
           (stage1-reader-verified-boot-chain-diagnostic-stream
            source-path
            (:verified-boot-chain-id boot-chain))
           :stage1-reader-verified-boot-chain-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-verified-boot-chain-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-verified-boot-chain-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT004" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact boot-chain) (:kind artifact-base))
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT004" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream boot-chain)
                   (get-in artifact-base
                           [:stage1-reader-verified-boot-chain-diagnostic-stream
                            :artifact]))
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT008" source-path artifact-base
         {:missing-fields [:diagnostic-stream]}))
      (when (seq host-primitives)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:host-primitives host-primitives}))
      (when (seq seed-builtin-fallbacks)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:seed-builtin-fallbacks seed-builtin-fallbacks}))
      (when (seq seed-orchestration-fallbacks)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:seed-orchestration-fallbacks
          seed-orchestration-fallbacks}))
      (when (seq runner-fallbacks)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:runner-fallbacks runner-fallbacks}))
      (when (seq os-boundaries)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:os-boundaries os-boundaries}))
      (when (seq machine-boundaries)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:machine-boundaries machine-boundaries}))
      (when (seq image-fallbacks)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:image-fallbacks image-fallbacks}))
      (when (seq boot-chain-fallbacks)
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT007" source-path trace-value
         {:boot-chain-fallbacks boot-chain-fallbacks}))
      (when-not (= #{:machine-instruction-dispatch
                     :kernel-process-scheduler
                     :artifact-loader}
                   (set replaced-machine-boundaries))
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT005" source-path trace-value
         {:replaced-machine-boundaries replaced-machine-boundaries}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :machine-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :kernel-process-scheduler-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :artifact-loader-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :hardware-reset-vector-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :firmware-root-of-trust-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :external-auditor-key-boundary?])))
        (stage1-reader-verified-boot-chain-fail!
         "STAGE1BOOT008" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-verified-boot-chain-proof artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id (c4-artifact-id (assoc artifact-base
                                                   :capability-based-proof
                                                   capability-proof)))))))

(defn stage1-reader-verified-boot-chain-file-artifact
  [path]
  (stage1-reader-verified-boot-chain-source-artifact path (slurp path)))

(def stage1-reader-diverse-bootstrap-verification-required-operations
  [:seed-built-rebuild
   :self-built-rebuild
   :clean-environment-rebuild
   :diverse-toolchain-rebuild
   :compare-bootstrap-traces
   :verify-provenance
   :record-independent-audit])

(defn stage1-reader-diverse-bootstrap-verification-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-diverse-bootstrap-verification-from-definitions
  [reader-source-path definitions]
  (let [diverse-verification
        (stage1-reader-diverse-bootstrap-verification-literal-definition-value
         reader-source-path definitions
         'stage1-reader-diverse-bootstrap-verification)
        diagnostics (:diagnostics diverse-verification)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint
                 :unsupported-verification-operation
                 :missing-diverse-verification-record
                 :single-implementation-self-certification
                 :bootstrap-trace-divergence
                 :unreproducible-diverse-build-provenance
                 :missing-independent-audit-metadata
                 :illegal-trust-anchor-fallback
                 :invalid-diverse-bootstrap-verification])
        required-stages
        [:stage1-diverse-bootstrap-seed-built-rebuild
         :stage1-diverse-bootstrap-self-built-rebuild
         :stage1-diverse-bootstrap-clean-environment-rebuild
         :stage1-diverse-bootstrap-diverse-toolchain-rebuild
         :stage1-diverse-bootstrap-compare-traces
         :stage1-diverse-bootstrap-verify-provenance
         :stage1-diverse-bootstrap-record-independent-audit]
        direct-stages (:direct-stages diverse-verification)
        independent-toolchains (:independent-toolchains diverse-verification)
        toolchain-identities (set (map :identity independent-toolchains))
        trace-comparisons (:bootstrap-trace-comparisons diverse-verification)
        trace-modes (set (map :mode trace-comparisons))
        reproducible-evidence
        (:reproducible-build-evidence diverse-verification)
        audit-record (:independent-audit-record diverse-verification)]
    (when-not (map? diverse-verification)
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV003" reader-source-path diverse-verification
       {:missing-fields [:stage1-reader-diverse-bootstrap-verification]}))
    (doseq [field [:engine :entrypoint :replaces :verified-boot-chain
                   :input :output :artifact :diagnostic-stream
                   :proof-kind :trust-anchor-boundaries
                   :replaced-trust-anchor-boundaries
                   :residual-trust-boundaries
                   :diverse-verification-fallbacks
                   :diverse-verification-operations
                   :independent-toolchains
                   :bootstrap-trace-comparisons
                   :reproducible-build-evidence
                   :independent-audit-record
                   :direct-stages :uses-runtimes :uses-builtins
                   :uses-executors :preserves :diagnostics :provenance]]
      (when-not (contains? diverse-verification field)
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV009" reader-source-path diverse-verification
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-diverse-bootstrap-verification-v1
                 (:engine diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-diverse-bootstrap-verification
                 (:entrypoint diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? #{:hardware-reset-vector
                             :firmware-root-of-trust
                             :external-auditor-key}
                           (set (:replaces diverse-verification)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-verified-boot-chain
                 (:verified-boot-chain diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:verified-boot-chain]}))
    (when-not (= [:diverse-bootstrap-verification
                  :verified-boot-chain
                  :source-path
                  :source-text]
                 (:input diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records
                 (:output diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-diverse-bootstrap-verification-artifact
                 (:artifact diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV005" reader-source-path diverse-verification
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-diverse-bootstrap-verification-diagnostic-stream
                 (:diagnostic-stream diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-diverse-bootstrap-verification-proof
                 (:proof-kind diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV006" reader-source-path diverse-verification
       {:missing-fields [:proof-kind]}))
    (when-not (= [] (:trust-anchor-boundaries diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV008" reader-source-path diverse-verification
       {:trust-anchor-boundaries
        (:trust-anchor-boundaries diverse-verification)}))
    (when-not (set/subset? #{:hardware-reset-vector
                             :firmware-root-of-trust
                             :external-auditor-key}
                           (set (:replaced-trust-anchor-boundaries
                                 diverse-verification)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:replaced-trust-anchor-boundaries]}))
    (when-not (set/subset? #{:physical-device-manufacturing
                             :supply-chain-custody
                             :independent-diversity-review}
                           (set (:residual-trust-boundaries
                                 diverse-verification)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV006" reader-source-path diverse-verification
       {:missing-fields [:residual-trust-boundaries]}))
    (when-not (= [] (:diverse-verification-fallbacks diverse-verification))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV008" reader-source-path diverse-verification
       {:diverse-verification-fallbacks
        (:diverse-verification-fallbacks diverse-verification)}))
    (let [diverse-operations
          (:diverse-verification-operations diverse-verification)
          operation-names (set diverse-operations)
          required-operation-set
          (set stage1-reader-diverse-bootstrap-verification-required-operations)]
      (when-not (vector? diverse-operations)
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV003" reader-source-path diverse-verification
         {:missing-fields [:diverse-verification-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV002" reader-source-path diverse-operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-diverse-bootstrap-verification-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:direct-stages]}))
    (when-not (and (vector? independent-toolchains)
                   (>= (count independent-toolchains) 2)
                   (>= (count toolchain-identities) 2))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV004" reader-source-path independent-toolchains
       {:missing-fields [:independent-toolchains]}))
    (when-not (and (set/subset? #{:manifest-equivalence
                                  :diagnostic-equivalence
                                  :stage0-form-parity}
                                trace-modes)
                   (every? #(= :accepted (:status %)) trace-comparisons))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV005" reader-source-path trace-comparisons
       {:missing-fields [:bootstrap-trace-comparisons]}))
    (when-not (and (= true (:locked-dependencies reproducible-evidence))
                   (= true (:fixed-time reproducible-evidence))
                   (= "C" (:locale reproducible-evidence))
                   (= :canonical (:filesystem-order reproducible-evidence))
                   (= :disabled (:network reproducible-evidence)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV006" reader-source-path reproducible-evidence
       {:missing-fields [:reproducible-build-evidence]}))
    (when-not (and (= :recorded (:status audit-record))
                   (= :independent-diversity-review
                      (:review-kind audit-record))
                   (:reviewer audit-record))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV007" reader-source-path audit-record
       {:missing-fields [:independent-audit-record]}))
    (when-not (set/subset? #{:stage1-reader-diverse-bootstrap-verification
                             :stage1-reader-verified-boot-chain
                             :stage1-reader-runtime-image
                             :stage1-reader-runtime-entrypoint
                             :stage1-reader-compiler-driver
                             :stage1-reader-core-bootstrap-runtime
                             :stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes diverse-verification)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins diverse-verification)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors diverse-verification)))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diverse-verification
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source
                 (get-in diverse-verification [:provenance :owner]))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV006" reader-source-path diverse-verification
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-diverse-bootstrap-trust-anchor-replacement
                 (get-in diverse-verification [:provenance :purpose]))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV006" reader-source-path diverse-verification
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-hardware-firmware-and-external-trust-anchors-with-diverse-self-hosted-bootstrap-verification
                 (get-in diverse-verification
                         [:provenance :retirement-objective]))
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV006" reader-source-path diverse-verification
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV009" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc diverse-verification
           :diverse-bootstrap-verification-id
           (str "sha256:" (sha256-hex (pr-str diverse-verification))))))

(defn stage1-reader-diverse-bootstrap-verification-entrypoint-valid?
  [definitions]
  (let [definition (get definitions
                        stage1-reader-diverse-bootstrap-verification-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-diverse-bootstrap-verification
               source-path
               source-text
               stage1-reader-diverse-bootstrap-verification
               stage1-reader-verified-boot-chain))
            (:body definition)))))

(defn stage1-reader-execute-diverse-bootstrap-verification
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver
   runtime-entrypoint
   runtime-image
   boot-chain
   diverse-verification]
  (let [diverse-verification-id
        (:diverse-bootstrap-verification-id diverse-verification)
        diverse-operations
        (:diverse-verification-operations diverse-verification)
        annotate-with-diverse-verification
        (fn [record]
          (assoc record
                 :diverse-bootstrap-verification-id
                 diverse-verification-id
                 :diverse-bootstrap-verification-engine
                 (:engine diverse-verification)
                 :diverse-bootstrap-verification
                 :gravity-reader-diverse-bootstrap-verification-v1))
        records
        (stage1-reader-execute-verified-boot-chain
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins
         compiler-driver
         runtime-entrypoint
         runtime-image
         boot-chain)
        annotated-records
        (mapv annotate-with-diverse-verification records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (let [prior-trust-anchor-boundaries
                     (:trust-anchor-boundaries trace)]
                 (-> (or trace {})
                     (assoc :diverse-bootstrap-verification
                            diverse-verification)
                     (assoc :diverse-bootstrap-verification-operation-coverage
                            {:required
                             stage1-reader-diverse-bootstrap-verification-required-operations
                             :provided diverse-operations
                             :covered?
                             (set/subset?
                              (set stage1-reader-diverse-bootstrap-verification-required-operations)
                              (set diverse-operations))})
                     (assoc :replaced-trust-anchor-boundaries
                            prior-trust-anchor-boundaries)
                     (assoc :trust-anchor-boundaries
                            (:trust-anchor-boundaries diverse-verification))
                     (assoc :residual-trust-boundaries
                            (:residual-trust-boundaries diverse-verification))
                     (assoc :diverse-verification-fallbacks
                            (:diverse-verification-fallbacks
                             diverse-verification))
                     (assoc :independent-toolchains
                            (:independent-toolchains diverse-verification))
                     (assoc :bootstrap-trace-comparisons
                            (:bootstrap-trace-comparisons
                             diverse-verification))
                     (assoc :reproducible-build-evidence
                            (:reproducible-build-evidence
                             diverse-verification))
                     (assoc :independent-audit-record
                            (:independent-audit-record diverse-verification))
                     (assoc :diverse-bootstrap-verification-artifact-routing
                            {:artifact (:artifact diverse-verification)
                             :diagnostic-stream
                             (:diagnostic-stream diverse-verification)
                             :proof-kind (:proof-kind diverse-verification)})
                     (update :gravity-runtimes (fnil conj [])
                             :stage1-reader-diverse-bootstrap-verification)
                     (update :character-stream
                             annotate-with-diverse-verification)
                     (update :token-stream
                             annotate-with-diverse-verification)
                     (assoc :diverse-bootstrap-verification-applied
                            {:diverse-bootstrap-verification-id
                             diverse-verification-id
                             :operation-count (count diverse-operations)
                             :replaced-trust-anchor-boundaries
                             prior-trust-anchor-boundaries
                             :residual-trust-boundaries
                             (:residual-trust-boundaries
                              diverse-verification)
                             :diverse-verification-fallbacks
                             (:diverse-verification-fallbacks
                              diverse-verification)}))))))
    annotated-records))

(defn stage1-reader-execute-diverse-bootstrap-verification-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)
        runtime-entrypoint
        (stage1-reader-runtime-entrypoint-from-definitions
         reader-source-path definitions)
        runtime-image
        (stage1-reader-runtime-image-from-definitions
         reader-source-path definitions)
        boot-chain
        (stage1-reader-verified-boot-chain-from-definitions
         reader-source-path definitions)
        diverse-verification
        (stage1-reader-diverse-bootstrap-verification-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-diverse-bootstrap-verification-entrypoint-valid?
               definitions)
      (stage1-reader-diverse-bootstrap-verification-fail!
       "STAGE1DIV001" reader-source-path
       stage1-reader-diverse-bootstrap-verification-entrypoint
       {:missing-fields
        [stage1-reader-diverse-bootstrap-verification-entrypoint]}))
    {:records
     (stage1-reader-execute-diverse-bootstrap-verification
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins
      compiler-driver
      runtime-entrypoint
      runtime-image
      boot-chain
      diverse-verification)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins
     :compiler-driver compiler-driver
     :runtime-entrypoint runtime-entrypoint
     :runtime-image runtime-image
     :verified-boot-chain boot-chain
     :diverse-bootstrap-verification diverse-verification}))

(defn stage1-reader-diverse-bootstrap-verification-diagnostic-stream
  [source-path diverse-verification-id]
  {:artifact
   :gravity/stage1-reader-diverse-bootstrap-verification-diagnostic-stream
   :stage :stage1-reader-diverse-bootstrap-verification
   :source-path source-path
   :diverse-bootstrap-verification-id diverse-verification-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-diverse-bootstrap-verification
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-diverse-bootstrap-verification-diagnostic-messages
                 id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat stage1-reader-diverse-bootstrap-verification-diagnostic-ids
                 (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-diverse-bootstrap-verification-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-diverse-bootstrap-verification-diagnostic-stream
                           :diagnostics])))
        diverse-verification
        (:stage1-reader-diverse-bootstrap-verification artifact)
        boot-chain (:stage1-reader-verified-boot-chain artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names
        (set (:diverse-verification-operations diverse-verification))
        direct-stages (mapv :op (:direct-stages diverse-verification))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))
        independent-toolchains
        (:independent-toolchains diverse-verification)
        toolchain-identities (set (map :identity independent-toolchains))
        trace-comparisons
        (:bootstrap-trace-comparisons diverse-verification)
        reproducible-evidence
        (:reproducible-build-evidence diverse-verification)
        audit-record (:independent-audit-record diverse-verification)]
    {:gravity-reader-diverse-bootstrap-verification-verified?
     (= stage1-reader-diverse-bootstrap-verification-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :diverse-bootstrap-verification-authored?
     (and (= :gravity-reader-diverse-bootstrap-verification-v1
             (:engine diverse-verification))
          (= :gravity-source
             (get-in diverse-verification [:provenance :owner]))
          (= :reader-diverse-bootstrap-trust-anchor-replacement
             (get-in diverse-verification [:provenance :purpose])))
     :diverse-bootstrap-verification-direct-stages-covered?
     (= [:stage1-diverse-bootstrap-seed-built-rebuild
         :stage1-diverse-bootstrap-self-built-rebuild
         :stage1-diverse-bootstrap-clean-environment-rebuild
         :stage1-diverse-bootstrap-diverse-toolchain-rebuild
         :stage1-diverse-bootstrap-compare-traces
         :stage1-diverse-bootstrap-verify-provenance
         :stage1-diverse-bootstrap-record-independent-audit]
        direct-stages)
     :diverse-bootstrap-verification-operations-covered?
     (set/subset?
      (set stage1-reader-diverse-bootstrap-verification-required-operations)
      operation-names)
     :diverse-bootstrap-links-verified-boot-chain?
     (= :stage1-reader-verified-boot-chain
        (:verified-boot-chain diverse-verification))
     :verified-boot-chain-authored?
     (= :gravity-reader-verified-boot-chain-v1 (:engine boot-chain))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-diverse-bootstrap-verification-artifact
        (:artifact diverse-verification)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-diverse-bootstrap-verification-diagnostic-stream
        (:diagnostic-stream diverse-verification)
        (get-in artifact
                [:stage1-reader-diverse-bootstrap-verification-diagnostic-stream
                 :artifact]))
     :hardware-reset-vector-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :hardware-reset-vector-boundary?]))
     :firmware-root-of-trust-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :firmware-root-of-trust-boundary?]))
     :external-auditor-key-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :external-auditor-key-boundary?]))
     :residual-trust-boundaries-explicit?
     (and (true? (get-in artifact [:trusted-boundary
                                   :physical-device-manufacturing-boundary?]))
          (true? (get-in artifact [:trusted-boundary
                                   :supply-chain-custody-boundary?]))
          (true? (get-in artifact [:trusted-boundary
                                   :independent-diversity-review-boundary?])))
     :independent-toolchains-covered?
     (and (>= (count independent-toolchains) 2)
          (>= (count toolchain-identities) 2))
     :bootstrap-trace-comparisons-covered?
     (and (set/subset? #{:manifest-equivalence
                         :diagnostic-equivalence
                         :stage0-form-parity}
                       (set (map :mode trace-comparisons)))
          (every? #(= :accepted (:status %)) trace-comparisons))
     :reproducible-build-evidence-covered?
     (and (= true (:locked-dependencies reproducible-evidence))
          (= true (:fixed-time reproducible-evidence))
          (= "C" (:locale reproducible-evidence))
          (= :canonical (:filesystem-order reproducible-evidence))
          (= :disabled (:network reproducible-evidence)))
	     :independent-audit-record-covered?
	     (and (= :recorded (:status audit-record))
	          (= :independent-diversity-review (:review-kind audit-record))
	          (some? (:reviewer audit-record)))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :runner-fallbacks-empty?
     (= [] (:runner-fallbacks artifact))
     :os-boundaries-empty?
     (= [] (:os-boundaries artifact))
     :image-fallbacks-empty?
     (= [] (:image-fallbacks artifact))
     :machine-boundaries-empty?
     (= [] (:machine-boundaries artifact))
     :boot-chain-fallbacks-empty?
     (= [] (:boot-chain-fallbacks artifact))
     :trust-anchor-boundaries-empty?
     (= [] (:trust-anchor-boundaries artifact))
     :diverse-verification-fallbacks-empty?
     (= [] (:diverse-verification-fallbacks artifact))
     :replaced-trust-anchor-boundaries-recorded?
     (= #{:hardware-reset-vector
          :firmware-root-of-trust
          :external-auditor-key}
        (set (:replaced-trust-anchor-boundaries artifact)))
     :residual-trust-boundaries-recorded?
     (= #{:physical-device-manufacturing
          :supply-chain-custody
          :independent-diversity-review}
        (set (:residual-trust-boundaries artifact)))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-diverse-bootstrap-verification
                    :stage1-reader-verified-boot-chain
                    :stage1-reader-runtime-image
                    :stage1-reader-runtime-entrypoint
                    :stage1-reader-compiler-driver
                    :stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-diverse-bootstrap-verification-v1
             (:diverse-bootstrap-verification-engine character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-diverse-bootstrap-verification-v1
             (:diverse-bootstrap-verification-engine token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-verified-boot-chain-v1
                           (:verified-boot-chain-engine %))
                        (= :gravity-reader-diverse-bootstrap-verification-v1
                           (:diverse-bootstrap-verification-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat stage1-reader-diverse-bootstrap-verification-diagnostic-ids
                   (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? false
      :host-command-invocation? false
      :host-file-read? false
      :os-process-boundary? false
      :os-filesystem-read-boundary? false
      :stdout-boundary? false
      :machine-boundary? false
      :kernel-process-scheduler-boundary? false
      :artifact-loader-boundary? false
      :hardware-reset-vector-boundary? false
      :firmware-root-of-trust-boundary? false
      :external-auditor-key-boundary? false
      :physical-device-manufacturing-boundary? true
      :supply-chain-custody-boundary? true
      :independent-diversity-review-boundary? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-physical-supply-chain-and-independent-diversity-assumptions-with-release-attestation-and-seed-retirement}
     :status :complete}))

(defn stage1-reader-diverse-bootstrap-verification-source-artifact
  [source-path source-text]
  (let [stage1-bootstrap-artifact
        (stage1-bootstrap-source-artifact stage1-reader-bootstrap-source-root)
        trace (atom {})
        runtime-result
        (binding [*stage1-reader-pipeline-trace* trace]
          (stage1-reader-execute-diverse-bootstrap-verification-pipeline
           stage1-reader-source-path source-path source-text))
        stage1-records (:records runtime-result)
        trace-value @trace
        self-hosted-runtime (:self-hosted-runtime runtime-result)
        core-bootstrap-runtime (:core-bootstrap-runtime runtime-result)
        core-bootstrap-builtins (:core-bootstrap-builtins runtime-result)
        compiler-driver (:compiler-driver runtime-result)
        runtime-entrypoint (:runtime-entrypoint runtime-result)
        runtime-image (:runtime-image runtime-result)
        boot-chain (:verified-boot-chain runtime-result)
        diverse-verification (:diverse-bootstrap-verification runtime-result)
        source-runtime (:source-runtime trace-value)
        character-stream (:character-stream trace-value)
        token-classifier (:token-classifier trace-value)
        token-realizer (:token-realizer trace-value)
        token-automaton (:token-automaton trace-value)
        token-automaton-executor (:token-automaton-executor trace-value)
        form-builder (:form-builder trace-value)
        form-builder-executor (:form-builder-executor trace-value)
        token-stream (:token-stream trace-value)
        gravity-runtimes (vec (distinct (:gravity-runtimes trace-value)))
        gravity-executors (vec (distinct (:gravity-executors trace-value)))
        host-primitives (vec (distinct (:host-primitives trace-value)))
        seed-builtin-fallbacks
        (vec (distinct (:seed-builtin-fallbacks trace-value)))
        seed-orchestration-fallbacks
        (vec (distinct (:seed-orchestration-fallbacks trace-value)))
        runner-fallbacks (vec (distinct (:runner-fallbacks trace-value)))
        os-boundaries (vec (distinct (:os-boundaries trace-value)))
        replaced-os-boundaries
        (vec (distinct (:replaced-os-boundaries trace-value)))
        machine-boundaries (vec (distinct (:machine-boundaries trace-value)))
        replaced-machine-boundaries
        (vec (distinct (:replaced-machine-boundaries trace-value)))
        trust-anchor-boundaries
        (vec (distinct (:trust-anchor-boundaries trace-value)))
        replaced-trust-anchor-boundaries
        (vec (distinct (:replaced-trust-anchor-boundaries trace-value)))
        residual-trust-boundaries
        (vec (distinct (:residual-trust-boundaries trace-value)))
        image-fallbacks (vec (distinct (:image-fallbacks trace-value)))
        boot-chain-fallbacks
        (vec (distinct (:boot-chain-fallbacks trace-value)))
        diverse-verification-fallbacks
        (vec (distinct (:diverse-verification-fallbacks trace-value)))
        independent-toolchains (:independent-toolchains trace-value)
        bootstrap-trace-comparisons
        (:bootstrap-trace-comparisons trace-value)
        reproducible-build-evidence
        (:reproducible-build-evidence trace-value)
        independent-audit-record
        (:independent-audit-record trace-value)
        stage0-records (read-source-form-records source-path source-text)
        stage1-forms (mapv :form stage1-records)
        stage0-forms (mapv :form stage0-records)
        comparison {:forms-equal? (= stage1-forms stage0-forms)
                    :top-level-count-matches? (= (count stage1-records)
                                                 (count stage0-records))
                    :stage1-form-count (count stage1-records)
                    :stage0-form-count (count stage0-records)}
        diverse-bootstrap-verification-artifact-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:reader-source stage1-reader-source-path
                       :entrypoint
                       stage1-reader-diverse-bootstrap-verification-entrypoint
                       :diverse-bootstrap-verification
                       diverse-verification
                       :verified-boot-chain boot-chain
                       :runtime-image runtime-image
                       :runtime-entrypoint runtime-entrypoint
                       :compiler-driver compiler-driver
                       :core-bootstrap-runtime core-bootstrap-runtime
                       :core-bootstrap-builtins
                       core-bootstrap-builtins})))]
    (let [artifact-base
          {:kind
           :gravity/stage1-reader-diverse-bootstrap-verification-artifact
           :phase "15"
           :task "P15-S20"
           :stage :stage1-reader-diverse-bootstrap-verification
           :source-path source-path
           :reader-source-path stage1-reader-source-path
           :gravity-entrypoint
           stage1-reader-diverse-bootstrap-verification-entrypoint
           :diverse-bootstrap-verification-artifact-id
           diverse-bootstrap-verification-artifact-id
           :reader-diverse-bootstrap-verification-id
           (:diverse-bootstrap-verification-id diverse-verification)
           :reader-verified-boot-chain-id
           (:verified-boot-chain-id boot-chain)
           :reader-runtime-image-id
           (:runtime-image-id runtime-image)
           :reader-runtime-entrypoint-id
           (:runtime-entrypoint-id runtime-entrypoint)
           :reader-compiler-driver-id
           (:compiler-driver-id compiler-driver)
           :reader-core-bootstrap-runtime-id
           (:core-bootstrap-runtime-id core-bootstrap-runtime)
           :reader-core-bootstrap-builtins-id
           (:core-bootstrap-builtins-id core-bootstrap-builtins)
           :reader-self-hosted-runtime-id
           (:self-hosted-runtime-id self-hosted-runtime)
           :host-primitives host-primitives
           :seed-builtin-fallbacks seed-builtin-fallbacks
           :seed-orchestration-fallbacks seed-orchestration-fallbacks
           :runner-fallbacks runner-fallbacks
           :os-boundaries os-boundaries
           :replaced-os-boundaries replaced-os-boundaries
           :machine-boundaries machine-boundaries
           :replaced-machine-boundaries replaced-machine-boundaries
           :trust-anchor-boundaries trust-anchor-boundaries
           :replaced-trust-anchor-boundaries replaced-trust-anchor-boundaries
           :residual-trust-boundaries residual-trust-boundaries
           :image-fallbacks image-fallbacks
           :boot-chain-fallbacks boot-chain-fallbacks
           :diverse-verification-fallbacks diverse-verification-fallbacks
           :independent-toolchains independent-toolchains
           :bootstrap-trace-comparisons bootstrap-trace-comparisons
           :reproducible-build-evidence reproducible-build-evidence
           :independent-audit-record independent-audit-record
           :gravity-runtimes gravity-runtimes
           :gravity-executors gravity-executors
           :trusted-boundary
           {:clojure-runtime-interpreter? false
            :clojure-instruction-executor? false
            :clojure-binary-runner? false
            :clojure-character-stream-implementation? false
            :clojure-seed-builtins? false
            :clojure-seed-orchestration? false
            :clojure-driver-runner? false
            :host-command-invocation? false
            :host-file-read? false
            :os-process-boundary? false
            :os-filesystem-read-boundary? false
            :stdout-boundary? false
            :machine-boundary? false
            :kernel-process-scheduler-boundary? false
            :artifact-loader-boundary? false
            :hardware-reset-vector-boundary? false
            :firmware-root-of-trust-boundary? false
            :external-auditor-key-boundary? false
            :physical-device-manufacturing-boundary? true
            :supply-chain-custody-boundary? true
            :independent-diversity-review-boundary? true}
           :stage1-bootstrap-source-artifact stage1-bootstrap-artifact
           :stage1-reader-diverse-bootstrap-verification
           diverse-verification
           :stage1-reader-verified-boot-chain boot-chain
           :stage1-reader-runtime-image runtime-image
           :stage1-reader-runtime-entrypoint runtime-entrypoint
           :stage1-reader-compiler-driver compiler-driver
           :stage1-reader-core-bootstrap-runtime
           core-bootstrap-runtime
           :stage1-reader-core-bootstrap-builtins
           core-bootstrap-builtins
           :stage1-reader-self-hosted-runtime self-hosted-runtime
           :stage1-reader-source-runtime source-runtime
           :stage1-reader-character-stream character-stream
           :stage1-reader-token-classifier token-classifier
           :stage1-reader-token-realizer token-realizer
           :stage1-reader-token-automaton token-automaton
           :stage1-reader-token-automaton-executor
           token-automaton-executor
           :stage1-reader-form-builder form-builder
           :stage1-reader-form-builder-executor form-builder-executor
           :stage1-reader-token-stream token-stream
           :stage1-reader-records stage1-records
           :stage1-reader-diverse-bootstrap-verification-trace
           (dissoc trace-value :character-stream :token-stream
                   :token-classifier :token-realizer :token-automaton
                   :token-automaton-executor :form-builder
                   :form-builder-executor :source-runtime
                   :self-hosted-reader-runtime
                   :core-bootstrap-runtime
                   :core-bootstrap-builtins
                   :compiler-driver
                   :runtime-entrypoint
                   :runtime-image
                   :verified-boot-chain
                   :diverse-bootstrap-verification)
           :stage0-comparison comparison
           :accepted-stage1-reader-diverse-bootstrap-verification-fixtures
           [{:fixture
             "bootstrap/clojure/fixtures/accepted/stage1-reader-execution.gravity"
             :status :accepted
             :comparison comparison
             :character-count (:character-count character-stream)
             :token-count (:token-count token-stream)
             :form-count (count stage1-records)
             :diverse-bootstrap-verification-id
             (:diverse-bootstrap-verification-id diverse-verification)}]
           :rejected-stage1-reader-diverse-bootstrap-verification-fixtures
           stage1-reader-diverse-bootstrap-verification-rejected-fixture-records
           :stage1-reader-diverse-bootstrap-verification-diagnostic-stream
           (stage1-reader-diverse-bootstrap-verification-diagnostic-stream
            source-path
            (:diverse-bootstrap-verification-id diverse-verification))
           :stage1-reader-diverse-bootstrap-verification-results
           {:accepted-fixtures 1
            :rejected-fixtures
            (count stage1-reader-diverse-bootstrap-verification-rejected-fixture-records)
            :diagnostic-count
            (+ (count stage1-reader-diverse-bootstrap-verification-diagnostic-ids)
               (dec (count stage1-reader-execution-diagnostic-ids)))
            :character-count (:character-count character-stream)
            :token-count (:token-count token-stream)
            :form-count (count stage1-records)
            :status :complete}
           :diagnostics []}]
      (when-not (:forms-equal? comparison)
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV005" source-path comparison
         {:missing-fields [:stage0-form-parity]}))
      (when-not (= (:artifact diverse-verification) (:kind artifact-base))
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV005" source-path artifact-base
         {:missing-fields [:artifact]}))
      (when-not (= (:diagnostic-stream diverse-verification)
                   (get-in artifact-base
                           [:stage1-reader-diverse-bootstrap-verification-diagnostic-stream
                            :artifact]))
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV009" source-path artifact-base
         {:missing-fields [:diagnostic-stream]}))
      (doseq [[diagnostic field value]
              [["STAGE1DIV008" :host-primitives host-primitives]
               ["STAGE1DIV008" :seed-builtin-fallbacks
                seed-builtin-fallbacks]
               ["STAGE1DIV008" :seed-orchestration-fallbacks
                seed-orchestration-fallbacks]
               ["STAGE1DIV008" :runner-fallbacks runner-fallbacks]
               ["STAGE1DIV008" :os-boundaries os-boundaries]
               ["STAGE1DIV008" :machine-boundaries machine-boundaries]
               ["STAGE1DIV008" :trust-anchor-boundaries
                trust-anchor-boundaries]
               ["STAGE1DIV008" :image-fallbacks image-fallbacks]
               ["STAGE1DIV008" :boot-chain-fallbacks
                boot-chain-fallbacks]
               ["STAGE1DIV008" :diverse-verification-fallbacks
                diverse-verification-fallbacks]]]
        (when (seq value)
          (stage1-reader-diverse-bootstrap-verification-fail!
           diagnostic source-path trace-value {field value})))
      (when-not (= #{:hardware-reset-vector
                     :firmware-root-of-trust
                     :external-auditor-key}
                   (set replaced-trust-anchor-boundaries))
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV008" source-path trace-value
         {:replaced-trust-anchor-boundaries
          replaced-trust-anchor-boundaries}))
      (when-not (= #{:physical-device-manufacturing
                     :supply-chain-custody
                     :independent-diversity-review}
                   (set residual-trust-boundaries))
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV006" source-path trace-value
         {:residual-trust-boundaries residual-trust-boundaries}))
      (when-not (and (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :hardware-reset-vector-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :firmware-root-of-trust-boundary?]))
                     (false? (get-in artifact-base
                                     [:trusted-boundary
                                      :external-auditor-key-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :physical-device-manufacturing-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :supply-chain-custody-boundary?]))
                     (true? (get-in artifact-base
                                    [:trusted-boundary
                                     :independent-diversity-review-boundary?])))
        (stage1-reader-diverse-bootstrap-verification-fail!
         "STAGE1DIV009" source-path artifact-base
         {:missing-fields [:trusted-boundary]}))
      (let [capability-proof
            (stage1-reader-diverse-bootstrap-verification-proof
             artifact-base)]
        (assoc artifact-base
               :capability-based-proof capability-proof
               :artifact-id
               (c4-artifact-id (assoc artifact-base
                                      :capability-based-proof
                                      capability-proof)))))))

(defn stage1-reader-diverse-bootstrap-verification-file-artifact
  [path]
  (stage1-reader-diverse-bootstrap-verification-source-artifact
   path
   (slurp path)))

(def stage1-reader-release-attestation-seed-retirement-required-operations
  [:verify-release-attestation
   :verify-seed-retirement-evidence
   :verify-supply-chain-manifest
   :verify-release-custody-reproducibility
   :verify-governance-approval
   :verify-revocation-status
   :record-release-provenance])

(defn stage1-reader-release-attestation-seed-retirement-literal-definition-value
  [reader-source-path definitions symbol-name]
  (let [definition (get definitions symbol-name)]
    (when-not (= :def (:kind definition))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL003" reader-source-path symbol-name
       {:missing-fields [symbol-name]}))
    (:value-form definition)))

(defn stage1-reader-release-attestation-seed-retirement-from-definitions
  [reader-source-path definitions]
  (let [release-attestation
        (stage1-reader-release-attestation-seed-retirement-literal-definition-value
         reader-source-path definitions
         'stage1-reader-release-attestation-seed-retirement)
        diagnostics (:diagnostics release-attestation)
        missing-diagnostics
        (remove #(contains? diagnostics %)
                [:missing-entrypoint
                 :unsupported-release-attestation-operation
                 :missing-release-attestation-record
                 :missing-seed-retirement-evidence
                 :nonreproducible-release-custody
                 :unverifiable-supply-chain-manifest
                 :missing-governance-approval
                 :illegal-physical-release-fallback
                 :revoked-release-input
                 :invalid-release-attestation-seed-retirement])
        required-stages
        [:stage1-release-attestation-verify
         :stage1-release-attestation-seed-retirement-evidence
         :stage1-release-attestation-supply-chain-manifest
         :stage1-release-attestation-release-custody-reproducibility
         :stage1-release-attestation-governance-approval
         :stage1-release-attestation-revocation-status
         :stage1-release-attestation-record-provenance]
        direct-stages (:direct-stages release-attestation)
        release-record (:release-attestation-record release-attestation)
        seed-retirement-evidence
        (:seed-retirement-evidence release-attestation)
        supply-chain-manifest
        (:supply-chain-manifest release-attestation)
        release-custody-record
        (:release-custody-record release-attestation)
        governance-approval-record
        (:governance-approval-record release-attestation)
        revocation-check-report
        (:revocation-check-report release-attestation)
        release-provenance-record
        (:release-provenance-record release-attestation)]
    (when-not (map? release-attestation)
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL003" reader-source-path release-attestation
       {:missing-fields
        [:stage1-reader-release-attestation-seed-retirement]}))
    (doseq [field [:engine :entrypoint :replaces
                   :diverse-bootstrap-verification
                   :verified-boot-chain :input :output :artifact
                   :diagnostic-stream :proof-kind
                   :physical-release-boundaries
                   :replaced-physical-release-boundaries
                   :residual-trust-boundaries
                   :residual-release-governance-boundaries
                   :release-attestation-fallbacks
                   :release-attestation-operations
                   :release-attestation-record
                   :seed-retirement-evidence
                   :supply-chain-manifest
                   :release-custody-record
                   :governance-approval-record
                   :revocation-check-report
                   :release-provenance-record
                   :direct-stages :uses-runtimes :uses-builtins
                   :uses-executors :preserves :diagnostics :provenance]]
      (when-not (contains? release-attestation field)
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL010" reader-source-path release-attestation
         {:missing-fields [field]})))
    (when-not (= :gravity-reader-release-attestation-seed-retirement-v1
                 (:engine release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:engine]}))
    (when-not (= :stage1-read-source-release-attestation-seed-retirement
                 (:entrypoint release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:entrypoint]}))
    (when-not (set/subset? #{:physical-device-manufacturing
                             :supply-chain-custody
                             :independent-diversity-review}
                           (set (:replaces release-attestation)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:replaces]}))
    (when-not (= :stage1-reader-diverse-bootstrap-verification
                 (:diverse-bootstrap-verification release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:diverse-bootstrap-verification]}))
    (when-not (= :stage1-reader-verified-boot-chain
                 (:verified-boot-chain release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:verified-boot-chain]}))
    (when-not (= [:release-attestation
                  :seed-retirement
                  :diverse-bootstrap-verification
                  :verified-boot-chain
                  :source-path
                  :source-text]
                 (:input release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:input]}))
    (when-not (= :gravity/stage1-reader-form-records
                 (:output release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:output]}))
    (when-not (= :gravity/stage1-reader-release-attestation-seed-retirement-artifact
                 (:artifact release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:artifact]}))
    (when-not (= :gravity/stage1-reader-release-attestation-seed-retirement-diagnostic-stream
                 (:diagnostic-stream release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:diagnostic-stream]}))
    (when-not (= :gravity/stage1-reader-release-attestation-seed-retirement-proof
                 (:proof-kind release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:proof-kind]}))
    (when-not (= [] (:physical-release-boundaries release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL008" reader-source-path release-attestation
       {:physical-release-boundaries
        (:physical-release-boundaries release-attestation)}))
    (when-not (set/subset? #{:physical-device-manufacturing
                             :supply-chain-custody
                             :independent-diversity-review}
                           (set (:replaced-physical-release-boundaries
                                 release-attestation)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:replaced-physical-release-boundaries]}))
    (when-not (= [] (:residual-trust-boundaries release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL008" reader-source-path release-attestation
       {:residual-trust-boundaries
        (:residual-trust-boundaries release-attestation)}))
    (when-not (set/subset? #{:human-release-governance
                             :legal-custody-record-retention
                             :deployment-environment-custody}
                           (set (:residual-release-governance-boundaries
                                 release-attestation)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:residual-release-governance-boundaries]}))
    (when-not (= [] (:release-attestation-fallbacks release-attestation))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL008" reader-source-path release-attestation
       {:release-attestation-fallbacks
        (:release-attestation-fallbacks release-attestation)}))
    (let [release-operations
          (:release-attestation-operations release-attestation)
          operation-names (set release-operations)
          required-operation-set
          (set stage1-reader-release-attestation-seed-retirement-required-operations)]
      (when-not (vector? release-operations)
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL002" reader-source-path release-attestation
         {:missing-fields [:release-attestation-operations]}))
      (when-not (set/subset? required-operation-set operation-names)
        (stage1-reader-release-attestation-seed-retirement-fail!
         "STAGE1REL002" reader-source-path release-operations
         {:missing-operations
          (vec (remove operation-names
                       stage1-reader-release-attestation-seed-retirement-required-operations))})))
    (when-not (and (vector? direct-stages)
                   (= required-stages (mapv :op direct-stages)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:direct-stages]}))
    (when-not (and (= :accepted (:status release-record))
                   (= :verified (:provenance release-record))
                   (= :verified (:sbom release-record))
                   (= :verified (:signatures release-record))
                   (= :verified (:artifact-hashes release-record))
                   (= :verified (:capability-manifest release-record))
                   (= :verified (:conformance-report release-record)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL003" reader-source-path release-record
       {:missing-fields [:release-attestation-record]}))
    (when-not (and (= :recorded (:status seed-retirement-evidence))
                   (true? (:stage1-reader-seed-assumptions-retired?
                           seed-retirement-evidence))
                   (false? (:full-compiler-seed-retired?
                            seed-retirement-evidence))
                   (= #{:physical-device-manufacturing
                        :supply-chain-custody
                        :independent-diversity-review}
                      (set (:retired-assumptions
                            seed-retirement-evidence)))
                   (set/subset?
                    #{:human-release-governance
                      :legal-custody-record-retention
                      :deployment-environment-custody}
                    (set (:remaining-boundaries
                          seed-retirement-evidence))))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL004" reader-source-path seed-retirement-evidence
       {:missing-fields [:seed-retirement-evidence]}))
    (when-not (and (= :verifiable (:status supply-chain-manifest))
                   (= :verified (:source-archive supply-chain-manifest))
                   (= :verified (:lockfile supply-chain-manifest))
                   (= :verified (:builder-identity supply-chain-manifest))
                   (= :verified (:custody-events supply-chain-manifest))
                   (= :verified (:sbom supply-chain-manifest))
                   (= :verified (:signatures supply-chain-manifest)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL006" reader-source-path supply-chain-manifest
       {:missing-fields [:supply-chain-manifest]}))
    (when-not (and (true? (:reproducible release-custody-record))
                   (true? (:locked-dependencies release-custody-record))
                   (true? (:fixed-time release-custody-record))
                   (= "C" (:locale release-custody-record))
                   (= :canonical (:filesystem-order
                                  release-custody-record))
                   (= :disabled (:network release-custody-record))
                   (= :accepted (:status release-custody-record)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL005" reader-source-path release-custody-record
       {:missing-fields [:release-custody-record]}))
    (when-not (and (= :approved (:status governance-approval-record))
                   (= :accepted (:rfc-state governance-approval-record))
                   (= :GOV6 (:rfc-policy governance-approval-record))
                   (= :GOV10 (:package-policy governance-approval-record))
                   (set/subset?
                    #{:compatibility :security :profile
                      :conformance :package-governance}
                    (set (:review-gates governance-approval-record))))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL007" reader-source-path governance-approval-record
       {:missing-fields [:governance-approval-record]}))
    (when-not (and (= :clear (:status revocation-check-report))
                   (= [] (:revoked-builders revocation-check-report))
                   (= [] (:revoked-dependencies revocation-check-report))
                   (= [] (:revoked-signatures revocation-check-report)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL009" reader-source-path revocation-check-report
       {:missing-fields [:revocation-check-report]}))
    (when-not (and (= :complete (:status release-provenance-record))
                   (true? (:canonicalized release-provenance-record))
                   (true? (:auditor-traversable release-provenance-record))
                   (set/subset?
                    #{:stage1-reader-release-attestation-seed-retirement
                      :stage1-reader-diverse-bootstrap-verification
                      :stage1-reader-verified-boot-chain}
                    (set (:lineage release-provenance-record))))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-provenance-record
       {:missing-fields [:release-provenance-record]}))
    (when-not (set/subset? #{:stage1-reader-release-attestation-seed-retirement
                             :stage1-reader-diverse-bootstrap-verification
                             :stage1-reader-verified-boot-chain
                             :stage1-reader-runtime-image
                             :stage1-reader-runtime-entrypoint
                             :stage1-reader-compiler-driver
                             :stage1-reader-core-bootstrap-runtime
                             :stage1-reader-self-hosted-runtime
                             :stage1-reader-source-runtime}
                           (set (:uses-runtimes release-attestation)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:uses-runtimes]}))
    (when-not (set/subset? #{:stage1-reader-core-bootstrap-builtins}
                           (set (:uses-builtins release-attestation)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:uses-builtins]}))
    (when-not (set/subset? #{:stage1-reader-token-automaton-executor
                             :stage1-reader-form-builder-executor}
                           (set (:uses-executors release-attestation)))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:uses-executors]}))
    (when-not (= :gravity-source
                 (get-in release-attestation [:provenance :owner]))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:provenance :owner]}))
    (when-not (= :reader-release-attestation-seed-retirement-assumption-replacement
                 (get-in release-attestation [:provenance :purpose]))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:provenance :purpose]}))
    (when-not (= :replace-physical-supply-chain-and-independent-diversity-assumptions-with-release-attestation-and-seed-retirement
                 (get-in release-attestation
                         [:provenance :retirement-objective]))
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path release-attestation
       {:missing-fields [:provenance :retirement-objective]}))
    (when (seq missing-diagnostics)
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL010" reader-source-path diagnostics
       {:missing-fields (vec missing-diagnostics)}))
    (assoc release-attestation
           :release-attestation-seed-retirement-id
           (str "sha256:" (sha256-hex (pr-str release-attestation))))))

(defn stage1-reader-release-attestation-seed-retirement-entrypoint-valid?
  [definitions]
  (let [definition
        (get definitions
             stage1-reader-release-attestation-seed-retirement-entrypoint)]
    (and (= :defn (:kind definition))
         (= '[source-path source-text] (:params definition))
         (= '((reader/execute-release-attestation-seed-retirement
               source-path
               source-text
               stage1-reader-release-attestation-seed-retirement
               stage1-reader-diverse-bootstrap-verification
               stage1-reader-verified-boot-chain))
            (:body definition)))))

(defn stage1-reader-execute-release-attestation-seed-retirement
  [reader-source-path
   definitions
   source-path
   source-text
   self-hosted-runtime
   core-bootstrap-runtime
   core-bootstrap-builtins
   compiler-driver
   runtime-entrypoint
   runtime-image
   boot-chain
   diverse-verification
   release-attestation]
  (let [release-attestation-id
        (:release-attestation-seed-retirement-id release-attestation)
        release-operations
        (:release-attestation-operations release-attestation)
        annotate-with-release-attestation
        (fn [record]
          (assoc record
                 :release-attestation-seed-retirement-id
                 release-attestation-id
                 :release-attestation-seed-retirement-engine
                 (:engine release-attestation)
                 :release-attestation-seed-retirement
                 :gravity-reader-release-attestation-seed-retirement-v1))
        records
        (stage1-reader-execute-diverse-bootstrap-verification
         reader-source-path
         definitions
         source-path
         source-text
         self-hosted-runtime
         core-bootstrap-runtime
         core-bootstrap-builtins
         compiler-driver
         runtime-entrypoint
         runtime-image
         boot-chain
         diverse-verification)
        annotated-records
        (mapv annotate-with-release-attestation records)]
    (when *stage1-reader-pipeline-trace*
      (swap! *stage1-reader-pipeline-trace*
             (fn [trace]
               (let [prior-residual-boundaries
                     (:residual-trust-boundaries trace)]
                 (-> (or trace {})
                     (assoc :release-attestation-seed-retirement
                            release-attestation)
                     (assoc :release-attestation-operation-coverage
                            {:required
                             stage1-reader-release-attestation-seed-retirement-required-operations
                             :provided release-operations
                             :covered?
                             (set/subset?
                              (set stage1-reader-release-attestation-seed-retirement-required-operations)
                              (set release-operations))})
                     (assoc :replaced-physical-release-boundaries
                            prior-residual-boundaries)
                     (assoc :physical-release-boundaries
                            (:physical-release-boundaries
                             release-attestation))
                     (assoc :residual-trust-boundaries
                            (:residual-trust-boundaries release-attestation))
                     (assoc :residual-release-governance-boundaries
                            (:residual-release-governance-boundaries
                             release-attestation))
                     (assoc :release-attestation-fallbacks
                            (:release-attestation-fallbacks
                             release-attestation))
                     (assoc :release-attestation-record
                            (:release-attestation-record
                             release-attestation))
                     (assoc :seed-retirement-evidence
                            (:seed-retirement-evidence
                             release-attestation))
                     (assoc :supply-chain-manifest
                            (:supply-chain-manifest
                             release-attestation))
                     (assoc :release-custody-record
                            (:release-custody-record
                             release-attestation))
                     (assoc :governance-approval-record
                            (:governance-approval-record
                             release-attestation))
                     (assoc :revocation-check-report
                            (:revocation-check-report
                             release-attestation))
                     (assoc :release-provenance-record
                            (:release-provenance-record
                             release-attestation))
                     (assoc :release-attestation-artifact-routing
                            {:artifact (:artifact release-attestation)
                             :diagnostic-stream
                             (:diagnostic-stream release-attestation)
                             :proof-kind (:proof-kind release-attestation)})
                     (update :gravity-runtimes (fnil conj [])
                             :stage1-reader-release-attestation-seed-retirement)
                     (update :character-stream
                             annotate-with-release-attestation)
                     (update :token-stream
                             annotate-with-release-attestation)
                     (assoc :release-attestation-seed-retirement-applied
                            {:release-attestation-seed-retirement-id
                             release-attestation-id
                             :operation-count (count release-operations)
                             :replaced-physical-release-boundaries
                             prior-residual-boundaries
                             :residual-trust-boundaries
                             (:residual-trust-boundaries
                              release-attestation)
                             :residual-release-governance-boundaries
                             (:residual-release-governance-boundaries
                              release-attestation)
                             :release-attestation-fallbacks
                             (:release-attestation-fallbacks
                              release-attestation)}))))))
    annotated-records))

(defn stage1-reader-execute-release-attestation-seed-retirement-pipeline
  [reader-source-path source-path source-text]
  (let [forms (stage1-reader-source-forms reader-source-path)
        definitions (stage1-reader-definition-map reader-source-path forms)
        self-hosted-runtime
        (stage1-reader-self-hosted-runtime-from-definitions
         reader-source-path definitions)
        core-bootstrap-builtins
        (stage1-reader-core-bootstrap-builtins-from-definitions
         reader-source-path definitions)
        core-bootstrap-runtime
        (stage1-reader-core-bootstrap-runtime-from-definitions
         reader-source-path definitions)
        compiler-driver
        (stage1-reader-compiler-driver-from-definitions
         reader-source-path definitions)
        runtime-entrypoint
        (stage1-reader-runtime-entrypoint-from-definitions
         reader-source-path definitions)
        runtime-image
        (stage1-reader-runtime-image-from-definitions
         reader-source-path definitions)
        boot-chain
        (stage1-reader-verified-boot-chain-from-definitions
         reader-source-path definitions)
        diverse-verification
        (stage1-reader-diverse-bootstrap-verification-from-definitions
         reader-source-path definitions)
        release-attestation
        (stage1-reader-release-attestation-seed-retirement-from-definitions
         reader-source-path definitions)]
    (when-not (stage1-reader-release-attestation-seed-retirement-entrypoint-valid?
               definitions)
      (stage1-reader-release-attestation-seed-retirement-fail!
       "STAGE1REL001" reader-source-path
       stage1-reader-release-attestation-seed-retirement-entrypoint
       {:missing-fields
        [stage1-reader-release-attestation-seed-retirement-entrypoint]}))
    {:records
     (stage1-reader-execute-release-attestation-seed-retirement
      reader-source-path
      definitions
      source-path
      source-text
      self-hosted-runtime
      core-bootstrap-runtime
      core-bootstrap-builtins
      compiler-driver
      runtime-entrypoint
      runtime-image
      boot-chain
      diverse-verification
      release-attestation)
     :self-hosted-runtime self-hosted-runtime
     :core-bootstrap-runtime core-bootstrap-runtime
     :core-bootstrap-builtins core-bootstrap-builtins
     :compiler-driver compiler-driver
     :runtime-entrypoint runtime-entrypoint
     :runtime-image runtime-image
     :verified-boot-chain boot-chain
     :diverse-bootstrap-verification diverse-verification
     :release-attestation-seed-retirement release-attestation}))

(defn stage1-reader-release-attestation-seed-retirement-diagnostic-stream
  [source-path release-attestation-id]
  {:artifact
   :gravity/stage1-reader-release-attestation-seed-retirement-diagnostic-stream
   :stage :stage1-reader-release-attestation-seed-retirement
   :source-path source-path
   :release-attestation-seed-retirement-id release-attestation-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :stage1-reader-release-attestation-seed-retirement
            :artifact :gravity/diagnostic
            :message
            (or (stage1-reader-release-attestation-seed-retirement-diagnostic-messages
                 id)
                (stage1-reader-execution-diagnostic-messages id))})
         (concat
          stage1-reader-release-attestation-seed-retirement-diagnostic-ids
          (butlast stage1-reader-execution-diagnostic-ids)))
   :status :complete})

(defn stage1-reader-release-attestation-seed-retirement-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:stage1-reader-release-attestation-seed-retirement-diagnostic-stream
                           :diagnostics])))
        release-attestation
        (:stage1-reader-release-attestation-seed-retirement artifact)
        diverse-verification
        (:stage1-reader-diverse-bootstrap-verification artifact)
        boot-chain (:stage1-reader-verified-boot-chain artifact)
        character-stream (:stage1-reader-character-stream artifact)
        token-stream (:stage1-reader-token-stream artifact)
        records (:stage1-reader-records artifact)
        operation-names
        (set (:release-attestation-operations release-attestation))
        direct-stages (mapv :op (:direct-stages release-attestation))
        gravity-runtimes (set (:gravity-runtimes artifact))
        gravity-executors (set (:gravity-executors artifact))
        release-record
        (:release-attestation-record release-attestation)
        seed-retirement-evidence
        (:seed-retirement-evidence release-attestation)
        supply-chain-manifest
        (:supply-chain-manifest release-attestation)
        release-custody-record
        (:release-custody-record release-attestation)
        governance-approval-record
        (:governance-approval-record release-attestation)
        revocation-check-report
        (:revocation-check-report release-attestation)
        release-provenance-record
        (:release-provenance-record release-attestation)]
    {:gravity-reader-release-attestation-seed-retirement-verified?
     (= stage1-reader-release-attestation-seed-retirement-entrypoint
        (:gravity-entrypoint artifact))
     :gravity-reader-source-verified?
     (= :complete (get-in artifact
                          [:stage1-bootstrap-source-artifact
                           :capability-based-proof
                           :status]))
     :release-attestation-seed-retirement-authored?
     (and (= :gravity-reader-release-attestation-seed-retirement-v1
             (:engine release-attestation))
          (= :gravity-source
             (get-in release-attestation [:provenance :owner]))
          (= :reader-release-attestation-seed-retirement-assumption-replacement
             (get-in release-attestation [:provenance :purpose])))
     :release-attestation-seed-retirement-direct-stages-covered?
     (= [:stage1-release-attestation-verify
         :stage1-release-attestation-seed-retirement-evidence
         :stage1-release-attestation-supply-chain-manifest
         :stage1-release-attestation-release-custody-reproducibility
         :stage1-release-attestation-governance-approval
         :stage1-release-attestation-revocation-status
         :stage1-release-attestation-record-provenance]
        direct-stages)
     :release-attestation-seed-retirement-operations-covered?
     (set/subset?
      (set stage1-reader-release-attestation-seed-retirement-required-operations)
      operation-names)
     :release-attestation-links-diverse-bootstrap-verification?
     (= :stage1-reader-diverse-bootstrap-verification
        (:diverse-bootstrap-verification release-attestation))
     :release-attestation-links-verified-boot-chain?
     (= :stage1-reader-verified-boot-chain
        (:verified-boot-chain release-attestation))
     :diverse-bootstrap-verification-authored?
     (= :gravity-reader-diverse-bootstrap-verification-v1
        (:engine diverse-verification))
     :verified-boot-chain-authored?
     (= :gravity-reader-verified-boot-chain-v1 (:engine boot-chain))
     :artifact-routing-covered?
     (= :gravity/stage1-reader-release-attestation-seed-retirement-artifact
        (:artifact release-attestation)
        (:kind artifact))
     :diagnostic-stream-routing-covered?
     (= :gravity/stage1-reader-release-attestation-seed-retirement-diagnostic-stream
        (:diagnostic-stream release-attestation)
        (get-in artifact
                [:stage1-reader-release-attestation-seed-retirement-diagnostic-stream
                 :artifact]))
     :physical-device-manufacturing-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :physical-device-manufacturing-boundary?]))
     :supply-chain-custody-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :supply-chain-custody-boundary?]))
     :independent-diversity-review-boundary-replaced?
     (false? (get-in artifact [:trusted-boundary
                               :independent-diversity-review-boundary?]))
     :residual-trust-boundaries-empty?
     (= [] (:residual-trust-boundaries artifact))
     :residual-release-governance-boundaries-explicit?
     (and (true? (get-in artifact
                         [:trusted-boundary
                          :human-release-governance-boundary?]))
          (true? (get-in artifact
                         [:trusted-boundary
                          :legal-custody-record-retention-boundary?]))
          (true? (get-in artifact
                         [:trusted-boundary
                          :deployment-environment-custody-boundary?])))
     :release-attestation-record-covered?
     (and (= :accepted (:status release-record))
          (= :verified (:provenance release-record))
          (= :verified (:sbom release-record))
          (= :verified (:signatures release-record))
          (= :verified (:artifact-hashes release-record))
          (= :verified (:capability-manifest release-record))
          (= :verified (:conformance-report release-record)))
     :seed-retirement-evidence-covered?
     (and (= :recorded (:status seed-retirement-evidence))
          (true? (:stage1-reader-seed-assumptions-retired?
                  seed-retirement-evidence))
          (false? (:full-compiler-seed-retired?
                   seed-retirement-evidence)))
     :supply-chain-manifest-covered?
     (and (= :verifiable (:status supply-chain-manifest))
          (= :verified (:source-archive supply-chain-manifest))
          (= :verified (:lockfile supply-chain-manifest))
          (= :verified (:builder-identity supply-chain-manifest))
          (= :verified (:custody-events supply-chain-manifest))
          (= :verified (:sbom supply-chain-manifest))
          (= :verified (:signatures supply-chain-manifest)))
     :release-custody-reproducibility-covered?
     (and (true? (:reproducible release-custody-record))
          (true? (:locked-dependencies release-custody-record))
          (true? (:fixed-time release-custody-record))
          (= "C" (:locale release-custody-record))
          (= :canonical (:filesystem-order release-custody-record))
          (= :disabled (:network release-custody-record)))
     :governance-approval-covered?
     (and (= :approved (:status governance-approval-record))
          (= :accepted (:rfc-state governance-approval-record))
          (= :GOV6 (:rfc-policy governance-approval-record))
          (= :GOV10 (:package-policy governance-approval-record)))
     :revocation-check-covered?
     (and (= :clear (:status revocation-check-report))
          (= [] (:revoked-builders revocation-check-report))
          (= [] (:revoked-dependencies revocation-check-report))
          (= [] (:revoked-signatures revocation-check-report)))
     :release-provenance-covered?
     (and (= :complete (:status release-provenance-record))
          (true? (:canonicalized release-provenance-record))
          (true? (:auditor-traversable release-provenance-record))
          (set/subset?
           #{:stage1-reader-release-attestation-seed-retirement
             :stage1-reader-diverse-bootstrap-verification
             :stage1-reader-verified-boot-chain}
           (set (:lineage release-provenance-record))))
     :host-primitive-boundary-empty?
     (= [] (:host-primitives artifact))
     :host-fallbacks-empty?
     (= [] (get-in artifact [:stage1-reader-core-bootstrap-builtins
                             :host-fallbacks]))
     :seed-builtin-fallbacks-empty?
     (= [] (:seed-builtin-fallbacks artifact))
     :seed-orchestration-fallbacks-empty?
     (= [] (:seed-orchestration-fallbacks artifact))
     :runner-fallbacks-empty?
     (= [] (:runner-fallbacks artifact))
     :os-boundaries-empty?
     (= [] (:os-boundaries artifact))
     :image-fallbacks-empty?
     (= [] (:image-fallbacks artifact))
     :machine-boundaries-empty?
     (= [] (:machine-boundaries artifact))
     :boot-chain-fallbacks-empty?
     (= [] (:boot-chain-fallbacks artifact))
     :trust-anchor-boundaries-empty?
     (= [] (:trust-anchor-boundaries artifact))
     :diverse-verification-fallbacks-empty?
     (= [] (:diverse-verification-fallbacks artifact))
     :release-attestation-fallbacks-empty?
     (= [] (:release-attestation-fallbacks artifact))
     :replaced-physical-release-boundaries-recorded?
     (= #{:physical-device-manufacturing
          :supply-chain-custody
          :independent-diversity-review}
        (set (:replaced-physical-release-boundaries artifact)))
     :residual-release-governance-boundaries-recorded?
     (= #{:human-release-governance
          :legal-custody-record-retention
          :deployment-environment-custody}
        (set (:residual-release-governance-boundaries artifact)))
     :gravity-runtimes-covered?
     (set/subset? #{:stage1-reader-release-attestation-seed-retirement
                    :stage1-reader-diverse-bootstrap-verification
                    :stage1-reader-verified-boot-chain
                    :stage1-reader-runtime-image
                    :stage1-reader-runtime-entrypoint
                    :stage1-reader-compiler-driver
                    :stage1-reader-core-bootstrap-runtime
                    :stage1-reader-self-hosted-runtime
                    :stage1-reader-source-runtime}
                  gravity-runtimes)
     :gravity-executors-covered?
     (set/subset? #{:stage1-reader-token-automaton-executor
                    :stage1-reader-form-builder-executor}
                  gravity-executors)
     :character-stream-covered?
     (and (= :gravity/stage1-reader-character-stream
             (:kind character-stream))
          (= :gravity-reader-release-attestation-seed-retirement-v1
             (:release-attestation-seed-retirement-engine
              character-stream))
          (pos? (:character-count character-stream))
          (= (:character-count character-stream)
             (count (:characters character-stream))))
     :token-stream-covered?
     (and (= :gravity/stage1-reader-token-stream (:kind token-stream))
          (= :gravity-reader-release-attestation-seed-retirement-v1
             (:release-attestation-seed-retirement-engine
              token-stream))
          (pos? (:token-count token-stream))
          (= (:token-count token-stream) (count (:tokens token-stream))))
     :form-records-covered?
     (and (seq records)
          (every? #(and (= :gravity-reader-diverse-bootstrap-verification-v1
                           (:diverse-bootstrap-verification-engine %))
                        (= :gravity-reader-release-attestation-seed-retirement-v1
                           (:release-attestation-seed-retirement-engine %)))
                  records))
     :forms-match-stage0?
     (true? (get-in artifact [:stage0-comparison :forms-equal?]))
     :source-spans-covered?
     (every? #(get-in % [:span :source]) records)
     :diagnostics-covered?
     (set/subset?
      (set (concat
            stage1-reader-release-attestation-seed-retirement-diagnostic-ids
            (butlast stage1-reader-execution-diagnostic-ids)))
      diagnostics)
     :limitations
     {:clojure-runtime-interpreter? false
      :clojure-instruction-executor? false
      :clojure-binary-runner? false
      :clojure-character-stream-implementation? false
      :clojure-seed-builtins? false
      :clojure-seed-orchestration? false
      :clojure-driver-runner? false
      :host-command-invocation? false
      :host-file-read? false
      :os-process-boundary? false
      :os-filesystem-read-boundary? false
      :stdout-boundary? false
      :machine-boundary? false
      :kernel-process-scheduler-boundary? false
      :artifact-loader-boundary? false
      :hardware-reset-vector-boundary? false
      :firmware-root-of-trust-boundary? false
      :external-auditor-key-boundary? false
      :physical-device-manufacturing-boundary? false
      :supply-chain-custody-boundary? false
      :independent-diversity-review-boundary? false
      :human-release-governance-boundary? true
      :legal-custody-record-retention-boundary? true
      :deployment-environment-custody-boundary? true
      :clojure-seed-retired? false
      :next-required-capability
      :replace-human-release-governance-and-deployment-custody-with-formal-release-governance-and-full-compiler-self-hosting}
     :status :complete}))

