(defn p15-s23-source-syntax-normalized-source-id?
  [source-unit]
  (and (map? (:identity-inputs source-unit))
       (= (:source-id source-unit)
          (reader-canonical-hash (:identity-inputs source-unit)))))

(defn p15-s23-source-syntax-source-unit-stable?
  [source-path source-unit serialization]
  (and (= :gravity/source-unit (:artifact source-unit))
       (= source-path (:path source-unit))
       (re-find #"^sha256:" (str (:source-id source-unit)))
       (p15-s23-source-syntax-normalized-source-id? source-unit)
       (true? (:source-unit-roundtrip? serialization))
       (true? (:stable-source-id? serialization))))

(defn p15-s23-source-syntax-span-resolves?
  [span]
  (let [primary (:primary span)]
    (or (and (map? primary)
             (:source primary)
             (contains? primary :byte-start)
             (contains? primary :byte-end))
        (and (string? primary)
             (str/starts-with? primary "generated:")))))

(defn p15-s23-source-syntax-objects-preserved?
  [source-unit syntax-stream serialization]
  (and (seq syntax-stream)
       (every? #(= :gravity/syntax-object (:artifact %)) syntax-stream)
       (every? #(re-find #"^sha256:" (str (:syntax/id %))) syntax-stream)
       (= (count syntax-stream) (count (set (map :syntax/id syntax-stream))))
       (every? #(= (:source-id source-unit) (get-in % [:source :source-id]))
               syntax-stream)
       (every? #(p15-s23-source-syntax-span-resolves? (:span %))
               syntax-stream)
       (every? #(seq (:origin %)) syntax-stream)
       (true? (:syntax-object-roundtrip? serialization))
       (true? (:stable-syntax-ids? serialization))
       (true? (:origin-links-preserved? serialization))))

(defn p15-s23-source-syntax-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        source-unit (:source-unit-record candidate)
        syntax-stream (:syntax-object-stream candidate)
        serialization (:serialization-roundtrip-record candidate)
        verifier (:syntax-verification-report candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-source-syntax-required-preserves preserves)]
    (vec
     (concat
      (when-not (= :gravity/source-unit-and-syntax-serialization-proof
                   (:artifact proof-contract))
        [(p15-s23-source-syntax-diagnostic-record
          source-path "P15S23S001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not (p15-s23-source-syntax-source-unit-stable?
                 source-path source-unit serialization)
        [(p15-s23-source-syntax-diagnostic-record
          source-path "P15S23S002" source-unit
          {:source-unit-roundtrip? (:source-unit-roundtrip? serialization)
           :stable-source-id? (:stable-source-id? serialization)})])
      (when-not (and (p15-s23-source-syntax-objects-preserved?
                      source-unit syntax-stream serialization)
                     (empty? missing-preserves))
        [(p15-s23-source-syntax-diagnostic-record
          source-path "P15S23S003" syntax-stream
          {:syntax-object-roundtrip?
           (:syntax-object-roundtrip? serialization)
           :stable-syntax-ids? (:stable-syntax-ids? serialization)
           :origin-links-preserved? (:origin-links-preserved? serialization)
           :missing-preserves (vec (sort missing-preserves))})])
      (when-not (and (true? (:roundtrip? serialization))
                     (true? (:c3-serialization-roundtrip? serialization))
                     (= :passed (:status verifier)))
        [(p15-s23-source-syntax-diagnostic-record
          source-path "P15S23S004" serialization
          {:roundtrip? (:roundtrip? serialization)
           :c3-serialization-roundtrip?
           (:c3-serialization-roundtrip? serialization)
           :syntax-verifier-status (:status verifier)})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-source-syntax-diagnostic-record
          source-path "P15S23S005" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired? (:clojure-seed-retired? claims)})])))))

(defn p15-s23-source-syntax-summary
  [syntax-stream]
  (mapv #(select-keys % [:artifact :syntax/id :form :span :source :origin
                         :identity :facts :phase :profile :version
                         :immutable?])
        syntax-stream))

(defn p15-s23-source-syntax-c2-capability-proof
  [artifact]
  (let [source-unit (:source-unit-record artifact)
        hashes (:incremental-reader-hashes artifact)
        lexical (:lexical-product-validation artifact)]
    {:source-unit-hash-stable?
     (boolean
      (and (= :gravity/source-unit (:artifact source-unit))
           (p15-s23-source-syntax-normalized-source-id? source-unit)
           (re-find #"^sha256:" (str (:source-id source-unit)))))
     :token-and-form-spans-present?
     (and (every? #(and (:token-id %)
                        (get-in % [:span :byte-start])
                        (get-in % [:span :byte-end]))
                  (:token-stream artifact))
          (every? #(and (:form-id %)
                        (get-in % [:span :byte-start])
                        (get-in % [:span :byte-end]))
                  (:form-tree artifact)))
     :reader-source-map-present?
     (and (seq (:reader-source-map artifact))
          (every? #(and (:syntax-id %) (:span %))
                  (:reader-source-map artifact)))
     :syntax-seeds-preserve-origins?
     (every? #(contains? % :generated-origin)
             (:syntax-seed-stream artifact))
     :incremental-hashes-stable?
     (and (= :stable (:status hashes))
          (every? #(re-find #"^sha256:" (str (get hashes %)))
                  [:source-unit :token-stream :form-tree
                   :syntax-seed-stream :extension-invocation-set
                   :reader-diagnostics]))
     :lexical-token-stream?
     (every? true?
             (map lexical
                  [:ordered-token-ids-unique?
                   :token-raw-slices-exact?
                   :token-provenance-complete?
                   :no-token-contains-top-level-form?]))
     :nested-form-tree?
     (every? true?
             (map lexical
                  [:form-ids-unique?
                   :graph-valid?
                   :root-form-ids-resolve?
                   :form-raw-slices-exact?
                   :form-links-resolve?
                   :parent-spans-enclose-children?
                   :collection-delimiters-resolve?]))
     :representation-status :genuine-lexical-token-and-recursive-form-tree
     :status :partial}))

(defn p15-s23-source-syntax-c2-artifact
  ([source-path source-text]
   (p15-s23-source-syntax-c2-artifact
    source-path source-text (reader-project-context-for-source source-path)))
  ([source-path source-text project-context]
   (try
    (let [reader-options standard-reader-options
        products (c2-reader-products source-path source-text reader-options
                                     project-context)
        forms (:parsed-values products)
        _ (validate-ns-syntax! source-path forms)
        module-context (reader-module-context forms)
        source-unit (:source-unit products)
        token-stream (:token-stream products)
        form-tree (:form-tree products)
        top-level-form-ids (:root-form-ids products)
        syntax-seeds (c2-syntax-seed-stream source-path products module-context)
        deferred-literals (c2-deferred-semantic-literals form-tree)
        literal-records (c2-literal-records form-tree)
        extension-invocations []
        diagnostics []
        lexical-validation (c2-lexical-product-validation
                            source-text token-stream form-tree
                            top-level-form-ids)
        lexical-token-stream?
        (every? true?
                (map lexical-validation
                     [:ordered-token-ids-unique?
                      :token-raw-slices-exact?
                      :token-provenance-complete?
                      :no-token-contains-top-level-form?]))
        nested-form-tree?
        (every? true?
                (map lexical-validation
                     [:form-ids-unique?
                      :graph-valid?
                      :root-form-ids-resolve?
                      :form-raw-slices-exact?
                      :form-links-resolve?
                      :parent-spans-enclose-children?
                      :collection-delimiters-resolve?]))
        incremental-hashes (c2-incremental-hashes
                            source-unit token-stream form-tree syntax-seeds
                            extension-invocations diagnostics)
        integrity-record (c2-reader-product-integrity-record
                          source-unit top-level-form-ids incremental-hashes
                          literal-records deferred-literals)
        artifact-base
        {:kind :gravity/stage0-c2-reader-document-artifact
         :task "P15-S23"
         :document-set ["C2"]
         :governing-document
         "docs/phase-06-compiler-architecture/081-c2-reader-implementation-design.md"
         :pass {:name :p15-s23-source-unit-reader-proof
                :input :gravity-source-bytes
                :output :source-unit-and-reader-source-map
                :requires [:source-bytes :reader-options]
                :preserves [:source-spans :source-unit-identity
                            :reader-origin :literal-facts]
                :emits [:source-unit-record :token-stream :form-tree
                        :reader-source-map :incremental-reader-hashes]
                :rejects p15-s23-source-syntax-serialization-diagnostic-ids}
         :status :partial
         :source-unit-record source-unit
         :representation-boundary
         {:token-stream :ordered-utf8-lexical-token-stream
          :form-tree :recursive-delimiter-linked-form-tree
          :lexical-token-stream? lexical-token-stream?
          :nested-form-tree? nested-form-tree?
          :status (if (and lexical-token-stream? nested-form-tree?)
                    :complete-for-slice
                    :failed)}
         :token-stream token-stream
         :form-tree form-tree
         :top-level-form-ids top-level-form-ids
         :parsed-semantic-values (:parsed-values products)
         :lexical-product-validation lexical-validation
         :syntax-seed-stream syntax-seeds
         :reader-source-map (mapv #(select-keys % [:syntax-id :form-id :span])
                                  syntax-seeds)
         :literal-decoding-records literal-records
         :trivia-retention-records (c2-trivia-records token-stream)
         :reader-extension-invocation-records extension-invocations
         :semantic-error-deferment-record
         {:artifact :gravity/semantic-error-deferment
          :forms-retained [:unknown-symbol :profile-illegal-form
                           :zero-denominator-ratio]
          :deferred-literal-records deferred-literals
          :semantic-analysis-in-reader? false
          :module-parser-invoked? false
          :deferred? true
          :owner-phases [:namespace-analysis :type-check :profile-validate
                         :numeric-mode-validation]}
         :reader-diagnostics diagnostics
         :incremental-reader-hashes incremental-hashes
         :reader-product-integrity integrity-record
         :p15-s23-source-syntax-reader-results
         {:source-unit-status :complete
          :source-map-status :complete
          :incremental-hash-status :complete
          :token-stream-status :complete-for-slice
          :form-tree-status :complete-for-slice
          :abbreviation-fixture-status :not-required-for-p15-source-proof
          :status :partial}
         :diagnostics []}
        proof (p15-s23-source-syntax-c2-capability-proof artifact-base)
        _ (when-not (and (:lexical-token-stream? proof)
                         (:nested-form-tree? proof))
            (p15-s23-source-syntax-serialization-fail!
             "P15S23S003" source-path lexical-validation
             {:missing-fields [:lexical-token-stream :nested-form-tree]}))
        artifact (assoc artifact-base :capability-based-proof proof)]
      (assoc artifact :artifact-id (c2-reader-artifact-id artifact)))
     (catch clojure.lang.ExceptionInfo ex
       (c2-reader-remap-exception! source-path ex)))))

(declare c2-top-level-products)

(defn p15-s23-source-syntax-c3-artifact
  [source-path c2-artifact]
  (let [integrity-report
        (c3-validate-c2-reader-artifact! source-path c2-artifact)
        source-unit (:source-unit-record c2-artifact)
        top-level-products (c2-top-level-products c2-artifact)
        base-syntax (mapv (fn [seed {:keys [form-record token-record]}]
                            (c3-syntax-object seed form-record token-record
                                              source-unit c2-artifact
                                              integrity-report))
                          (:syntax-seed-stream c2-artifact)
                          top-level-products)
        generated (c3-generated-syntax-object
                   (or (some #(when (seq (:origin %)) %) base-syntax)
                       (first base-syntax)))
        syntax-stream (conj base-syntax generated)
        serialization (c3-syntax-serialization-fixture syntax-stream)
        verifier (c3-syntax-verification-report syntax-stream serialization
                                                c2-artifact)
        artifact-base
        {:kind :gravity/stage0-c3-syntax-object-artifact
         :task "P15-S23"
         :document-set ["C3"]
         :governing-document c3-syntax-governing-document
         :pass {:name :p15-s23-source-syntax-serialization-proof
                :input :source-unit-and-reader-source-map
                :output :syntax-object-serialization-proof
                :requires [:source-unit-record :syntax-seed-stream
                           :reader-source-map]
                :preserves [:source-spans :syntax-identity :origin-chain
                            :metadata :hygiene]
                :emits [:syntax-object-stream
                        :syntax-verification-report
                        :syntax-serialization-fixture
                        :origin-chain-graph]
                :rejects c3-syntax-diagnostic-ids}
         :c2-reader-artifact
         (c3-reader-artifact-view c2-artifact)
         :syntax-object-schema (c3-syntax-schema)
         :syntax-object-stream syntax-stream
         :hygiene-context-map (c3-hygiene-context-map syntax-stream)
         :origin-chain-graph (c3-origin-chain-graph syntax-stream)
         :metadata-ledger (c3-metadata-ledger syntax-stream)
         :generated-syntax-report (c3-generated-syntax-report syntax-stream)
         :fact-ledger (c3-fact-ledger syntax-stream)
         :syntax-serialization-fixture serialization
         :syntax-verification-report verifier
         :rejected-design-coverage c3-syntax-rejected-designs
         :p15-s23-source-syntax-results
         {:syntax-object-count (count syntax-stream)
          :serialization-status :complete
          :verifier-status (:status verifier)
          :status (if (= :passed (:status verifier)) :complete :failed)}
         :diagnostics []}
        _ (c3-syntax-validate! source-path artifact-base)
        capability-proof (c3-syntax-capability-proof artifact-base)
        artifact (assoc artifact-base
                        :capability-based-proof capability-proof)]
    (assoc artifact :artifact-id (c3-artifact-id artifact))))

(defn p15-s23-source-syntax-serialization-roundtrip-record
  [c2-artifact c3-artifact]
  (let [source-unit (:source-unit-record c2-artifact)
        syntax-summary
        (p15-s23-source-syntax-summary (:syntax-object-stream c3-artifact))
        payload {:artifact
                 :gravity/p15-s23-source-syntax-serialization-payload
                 :source-unit source-unit
                 :reader-source-map (:reader-source-map c2-artifact)
                 :syntax-summary syntax-summary
                 :syntax-serialization-fixture
                 (:syntax-serialization-fixture c3-artifact)}
        identity-payload
        (-> payload
            (update :source-unit
                    #(-> %
                         (dissoc :path)
                         (update :project-root-record dissoc :path)))
            (update :reader-source-map
                    (fn [records]
                      (mapv #(update % :span c2-path-neutral-span) records)))
            (update :syntax-summary
                    #(mapv c3-path-neutral-syntax-object %)))
        canonical (pr-str payload)
        roundtrip (read-string canonical)
        syntax-ids (mapv :syntax/id syntax-summary)]
    {:artifact :gravity/p15-s23-source-syntax-serialization-roundtrip
     :format :edn
     :serialization-id (reader-canonical-hash identity-payload)
     :payload payload
     :canonical canonical
     :roundtrip? (= payload roundtrip)
     :source-unit-roundtrip?
     (= (:source-unit payload) (:source-unit roundtrip))
     :syntax-object-roundtrip?
     (= (:syntax-summary payload) (:syntax-summary roundtrip))
     :stable-source-id?
     (and (re-find #"^sha256:" (str (:source-id source-unit)))
          (p15-s23-source-syntax-normalized-source-id? source-unit))
     :stable-syntax-ids?
     (and (every? #(re-find #"^sha256:" (str %)) syntax-ids)
          (= (count syntax-ids) (count (set syntax-ids))))
     :origin-links-preserved?
     (every? #(seq (:origin %)) syntax-summary)
     :c3-serialization-roundtrip?
     (true? (get-in c3-artifact [:syntax-serialization-fixture :roundtrip?]))
     :syntax-verifier-passed?
     (= :passed (get-in c3-artifact [:syntax-verification-report :status]))
     :status :complete}))

