(defn p15-s23-source-syntax-rejected-records
  [source-path]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-source-syntax-proof-diagnostics source-path candidate)})
        p15-s23-source-syntax-rejected-candidates))

(defn p15-s23-source-syntax-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-source-syntax-serialization-diagnostic-stream
   :stage :p15-s23-source-syntax-serialization-proof
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-source-syntax-serialization-proof
            :message
            (get p15-s23-source-syntax-serialization-diagnostic-messages
                 id)})
         p15-s23-source-syntax-serialization-diagnostic-ids)
   :status :complete})

(defn p15-s23-source-syntax-serialization-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-source-syntax-serialization-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-source-syntax-fixtures artifact)))
        serialization (:serialization-roundtrip-record artifact)]
    {:source-syntax-proof-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :compiler-source-inventory-linked?
     (= :gravity/p15-s23-compiler-source-inventory-artifact
        (get-in artifact [:compiler-source-inventory-artifact :kind]))
     :c2-reader-artifact-linked?
     (= :gravity/stage0-c2-reader-document-artifact
        (get-in artifact [:c2-reader-artifact :kind]))
     :c3-syntax-artifact-linked?
     (= :gravity/stage0-c3-syntax-object-artifact
        (get-in artifact [:c3-syntax-artifact :kind]))
     :source-unit-roundtrips?
     (true? (:source-unit-roundtrip? serialization))
     :syntax-objects-roundtrip?
     (true? (:syntax-object-roundtrip? serialization))
     :source-spans-preserved?
     (every? #(p15-s23-source-syntax-span-resolves? (:span %))
             (:syntax-object-stream artifact))
     :syntax-identities-preserved?
     (true? (:stable-syntax-ids? serialization))
     :origin-chains-preserved?
     (true? (:origin-links-preserved? serialization))
     :syntax-verifier-passed?
     (= :passed (get-in artifact [:syntax-verification-report :status]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-source-syntax-serialization-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-source-syntax-serialization-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :compiles-whole-claimed-subset? false
      :next-required-capability
      :implement_core_lowering_and_diagnostic_preservation_report}}))

(defn p15-s23-source-syntax-serialization-proof-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-source-syntax-serialization-proof)
        c2-artifact
        (p15-s23-source-syntax-c2-artifact source-path
                                           (:source-text source-data))
        c3-artifact
        (p15-s23-source-syntax-c3-artifact source-path c2-artifact)
        serialization
        (p15-s23-source-syntax-serialization-roundtrip-record
         c2-artifact c3-artifact)
        candidate {:proof-contract proof-contract
                   :source-unit-record (:source-unit-record c2-artifact)
                   :syntax-object-stream (:syntax-object-stream c3-artifact)
                   :serialization-roundtrip-record serialization
                   :syntax-verification-report
                   (:syntax-verification-report c3-artifact)}
        diagnostics
        (p15-s23-source-syntax-proof-diagnostics source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-source-syntax-serialization-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        compiler-source-inventory
        (p15-s23-compiler-source-inventory-source-artifact source-path)
        proof-id
        (reader-canonical-hash
         {:source-id
          (get-in c2-artifact [:source-unit-record :source-id])
          :c2-artifact (:artifact-id c2-artifact)
          :c3-artifact (:artifact-id c3-artifact)
          :serialization (:serialization-id serialization)
          :proof-contract proof-contract})
        rejected-records
        (p15-s23-source-syntax-rejected-records source-path)
        artifact-base
        {:kind :gravity/p15-s23-source-syntax-serialization-proof-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-source-syntax-serialization-proof
         :source-path source-path
         :proof-id proof-id
         :compiler-source-inventory-artifact compiler-source-inventory
         :proof-contract proof-contract
         :c2-reader-artifact
         (select-keys c2-artifact
                      [:kind :artifact-id :status :source-unit-record
                       :reader-source-map :incremental-reader-hashes
                       :representation-boundary
                       :p15-s23-source-syntax-reader-results
                       :capability-based-proof])
         :c3-syntax-artifact
         (select-keys c3-artifact
                      [:kind :artifact-id :syntax-serialization-fixture
                       :syntax-verification-report :capability-based-proof])
         :source-unit-record (:source-unit-record c2-artifact)
         :syntax-object-stream (:syntax-object-stream c3-artifact)
         :syntax-object-summary
         (p15-s23-source-syntax-summary (:syntax-object-stream c3-artifact))
         :syntax-verification-report (:syntax-verification-report c3-artifact)
         :serialization-roundtrip-record serialization
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-source-syntax-fixtures
         [{:fixture source-path
           :status :accepted
           :source-id
           (get-in c2-artifact [:source-unit-record :source-id])
           :syntax-object-count (count (:syntax-object-stream c3-artifact))
           :serialization-id (:serialization-id serialization)}]
         :rejected-p15-s23-source-syntax-fixtures rejected-records
         :p15-s23-source-syntax-serialization-diagnostic-stream
         (p15-s23-source-syntax-diagnostic-stream source-path proof-id)
         :p15-s23-source-syntax-serialization-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-source-syntax-serialization-diagnostic-ids)
          :syntax-object-count (count (:syntax-object-stream c3-artifact))
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-source-syntax-serialization-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-source-syntax-serialization-proof-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-source-syntax-serialization-fail!
     "P15S23S001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-source-syntax-serialization-proof-source-artifact path))

(def p15-s23-core-diagnostic-required-preserves
  #{:source-spans :syntax-identity :origin-chain :diagnostic-codes
    :artifact-provenance :remediation})

(def p15-s23-core-diagnostic-messages
  {"P15S23D001" "P15-S23 core lowering and diagnostic preservation report is missing"
   "P15S23D002" "P15-S23 core lowering evidence does not preserve source, syntax, origin, or evaluation-order facts"
   "P15S23D003" "P15-S23 diagnostic preservation evidence is incomplete or unstable"
   "P15S23D004" "P15-S23 core lowering or diagnostic evidence is not linked to the required artifacts"
   "P15S23D005" "P15-S23 core lowering and diagnostic preservation report makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-core-diagnostic-ids
  ["P15S23D001" "P15S23D002" "P15S23D003" "P15S23D004"
   "P15S23D005"])

(def p15-s23-core-diagnostic-forms
  #{:quote :if :do :let :fn :loop :recur :def :var :set! :try :throw :match
    :call :literal :symbol :generated-form})

(defn p15-s23-core-diagnostic-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-core-diagnostic-messages
              id
              "P15-S23 core lowering and diagnostic preservation failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-core-lowering-diagnostic-preservation-report
                 :diagnostic-family
                 :p15-s23-core-lowering-diagnostic-preservation-report
                 :value value
                 :remediation "Keep P15-S23 core lowering and diagnostic preservation evidence in Gravity-owned source, preserve source spans, syntax ids, origin chains, diagnostic ids, artifact provenance, and remediation, and keep self-hosting claims false until the complete evidence bundle exists."}
                data)))

(defn p15-s23-core-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-core-lowering-diagnostic-preservation-report
   :source-span {:source source-path}
   :message (get p15-s23-core-diagnostic-messages id)
   :facts data
   :observed value
   :remediation
   :repair_gravity_core_lowering_and_diagnostic_preservation_report})

(defn p15-s23-core-diagnostic-core-form
  [value]
  (cond
    (and (seq? value) (contains? core-forms (first value)))
    (keyword (name (first value)))
    (seq? value) :call
    (symbol? value) :symbol
    :else :literal))

(defn p15-s23-core-diagnostic-evaluation-order
  [core-form value]
  (case core-form
    :quote []
    :if [:condition :then-or-else]
    :do (mapv (fn [idx] [:expr idx]) (range (count (rest value))))
    :let [:bindings-left-to-right :body-left-to-right]
    :fn [:call-arguments-left-to-right]
    :loop [:loop-bindings-left-to-right :body-left-to-right]
    :recur [:arguments-left-to-right]
    :def [:initializer]
    :var []
    :set! [:value]
    :try [:body :matching-handler]
    :throw [:value]
    :match [:scrutinee :selected-clause]
    :call [:operator :arguments-left-to-right]
    []))

(defn p15-s23-core-diagnostic-core-node
  [idx syntax]
  (let [value (get-in syntax [:form :value])
        core-form (p15-s23-core-diagnostic-core-form value)
        node-input {:syntax-id (:syntax/id syntax)
                    :form core-form
                    :value (pr-str value)
                    :span (:span syntax)
                    :origin (:origin syntax)
                    :idx idx}
        node-id (str "sha256:" (sha256-hex (pr-str node-input)))]
    {:artifact :gravity/core-node
     :node-id node-id
     :form core-form
     :children {:surface-form (pr-str value)}
     :source {:syntax-id (:syntax/id syntax)
              :span (:span syntax)
              :origin-chain (:origin syntax)}
     :binding-context :p15-s23-compiler-source
     :profile (:profile syntax)
     :target :jvm
     :metadata (:metadata syntax)
     :facts {:source-syntax-id (:syntax/id syntax)
             :source-form-kind (get-in syntax [:form :kind])}
     :effects #{}
     :capabilities #{}
     :unsafe-metadata nil
     :generated? (= :generated-form (get-in syntax [:form :kind]))
     :evaluation-order
     (p15-s23-core-diagnostic-evaluation-order core-form value)
     :lowering-rule core-form
     :version 1}))

(defn p15-s23-core-diagnostic-c6-artifact
  [source-path source-syntax-artifact pipeline-artifact]
  (let [syntax-stream (:syntax-object-stream source-syntax-artifact)
        nodes (mapv p15-s23-core-diagnostic-core-node
                    (range)
                    syntax-stream)
        surface-map
        {:artifact :gravity/c6-surface-to-core-map
         :entries (mapv (fn [node]
                          {:surface-syntax (get-in node [:source :syntax-id])
                           :core-root (:node-id node)
                           :core-form (:form node)
                           :generated? (:generated? node)})
                        nodes)
         :status :complete}
        trace
        {:artifact :gravity/c6-desugaring-trace
         :records (mapv (fn [node]
                          {:surface-syntax
                           (get-in node [:source :syntax-id])
                           :surface-kind (:form node)
                           :core-root (:node-id node)
                           :introduced-forms
                           (if (:generated? node) [(:form node)] [])
                           :preserved
                           p15-s23-core-diagnostic-required-preserves
                           :introduced-origin
                           [{:core-node (:node-id node)
                             :reason :p15-s23-source-lowering
                             :from (get-in node [:source :syntax-id])}]
                           :evaluation-order (:evaluation-order node)
                           :diagnostics []})
                        nodes)
         :status :complete}
        evaluation
        {:artifact :gravity/c6-evaluation-order-records
         :records (mapv (fn [node]
                          {:core-node (:node-id node)
                           :form (:form node)
                           :order (:evaluation-order node)
                           :effect-sensitive? false
                           :source (:source node)})
                        nodes)
         :status :complete}
        verifier
        {:artifact :gravity/c6-core-verifier-report
         :valid-core-forms?
         (every? #(contains? p15-s23-core-diagnostic-forms (:form %)) nodes)
         :source-and-generated-origins-valid?
         (every? #(and (get-in % [:source :syntax-id])
                       (p15-s23-source-syntax-span-resolves?
                        (get-in % [:source :span]))
                       (seq (get-in % [:source :origin-chain])))
                 nodes)
         :evaluation-order-present?
         (every? #(contains? % :evaluation-order) nodes)
         :profile-target-annotations-valid?
         (every? #(and (:profile %) (:target %)) nodes)
         :surface-only-forms-absent? true
         :status :passed}
        artifact-base
        {:kind :gravity/stage0-c6-core-lowering-artifact
         :task "P15-S23"
         :document-set ["C6"]
         :governing-document c6-lowering-governing-document
         :pass {:name :p15-s23-core-lowering-proof
                :input :p15-s23-source-syntax-serialization-proof
                :output :p15-s23-core-lowering-evidence
                :requires [:syntax-object-stream :source-unit-record
                           :compiler-pipeline-manifest]
                :preserves [:source-spans :syntax-identity :origin-chain
                            :metadata :profile :effects :capabilities]
                :emits [:core-ast-module :surface-to-core-map
                        :desugaring-trace :evaluation-order-records
                        :core-verifier-report]
                :rejects p15-s23-core-diagnostic-ids}
         :source-path source-path
         :source-syntax-artifact
         (select-keys source-syntax-artifact
                      [:kind :artifact-id :proof-id :source-unit-record
                       :syntax-object-summary :serialization-roundtrip-record])
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :manifest-id])
         :core-ast-module {:artifact :gravity/core-ast-module
                           :module :gravity.bootstrap.p15-s23.compiler
                           :roots (mapv :node-id nodes)
                           :node-count (count nodes)
                           :status :complete}
         :core-node-table nodes
         :surface-to-core-map surface-map
         :desugaring-trace trace
         :evaluation-order-records evaluation
         :domain-boundary-records []
         :core-verifier-report verifier
         :lowering-rule-invalidation
         {:artifact :gravity/c6-lowering-rule-invalidation
          :rule-version "p15-s23-core.1"
          :rules (vec (sort (set (map :lowering-rule nodes))))
          :invalidates [:typed-core :effects :ownership :safety :mir
                        :diagnostics]
          :status :stable}
         :p15-s23-core-lowering-results
         {:core-node-count (count nodes)
          :source-syntax-linked? true
          :pipeline-manifest-linked? true
          :core-verifier-status (:status verifier)
          :status :complete}
         :diagnostics []}
        proof {:source-syntax-linked? true
               :pipeline-manifest-linked? true
               :core-nodes-produced? (boolean (seq nodes))
               :source-to-core-map-present?
               (= :complete (:status surface-map))
               :evaluation-order-preserved?
               (= :complete (:status evaluation))
               :source-spans-preserved?
               (every? #(p15-s23-source-syntax-span-resolves?
                         (get-in % [:source :span]))
                       nodes)
               :syntax-identities-preserved?
               (= (count nodes)
                  (count (set (map #(get-in % [:source :syntax-id])
                                   nodes))))
               :origin-chains-preserved?
               (every? #(seq (get-in % [:source :origin-chain])) nodes)
               :core-verifier-passed? (= :passed (:status verifier))
               :status :complete}
        artifact (assoc artifact-base :capability-based-proof proof)]
    (assoc artifact :artifact-id (c4-artifact-id artifact))))

(defn p15-s23-core-diagnostic-stable-id
  [diagnostic]
  (str "diag-"
       (sha256-hex
        (pr-str {:rule (:rule diagnostic)
                 :stage (:stage diagnostic)
                 :primary-artifact (get-in diagnostic [:primary :artifact])
                 :facts (:facts diagnostic)}))))

(defn p15-s23-core-diagnostic-preserved-diagnostic
  [source-path c6-artifact id idx]
  (let [node (nth (:core-node-table c6-artifact)
                  (mod idx (count (:core-node-table c6-artifact))))
        diagnostic
        {:artifact :gravity/diagnostic
         :rule id
         :severity :error
         :stage :p15-s23-core-lowering-diagnostic-preservation-report
         :message-key
         (keyword "p15-s23.core-diagnostic" (str/lower-case id))
         :primary {:span (get-in node [:source :span])
                   :syntax-id (get-in node [:source :syntax-id])
                   :artifact (:node-id node)}
         :related [{:role :lowered-from
                    :span (get-in node [:source :span])
                    :artifact
                    (get-in node [:source :syntax-id])}]
         :origin-chain (get-in node [:source :origin-chain])
         :profile (:profile node)
         :target (:target node)
         :involved-artifacts [(:artifact-id c6-artifact) (:node-id node)]
         :facts {:diagnostic id
                 :core-node (:node-id node)
                 :source-path source-path
                 :preserves p15-s23-core-diagnostic-required-preserves}
         :remediation
         [{:kind :repair-p15-s23-core-diagnostic-preservation}]
         :redactions []
         :lifecycle :active
         :ordering-key [id (:node-id node)]}]
    (assoc diagnostic
           :diagnostic-id
           (p15-s23-core-diagnostic-stable-id diagnostic))))

(defn p15-s23-core-diagnostic-c15-artifact
  [source-path c6-artifact]
  (let [diagnostics
        (mapv #(p15-s23-core-diagnostic-preserved-diagnostic
                source-path c6-artifact %1 %2)
              p15-s23-core-diagnostic-ids
              (range))
        preservation-report
        {:artifact :gravity/p15-s23-diagnostic-preservation-report
         :source-path source-path
         :core-lowering-artifact-id (:artifact-id c6-artifact)
         :diagnostic-rules (mapv :rule diagnostics)
         :stable-ids?
         (every? #(= (:diagnostic-id %)
                     (p15-s23-core-diagnostic-stable-id
                      (dissoc % :diagnostic-id)))
                 diagnostics)
         :source-spans-preserved?
         (every? #(p15-s23-source-syntax-span-resolves?
                   (get-in % [:primary :span]))
                 diagnostics)
         :syntax-identities-preserved?
         (every? #(get-in % [:primary :syntax-id]) diagnostics)
         :origin-chains-preserved?
         (every? #(seq (:origin-chain %)) diagnostics)
         :remediation-preserved?
         (every? #(seq (:remediation %)) diagnostics)
         :status :complete}
        artifact-base
        {:kind :gravity/stage0-c15-compiler-diagnostics-artifact
         :task "P15-S23"
         :document-set ["C15"]
         :governing-document c15-diagnostics-governing-document
         :pass {:name :p15-s23-diagnostic-preservation-proof
                :input :p15-s23-core-lowering-evidence
                :output :p15-s23-diagnostic-preservation-evidence
                :requires [:core-ast-module :surface-to-core-map
                           :diagnostic-schema]
                :preserves [:diagnostic-codes :source-spans
                            :syntax-identity :origin-chain
                            :artifact-provenance :remediation]
                :emits [:diagnostic-preservation-report
                        :diagnostic-stream :golden-diagnostic-fixtures]
                :rejects p15-s23-core-diagnostic-ids}
         :c6-core-lowering-artifact
         (select-keys c6-artifact
                      [:kind :artifact-id :core-ast-module
                       :surface-to-core-map :core-verifier-report
                       :capability-based-proof])
         :diagnostic-schema
         {:artifact :gravity/diagnostic-schema
          :status :complete
          :required-fields c15-diagnostic-required-fields
          :stable-id-input [:rule :primary-artifact :stage :facts]}
         :diagnostic-stream
         {:artifact :gravity/diagnostic-stream
          :stage :p15-s23-core-lowering-diagnostic-preservation-report
          :input-artifact (:artifact-id c6-artifact)
          :diagnostics diagnostics
          :summary (frequencies (map :severity diagnostics))
          :deterministic-ordering-key :ordering-key
          :redaction-policy :public-safe
          :status :complete}
         :diagnostic-preservation-report preservation-report
         :golden-diagnostic-fixtures
         (mapv (fn [id]
                 {:fixture (str "p15-s23-core-diagnostic-" id)
                  :rule id
                  :asserts [:rule :severity :primary :related :stage
                            :profile :target :facts :remediation
                            :ordering]
                  :status :matched})
               p15-s23-core-diagnostic-ids)
         :p15-s23-diagnostic-preservation-results
         {:diagnostic-count (count diagnostics)
          :status :complete}
         :diagnostics []}
        proof {:c6-core-lowering-input-linked? true
               :diagnostic-schema-complete? true
               :diagnostic-stream-deterministic?
               (= diagnostics (vec (sort-by :ordering-key diagnostics)))
               :stable-diagnostic-ids?
               (:stable-ids? preservation-report)
               :source-spans-preserved?
               (:source-spans-preserved? preservation-report)
               :syntax-identities-preserved?
               (:syntax-identities-preserved? preservation-report)
               :origin-chains-preserved?
               (:origin-chains-preserved? preservation-report)
               :remediation-preserved?
               (:remediation-preserved? preservation-report)
               :golden-fixtures-matched?
               (every? #(= :matched (:status %))
                       (:golden-diagnostic-fixtures artifact-base))
               :diagnostics-covered?
               (= (set p15-s23-core-diagnostic-ids)
                  (set (map :rule diagnostics)))
               :status :complete}
        artifact (assoc artifact-base :capability-based-proof proof)]
    (assoc artifact :artifact-id (c4-artifact-id artifact))))

(defn p15-s23-core-diagnostic-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        c6-artifact (:c6-core-lowering-artifact candidate)
        c15-artifact (:c15-diagnostics-artifact candidate)
        source-syntax (:source-syntax-artifact candidate)
        pipeline (:compiler-pipeline-manifest-artifact candidate)
        preservation (:diagnostic-preservation-report candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-core-diagnostic-required-preserves
                        preserves)]
    (vec
     (concat
      (when-not (= :gravity/core-lowering-and-diagnostic-preservation-report
                   (:artifact proof-contract))
        [(p15-s23-core-diagnostic-record
          source-path "P15S23D001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not (and (= :gravity/stage0-c6-core-lowering-artifact
                        (:kind c6-artifact))
                     (= :passed
                        (get-in c6-artifact
                                [:core-verifier-report :status]))
                     (seq (:core-node-table c6-artifact))
                     (true?
                      (get-in c6-artifact
                              [:capability-based-proof
                               :source-spans-preserved?]))
                     (true?
                      (get-in c6-artifact
                              [:capability-based-proof
                               :origin-chains-preserved?]))
                     (empty? missing-preserves))
        [(p15-s23-core-diagnostic-record
          source-path "P15S23D002" c6-artifact
          {:missing-preserves (vec (sort missing-preserves))
           :core-verifier-status
           (get-in c6-artifact [:core-verifier-report :status])})])
      (when-not (and (= :gravity/stage0-c15-compiler-diagnostics-artifact
                        (:kind c15-artifact))
                     (= :complete (:status preservation))
                     (true? (:stable-ids? preservation))
                     (true? (:source-spans-preserved? preservation))
                     (true? (:syntax-identities-preserved? preservation))
                     (true? (:origin-chains-preserved? preservation))
                     (true? (:remediation-preserved? preservation))
                     (= (set p15-s23-core-diagnostic-ids)
                        (set (:diagnostic-rules preservation))))
        [(p15-s23-core-diagnostic-record
          source-path "P15S23D003" preservation
          {:expected-diagnostics p15-s23-core-diagnostic-ids})])
      (when-not (and (= :gravity/p15-s23-source-syntax-serialization-proof-artifact
                        (:kind source-syntax))
                     (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                        (:kind pipeline))
                     (= (:artifact-id c6-artifact)
                        (get-in c15-artifact
                                [:c6-core-lowering-artifact :artifact-id])))
        [(p15-s23-core-diagnostic-record
          source-path "P15S23D004"
          {:source-syntax source-syntax
           :pipeline pipeline
           :c6 (:artifact-id c6-artifact)
           :c15-input
           (get-in c15-artifact
                   [:c6-core-lowering-artifact :artifact-id])}
          {:missing-fields [:artifact-links]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-core-diagnostic-record
          source-path "P15S23D005" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired? (:clojure-seed-retired? claims)})])))))

(def p15-s23-core-diagnostic-rejected-candidates
  [{:fixture :internal-p15-s23-core-diagnostic-missing-report
    :candidate {}
    :expected-diagnostic "P15S23D001"}
   {:fixture :internal-p15-s23-core-diagnostic-core-gap
    :candidate {:proof-contract
                {:artifact
                 :gravity/core-lowering-and-diagnostic-preservation-report
                 :preserves p15-s23-core-diagnostic-required-preserves
                 :self-hosting-claims
                 {:full-language-compiler-self-hosted? false
                  :clojure-seed-retired? false}}
                :c6-core-lowering-artifact
                {:kind :gravity/stage0-c6-core-lowering-artifact
                 :core-verifier-report {:status :failed}
                 :core-node-table []}}
    :expected-diagnostic "P15S23D002"}
   {:fixture :internal-p15-s23-core-diagnostic-preservation-gap
    :candidate {:proof-contract
                {:artifact
                 :gravity/core-lowering-and-diagnostic-preservation-report
                 :preserves p15-s23-core-diagnostic-required-preserves
                 :self-hosting-claims
                 {:full-language-compiler-self-hosted? false
                  :clojure-seed-retired? false}}
                :c15-diagnostics-artifact
                {:kind :gravity/stage0-c15-compiler-diagnostics-artifact}
                :diagnostic-preservation-report
                {:status :failed
                 :stable-ids? false
                 :diagnostic-rules []}}
    :expected-diagnostic "P15S23D003"}
   {:fixture :internal-p15-s23-core-diagnostic-link-gap
    :candidate {:proof-contract
                {:artifact
                 :gravity/core-lowering-and-diagnostic-preservation-report
                 :preserves p15-s23-core-diagnostic-required-preserves
                 :self-hosting-claims
                 {:full-language-compiler-self-hosted? false
                  :clojure-seed-retired? false}}
                :c6-core-lowering-artifact {:artifact-id "c6"}
                :c15-diagnostics-artifact
                {:c6-core-lowering-artifact {:artifact-id "other"}}}
    :expected-diagnostic "P15S23D004"}
   {:fixture :internal-p15-s23-core-diagnostic-overclaim
    :candidate {:proof-contract
                {:artifact
                 :gravity/core-lowering-and-diagnostic-preservation-report
                 :preserves p15-s23-core-diagnostic-required-preserves
                 :self-hosting-claims
                 {:full-language-compiler-self-hosted? true
                  :clojure-seed-retired? true}}
                :c6-core-lowering-artifact
                {:kind :gravity/stage0-c6-core-lowering-artifact
                 :core-verifier-report {:status :passed}
                 :core-node-table [{:node-id "core"}]
                 :capability-based-proof
                 {:source-spans-preserved? true
                  :origin-chains-preserved? true}}
                :c15-diagnostics-artifact
                {:kind :gravity/stage0-c15-compiler-diagnostics-artifact}
                :diagnostic-preservation-report
                {:status :complete
                 :stable-ids? true
                 :source-spans-preserved? true
                 :syntax-identities-preserved? true
                 :origin-chains-preserved? true
                 :remediation-preserved? true
                 :diagnostic-rules p15-s23-core-diagnostic-ids}}
    :expected-diagnostic "P15S23D005"}])

(defn p15-s23-core-diagnostic-rejected-records
  [source-path]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-core-diagnostic-proof-diagnostics source-path
                                                      candidate)})
        p15-s23-core-diagnostic-rejected-candidates))

(defn p15-s23-core-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-core-diagnostic-preservation-diagnostic-stream
   :stage :p15-s23-core-lowering-diagnostic-preservation-report
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage
            :p15-s23-core-lowering-diagnostic-preservation-report
            :message (get p15-s23-core-diagnostic-messages id)})
         p15-s23-core-diagnostic-ids)
   :status :complete})

(defn p15-s23-core-lowering-diagnostic-preservation-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-core-diagnostic-preservation-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-core-diagnostic-fixtures artifact)))
        preservation (:diagnostic-preservation-report artifact)]
    {:core-diagnostic-proof-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :source-syntax-proof-linked?
     (= :gravity/p15-s23-source-syntax-serialization-proof-artifact
        (get-in artifact [:source-syntax-artifact :kind]))
     :compiler-pipeline-manifest-linked?
     (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
        (get-in artifact [:compiler-pipeline-manifest-artifact :kind]))
     :c6-core-lowering-artifact-linked?
     (= :gravity/stage0-c6-core-lowering-artifact
        (get-in artifact [:c6-core-lowering-artifact :kind]))
     :c15-diagnostics-artifact-linked?
     (= :gravity/stage0-c15-compiler-diagnostics-artifact
        (get-in artifact [:c15-diagnostics-artifact :kind]))
     :core-verifier-passed?
     (= :passed (get-in artifact
                        [:c6-core-lowering-artifact
                         :core-verifier-report :status]))
     :source-spans-preserved? (:source-spans-preserved? preservation)
     :syntax-identities-preserved?
     (:syntax-identities-preserved? preservation)
     :origin-chains-preserved? (:origin-chains-preserved? preservation)
     :stable-diagnostic-ids? (:stable-ids? preservation)
     :diagnostic-remediation-preserved?
     (:remediation-preserved? preservation)
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-core-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-core-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :compiles-whole-claimed-subset? false
      :next-required-capability
      :implement_runtime_manifest_and_capability_enforcement_report}}))

(defn p15-s23-core-lowering-diagnostic-preservation-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-core-lowering-diagnostic-preservation-report)
        source-syntax-artifact
        (p15-s23-source-syntax-serialization-proof-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
        c6-artifact
        (p15-s23-core-diagnostic-c6-artifact
         source-path source-syntax-artifact pipeline-artifact)
        c15-artifact
        (p15-s23-core-diagnostic-c15-artifact source-path c6-artifact)
        preservation (:diagnostic-preservation-report c15-artifact)
        candidate {:proof-contract proof-contract
                   :source-syntax-artifact source-syntax-artifact
                   :compiler-pipeline-manifest-artifact pipeline-artifact
                   :c6-core-lowering-artifact c6-artifact
                   :c15-diagnostics-artifact c15-artifact
                   :diagnostic-preservation-report preservation}
        diagnostics
        (p15-s23-core-diagnostic-proof-diagnostics source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-core-diagnostic-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :source-syntax-artifact
                       (:artifact-id source-syntax-artifact)
                       :pipeline-manifest (:artifact-id pipeline-artifact)
                       :c6-artifact (:artifact-id c6-artifact)
                       :c15-artifact (:artifact-id c15-artifact)
                       :proof-contract proof-contract})))
        rejected-records
        (p15-s23-core-diagnostic-rejected-records source-path)
        artifact-base
        {:kind
         :gravity/p15-s23-core-lowering-diagnostic-preservation-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-core-lowering-diagnostic-preservation-report
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :source-syntax-artifact
         (select-keys source-syntax-artifact
                      [:kind :artifact-id :proof-id
                       :serialization-roundtrip-record])
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :manifest-id])
         :c6-core-lowering-artifact
         (select-keys c6-artifact
                      [:kind :artifact-id :core-ast-module
                       :surface-to-core-map :core-verifier-report
                       :capability-based-proof])
         :c15-diagnostics-artifact
         (select-keys c15-artifact
                      [:kind :artifact-id :diagnostic-schema
                       :diagnostic-stream
                       :diagnostic-preservation-report
                       :golden-diagnostic-fixtures
                       :capability-based-proof])
         :core-node-summary
         (mapv #(select-keys % [:artifact :node-id :form :source
                                :profile :target :evaluation-order
                                :lowering-rule])
               (:core-node-table c6-artifact))
         :diagnostic-preservation-report preservation
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-core-diagnostic-fixtures
         [{:fixture source-path
           :status :accepted
           :core-node-count (count (:core-node-table c6-artifact))
           :diagnostic-count
           (count (get-in c15-artifact
                          [:diagnostic-stream :diagnostics]))}]
         :rejected-p15-s23-core-diagnostic-fixtures rejected-records
         :p15-s23-core-diagnostic-preservation-diagnostic-stream
         (p15-s23-core-diagnostic-stream source-path proof-id)
         :p15-s23-core-diagnostic-preservation-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count (count p15-s23-core-diagnostic-ids)
          :core-node-count (count (:core-node-table c6-artifact))
          :status :in-progress}
         :diagnostics []}
        proof
        (p15-s23-core-lowering-diagnostic-preservation-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-core-lowering-diagnostic-preservation-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-core-diagnostic-fail!
     "P15S23D001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-core-lowering-diagnostic-preservation-source-artifact path))

(def p15-s23-runtime-required-preserves
  #{:profile :target :effects :capabilities :source-spans
    :artifact-provenance :runtime-capability-manifest
    :capability-decision-log :runtime-service-classification})

(def p15-s23-runtime-action-families
  #{:filesystem :network :database :environment :process :shell :secrets
    :ffi :raw-memory :model :tool :memory :ai/human-review :observability
    :deployment :package-mutation})

(def p15-s23-runtime-diagnostic-messages
  {"P15S23R001" "P15-S23 runtime manifest/capability enforcement report is missing"
   "P15S23R002" "P15-S23 runtime manifest or family selection is incomplete"
   "P15S23R003" "P15-S23 runtime service classification is incomplete or hides a dependency"
   "P15S23R004" "P15-S23 runtime capability enforcement is incomplete or not deny-by-default"
   "P15S23R005" "P15-S23 runtime audit, principal, delegation, revocation, or redaction evidence is incomplete"
   "P15S23R006" "P15-S23 runtime/capability evidence is not linked to the verified compiler artifacts"
   "P15S23R007" "P15-S23 runtime/capability report makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-runtime-diagnostic-ids
  ["P15S23R001" "P15S23R002" "P15S23R003" "P15S23R004"
   "P15S23R005" "P15S23R006" "P15S23R007"])

(defn p15-s23-runtime-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-runtime-diagnostic-messages
              id
              "P15-S23 runtime manifest/capability proof failed")
         (merge {:source-span {:source source-path}
                 :stage
                 :p15-s23-runtime-manifest-capability-enforcement-report
                 :diagnostic-family
                 :p15-s23-runtime-manifest-capability-enforcement-report
                 :value value
                 :remediation "Keep runtime selection explicit, classify every runtime service, enforce capabilities deny-by-default, preserve principal/audit/redaction records, link the evidence to verified compiler artifacts, and keep self-hosting claims false until the full P15-S23 evidence bundle exists."}
                data)))

(defn p15-s23-runtime-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-runtime-manifest-capability-enforcement-report
   :source-span {:source source-path}
   :message (get p15-s23-runtime-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_runtime_manifest_capability_enforcement_report})

(defn p15-s23-runtime-manifest
  [source-path core-artifact-id]
  {:artifact :gravity/p15-s23-runtime-manifest
   :profile :meta
   :target {:backend :jvm
            :platform :clojure-stage0
            :artifact core-artifact-id}
   :family :managed
   :selection-record
   {:artifact :gravity/runtime-family-selection-record
    :profile :meta
    :target :jvm
    :backend :clojure-stage0
    :selected-family :managed
    :selection-inputs [:profile :target :backend :effects :capabilities
                       :package-policy :deployment-policy]
    :status :complete}
   :services {:linked #{:diagnostic-renderer :source-map-loader
                        :capability-check-hook :panic-diagnostic}
              :generated #{:runtime-check-table
                           :capability-decision-dispatch
                           :denial-diagnostic}
              :delegated #{:clojure-stage0-artifact-store
                           :clojure-stage0-test-runner}
              :external #{}
              :forbidden #{:ambient-filesystem :ambient-network
                           :ambient-environment :ambient-process
                           :ambient-shell :ambient-secret-store
                           :dynamic-eval :unchecked-reflection}}
   :capability-checks true
   :diagnostics
   :gravity/p15-s23-runtime-capability-diagnostic-stream
   :consumed-by [:backend :package :observability :conformance
                 :self-hosting-gate]
   :source-span {:source source-path}
   :status :complete})

(defn p15-s23-runtime-service-table
  [runtime-manifest]
  (let [services (:services runtime-manifest)]
    {:artifact :gravity/p15-s23-runtime-service-table
     :runtime-manifest (:artifact runtime-manifest)
     :classification-kinds #{:linked :generated :delegated :external
                             :forbidden}
     :services services
     :linked (:linked services)
     :generated (:generated services)
     :delegated (:delegated services)
     :external (:external services)
     :forbidden (:forbidden services)
     :hidden-services []
     :backend-consumer :p15-s23-lower-target
     :package-consumer :p15-s23-artifact-bundle
     :observability-consumer :p15-s23-diagnostic-bundle
     :conformance-consumer :p15-s23-self-hosting-gate
     :status :complete}))

