(defn p15-s23-runtime-decision-row
  [source-path artifact-id index spec]
  (merge
   {:artifact :gravity/runtime-capability-decision
    :action-id (:action-id spec)
    :principal :gravity.compiler/p15-s23
    :namespace :gravity.bootstrap.p15-s23.compiler
    :package :gravity/bootstrap
    :artifact-id artifact-id
    :source-span (source-span source-path index)
    :family (:family spec)
    :effect (:effect spec)
    :capability (:capability spec)
    :provider (:provider spec)
    :policy-source :p15-s23-bootstrap-policy
    :policy-inputs [:compiled-effects :package-policy :deployment-policy
                    :artifact-manifest]
    :decision (:decision spec)
    :redaction-status (:redaction-status spec)
    :audit-status :recorded
    :runtime-checks-do-not-grant-authority? true}
   (select-keys spec [:handle-id :delegate-scope])))

(defn p15-s23-runtime-capability-table
  [source-path artifact-id]
  (let [rows (mapv #(p15-s23-runtime-decision-row source-path
                                                  artifact-id
                                                  %1 %2)
                   (range)
                   p15-s23-runtime-action-specs)]
    {:artifact :gravity/p15-s23-runtime-capability-table
     :rows rows
     :decisions (set (map :decision rows))
     :families-covered (set (map :family rows))
     :deny-by-default? true
     :runtime-checks-do-not-grant-authority? true
     :ambient-authority-rejected?
     (boolean (some #(and (= :deny (:decision %))
                          (str/includes? (:action-id %) "ambient"))
                    rows))
     :status :complete}))

(defn p15-s23-runtime-capability-manifest
  [capability-table]
  {:artifact :gravity/runtime-capabilities
   :inputs #{:compiled-effects :package-policy :deployment-policy
             :principal :artifact-manifest}
   :handles p15-s23-runtime-action-families
   :decisions #{:grant :deny :delegate :revoke}
   :records #{:capability-table :decision-log :denial-diagnostic
              :delegated-handle-record :revocation-record
              :redaction-secret-handling-record}
   :rejects #{:ambient-authority :effect-outside-grant
              :tool-contract-violation :profile-as-deployment-authority
              :unscoped-handle :secret-leak}
   :table-artifact (:artifact capability-table)
   :deny-by-default? true
   :status :complete})

(defn p15-s23-runtime-identity-and-audit-records
  [source-path capability-table]
  (let [rows (:rows capability-table)
        grants (filter #(contains? #{:grant :delegate} (:decision %)) rows)
        denials (filter #(= :deny (:decision %)) rows)
        revocations (filter #(= :revoke (:decision %)) rows)]
    {:principal-identity-record
     {:artifact :gravity/principal-identity-record
      :principals [{:principal :gravity.compiler/p15-s23
                    :namespace :gravity.bootstrap.p15-s23.compiler
                    :package :gravity/bootstrap
                    :source-path source-path
                    :identity-status :verified}]
      :invalid-principals []
      :status :complete}
     :runtime-decision-log
     {:artifact :gravity/runtime-decision-log
      :decisions
      (mapv #(select-keys % [:action-id :principal :family :effect
                             :capability :provider :policy-source
                             :decision :redaction-status :audit-status
                             :handle-id])
            rows)
      :missing-required-audit []
      :status :complete}
     :delegated-handle-record
     {:artifact :gravity/delegated-handle-record
      :handles
      (mapv (fn [row]
              {:handle-id (:handle-id row)
               :principal (:principal row)
               :provider (:provider row)
               :allowed-effect (:effect row)
               :capability (:capability row)
               :scope (or (:delegate-scope row) [(:family row)])
               :typed? true
               :scoped? true
               :revocable? true
               :audit-required? true})
            grants)
      :unscoped-handles []
      :status :complete}
     :revocation-record
     {:artifact :gravity/revocation-record
      :records
      (mapv (fn [row]
              {:handle-id (:handle-id row)
               :principal (:principal row)
               :provider (:provider row)
               :decision :revoke
               :use-after-revocation? false
               :audit-status :recorded})
            revocations)
      :unsupported-revocations []
      :status :complete}
     :denial-diagnostic-record
     {:artifact :gravity/denial-diagnostic-record
      :denials
      (mapv (fn [row]
              {:diagnostic "R11-GRANT"
               :action-id (:action-id row)
               :principal (:principal row)
               :effect (:effect row)
               :capability (:capability row)
               :provider (:provider row)
               :policy-source (:policy-source row)
               :decision (:decision row)
               :redaction-status (:redaction-status row)
               :source-span (:source-span row)
               :remediation :attach_matching_runtime_grant_or_keep_denied})
            denials)
      :status :complete}
     :redaction-secret-handling-record
     {:artifact :gravity/redaction-secret-handling-record
      :policies [{:category :secret :redaction :secret-name-only}
                 {:category :prompt :redaction :prompt-digest}
                 {:category :command :redaction :command-digest}
                 {:category :artifact :redaction :artifact-id-only}]
      :secret-leaks []
      :records-redacted?
      (every? #(contains? % :redaction-status) rows)
      :status :complete}}))

(defn p15-s23-runtime-conformance-evidence
  [runtime-manifest service-table capability-manifest capability-table
   audit-records]
  {:artifact :gravity/p15-s23-runtime-capability-conformance-evidence
   :runtime-manifest-consumed?
   (contains? (set (:consumed-by runtime-manifest)) :self-hosting-gate)
   :runtime-family-selection-covered?
   (= :complete (get-in runtime-manifest [:selection-record :status]))
   :service-classification-covered?
   (and (= :complete (:status service-table))
        (empty? (:hidden-services service-table)))
   :capability-manifest-covered?
   (and (= :complete (:status capability-manifest))
        (true? (:deny-by-default? capability-manifest)))
   :deny-by-default-demonstrated?
   (and (true? (:deny-by-default? capability-table))
        (some #(= :deny (:decision %)) (:rows capability-table)))
   :grant-deny-delegate-revoke-covered?
   (= #{:grant :deny :delegate :revoke}
      (:decisions capability-table))
   :action-families-covered?
   (set/subset? p15-s23-runtime-action-families
                (:families-covered capability-table))
   :principal-identity-covered?
   (= :complete
      (get-in audit-records [:principal-identity-record :status]))
   :delegated-handles-scoped?
   (empty?
    (get-in audit-records [:delegated-handle-record :unscoped-handles]))
   :revocation-covered?
   (and (= :complete (get-in audit-records [:revocation-record :status]))
        (every? #(false? (:use-after-revocation? %))
                (get-in audit-records [:revocation-record :records])))
   :secret-redaction-covered?
   (and (= :complete
           (get-in audit-records
                   [:redaction-secret-handling-record :status]))
        (empty?
         (get-in audit-records
                 [:redaction-secret-handling-record :secret-leaks])))
   :audit-log-covered?
   (and (= :complete (get-in audit-records
                             [:runtime-decision-log :status]))
        (empty? (get-in audit-records
                        [:runtime-decision-log
                         :missing-required-audit])))
   :status :complete})

(defn p15-s23-runtime-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        runtime-manifest (:runtime-manifest candidate)
        service-table (:runtime-service-table candidate)
        capability-manifest (:runtime-capability-manifest candidate)
        capability-table (:capability-enforcement-table candidate)
        audit-records (:audit-records candidate)
        conformance (:capability-conformance-evidence candidate)
        core-artifact (:core-diagnostic-artifact candidate)
        pipeline (:compiler-pipeline-manifest-artifact candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-runtime-required-preserves preserves)]
    (vec
     (concat
      (when-not
       (= :gravity/runtime-manifest-and-capability-enforcement-report
          (:artifact proof-contract))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not
       (and (= :gravity/p15-s23-runtime-manifest
               (:artifact runtime-manifest))
            (= :complete (:status runtime-manifest))
            (= :managed (:family runtime-manifest))
            (= :meta (:profile runtime-manifest))
            (= :jvm (get-in runtime-manifest [:target :backend]))
            (true? (:capability-checks runtime-manifest))
            (contains? (set (:consumed-by runtime-manifest))
                       :self-hosting-gate)
            (empty? missing-preserves))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R002" runtime-manifest
          {:missing-preserves (vec (sort missing-preserves))})])
      (when-not
       (and (= :gravity/p15-s23-runtime-service-table
               (:artifact service-table))
            (= :complete (:status service-table))
            (= #{:linked :generated :delegated :external :forbidden}
               (:classification-kinds service-table))
            (seq (:linked service-table))
            (seq (:generated service-table))
            (seq (:delegated service-table))
            (contains? (:forbidden service-table) :ambient-network)
            (empty? (:hidden-services service-table)))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R003" service-table
          {:missing-fields [:runtime-service-classification]})])
      (when-not
       (and (= :gravity/runtime-capabilities
               (:artifact capability-manifest))
            (= :complete (:status capability-manifest))
            (true? (:deny-by-default? capability-manifest))
            (= #{:grant :deny :delegate :revoke}
               (:decisions capability-table))
            (set/subset? p15-s23-runtime-action-families
                         (:families-covered capability-table))
            (true? (:runtime-checks-do-not-grant-authority?
                    capability-table))
            (true? (:ambient-authority-rejected? capability-table)))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R004" capability-table
          {:required-families p15-s23-runtime-action-families
           :observed-families (:families-covered capability-table)})])
      (when-not
       (and (= :complete
               (get-in audit-records
                       [:principal-identity-record :status]))
            (empty? (get-in audit-records
                            [:principal-identity-record
                             :invalid-principals]))
            (= :complete
               (get-in audit-records [:runtime-decision-log :status]))
            (empty? (get-in audit-records
                            [:runtime-decision-log
                             :missing-required-audit]))
            (= :complete
               (get-in audit-records [:delegated-handle-record :status]))
            (empty? (get-in audit-records
                            [:delegated-handle-record
                             :unscoped-handles]))
            (= :complete
               (get-in audit-records [:revocation-record :status]))
            (every? #(false? (:use-after-revocation? %))
                    (get-in audit-records
                            [:revocation-record :records]))
            (= :complete
               (get-in audit-records
                       [:redaction-secret-handling-record :status]))
            (empty? (get-in audit-records
                            [:redaction-secret-handling-record
                             :secret-leaks]))
            (= :complete (:status conformance)))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R005" audit-records
          {:missing-fields [:principal-audit-delegation-revocation-redaction]})])
      (when-not
       (and (= :gravity/p15-s23-core-lowering-diagnostic-preservation-artifact
               (:kind core-artifact))
            (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
               (:kind pipeline))
            (= (:artifact-id core-artifact)
               (get-in runtime-manifest [:target :artifact])))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R006"
          {:core-artifact core-artifact
           :pipeline pipeline
           :runtime-target-artifact
           (get-in runtime-manifest [:target :artifact])}
          {:missing-fields [:artifact-links]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-runtime-diagnostic-record
          source-path "P15S23R007" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

