(defn p15-s23-runtime-rejected-records
  [source-path]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-runtime-proof-diagnostics source-path candidate)})
        p15-s23-runtime-rejected-candidates))

(defn p15-s23-runtime-diagnostic-stream
  [source-path proof-id]
  {:artifact
   :gravity/p15-s23-runtime-manifest-capability-diagnostic-stream
   :stage :p15-s23-runtime-manifest-capability-enforcement-report
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage
            :p15-s23-runtime-manifest-capability-enforcement-report
            :message (get p15-s23-runtime-diagnostic-messages id)})
         p15-s23-runtime-diagnostic-ids)
   :status :complete})

(defn p15-s23-runtime-manifest-capability-enforcement-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-runtime-manifest-capability-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-runtime-capability-fixtures
                      artifact)))
        conformance (:capability-conformance-evidence artifact)]
    {:runtime-capability-proof-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :core-diagnostic-proof-linked?
     (= :gravity/p15-s23-core-lowering-diagnostic-preservation-artifact
        (get-in artifact [:core-diagnostic-artifact :kind]))
     :compiler-pipeline-manifest-linked?
     (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
        (get-in artifact [:compiler-pipeline-manifest-artifact :kind]))
     :runtime-manifest-complete?
     (= :complete (get-in artifact [:runtime-manifest :status]))
     :runtime-family-selection-explicit?
     (= :complete
        (get-in artifact
                [:runtime-manifest :selection-record :status]))
     :runtime-services-classified?
     (and (= :complete (:status (:runtime-service-table artifact)))
          (empty? (get-in artifact [:runtime-service-table
                                    :hidden-services])))
     :capability-manifest-deny-by-default?
     (true? (get-in artifact
                    [:runtime-capability-manifest
                     :deny-by-default?]))
     :grant-deny-delegate-revoke-covered?
     (:grant-deny-delegate-revoke-covered? conformance)
     :authority-families-covered?
     (:action-families-covered? conformance)
     :runtime-checks-do-not-grant-authority?
     (true? (get-in artifact
                    [:capability-enforcement-table
                     :runtime-checks-do-not-grant-authority?]))
     :ambient-authority-rejected?
     (true? (get-in artifact
                    [:capability-enforcement-table
                     :ambient-authority-rejected?]))
     :principal-identity-covered?
     (:principal-identity-covered? conformance)
     :audit-log-covered? (:audit-log-covered? conformance)
     :delegated-handles-scoped?
     (:delegated-handles-scoped? conformance)
     :revocation-covered? (:revocation-covered? conformance)
     :secret-redaction-covered? (:secret-redaction-covered? conformance)
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-runtime-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-runtime-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :compiles-whole-claimed-subset? false
      :next-required-capability
      :implement_accepted_app_execution_proof}}))

(defn p15-s23-runtime-manifest-capability-enforcement-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-runtime-manifest-capability-enforcement-report)
        core-artifact
        (p15-s23-core-lowering-diagnostic-preservation-source-artifact
         source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
        runtime-manifest
        (p15-s23-runtime-manifest source-path (:artifact-id core-artifact))
        service-table (p15-s23-runtime-service-table runtime-manifest)
        capability-table
        (p15-s23-runtime-capability-table source-path
                                          (:artifact-id core-artifact))
        capability-manifest
        (p15-s23-runtime-capability-manifest capability-table)
        audit-records
        (p15-s23-runtime-identity-and-audit-records source-path
                                                    capability-table)
        conformance
        (p15-s23-runtime-conformance-evidence runtime-manifest
                                              service-table
                                              capability-manifest
                                              capability-table
                                              audit-records)
        candidate {:proof-contract proof-contract
                   :runtime-manifest runtime-manifest
                   :runtime-service-table service-table
                   :runtime-capability-manifest capability-manifest
                   :capability-enforcement-table capability-table
                   :audit-records audit-records
                   :capability-conformance-evidence conformance
                   :core-diagnostic-artifact core-artifact
                   :compiler-pipeline-manifest-artifact pipeline-artifact}
        diagnostics (p15-s23-runtime-proof-diagnostics source-path
                                                       candidate)
        _ (when (seq diagnostics)
            (p15-s23-runtime-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :core-artifact (:artifact-id core-artifact)
                       :pipeline-manifest (:artifact-id pipeline-artifact)
                       :runtime-manifest runtime-manifest
                       :capability-manifest capability-manifest
                       :capability-table
                       (:artifact capability-table)
                       :proof-contract proof-contract})))
        rejected-records (p15-s23-runtime-rejected-records source-path)
        artifact-base
        (merge
         {:kind
          :gravity/p15-s23-runtime-manifest-capability-enforcement-artifact
          :phase "15"
          :task "P15-S23"
          :stage
          :p15-s23-runtime-manifest-capability-enforcement-report
          :source-path source-path
          :proof-id proof-id
          :proof-contract proof-contract
          :core-diagnostic-artifact
          (select-keys core-artifact
                       [:kind :artifact-id :proof-id
                        :diagnostic-preservation-report
                        :capability-based-proof])
          :compiler-pipeline-manifest-artifact
          (select-keys pipeline-artifact
                       [:kind :artifact-id :manifest-id
                        :capability-based-proof])
          :runtime-manifest runtime-manifest
          :runtime-service-table service-table
          :runtime-capability-manifest capability-manifest
          :capability-enforcement-table capability-table
          :capability-conformance-evidence conformance
          :full-language-compiler-self-hosted?
          (get-in proof-contract
                  [:self-hosting-claims
                   :full-language-compiler-self-hosted?])
          :clojure-seed-retired?
          (get-in proof-contract
                  [:self-hosting-claims :clojure-seed-retired?])
          :accepted-p15-s23-runtime-capability-fixtures
          [{:fixture source-path
            :status :accepted
            :runtime-family (:family runtime-manifest)
            :runtime-consumers (:consumed-by runtime-manifest)
            :decision-count
            (count (:rows capability-table))
            :families-covered
            (count (:families-covered capability-table))}]
          :rejected-p15-s23-runtime-capability-fixtures
          rejected-records
          :p15-s23-runtime-manifest-capability-diagnostic-stream
          (p15-s23-runtime-diagnostic-stream source-path proof-id)
          :p15-s23-runtime-manifest-capability-results
          {:accepted-fixtures 1
           :rejected-fixtures (count rejected-records)
           :diagnostic-count (count p15-s23-runtime-diagnostic-ids)
           :decision-count (count (:rows capability-table))
           :authority-family-count
           (count (:families-covered capability-table))
           :status :in-progress}
          :diagnostics []}
         audit-records)
        proof
        (p15-s23-runtime-manifest-capability-enforcement-proof
         artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-runtime-manifest-capability-enforcement-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-runtime-fail!
     "P15S23R001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-runtime-manifest-capability-enforcement-source-artifact path))

(def p15-s23-accepted-app-source-path
  "bootstrap/clojure/fixtures/accepted/core-app.gravity")

(def p15-s23-accepted-app-expected-stdout
  "core-app\ngravity:19:2\n(:ok 19)\n")

(def p15-s23-accepted-app-required-preserves
  #{:source-spans :diagnostic-codes :artifact-provenance :effects
    :capabilities :runtime-capability-manifest
    :compiled-plan-execution-trace :accepted-app-output})

(def p15-s23-accepted-app-diagnostic-messages
  {"P15S23A001" "P15-S23 accepted app execution proof is missing"
   "P15S23A002" "P15-S23 accepted app fixture or compiled execution record is incomplete"
   "P15S23A003" "P15-S23 accepted app output does not match the reference run and expected stdout"
   "P15S23A004" "P15-S23 accepted app execution is not linked to the compiler/runtime evidence bundle"
   "P15S23A005" "P15-S23 accepted app trusted boundary is incomplete or hidden"
   "P15S23A006" "P15-S23 accepted app proof makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-accepted-app-diagnostic-ids
  ["P15S23A001" "P15S23A002" "P15S23A003"
   "P15S23A004" "P15S23A005" "P15S23A006"])

(defn p15-s23-accepted-app-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-accepted-app-diagnostic-messages
              id
              "P15-S23 accepted app execution proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-accepted-app-execution-proof
                 :diagnostic-family
                 :p15-s23-accepted-app-execution-proof
                 :value value
                 :remediation "Run a nontrivial accepted Gravity app through the current compiled-plan path, compare its output, link the result to P15-S23 compiler/runtime artifacts, expose the remaining Clojure runner boundary, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-accepted-app-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-accepted-app-execution-proof
   :source-span {:source source-path}
   :message (get p15-s23-accepted-app-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_accepted_app_execution_proof})

(defn p15-s23-accepted-app-output-comparison
  [accepted-app-artifact expected-stdout]
  (let [accepted-stdout (get-in accepted-app-artifact
                                [:accepted-run :stdout])
        reference-stdout (get-in accepted-app-artifact
                                 [:reference-run :stdout])
        accepted-matches-reference? (= accepted-stdout reference-stdout)
        accepted-matches-expected? (= accepted-stdout expected-stdout)]
    {:artifact :gravity/p15-s23-accepted-output-comparison
     :accepted-command (get-in accepted-app-artifact
                               [:accepted-run :command])
     :reference-command (get-in accepted-app-artifact
                                [:reference-run :command])
     :accepted-stdout accepted-stdout
     :reference-stdout reference-stdout
     :expected-stdout expected-stdout
     :accepted-matches-reference? accepted-matches-reference?
     :accepted-matches-expected? accepted-matches-expected?
     :status (if (and accepted-matches-reference?
                      accepted-matches-expected?)
               :complete
               :failed)}))

(defn p15-s23-compiled-plan-execution-trace
  [accepted-app-artifact]
  (let [plan (:compiled-plan accepted-app-artifact)
        proof (:capability-based-proof accepted-app-artifact)]
    {:artifact :gravity/p15-s23-compiled-plan-execution-trace
     :compiled-plan-id (:plan-id plan)
     :compiled-plan-kind (:kind plan)
     :entrypoint (:entrypoint plan)
     :instruction-summary (:instruction-summary plan)
     :effect-summary (:effect-summary plan)
     :accepted-stdout (get-in accepted-app-artifact
                              [:accepted-run :stdout])
     :reference-stdout (get-in accepted-app-artifact
                               [:reference-run :stdout])
     :compiled-plan-emitted? (:compiled-plan-emitted? proof)
     :compiled-plan-executed? (:compiled-plan-executed? proof)
     :source-form-interpreter-replaced?
     (:source-form-interpreter-replaced? proof)
     :status (if (and (= :gravity/stage0-hosted-core-compiled-plan
                         (:kind plan))
                      (true? (:compiled-plan-executed? proof)))
               :complete
               :failed)}))

(defn p15-s23-accepted-app-runtime-capability-use-record
  [accepted-app-artifact runtime-artifact]
  (let [effect-summary (get-in accepted-app-artifact
                               [:compiled-plan :effect-summary])
        declared-effects (get-in accepted-app-artifact
                                 [:module :effects])
        declared-capabilities (get-in accepted-app-artifact
                                      [:module :capabilities])]
    {:artifact :gravity/p15-s23-accepted-app-runtime-capability-use-record
     :application-effects declared-effects
     :application-capabilities declared-capabilities
     :compiled-effect-summary effect-summary
     :required-effects #{:io/write}
     :required-capabilities #{:io/stdout}
     :effect-capability-check-passed?
     (true? (get-in accepted-app-artifact
                    [:capability-based-proof
                     :effects-and-capabilities-checked?]))
     :runtime-enforcement-artifact-id (:artifact-id runtime-artifact)
     :runtime-capability-proof-id (:proof-id runtime-artifact)
     :runtime-capability-manifest
     (select-keys (:runtime-capability-manifest runtime-artifact)
                  [:artifact :deny-by-default? :handles :decisions
                   :status])
     :boundary
     :application_stdout_checked_by_stage0_runner_and_linked_to_p15_runtime_evidence
     :status :complete}))

(defn p15-s23-accepted-app-trusted-boundary-record
  [accepted-app-artifact]
  {:artifact :gravity/p15-s23-accepted-app-trusted-boundary
   :compiler (get-in accepted-app-artifact
                     [:trusted-boundary :compiler])
   :runtime (get-in accepted-app-artifact
                    [:trusted-boundary :runtime])
   :instruction-plan?
   (true? (get-in accepted-app-artifact
                  [:trusted-boundary :instruction-plan?]))
   :direct-form-interpreter? false
   :clojure-instruction-runner? true
   :self-hosted-compiler? false
   :clojure-seed-retired? false
   :seed-boundary :clojure-stage0-bootstrap
   :retirement-condition :complete-p15-s23-evidence-bundle
   :status :complete})

(defn p15-s23-accepted-app-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        accepted-app-artifact (:accepted-app-artifact candidate)
        output-comparison (:accepted-output-comparison candidate)
        execution-trace (:compiled-plan-execution-trace candidate)
        runtime-artifact (:runtime-capability-artifact candidate)
        trusted-boundary (:trusted-boundary-record candidate)
        runtime-use (:runtime-capability-use-record candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-accepted-app-required-preserves preserves)]
    (vec
     (concat
      (when-not (= :gravity/accepted-app-execution-proof
                   (:artifact proof-contract))
        [(p15-s23-accepted-app-diagnostic-record
          source-path "P15S23A001" proof-contract
          {:missing-fields [:artifact]})])
      (when-not
       (and (= :gravity/stage0-hosted-core-compiled-app-proof
               (:kind accepted-app-artifact))
            (= p15-s23-accepted-app-source-path
               (get-in accepted-app-artifact [:source :path]))
            (= 'core.app (get-in accepted-app-artifact
                                  [:module :module]))
            (= :hosted (get-in accepted-app-artifact
                                [:module :profile]))
            (= :jvm (get-in accepted-app-artifact
                             [:module :target]))
            (= #{:io/write} (get-in accepted-app-artifact
                                     [:module :effects]))
            (contains? (set (get-in accepted-app-artifact
                                     [:module :capabilities]))
                       :io/stdout)
            (= :gravity/stage0-hosted-core-compiled-plan
               (get-in accepted-app-artifact [:compiled-plan :kind]))
            (true? (get-in accepted-app-artifact
                           [:capability-based-proof
                            :compiled-plan-executed?]))
            (true? (get-in accepted-app-artifact
                           [:capability-based-proof
                            :function-instructions-covered?]))
            (empty? missing-preserves))
        [(p15-s23-accepted-app-diagnostic-record
          source-path "P15S23A002" accepted-app-artifact
          {:missing-preserves (vec (sort missing-preserves))
           :required-fixture p15-s23-accepted-app-source-path})])
      (when-not
       (and (= :gravity/p15-s23-accepted-output-comparison
               (:artifact output-comparison))
            (= :complete (:status output-comparison))
            (true? (:accepted-matches-reference? output-comparison))
            (true? (:accepted-matches-expected? output-comparison))
            (= (:accepted-stdout output-comparison)
               (:accepted-stdout execution-trace)))
        [(p15-s23-accepted-app-diagnostic-record
          source-path "P15S23A003" output-comparison
          {:expected-stdout p15-s23-accepted-app-expected-stdout})])
      (when-not
       (and (= :gravity/p15-s23-runtime-manifest-capability-enforcement-artifact
               (:kind runtime-artifact))
            (= :gravity/p15-s23-core-lowering-diagnostic-preservation-artifact
               (get-in runtime-artifact
                       [:core-diagnostic-artifact :kind]))
            (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
               (get-in runtime-artifact
                       [:compiler-pipeline-manifest-artifact :kind]))
            (re-find #"^sha256:" (str (:artifact-id runtime-artifact)))
            (re-find #"^sha256:" (str (get-in accepted-app-artifact
                                               [:compiled-plan
                                                :plan-id])))
            (= :complete (:status runtime-use))
            (true? (:effect-capability-check-passed? runtime-use)))
        [(p15-s23-accepted-app-diagnostic-record
          source-path "P15S23A004" runtime-artifact
          {:required-links [:runtime-capability-artifact
                            :compiler-pipeline-manifest-artifact
                            :core-diagnostic-artifact
                            :compiled-plan-id]})])
      (when-not
       (and (= :gravity/p15-s23-accepted-app-trusted-boundary
               (:artifact trusted-boundary))
            (= :clojure/jvm (:compiler trusted-boundary))
            (= :clojure/jvm (:runtime trusted-boundary))
            (true? (:instruction-plan? trusted-boundary))
            (false? (:direct-form-interpreter? trusted-boundary))
            (true? (:clojure-instruction-runner? trusted-boundary))
            (false? (:self-hosted-compiler? trusted-boundary))
            (false? (:clojure-seed-retired? trusted-boundary)))
        [(p15-s23-accepted-app-diagnostic-record
          source-path "P15S23A005" trusted-boundary
          {:required-boundary [:clojure-stage0-bootstrap
                               :clojure-instruction-runner
                               :self-hosted-compiler-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-accepted-app-diagnostic-record
          source-path "P15S23A006" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-accepted-app-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-accepted-app-execution-diagnostic-stream
   :stage :p15-s23-accepted-app-execution-proof
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-accepted-app-execution-proof
            :message (get p15-s23-accepted-app-diagnostic-messages id)})
         p15-s23-accepted-app-diagnostic-ids)
   :status :complete})

(defn p15-s23-accepted-app-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-accepted-app-missing-proof
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23A001"}
   {:fixture :internal-p15-s23-accepted-app-fixture-gap
    :candidate (assoc-in accepted-candidate
                         [:accepted-app-artifact :kind]
                         :gravity/wrong-accepted-app-artifact)
    :expected-diagnostic "P15S23A002"}
   {:fixture :internal-p15-s23-accepted-app-output-mismatch
    :candidate (-> accepted-candidate
                   (assoc-in [:accepted-output-comparison
                              :accepted-stdout]
                             "wrong\n")
                   (assoc-in [:accepted-output-comparison
                              :accepted-matches-reference?]
                             false)
                   (assoc-in [:accepted-output-comparison
                              :accepted-matches-expected?]
                             false)
                   (assoc-in [:accepted-output-comparison :status]
                             :failed))
    :expected-diagnostic "P15S23A003"}
   {:fixture :internal-p15-s23-accepted-app-artifact-link-gap
    :candidate (assoc accepted-candidate
                      :runtime-capability-artifact {:kind :wrong})
    :expected-diagnostic "P15S23A004"}
   {:fixture :internal-p15-s23-accepted-app-trusted-boundary-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:trusted-boundary-record
                              :clojure-instruction-runner?]
                             false)
                   (assoc-in [:trusted-boundary-record
                              :self-hosted-compiler?]
                             true))
    :expected-diagnostic "P15S23A005"}
   {:fixture :internal-p15-s23-accepted-app-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23A006"}])

(defn p15-s23-accepted-app-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-accepted-app-proof-diagnostics source-path candidate)})
        (p15-s23-accepted-app-rejected-candidates accepted-candidate)))

(defn p15-s23-accepted-app-execution-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-accepted-app-execution-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-app-execution-fixtures artifact)))
        output-comparison (:accepted-output-comparison artifact)
        execution-trace (:compiled-plan-execution-trace artifact)
        trusted-boundary (:trusted-boundary-record artifact)
        runtime-use (:runtime-capability-use-record artifact)]
    {:accepted-app-execution-proof-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :accepted-fixture-linked?
     (= p15-s23-accepted-app-source-path
        (get-in artifact [:accepted-app-artifact :source :path]))
     :compiled-plan-emitted?
     (true? (:compiled-plan-emitted? execution-trace))
     :compiled-plan-executed?
     (true? (:compiled-plan-executed? execution-trace))
     :accepted-output-matches-reference?
     (true? (:accepted-matches-reference? output-comparison))
     :accepted-output-matches-expected?
     (true? (:accepted-matches-expected? output-comparison))
     :runtime-capability-proof-linked?
     (= :gravity/p15-s23-runtime-manifest-capability-enforcement-artifact
        (get-in artifact [:runtime-capability-artifact :kind]))
     :effects-and-capabilities-recorded?
     (and (= #{:io/write} (:application-effects runtime-use))
          (contains? (:application-capabilities runtime-use) :io/stdout)
          (true? (:effect-capability-check-passed? runtime-use)))
     :trusted-boundaries-explicit?
     (and (true? (:clojure-instruction-runner? trusted-boundary))
          (false? (:self-hosted-compiler? trusted-boundary))
          (false? (:clojure-seed-retired? trusted-boundary)))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-accepted-app-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-accepted-app-diagnostic-ids) diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :clojure-stage0-compiler? true
      :clojure-instruction-runner? true
      :full-self-hosted-toolchain? false
      :next-required-capability
      :implement_rejected_app_diagnostic_proof}}))

(defn p15-s23-accepted-app-execution-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-accepted-app-execution-proof)
        expected-stdout
        (or (get-in proof-contract [:accepted-fixture :expected-stdout])
            p15-s23-accepted-app-expected-stdout)
        compiled-app-fn
        (resolve 'gravity.bootstrap/hosted-core-compiled-app-proof-file-artifact)
        _ (when-not compiled-app-fn
            (p15-s23-accepted-app-fail!
             "P15S23A002" source-path nil
             {:missing-fields [:hosted-core-compiled-app-proof-file-artifact]}))
        accepted-app-artifact
        (compiled-app-fn p15-s23-accepted-app-source-path)
        runtime-artifact
        (p15-s23-runtime-manifest-capability-enforcement-source-artifact
         source-path)
        output-comparison
        (p15-s23-accepted-app-output-comparison accepted-app-artifact
                                                expected-stdout)
        execution-trace
        (p15-s23-compiled-plan-execution-trace accepted-app-artifact)
        runtime-use
        (p15-s23-accepted-app-runtime-capability-use-record
         accepted-app-artifact
         runtime-artifact)
        trusted-boundary
        (p15-s23-accepted-app-trusted-boundary-record accepted-app-artifact)
        candidate {:proof-contract proof-contract
                   :accepted-app-artifact accepted-app-artifact
                   :accepted-output-comparison output-comparison
                   :compiled-plan-execution-trace execution-trace
                   :runtime-capability-artifact runtime-artifact
                   :runtime-capability-use-record runtime-use
                   :trusted-boundary-record trusted-boundary}
        diagnostics
        (p15-s23-accepted-app-proof-diagnostics source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-accepted-app-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :accepted-app-artifact
                       (:artifact-id accepted-app-artifact)
                       :compiled-plan-id
                       (get-in accepted-app-artifact
                               [:compiled-plan :plan-id])
                       :runtime-artifact (:artifact-id runtime-artifact)
                       :expected-stdout expected-stdout
                       :proof-contract proof-contract})))
        rejected-records
        (p15-s23-accepted-app-rejected-records source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-accepted-app-execution-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-accepted-app-execution-proof
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :accepted-app-path p15-s23-accepted-app-source-path
         :accepted-app-artifact
         (select-keys accepted-app-artifact
                      [:kind :artifact-id :phase :task :source :module
                       :compiled-plan :runtime-surface :accepted-run
                       :reference-run :trusted-boundary
                       :capability-based-proof])
         :runtime-capability-artifact
         (select-keys runtime-artifact
                      [:kind :artifact-id :proof-id
                       :runtime-manifest
                       :runtime-capability-manifest
                       :capability-enforcement-table
                       :core-diagnostic-artifact
                       :compiler-pipeline-manifest-artifact
                       :capability-based-proof])
         :compiled-plan-execution-trace execution-trace
         :accepted-output-comparison output-comparison
         :runtime-capability-use-record runtime-use
         :trusted-boundary-record trusted-boundary
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-app-execution-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :profile (get-in accepted-app-artifact [:module :profile])
           :target (get-in accepted-app-artifact [:module :target])
           :effects (get-in accepted-app-artifact [:module :effects])
           :capabilities (get-in accepted-app-artifact
                                 [:module :capabilities])
           :user-functions
           (get-in accepted-app-artifact
                   [:runtime-surface :user-functions])
           :compiled-plan-id
           (get-in accepted-app-artifact [:compiled-plan :plan-id])
           :stdout (get-in output-comparison [:accepted-stdout])}]
         :rejected-p15-s23-app-execution-fixtures rejected-records
         :p15-s23-accepted-app-execution-diagnostic-stream
         (p15-s23-accepted-app-diagnostic-stream source-path proof-id)
         :p15-s23-accepted-app-execution-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count (count p15-s23-accepted-app-diagnostic-ids)
          :stdout (get-in output-comparison [:accepted-stdout])
          :compiled-plan-id
          (get-in accepted-app-artifact [:compiled-plan :plan-id])
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-accepted-app-execution-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-accepted-app-execution-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-accepted-app-fail!
     "P15S23A001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-accepted-app-execution-source-artifact path))

