(def p15-s23-whole-language-compiler-diagnostic-messages
  {"P15S23W001" "P15-S23 whole-language compiler artifact contract is missing"
   "P15S23W002" "P15-S23 whole-language compiler artifact is missing source, pipeline, or evidence links"
   "P15S23W003" "P15-S23 whole-language compiler artifact does not compile and run the claimed application subset"
   "P15S23W004" "P15-S23 whole-language compiler artifact is missing reproducibility, equivalence, conformance, or provenance linkage"
   "P15S23W005" "P15-S23 whole-language compiler artifact has an unsupported self-hosting, seed-retirement, or trusted-boundary claim"
   "P15S23W006" "P15-S23 whole-language compiler artifact does not preserve rejected diagnostic coverage"})

(def p15-s23-whole-language-compiler-diagnostic-ids
  ["P15S23W001" "P15S23W002" "P15S23W003"
   "P15S23W004" "P15S23W005" "P15S23W006"])

(defn p15-s23-whole-language-compiler-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-whole-language-compiler-diagnostic-messages
              id
              "P15-S23 whole-language compiler artifact failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-whole-language-compiler-artifact
                 :diagnostic-family
                 :p15-s23-whole-language-compiler-artifact
                 :value value
                 :remediation "Emit a current-stage compiler artifact with source, pipeline, accepted execution, rejected diagnostics, rebuild, comparison, conformance, provenance, TCB, and unsafe-audit links. Keep Clojure seed retirement false until the full release evidence bundle exists."}
                data)))

(defn p15-s23-whole-language-compiler-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-whole-language-compiler-artifact
   :source-span {:source source-path}
   :message (get p15-s23-whole-language-compiler-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_p15_s23_whole_language_compiler_artifact})

(defn p15-s23-whole-language-compiler-stage-support-matrix
  [source-path proof-contract inventory-artifact pipeline-artifact
   source-syntax-artifact core-artifact runtime-artifact]
  {:artifact :gravity/p15-s23-whole-language-compiler-stage-support-matrix
   :source-path source-path
   :support-level :current-stage-compiler-artifact
   :claimed-subset :current-implementation-language-subset
   :source-components
   (mapv :component (:source-inventory inventory-artifact))
   :canonical-pipeline
   (get-in pipeline-artifact [:compiler-pipeline-manifest :pipeline])
   :canonical-stage-count
   (count (get-in pipeline-artifact [:compiler-pipeline-manifest :pipeline]))
   :syntax-object-count
   (get-in source-syntax-artifact
           [:p15-s23-source-syntax-serialization-results
            :syntax-object-count])
   :core-node-count
   (get-in core-artifact
           [:p15-s23-core-diagnostic-preservation-results
            :core-node-count])
   :runtime-family (get-in runtime-artifact [:runtime-manifest :family])
   :stage0-executor-boundary
   (get-in proof-contract
           [:claimed-language-subset :stage0-executor-boundary])
   :unsupported-claims
   {:full-language-compiler-self-hosted? false
    :clojure-seed-retired? false
    :release-eligible? false}
   :status
   (if (and (= :gravity/p15-s23-compiler-source-inventory-artifact
               (:kind inventory-artifact))
            (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
               (:kind pipeline-artifact))
            (= p15-s23-canonical-compiler-pipeline
               (get-in pipeline-artifact
                       [:compiler-pipeline-manifest :pipeline]))
            (pos? (or (get-in source-syntax-artifact
                               [:p15-s23-source-syntax-serialization-results
                                :syntax-object-count])
                      0))
            (pos? (or (get-in core-artifact
                               [:p15-s23-core-diagnostic-preservation-results
                                :core-node-count])
                      0)))
     :complete
     :failed)})

(defn p15-s23-whole-language-compiler-evidence-link-table
  [inventory-artifact pipeline-artifact source-syntax-artifact core-artifact
   runtime-artifact accepted-artifact rejected-artifact rebuild-artifact
   stage-comparison-artifact conformance-artifact provenance-artifact
   tcb-artifact unsafe-artifact]
  (let [links
        [{:link :compiler-source-inventory
          :artifact-id (:artifact-id inventory-artifact)
          :inventory-id (:inventory-id inventory-artifact)
          :status :verified}
         {:link :compiler-pipeline-manifest
          :artifact-id (:artifact-id pipeline-artifact)
          :manifest-id (:manifest-id pipeline-artifact)
          :status :verified}
         {:link :source-unit-and-syntax-serialization-proof
          :artifact-id (:artifact-id source-syntax-artifact)
          :proof-id (:proof-id source-syntax-artifact)
          :status :verified}
         {:link :core-lowering-and-diagnostic-preservation-report
          :artifact-id (:artifact-id core-artifact)
          :proof-id (:proof-id core-artifact)
          :status :verified}
         {:link :runtime-manifest-and-capability-enforcement-report
          :artifact-id (:artifact-id runtime-artifact)
          :proof-id (:proof-id runtime-artifact)
          :status :verified}
         {:link :accepted-app-execution-proof
          :artifact-id (:artifact-id accepted-artifact)
          :proof-id (:proof-id accepted-artifact)
          :status :verified}
         {:link :rejected-app-diagnostic-proof
          :artifact-id (:artifact-id rejected-artifact)
          :proof-id (:proof-id rejected-artifact)
          :status :verified}
         {:link :reproducible-rebuild-log
          :artifact-id (:artifact-id rebuild-artifact)
          :proof-id (:proof-id rebuild-artifact)
          :status :verified}
         {:link :stage-comparison-report
          :artifact-id (:artifact-id stage-comparison-artifact)
          :proof-id (:proof-id stage-comparison-artifact)
          :status :verified}
         {:link :self-hosting-conformance-report
          :artifact-id (:artifact-id conformance-artifact)
          :proof-id (:proof-id conformance-artifact)
          :status :verified}
         {:link :bootstrap-provenance-attestation
          :artifact-id (:artifact-id provenance-artifact)
          :proof-id (:proof-id provenance-artifact)
          :status :verified}
         {:link :trusted-computing-base-delta-record
          :artifact-id (:artifact-id tcb-artifact)
          :proof-id (:proof-id tcb-artifact)
          :status :verified}
         {:link :unsafe-audit-report
          :artifact-id (:artifact-id unsafe-artifact)
          :proof-id (:proof-id unsafe-artifact)
          :status :verified}]
        covered (set (map :link links))]
    {:artifact :gravity/p15-s23-whole-language-compiler-evidence-link-table
     :links links
     :required-links
     (vec (sort p15-s23-whole-language-compiler-required-links))
     :required-links-covered?
     (= p15-s23-whole-language-compiler-required-links covered)
     :status
     (if (= p15-s23-whole-language-compiler-required-links covered)
       :complete
       :failed)}))

(defn p15-s23-whole-language-compiler-accepted-record
  [accepted-artifact hosted-compiler-artifact]
  {:artifact :gravity/p15-s23-whole-language-compiler-accepted-application-compile-record
   :fixture p15-s23-accepted-app-source-path
   :hosted-compiler-artifact-id (:artifact-id hosted-compiler-artifact)
   :p15-s23-accepted-artifact-id (:artifact-id accepted-artifact)
   :compiled-plan-id
   (get-in accepted-artifact
           [:accepted-app-artifact :compiled-plan :plan-id])
   :compiler-report-id
   (get-in hosted-compiler-artifact [:compiler-report :report-id])
   :stdout
   (get-in accepted-artifact [:accepted-output-comparison
                              :accepted-stdout])
   :reference-stdout
   (get-in accepted-artifact [:accepted-output-comparison
                              :reference-stdout])
   :output-matches?
   (true?
    (get-in accepted-artifact [:accepted-output-comparison
                               :accepted-matches-reference?]))
   :compiled-plan-emitted?
   (true?
    (get-in accepted-artifact [:compiled-plan-execution-trace
                               :compiled-plan-emitted?]))
   :compiled-plan-executed?
   (true?
    (get-in accepted-artifact [:compiled-plan-execution-trace
                               :compiled-plan-executed?]))
   :status
   (if (and (true?
             (get-in accepted-artifact [:accepted-output-comparison
                                        :accepted-matches-reference?]))
            (true?
             (get-in accepted-artifact [:compiled-plan-execution-trace
                                        :compiled-plan-emitted?]))
            (true?
             (get-in accepted-artifact [:compiled-plan-execution-trace
                                        :compiled-plan-executed?]))
            (= :gravity/stage0-hosted-core-compiled-compiler-proof
               (:kind hosted-compiler-artifact)))
     :complete
     :failed)})

(defn p15-s23-whole-language-compiler-rejected-record
  [rejected-artifact]
  (let [records (:rejected-app-diagnostic-records rejected-artifact)
        diagnostics (mapv :diagnostic records)
        expected (mapv :expected-diagnostic records)]
    {:artifact :gravity/p15-s23-whole-language-compiler-rejected-application-diagnostic-record
     :fixtures (mapv :fixture records)
     :diagnostics diagnostics
     :expected-diagnostics expected
     :all-fixtures-rejected?
     (every? #(= :rejected (:status %)) records)
     :diagnostics-match-expected?
     (every? true? (map :matches-expected? records))
     :diagnostic-codes-stable? (= (set diagnostics) (set expected))
     :status
     (if (and (seq records)
              (every? #(= :rejected (:status %)) records)
              (every? true? (map :matches-expected? records))
              (= (set diagnostics) (set expected)))
       :complete
       :failed)}))

(defn p15-s23-whole-language-compiler-residual-boundary-record
  [accepted-artifact tcb-artifact]
  (let [accepted-boundary (:trusted-boundary-record accepted-artifact)
        tcb-boundaries
        (get-in tcb-artifact
                [:residual-trust-boundary-record :residual-boundaries])]
    {:artifact :gravity/p15-s23-whole-language-compiler-residual-trusted-boundary-record
     :compiler (:compiler accepted-boundary)
     :runtime (:runtime accepted-boundary)
     :instruction-plan? (:instruction-plan? accepted-boundary)
     :clojure-instruction-runner?
     (:clojure-instruction-runner? accepted-boundary)
     :clojure-stage0-still-required? true
     :self-hosted-compiler? false
     :clojure-seed-retired? false
     :residual-tcb-boundaries tcb-boundaries
     :retirement-condition :complete-governance-release-and-seed-retirement
     :status
     (if (and (true? (:clojure-instruction-runner?
                     accepted-boundary))
              (false? (:self-hosted-compiler? accepted-boundary))
              (false? (:clojure-seed-retired? accepted-boundary))
              (contains? (set tcb-boundaries) :clojure-stage0-bootstrap))
       :complete
       :failed)}))

(defn p15-s23-whole-language-compiler-lineage-record
  [source-path inventory-artifact provenance-artifact stage-comparison-artifact]
  {:artifact :gravity/p15-s23-whole-language-compiler-lineage-record
   :source-path source-path
   :compiler-artifact-source :gravity-source
   :compiled-by :clojure-stage0
   :verified-by :clojure-stage0
   :source-inventory-id (:inventory-id inventory-artifact)
   :bootstrap-provenance-record-id
   (get-in provenance-artifact [:bootstrap-provenance-record
                                :provenance-record-id])
   :stage-comparison-proof-id (:proof-id stage-comparison-artifact)
   :lineage-traversable-to-seed?
   (get-in provenance-artifact [:compiler-lineage-graph
                                :lineage-traversable-to-seed?])
   :status
   (if (and (re-find #"^sha256:" (str (:inventory-id inventory-artifact)))
            (true?
             (get-in provenance-artifact [:compiler-lineage-graph
                                          :lineage-traversable-to-seed?]))
            (true?
             (get-in stage-comparison-artifact
                     [:capability-based-proof
                      :current-candidate-equivalent-to-seed?])))
     :complete
     :failed)})

(defn p15-s23-whole-language-compiler-auditor-query-record
  [manifest stage-support accepted-record rejected-record boundary-record
   lineage-record link-table]
  {:artifact :gravity/p15-s23-whole-language-compiler-auditor-query-record
   :queries
   [{:query :which_artifact_is_the_current_compiler
     :answer (:compiler-artifact-id manifest)
     :status :answered}
    {:query :which_language_subset_is_claimed
     :answer (:claimed-subset stage-support)
     :status :answered}
    {:query :did_the_accepted_application_run
     :answer (:output-matches? accepted-record)
     :status :answered}
    {:query :did_rejected_applications_fail_closed
     :answer (:diagnostic-codes-stable? rejected-record)
     :status :answered}
    {:query :which_seed_boundary_remains
     :answer (:residual-tcb-boundaries boundary-record)
     :status :answered}
    {:query :which_compiler_compiled_this_compiler
     :answer (:compiled-by lineage-record)
     :status :answered}
    {:query :which_evidence_links_support_this_artifact
     :answer (mapv :link (:links link-table))
     :status :answered}]
   :compiler-artifact-identifiable?
   (boolean (re-find #"^sha256:"
                     (str (:compiler-artifact-id manifest))))
   :accepted-application-proven? (:output-matches? accepted-record)
   :rejected-diagnostics-proven? (:diagnostic-codes-stable? rejected-record)
   :residual-boundary-explicit? (= :complete (:status boundary-record))
   :lineage-traversable? (:lineage-traversable-to-seed? lineage-record)
   :required-links-covered? (:required-links-covered? link-table)
   :status :complete})

(defn p15-s23-whole-language-compiler-manifest
  [source-path proof-contract inventory-artifact pipeline-artifact
   stage-support accepted-record rejected-record boundary-record
   lineage-record link-table]
  (let [manifest-base
        {:artifact :gravity/p15-s23-whole-language-compiler-artifact-manifest
         :source-path source-path
         :bootstrap-stage :p15-s23
         :compiler-source-language :gravity
         :compiler-source-inventory-id (:inventory-id inventory-artifact)
         :pipeline-manifest-id (:manifest-id pipeline-artifact)
         :stage-support-id (c4-artifact-id stage-support)
         :accepted-application-compile-record-id
         (c4-artifact-id accepted-record)
         :rejected-application-diagnostic-record-id
         (c4-artifact-id rejected-record)
         :residual-trusted-boundary-record-id
         (c4-artifact-id boundary-record)
         :compiler-lineage-record-id (c4-artifact-id lineage-record)
         :evidence-link-table-id (c4-artifact-id link-table)
         :claimed-subset
         (get-in proof-contract [:claimed-language-subset :scope])
         :canonical-stage-count (:canonical-stage-count stage-support)
         :accepted-app-output (:stdout accepted-record)
         :rejected-diagnostics (:diagnostics rejected-record)
         :required-links-covered?
         (:required-links-covered? link-table)
         :full-language-compiler-self-hosted? false
         :clojure-seed-retired? false
         :release-eligible? false
         :status :complete}
        compiler-artifact-id (c4-artifact-id manifest-base)]
    (assoc manifest-base :compiler-artifact-id compiler-artifact-id)))

(defn p15-s23-whole-language-compiler-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        stage-support (:stage-support-matrix candidate)
        manifest (:compiler-artifact-manifest candidate)
        link-table (:compiler-evidence-link-table candidate)
        accepted-record (:accepted-application-compile-record candidate)
        rejected-record (:rejected-application-diagnostic-record candidate)
        boundary-record (:residual-trusted-boundary-record candidate)
        lineage-record (:compiler-artifact-lineage-record candidate)
        rebuild-artifact (:reproducible-rebuild-log-artifact candidate)
        stage-comparison-artifact (:stage-comparison-report-artifact candidate)
        conformance-artifact (:self-hosting-conformance-report-artifact candidate)
        provenance-artifact (:bootstrap-provenance-attestation-artifact candidate)
        claims (:self-hosting-claims proof-contract)
        preserves (set (:preserves proof-contract))
        missing-preserves
        (set/difference p15-s23-whole-language-compiler-required-preserves
                        preserves)]
    (vec
     (concat
      (when-not (= :gravity/whole-language-compiler-artifact
                   (:artifact proof-contract))
        [(p15-s23-whole-language-compiler-diagnostic-record
          source-path "P15S23W001" proof-contract
          {:missing-fields [:artifact]})])
      (when (or (seq missing-preserves)
                (not= :complete (:status link-table))
                (not (:required-links-covered? link-table))
                (not= :complete (:status manifest)))
        [(p15-s23-whole-language-compiler-diagnostic-record
          source-path "P15S23W002"
          {:manifest manifest :link-table link-table}
          {:missing-preserves (vec (sort missing-preserves))
           :required-links
           (vec (sort p15-s23-whole-language-compiler-required-links))})])
      (when-not
       (and (= :complete (:status stage-support))
            (= :complete (:status accepted-record))
            (true? (:output-matches? accepted-record))
            (true? (:compiled-plan-emitted? accepted-record))
            (true? (:compiled-plan-executed? accepted-record)))
        [(p15-s23-whole-language-compiler-diagnostic-record
          source-path "P15S23W003"
          {:stage-support stage-support
           :accepted-application-compile-record accepted-record}
          {:required [:complete-stage-support
                      :compiled-plan-emitted
                      :compiled-plan-executed
                      :accepted-output-matches-reference]})])
      (when-not
       (and (= :complete (:status lineage-record))
            (true?
             (get-in rebuild-artifact
                     [:artifact-identity-comparison
                      :all-artifact-identities-match?]))
            (true?
             (get-in stage-comparison-artifact
                     [:capability-based-proof
                      :current-candidate-equivalent-to-seed?]))
            (true?
             (get-in conformance-artifact
                     [:stage-support-conformance-record
                      :stage-support-conformant?]))
            (true?
             (get-in provenance-artifact
                     [:compiler-lineage-graph
                      :lineage-traversable-to-seed?])))
        [(p15-s23-whole-language-compiler-diagnostic-record
          source-path "P15S23W004"
          {:lineage-record lineage-record
           :rebuild-artifact (:artifact-id rebuild-artifact)
           :stage-comparison-artifact (:artifact-id stage-comparison-artifact)
           :conformance-artifact (:artifact-id conformance-artifact)
           :provenance-artifact (:artifact-id provenance-artifact)}
          {:required [:reproducible-artifact-identities
                      :stage-equivalence
                      :stage-support-conformance
                      :lineage-traversable-to-seed]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims))
                (true? (:full-language-compiler-self-hosted? manifest))
                (true? (:clojure-seed-retired? manifest))
                (not= :complete (:status boundary-record))
                (false? (:clojure-stage0-still-required?
                         boundary-record)))
        [(p15-s23-whole-language-compiler-diagnostic-record
          source-path "P15S23W005"
          {:claims claims
           :manifest manifest
           :boundary-record boundary-record}
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)
           :residual-boundary-status (:status boundary-record)})])
      (when-not
       (and (= :complete (:status rejected-record))
            (true? (:all-fixtures-rejected? rejected-record))
            (true? (:diagnostics-match-expected? rejected-record))
            (true? (:diagnostic-codes-stable? rejected-record)))
        [(p15-s23-whole-language-compiler-diagnostic-record
          source-path "P15S23W006" rejected-record
          {:required [:all-rejected-fixtures-fail-closed
                      :diagnostics-match-expected
                      :diagnostic-codes-stable]})])))))

(defn p15-s23-whole-language-compiler-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-whole-language-compiler-diagnostic-stream
   :stage :p15-s23-whole-language-compiler-artifact
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-whole-language-compiler-artifact
            :message
            (get p15-s23-whole-language-compiler-diagnostic-messages id)})
         p15-s23-whole-language-compiler-diagnostic-ids)
   :status :complete})

(defn p15-s23-whole-language-compiler-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-whole-language-compiler-missing-artifact
    :candidate (assoc accepted-candidate :proof-contract {})
    :expected-diagnostic "P15S23W001"}
   {:fixture :internal-p15-s23-whole-language-compiler-evidence-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:compiler-evidence-link-table
                              :required-links-covered?]
                             false)
