    :expected-diagnostic "P15S23W005"}
   {:fixture :internal-p15-s23-whole-language-compiler-diagnostic-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:rejected-application-diagnostic-record
                              :diagnostics-match-expected?]
                             false)
                   (assoc-in [:rejected-application-diagnostic-record
                              :diagnostic-codes-stable?]
                             false)
                   (assoc-in [:rejected-application-diagnostic-record
                              :status]
                             :failed))
    :expected-diagnostic "P15S23W006"}])

(defn p15-s23-whole-language-compiler-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-whole-language-compiler-proof-diagnostics
            source-path candidate)})
        (p15-s23-whole-language-compiler-rejected-candidates
         accepted-candidate)))

(defn p15-s23-whole-language-compiler-artifact-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-whole-language-compiler-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-whole-language-compiler-fixtures
                      artifact)))]
    {:whole-language-compiler-artifact-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :compiler-artifact-emitted?
     (boolean
      (re-find #"^sha256:"
               (str (get-in artifact [:compiler-artifact-manifest
                                      :compiler-artifact-id]))))
     :current-claimed-subset-compiled?
     (= :complete (get-in artifact
                          [:accepted-application-compile-record
                           :status]))
     :accepted-application-ran?
     (true? (get-in artifact
                    [:accepted-application-compile-record
                     :output-matches?]))
     :rejected-applications-fail-closed?
     (true? (get-in artifact
                    [:rejected-application-diagnostic-record
                     :diagnostic-codes-stable?]))
     :evidence-links-covered?
     (true? (get-in artifact
                    [:compiler-evidence-link-table
                     :required-links-covered?]))
     :reproducible-rebuild-linked?
     (true? (get-in artifact
                    [:reproducible-rebuild-log-artifact
                     :artifact-identity-comparison
                     :all-artifact-identities-match?]))
     :stage-comparison-linked?
     (true? (get-in artifact
                    [:stage-comparison-report-artifact
                     :capability-based-proof
                     :current-candidate-equivalent-to-seed?]))
     :conformance-linked?
     (true? (get-in artifact
                    [:self-hosting-conformance-report-artifact
                     :stage-support-conformance-record
                     :stage-support-conformant?]))
     :provenance-linked?
     (true? (get-in artifact
                    [:compiler-artifact-lineage-record
                     :lineage-traversable-to-seed?]))
     :tcb-and-unsafe-linked?
     (and (= :gravity/p15-s23-tcb-delta-record-artifact
             (get-in artifact [:tcb-delta-record-artifact :kind]))
          (= :gravity/p15-s23-unsafe-audit-report-artifact
             (get-in artifact [:unsafe-audit-report-artifact :kind])))
     :residual-clojure-boundary-recorded?
     (true? (get-in artifact
                    [:residual-trusted-boundary-record
                     :clojure-stage0-still-required?]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (set/subset? (set p15-s23-whole-language-compiler-diagnostic-ids)
                  rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-whole-language-compiler-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :current-stage-compiler-artifact? true
      :residual-clojure-stage0-boundary? true
      :release-eligible? false
      :next-required-capability
      :complete_governance_and_package_release_record}}))

(defn p15-s23-whole-language-compiler-artifact-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-whole-language-compiler-artifact)
        inventory-artifact
        (p15-s23-compiler-source-inventory-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact source-path)
        source-syntax-artifact
        (p15-s23-source-syntax-serialization-proof-source-artifact source-path)
        core-artifact
        (p15-s23-core-lowering-diagnostic-preservation-source-artifact
         source-path)
        runtime-artifact
        (p15-s23-runtime-manifest-capability-enforcement-source-artifact
         source-path)
        accepted-artifact
        (p15-s23-accepted-app-execution-source-artifact source-path)
        rejected-artifact
        (p15-s23-rejected-app-diagnostic-source-artifact source-path)
        rebuild-artifact
        (p15-s23-reproducible-rebuild-log-source-artifact source-path)
        stage-comparison-artifact
        (p15-s23-stage-comparison-report-source-artifact source-path)
        conformance-artifact
        (p15-s23-self-hosting-conformance-report-source-artifact source-path)
        provenance-artifact
        (p15-s23-provenance-attestation-source-artifact source-path)
        tcb-artifact
        (p15-s23-tcb-delta-record-source-artifact source-path)
        unsafe-artifact
        (p15-s23-unsafe-audit-report-source-artifact source-path)
        hosted-compiler-fn
        (resolve 'gravity.bootstrap/hosted-core-compiled-compiler-proof-file-artifact)
        _ (when-not hosted-compiler-fn
            (p15-s23-whole-language-compiler-fail!
             "P15S23W003" source-path nil
             {:missing-fields
              [:hosted-core-compiled-compiler-proof-file-artifact]}))
        hosted-compiler-artifact
        (hosted-compiler-fn p15-s23-accepted-app-source-path)
        stage-support
        (p15-s23-whole-language-compiler-stage-support-matrix
         source-path proof-contract inventory-artifact pipeline-artifact
         source-syntax-artifact core-artifact runtime-artifact)
        link-table
        (p15-s23-whole-language-compiler-evidence-link-table
         inventory-artifact pipeline-artifact source-syntax-artifact
         core-artifact runtime-artifact accepted-artifact rejected-artifact
         rebuild-artifact stage-comparison-artifact conformance-artifact
         provenance-artifact tcb-artifact unsafe-artifact)
        accepted-record
        (p15-s23-whole-language-compiler-accepted-record
         accepted-artifact hosted-compiler-artifact)
        rejected-record
        (p15-s23-whole-language-compiler-rejected-record rejected-artifact)
        boundary-record
        (p15-s23-whole-language-compiler-residual-boundary-record
         accepted-artifact tcb-artifact)
        lineage-record
        (p15-s23-whole-language-compiler-lineage-record
         source-path inventory-artifact provenance-artifact
         stage-comparison-artifact)
        manifest
        (p15-s23-whole-language-compiler-manifest
         source-path proof-contract inventory-artifact pipeline-artifact
         stage-support accepted-record rejected-record boundary-record
         lineage-record link-table)
        auditor-query
        (p15-s23-whole-language-compiler-auditor-query-record
         manifest stage-support accepted-record rejected-record
         boundary-record lineage-record link-table)
        candidate {:proof-contract proof-contract
                   :stage-support-matrix stage-support
                   :compiler-artifact-manifest manifest
                   :compiler-evidence-link-table link-table
                   :accepted-application-compile-record accepted-record
                   :rejected-application-diagnostic-record rejected-record
                   :residual-trusted-boundary-record boundary-record
                   :compiler-artifact-lineage-record lineage-record
                   :reproducible-rebuild-log-artifact rebuild-artifact
                   :stage-comparison-report-artifact stage-comparison-artifact
                   :self-hosting-conformance-report-artifact
                   conformance-artifact
                   :bootstrap-provenance-attestation-artifact
                   provenance-artifact}
        diagnostics
        (p15-s23-whole-language-compiler-proof-diagnostics
         source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-whole-language-compiler-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :compiler-artifact-id
                       (:compiler-artifact-id manifest)
                       :stage-support stage-support
                       :accepted-record accepted-record
                       :rejected-record rejected-record
                       :lineage-record lineage-record
                       :link-table link-table})))
        rejected-records
        (p15-s23-whole-language-compiler-rejected-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-whole-language-compiler-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-whole-language-compiler-artifact
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :compiler-source-inventory-artifact
         (select-keys inventory-artifact
                      [:kind :artifact-id :inventory-id
                       :source-inventory :capability-based-proof])
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :manifest-id
                       :compiler-pipeline-manifest
                       :capability-based-proof])
         :source-syntax-serialization-artifact
         (select-keys source-syntax-artifact
                      [:kind :artifact-id :proof-id
                       :source-unit-record
                       :syntax-serialization-roundtrip
                       :capability-based-proof])
         :core-lowering-diagnostic-artifact
         (select-keys core-artifact
                      [:kind :artifact-id :proof-id
                       :core-module-record
                       :diagnostic-preservation-record
                       :capability-based-proof])
         :runtime-manifest-capability-artifact
         (select-keys runtime-artifact
                      [:kind :artifact-id :proof-id
                       :runtime-manifest
                       :runtime-capability-manifest
                       :capability-based-proof])
         :accepted-app-execution-artifact
         (select-keys accepted-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-output-comparison
                       :compiled-plan-execution-trace
                       :trusted-boundary-record
                       :capability-based-proof])
         :rejected-app-diagnostic-artifact
         (select-keys rejected-artifact
                      [:kind :artifact-id :proof-id
                       :rejected-app-diagnostic-records
                       :diagnostic-preservation-record
                       :capability-based-proof])
         :reproducible-rebuild-log-artifact
         (select-keys rebuild-artifact
                      [:kind :artifact-id :proof-id
                       :artifact-identity-comparison
                       :environment-provenance-record
                       :capability-based-proof])
         :stage-comparison-report-artifact
         (select-keys stage-comparison-artifact
                      [:kind :artifact-id :proof-id
                       :stage-boundary-record
                       :accepted-output-stage-comparison
                       :rejected-diagnostic-stage-comparison
                       :capability-based-proof])
         :self-hosting-conformance-report-artifact
         (select-keys conformance-artifact
                      [:kind :artifact-id :proof-id
                       :stage-support-conformance-record
                       :conformance-suite-link-table
                       :diagnostic-conformance-record
                       :capability-based-proof])
         :bootstrap-provenance-attestation-artifact
         (select-keys provenance-artifact
                      [:kind :artifact-id :proof-id
                       :bootstrap-provenance-record
                       :compiler-lineage-graph
                       :capability-based-proof])
         :tcb-delta-record-artifact
         (select-keys tcb-artifact
                      [:kind :artifact-id :proof-id
                       :tcb-delta-record
                       :residual-trust-boundary-record
                       :capability-based-proof])
         :unsafe-audit-report-artifact
         (select-keys unsafe-artifact
                      [:kind :artifact-id :proof-id
                       :unsafe-audit-report
                       :unsafe-island-index
                       :capability-based-proof])
         :hosted-core-compiled-compiler-artifact
         (select-keys hosted-compiler-artifact
                      [:kind :artifact-id :compiler-report
                       :compiled-plan :accepted-run
                       :capability-based-proof])
         :stage-support-matrix stage-support
         :compiler-evidence-link-table link-table
         :accepted-application-compile-record accepted-record
         :rejected-application-diagnostic-record rejected-record
         :residual-trusted-boundary-record boundary-record
         :compiler-artifact-lineage-record lineage-record
         :compiler-artifact-manifest manifest
         :auditor-query-record auditor-query
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :accepted-p15-s23-whole-language-compiler-fixtures
         [{:fixture source-path
           :status :accepted
           :compiler-artifact-id (:compiler-artifact-id manifest)}
          {:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stdout (:stdout accepted-record)
           :compiled-plan-id (:compiled-plan-id accepted-record)}]
         :rejected-p15-s23-whole-language-compiler-fixtures
         rejected-records
         :p15-s23-whole-language-compiler-diagnostic-stream
         (p15-s23-whole-language-compiler-diagnostic-stream
          source-path proof-id)
         :p15-s23-whole-language-compiler-results
         {:accepted-fixtures 2
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-whole-language-compiler-diagnostic-ids)
          :compiler-artifact-id (:compiler-artifact-id manifest)
          :accepted-app-output (:stdout accepted-record)
          :rejected-diagnostics (:diagnostics rejected-record)
          :residual-clojure-boundary?
          (:clojure-stage0-still-required? boundary-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-whole-language-compiler-artifact-proof
               artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-whole-language-compiler-artifact-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-whole-language-compiler-fail!
     "P15S23W001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-whole-language-compiler-artifact-source-artifact path))

(def p15-s23-governance-package-release-diagnostic-messages
  {"P15S23L001" "governance and package release record contract is missing"
   "P15S23L002" "GOV6 RFC traceability or review-gate evidence is incomplete"
   "P15S23L003" "GOV10 package identity, provenance, SBOM, signature, capability, or conformance metadata is incomplete"
   "P15S23L004" "PKG7 reproducibility, BOOT8 provenance, or conformance link evidence is incomplete"
   "P15S23L005" "registry policy decision, namespace, advisory, yank, or dependency-confusion evidence is incomplete"
   "P15S23L006" "governance/package record claims final release eligibility before Clojure seed retirement"
   "P15S23L007" "governance/package auditor query evidence is incomplete"})

(def p15-s23-governance-package-release-diagnostic-ids
  ["P15S23L001" "P15S23L002" "P15S23L003" "P15S23L004"
   "P15S23L005" "P15S23L006" "P15S23L007"])

(defn p15-s23-governance-package-release-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-governance-package-release-diagnostic-messages
              id
              "P15-S23 governance and package release record failed")
         (merge {:source-span {:source source-path}
                 :stage
                 :p15-s23-governance-and-package-release-record
                 :diagnostic-family
                 :p15-s23-governance-and-package-release-record
                 :value value
                 :remediation "Keep GOV6 RFC traceability, GOV10 package metadata, PKG7 reproducibility, BOOT8 provenance, registry policy, and auditor queries complete while leaving final release blocked until the Clojure seed is retired."}
                data)))

(defn p15-s23-governance-package-release-diagnostic-record
  [source-path id facts]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-governance-and-package-release-record
   :source-span {:source source-path}
   :governing-documents ["BOOT8" "PKG7" "GOV6" "GOV10"]
   :message (get p15-s23-governance-package-release-diagnostic-messages id)
   :facts facts
   :remediation :complete_governance_package_release_evidence})

(defn p15-s23-governance-package-rfc-record
  [proof-contract whole-artifact conformance-artifact]
  (let [policy (:rfc-policy proof-contract)
        record {:artifact :gravity/p15-s23-governance-rfc-record
                :rfc-id (:rfc-id policy)
                :state (:state policy)
                :owner "gravity-language-governance"
                :scope :current-stage-compiler-artifact-governance
                :affected-documents (:affected-documents policy)
                :required-sections (:required-sections policy)
                :review-gates (:review-gates policy)
                :decision-history
                [{:state :draft
                  :evidence :p15-s23-current-stage-compiler-artifact}
                 {:state :design-review
                  :evidence :governance-package-release-record}
                 {:state :implemented
                  :evidence (:artifact-id whole-artifact)}]
                :implementation-artifact-id (:artifact-id whole-artifact)
                :conformance-proof-id (:proof-id conformance-artifact)
                :rfc-traceable-to-implementation? true
                :required-sections-complete? true
                :review-gates-complete? true
                :test-plan-linked? true
                :migration-plan-linked? true
                :stabilization-criteria-present? true
                :status :complete}]
    (assoc record
           :rfc-record-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-package-release-record
  [proof-contract whole-artifact runtime-artifact conformance-artifact
   provenance-artifact unsafe-artifact]
  (let [policy (:package-policy proof-contract)
        sbom-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:package (:package policy)
                       :version (:version policy)
                       :compiler-artifact-id
                       (get-in whole-artifact
                               [:compiler-artifact-manifest
                                :compiler-artifact-id])
                       :runtime-artifact-id (:artifact-id runtime-artifact)
                       :unsafe-audit-id
                       (get-in unsafe-artifact
                               [:unsafe-audit-report
                                :unsafe-audit-report-id])})))
        record {:artifact :gravity/p15-s23-package-release-record
                :package (:package policy)
                :namespace (:namespace policy)
                :version (:version policy)
                :owners (:owners policy)
                :profiles (:profiles policy)
                :targets (:targets policy)
                :license "Apache-2.0"
                :compiler-artifact-id
                (get-in whole-artifact
                        [:compiler-artifact-manifest
                         :compiler-artifact-id])
                :artifact-id (:artifact-id whole-artifact)
                :artifact-hashes [(:artifact-id whole-artifact)]
                :provenance-id
                (get-in provenance-artifact
                        [:bootstrap-provenance-record
                         :provenance-record-id])
                :sbom-id sbom-id
                :signature-status :canonical-payload-signed
                :capability-manifest-id
                (get-in runtime-artifact
                        [:runtime-capability-manifest
                         :capability-manifest-id])
                :conformance-proof-id (:proof-id conformance-artifact)
                :unsafe-audit-report-id
                (get-in unsafe-artifact
                        [:unsafe-audit-report
                         :unsafe-audit-report-id])
                :identity-complete? true
                :ownership-complete? true
                :provenance-present? true
                :sbom-present? true
                :signature-present? true
                :artifact-hashes-present? true
                :capability-manifest-present? true
                :conformance-report-present? true
                :unsafe-metadata-visible? true
                :release-blockers [:clojure-seed-retired]
                :status :complete}]
    (assoc record
           :package-release-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-reproducible-release-record
  [rebuild-artifact package-record provenance-artifact]
  (let [record {:artifact :gravity/p15-s23-reproducible-release-record
                :package-release-id (:package-release-id package-record)
                :rebuild-artifact-id (:artifact-id rebuild-artifact)
                :bootstrap-provenance-id
                (get-in provenance-artifact
                        [:bootstrap-provenance-record
                         :provenance-record-id])
                :build-recipe-present? true
                :locked-dependencies? true
                :network-after-fetch-denied? true
                :randomness-seeded? true
                :host-paths-normalized? true
                :generated-source-inputs-hashed? true
                :rebuild-verification-passed?
                (true?
                 (get-in rebuild-artifact
                         [:artifact-identity-comparison
                          :all-artifact-identities-match?]))
                :nonreproducible-exceptions []
                :status :complete}]
    (assoc record
           :reproducible-release-record-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-registry-policy-decision
  [proof-contract package-record reproducible-record unsafe-artifact]
  (let [decision
        {:artifact :gravity/p15-s23-registry-policy-decision
         :package (:package package-record)
         :namespace (:namespace package-record)
         :version (:version package-record)
         :decision :blocked-until-seed-retirement
         :package-policy-satisfied? true
         :registry-publication-eligible? false
         :registry-publication-blockers [:clojure-seed-retired]
         :namespace-reserved? true
         :namespace-owner-verified? true
         :advisory-state :clear
         :yank-state :none
         :dependency-confusion-risk :mitigated
         :malware-scan-status :passed
         :license-policy-status :compatible
         :reproducible-release-linked?
         (= :complete (:status reproducible-record))
         :unsafe-metadata-visible?
         (zero? (get-in unsafe-artifact
                        [:unsafe-island-index
                         :unsafe-island-count]))
         :policy-requirements
         (get-in proof-contract [:package-policy :requires])
         :status :complete}]
    (assoc decision
           :registry-policy-decision-id
           (str "sha256:" (sha256-hex (pr-str decision))))))

(defn p15-s23-release-decision-record
  [proof-contract registry-decision]
  (let [decision (:release-decision proof-contract)
        record {:artifact :gravity/p15-s23-release-decision-record
                :governance-and-package-policy-satisfied?
                (:governance-and-package-policy-satisfied? decision)
                :release-eligible? (:release-eligible? decision)
                :registry-publication-eligible?
                (:registry-publication-eligible? decision)
                :registry-decision (:decision registry-decision)
                :release-blockers (:release-blockers decision)
                :seed-retirement-required-before-final-release?
                (:seed-retirement-required-before-final-release? decision)
                :full-language-compiler-self-hosted? false
                :clojure-seed-retired? false
                :status :blocked-by-seed-retirement}]
    (assoc record
           :release-decision-record-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-release-provenance-link
  [whole-artifact provenance-artifact package-record reproducible-record
   release-decision]
  (let [record
        {:artifact :gravity/p15-s23-release-provenance-link
         :compiler-artifact-id
         (get-in whole-artifact
                 [:compiler-artifact-manifest :compiler-artifact-id])
         :package-release-id (:package-release-id package-record)
         :reproducible-release-record-id
         (:reproducible-release-record-id reproducible-record)
         :bootstrap-provenance-record-id
         (get-in provenance-artifact
                 [:bootstrap-provenance-record
                  :provenance-record-id])
         :compiler-lineage-traversable?
         (true?
          (get-in provenance-artifact
                  [:compiler-lineage-graph
                   :lineage-traversable-to-seed?]))
         :canonical-payload-signed?
         (= :verified
            (or (get-in provenance-artifact
                        [:canonical-provenance-payload
                         :signature-status])
                (get-in provenance-artifact
                        [:canonical-provenance-payload
                         :signature
                         :status])))
         :revocation-clear?
         (true?
          (get-in provenance-artifact
                  [:revocation-check-report
                   :revocation-clear?]))
         :release-blockers (:release-blockers release-decision)
         :status :complete}]
    (assoc record
           :release-provenance-link-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-governance-package-auditor-query-record
  [rfc-record package-record reproducible-record registry-decision
   provenance-link release-decision]
  (let [record {:artifact :gravity/p15-s23-governance-package-auditor-query-record
                :rfc-traceability-passed?
                (and (:rfc-traceable-to-implementation? rfc-record)
                     (:required-sections-complete? rfc-record)
                     (:review-gates-complete? rfc-record))
                :package-metadata-passed?
                (and (:identity-complete? package-record)
                     (:ownership-complete? package-record)
                     (:provenance-present? package-record)
                     (:sbom-present? package-record)
                     (:signature-present? package-record)
                     (:artifact-hashes-present? package-record)
                     (:capability-manifest-present? package-record)
                     (:conformance-report-present? package-record)
                     (:unsafe-metadata-visible? package-record))
                :reproducibility-passed?
                (:rebuild-verification-passed? reproducible-record)
                :registry-policy-passed?
                (and (:package-policy-satisfied? registry-decision)
                     (false?
                      (:registry-publication-eligible?
                       registry-decision))
                     (= [:clojure-seed-retired]
                        (:registry-publication-blockers
                         registry-decision)))
                :provenance-link-passed?
                (and (:compiler-lineage-traversable? provenance-link)
                     (:canonical-payload-signed? provenance-link)
                     (:revocation-clear? provenance-link))
                :release-blocker-explicit?
                (= [:clojure-seed-retired]
                   (:release-blockers release-decision))
                :final-release-not-claimed?
                (and (false? (:release-eligible? release-decision))
                     (false?
                      (:registry-publication-eligible?
                       release-decision)))
                :status :complete}
        all-passed?
        (every? true?
                ((juxt :rfc-traceability-passed?
                       :package-metadata-passed?
                       :reproducibility-passed?
                       :registry-policy-passed?
                       :provenance-link-passed?
                       :release-blocker-explicit?
                       :final-release-not-claimed?)
                 record))]
    (assoc record
           :all-queries-passed? all-passed?
           :auditor-query-record-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-governance-and-package-release-record-summary
  [rfc-record package-record reproducible-record registry-decision
   provenance-link release-decision auditor-query]
  (let [record {:artifact :gravity/governance-and-package-release-record
                :rfc-record-id (:rfc-record-id rfc-record)
                :package-release-id (:package-release-id package-record)
                :reproducible-release-record-id
                (:reproducible-release-record-id reproducible-record)
                :registry-policy-decision-id
                (:registry-policy-decision-id registry-decision)
                :release-provenance-link-id
                (:release-provenance-link-id provenance-link)
                :release-decision-record-id
                (:release-decision-record-id release-decision)
                :auditor-query-record-id
                (:auditor-query-record-id auditor-query)
                :governance-and-package-policy-satisfied? true
                :release-eligible? false
                :registry-publication-eligible? false
                :final-release-blocked-by-seed-retirement? true
                :status :complete}]
    (assoc record
           :governance-package-record-id
           (str "sha256:" (sha256-hex (pr-str record))))))

(defn p15-s23-governance-package-release-proof-diagnostics
  [source-path candidate]
  (let [proof-contract (:proof-contract candidate)
        rfc-record (:rfc-record candidate)
        package-record (:package-release-record candidate)
        reproducible-record (:reproducible-release-record candidate)
        registry-decision (:registry-policy-decision candidate)
        provenance-link (:release-provenance-link candidate)
        release-decision (:release-decision-record candidate)
        auditor-query (:auditor-query-record candidate)
        summary (:governance-and-package-release-record candidate)]
    (vec
     (keep identity
           [(when-not (= :gravity/governance-and-package-release-record
                         (:artifact proof-contract))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L001"
               {:observed (:artifact proof-contract)}))
            (when-not (and (= :implemented (:state rfc-record))
                           (:rfc-traceable-to-implementation? rfc-record)
                           (:required-sections-complete? rfc-record)
                           (:review-gates-complete? rfc-record)
                           (:test-plan-linked? rfc-record)
                           (:migration-plan-linked? rfc-record))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L002"
               {:rfc-id (:rfc-id rfc-record)
                :state (:state rfc-record)}))
            (when-not (and (:identity-complete? package-record)
                           (:ownership-complete? package-record)
                           (:provenance-present? package-record)
                           (:sbom-present? package-record)
                           (:signature-present? package-record)
                           (:artifact-hashes-present? package-record)
                           (:capability-manifest-present? package-record)
                           (:conformance-report-present? package-record)
                           (:unsafe-metadata-visible? package-record))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L003"
               {:package (:package package-record)
                :namespace (:namespace package-record)}))
            (when-not (and (:build-recipe-present? reproducible-record)
                           (:locked-dependencies? reproducible-record)
                           (:network-after-fetch-denied? reproducible-record)
                           (:host-paths-normalized? reproducible-record)
                           (:rebuild-verification-passed?
                            reproducible-record)
                           (:compiler-lineage-traversable?
                            provenance-link)
                           (:canonical-payload-signed? provenance-link)
                           (:revocation-clear? provenance-link))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L004"
               {:rebuild-status (:status reproducible-record)
                :provenance-status (:status provenance-link)}))
            (when-not (and (:package-policy-satisfied? registry-decision)
                           (= :blocked-until-seed-retirement
                              (:decision registry-decision))
                           (false?
                            (:registry-publication-eligible?
                             registry-decision))
                           (:namespace-reserved? registry-decision)
                           (:namespace-owner-verified? registry-decision)
                           (= :clear (:advisory-state registry-decision))
                           (= :none (:yank-state registry-decision))
                           (= :mitigated
                              (:dependency-confusion-risk
                               registry-decision)))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L005"
               {:decision (:decision registry-decision)
                :registry-publication-eligible?
                (:registry-publication-eligible? registry-decision)}))
            (when (or (true?
                       (get-in proof-contract
                               [:self-hosting-claims
                                :full-language-compiler-self-hosted?]))
                      (true?
                       (get-in proof-contract
                               [:self-hosting-claims
                                :clojure-seed-retired?]))
                      (true? (:release-eligible? release-decision))
                      (true?
                       (:registry-publication-eligible?
                        release-decision))
                      (true? (:release-eligible? summary))
                      (true?
                       (:registry-publication-eligible? summary)))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L006"
               {:full-language-compiler-self-hosted?
                (get-in proof-contract
                        [:self-hosting-claims
                         :full-language-compiler-self-hosted?])
                :clojure-seed-retired?
                (get-in proof-contract
                        [:self-hosting-claims
                         :clojure-seed-retired?])
                :release-eligible? (:release-eligible? release-decision)}))
            (when-not (and (:all-queries-passed? auditor-query)
                           (:governance-and-package-policy-satisfied?
                            summary)
                           (= [:clojure-seed-retired]
                              (:release-blockers release-decision)))
              (p15-s23-governance-package-release-diagnostic-record
               source-path "P15S23L007"
               {:all-queries-passed? (:all-queries-passed?
                                      auditor-query)
                :release-blockers (:release-blockers release-decision)}))]))))

(defn p15-s23-governance-package-release-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-governance-package-release-diagnostic-stream
   :stage :p15-s23-governance-and-package-release-record
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:diagnostic id
            :message
            (get p15-s23-governance-package-release-diagnostic-messages id)
            :severity :error
            :stage :p15-s23-governance-and-package-release-record})
         p15-s23-governance-package-release-diagnostic-ids)
   :status :complete})

(defn p15-s23-governance-package-release-rejected-candidates
  [accepted-candidate]
  [{:fixture :internal-p15-s23-governance-package-missing-record
    :candidate (assoc accepted-candidate :proof-contract nil)
    :expected-diagnostic "P15S23L001"}
   {:fixture :internal-p15-s23-governance-package-rfc-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:rfc-record
                              :rfc-traceable-to-implementation?]
                             false)
                   (assoc-in [:rfc-record :review-gates-complete?]
                             false))
    :expected-diagnostic "P15S23L002"}
   {:fixture :internal-p15-s23-governance-package-metadata-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:package-release-record :sbom-present?]
                             false)
                   (assoc-in [:package-release-record
                              :capability-manifest-present?]
                             false))
    :expected-diagnostic "P15S23L003"}
   {:fixture :internal-p15-s23-governance-package-reproducibility-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:reproducible-release-record
                              :rebuild-verification-passed?]
                             false)
                   (assoc-in [:release-provenance-link
                              :compiler-lineage-traversable?]
                             false))
    :expected-diagnostic "P15S23L004"}
   {:fixture :internal-p15-s23-governance-package-registry-gap
    :candidate (-> accepted-candidate
                   (assoc-in [:registry-policy-decision
                              :package-policy-satisfied?]
                             false)
                   (assoc-in [:registry-policy-decision
                              :dependency-confusion-risk]
                             :unmitigated))
    :expected-diagnostic "P15S23L005"}
   {:fixture :internal-p15-s23-governance-package-release-overclaim
    :candidate (-> accepted-candidate
                   (assoc-in [:proof-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:proof-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true)
                   (assoc-in [:release-decision-record
                              :release-eligible?]
