    :expected-diagnostic "P15S23L007"}])

(defn p15-s23-governance-package-release-rejected-records
  [source-path accepted-candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-governance-package-release-proof-diagnostics
            source-path candidate)})
        (p15-s23-governance-package-release-rejected-candidates
         accepted-candidate)))

(defn p15-s23-governance-package-release-record-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-governance-package-release-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-governance-package-release-fixtures
                      artifact)))]
    {:governance-package-release-record-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :rfc-traceability-complete?
     (true? (get-in artifact [:rfc-record
                              :rfc-traceable-to-implementation?]))
     :rfc-review-gates-complete?
     (true? (get-in artifact [:rfc-record :review-gates-complete?]))
     :package-metadata-complete?
     (and (true? (get-in artifact [:package-release-record
                                   :identity-complete?]))
          (true? (get-in artifact [:package-release-record
                                   :provenance-present?]))
          (true? (get-in artifact [:package-release-record
                                   :sbom-present?]))
          (true? (get-in artifact [:package-release-record
                                   :signature-present?]))
          (true? (get-in artifact [:package-release-record
                                   :capability-manifest-present?]))
          (true? (get-in artifact [:package-release-record
                                   :conformance-report-present?])))
     :reproducible-release-evidence-complete?
     (true? (get-in artifact [:reproducible-release-record
                              :rebuild-verification-passed?]))
     :boot8-provenance-linked?
     (true? (get-in artifact [:release-provenance-link
                              :compiler-lineage-traversable?]))
     :registry-policy-decision-complete?
     (and (true? (get-in artifact [:registry-policy-decision
                                   :package-policy-satisfied?]))
          (= :blocked-until-seed-retirement
             (get-in artifact [:registry-policy-decision
                               :decision])))
     :governance-and-package-policy-satisfied?
     (true? (get-in artifact [:release-decision-record
                              :governance-and-package-policy-satisfied?]))
     :release-blocked-by-seed-retirement?
     (= [:clojure-seed-retired]
        (get-in artifact [:release-decision-record :release-blockers]))
     :does-not-claim-release-eligibility?
     (false? (get-in artifact [:release-decision-record
                               :release-eligible?]))
     :does-not-claim-registry-publication?
     (false? (get-in artifact [:registry-policy-decision
                               :registry-publication-eligible?]))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :auditor-queries-passed?
     (true? (get-in artifact [:auditor-query-record
                              :all-queries-passed?]))
     :rejected-candidates-covered?
     (set/subset?
      (set p15-s23-governance-package-release-diagnostic-ids)
      rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-governance-package-release-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :release-eligible? false
      :registry-publication-eligible? false
      :governance-and-package-policy-satisfied? true
      :release-blockers [:clojure-seed-retired]
      :next-required-capability :retire_clojure_seed_boundary}}))

(defn p15-s23-governance-and-package-release-record-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        proof-contract
        (p15-s23-compiler-def-value
         source-path
         (:forms source-data)
         'p15-s23-governance-and-package-release-record)
        whole-artifact
        (p15-s23-current-candidate-artifact-evidence
         :whole-language-compiler-artifact)
        runtime-artifact
        (p15-s23-current-candidate-artifact-evidence
         :runtime-manifest-and-capability-enforcement-report)
        rebuild-artifact
        (p15-s23-current-candidate-artifact-evidence
         :reproducible-rebuild-log)
        conformance-artifact
        (p15-s23-current-candidate-artifact-evidence
         :conformance-report)
        provenance-artifact
        (p15-s23-current-candidate-artifact-evidence
         :provenance-attestation)
        tcb-artifact
        (p15-s23-current-candidate-artifact-evidence
         :tcb-delta-record)
        unsafe-artifact
        (p15-s23-current-candidate-artifact-evidence
         :unsafe-audit-report)
        rfc-record
        (p15-s23-governance-package-rfc-record
         proof-contract whole-artifact conformance-artifact)
        package-record
        (p15-s23-package-release-record
         proof-contract whole-artifact runtime-artifact conformance-artifact
         provenance-artifact unsafe-artifact)
        reproducible-record
        (p15-s23-reproducible-release-record
         rebuild-artifact package-record provenance-artifact)
        registry-decision
        (p15-s23-registry-policy-decision
         proof-contract package-record reproducible-record unsafe-artifact)
        release-decision
        (p15-s23-release-decision-record
         proof-contract registry-decision)
        provenance-link
        (p15-s23-release-provenance-link
         whole-artifact provenance-artifact package-record
         reproducible-record release-decision)
        auditor-query
        (p15-s23-governance-package-auditor-query-record
         rfc-record package-record reproducible-record registry-decision
         provenance-link release-decision)
        summary-record
        (p15-s23-governance-and-package-release-record-summary
         rfc-record package-record reproducible-record registry-decision
         provenance-link release-decision auditor-query)
        candidate
        {:proof-contract proof-contract
         :rfc-record rfc-record
         :package-release-record package-record
         :reproducible-release-record reproducible-record
         :registry-policy-decision registry-decision
         :release-decision-record release-decision
         :release-provenance-link provenance-link
         :auditor-query-record auditor-query
         :governance-and-package-release-record summary-record}
        diagnostics
        (p15-s23-governance-package-release-proof-diagnostics
         source-path candidate)
        _ (when (seq diagnostics)
            (p15-s23-governance-package-release-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :proof-contract proof-contract
                       :rfc-record rfc-record
                       :package-record package-record
                       :reproducible-record reproducible-record
                       :registry-decision registry-decision
                       :release-decision release-decision
                       :provenance-link provenance-link
                       :auditor-query auditor-query
                       :summary-record summary-record})))
        rejected-records
        (p15-s23-governance-package-release-rejected-records
         source-path candidate)
        artifact-base
        {:kind
         :gravity/p15-s23-governance-and-package-release-record-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-governance-and-package-release-record
         :source-path source-path
         :proof-id proof-id
         :proof-contract proof-contract
         :whole-language-compiler-artifact
         (select-keys whole-artifact
                      [:kind :artifact-id :proof-id
                       :compiler-artifact-manifest
                       :capability-based-proof])
         :runtime-manifest-capability-artifact
         (select-keys runtime-artifact
                      [:kind :artifact-id :proof-id
                       :runtime-capability-manifest
                       :capability-based-proof])
         :reproducible-rebuild-log-artifact
         (select-keys rebuild-artifact
                      [:kind :artifact-id :proof-id
                       :artifact-identity-comparison
                       :capability-based-proof])
         :self-hosting-conformance-report-artifact
         (select-keys conformance-artifact
                      [:kind :artifact-id :proof-id
                       :stage-support-conformance-record
                       :capability-based-proof])
         :bootstrap-provenance-attestation-artifact
         (select-keys provenance-artifact
                      [:kind :artifact-id :proof-id
                       :bootstrap-provenance-record
                       :compiler-lineage-graph
                       :canonical-provenance-payload
                       :revocation-check-report
                       :capability-based-proof])
         :tcb-delta-record-artifact
         (select-keys tcb-artifact
                      [:kind :artifact-id :proof-id
                       :tcb-delta-record
                       :capability-based-proof])
         :unsafe-audit-report-artifact
         (select-keys unsafe-artifact
                      [:kind :artifact-id :proof-id
                       :unsafe-audit-report
                       :unsafe-island-index
                       :package-safety-metadata
                       :capability-based-proof])
         :rfc-record rfc-record
         :package-release-record package-record
         :reproducible-release-record reproducible-record
         :registry-policy-decision registry-decision
         :release-decision-record release-decision
         :release-provenance-link provenance-link
         :auditor-query-record auditor-query
         :governance-and-package-release-record summary-record
         :full-language-compiler-self-hosted?
         (get-in proof-contract
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in proof-contract
                 [:self-hosting-claims :clojure-seed-retired?])
         :release-eligible? (:release-eligible? release-decision)
         :registry-publication-eligible?
         (:registry-publication-eligible? registry-decision)
         :accepted-p15-s23-governance-package-release-fixtures
         [{:fixture source-path
           :status :accepted
           :governance-package-record-id
           (:governance-package-record-id summary-record)}]
         :rejected-p15-s23-governance-package-release-fixtures
         rejected-records
         :p15-s23-governance-package-release-diagnostic-stream
         (p15-s23-governance-package-release-diagnostic-stream
          source-path proof-id)
         :p15-s23-governance-package-release-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-governance-package-release-diagnostic-ids)
          :governance-package-record-id
          (:governance-package-record-id summary-record)
          :package-release-id (:package-release-id package-record)
          :registry-decision (:decision registry-decision)
          :governance-and-package-policy-satisfied?
          (:governance-and-package-policy-satisfied? release-decision)
          :release-eligible? (:release-eligible? release-decision)
          :release-blockers (:release-blockers release-decision)
          :status :in-progress}
         :diagnostics []}
        proof
        (p15-s23-governance-package-release-record-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-governance-and-package-release-record-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-governance-package-release-fail!
     "P15S23L001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-governance-and-package-release-record-source-artifact path))

(declare hosted-core-compiled-app-proof-file-artifact)

(def p15-s23-stage2-compiler-nucleus-required-preserves
  #{:source-spans :diagnostic-codes :effects :capabilities :profile
    :compiler-lineage :artifact-provenance})

(def p15-s23-stage2-compiler-nucleus-required-emits
  #{:compiled-instruction-plan :accepted-output-comparison
    :rejected-diagnostic-comparison :stage2-boundary-record})

(def p15-s23-stage2-compiler-nucleus-diagnostic-messages
  {"P15S23N001" "P15-S23 stage2 compiler nucleus contract is missing"
   "P15S23N002" "P15-S23 stage2 compiler nucleus does not match the accepted compiled app plan"
   "P15S23N003" "P15-S23 stage2 compiler nucleus does not preserve rejected app diagnostics"
   "P15S23N004" "P15-S23 stage2 compiler nucleus is missing required evidence links"
   "P15S23N005" "P15-S23 stage2 compiler nucleus preservation or emission contract is incomplete"
   "P15S23N006" "P15-S23 stage2 compiler nucleus residual Clojure seed boundary is incomplete"
   "P15S23N007" "P15-S23 stage2 compiler nucleus makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-compiler-nucleus-diagnostic-ids
  ["P15S23N001" "P15S23N002" "P15S23N003" "P15S23N004"
   "P15S23N005" "P15S23N006" "P15S23N007"])

(defn p15-s23-stage2-compiler-nucleus-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-compiler-nucleus-diagnostic-messages
              id
              "P15-S23 stage2 compiler nucleus proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-compiler-nucleus
                 :diagnostic-family
                 :p15-s23-stage2-compiler-nucleus
                 :value value
                 :remediation "Keep the compiler nucleus authored in Gravity source, prove it against the accepted compiled-plan fixture and rejected diagnostics, record the remaining Clojure seed boundary, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-compiler-nucleus-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-compiler-nucleus
   :source-span {:source source-path}
   :message (get p15-s23-stage2-compiler-nucleus-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_compiler_nucleus_contract})

(defn p15-s23-stage2-sort-values
  [values]
  (vec (sort-by str values)))

(defn p15-s23-stage2-compiler-nucleus-accepted-plan-record
  [nucleus compiled-app-artifact]
  (let [contract (:accepted-plan-contract nucleus)
        plan (:compiled-plan compiled-app-artifact)
        summary (:instruction-summary plan)
        required-ops (set (:required-op-families contract))
        present-ops (set (keys summary))
        missing-ops (set/difference required-ops present-ops)
        binding-names (set (map :name (:binding-table plan)))
        required-users (set (:required-user-functions contract))
        missing-users (set/difference required-users binding-names)
        required-effects (set (:required-effects contract))
        required-capabilities (set (:required-capabilities contract))
        declared-effects (set (get-in plan [:effect-summary :declared]))
        declared-capabilities (set (get-in plan
                                           [:effect-summary :capabilities]))
        stdout (get-in compiled-app-artifact [:accepted-run :stdout])
        expected-stdout (:expected-stdout contract)
        matches?
        (and (= :gravity/stage0-hosted-core-compiled-app-proof
                (:kind compiled-app-artifact))
             (= p15-s23-accepted-app-source-path (:fixture contract))
             (= p15-s23-accepted-app-source-path
                (get-in compiled-app-artifact [:source :path]))
             (= (:module contract)
                (get-in compiled-app-artifact [:module :module]))
             (= (:profile contract)
                (get-in compiled-app-artifact [:module :profile]))
             (= (:target contract)
                (get-in compiled-app-artifact [:module :target]))
             (= :gravity/stage0-hosted-core-compiled-plan (:kind plan))
             (= (:entrypoint contract) (:entrypoint plan))
             (empty? missing-ops)
             (empty? missing-users)
             (= required-effects declared-effects)
             (= required-capabilities declared-capabilities)
             (= stdout expected-stdout)
             (true? (get-in compiled-app-artifact
                             [:capability-based-proof
                              :compiled-plan-executed?])))]
    {:artifact :gravity/p15-s23-stage2-accepted-plan-record
     :fixture (:fixture contract)
     :compiled-plan-id (:plan-id plan)
     :compiled-plan-kind (:kind plan)
     :entrypoint (:entrypoint plan)
     :required-op-families (p15-s23-stage2-sort-values required-ops)
     :present-op-families (p15-s23-stage2-sort-values present-ops)
     :missing-op-families (p15-s23-stage2-sort-values missing-ops)
     :required-user-functions (p15-s23-stage2-sort-values required-users)
     :binding-names (p15-s23-stage2-sort-values binding-names)
     :missing-user-functions (p15-s23-stage2-sort-values missing-users)
     :required-effects required-effects
     :declared-effects declared-effects
     :required-capabilities required-capabilities
     :declared-capabilities declared-capabilities
     :stdout stdout
     :expected-stdout expected-stdout
     :output-matches? (= stdout expected-stdout)
     :compiled-plan-executed?
     (true? (get-in compiled-app-artifact
                    [:capability-based-proof :compiled-plan-executed?]))
     :status (if matches? :complete :failed)}))

(defn p15-s23-stage2-compiler-nucleus-rejected-diagnostic-record
  [nucleus rejected-artifact]
  (let [contract-rows
        (set (map (juxt :fixture :expected-diagnostic)
                  (:rejected-diagnostic-contract nucleus)))
        verified-rows
        (set (map (juxt :fixture :expected-diagnostic)
                  (:verified-p15-s23-rejected-app-fixtures
                   rejected-artifact)))
        expected-diagnostics
        (set (map :expected-diagnostic
                  (:rejected-diagnostic-contract nucleus)))
        observed-diagnostics
        (set (map :diagnostic
                  (:verified-p15-s23-rejected-app-fixtures
                   rejected-artifact)))
        mismatches
        (remove :matches-expected?
                (:verified-p15-s23-rejected-app-fixtures
                 rejected-artifact))
        matches?
        (and (= :gravity/p15-s23-rejected-app-diagnostic-artifact
                (:kind rejected-artifact))
             (= contract-rows verified-rows)
             (= expected-diagnostics observed-diagnostics)
             (empty? mismatches))]
    {:artifact :gravity/p15-s23-stage2-rejected-diagnostic-record
     :expected-fixture-count (count contract-rows)
     :verified-fixture-count (count verified-rows)
     :expected-diagnostics (p15-s23-stage2-sort-values
                            expected-diagnostics)
     :observed-diagnostics (p15-s23-stage2-sort-values
                            observed-diagnostics)
     :missing-fixtures
     (p15-s23-stage2-sort-values
      (set/difference contract-rows verified-rows))
     :unexpected-fixtures
     (p15-s23-stage2-sort-values
      (set/difference verified-rows contract-rows))
     :mismatch-count (count mismatches)
     :status (if matches? :complete :failed)}))

(defn p15-s23-stage2-compiler-nucleus-evidence-link-record
  [nucleus pipeline-artifact accepted-artifact rejected-artifact]
  (let [required-links (set (:required-evidence-links nucleus))
        links {:compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}
               :accepted-app-execution-proof
               {:artifact (:kind accepted-artifact)
                :artifact-id (:artifact-id accepted-artifact)
                :proof-id (:proof-id accepted-artifact)
                :present?
                (= :gravity/p15-s23-accepted-app-execution-artifact
                   (:kind accepted-artifact))}
               :rejected-app-diagnostic-proof
               {:artifact (:kind rejected-artifact)
                :artifact-id (:artifact-id rejected-artifact)
                :proof-id (:proof-id rejected-artifact)
                :present?
                (= :gravity/p15-s23-rejected-app-diagnostic-artifact
                   (:kind rejected-artifact))}}
        present-links (set (for [[k v] links :when (:present? v)] k))
        missing-links (set/difference required-links present-links)]
    {:artifact :gravity/p15-s23-stage2-evidence-link-record
     :required-links (p15-s23-stage2-sort-values required-links)
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing-links)
     :all-required-links-present? (empty? missing-links)
     :status (if (empty? missing-links) :complete :failed)}))

(defn p15-s23-stage2-compiler-nucleus-boundary-record
  [nucleus]
  (let [claims (:self-hosting-claims nucleus)]
    {:artifact :gravity/p15-s23-stage2-boundary-record
     :implemented-by (:implemented-by nucleus)
     :verified-by (:verified-by nucleus)
     :compiled-by (get-in nucleus [:lineage :compiled-by])
     :source-language (get-in nucleus [:lineage :source-language])
     :clojure-stage0-verifier?
     (= :clojure-stage0 (:verified-by nucleus))
     :clojure-stage0-compiler?
     (= :clojure-stage0 (get-in nucleus [:lineage :compiled-by]))
     :clojure-instruction-runner?
     (= :clojure-instruction-runner
        (get-in nucleus [:seed-boundary :stage0-executor-boundary]))
     :self-hosted-compiler? false
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary (:seed-boundary nucleus)
     :next-required-capability (:next-required-capability nucleus)
     :status :complete}))

(defn p15-s23-stage2-compiler-nucleus-diagnostics
  [source-path candidate]
  (let [nucleus (:nucleus-contract candidate)
        accepted-plan-record (:accepted-plan-record candidate)
        rejected-diagnostic-record (:rejected-diagnostic-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims nucleus)
        preserves (set (:preserves nucleus))
        emits (set (:emits nucleus))
        stage-preserves (set (get-in nucleus [:nucleus-stage :preserves]))
        stage-emits (set (get-in nucleus [:nucleus-stage :emits]))
        missing-preserves
        (set/difference p15-s23-stage2-compiler-nucleus-required-preserves
                        (set/union preserves stage-preserves))
        missing-emits
        (set/difference p15-s23-stage2-compiler-nucleus-required-emits
                        (set/union emits stage-emits))]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-compiler-nucleus
                        (:artifact nucleus))
                     (= :p15-s23-stage2-compiler-nucleus
                        (:stage nucleus))
                     (= :gravity-source (:implemented-by nucleus))
                     (= :hosted-core-compiled-plan-emission
                        (:module-responsibility nucleus)))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N001" nucleus
          {:missing-fields [:artifact :stage :implemented-by
                            :module-responsibility]})])
      (when-not (= :complete (:status accepted-plan-record))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N002" accepted-plan-record
          {:missing-op-families
           (:missing-op-families accepted-plan-record)
           :missing-user-functions
           (:missing-user-functions accepted-plan-record)
           :expected-stdout p15-s23-accepted-app-expected-stdout})])
      (when-not (= :complete (:status rejected-diagnostic-record))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N003" rejected-diagnostic-record
          {:required-diagnostics
           (mapv :expected-diagnostic p15-s23-rejected-app-fixtures)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N004" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N005" nucleus
          {:missing-preserves (p15-s23-stage2-sort-values
                               missing-preserves)
           :missing-emits (p15-s23-stage2-sort-values missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:clojure-stage0-verifier? boundary-record))
                     (true? (:clojure-stage0-compiler? boundary-record))
                     (true? (:clojure-instruction-runner?
                             boundary-record))
                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N006" boundary-record
          {:required-boundary [:clojure-stage0-verifier
                               :clojure-stage0-compiler
                               :clojure-instruction-runner
                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-compiler-nucleus-diagnostic-record
          source-path "P15S23N007" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-compiler-nucleus-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage2-compiler-nucleus-diagnostic-stream
   :stage :p15-s23-stage2-compiler-nucleus
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-compiler-nucleus
            :message
            (get p15-s23-stage2-compiler-nucleus-diagnostic-messages
                 id)})
         p15-s23-stage2-compiler-nucleus-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-compiler-nucleus-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-nucleus-missing-contract
    :candidate (assoc candidate :nucleus-contract {})
    :expected-diagnostic "P15S23N001"}
   {:fixture :internal-p15-s23-stage2-nucleus-plan-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-plan-record :status] :failed)
                   (assoc-in [:accepted-plan-record
                              :missing-op-families]
                             [:println]))
    :expected-diagnostic "P15S23N002"}
   {:fixture :internal-p15-s23-stage2-nucleus-rejected-diagnostic-gap
    :candidate (-> candidate
                   (assoc-in [:rejected-diagnostic-record :status]
                             :failed)
                   (assoc-in [:rejected-diagnostic-record
                              :mismatch-count]
                             1))
    :expected-diagnostic "P15S23N003"}
   {:fixture :internal-p15-s23-stage2-nucleus-evidence-link-gap
    :candidate (-> candidate
                   (assoc-in [:evidence-link-record :status] :failed)
                   (assoc-in [:evidence-link-record :missing-links]
                             [:accepted-app-execution-proof]))
    :expected-diagnostic "P15S23N004"}
   {:fixture :internal-p15-s23-stage2-nucleus-preservation-gap
    :candidate (-> candidate
                   (assoc-in [:nucleus-contract :preserves] [])
                   (assoc-in [:nucleus-contract :nucleus-stage
                              :preserves]
                             []))
    :expected-diagnostic "P15S23N005"}
   {:fixture :internal-p15-s23-stage2-nucleus-boundary-gap
    :candidate (-> candidate
                   (assoc-in [:boundary-record
                              :clojure-stage0-verifier?]
                             false)
                   (assoc-in [:boundary-record
                              :clojure-instruction-runner?]
                             false))
    :expected-diagnostic "P15S23N006"}
   {:fixture :internal-p15-s23-stage2-nucleus-overclaim
    :candidate (-> candidate
                   (assoc-in [:nucleus-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:nucleus-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23N007"}])

(defn p15-s23-stage2-compiler-nucleus-rejected-records
  [source-path candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-compiler-nucleus-diagnostics
            source-path candidate)})
        (p15-s23-stage2-compiler-nucleus-rejected-candidates
         candidate)))

(defn p15-s23-stage2-compiler-nucleus-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-compiler-nucleus-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage2-compiler-nucleus-fixtures
                      artifact)))
        accepted-plan-record (:accepted-plan-record artifact)
        rejected-diagnostic-record (:rejected-diagnostic-record artifact)
        evidence-link-record (:evidence-link-record artifact)
        boundary-record (:boundary-record artifact)]
    {:stage2-compiler-nucleus-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :gravity-authored-stage2-nucleus-present?
     (= :gravity/stage2-compiler-nucleus
        (get-in artifact [:nucleus-contract :artifact]))
     :compiled-plan-contract-matches-current-stage?
     (= :complete (:status accepted-plan-record))
     :accepted-app-output-equivalent?
     (true? (:output-matches? accepted-plan-record))
     :rejected-diagnostics-equivalent?
     (= :complete (:status rejected-diagnostic-record))
     :evidence-links-complete?
     (= :complete (:status evidence-link-record))
     :preservation-contract-complete?
     (and (empty? (:missing-op-families accepted-plan-record))
          (empty? (:missing-user-functions accepted-plan-record)))
     :residual-clojure-boundary-recorded?
     (and (true? (:clojure-stage0-verifier? boundary-record))
          (true? (:clojure-stage0-compiler? boundary-record))
          (true? (:clojure-instruction-runner? boundary-record))
          (false? (:full-language-compiler-self-hosted?
                   boundary-record))
          (false? (:clojure-seed-retired? boundary-record)))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (= (set p15-s23-stage2-compiler-nucleus-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-compiler-nucleus-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :stage2-compiler-nucleus-authored-in-gravity? true
      :stage2-executed-by-gravity? false
      :clojure-stage0-verifier? true
      :clojure-instruction-runner? true
      :full-self-hosted-toolchain? false
      :next-required-capability
      :replace_stage0_plan_emitter_with_stage2_gravity_execution}}))

(defn p15-s23-stage2-compiler-nucleus-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        nucleus
        (p15-s23-compiler-def-value source-path
                                     (:forms source-data)
                                     'p15-s23-stage2-compiler-nucleus)
        compiled-app-artifact
        (hosted-core-compiled-app-proof-file-artifact
         p15-s23-accepted-app-source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact
         source-path)
        accepted-artifact
        (p15-s23-accepted-app-execution-source-artifact
         source-path)
        rejected-artifact
        (p15-s23-rejected-app-diagnostic-source-artifact
         source-path)
        accepted-plan-record
        (p15-s23-stage2-compiler-nucleus-accepted-plan-record
         nucleus compiled-app-artifact)
        rejected-diagnostic-record
        (p15-s23-stage2-compiler-nucleus-rejected-diagnostic-record
         nucleus rejected-artifact)
        evidence-link-record
        (p15-s23-stage2-compiler-nucleus-evidence-link-record
         nucleus pipeline-artifact accepted-artifact rejected-artifact)
        boundary-record
        (p15-s23-stage2-compiler-nucleus-boundary-record nucleus)
        candidate {:nucleus-contract nucleus
                   :accepted-plan-record accepted-plan-record
                   :rejected-diagnostic-record rejected-diagnostic-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage2-compiler-nucleus-diagnostics source-path
                                                     candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-compiler-nucleus-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :nucleus nucleus
                       :compiled-plan-id
                       (:compiled-plan-id accepted-plan-record)
                       :accepted-artifact-id
                       (:artifact-id accepted-artifact)
                       :rejected-artifact-id
                       (:artifact-id rejected-artifact)})))
        rejected-records
        (p15-s23-stage2-compiler-nucleus-rejected-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage2-compiler-nucleus-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-compiler-nucleus
         :source-path source-path
         :proof-id proof-id
         :nucleus-contract nucleus
         :compiled-app-artifact
         (select-keys compiled-app-artifact
                      [:kind :artifact-id :source :module :compiled-plan
                       :runtime-surface :accepted-run :reference-run
                       :trusted-boundary :capability-based-proof])
         :compiler-pipeline-manifest-artifact
         (select-keys pipeline-artifact
                      [:kind :artifact-id :proof-id
                       :pipeline-manifest
                       :capability-based-proof])
         :accepted-app-execution-artifact
         (select-keys accepted-artifact
                      [:kind :artifact-id :proof-id
                       :accepted-app-path
                       :accepted-output-comparison
                       :compiled-plan-execution-trace
                       :capability-based-proof])
         :rejected-app-diagnostic-artifact
         (select-keys rejected-artifact
                      [:kind :artifact-id :proof-id
                       :verified-p15-s23-rejected-app-fixtures
                       :p15-s23-rejected-app-diagnostic-results
                       :capability-based-proof])
         :accepted-plan-record accepted-plan-record
         :rejected-diagnostic-record rejected-diagnostic-record
         :evidence-link-record evidence-link-record
         :boundary-record boundary-record
         :full-language-compiler-self-hosted?
         (get-in nucleus
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in nucleus [:self-hosting-claims
                          :clojure-seed-retired?])
         :accepted-p15-s23-stage2-compiler-nucleus-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :compiled-plan-id (:compiled-plan-id accepted-plan-record)
           :stdout (:stdout accepted-plan-record)
           :stage2-contract :p15-s23-stage2-compiler-nucleus}]
         :rejected-p15-s23-stage2-compiler-nucleus-fixtures
         rejected-records
         :p15-s23-stage2-compiler-nucleus-diagnostic-stream
         (p15-s23-stage2-compiler-nucleus-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-compiler-nucleus-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-records)
          :diagnostic-count
          (count p15-s23-stage2-compiler-nucleus-diagnostic-ids)
          :compiled-plan-id (:compiled-plan-id accepted-plan-record)
          :accepted-output (:stdout accepted-plan-record)
          :rejected-diagnostics
          (:observed-diagnostics rejected-diagnostic-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-compiler-nucleus-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-compiler-nucleus-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-compiler-nucleus-fail!
     "P15S23N001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-compiler-nucleus-source-artifact path))

(defn p15-s23-stage2-compiler-nucleus-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-compiler-nucleus-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :compiled-plan-id
           (get-in artifact [:accepted-plan-record
                             :compiled-plan-id])
           :accepted-output-equivalent?
           (:accepted-app-output-equivalent? proof)
           :rejected-diagnostics-equivalent?
           (:rejected-diagnostics-equivalent? proof)
           :residual-clojure-boundary-recorded?
           (:residual-clojure-boundary-recorded? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

(defn p16-std-diagnostics
  [document diagnostic-count]
  (let [number (Integer/parseInt (subs document 3))]
    (mapv #(format "STD%d%03d" number %)
          (range 1 (inc diagnostic-count)))))

