(def p16-standard-library-documents
  (mapv :document p16-standard-library-document-data))

(def p16-standard-library-data-by-document
  (into {} (map (juxt :document identity)
                p16-standard-library-document-data)))

(def p16-standard-library-phase-governing-documents
  (into {} (map (juxt :document :file)
                p16-standard-library-document-data)))

(def p16-standard-library-diagnostics-by-document
  (into {}
        (map (fn [{:keys [document diagnostic-count]}]
               [document (p16-std-diagnostics document
                                               (or diagnostic-count 8))])
             p16-standard-library-document-data)))

(def p16-standard-library-rejected-diagnostics
  (into {} (map (juxt :document :rejected-diagnostic)
                p16-standard-library-document-data)))

(def p16-standard-library-rejected-fixture-names
  (into {} (map (juxt :document :rejected-fixture)
                p16-standard-library-document-data)))

(def p16-standard-library-diagnostic-ids
  (vec
   (distinct
    (concat (mapcat p16-standard-library-diagnostics-by-document
                    p16-standard-library-documents)
            ["P16-MANIFEST" "P16-ACCEPTED" "P16-REJECTED"
             "P16-STDLIB"]))))

(def p16-standard-library-override-diagnostics
  (into {}
        (map (fn [id]
               [(keyword (str/lower-case id)) id])
             p16-standard-library-diagnostic-ids)))

(def p16-standard-library-artifact-keys
  [:library-module-manifest :api-stability-record :safe-wrapper-audit
   :library-conformance-fixture :profile-support-matrix
   :compatibility-report])

(defn p16-task-id
  [document]
  (str "P16-D" (:sequence (p16-standard-library-data-by-document document))))

(defn p16-standard-library-source-overrides
  [module]
  (get-in module [:metadata :standard-library :phase16] {}))

(defn p16-standard-library-diagnostic-document
  [diagnostic-id]
  (some (fn [document]
          (when (some #(= diagnostic-id %)
                      (p16-standard-library-diagnostics-by-document document))
            document))
        p16-standard-library-documents))

(defn p16-standard-library-fail!
  [id source-path subject extra]
  (let [document (or (:document-id subject)
                     (p16-standard-library-diagnostic-document id))]
    (fail! id
           "P16 standard-library validation failed"
           (merge {:source-span (or (:source-span subject)
                                    (source-span source-path 0))
                   :diagnostic-family :phase16-standard-library
                   :stage :standard-library
                   :document-id document
                   :task (when document (p16-task-id document))
                   :module (:module subject)
                   :artifact-id (:artifact-id subject)
                   :missing-fact (:missing-fact subject)
                   :fallback-status :rejected
                   :remediation "Phase 16 requires profile-aware module manifests, explicit effects and capabilities, safe wrapper audits, conformance fixtures, profile support matrices, stability records, and compatibility evidence before standard-library tasks can complete."}
                  extra))))

(defn p16-standard-library-validate-source-overrides!
  [source-path overrides]
  (when-let [fail-kind (:fail overrides)]
    (if-let [id (get p16-standard-library-override-diagnostics fail-kind)]
      (p16-standard-library-fail!
       id source-path
       {:artifact-id (str "p16-stdlib-" (name fail-kind))
        :document-id (p16-standard-library-diagnostic-document id)
        :missing-fact fail-kind}
       {:missing-fields [fail-kind]})
      (p16-standard-library-fail!
       "P16-MANIFEST" source-path
       {:artifact-id "p16-stdlib-unknown-override"
        :missing-fact fail-kind}
       {:missing-fields [:known-override-diagnostic]}))))

(defn p16-standard-library-module-record
  [{:keys [document module namespace title owned-surface profiles
           check-key dependencies]}]
  {:document document
   :module module
   :namespace namespace
   :title title
   :owned-surface owned-surface
   :profiles profiles
   :exports [{:name (keyword (str (name module) "-contract"))
              :kind :module-contract
              :profiles profiles
              :effects #{}
              :capabilities #{}
              :allocation :declared
              :stability :draft}]
   :effects [:declared-per-export]
   :capabilities [:declared-per-export]
   :allocation :declared-per-export
   :safety-boundary :safe-wrapper-or-rejected
   :stability :draft
   :diagnostics (p16-standard-library-diagnostics-by-document document)
   :checks (assoc {:profile-metadata true
                   :effects-declared true
                   :capabilities-declared true
                   :safe-wrapper-audited true
                   :docs-examples-compiled true
                   :stability-level true}
                  check-key true)
   :dependencies dependencies
   :status :complete})

(defn p16-standard-library-artifact-values
  []
  (let [modules (mapv p16-standard-library-module-record
                      p16-standard-library-document-data)
        profile-rows (mapv (fn [{:keys [document module profiles]}]
                             {:document document
                              :module module
                              :profiles profiles
                              :unsupported-profile-policy :reject
                              :status :complete})
                           p16-standard-library-document-data)
        stability-entries (mapv (fn [{:keys [document module namespace]}]
                                  {:document document
                                   :module module
                                   :namespace namespace
                                   :level :draft
                                   :tracked [:source :behavior :effects
                                             :capabilities :diagnostics
                                             :artifacts :profiles
                                             :conformance]
                                   :status :complete})
                                p16-standard-library-document-data)]
    {:library-module-manifest
     {:artifact :gravity/library-module-manifest
      :artifact-id "stdlib:module-manifest:phase16"
      :modules modules
      :module-count (count modules)
      :profile-metadata-complete true
      :effect-capability-metadata-complete true
      :package-manifest-consistency :complete
      :status :complete}
     :api-stability-record
     {:artifact :gravity/api-stability-record
      :artifact-id "stdlib:api-stability"
      :entries stability-entries
      :levels [:experimental :draft :stable :deprecated :removed :internal]
      :compatibility-dimensions [:source :behavior :effects :capabilities
                                 :profiles :diagnostics :artifacts
                                 :conformance]
      :explicit-opt-in-required true
      :deprecation-diagnostics true
      :status :complete}
     :safe-wrapper-audit
     {:artifact :gravity/safe-wrapper-audit
      :artifact-id "stdlib:safe-wrapper-audit"
      :audited-modules (mapv :module
                             (filter #(some #{(:document %)}
                                            ["STD3" "STD5" "STD6" "STD7"
                                             "STD8" "STD9" "STD15" "STD16"
                                             "STD17" "STD18"])
                                     p16-standard-library-document-data))
      :unsafe-islands [:allocator-internals :scheduler-internals
                       :filesystem-adapters :tls-provider
                       :hardware-mmio :crypto-constant-time]
      :safe-wrapper-policy :prove-check-reject-or-unsafe-island
      :audit-records [:std-memory-audit :std-concurrency-audit
                      :std-io-audit :std-crypto-audit
                      :std-hardware-audit]
      :status :complete}
     :library-conformance-fixture
     {:artifact :gravity/library-conformance-fixture
      :artifact-id "stdlib:conformance-fixture"
      :accepted-fixtures ["accepted/standard-library-phase16.gravity"]
      :rejected-fixtures (vals p16-standard-library-rejected-fixture-names)
      :document-count (count p16-standard-library-documents)
      :accepted-count (count p16-standard-library-documents)
      :rejected-count (count p16-standard-library-documents)
      :diagnostic-count (count p16-standard-library-diagnostic-ids)
      :suite-categories [:module-manifest :profile-matrix :safe-wrapper
                         :conformance :stability :compatibility]
      :status :complete}
     :profile-support-matrix
     {:artifact :gravity/profile-support-matrix
      :artifact-id "stdlib:profile-support-matrix"
      :rows profile-rows
      :profiles (vec (distinct (mapcat :profiles profile-rows)))
      :unsupported-profile-policy :reject
      :profile-compliance-report :p03-profile-compliance-suite
      :status :complete}
     :compatibility-report
     {:artifact :gravity/standard-library-compatibility-report
      :artifact-id "stdlib:compatibility"
      :modules (mapv :module p16-standard-library-document-data)
      :release "0.1.0-stage0"
      :source-compatible true
      :artifact-compatible true
      :diagnostic-compatible true
      :profile-availability-delta []
      :migration-artifacts []
      :signed-provenance :stage0-stdlib-provenance
      :status :complete}}))

(defn p16-standard-library-document-record
  [document]
  (let [summary (p16-standard-library-data-by-document document)]
    (merge
     {:document document
      :task-id (p16-task-id document)
      :governing-doc (:file summary)
      :suite-id (:owned-surface summary)
      :diagnostics (p16-standard-library-diagnostics-by-document document)
      :evidence (into {}
                      (map (fn [diagnostic]
                             [(keyword (str/lower-case diagnostic))
                              {:diagnostic diagnostic
                               :source :governing-document
                               :status :present}])
                           (p16-standard-library-diagnostics-by-document
                            document)))
      :standard-library
      {:accepted-fixture "bootstrap/clojure/fixtures/accepted/standard-library-phase16.gravity"
       :rejected-fixture (str "bootstrap/clojure/fixtures/rejected/"
                              (:rejected-fixture summary))
       :artifact-evidence :standard-library
       :validation-command "clojure -M:test"
       :status :complete}}
     (select-keys summary [:title :module :namespace :owned-surface
                           :accepted-behavior :rejected-diagnostic
                           :artifact-keys :dependencies :profiles]))))

(defn p16-standard-library-document-records
  []
  (into {} (map (fn [document]
                  [document (p16-standard-library-document-record document)])
                p16-standard-library-documents)))

(defn p16-accepted-standard-library-fixtures
  []
  (mapv (fn [document]
          (let [summary (p16-standard-library-data-by-document document)]
            {:document document
             :fixture "bootstrap/clojure/fixtures/accepted/standard-library-phase16.gravity"
             :artifact (:owned-surface summary)
             :evidence [(p16-task-id document) (:file summary)]
             :status :accepted}))
        p16-standard-library-documents))

(defn p16-rejected-standard-library-fixtures
  []
  (mapv (fn [document]
          (let [summary (p16-standard-library-data-by-document document)]
            {:document document
             :fixture (str "bootstrap/clojure/fixtures/rejected/"
                           (:rejected-fixture summary))
             :artifact :stable-standard-library-diagnostic
             :diagnostic (:rejected-diagnostic summary)
             :evidence [(p16-task-id document) (:file summary)]
             :status :rejected}))
        p16-standard-library-documents))

(defn p16-standard-library-evidence
  []
  (mapv (fn [document]
          (let [summary (p16-standard-library-data-by-document document)]
            {:document document
             :accepted-behavior (:accepted-behavior summary)
             :rejected-behavior (:rejected-diagnostic summary)
             :artifacts (:artifact-keys summary)
             :validation ["clojure -M:test"
                          "clojure -M:gravity standard-library bootstrap/clojure/fixtures/accepted/standard-library-phase16.gravity"]
             :status :complete}))
        p16-standard-library-documents))

(defn p16-standard-library-diagnostic-stream
  [source-path input-id]
  {:artifact :gravity/phase16-standard-library-diagnostic-stream
   :stage :standard-library
   :input-artifact input-id
   :diagnostics
   (mapv (fn [id index]
           (let [document (p16-standard-library-diagnostic-document id)]
             {:artifact :gravity/diagnostic
              :diagnostic-id (str "diag-" (str/lower-case id) "-stage0")
              :diagnostic id
              :rule id
              :severity :error
              :stage :standard-library
              :document-id document
              :task (when document (p16-task-id document))
              :primary {:span (source-span source-path index)
                        :syntax-id (str "p16-standard-library-syntax-"
                                        index)
                        :artifact input-id}
              :missing-fact (keyword (str/lower-case id))
              :remediation [{:kind :record-module-manifest}
                            {:kind :declare-profile-effect-capability}
                            {:kind :attach-safe-wrapper-audit}
                            {:kind :update-stability-policy}]
              :ordering-key [id :standard-library]}))
         p16-standard-library-diagnostic-ids
         (range))
   :status :complete})

(defn p16-present?
  [value]
  (if (coll? value)
    (seq value)
    (some? value)))

(defn p16-module-record
  [artifact document]
  (some #(when (= document (:document %)) %)
        (get-in artifact [:library-module-manifest :modules])))

(defn p16-standard-library-validate!
  [source-path artifact]
  (let [documents (:document-contracts artifact)
        accepted (:accepted-standard-library-fixtures artifact)
        rejected (:rejected-standard-library-fixtures artifact)
        standard-library (:standard-library-evidence artifact)
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:standard-library-diagnostic-stream
                                       :diagnostics])))]
    (when-not (= (set p16-standard-library-documents)
                 (set (:document-set artifact)))
      (p16-standard-library-fail! "P16-MANIFEST" source-path artifact
                                  {:missing-fields [:document-set]}))
    (doseq [artifact-key p16-standard-library-artifact-keys]
      (when-not (p16-present? (get artifact artifact-key))
        (p16-standard-library-fail! "P16-MANIFEST" source-path artifact
                                    {:missing-fields [artifact-key]}))
      (when-not (= :complete (:status (get artifact artifact-key)))
        (p16-standard-library-fail! "P16-MANIFEST" source-path
                                    (get artifact artifact-key)
                                    {:missing-fields [:status]})))
    (when-not (every? #(contains? documents %) p16-standard-library-documents)
      (p16-standard-library-fail! "P16-MANIFEST" source-path documents
                                  {:missing-fields [:document-contracts]}))
    (doseq [document p16-standard-library-documents
            :let [record (get documents document)
                  summary (p16-standard-library-data-by-document document)]]
      (doseq [field [:document :task-id :governing-doc :suite-id
                     :diagnostics :evidence :owned-surface
                     :accepted-behavior :rejected-diagnostic
                     :artifact-keys :standard-library]]
        (when-not (p16-present? (get record field))
          (p16-standard-library-fail! "P16-MANIFEST" source-path record
                                      {:missing-fields [field]})))
      (when-not (= (:owned-surface summary) (:owned-surface record))
        (p16-standard-library-fail! "P16-MANIFEST" source-path record
                                    {:missing-fields [:owned-surface]}))
      (doseq [diagnostic (p16-standard-library-diagnostics-by-document
                          document)]
        (when-not (and (contains? (set (:diagnostics record)) diagnostic)
                       (get-in record [:evidence
                                       (keyword (str/lower-case diagnostic))]))
          (p16-standard-library-fail!
           diagnostic source-path record
           {:missing-fields [(keyword (str/lower-case diagnostic))]})))
      (let [module-record (p16-module-record artifact document)]
        (when-not (true? (get-in module-record [:checks (:check-key summary)]))
          (p16-standard-library-fail!
           (:rejected-diagnostic summary) source-path module-record
           {:missing-fields [(:check-key summary)]}))))
    (when-not (= (set p16-standard-library-documents)
                 (set (map :document accepted)))
      (p16-standard-library-fail!
       "P16-ACCEPTED" source-path accepted
       {:missing-fields [:accepted-standard-library-fixtures]}))
    (when-not (= (set p16-standard-library-documents)
                 (set (map :document rejected)))
      (p16-standard-library-fail!
       "P16-REJECTED" source-path rejected
       {:missing-fields [:rejected-standard-library-fixtures]}))
    (when-not (= (set p16-standard-library-documents)
                 (set (map :document standard-library)))
      (p16-standard-library-fail!
       "P16-STDLIB" source-path standard-library
       {:missing-fields [:standard-library-evidence]}))
    (when-not (= 20 (:module-count (:library-module-manifest artifact)))
      (p16-standard-library-fail!
       "STD1001" source-path (:library-module-manifest artifact)
       {:missing-fields [:module-count]}))
    (when-not (true? (:profile-metadata-complete
                     (:library-module-manifest artifact)))
      (p16-standard-library-fail!
       "STD1001" source-path (:library-module-manifest artifact)
       {:missing-fields [:profile-metadata-complete]}))
    (when-not (p16-present? (:entries (:api-stability-record artifact)))
      (p16-standard-library-fail!
       "STD20001" source-path (:api-stability-record artifact)
       {:missing-fields [:entries]}))
    (when-not (p16-present? (:audit-records (:safe-wrapper-audit artifact)))
      (p16-standard-library-fail!
       "STD1005" source-path (:safe-wrapper-audit artifact)
       {:missing-fields [:audit-records]}))
    (when-not (= 20 (:accepted-count (:library-conformance-fixture artifact)))
      (p16-standard-library-fail!
       "P16-ACCEPTED" source-path (:library-conformance-fixture artifact)
       {:missing-fields [:accepted-count]}))
    (when-not (= 20 (:rejected-count (:library-conformance-fixture artifact)))
      (p16-standard-library-fail!
       "P16-REJECTED" source-path (:library-conformance-fixture artifact)
       {:missing-fields [:rejected-count]}))
    (when-not (= 20 (count (:rows (:profile-support-matrix artifact))))
      (p16-standard-library-fail!
       "P16-MANIFEST" source-path (:profile-support-matrix artifact)
       {:missing-fields [:rows]}))
    (when-not (true? (:diagnostic-compatible (:compatibility-report artifact)))
      (p16-standard-library-fail!
       "STD20004" source-path (:compatibility-report artifact)
       {:missing-fields [:diagnostic-compatible]}))
    (when-not (set/subset? (set p16-standard-library-diagnostic-ids)
                           diagnostics)
      (p16-standard-library-fail!
       "P16-MANIFEST" source-path
       (:standard-library-diagnostic-stream artifact)
       {:missing-fields [:diagnostics]})))
  :complete)

(defn p16-task-statuses
  []
  (merge (zipmap ["P16-T01" "P16-T02" "P16-T03"
                  "P16-T04" "P16-T05" "P16-T06"]
                 (repeat :complete))
         (zipmap (map p16-task-id p16-standard-library-documents)
                 (repeat :complete))))

(defn p16-standard-library-proof
  [artifact]
  (let [documents (:document-contracts artifact)
        accepted-docs (set (map :document
                                (:accepted-standard-library-fixtures
                                 artifact)))
        rejected-docs (set (map :document
                                (:rejected-standard-library-fixtures
                                 artifact)))
        standard-library-docs (set (map :document
                                        (:standard-library-evidence
                                         artifact)))
        diagnostics (set (map :diagnostic
                              (get-in artifact
                                      [:standard-library-diagnostic-stream
                                       :diagnostics])))]
    {:module-manifest-covered?
     (boolean
      (and (= 20 (:module-count (:library-module-manifest artifact)))
           (true? (:profile-metadata-complete
                   (:library-module-manifest artifact)))))
     :stability-record-covered?
     (boolean
      (and (p16-present? (:entries (:api-stability-record artifact)))
           (true? (:explicit-opt-in-required
                   (:api-stability-record artifact)))))
     :safe-wrapper-audit-covered?
     (boolean
      (p16-present? (:audit-records (:safe-wrapper-audit artifact))))
     :conformance-fixture-covered?
     (boolean
      (and (= 20 (:accepted-count (:library-conformance-fixture artifact)))
           (= 20 (:rejected-count (:library-conformance-fixture artifact)))))
     :profile-matrix-covered?
     (= 20 (count (:rows (:profile-support-matrix artifact))))
     :compatibility-covered?
     (boolean
      (and (true? (:source-compatible (:compatibility-report artifact)))
           (true? (:artifact-compatible (:compatibility-report artifact)))
           (true? (:diagnostic-compatible (:compatibility-report artifact)))))
     :document-coverage-complete?
     (= (set p16-standard-library-documents) (set (keys documents)))
     :accepted-fixtures-covered?
     (= (set p16-standard-library-documents) accepted-docs)
     :rejected-fixtures-covered?
     (= (set p16-standard-library-documents) rejected-docs)
     :standard-library-evidence-covered?
     (= (set p16-standard-library-documents) standard-library-docs)
     :diagnostics-covered?
     (set/subset? (set p16-standard-library-diagnostic-ids) diagnostics)
     :task-statuses (p16-task-statuses)
     :status :complete}))

(defn standard-library-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        source-overrides (p16-standard-library-source-overrides module)
        _ (p16-standard-library-validate-source-overrides!
           source-path source-overrides)
        input-id (c4-artifact-id {:source-path source-path
                                  :module (:module module)
                                  :task "P16-T01-T06"
                                  :documents p16-standard-library-documents})
        diagnostic-stream (p16-standard-library-diagnostic-stream
                           source-path input-id)
        standard-library-artifacts (p16-standard-library-artifact-values)
        artifact-base
        (merge
         {:kind :gravity/stage0-standard-library-artifact
          :phase "16"
          :task "P16-T01-T06"
          :document-set p16-standard-library-documents
          :governing-documents p16-standard-library-phase-governing-documents
          :pass {:name :phase16-standard-library
                 :input :ordinary-gravity-source
                 :output :standard-library
                 :requires p16-standard-library-artifact-keys
                 :preserves [:profile :target :effect :capability
                             :allocation :safety :stability
                             :diagnostic-code :source-spans
                             :artifact-provenance]
                 :emits [:document-contracts
                         :accepted-standard-library-fixtures
                         :rejected-standard-library-fixtures
                         :standard-library-evidence
                         :standard-library-diagnostic-stream]
                 :rejects p16-standard-library-diagnostic-ids}
          :source-overrides source-overrides
          :module (select-keys module [:module :source-path :profile :target
                                       :effects :capabilities :safety
                                       :metadata])
          :document-contracts (p16-standard-library-document-records)
          :accepted-standard-library-fixtures
          (p16-accepted-standard-library-fixtures)
          :rejected-standard-library-fixtures
          (p16-rejected-standard-library-fixtures)
          :standard-library-evidence (p16-standard-library-evidence)
          :standard-library-diagnostic-stream diagnostic-stream
          :standard-library-results
          {:documents p16-standard-library-documents
           :tasks (p16-task-statuses)
           :document-contracts 20
           :artifact-families (count p16-standard-library-artifact-keys)
           :accepted-fixtures 20
           :rejected-fixtures 20
           :standard-library-records 20
           :diagnostic-count (count p16-standard-library-diagnostic-ids)
           :status :complete}
          :diagnostics []}
         standard-library-artifacts)
        _ (p16-standard-library-validate! source-path artifact-base)
        capability-proof (p16-standard-library-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof capability-proof
           :artifact-id (c4-artifact-id (assoc artifact-base
                                               :capability-based-proof
                                               capability-proof)))))

(defn standard-library-file-artifact
  [path]
  (standard-library-source-artifact path (slurp path)))

(defn p17-gov-diagnostics
  [document]
  (let [number (Integer/parseInt (subs document 3))]
    (mapv #(format "GOV%d%03d" number %)
          (range 1 9))))

