          :risk :high
          :reason #{:emits-backend-artifacts}
          :affected-profiles #{:hosted :native}
          :minimum-evidence #{:backend-conformance
                              :differential-fixtures}
          :release-gate :required}]
        artifact
        {:kind :gravity/stage0-compiler-verification-artifact
         :document-set ["C15" "C16" "C17" "C18"]
         :pass {:name :compiler-diagnostics-and-verification
                :input :optimization-lowering-manifest
                :output :compiler-verification-report
                :requires [:diagnostic-schema :incremental-graph
                           :plugin-manifest :risk-classification
                           :translation-validation :trust-report]
                :preserves [:source-spans :generated-origins :profile
                            :target :diagnostics :proofs]
                :emits [:diagnostic-schema :diagnostic-stream
                        :diagnostic-catalog :golden-diagnostic-fixtures
                        :incremental-dependency-graph :cache-key-schema
                        :cache-entry-manifest :invalidation-trace
                        :artifact-reuse-report :revalidation-report
                        :plugin-manifest :plugin-execution-trace
                        :compiler-verification-plan :pass-risk-classification
                        :pass-evidence-records :translation-validation-log
                        :compiler-trust-report :release-gate-report]
                :rejects compiler-verification-diagnostic-ids}
         :source-overrides overrides
         :optimization-lowering-artifact-kind (:kind optimization-artifact)
         :optimization-lowering-artifact-hash input-id
         :diagnostic-schema diagnostic-schema
         :diagnostic-stream diagnostic-stream
         :diagnostic-catalog
         {:artifact :gravity/diagnostic-catalog
          :rules compiler-verification-diagnostic-ids
          :status :complete}
         :related-span-map
         {:artifact :gravity/related-span-map
          :status :complete
          :entries (get-in diagnostic-stream [:diagnostics 0 :related])}
         :remediation-and-quick-fix-records
         [{:rule "C15-GOLDEN"
           :remediation :update-golden-fixture
           :quick-fix :regenerate-fixture
           :status :available}]
         :redaction-report
         {:artifact :gravity/diagnostic-redaction-report
          :status :passed
          :redacted-values []
          :public-safe? true}
         :rendering-records
         [{:renderer :cli
           :source :gravity/diagnostic-stream
           :status :complete}
          {:renderer :ide
           :source :gravity/diagnostic-stream
           :status :complete}
          {:renderer :ci
           :source :gravity/diagnostic-stream
           :status :complete}]
         :golden-diagnostic-fixtures
         [{:fixture :compiler-verification-golden
           :rules ["C15-GOLDEN"]
           :status :matched}]
         :incremental-dependency-graph incremental-graph
         :cache-key-schema
         {:artifact :gravity/cache-key-schema
          :required-fields [:stage :source :compiler :profile :target
                            :pass-contract :dependencies :build-effects
                            :capabilities :policy]
          :status :complete}
         :cache-entry-manifest cache-entry
         :invalidation-trace
         [{:invalidating-input :diagnostic-schema-change
           :affected-nodes [:diagnostics :target-artifact]
           :revalidation-stages [:compiler-verify]
           :status :recorded}]
         :artifact-reuse-report
         {:artifact :gravity/artifact-reuse-report
          :status :revalidated
          :reuse :allowed-after-validation}
         :revalidation-report
         {:artifact :gravity/revalidation-report
          :status :passed
          :checks [:cache-key :schema-version :producer-pass
                   :proof-freshness :profile-target :diagnostic-schema]}
         :stale-proof-rejection-report
         {:artifact :gravity/stale-proof-rejection-report
          :status :covered
          :diagnostic "C16-PROOF"}
         :plugin-manifest plugin-manifest
         :api-compatibility-report
         {:artifact :gravity/plugin-api-compatibility
          :plugin (:plugin plugin-manifest)
          :status :compatible}
         :sandbox-grant
         {:artifact :gravity/plugin-sandbox-grant
          :plugin (:plugin plugin-manifest)
          :status :sandboxed
          :capabilities (:capabilities plugin-manifest)}
         :plugin-pass-registration-records
         [{:plugin (:plugin plugin-manifest)
           :pass :diagnostic-golden-check
           :contract :accepted
           :status :registered}]
         :plugin-execution-trace
         {:artifact :gravity/plugin-execution
          :plugin (:plugin plugin-manifest)
          :pass :diagnostic-golden-check
          :input input-id
          :output :gravity/diagnostic-stream
          :grants :gravity/plugin-sandbox-grant
          :build-effects []
          :diagnostics []
          :verifier-result :passed}
         :plugin-conformance-results
         {:artifact :gravity/plugin-conformance-results
          :status :passed
          :fixtures [:compiler-verification-fixtures]}
         :compiler-verification-plan
         {:artifact :gravity/compiler-verification-plan
          :status :complete
          :evidence-policy :risk-based}
         :pass-risk-classification risk-records
         :pass-evidence-records
         (mapv (fn [risk]
                 {:pass (:pass risk)
                  :risk (:risk risk)
                  :evidence (:minimum-evidence risk)
                  :status :present})
               risk-records)
         :translation-validation-logs
         [{:artifact :gravity/translation-validation
           :pass :bounds-check-elide
           :input input-id
           :output input-id
           :changed-functions [:stage0-main]
           :properties #{:same-observable-result :same-effects
                         :same-safety-outcomes}
           :method :symbolic-plus-fixtures
           :proofs [:proof/c13-bounds-check-elision]
           :counterexamples []
           :result :accepted}]
         :proof-or-certificate-references
         [{:proof :proof/c13-bounds-check-elision
           :status :accepted}
          {:certificate :cert/stage0-diagnostic-golden
           :status :accepted}]
         :differential-and-property-fixture-results
         {:artifact :gravity/compiler-fixture-results
          :status :passed
          :families [:front-end :optimization :backend]}
         :compiler-trust-report
         {:artifact :gravity/compiler-trust-report
          :compiler "gravity-stage0-clojure"
          :passes (mapv #(select-keys % [:pass :risk :minimum-evidence])
                        risk-records)
          :profiles {:hosted {:required-evidence :high
                              :blocked-passes []}}
          :known-gaps []
          :status :complete}
         :release-gate-report
         {:artifact :gravity/release-gate-report
          :status :passed
          :checks [:verifiers :critical-failures :high-risk-evidence
                   :target-lowering-conformance :stale-proof-rejection
                   :diagnostic-goldens]}
         :counterexample-artifacts
         [{:artifact :gravity/counterexample
           :status :none-produced
           :regression-fixture-created? false}]
         :diagnostics []}
        capability-proof
        {:diagnostic-schema-complete?
         (= :complete (get-in artifact [:diagnostic-schema :status]))
         :diagnostic-stream-deterministic?
         (= [:rule :primary :artifact]
            (get-in artifact [:diagnostic-stream :ordering-key]))
         :redaction-public-safe?
         (true? (get-in artifact [:redaction-report :public-safe?]))
         :golden-fixtures-matched?
         (every? #(= :matched (:status %))
                 (:golden-diagnostic-fixtures artifact))
         :incremental-records-complete?
         (and (= :consistent
                 (get-in artifact [:incremental-dependency-graph :status]))
              (= :complete (get-in artifact [:cache-key-schema :status]))
              (= :gravity/cache-entry
                 (get-in artifact [:cache-entry-manifest :artifact]))
              (= :passed (get-in artifact [:revalidation-report :status])))
         :plugin-policy-enforced?
         (and (= :accepted (get-in artifact [:plugin-manifest :status]))
              (= :compatible
                 (get-in artifact [:api-compatibility-report :status]))
              (= :sandboxed (get-in artifact [:sandbox-grant :status]))
              (= :passed
                 (get-in artifact [:plugin-conformance-results :status])))
         :verification-evidence-present?
         (and (every? #(= :present (:status %))
                      (:pass-evidence-records artifact))
              (every? #(= :accepted (:result %))
                      (:translation-validation-logs artifact)))
         :trust-report-complete?
         (= :complete (get-in artifact [:compiler-trust-report :status]))
         :release-gate-passed?
         (= :passed (get-in artifact [:release-gate-report :status]))
         :status :complete}
        conformance {:documents ["C15" "C16" "C17" "C18"]
                     :task "P06-T06"
                     :required-diagnostic-ids
                     compiler-verification-diagnostic-ids
                     :diagnostic-status :complete
                     :incremental-status :complete
                     :plugin-status :complete
                     :verification-status :complete
                     :status :complete}]
    (assoc artifact
           :capability-based-proof capability-proof
           :compiler-verification-results conformance)))

(defn defn-form?
  [form]
  (and (seq? form) (= 'defn (first form))))

(defn def-main-form?
  [form]
  (and (seq? form)
       (= 'def (first form))
       (= 'main (second form))
       (seq? (nth form 2 nil))
       (= 'fn (first (nth form 2)))))

(defn def-function-form?
  [form]
  (and (seq? form)
       (= 'def (first form))
       (symbol? (second form))
       (seq? (nth form 2 nil))
       (= 'fn (first (nth form 2)))))

(def stage0-special-forms
  '#{println do if let quote host-reflect})

(def stage0-builtin-functions
  '#{+ - * / = < > <= >= str pr-str hash-map vector list conj assoc get
     first second rest count})

