(def stage0-safe1-outcomes
  #{:proven-safe :runtime-checked :rejected :unsafe-island})

(def stage0-unsafe-required-metadata
  #{:reason :operation :owner :profiles :target :effects :capabilities
    :invariants :safe-boundary :review})

(declare eval-expr compile-source compile-stage0-expr
         execute-stage0-instruction execute-stage0-compiled-function)

(defn stage0-unsafe-forms
  [form]
  (cond
    (and (seq? form) (= 'quote (first form)))
    []

    (and (seq? form) (= 'unsafe (first form)))
    [form]

    (seq? form)
    (mapcat stage0-unsafe-forms form)

    (coll? form)
    (mapcat stage0-unsafe-forms form)

    :else
    []))

(defn validate-stage0-unsafe-island!
  [module form]
  (let [metadata (second form)
        source-path (:source-path module)
        safety-mode (:safety module)]
    (when (#{:safe :safe-optimized} safety-mode)
      (fail! "SAFE6-UNSAFE-FORBIDDEN"
             "unsafe islands are forbidden in this stage0 executable safety mode"
             {:source-span {:source source-path}
              :safety-mode safety-mode
              :safety-outcome :rejected
              :operator 'unsafe
              :remediation "Remove the unsafe island or move it behind an audited safe wrapper in a mode that permits unsafe islands."}))
    (when-not (map? metadata)
      (fail! "SAFE6-MISSING-METADATA"
             "unsafe island requires an audit metadata map"
             {:source-span {:source source-path}
              :safety-mode safety-mode
              :safety-outcome :rejected
              :operator 'unsafe
              :missing-fact :unsafe-audit-metadata
              :remediation "Attach SAFE6 metadata with owner, invariant, effects, capabilities, review policy, and safe boundary."}))
    (let [missing (seq (sort (set/difference stage0-unsafe-required-metadata
                                             (set (keys metadata)))))]
      (when missing
        (fail! "SAFE6-MISSING-METADATA"
               "unsafe island lacks required audit metadata"
               {:source-span {:source source-path}
                :safety-mode safety-mode
                :safety-outcome :rejected
                :operator 'unsafe
                :missing-fact (first missing)
                :remediation "Provide the full SAFE6 unsafe island audit record before compiling executable code."})))))

(defn validate-stage0-executable-safety!
  [module]
  (doseq [form (:forms module)
          unsafe-form (stage0-unsafe-forms form)]
    (validate-stage0-unsafe-island! module unsafe-form)))

(defn validate-stage0-source-safety!
  [source-path source-text]
  (let [records (read-source-form-records source-path source-text)
        forms (mapv :form records)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)]
    (validate-stage0-executable-safety! module)))

(defn validate-stage0-compiled-profile!
  [module]
  (let [source-path (:source-path module)
        writes? (some uses-println? (:forms module))]
    (when-not (= :hosted (:profile module))
      (fail! "P1-RUNTIME"
             "stage0 compiled execution requires the :hosted profile"
             {:source-span {:source source-path}
              :active-profile (:profile module)
              :target (:target module)
              :requested-runtime :clojure-stage0-jvm
              :policy-layer :profile
              :remediation "Use (:profile :hosted) for stage0 compiled executable modules or consume the output as an artifact boundary."}))
    (when (and writes? (not (contains? (:effects module) :io/write)))
      (fail! "P4-HOST-EFFECT"
             "hosted stdout requires the declared :io/write effect"
             {:source-span {:source source-path}
              :active-profile (:profile module)
              :target (:target module)
              :requested-effect :io/write
              :policy-layer :source
              :remediation "Add :io/write to the namespace effects before compiling the hosted executable."}))
    (when (and writes? (not (contains? (:capabilities module) :io/stdout)))
      (fail! "P4-HOST-CAPABILITY"
             "hosted stdout requires the :io/stdout capability"
             {:source-span {:source source-path}
              :active-profile (:profile module)
              :target (:target module)
              :requested-capability :io/stdout
              :policy-layer :source
              :remediation "Add :io/stdout to the namespace capabilities before compiling the hosted executable."}))))

(defn validate-stage0-source-profile!
  [source-path source-text]
  (let [records (read-source-form-records source-path source-text)
        forms (mapv :form records)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)]
    (validate-stage0-compiled-profile! module)))

(defn stage0-compiled-performance-manifest
  [module]
  {:profile (:profile module)
   :target (:target module)
   :source-effects (:effects module)
   :source-capabilities (:capabilities module)
   :metadata (:metadata module)})

(defn stage0-compiled-check-elision-proof-present?
  [record]
  (or (perf-present? (:proof-id record))
      (perf-present? (:proof record))
      (perf-present? (:certificate record))
      (perf-present? (:certificate-id record))
      (perf-present? (:dominating-proof record))))

(defn validate-stage0-compiled-check-elision!
  [module record]
  (let [source-path (:source-path module)
        erased? (or (true? (:erased? record))
                    (seq (:erased-checks record)))
        proof-present? (stage0-compiled-check-elision-proof-present?
                        record)]
    (when (and erased? (not proof-present?))
      (fail! "PERF10-PROOF-MISSING"
             "compiled performance metadata erases a check without proof"
             {:source-span {:source source-path}
              :profile (:profile module)
              :target (:target module)
              :check-class (:check-class record)
              :operation (:operation record)
              :ir-node (:ir-node record)
              :missing-proof :dominating-proof
              :pass-id :stage0-compiled-performance-gate
              :diagnostic-family :compiled-performance-validation
              :remediation "Keep the runtime check or attach a dominating proof and certificate before claiming check elision."}))))

(defn validate-stage0-compiled-performance!
  [module]
  (let [source-path (:source-path module)
        performance (get-in module [:metadata :performance] {})
        manifest (stage0-compiled-performance-manifest module)
        claim (:claim performance)]
    (when (map? claim)
      (perf1-validate-claim! source-path
                             manifest
                             performance
                             (perf1-normalize-claim claim)))
    (doseq [record (:check-elision performance)]
      (validate-stage0-compiled-check-elision! module record))))

(def stage0-numeric-builtin-functions
  '#{+ - * / = < > <= >=})

(defn stage0-floating-literal?
  [form]
  (or (instance? Float form)
      (instance? Double form)
      (instance? java.math.BigDecimal form)))

(defn stage0-floating-literals
  [form]
  (cond
    (stage0-floating-literal? form)
    [form]

    (and (seq? form) (= 'quote (first form)))
    []

    (seq? form)
    (mapcat stage0-floating-literals form)

    (coll? form)
    (mapcat stage0-floating-literals form)

    :else
    []))

(defn stage0-compiled-math-manifest
  [module]
  {:profile (:profile module)
   :target (:target module)
   :source-effects (:effects module)
   :source-capabilities (:capabilities module)
   :metadata (:metadata module)})

(defn stage0-compiled-math-suite-present?
  [module]
  (contains? (get-in module [:metadata :math] {}) :numeric))

(defn validate-stage0-compiled-floating-literals!
  [module manifest]
  (let [floating-literals (vec (stage0-floating-literals (:forms module)))
        floating-manifests (get-in module
                                   [:metadata :math :numeric
                                    :floating-manifests])]
    (when (and (seq floating-literals) (empty? floating-manifests))
      (numeric-fail! "MATH8-MANIFEST"
                     (:source-path module)
                     manifest
                     {:operation :stage0/floating-literal
                      :manifest-id :stage0/floating-manifest
                      :profile (:profile module)
                      :target (:target module)
                      :source-span {:source (:source-path module)}}
                     {:floating-literals floating-literals
                      :missing-fields [:floating-manifests]
                      :remediation "Attach a complete MATH8 floating manifest before compiling floating arithmetic through the stage0 executable path."}))))

(defn validate-stage0-compiled-math!
  [module]
  (let [manifest (stage0-compiled-math-manifest module)]
    (when (stage0-compiled-math-suite-present? module)
      (let [suite (numeric-mode-suite manifest)]
        (numeric-validate-math1! (:source-path module) manifest suite)
        (numeric-validate-math7! (:source-path module) manifest suite)
        (numeric-validate-math8! (:source-path module) manifest suite)))
    (validate-stage0-compiled-floating-literals! module manifest)))

(defn stage0-compiled-compiler-manifest
  [module]
  {:profile (:profile module)
   :target (:target module)
   :source-effects (:effects module)
   :source-capabilities (:capabilities module)
   :metadata (:metadata module)})

(defn stage0-compiled-compiler-suite
  [module]
  (get-in module [:metadata :compiler :compiled-gate] {}))

(defn stage0-compiled-compiler-suite-present?
  [module]
  (contains? (get-in module [:metadata :compiler] {}) :compiled-gate))

(defn validate-stage0-compiled-pass-contract!
  [module manifest contract]
  (let [source-path (:source-path module)
        missing-fields (compiler-pass-missing-fields
                        contract
                        compiler-pass-contract-required-fields)]
    (if (seq missing-fields)
      (compiler-pass-fail!
       "C1-PASS-CONTRACT" source-path manifest contract
       {:missing-fields missing-fields
        :remediation
        "Expose the compiled executable pass contract before claiming compiler architecture coverage."})
      (let [durable-drops (set/intersection compiler-pass-durable-facts
                                            (set (:invalidates contract)))
            replacements (set (concat (:regenerates contract)
                                      (:replacement-evidence contract)
                                      (:emits contract)))
            missing-replacements (set/difference durable-drops
                                                 replacements)]
        (when (seq missing-replacements)
          (compiler-pass-fail!
           "C1-EVIDENCE-DROP" source-path manifest contract
           {:missing-fields (vec missing-replacements)
            :remediation
            "Regenerate durable facts, emit replacement proof, keep runtime checks, or reject the transformation."}))))))

(defn validate-stage0-compiled-mir!
  [module manifest mir-operation]
  (when (= :target-specific (:family mir-operation))
    (mir-fail!
     "C11-TARGET-LEAK"
     (:source-path module)
     {:mir-module {:profile (:profile module)
                   :target-request (:target module)
                   :module :stage0-compiled-core-app}}
     mir-operation
     {:missing-fields [:target-independent-opcode]
      :remediation
      "Keep generic MIR target-independent; move target opcodes behind verified target lowering."})))

(defn stage0-compiled-target-proof-present?
  [record]
  (or (perf-present? (:proof-id record))
      (perf-present? (:proof record))
      (perf-present? (:certificate record))
      (perf-present? (:certificate-id record))
      (perf-present? (:translation-validation record))))

(defn validate-stage0-compiled-target-lowering!
  [module lowering]
  (let [source-path (:source-path module)
        backend (or (:backend lowering) (:target module))
        artifact {:lowering-request {:profile (:profile module)
                                     :target {:backend backend}}
                  :input (:input-artifact-id lowering)}
        subject (assoc lowering
                       :pass-id :stage0-compiled-target-lowering-gate
                       :source-span {:source source-path})]
    (when-not (and (contains? #{:verified-mir :verified-domain-ir}
                              (:input-kind lowering))
                   (true? (:verified? lowering)))
      (optimization-lowering-fail!
       "C14-INPUT" source-path artifact subject
       {:missing-fields [:verified-mir-or-domain-ir]
        :remediation
        "Target lowering must consume verified MIR or verified domain IR before backend artifacts are claimed."}))
    (when (and (seq (:target-metadata lowering))
               (not (stage0-compiled-target-proof-present? lowering)))
      (optimization-lowering-fail!
       "C14-PROOF-METADATA" source-path artifact subject
       {:missing-fields [:proof-id]
        :remediation
        "Attach proof or certificate metadata before preserving target-specific lowering facts."}))))

(defn validate-stage0-compiled-verification-risk!
  [module risk-record]
  (let [required (set (:minimum-evidence risk-record))
        available (set (:available-evidence risk-record))]
    (when (and (contains? #{:high :critical} (:risk risk-record))
               (not (set/subset? required available)))
      (c18-verification-fail!
       "C18-EVIDENCE" (:source-path module)
       {:stage :stage0-compiled-compiler-gate
        :pass-id (:pass risk-record)
        :version (or (:version risk-record) "stage0-p06-s1")
        :risk-class (:risk risk-record)
        :required-evidence required
        :available-evidence available
        :affected-profiles #{(:profile module)}
        :affected-targets #{(:target module)}
        :artifact-id (:artifact-id risk-record)}
       {:missing-fields
        (vec (sort-by name (set/difference required available)))}))))

(defn validate-stage0-compiled-compiler!
  [module]
  (when (stage0-compiled-compiler-suite-present? module)
    (let [manifest (stage0-compiled-compiler-manifest module)
          suite (stage0-compiled-compiler-suite module)]
      (doseq [contract (:pass-contracts suite)]
        (validate-stage0-compiled-pass-contract! module manifest contract))
      (doseq [mir-operation (:mir-operations suite)]
        (validate-stage0-compiled-mir! module manifest mir-operation))
      (doseq [lowering (:target-lowering suite)]
        (validate-stage0-compiled-target-lowering! module lowering))
      (doseq [risk-record (:verification-risk suite)]
        (validate-stage0-compiled-verification-risk! module risk-record)))))

(def stage0-compiled-jvm-manifest-required-fields
  [:backend :target :classfile :runtime :packaging :module-system
   :classloader-policy :reflection-policy :exception-policy
   :nullability-policy :runtime-provider :artifact-kind
   :source-debug-map])

(defn stage0-compiled-backend-suite
  [module]
  (get-in module [:metadata :backend :compiled-gate] {}))

(defn stage0-compiled-backend-suite-present?
  [module]
  (contains? (get-in module [:metadata :backend] {}) :compiled-gate))

(defn validate-stage0-compiled-backend-input!
  [module input-record]
  (when-not (contains? #{:verified-mir :verified-domain-ir}
                       (:input-kind input-record))
    (backend-interface-fail!
     "B1-INPUT" (:source-path module)
     {:stage :stage0-compiled-backend-gate
      :backend-id :gravity.backend/stage0-jvm-instruction-runner
      :input-artifact-id (:input-artifact-id input-record)
      :profile (:profile module)
      :target (:target module)
      :missing-evidence [:verified-mir-or-domain-ir]
      :fallback-status :development-only}
     {:missing-fields [:verified-mir-or-domain-ir]
      :remediation
      "A release or real backend claim must consume verified MIR or verified domain IR; the stage0 instruction plan is only a development backend artifact boundary."})))

(defn validate-stage0-compiled-jvm-manifest!
  [module manifest]
  (let [missing-fields (compiler-pass-missing-fields
                        manifest
                        stage0-compiled-jvm-manifest-required-fields)]
    (when (seq missing-fields)
      (hosted-lowering-fail!
       "B5-MANIFEST" (:source-path module)
       {:stage :stage0-compiled-jvm-backend-gate
        :backend :gravity.backend/jvm
        :target :jvm
        :artifact-id (:artifact-id manifest)
        :host-symbol :stage0-compiled-core-app
        :missing-evidence missing-fields}
       {:missing-fields missing-fields
        :remediation
        "A JVM backend artifact claim must record classfile/runtime/package/module, host boundary, source map, and manifest metadata."})))
  (doseq [flow (:null-flow manifest)]
    (when (and (not (true? (:checked? flow)))
               (not (contains? #{:option :result :opaque-checked}
                               (:wrapper flow))))
      (hosted-lowering-fail!
       "B5-NULL" (:source-path module)
       {:stage :stage0-compiled-jvm-backend-gate
        :backend :gravity.backend/jvm
        :target :jvm
        :artifact-id (:artifact-id manifest)
        :host-symbol (:host-symbol flow)
        :missing-evidence [:nullability-wrapper]
        :target-construct (:target-construct flow)}
       {:missing-fields [:nullability-wrapper]
        :remediation
        "Java null must cross into safe Gravity only through Option, Result, checked wrappers, or opaque checked host values."}))))

(defn stage0-compiled-artifact-provenance-complete?
  [artifact]
  (let [provenance (:provenance artifact)]
    (and (:source provenance)
         (:compiler provenance)
         (seq (:passes provenance))
         (:dependencies provenance))))

(defn validate-stage0-compiled-backend-artifact!
  [module artifact]
  (when-not (stage0-compiled-artifact-provenance-complete? artifact)
    (artifact-emission-fail!
     "B13-PROVENANCE" (:source-path module)
     {:stage :stage0-compiled-backend-artifact-emission
      :artifact-id (:artifact-id artifact)
      :artifact-kind (:artifact-kind artifact)
      :backend (:backend artifact)
      :profile (:profile module)
      :target (:target module)
      :missing-evidence [:source :compiler :passes :dependencies]}
     {:missing-fields [:provenance]
      :remediation
      "Compiled backend artifacts must preserve source, compiler, pass, generator, and dependency provenance."}))
  (when (true? (:release-grade? artifact))
    (artifact-emission-fail!
     "B13-RELEASE" (:source-path module)
     {:stage :stage0-compiled-backend-artifact-emission
      :artifact-id (:artifact-id artifact)
      :artifact-kind (:artifact-kind artifact)
      :backend (:backend artifact)
      :profile (:profile module)
      :target (:target module)
      :release-grade? true
      :missing-evidence [:verified-mir :target-lowering
                         :release-conformance-pack]}
     {:missing-fields [:release-grade-evidence]
      :remediation
      "The stage0 compiled backend artifact is development-only until verified MIR, target lowering, and release conformance evidence exist."})))

(defn validate-stage0-compiled-backend-conformance!
  [module conformance]
  (when-not (= :valid (:artifact-manifest-validation conformance))
    (backend-test-matrix-fail!
     "B14-ARTIFACT" (:source-path module)
     {:stage :stage0-compiled-backend-conformance
      :backend :gravity.backend/stage0-jvm-instruction-runner
      :target (:target module)
      :fixture-id (:fixture-id conformance)
      :artifact-id (:artifact-id conformance)
      :missing-metadata [:artifact-manifest-validation]}
     {:missing-fields [:artifact-manifest-validation]
      :remediation
      "Backend conformance evidence must validate the emitted artifact manifest and metadata preservation record."})))

(defn validate-stage0-compiled-backend!
  [module]
  (when (stage0-compiled-backend-suite-present? module)
    (let [suite (stage0-compiled-backend-suite module)]
      (doseq [input-record (:inputs suite)]
        (validate-stage0-compiled-backend-input! module input-record))
      (doseq [manifest (:jvm-manifests suite)]
        (validate-stage0-compiled-jvm-manifest! module manifest))
      (doseq [artifact (:artifacts suite)]
        (validate-stage0-compiled-backend-artifact! module artifact))
      (doseq [conformance (:conformance suite)]
        (validate-stage0-compiled-backend-conformance! module conformance)))))

(def stage0-compiled-managed-runtime-required-fields
  [:family :host-runtime :host-version :module-system :package-system
   :services :interop :collection-semantics :dynamic-state
   :exception-policy :nullability-policy :reflection-policy
   :interop-policy :source-debug-map :capability-enforcement
   :observability])

(defn stage0-compiled-runtime-suite
  [module]
  (get-in module [:metadata :runtime :compiled-gate] {}))

(defn stage0-compiled-runtime-suite-present?
  [module]
  (contains? (get-in module [:metadata :runtime] {}) :compiled-gate))

(defn validate-stage0-compiled-runtime-selection!
  [module selection]
  (let [source-path (:source-path module)
        required-missing (cond-> []
                           (not= :managed (:family selection))
                           (conj :family)
                           (not= :hosted (:profile selection))
                           (conj :profile)
                           (not= :jvm (:target selection))
                           (conj :target)
                           (not= :explicit (:selection-mode selection))
                           (conj :selection-mode))
        hidden-services (set (:hidden-services selection))
        used-forbidden-services (set/intersection
                                  (set (:used-services selection))
                                  (set (:forbidden selection)))]
    (when (seq required-missing)
      (runtime-selection-fail!
       "R1-SELECTION" source-path
       {:runtime-family (:family selection)
        :profile (:profile selection)
        :target (:target selection)
        :service-id :runtime-family-selection
        :artifact-id (:artifact-id selection)}
       {:missing-fields required-missing
        :remediation
        "Compiled hosted core runtime metadata must explicitly select the managed JVM runtime family for the :hosted profile before execution."}))
    (when (or (seq hidden-services)
              (seq used-forbidden-services))
      (runtime-selection-fail!
       "R1-FORBIDDEN" source-path
       {:runtime-family (:family selection)
        :profile (:profile selection)
        :target (:target selection)
        :service-id (or (first hidden-services)
                        (first used-forbidden-services)
                        :runtime-service)
        :artifact-id (:artifact-id selection)}
       {:hidden-services (vec (sort-by name hidden-services))
        :forbidden-services (vec (sort-by name used-forbidden-services))
        :missing-fields [:runtime-service-classification]
        :remediation
        "Compiled runtime services must be classified as linked, generated, delegated, external, or forbidden; hidden service dependencies are rejected."}))))

(defn validate-stage0-compiled-managed-runtime!
  [module managed-runtime]
  (let [source-path (:source-path module)
        missing-fields (compiler-pass-missing-fields
                        managed-runtime
                        stage0-compiled-managed-runtime-required-fields)]
    (when (seq missing-fields)
      (managed-runtime-fail!
       "R4-MANIFEST" source-path
       {:host-runtime (:host-runtime managed-runtime)
        :host-symbol :stage0-compiled-runtime
        :profile (:profile module)
        :target (:target module)}
       {:missing-fields missing-fields
        :remediation
        "Compiled hosted core runtime metadata must expose the managed host runtime manifest before execution."}))
    (doseq [flow (:null-flow managed-runtime)]
      (when (and (not (true? (:checked? flow)))
                 (not (contains? #{:option :result :opaque-foreign
                                   :opaque-checked}
                                 (:wrapper flow))))
        (managed-runtime-fail!
         "R4-NULL" source-path
         {:host-runtime (:host-runtime managed-runtime)
          :host-symbol (:host-symbol flow)
          :profile (:profile module)
          :target (:target module)}
         {:missing-fields [:checked-nullability-wrapper]
          :remediation
          "Managed host nulls must be checked or wrapped before they can enter safe Gravity runtime execution."})))))

(defn validate-stage0-compiled-runtime-capability!
  [module decision]
  (when-not (and (= :grant (:decision decision))
                 (:capability decision)
                 (:effect decision)
                 (:principal decision)
                 (:provider decision))
    (ai-repl-ffi-capability-fail!
     "R11-GRANT" (:source-path module)
     {:action-id (:action-id decision)
      :principal (:principal decision)
      :effect (:effect decision)
      :capability (:capability decision)
      :provider (:provider decision)
      :decision (:decision decision)
      :profile (:profile module)
      :target (:target module)}
     {:missing-fields [:matching-runtime-capability-grant]
      :remediation
      "A compiled runtime action may execute only when the effect, principal, provider, and capability decision produce an explicit grant."})))

(defn validate-stage0-compiled-runtime-observability!
  [module sink]
  (when (and (:sink sink)
             (not (true? (:sink-capability-granted? sink))))
    (runtime-observability-fail!
     "R12-SINK" (:source-path module)
     {:event-id (:event-id sink)
      :artifact-id (:artifact-id sink)
      :sink (:sink sink)
      :redaction-policy (:redaction-policy sink)
      :capability (:capability sink)
      :profile (:profile module)
      :target (:target module)}
     {:missing-fields [:observability-sink-capability]
      :remediation
      "Runtime observability sinks must be capability checked and redacted before compiled execution can emit events."})))

(defn validate-stage0-compiled-runtime!
  [module]
  (when (stage0-compiled-runtime-suite-present? module)
    (let [suite (stage0-compiled-runtime-suite module)]
      (doseq [selection (:selections suite)]
        (validate-stage0-compiled-runtime-selection! module selection))
      (doseq [managed-runtime (:managed-runtimes suite)]
        (validate-stage0-compiled-managed-runtime! module managed-runtime))
      (doseq [decision (:capability-decisions suite)]
        (validate-stage0-compiled-runtime-capability! module decision))
      (doseq [sink (:observability-sinks suite)]
        (validate-stage0-compiled-runtime-observability! module sink)))))

(def stage0-compiled-domain-slice-required-fields
  [:document-id :domain :slice-id :profile :target :effects :capabilities
   :artifacts :accepted-fixtures :rejected-fixtures :replacement-scope
   :conformance])

(defn stage0-compiled-domain-suite
  [module]
  (get-in module [:metadata :domain :compiled-gate] {}))

(defn stage0-compiled-domain-suite-present?
  [module]
  (contains? (get-in module [:metadata :domain] {}) :compiled-gate))

(defn validate-stage0-compiled-domain-slice!
  [module slice]
  (let [source-path (:source-path module)
        missing-fields (compiler-pass-missing-fields
                        slice
                        stage0-compiled-domain-slice-required-fields)
        document-id (:document-id slice)]
    (when (seq missing-fields)
      (p09-domain-fail!
       "P09-MANIFEST" source-path
       {:document-id document-id
        :domain (:domain slice)
        :profile (:profile slice)
        :target (:target slice)
        :artifact-id (:slice-id slice)
        :missing-fact (first missing-fields)}
       {:missing-fields missing-fields
        :remediation
        "Compiled domain claims must carry the complete slice packet before execution."}))
    (when (contains? #{:full-replacement :platform-wide :provider-replacement}
                     (get-in slice [:replacement-scope :claim-status]))
      (p09-domain-fail!
       "P09-CLAIM" source-path
       {:document-id document-id
        :domain (:domain slice)
        :profile (:profile slice)
        :target (:target slice)
        :artifact-id (:slice-id slice)
        :claim-id (get-in slice [:replacement-scope :claim-id])
        :missing-fact :slice-scoped-claim}
       {:missing-fields [:slice-scoped-claim]
        :remediation
        "Compiled domain metadata may only claim a fixture-backed slice, not a platform-wide or provider-wide replacement."}))
    (when-not (seq (:accepted-fixtures slice))
      (p09-domain-fail!
       "P09-ACCEPTED" source-path
       {:document-id document-id
        :domain (:domain slice)
        :profile (:profile slice)
        :target (:target slice)
        :artifact-id (:slice-id slice)
        :missing-fact :accepted-domain-fixture}
       {:missing-fields [:accepted-fixtures]
        :remediation
        "A compiled domain slice must name accepted fixture evidence for the claimed behavior."}))
    (when-not (seq (:rejected-fixtures slice))
      (p09-domain-fail!
       "P09-REJECTED" source-path
       {:document-id document-id
        :domain (:domain slice)
        :profile (:profile slice)
        :target (:target slice)
        :artifact-id (:slice-id slice)
        :missing-fact :rejected-domain-fixture}
       {:missing-fields [:rejected-fixtures]
        :remediation
        "A compiled domain slice must name rejected fixture evidence for illegal behavior."}))
    (when-not (= :complete (get-in slice [:conformance :status]))
      (p09-domain-fail!
       "P09-CONFORMANCE" source-path
       {:document-id document-id
        :domain (:domain slice)
        :profile (:profile slice)
        :target (:target slice)
        :artifact-id (:slice-id slice)
        :missing-fact :domain-conformance-evidence}
       {:missing-fields [:conformance]
        :remediation
        "A compiled domain slice must record conformance evidence before replacement claims can execute."}))
    (when (and (= "DOM17" document-id)
               (not (true? (:metadata-preserved? slice))))
      (p09-domain-fail!
       "DOM17-METADATA" source-path
       {:document-id document-id
        :domain (:domain slice)
        :profile (:profile slice)
        :target (:target slice)
        :artifact-id (:slice-id slice)
        :missing-fact :metadata_preservation}
       {:missing-fields [:metadata-preserved?]
        :remediation
        "Compiler/tooling domain slices must preserve type, effect, safety, capability, and source metadata."}))))

(defn validate-stage0-compiled-domain!
  [module]
  (when (stage0-compiled-domain-suite-present? module)
    (let [suite (stage0-compiled-domain-suite module)]
      (doseq [slice (:domain-slices suite)]
        (validate-stage0-compiled-domain-slice! module slice)))))

