(defn eval-do
  [module env forms]
  (reduce (fn [_ form] (eval-expr module env form)) nil forms))

(defn bind-let
  [module env bindings]
  (when-not (and (vector? bindings) (even? (count bindings)))
    (fail! "L2-LET-BINDING"
           "let requires an even binding vector"
           {:source-span {:source (:source-path module)}
            :bindings bindings
            :remediation "Use pairs of local names and expressions in let."}))
  (loop [env env
         pairs (partition 2 bindings)]
    (if-let [[name expr] (first pairs)]
      (do
        (when-not (symbol? name)
          (fail! "L2-LET-BINDING"
                 "let binding name must be a symbol"
                 {:source-span {:source (:source-path module)}
                  :binding name
                  :remediation "Bind symbols in stage0 let forms."}))
        (recur (assoc env name (eval-expr module env expr)) (rest pairs)))
      env)))

(defn function-definition-form
  [source-path form]
  (cond
    (defn-form? form)
    (let [[_ name params & body] form]
      {:name name :params params :body body :definition-form :defn})

    (def-function-form? form)
    (let [[_ params & body] (nth form 2)]
      {:name (second form) :params params :body body :definition-form :def-fn})

    :else nil))

(defn validate-function-definition!
  [source-path {:keys [name params body]}]
  (when-not (symbol? name)
    (fail! "L2-FUNCTION-PARAMS"
           "stage0 function name must be a symbol"
           {:source-span {:source source-path}
            :function name
            :remediation "Define functions with symbolic names."}))
  (when-not (and (vector? params) (every? symbol? params))
    (fail! "L2-FUNCTION-PARAMS"
           "stage0 function parameters must be a vector of symbols"
           {:source-span {:source source-path}
            :function name
            :params params
            :remediation "Use a fixed arity parameter vector such as [x y]."}))
  (when-not (seq body)
    (fail! "L2-FUNCTION-PARAMS"
           "stage0 function body cannot be empty"
           {:source-span {:source source-path}
            :function name
            :remediation "Add at least one body form."})))

(defn stage0-function-table
  [module]
  (let [source-path (:source-path module)
        definitions (keep #(function-definition-form source-path %)
                          (:forms module))
        duplicate (first (for [[name n] (frequencies (map :name definitions))
                               :when (> n 1)]
                           name))]
    (when duplicate
      (fail! "L2-DUPLICATE-FUNCTION"
             "stage0 executable has duplicate function definitions"
             {:source-span {:source source-path}
              :function duplicate
              :remediation "Keep one definition per stage0 function name."}))
    (into {}
          (map (fn [definition]
                 (validate-function-definition! source-path definition)
                 [(:name definition)
                  (assoc definition
                         :arity (count (:params definition))
                         :body-form-count (count (:body definition)))]))
          definitions)))

(defn fail-call-arity!
  [id module callee args expected]
  (fail! id
         (case id
           "L2-FUNCTION-ARITY" "stage0 function call has the wrong arity"
           "L2-BUILTIN-ARITY" "stage0 builtin call has the wrong arity"
           "stage0 call has the wrong arity")
         {:source-span {:source (:source-path module)}
          :function callee
          :expected-arity expected
          :actual-arity (count args)
          :remediation "Call the function with the arity supported by the stage0 hosted subset."}))

(defn assert-min-arity!
  [module callee args n]
  (when (< (count args) n)
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                      (str "at least " n))))

(defn assert-exact-arity!
  [module callee args n]
  (when-not (= n (count args))
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args n)))

(defn assert-between-arity!
  [module callee args min-n max-n]
  (when-not (<= min-n (count args) max-n)
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                      (str min-n " to " max-n))))

(defn assert-even-arity!
  [module callee args]
  (when (odd? (count args))
    (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                      "an even number of arguments")))

(defn invoke-stage0-builtin
  [module callee args]
  (try
    (case callee
      + (apply + args)
      - (do (assert-min-arity! module callee args 1)
            (apply - args))
      * (apply * args)
      / (do (assert-min-arity! module callee args 1)
            (apply / args))
      = (do (assert-min-arity! module callee args 1)
            (apply = args))
      < (do (assert-min-arity! module callee args 2)
            (apply < args))
      > (do (assert-min-arity! module callee args 2)
            (apply > args))
      <= (do (assert-min-arity! module callee args 2)
             (apply <= args))
      >= (do (assert-min-arity! module callee args 2)
             (apply >= args))
      str (apply str args)
      pr-str (apply pr-str args)
      hash-map (do (assert-even-arity! module callee args)
                   (apply hash-map args))
      vector (vec args)
      list (apply list args)
      conj (do (assert-min-arity! module callee args 1)
               (apply conj args))
      assoc (do
              (assert-min-arity! module callee args 3)
              (when (even? (count args))
                (fail-call-arity! "L2-BUILTIN-ARITY" module callee args
                                  "a collection followed by key/value pairs"))
              (apply assoc args))
      get (do (assert-between-arity! module callee args 2 3)
              (apply get args))
      first (do (assert-exact-arity! module callee args 1)
                (first (first args)))
      second (do (assert-exact-arity! module callee args 1)
                 (second (first args)))
      rest (do (assert-exact-arity! module callee args 1)
               (rest (first args)))
      count (do (assert-exact-arity! module callee args 1)
                (count (first args))))
    (catch clojure.lang.ExceptionInfo ex
      (throw ex))
    (catch Exception ex
      (fail! "L2-BUILTIN-ERROR"
             "stage0 builtin call failed"
             {:source-span {:source (:source-path module)}
              :function callee
              :cause-message (.getMessage ex)
              :remediation "Keep builtin inputs inside the checked stage0 core subset."}))))

(defn invoke-stage0-function
  [module callee args]
  (let [definition (get (:function-table module) callee)
        params (:params definition)]
    (when-not (= (count params) (count args))
      (fail-call-arity! "L2-FUNCTION-ARITY" module callee args
                        (count params)))
    (eval-do module (zipmap params args) (:body definition))))

(defn eval-collection
  [module env form]
  (cond
    (vector? form) (mapv #(eval-expr module env %) form)
    (map? form) (into {} (map (fn [[k v]]
                                [(eval-expr module env k)
                                 (eval-expr module env v)]))
                      form)
    (set? form) (set (map #(eval-expr module env %) form))
    :else form))

(defn eval-expr
  [module env form]
  (cond
    (symbol? form)
    (if (contains? env form)
      (get env form)
      (fail! "L2-UNKNOWN-SYMBOL"
             "stage0 cannot resolve symbol"
             {:source-span {:source (:source-path module)}
              :symbol form
              :remediation "Define the symbol or stay within the stage0 subset."}))

    (seq? form)
    (case (first form)
      println (do
                (validate-module-effects! module)
                (println (clojure.string/join " " (map #(str (eval-expr module env %)) (rest form)))))
      do (eval-do module env (rest form))
      if (let [[_ test then else] form]
           (if (eval-expr module env test)
             (eval-expr module env then)
             (eval-expr module env else)))
      let (let [[_ bindings & body] form]
            (eval-do module (bind-let module env bindings) body))
      quote (second form)
      host-reflect (fail! "P4-HOST-REFLECTION"
                          "host reflection is not implemented in stage0"
                          {:source-span {:source (:source-path module)}
                           :remediation "Remove host reflection from the stage0 executable subset."})
      (let [callee (first form)
            args (mapv #(eval-expr module env %) (rest form))]
        (cond
          (contains? stage0-builtin-functions callee)
          (invoke-stage0-builtin module callee args)

          (contains? (:function-table module) callee)
          (invoke-stage0-function module callee args)

          :else
          (fail! "L2-UNKNOWN-CORE-FORM"
                 "stage0 cannot execute this form"
                 {:source-span {:source (:source-path module)}
                  :operator callee
                  :remediation "Use defn, println, do, if, let, quote, supported core builtins, or local function calls in the stage0 hosted subset."}))))

    (or (vector? form) (map? form) (set? form))
    (eval-collection module env form)

    :else form))

(defn run-main
  [module]
  (let [function-table (stage0-function-table module)
        module (assoc module :function-table function-table)
        main-function (get function-table 'main)]
    (when-not main-function
      (fail! "L3-UNKNOWN-ALIAS"
             "stage0 executable requires a main function"
             {:source-span {:source (:source-path module)}
              :remediation "Add (defn main [] ...)."}))
    (let [params (:params main-function)
          body (:body main-function)]
      (when-not (empty? params)
        (fail! "L2-MAIN-ARITY"
               "stage0 main must take no arguments"
               {:source-span {:source (:source-path module)}
                :params params
                :remediation "Use (defn main [] ...)."}))
      (with-out-str
        (eval-do module {} body)))))

(defn compile-stage0-collection
  [module locals form]
  (cond
    (vector? form)
    {:op :vector-literal
     :items (mapv #(compile-stage0-expr module locals %) form)}

    (map? form)
    {:op :map-literal
     :entries (mapv (fn [[k v]]
                      {:key (compile-stage0-expr module locals k)
                       :value (compile-stage0-expr module locals v)})
                    (sort-by (fn [[k v]] (pr-str [k v])) form))}

    (set? form)
    {:op :set-literal
     :items (mapv #(compile-stage0-expr module locals %)
                  (sort-by pr-str form))}

    :else
    {:op :literal :value form}))

(defn compile-stage0-let
  [module locals bindings body]
  (when-not (and (vector? bindings) (even? (count bindings)))
    (fail! "L2-LET-BINDING"
           "let requires an even binding vector"
           {:source-span {:source (:source-path module)}
            :bindings bindings
            :remediation "Use pairs of local names and expressions in let."}))
  (loop [scope locals
         compiled []
         pairs (partition 2 bindings)]
    (if-let [[name expr] (first pairs)]
      (do
        (when-not (symbol? name)
          (fail! "L2-LET-BINDING"
                 "let binding name must be a symbol"
                 {:source-span {:source (:source-path module)}
                  :binding name
                  :remediation "Bind symbols in stage0 let forms."}))
        (recur (conj scope name)
               (conj compiled {:name name
                               :expr (compile-stage0-expr module scope expr)})
               (rest pairs)))
      {:op :let
       :bindings compiled
       :body (mapv #(compile-stage0-expr module scope %) body)})))

(defn compile-stage0-expr
  [module locals form]
  (cond
    (symbol? form)
    (if (contains? locals form)
      {:op :local :name form}
      (fail! "L2-UNKNOWN-SYMBOL"
             "stage0 cannot resolve symbol"
             {:source-span {:source (:source-path module)}
              :symbol form
              :remediation "Define the symbol or stay within the stage0 subset."}))

    (seq? form)
    (case (first form)
      println {:op :println
               :effect :io/write
               :capability :io/stdout
               :args (mapv #(compile-stage0-expr module locals %) (rest form))}
      do {:op :do
          :body (mapv #(compile-stage0-expr module locals %) (rest form))}
      if (let [[_ test then else] form]
           {:op :if
            :test (compile-stage0-expr module locals test)
            :then (compile-stage0-expr module locals then)
            :else (compile-stage0-expr module locals else)})
      let (let [[_ bindings & body] form]
            (compile-stage0-let module locals bindings body))
      quote {:op :quote :value (second form)}
      host-reflect (fail! "P4-HOST-REFLECTION"
                          "host reflection is not implemented in stage0"
                          {:source-span {:source (:source-path module)}
                           :remediation "Remove host reflection from the stage0 executable subset."})
      (let [callee (first form)
            args (mapv #(compile-stage0-expr module locals %) (rest form))]
        (cond
          (contains? stage0-builtin-functions callee)
          {:op :builtin-call :function callee :args args}

          (contains? (:function-table module) callee)
          {:op :function-call :function callee :args args}

          :else
          (fail! "L2-UNKNOWN-CORE-FORM"
                 "stage0 cannot execute this form"
                 {:source-span {:source (:source-path module)}
                  :operator callee
                  :remediation "Use defn, println, do, if, let, quote, supported core builtins, or local function calls in the stage0 hosted subset."}))))

    (or (vector? form) (map? form) (set? form))
    (compile-stage0-collection module locals form)

    :else
    {:op :literal :value form}))

(defn compile-stage0-function
  [module {:keys [name params body] :as definition}]
  (assoc definition
         :binding {:name name
                   :kind :function
                   :namespace (:module module)
                   :profile (:profile module)
                   :target (:target module)
                   :visibility (if (seq (:exports module))
                                 (if (contains? (set (:exports module)) name)
                                   :public
                                   :private)
                                 :stage0-local)
                   :effects (:effects module)
                   :capabilities (:capabilities module)}
         :instructions (mapv #(compile-stage0-expr module (set params) %) body)))

(defn stage0-instruction-summary
  [instruction]
  (let [children
        (case (:op instruction)
          :println (:args instruction)
          :do (:body instruction)
          :if [(:test instruction) (:then instruction) (:else instruction)]
          :let (concat (map :expr (:bindings instruction)) (:body instruction))
          :builtin-call (:args instruction)
          :function-call (:args instruction)
          :vector-literal (:items instruction)
          :set-literal (:items instruction)
          :map-literal (mapcat (fn [{:keys [key value]}] [key value])
                                (:entries instruction))
          [])]
    (merge {(:op instruction) 1}
           (apply merge-with +
                  (map stage0-instruction-summary
                       (remove nil? children))))))

(defn stage0-compiled-core-plan
  [source-path source-text module]
  (let [function-table (stage0-function-table module)
        module (assoc module :function-table function-table)
        _ (validate-stage0-compiled-profile! module)
        _ (executable-profile! source-path module (:forms module))
        _ (validate-module-effects! module)
        _ (validate-stage0-executable-safety! module)
        _ (validate-stage0-compiled-performance! module)
        _ (validate-stage0-compiled-math! module)
        _ (validate-stage0-compiled-compiler! module)
        _ (validate-stage0-compiled-backend! module)
        _ (validate-stage0-compiled-runtime! module)
        _ (validate-stage0-compiled-domain! module)
        _ (validate-stage0-compiled-schema! module)
        _ (validate-stage0-compiled-ai! module)
        _ (validate-stage0-compiled-package! module)
        _ (validate-stage0-compiled-tooling! module)
        _ (validate-stage0-compiled-conformance! module)
        functions (into (sorted-map)
                        (map (fn [[name definition]]
                               [name (compile-stage0-function
                                      module
                                      definition)]))
                        function-table)
        main-function (get functions 'main)
        _ (when-not main-function
            (fail! "L3-UNKNOWN-ALIAS"
                   "stage0 executable requires a main function"
                   {:source-span {:source source-path}
                    :remediation "Add (defn main [] ...)."}))
        _ (when-not (empty? (:params main-function))
            (fail! "L2-MAIN-ARITY"
                   "stage0 main must take no arguments"
                   {:source-span {:source source-path}
                    :params (:params main-function)
                    :remediation "Use (defn main [] ...)."}))
        instruction-summary (apply merge-with +
                                   (mapcat (fn [[_ function]]
                                             (map stage0-instruction-summary
                                                  (:instructions function)))
                                           functions))
        plan-base {:kind :gravity/stage0-hosted-core-compiled-plan
                   :entrypoint 'main
                   :source {:path source-path
                            :sha256 (str "sha256:" (sha256-hex source-text))}
                   :compiler {:owner :clojure-bootstrap
                              :stage :stage0
                              :input :macro-expanded-core
                              :output :instruction-plan
                              :retirement-objective
                              :replace-with-gravity-self-hosted-compiler}
                   :module (select-keys module
                                        [:module :source-path :profile :target
                                         :effects :capabilities :exports
                                         :safety])
                   :binding-table (mapv (fn [[name function]]
                                           (assoc (:binding function)
                                                  :arity (:arity function)))
                                         (sort-by key functions))
                   :functions functions
                   :instruction-summary instruction-summary
                   :effect-summary {:declared (:effects module)
                                    :inferred (if (pos? (get instruction-summary
                                                             :println
                                                             0))
                                                #{:io/write}
                                                #{})
                                    :capabilities (:capabilities module)}
                   :diagnostics []}]
    (assoc plan-base
           :plan-id (str "sha256:" (sha256-hex (pr-str plan-base))))))

(defn execute-stage0-instructions
  [plan env instructions]
  (reduce (fn [_ instruction]
            (execute-stage0-instruction plan env instruction))
          nil
          instructions))

(defn execute-stage0-instruction
  [plan env instruction]
  (case (:op instruction)
    :literal (:value instruction)
    :quote (:value instruction)
    :local (if (contains? env (:name instruction))
             (get env (:name instruction))
             (fail! "L2-UNKNOWN-SYMBOL"
                    "stage0 compiled plan cannot resolve local"
                    {:source-span {:source (get-in plan [:source :path])}
                     :symbol (:name instruction)
                     :remediation "Regenerate the compiled plan from a valid stage0 source module."}))
    :vector-literal (mapv #(execute-stage0-instruction plan env %)
                          (:items instruction))
    :set-literal (set (map #(execute-stage0-instruction plan env %)
                           (:items instruction)))
    :map-literal (into {}
                       (map (fn [{:keys [key value]}]
                              [(execute-stage0-instruction plan env key)
                               (execute-stage0-instruction plan env value)]))
                       (:entries instruction))
    :println (let [module (:module plan)
                   args (mapv #(execute-stage0-instruction plan env %)
                              (:args instruction))]
               (validate-module-effects! module)
               (println (clojure.string/join " " (map str args))))
    :do (execute-stage0-instructions plan env (:body instruction))
    :if (if (execute-stage0-instruction plan env (:test instruction))
          (execute-stage0-instruction plan env (:then instruction))
          (execute-stage0-instruction plan env (:else instruction)))
    :let (loop [env env
                bindings (:bindings instruction)]
           (if-let [{:keys [name expr]} (first bindings)]
             (recur (assoc env name
                           (execute-stage0-instruction plan env expr))
                    (rest bindings))
             (execute-stage0-instructions plan env (:body instruction))))
    :builtin-call (let [module (:module plan)
                        args (mapv #(execute-stage0-instruction plan env %)
                                   (:args instruction))]
                    (invoke-stage0-builtin module (:function instruction) args))
    :function-call (let [args (mapv #(execute-stage0-instruction plan env %)
                                    (:args instruction))]
                     (execute-stage0-compiled-function
                      plan
                      (:function instruction)
                      args))
    (fail! "L2-UNKNOWN-CORE-FORM"
           "stage0 compiled plan contains an unknown instruction"
           {:source-span {:source (get-in plan [:source :path])}
            :operator (:op instruction)
            :remediation "Regenerate the compiled plan with a supported stage0 compiler."})))

(defn execute-stage0-compiled-function
  [plan callee args]
  (let [definition (get-in plan [:functions callee])
        params (:params definition)]
    (when-not definition
      (fail! "L2-UNKNOWN-CORE-FORM"
             "stage0 compiled plan references an unknown function"
             {:source-span {:source (get-in plan [:source :path])}
              :function callee
              :remediation "Regenerate the compiled plan from source."}))
    (when-not (= (count params) (count args))
      (fail-call-arity! "L2-FUNCTION-ARITY"
                        (:module plan)
                        callee
                        args
                        (count params)))
    (execute-stage0-instructions plan (zipmap params args)
                                 (:instructions definition))))

(defn execute-stage0-compiled-plan
  [plan]
  (let [main-function (get-in plan [:functions (:entrypoint plan)])
        params (:params main-function)]
    (when-not main-function
      (fail! "L3-UNKNOWN-ALIAS"
             "stage0 compiled plan requires a main function"
             {:source-span {:source (get-in plan [:source :path])}
              :remediation "Regenerate the compiled plan from a module with main."}))
    (when-not (empty? params)
      (fail! "L2-MAIN-ARITY"
             "stage0 compiled main must take no arguments"
             {:source-span {:source (get-in plan [:source :path])}
              :params params
              :remediation "Use (defn main [] ...)."}))
    (with-out-str
      (execute-stage0-instructions plan {} (:instructions main-function)))))

(defn stage0-compiled-plan-safety-report
  [plan]
  (let [summary (:instruction-summary plan)
        source-path (get-in plan [:source :path])
        operation-records
        (vec
         (concat
          (when (pos? (get summary :function-call 0))
            [{:operation :stage0/function-call
              :outcome :runtime-checked
              :condition :fixed-arity
              :failure "L2-FUNCTION-ARITY"
              :source-span {:source source-path}
              :profile (get-in plan [:module :profile])}])
          (when (pos? (get summary :builtin-call 0))
            [{:operation :stage0/builtin-call
              :outcome :runtime-checked
              :condition :builtin-arity
              :failure "L2-BUILTIN-ARITY"
              :source-span {:source source-path}
              :profile (get-in plan [:module :profile])}])
          (when (pos? (get summary :println 0))
            [{:operation :stage0/io-write
              :outcome :proven-safe
              :condition :declared-effect-and-capability
              :effect :io/write
              :capability :io/stdout
              :source-span {:source source-path}
              :profile (get-in plan [:module :profile])}])
          [{:operation :stage0/control-flow
            :outcome :proven-safe
            :condition :compiled-instruction-plan
            :forms (select-keys summary [:do :if :let :quote])
            :source-span {:source source-path}
            :profile (get-in plan [:module :profile])}
           {:operation :stage0/literals-and-locals
            :outcome :proven-safe
            :condition :closed-compiled-plan
            :forms (select-keys summary
                                [:literal :local :vector-literal
                                 :map-literal :set-literal])
            :source-span {:source source-path}
            :profile (get-in plan [:module :profile])}]))
        report-base
        {:kind :gravity/stage0-hosted-core-compiled-safety-report
         :document "SAFE1"
         :governing-documents ["D8" "D9" "SAFE1" "SAFE6"]
         :compiled-plan-id (:plan-id plan)
         :module (:module plan)
         :safety-mode (get-in plan [:module :safety])
         :safety-outcomes stage0-safe1-outcomes
         :safety-classification-records operation-records
         :runtime-checks (filterv #(= :runtime-checked (:outcome %))
                                  operation-records)
         :unsafe-islands []
         :unsafe-policy {:mode (get-in plan [:module :safety])
                         :unsafe-islands-allowed? false}
         :diagnostics []}]
    (assoc report-base
           :report-id (str "sha256:" (sha256-hex (pr-str report-base))))))

(defn hosted-core-compiled-safety-proof-source-artifact
  [source-path source-text]
  (let [_ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        compiled-plan (stage0-compiled-core-plan source-path source-text module)
        run-output (execute-stage0-compiled-plan compiled-plan)
        safety-report (stage0-compiled-plan-safety-report compiled-plan)
        outcomes (map :outcome (:safety-classification-records safety-report))
        proof {:compiled-plan-safety-classified? true
               :exactly-one-outcome-per-operation?
               (and (seq outcomes)
                    (every? stage0-safe1-outcomes outcomes)
                    (= (count outcomes)
                       (count (:safety-classification-records
                               safety-report))))
               :runtime-checks-recorded?
               (set/subset? #{:stage0/function-call :stage0/builtin-call}
                            (set (map :operation
                                      (:runtime-checks safety-report))))
               :unsafe-islands-rejected? true
               :unsafe-audit-metadata-required? true
               :compiled-plan-executed? (= "core-app\ngravity:19:2\n(:ok 19)\n"
                                          run-output)
               :rejected-diagnostics-covered?
               (= #{"SAFE6-UNSAFE-FORBIDDEN" "SAFE6-MISSING-METADATA"}
                  (set (map :diagnostic
                            stage0-compiled-safety-rejected-fixtures)))
               :limitations {:clojure-instruction-runner? true
                             :self-hosted-compiler? false
                             :native-backend? false
                             :unsafe-island-execution? false
                             :next-required-capability
                             :lower-safety-report-into-runtime-and-mir-artifacts}
               :status :complete}
        artifact-base
        {:kind :gravity/stage0-hosted-core-compiled-safety-proof
         :phase "02"
         :task "P02-S1"
         :governing-documents ["D8" "D9" "SAFE1" "SAFE6"]
         :source {:path source-path
                  :sha256 (str "sha256:" (sha256-hex source-text))}
         :compiled-plan (select-keys compiled-plan
                                     [:kind :plan-id :entrypoint
                                      :instruction-summary :effect-summary])
         :safety-report (select-keys safety-report
                                     [:kind :report-id :document
                                      :safety-mode
                                      :safety-classification-records
                                      :runtime-checks :unsafe-islands
                                      :unsafe-policy :diagnostics])
         :accepted-run {:command (str "clojure -M:gravity run-compiled "
                                      source-path)
                        :stdout run-output}
         :rejected-fixtures stage0-compiled-safety-rejected-fixtures
         :trusted-boundary {:compiler :clojure/jvm
                            :runtime :clojure/jvm
                            :instruction-plan? true
                            :clojure-instruction-runner? true
                            :self-hosted-compiler? false}
         :capability-based-proof proof}]
    (assoc artifact-base
           :artifact-id (str "sha256:" (sha256-hex (pr-str artifact-base))))))

(defn hosted-core-compiled-safety-proof-file-artifact
  [path]
  (hosted-core-compiled-safety-proof-source-artifact path (slurp path)))

(defn stage0-compiled-plan-profile-report
  [plan]
  (let [module (:module plan)
        inferred-effects (get-in plan [:effect-summary :inferred] #{})
        required-capabilities (set/union
                               (get-in plan [:effect-summary :capabilities] #{})
                               (required-capabilities-for-effects
                                inferred-effects))
        effect-authority (profile-effective-effects module inferred-effects)
        capability-authority (profile-effective-capabilities
                              module
                              required-capabilities)
        effect-table (effect-permission-table module inferred-effects
                                              effect-authority)
        capability-table (capability-permission-table
                          module
                          required-capabilities
                          capability-authority)
        contract (profile-contract (:profile module))
        manifest {:module (:module module)
                  :source-path (:source-path module)
                  :profile (:profile module)
                  :target (:target module)
                  :source-effects (:source effect-authority)
                  :inferred-effects inferred-effects
                  :effective-effects (:effective effect-authority)
                  :source-capabilities (:source capability-authority)
                  :required-capabilities required-capabilities
                  :effective-capabilities (:effective capability-authority)
                  :memory-regime (:memory contract)
                  :runtime-assumptions (:runtime contract)
                  :unsafe-policy (:unsafe-policy contract)
                  :dependencies {:module (:module module)
                                 :dependencies []
                                 :acyclic true}
                  :provider-selections []
                  :safety (:safety module)
                  :policy-layers {:effects (select-keys
                                             effect-authority
                                             [:source :profile :package
                                              :provider :deployment])
                                  :capabilities (select-keys
                                                 capability-authority
                                                 [:source :profile :package
                                                  :provider :deployment])}}
        backend-report (backend-eligibility-report
                        module
                        (assoc manifest :profile-contract contract))
        report-base
        {:kind :gravity/stage0-hosted-core-compiled-profile-report
         :document-set ["P1" "P4" "P13"]
         :compiled-plan-id (:plan-id plan)
         :profile-contract (select-keys contract
                                        [:profile :allowed-effects
                                         :checked-effects :capabilities
                                         :memory :runtime :unsafe-policy])
         :profile-manifest manifest
         :effect-permission-table effect-table
         :capability-permission-table capability-table
         :cross-profile-dependency-graph (:dependencies manifest)
         :backend-eligibility-report backend-report
         :behavior-states {:effects (set (map :state effect-table))
                           :capabilities (set (map :state
                                                   capability-table))}
         :diagnostics []}]
    (assoc report-base
           :report-id (str "sha256:" (sha256-hex (pr-str report-base))))))

(defn hosted-core-compiled-profile-proof-source-artifact
  [source-path source-text]
  (let [_ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        compiled-plan (stage0-compiled-core-plan source-path source-text module)
        run-output (execute-stage0-compiled-plan compiled-plan)
        profile-report (stage0-compiled-plan-profile-report compiled-plan)
        manifest (:profile-manifest profile-report)
        proof {:compiled-profile-validated? true
               :active-profile-hosted? (= :hosted (:profile manifest))
               :target-jvm? (= :jvm (:target manifest))
               :effective-effects-covered?
               (contains? (:effective-effects manifest) :io/write)
               :effective-capabilities-covered?
               (contains? (:effective-capabilities manifest) :io/stdout)
               :backend-eligibility-recorded?
               (true? (get-in profile-report
                              [:backend-eligibility-report :eligible?]))
               :cross-profile-graph-recorded?
               (= [] (get-in profile-report
                             [:cross-profile-dependency-graph
                              :dependencies]))
               :compiled-plan-executed? (= "core-app\ngravity:19:2\n(:ok 19)\n"
                                          run-output)
               :rejected-diagnostics-covered?
               (= #{"P4-HOST-EFFECT" "P4-HOST-CAPABILITY" "P1-RUNTIME"}
                  (set (map :diagnostic
                            stage0-compiled-profile-rejected-fixtures)))
               :limitations {:clojure-instruction-runner? true
                             :self-hosted-compiler? false
                             :native-backend? false
                             :next-required-capability
                             :lower-profile-manifest-into-mir-runtime-and-package-artifacts}
               :status :complete}
        artifact-base
        {:kind :gravity/stage0-hosted-core-compiled-profile-proof
         :phase "03"
         :task "P03-S1"
         :governing-documents ["P1" "P4" "P13"]
         :source {:path source-path
                  :sha256 (str "sha256:" (sha256-hex source-text))}
         :compiled-plan (select-keys compiled-plan
                                     [:kind :plan-id :entrypoint
                                      :instruction-summary :effect-summary])
         :profile-report (select-keys profile-report
                                      [:kind :report-id :document-set
                                       :profile-manifest
                                       :effect-permission-table
                                       :capability-permission-table
                                       :cross-profile-dependency-graph
                                       :backend-eligibility-report
                                       :behavior-states :diagnostics])
         :accepted-run {:command (str "clojure -M:gravity run-compiled "
                                      source-path)
                        :stdout run-output}
         :rejected-fixtures stage0-compiled-profile-rejected-fixtures
         :trusted-boundary {:compiler :clojure/jvm
                            :runtime :clojure/jvm
                            :instruction-plan? true
                            :clojure-instruction-runner? true
                            :self-hosted-compiler? false}
         :capability-based-proof proof}]
    (assoc artifact-base
           :artifact-id (str "sha256:" (sha256-hex (pr-str artifact-base))))))

(defn hosted-core-compiled-profile-proof-file-artifact
  [path]
  (hosted-core-compiled-profile-proof-source-artifact path (slurp path)))

(defn stage0-compiled-plan-performance-report
  [plan]
  (let [module (:module plan)
        performance (get-in module [:metadata :performance] {})
        claim (when (map? (:claim performance))
                (perf1-normalize-claim (:claim performance)))
        claim-present? (some? claim)
        instruction-summary (:instruction-summary plan)
        residual-checks (cond-> #{}
                          (pos? (get instruction-summary :function-call 0))
                          (conj :function-arity)
                          (pos? (get instruction-summary :builtin-call 0))
                          (conj :builtin-arity))
        erased-checks (set (mapcat #(or (:erased-checks %)
                                        (when (:erased? %)
                                          [(:check-class %)]))
                                   (get-in module
                                           [:metadata :performance
                                            :check-elision]
                                           [])))
        target-fingerprint (when claim-present?
                             (perf1-target-fingerprint claim))
        contract {:claim-status (if claim-present? :recorded :not-asserted)
                  :claim-id (:claim-id claim)
                  :profile (:profile module)
                  :stage0-source-target (:target module)
                  :target-request (or (:target claim) :clojure-stage0-jvm)
                  :target-features (or (:target-features claim)
                                       #{:clojure-jvm
                                         :stage0-instruction-plan})
                  :safety-mode (or (:safety-mode claim) (:safety module))
                  :optimization-mode :none
                  :reason :stage0-records-baseline-only}
        decision {:pass :stage0-compiled-performance-gate
                  :decision :retain-safe-semantics
                  :erased-checks erased-checks
                  :residual-checks residual-checks
                  :preserves #{:source-semantics :profile :effects
                               :capabilities :safety-outcomes
                               :diagnostics}
                  :status :complete}
        report-base
        {:kind :gravity/stage0-hosted-core-compiled-performance-report
         :document-set ["D6" "PERF1" "PERF10"]
         :compiled-plan-id (:plan-id plan)
         :performance-contract-manifest contract
         :optimization-decision-log
         (vec (conj (vec (:optimization-decisions performance))
                    decision))
         :target-feature-report
         {:target (:target-request contract)
          :features (:target-features contract)
          :fingerprint (or target-fingerprint
                           {:runtime :clojure-stage0
                            :executor :instruction-plan
                            :claim :not-asserted})
          :status (if claim-present? :recorded :baseline)}
         :layout-input-shape-record
         {:input-shape (or (:input-shape claim)
                           {:entrypoint (:entrypoint plan)
                            :arguments 0})
          :layout (or (:layout claim)
                      {:instruction-plan :linear-vector
                       :values :clojure-hosted})
          :status (if claim-present? :recorded :baseline)}
         :benchmark-report
         (or (:benchmark claim)
             {:harness :not-run
              :reason :no-performance-claim
              :status :not-asserted})
         :check-elision-report
         {:erased-checks erased-checks
          :residual-checks residual-checks
          :policy-checks-preserved? true
          :certificate-required? (seq erased-checks)
          :status (if (empty? erased-checks)
                    :no-checks-elided
                    :certificate-backed)}
         :performance-conformance-results
         {:document-set ["D6" "PERF1" "PERF10"]
          :task "P04-S1"
          :performance-claim-status (if claim-present?
                                      :recorded
                                      :not-asserted)
          :check-elision-status (if (empty? erased-checks)
                                  :no-checks-elided
                                  :certificate-backed)
          :required-diagnostic-ids ["PERF1-CLAIM" "PERF1-TARGET"
                                    "PERF10-PROOF-MISSING"]
          :status :complete}
         :diagnostics []}]
    (assoc report-base
           :report-id (str "sha256:" (sha256-hex (pr-str report-base))))))

(defn hosted-core-compiled-performance-proof-source-artifact
  [source-path source-text]
  (let [_ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        compiled-plan (stage0-compiled-core-plan source-path source-text
                                                 module)
        run-output (execute-stage0-compiled-plan compiled-plan)
        performance-report (stage0-compiled-plan-performance-report
                            compiled-plan)
        elision-report (:check-elision-report performance-report)
        proof {:compiled-performance-validated? true
               :baseline-performance-recorded?
               (= :not-asserted
                  (get-in performance-report
                          [:performance-contract-manifest
                           :claim-status]))
               :optimization-decisions-preserve-semantics?
               (every? #(contains? (:preserves %) :source-semantics)
                       (:optimization-decision-log performance-report))
               :effects-and-capabilities-preserved?
               (every? #(and (contains? (:preserves %) :effects)
                             (contains? (:preserves %) :capabilities))
                       (:optimization-decision-log performance-report))
               :safety-checks-not-elided-without-proof?
               (empty? (:erased-checks elision-report))
               :residual-runtime-checks-recorded?
               (set/subset? #{:function-arity :builtin-arity}
                            (:residual-checks elision-report))
               :compiled-plan-executed? (= "core-app\ngravity:19:2\n(:ok 19)\n"
                                          run-output)
               :rejected-diagnostics-covered?
               (= #{"PERF1-CLAIM" "PERF1-TARGET"
                    "PERF10-PROOF-MISSING"}
                  (set (map :diagnostic
                            stage0-compiled-performance-rejected-fixtures)))
               :limitations {:clojure-instruction-runner? true
                             :self-hosted-compiler? false
                             :native-backend? false
                             :performance-claim-accepted? false
                             :next-required-capability
                             :compile-real-mir-performance-artifacts-before-accepting-throughput-claims}
               :status :complete}
        artifact-base
        {:kind :gravity/stage0-hosted-core-compiled-performance-proof
         :phase "04"
         :task "P04-S1"
         :governing-documents ["D6" "PERF1" "PERF10"]
         :source {:path source-path
                  :sha256 (str "sha256:" (sha256-hex source-text))}
         :compiled-plan (select-keys compiled-plan
                                     [:kind :plan-id :entrypoint
                                      :instruction-summary :effect-summary])
         :performance-report (select-keys performance-report
                                          [:kind :report-id :document-set
                                           :performance-contract-manifest
                                           :optimization-decision-log
                                           :target-feature-report
                                           :layout-input-shape-record
                                           :benchmark-report
                                           :check-elision-report
                                           :performance-conformance-results
                                           :diagnostics])
         :accepted-run {:command (str "clojure -M:gravity run-compiled "
                                      source-path)
                        :stdout run-output}
         :rejected-fixtures stage0-compiled-performance-rejected-fixtures
         :trusted-boundary {:compiler :clojure/jvm
                            :runtime :clojure/jvm
                            :instruction-plan? true
                            :clojure-instruction-runner? true
