  (hosted-core-compiled-app-proof-source-artifact path (slurp path)))

(def p15-s23-stage2-plan-emitter-required-preserves
  #{:source-spans :diagnostic-codes :function-bindings
    :instruction-semantics :effects :capabilities :profile
    :compiler-lineage :artifact-provenance})

(def p15-s23-stage2-plan-emitter-required-emits
  #{:stage2-instruction-plan :stage2-plan-execution-record
    :accepted-output-comparison :rejected-diagnostic-comparison
    :stage2-emitter-boundary-record})

(def p15-s23-stage2-plan-emitter-required-special-forms
  '#{println do if let quote host-reflect})

(def p15-s23-stage2-plan-emitter-diagnostic-messages
  {"P15S23Q001" "P15-S23 stage2 plan emitter contract is missing"
   "P15S23Q002" "P15-S23 stage2 plan emitter rule set is incomplete"
   "P15S23Q003" "P15-S23 stage2 plan emitter accepted plan or output is not equivalent"
   "P15S23Q004" "P15-S23 stage2 plan emitter rejected diagnostics are not preserved"
   "P15S23Q005" "P15-S23 stage2 plan emitter evidence links are incomplete"
   "P15S23Q006" "P15-S23 stage2 plan emitter preservation or emission contract is incomplete"
   "P15S23Q007" "P15-S23 stage2 plan emitter residual boundary record is incomplete"
   "P15S23Q008" "P15-S23 stage2 plan emitter makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-plan-emitter-diagnostic-ids
  ["P15S23Q001" "P15S23Q002" "P15S23Q003" "P15S23Q004"
   "P15S23Q005" "P15S23Q006" "P15S23Q007" "P15S23Q008"])

(defn p15-s23-stage2-plan-emitter-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-plan-emitter-diagnostic-messages
              id
              "P15-S23 stage2 plan emitter proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-plan-emitter
                 :diagnostic-family :p15-s23-stage2-plan-emitter
                 :value value
                 :remediation "Keep the stage2 plan emitter rules authored in Gravity source, execute them through the declared Clojure rule-runner boundary, prove accepted output and rejected diagnostics against the current stage, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-plan-emitter-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-plan-emitter
   :source-span {:source source-path}
   :message (get p15-s23-stage2-plan-emitter-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_plan_emitter})

(defn p15-s23-stage2-plan-emitter-rule-record
  [emitter]
  (let [special-rules (set (keys (:special-form-rules emitter)))
        builtin-functions (set (get-in emitter
                                       [:call-rules :builtin-functions]))
        missing-special
        (set/difference p15-s23-stage2-plan-emitter-required-special-forms
                        special-rules)
        missing-builtins
        (set/difference stage0-builtin-functions builtin-functions)
        plan-kind (get-in emitter [:plan-shape :kind])
        compiler-owner (get-in emitter [:plan-shape :compiler :owner])]
    {:artifact :gravity/p15-s23-stage2-plan-emitter-rule-record
     :engine (:engine emitter)
     :special-forms (p15-s23-stage2-sort-values special-rules)
     :builtin-functions (p15-s23-stage2-sort-values builtin-functions)
     :missing-special-forms (p15-s23-stage2-sort-values missing-special)
     :missing-builtin-functions (p15-s23-stage2-sort-values
                                 missing-builtins)
     :plan-kind plan-kind
     :compiler-owner compiler-owner
     :rule-set-complete?
     (and (= :gravity-stage2-plan-emitter-rules-v1 (:engine emitter))
          (empty? missing-special)
          (empty? missing-builtins)
          (= :gravity/stage2-hosted-core-compiled-plan plan-kind)
          (= :gravity-source compiler-owner))
     :status (if (and (= :gravity-stage2-plan-emitter-rules-v1
                         (:engine emitter))
                      (empty? missing-special)
                      (empty? missing-builtins)
                      (= :gravity/stage2-hosted-core-compiled-plan
                         plan-kind)
                      (= :gravity-source compiler-owner))
               :complete
               :failed)}))

(declare p15-s23-stage2-compile-expr)

(defn p15-s23-stage2-compile-collection
  [emitter module locals form]
  (let [collection-rules (:collection-rules emitter)]
    (cond
      (vector? form)
      {:op (get-in collection-rules [:vector :op] :vector-literal)
       :items (mapv #(p15-s23-stage2-compile-expr emitter module locals %)
                    form)}

      (map? form)
      {:op (get-in collection-rules [:map :op] :map-literal)
       :entries (mapv (fn [[k v]]
                        {:key (p15-s23-stage2-compile-expr
                               emitter module locals k)
                         :value (p15-s23-stage2-compile-expr
                                 emitter module locals v)})
                      (sort-by (fn [[k v]] (pr-str [k v])) form))}

      (set? form)
      {:op (get-in collection-rules [:set :op] :set-literal)
       :items (mapv #(p15-s23-stage2-compile-expr emitter module locals %)
                    (sort-by pr-str form))}

      :else
      {:op (get-in collection-rules [:literal :op] :literal)
       :value form})))

(defn p15-s23-stage2-compile-let
  [emitter module locals bindings body]
  (when-not (and (vector? bindings) (even? (count bindings)))
    (fail! "L2-LET-BINDING"
           "let requires an even binding vector"
           {:source-span {:source (:source-path module)}
            :bindings bindings
            :remediation "Use pairs of local names and expressions in let."}))
  (loop [scope locals
         compiled []
         pairs (partition 2 bindings)]
    (if-let [[name expr] (first pairs)]
      (do
        (when-not (symbol? name)
          (fail! "L2-LET-BINDING"
                 "let binding name must be a symbol"
                 {:source-span {:source (:source-path module)}
                  :binding name
                  :remediation "Bind symbols in stage2 let forms."}))
        (recur (conj scope name)
               (conj compiled
                     {:name name
                      :expr (p15-s23-stage2-compile-expr
                             emitter module scope expr)})
               (rest pairs)))
      {:op (get-in emitter [:special-form-rules 'let :op] :let)
       :bindings compiled
       :body (mapv #(p15-s23-stage2-compile-expr
                     emitter module scope %)
                   body)})))

(defn p15-s23-stage2-compile-expr
  [emitter module locals form]
  (cond
    (symbol? form)
    (if (contains? locals form)
      {:op :local :name form}
      (fail! "L2-UNKNOWN-SYMBOL"
             "stage2 plan emitter cannot resolve symbol"
             {:source-span {:source (:source-path module)}
              :symbol form
              :remediation "Define the symbol or stay within the stage2 hosted-core subset."}))

    (seq? form)
    (let [callee (first form)
          special-rule (get-in emitter [:special-form-rules callee])
          builtin-functions (set (get-in emitter
                                         [:call-rules :builtin-functions]))]
      (cond
        (= callee 'println)
        {:op (:op special-rule)
         :effect (:effect special-rule)
         :capability (:capability special-rule)
         :args (mapv #(p15-s23-stage2-compile-expr
                       emitter module locals %)
                     (rest form))}

        (= callee 'do)
        {:op (:op special-rule)
         :body (mapv #(p15-s23-stage2-compile-expr
                       emitter module locals %)
                     (rest form))}

        (= callee 'if)
        (let [[_ test then else] form]
          {:op (:op special-rule)
           :test (p15-s23-stage2-compile-expr emitter module locals test)
           :then (p15-s23-stage2-compile-expr emitter module locals then)
           :else (p15-s23-stage2-compile-expr emitter module locals else)})

        (= callee 'let)
        (let [[_ bindings & body] form]
          (p15-s23-stage2-compile-let emitter module locals bindings body))

        (= callee 'quote)
        {:op (:op special-rule) :value (second form)}

        (= callee 'host-reflect)
        (fail! (get-in special-rule [:diagnostic] "P4-HOST-REFLECTION")
               "host reflection is not implemented in stage2 plan emission"
               {:source-span {:source (:source-path module)}
                :remediation "Remove host reflection from the stage2 executable subset."})

        (contains? builtin-functions callee)
        {:op (get-in emitter [:call-rules :builtin-op] :builtin-call)
         :function callee
         :args (mapv #(p15-s23-stage2-compile-expr
                       emitter module locals %)
                     (rest form))}

        (contains? (:function-table module) callee)
        {:op (get-in emitter [:call-rules :function-op] :function-call)
         :function callee
         :args (mapv #(p15-s23-stage2-compile-expr
                       emitter module locals %)
                     (rest form))}

        :else
        (fail! (get-in emitter
                       [:call-rules :unknown-callee-diagnostic]
                       "L2-UNKNOWN-CORE-FORM")
               "stage2 plan emitter cannot compile this form"
               {:source-span {:source (:source-path module)}
                :operator callee
                :remediation "Use defn, println, do, if, let, quote, supported core builtins, or local function calls in the stage2 hosted-core subset."})))

    (or (vector? form) (map? form) (set? form))
    (p15-s23-stage2-compile-collection emitter module locals form)

    :else
    {:op (get-in emitter [:collection-rules :literal :op] :literal)
     :value form}))

(defn p15-s23-stage2-compile-function
  [emitter module {:keys [name params body] :as definition}]
  (assoc definition
         :binding {:name name
                   :kind :function
                   :namespace (:module module)
                   :profile (:profile module)
                   :target (:target module)
                   :visibility (if (seq (:exports module))
                                 (if (contains? (set (:exports module)) name)
                                   :public
                                   :private)
                                 :stage2-local)
                   :effects (:effects module)
                   :capabilities (:capabilities module)}
         :instructions (mapv #(p15-s23-stage2-compile-expr
                               emitter module (set params) %)
                             body)))

(defn p15-s23-stage2-emitted-core-plan
  [emitter source-path source-text module]
  (let [function-table (stage0-function-table module)
        module (assoc module :function-table function-table)
        _ (validate-stage0-compiled-profile! module)
        _ (executable-profile! source-path module (:forms module))
        _ (validate-module-effects! module)
        _ (validate-stage0-executable-safety! module)
        _ (validate-stage0-compiled-performance! module)
        _ (validate-stage0-compiled-math! module)
        _ (validate-stage0-compiled-compiler! module)
        _ (validate-stage0-compiled-backend! module)
        _ (validate-stage0-compiled-runtime! module)
        _ (validate-stage0-compiled-domain! module)
        _ (validate-stage0-compiled-schema! module)
        _ (validate-stage0-compiled-ai! module)
        _ (validate-stage0-compiled-package! module)
        _ (validate-stage0-compiled-tooling! module)
        _ (validate-stage0-compiled-conformance! module)
        functions (into (sorted-map)
                        (map (fn [[name definition]]
                               [name (p15-s23-stage2-compile-function
                                      emitter module definition)]))
                        function-table)
        main-function (get functions 'main)
        _ (when-not main-function
            (fail! "L3-UNKNOWN-ALIAS"
                   "stage2 executable requires a main function"
                   {:source-span {:source source-path}
                    :remediation "Add (defn main [] ...)."}))
        _ (when-not (empty? (:params main-function))
            (fail! "L2-MAIN-ARITY"
                   "stage2 main must take no arguments"
                   {:source-span {:source source-path}
                    :params (:params main-function)
                    :remediation "Use (defn main [] ...)."}))
        instruction-summary (apply merge-with +
                                   (mapcat (fn [[_ function]]
                                             (map stage0-instruction-summary
                                                  (:instructions function)))
                                           functions))
        plan-base {:kind (get-in emitter
                                 [:plan-shape :kind]
                                 :gravity/stage2-hosted-core-compiled-plan)
                   :compatibility-kind
                   (get-in emitter [:plan-shape :compatibility-kind])
                   :entrypoint (get-in emitter [:plan-shape :entrypoint] 'main)
                   :source {:path source-path
                            :sha256 (str "sha256:" (sha256-hex source-text))}
                   :compiler (merge
                              (get-in emitter [:plan-shape :compiler])
                              {:rule-engine (:engine emitter)
                               :rule-source :p15-s23-stage2-plan-emitter
                               :retirement-objective
                               :retire-clojure-seed})
                   :module (select-keys module
                                        [:module :source-path :profile :target
                                         :effects :capabilities :exports
                                         :safety])
                   :binding-table (mapv (fn [[name function]]
                                           (assoc (:binding function)
                                                  :arity (:arity function)))
                                         (sort-by key functions))
                   :functions functions
                   :instruction-summary instruction-summary
                   :effect-summary {:declared (:effects module)
                                    :inferred (if (pos? (get instruction-summary
                                                             :println
                                                             0))
                                                #{:io/write}
                                                #{})
                                    :capabilities (:capabilities module)}
                   :diagnostics []}]
    (assoc plan-base
           :plan-id (str "sha256:" (sha256-hex (pr-str plan-base))))))

(defn p15-s23-stage2-plan-emitter-compile-source
  [emitter source-path source-text]
  (let [_ (validate-stage0-source-profile! source-path source-text)
        _ (validate-stage0-source-safety! source-path source-text)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))]
    (p15-s23-stage2-emitted-core-plan emitter source-path source-text module)))

(defn p15-s23-stage2-plan-emitter-accepted-record
  [emitter]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        macro-artifact (macro-source-artifact source-path source-text)
        module (assoc (:module macro-artifact)
                      :forms (:expanded-forms macro-artifact))
        stage2-plan (p15-s23-stage2-emitted-core-plan
                     emitter source-path source-text module)
        stage2-output (execute-stage0-compiled-plan stage2-plan)
        stage0-plan (stage0-compiled-core-plan source-path source-text module)
        stage0-output (execute-stage0-compiled-plan stage0-plan)
        expected-stdout (get-in emitter
                                [:accepted-scope :expected-stdout])
        normalized-stage2-bindings
        (mapv #(assoc % :visibility :local)
              (:binding-table stage2-plan))
        normalized-stage0-bindings
        (mapv #(assoc % :visibility :local)
              (:binding-table stage0-plan))
        binding-table-equivalent?
        (= normalized-stage2-bindings normalized-stage0-bindings)
        function-instructions-equivalent?
        (= (update-vals (:functions stage2-plan)
                        #(select-keys % [:params :body :arity
                                         :body-form-count :instructions]))
           (update-vals (:functions stage0-plan)
                        #(select-keys % [:params :body :arity
                                         :body-form-count :instructions])))
        instruction-summary-equivalent?
        (= (:instruction-summary stage2-plan)
           (:instruction-summary stage0-plan))
        effect-summary-equivalent?
        (= (:effect-summary stage2-plan)
           (:effect-summary stage0-plan))
        accepted-output-equivalent?
        (and (= stage2-output stage0-output)
             (= stage2-output expected-stdout))
        equivalent?
        (and binding-table-equivalent?
             function-instructions-equivalent?
             instruction-summary-equivalent?
             effect-summary-equivalent?
             accepted-output-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-plan-emitter-accepted-record
     :fixture source-path
     :stage2-plan-id (:plan-id stage2-plan)
     :stage0-plan-id (:plan-id stage0-plan)
     :stage2-plan-kind (:kind stage2-plan)
     :stage0-plan-kind (:kind stage0-plan)
     :entrypoint (:entrypoint stage2-plan)
     :binding-table-equivalent? binding-table-equivalent?
     :binding-table-visibility-normalized? true
     :function-instructions-equivalent?
     function-instructions-equivalent?
     :instruction-summary-equivalent? instruction-summary-equivalent?
     :effect-summary-equivalent? effect-summary-equivalent?
     :accepted-output-equivalent? accepted-output-equivalent?
     :stage2-output stage2-output
     :stage0-output stage0-output
     :expected-stdout expected-stdout
     :stage2-plan (select-keys stage2-plan
                               [:kind :compatibility-kind :plan-id
                                :entrypoint :compiler :module
                                :binding-table :instruction-summary
                                :effect-summary :diagnostics])
     :status (if equivalent? :complete :failed)}))

(defn p15-s23-stage2-plan-emitter-rejected-records
  [emitter]
  (mapv
   (fn [{:keys [fixture expected-diagnostic rejected-design]}]
     (try
       (let [source-text (slurp fixture)
             plan (p15-s23-stage2-plan-emitter-compile-source
                   emitter fixture source-text)
             stdout (execute-stage0-compiled-plan plan)]
         {:fixture fixture
          :rejected-design rejected-design
          :expected-diagnostic expected-diagnostic
          :status :accepted-unexpectedly
          :stdout stdout
          :stage2-plan-id (:plan-id plan)
          :matches-expected? false})
       (catch clojure.lang.ExceptionInfo ex
         (let [data (ex-data ex)
               diagnostic (:id data)]
           {:fixture fixture
            :rejected-design rejected-design
            :expected-diagnostic expected-diagnostic
            :status :rejected
            :diagnostic diagnostic
            :message (:message data)
            :diagnostic-data data
            :matches-expected? (= expected-diagnostic diagnostic)}))))
   p15-s23-rejected-app-fixtures))

(defn p15-s23-stage2-plan-emitter-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact :gravity/p15-s23-stage2-plan-emitter-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

(defn p15-s23-stage2-plan-emitter-evidence-link-record
  [nucleus-artifact pipeline-artifact accepted-artifact rejected-artifact]
  (let [links {:stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}
               :accepted-app-execution-proof
               {:artifact (:kind accepted-artifact)
                :artifact-id (:artifact-id accepted-artifact)
                :present?
                (= :gravity/p15-s23-accepted-app-execution-artifact
                   (:kind accepted-artifact))}
               :rejected-app-diagnostic-proof
               {:artifact (:kind rejected-artifact)
                :artifact-id (:artifact-id rejected-artifact)
                :present?
                (= :gravity/p15-s23-rejected-app-diagnostic-artifact
                   (:kind rejected-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact :gravity/p15-s23-stage2-plan-emitter-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-plan-emitter-boundary-record
  [emitter]
  (let [claims (:self-hosting-claims emitter)]
    {:artifact :gravity/p15-s23-stage2-plan-emitter-boundary-record
     :implemented-by (:implemented-by emitter)
     :executed-by (:executed-by emitter)
     :compiled-by (get-in emitter [:lineage :compiled-by])
     :stage0-plan-emitter-replaced? true
     :stage2-plan-emitted-by-gravity-rules? true
     :clojure-stage0-rule-runner?
     (= :clojure-stage0-rule-runner (:executed-by emitter))
     :clojure-stage0-compiler?
     (= :clojure-stage0 (get-in emitter [:lineage :compiled-by]))
     :clojure-instruction-runner?
     (= :clojure-instruction-runner
        (get-in emitter [:seed-boundary :stage0-executor-boundary]))
     :self-hosted-compiler? false
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary (:seed-boundary emitter)
     :next-required-capability (:next-required-capability emitter)
     :status :complete}))

(defn p15-s23-stage2-plan-emitter-diagnostics
  [source-path candidate]
  (let [emitter (:emitter-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims emitter)
        preserves (set (:preserves emitter))
        emits (set (:emits emitter))
        missing-preserves
        (set/difference p15-s23-stage2-plan-emitter-required-preserves
                        preserves)
        missing-emits
        (set/difference p15-s23-stage2-plan-emitter-required-emits emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-plan-emitter
                        (:artifact emitter))
                     (= :p15-s23-stage2-plan-emitter
                        (:stage emitter))
                     (= :gravity-source (:implemented-by emitter))
                     (= :clojure-stage0-rule-runner
                        (:executed-by emitter)))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q001" emitter
          {:missing-fields [:artifact :stage :implemented-by
                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q002" rule-record
          {:missing-special-forms (:missing-special-forms rule-record)
           :missing-builtin-functions
           (:missing-builtin-functions rule-record)})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q003" accepted-record
          {:stage2-output (:stage2-output accepted-record)
           :stage0-output (:stage0-output accepted-record)
           :expected-stdout (:expected-stdout accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q004" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q005" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q006" emitter
          {:missing-preserves (p15-s23-stage2-sort-values
                               missing-preserves)
           :missing-emits (p15-s23-stage2-sort-values missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage0-plan-emitter-replaced?
                             boundary-record))
                     (true? (:stage2-plan-emitted-by-gravity-rules?
                             boundary-record))
                     (true? (:clojure-stage0-rule-runner?
                             boundary-record))
                     (true? (:clojure-instruction-runner?
                             boundary-record))
                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q007" boundary-record
          {:required-boundary [:stage0-plan-emitter-replaced
                               :gravity-rule-authored-plan-emission
                               :clojure-stage0-rule-runner
                               :clojure-instruction-runner
                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-plan-emitter-diagnostic-record
          source-path "P15S23Q008" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-plan-emitter-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage2-plan-emitter-diagnostic-stream
   :stage :p15-s23-stage2-plan-emitter
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-plan-emitter
            :message
            (get p15-s23-stage2-plan-emitter-diagnostic-messages id)})
         p15-s23-stage2-plan-emitter-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-plan-emitter-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-plan-emitter-missing-contract
    :candidate (assoc candidate :emitter-contract {})
    :expected-diagnostic "P15S23Q001"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-rule-gap
    :candidate (assoc-in candidate [:rule-record :status] :failed)
    :expected-diagnostic "P15S23Q002"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-output-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-record :status] :failed)
                   (assoc-in [:accepted-record
                              :accepted-output-equivalent?]
                             false))
    :expected-diagnostic "P15S23Q003"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-rejected-gap
    :candidate (-> candidate
                   (assoc-in [:rejected-record :status] :failed)
                   (assoc-in [:rejected-record :mismatch-count] 1))
    :expected-diagnostic "P15S23Q004"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-evidence-gap
    :candidate (-> candidate
                   (assoc-in [:evidence-link-record :status] :failed)
                   (assoc-in [:evidence-link-record :missing-links]
                             [:stage2-compiler-nucleus]))
    :expected-diagnostic "P15S23Q005"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-preservation-gap
    :candidate (assoc-in candidate [:emitter-contract :preserves] [])
    :expected-diagnostic "P15S23Q006"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-boundary-gap
    :candidate (-> candidate
                   (assoc-in [:boundary-record
                              :stage0-plan-emitter-replaced?]
                             false)
                   (assoc-in [:boundary-record
                              :clojure-stage0-rule-runner?]
                             false))
    :expected-diagnostic "P15S23Q007"}
   {:fixture :internal-p15-s23-stage2-plan-emitter-overclaim
    :candidate (-> candidate
                   (assoc-in [:emitter-contract :self-hosting-claims
                              :full-language-compiler-self-hosted?]
                             true)
                   (assoc-in [:emitter-contract :self-hosting-claims
                              :clojure-seed-retired?]
                             true))
    :expected-diagnostic "P15S23Q008"}])

(defn p15-s23-stage2-plan-emitter-rejected-proof-records
  [source-path candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-plan-emitter-diagnostics source-path
                                                    candidate)})
        (p15-s23-stage2-plan-emitter-rejected-candidates candidate)))

(defn p15-s23-stage2-plan-emitter-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-plan-emitter-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage2-plan-emitter-fixtures
                      artifact)))
        accepted-record (:accepted-record artifact)
        rejected-record (:rejected-record artifact)
        boundary-record (:boundary-record artifact)]
    {:stage2-plan-emitter-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :stage2-plan-emitter-present?
     (= :gravity/stage2-plan-emitter
        (get-in artifact [:emitter-contract :artifact]))
     :stage2-plan-emitted?
     (= :gravity/stage2-hosted-core-compiled-plan
        (:stage2-plan-kind accepted-record))
     :stage0-plan-emitter-replaced?
     (true? (:stage0-plan-emitter-replaced? boundary-record))
     :function-instructions-equivalent?
     (true? (:function-instructions-equivalent? accepted-record))
     :accepted-output-equivalent?
     (true? (:accepted-output-equivalent? accepted-record))
     :rejected-diagnostics-equivalent?
     (= :complete (:status rejected-record))
     :residual-clojure-rule-runner-recorded?
     (true? (:clojure-stage0-rule-runner? boundary-record))
     :residual-clojure-instruction-runner-recorded?
     (true? (:clojure-instruction-runner? boundary-record))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (= (set p15-s23-stage2-plan-emitter-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-plan-emitter-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
      :stage2-plan-emitter-authored-in-gravity? true
      :stage2-plan-emitter-executed? true
      :stage2-runtime-executed? false
      :clojure-stage0-rule-runner? true
      :clojure-instruction-runner? true
      :full-self-hosted-toolchain? false
      :next-required-capability
      :replace_stage0_instruction_runner_with_stage2_runtime_execution}}))

(defn p15-s23-stage2-plan-emitter-source-artifact
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        emitter
        (p15-s23-compiler-def-value source-path
                                     (:forms source-data)
                                     'p15-s23-stage2-plan-emitter)
        rule-record (p15-s23-stage2-plan-emitter-rule-record emitter)
        accepted-record (p15-s23-stage2-plan-emitter-accepted-record
                         emitter)
        rejected-fixture-records
        (p15-s23-stage2-plan-emitter-rejected-records emitter)
        rejected-record
        (p15-s23-stage2-plan-emitter-rejected-record
         rejected-fixture-records)
        nucleus-artifact
        (p15-s23-stage2-compiler-nucleus-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact
         source-path)
        accepted-artifact
        (p15-s23-accepted-app-execution-source-artifact source-path)
        rejected-artifact
        (p15-s23-rejected-app-diagnostic-source-artifact source-path)
        evidence-link-record
        (p15-s23-stage2-plan-emitter-evidence-link-record
         nucleus-artifact pipeline-artifact accepted-artifact
         rejected-artifact)
        boundary-record
        (p15-s23-stage2-plan-emitter-boundary-record emitter)
        candidate {:emitter-contract emitter
                   :rule-record rule-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage2-plan-emitter-diagnostics source-path
                                                 candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-plan-emitter-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :emitter emitter
                       :stage2-plan-id
                       (:stage2-plan-id accepted-record)
                       :stage0-plan-id
                       (:stage0-plan-id accepted-record)
                       :rejected-diagnostics
                       (:observed-diagnostics rejected-record)})))
        rejected-proof-records
        (p15-s23-stage2-plan-emitter-rejected-proof-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage2-plan-emitter-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-plan-emitter
         :source-path source-path
         :proof-id proof-id
         :emitter-contract emitter
         :rule-record rule-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :evidence-link-record evidence-link-record
         :boundary-record boundary-record
         :linked-artifacts
         {:stage2-compiler-nucleus
          (select-keys nucleus-artifact [:kind :artifact-id :proof-id])
          :compiler-pipeline-manifest
          (select-keys pipeline-artifact [:kind :artifact-id :proof-id])
          :accepted-app-execution-proof
          (select-keys accepted-artifact [:kind :artifact-id :proof-id])
          :rejected-app-diagnostic-proof
          (select-keys rejected-artifact [:kind :artifact-id :proof-id])}
         :full-language-compiler-self-hosted?
         (get-in emitter
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in emitter [:self-hosting-claims
                          :clojure-seed-retired?])
         :accepted-p15-s23-stage2-plan-emitter-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stage2-plan-id (:stage2-plan-id accepted-record)
           :stage0-plan-id (:stage0-plan-id accepted-record)
           :stdout (:stage2-output accepted-record)}]
         :verified-p15-s23-stage2-plan-emitter-rejected-fixtures
         rejected-fixture-records
         :rejected-p15-s23-stage2-plan-emitter-fixtures
         rejected-proof-records
         :p15-s23-stage2-plan-emitter-diagnostic-stream
         (p15-s23-stage2-plan-emitter-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-plan-emitter-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-fixture-records)
          :internal-rejected-fixtures (count rejected-proof-records)
          :diagnostic-count
          (count p15-s23-stage2-plan-emitter-diagnostic-ids)
          :stage2-plan-id (:stage2-plan-id accepted-record)
          :stage0-plan-id (:stage0-plan-id accepted-record)
          :accepted-output (:stage2-output accepted-record)
          :rejected-diagnostics (:observed-diagnostics rejected-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-plan-emitter-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-plan-emitter-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-plan-emitter-fail!
     "P15S23Q001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-plan-emitter-source-artifact path))

(defn p15-s23-stage2-plan-emitter-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-plan-emitter-file-artifact source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage2-plan-id
           (get-in artifact [:accepted-record :stage2-plan-id])
           :stage0-plan-emitter-replaced?
           (:stage0-plan-emitter-replaced? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
           :rejected-diagnostics-equivalent?
           (:rejected-diagnostics-equivalent? proof)
           :residual-clojure-rule-runner-recorded?
           (:residual-clojure-rule-runner-recorded? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

(def p15-s23-stage2-runtime-executor-required-preserves
  #{:source-spans :diagnostic-codes :instruction-semantics
    :function-bindings :effects :capabilities :profile
    :compiler-lineage :artifact-provenance})

(def p15-s23-stage2-runtime-executor-required-emits
  #{:stage2-runtime-execution-record :accepted-output-comparison
    :rejected-diagnostic-comparison :stage2-runtime-boundary-record})

(def p15-s23-stage2-runtime-executor-required-instructions
  #{:literal :quote :local :vector-literal :set-literal :map-literal
    :println :do :if :let :builtin-call :function-call})

(def p15-s23-stage2-runtime-executor-diagnostic-messages
  {"P15S23X001" "P15-S23 stage2 runtime executor contract is missing"
   "P15S23X002" "P15-S23 stage2 runtime executor rule set is incomplete"
   "P15S23X003" "P15-S23 stage2 runtime executor accepted output is not equivalent"
   "P15S23X004" "P15-S23 stage2 runtime executor rejected diagnostics are not preserved"
   "P15S23X005" "P15-S23 stage2 runtime executor evidence links are incomplete"
   "P15S23X006" "P15-S23 stage2 runtime executor preservation or emission contract is incomplete"
   "P15S23X007" "P15-S23 stage2 runtime executor residual boundary record is incomplete"
   "P15S23X008" "P15-S23 stage2 runtime executor makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-runtime-executor-diagnostic-ids
  ["P15S23X001" "P15S23X002" "P15S23X003" "P15S23X004"
   "P15S23X005" "P15S23X006" "P15S23X007" "P15S23X008"])

(defn p15-s23-stage2-runtime-executor-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-runtime-executor-diagnostic-messages
              id
              "P15-S23 stage2 runtime executor proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-runtime-executor
                 :diagnostic-family :p15-s23-stage2-runtime-executor
                 :value value
                 :remediation "Keep the stage2 runtime executor rules authored in Gravity source, execute the stage2 plan through the declared runtime-host boundary, prove accepted output and rejected diagnostics against the current stage, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-runtime-executor-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-runtime-executor
   :source-span {:source source-path}
   :message (get p15-s23-stage2-runtime-executor-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_runtime_executor})

(defn p15-s23-stage2-runtime-executor-rule-record
  [runtime]
  (let [instruction-rules (set (keys (:instruction-rules runtime)))
        builtin-functions (set (get-in runtime
                                       [:builtin-rules :functions]))
        missing-instructions
        (set/difference
         p15-s23-stage2-runtime-executor-required-instructions
         instruction-rules)
        missing-builtins
        (set/difference stage0-builtin-functions builtin-functions)
        complete?
        (and (= :gravity-stage2-runtime-executor-rules-v1
                (:engine runtime))
             (= :stage2-instruction-plan (:input runtime))
             (= :stage2-runtime-execution-record (:output runtime))
             (empty? missing-instructions)
             (empty? missing-builtins))]
    {:artifact :gravity/p15-s23-stage2-runtime-executor-rule-record
     :engine (:engine runtime)
     :input (:input runtime)
     :output (:output runtime)
     :instruction-rules (p15-s23-stage2-sort-values instruction-rules)
     :builtin-functions (p15-s23-stage2-sort-values builtin-functions)
     :missing-instructions (p15-s23-stage2-sort-values
                            missing-instructions)
     :missing-builtin-functions (p15-s23-stage2-sort-values
                                 missing-builtins)
     :rule-set-complete? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-runtime-fail-call-arity!
  [id plan callee args expected]
  (fail! id
         (case id
           "L2-FUNCTION-ARITY" "stage2 runtime function call has the wrong arity"
           "L2-BUILTIN-ARITY" "stage2 runtime builtin call has the wrong arity"
           "stage2 runtime call has the wrong arity")
         {:source-span {:source (get-in plan [:source :path])}
          :function callee
          :expected-arity expected
          :actual-arity (count args)
          :remediation "Call the function with the arity supported by the stage2 hosted-core runtime subset."}))

(defn p15-s23-stage2-runtime-assert-min-arity!
  [plan callee args n]
  (when (< (count args) n)
    (p15-s23-stage2-runtime-fail-call-arity!
     "L2-BUILTIN-ARITY" plan callee args (str "at least " n))))

(defn p15-s23-stage2-runtime-assert-exact-arity!
  [plan callee args n]
  (when-not (= n (count args))
    (p15-s23-stage2-runtime-fail-call-arity!
     "L2-BUILTIN-ARITY" plan callee args n)))

(defn p15-s23-stage2-runtime-assert-between-arity!
  [plan callee args min-n max-n]
  (when-not (<= min-n (count args) max-n)
    (p15-s23-stage2-runtime-fail-call-arity!
     "L2-BUILTIN-ARITY" plan callee args (str min-n " to " max-n))))

(defn p15-s23-stage2-runtime-assert-even-arity!
  [plan callee args]
  (when (odd? (count args))
    (p15-s23-stage2-runtime-fail-call-arity!
     "L2-BUILTIN-ARITY" plan callee args "an even number of arguments")))

(defn p15-s23-stage2-runtime-invoke-builtin
  [plan callee args]
  (try
    (case callee
      + (apply + args)
      - (do (p15-s23-stage2-runtime-assert-min-arity!
             plan callee args 1)
            (apply - args))
      * (apply * args)
      / (do (p15-s23-stage2-runtime-assert-min-arity!
             plan callee args 1)
            (apply / args))
      = (do (p15-s23-stage2-runtime-assert-min-arity!
             plan callee args 1)
            (apply = args))
      < (do (p15-s23-stage2-runtime-assert-min-arity!
             plan callee args 2)
            (apply < args))
      > (do (p15-s23-stage2-runtime-assert-min-arity!
             plan callee args 2)
            (apply > args))
      <= (do (p15-s23-stage2-runtime-assert-min-arity!
              plan callee args 2)
             (apply <= args))
      >= (do (p15-s23-stage2-runtime-assert-min-arity!
              plan callee args 2)
             (apply >= args))
      str (apply str args)
      pr-str (apply pr-str args)
      hash-map (do (p15-s23-stage2-runtime-assert-even-arity!
                    plan callee args)
                   (apply hash-map args))
      vector (vec args)
      list (apply list args)
      conj (do (p15-s23-stage2-runtime-assert-min-arity!
                plan callee args 1)
               (apply conj args))
      assoc (do
              (p15-s23-stage2-runtime-assert-min-arity!
               plan callee args 3)
              (when (even? (count args))
                (p15-s23-stage2-runtime-fail-call-arity!
                 "L2-BUILTIN-ARITY" plan callee args
                 "a collection followed by key/value pairs"))
              (apply assoc args))
      get (do (p15-s23-stage2-runtime-assert-between-arity!
               plan callee args 2 3)
              (apply get args))
      first (do (p15-s23-stage2-runtime-assert-exact-arity!
                 plan callee args 1)
                (first (first args)))
      second (do (p15-s23-stage2-runtime-assert-exact-arity!
                  plan callee args 1)
                 (second (first args)))
      rest (do (p15-s23-stage2-runtime-assert-exact-arity!
                plan callee args 1)
               (rest (first args)))
      count (do (p15-s23-stage2-runtime-assert-exact-arity!
                 plan callee args 1)
                (count (first args))))
    (catch clojure.lang.ExceptionInfo ex
      (throw ex))
    (catch Exception ex
      (fail! "L2-BUILTIN-ERROR"
             "stage2 runtime builtin call failed"
             {:source-span {:source (get-in plan [:source :path])}
              :function callee
              :cause-message (.getMessage ex)
              :remediation "Keep builtin inputs inside the checked stage2 hosted-core runtime subset."}))))

(declare p15-s23-stage2-runtime-execute-instruction)
(declare p15-s23-stage2-runtime-execute-function)

(defn p15-s23-stage2-runtime-execute-instructions
  [runtime plan env instructions]
  (reduce (fn [_ instruction]
            (p15-s23-stage2-runtime-execute-instruction
             runtime plan env instruction))
          nil
          instructions))

(defn p15-s23-stage2-runtime-execute-instruction
  [runtime plan env instruction]
  (case (:op instruction)
    :literal (:value instruction)
    :quote (:value instruction)
    :local (if (contains? env (:name instruction))
             (get env (:name instruction))
             (fail! "L2-UNKNOWN-SYMBOL"
                    "stage2 runtime cannot resolve local"
                    {:source-span {:source (get-in plan [:source :path])}
                     :symbol (:name instruction)
                     :remediation "Regenerate the stage2 instruction plan from a valid source module."}))
    :vector-literal
    (mapv #(p15-s23-stage2-runtime-execute-instruction
            runtime plan env %)
          (:items instruction))
    :set-literal
    (set (map #(p15-s23-stage2-runtime-execute-instruction
                runtime plan env %)
              (:items instruction)))
    :map-literal
    (into {}
          (map (fn [{:keys [key value]}]
                 [(p15-s23-stage2-runtime-execute-instruction
                   runtime plan env key)
                  (p15-s23-stage2-runtime-execute-instruction
                   runtime plan env value)]))
          (:entries instruction))
    :println
    (let [module (:module plan)
          args (mapv #(p15-s23-stage2-runtime-execute-instruction
                       runtime plan env %)
                     (:args instruction))]
      (validate-module-effects! module)
      (println (clojure.string/join " " (map str args))))
    :do
    (p15-s23-stage2-runtime-execute-instructions
     runtime plan env (:body instruction))
    :if
    (if (p15-s23-stage2-runtime-execute-instruction
         runtime plan env (:test instruction))
      (p15-s23-stage2-runtime-execute-instruction
       runtime plan env (:then instruction))
      (p15-s23-stage2-runtime-execute-instruction
       runtime plan env (:else instruction)))
    :let
    (loop [env env
           bindings (:bindings instruction)]
      (if-let [{:keys [name expr]} (first bindings)]
        (recur (assoc env name
                      (p15-s23-stage2-runtime-execute-instruction
                       runtime plan env expr))
               (rest bindings))
        (p15-s23-stage2-runtime-execute-instructions
         runtime plan env (:body instruction))))
    :builtin-call
    (let [args (mapv #(p15-s23-stage2-runtime-execute-instruction
                       runtime plan env %)
                     (:args instruction))]
      (p15-s23-stage2-runtime-invoke-builtin
       plan (:function instruction) args))
    :function-call
    (let [args (mapv #(p15-s23-stage2-runtime-execute-instruction
                       runtime plan env %)
                     (:args instruction))]
      (p15-s23-stage2-runtime-execute-function
       runtime plan (:function instruction) args))
    (fail! "L2-UNKNOWN-CORE-FORM"
           "stage2 runtime plan contains an unknown instruction"
           {:source-span {:source (get-in plan [:source :path])}
            :operator (:op instruction)
            :remediation "Regenerate the stage2 instruction plan with a supported stage2 plan emitter."})))

(defn p15-s23-stage2-runtime-execute-function
  [runtime plan callee args]
  (let [definition (get-in plan [:functions callee])
        params (:params definition)]
    (when-not definition
      (fail! "L2-UNKNOWN-CORE-FORM"
             "stage2 runtime plan references an unknown function"
             {:source-span {:source (get-in plan [:source :path])}
              :function callee
              :remediation "Regenerate the stage2 instruction plan from source."}))
    (when-not (= (count params) (count args))
      (p15-s23-stage2-runtime-fail-call-arity!
       "L2-FUNCTION-ARITY" plan callee args (count params)))
    (p15-s23-stage2-runtime-execute-instructions
     runtime plan (zipmap params args) (:instructions definition))))

(defn p15-s23-stage2-runtime-execute-plan
  [runtime plan]
  (let [main-function (get-in plan [:functions (:entrypoint plan)])
        params (:params main-function)
        result (atom nil)
        stdout
        (with-out-str
          (when-not main-function
            (fail! "L3-UNKNOWN-ALIAS"
                   "stage2 runtime plan requires a main function"
                   {:source-span {:source (get-in plan [:source :path])}
                    :remediation "Regenerate the stage2 plan from a module with main."}))
          (when-not (empty? params)
            (fail! "L2-MAIN-ARITY"
                   "stage2 runtime main must take no arguments"
                   {:source-span {:source (get-in plan [:source :path])}
                    :params params
                    :remediation "Use (defn main [] ...)."}))
          (reset! result
                  (p15-s23-stage2-runtime-execute-instructions
                   runtime plan {} (:instructions main-function))))]
	    {:artifact :gravity/p15-s23-stage2-runtime-execution-record
	     :runtime-engine (:engine runtime)
	     :plan-id (:plan-id plan)
	     :plan-kind (:kind plan)
     :entrypoint (:entrypoint plan)
     :stdout stdout
     :entrypoint-result @result
     :instruction-summary (:instruction-summary plan)
	     :effect-summary (:effect-summary plan)
	     :status :complete}))

	(def p15-s23-stage2-runtime-kernel-required-preserves
	  #{:source-spans :diagnostic-codes :instruction-semantics
	    :function-bindings :effects :capabilities :profile
	    :compiler-lineage :artifact-provenance})

	(def p15-s23-stage2-runtime-kernel-required-emits
	  #{:stage2-runtime-kernel-execution-record
	    :gravity-runtime-primitive-record
	    :accepted-output-comparison
	    :rejected-diagnostic-comparison
	    :stage2-runtime-kernel-boundary-record})

	(def p15-s23-stage2-runtime-kernel-required-instructions
	  p15-s23-stage2-runtime-executor-required-instructions)

	(def p15-s23-stage2-runtime-kernel-diagnostic-messages
	  {"P15S23K001" "P15-S23 stage2 runtime kernel contract is missing"
	   "P15S23K002" "P15-S23 stage2 runtime kernel rule set is incomplete"
	   "P15S23K003" "P15-S23 stage2 runtime kernel accepted output is not equivalent"
	   "P15S23K004" "P15-S23 stage2 runtime kernel rejected diagnostics are not preserved"
	   "P15S23K005" "P15-S23 stage2 runtime kernel evidence links are incomplete"
	   "P15S23K006" "P15-S23 stage2 runtime kernel preservation or emission contract is incomplete"
	   "P15S23K007" "P15-S23 stage2 runtime kernel boundary record is incomplete"
	   "P15S23K008" "P15-S23 stage2 runtime kernel makes an unsupported self-hosting or seed-retirement claim"})

	(def p15-s23-stage2-runtime-kernel-diagnostic-ids
	  ["P15S23K001" "P15S23K002" "P15S23K003" "P15S23K004"
	   "P15S23K005" "P15S23K006" "P15S23K007" "P15S23K008"])

	(defn p15-s23-stage2-runtime-kernel-fail!
	  [id source-path value data]
	  (fail! id
	         (get p15-s23-stage2-runtime-kernel-diagnostic-messages
	              id
	              "P15-S23 stage2 runtime kernel proof failed")
	         (merge {:source-span {:source source-path}
	                 :stage :p15-s23-stage2-runtime-kernel
	                 :diagnostic-family :p15-s23-stage2-runtime-kernel
	                 :value value
	                 :remediation "Keep the runtime kernel authored in Gravity source, prove hosted-core execution and primitive dispatch through the declared kernel boundary, and keep the remaining Clojure verifier/compiler seed boundary explicit."}
	                data)))

	(defn p15-s23-stage2-runtime-kernel-diagnostic-record
	  [source-path id value data]
	  {:artifact :gravity/diagnostic
	   :diagnostic-id (str "diag-" (str/lower-case id))
	   :diagnostic id
	   :severity :error
	   :stage :p15-s23-stage2-runtime-kernel
	   :source-span {:source source-path}
	   :message (get p15-s23-stage2-runtime-kernel-diagnostic-messages id)
	   :facts data
	   :observed value
	   :remediation :repair_stage2_runtime_kernel})

	(defn p15-s23-stage2-runtime-kernel-rule-record
	  [kernel]
	  (let [instruction-rules (set (keys (:instruction-rules kernel)))
	        runtime-primitives (set (get-in kernel
	                                        [:runtime-primitives :functions]))
	        missing-instructions
	        (set/difference
	         p15-s23-stage2-runtime-kernel-required-instructions
	         instruction-rules)
	        missing-primitives
	        (set/difference stage0-builtin-functions runtime-primitives)
	        primitive-boundary
	        (get-in kernel [:runtime-primitives
	                        :host-primitive-boundary])
	        complete?
	        (and (= :gravity-stage2-runtime-kernel-v1
	                (:engine kernel))
	             (= :stage2-instruction-plan (:input kernel))
	             (= :stage2-runtime-kernel-execution-record
	                (:output kernel))
	             (= :gravity-runtime-primitives primitive-boundary)
	             (empty? missing-instructions)
	             (empty? missing-primitives))]
	    {:artifact :gravity/p15-s23-stage2-runtime-kernel-rule-record
	     :engine (:engine kernel)
	     :primitive-engine (get-in kernel [:runtime-primitives :engine])
	     :input (:input kernel)
	     :output (:output kernel)
	     :primitive-boundary primitive-boundary
	     :instruction-rules (p15-s23-stage2-sort-values
	                         instruction-rules)
	     :runtime-primitives (p15-s23-stage2-sort-values
	                          runtime-primitives)
	     :missing-instructions (p15-s23-stage2-sort-values
	                            missing-instructions)
	     :missing-runtime-primitives (p15-s23-stage2-sort-values
	                                  missing-primitives)
	     :rule-set-complete? complete?
	     :status (if complete? :complete :failed)}))

	(defn p15-s23-stage2-runtime-kernel-accepted-record
	  [kernel emitter]
	  (let [source-path p15-s23-accepted-app-source-path
	        source-text (slurp source-path)
	        stage2-plan
	        (p15-s23-stage2-plan-emitter-compile-source
	         emitter source-path source-text)
	        kernel-output
	        (assoc (p15-s23-stage2-runtime-execute-plan kernel
	                                                   stage2-plan)
	               :artifact
	               :gravity/p15-s23-stage2-runtime-kernel-execution-record)
	        stage0-output (execute-stage0-compiled-plan stage2-plan)
	        expected-stdout (get-in kernel
	                                [:accepted-scope :expected-stdout])
	        accepted-output-equivalent?
	        (and (= (:stdout kernel-output) stage0-output)
	             (= (:stdout kernel-output) expected-stdout))
	        entrypoint-result-equivalent?
	        (nil? (:entrypoint-result kernel-output))
	        summary-equivalent?
	        (= (:instruction-summary kernel-output)
	           (:instruction-summary stage2-plan))
	        effect-summary-equivalent?
	        (= (:effect-summary kernel-output)
	           (:effect-summary stage2-plan))
	        equivalent?
	        (and accepted-output-equivalent?
	             entrypoint-result-equivalent?
	             summary-equivalent?
	             effect-summary-equivalent?)]
	    {:artifact :gravity/p15-s23-stage2-runtime-kernel-accepted-record
	     :fixture source-path
	     :stage2-plan-id (:plan-id stage2-plan)
	     :stage2-plan-kind (:kind stage2-plan)
	     :entrypoint (:entrypoint stage2-plan)
	     :kernel-execution-record kernel-output
	     :stage2-runtime-kernel-executed? true
	     :stage0-instruction-runner-output stage0-output
	     :stage2-runtime-kernel-output (:stdout kernel-output)
	     :expected-stdout expected-stdout
	     :entrypoint-result-equivalent? entrypoint-result-equivalent?
	     :instruction-summary-equivalent? summary-equivalent?
	     :effect-summary-equivalent? effect-summary-equivalent?
	     :accepted-output-equivalent? accepted-output-equivalent?
	     :status (if equivalent? :complete :failed)}))

	(defn p15-s23-stage2-runtime-kernel-rejected-plan-fixtures
	  [stage2-plan]
	  (let [function-arity-plan
	        (assoc-in stage2-plan
	                  [:functions 'main :instructions]
	                  [{:op :function-call
	                    :function 'total
	                    :args [{:op :literal :value 5}]}])
	        builtin-arity-plan
	        (assoc-in stage2-plan
	                  [:functions 'main :instructions]
	                  [{:op :builtin-call
	                    :function 'assoc
	                    :args [{:op :map-literal :entries []}
	                           {:op :quote :value :missing-value}]}])]
	    [{:fixture :internal-stage2-runtime-kernel-function-arity-plan
	      :expected-diagnostic "L2-FUNCTION-ARITY"
	      :rejected-design :wrong-user-function-arity
	      :plan function-arity-plan}
	     {:fixture :internal-stage2-runtime-kernel-builtin-arity-plan
	      :expected-diagnostic "L2-BUILTIN-ARITY"
	      :rejected-design :wrong-builtin-arity
	      :plan builtin-arity-plan}]))

	(defn p15-s23-stage2-runtime-kernel-rejected-records
	  [kernel emitter]
	  (let [source-path p15-s23-accepted-app-source-path
	        source-text (slurp source-path)
	        stage2-plan
	        (p15-s23-stage2-plan-emitter-compile-source
	         emitter source-path source-text)]
	    (mapv
	     (fn [{:keys [fixture expected-diagnostic rejected-design plan]}]
	       (try
	         (let [kernel-output
	               (p15-s23-stage2-runtime-execute-plan kernel plan)]
	           {:fixture fixture
	            :rejected-design rejected-design
	            :expected-diagnostic expected-diagnostic
	            :status :accepted-unexpectedly
	            :kernel-output kernel-output
	            :plan-id (:plan-id plan)
	            :matches-expected? false})
	         (catch clojure.lang.ExceptionInfo ex
	           (let [data (ex-data ex)
	                 diagnostic (:id data)]
	             {:fixture fixture
	              :rejected-design rejected-design
	              :expected-diagnostic expected-diagnostic
	              :status :rejected
	              :diagnostic diagnostic
	              :message (:message data)
	              :diagnostic-data data
	              :plan-id
	              (str "sha256:" (sha256-hex (pr-str plan)))
	              :matches-expected?
	              (= expected-diagnostic diagnostic)}))))
	     (p15-s23-stage2-runtime-kernel-rejected-plan-fixtures
	      stage2-plan))))

	(defn p15-s23-stage2-runtime-kernel-rejected-record
	  [records]
	  (let [expected (set (map :expected-diagnostic records))
	        observed (set (map :diagnostic records))
	        mismatches (remove :matches-expected? records)
	        matches? (and (= expected observed) (empty? mismatches))]
	    {:artifact :gravity/p15-s23-stage2-runtime-kernel-rejected-record
	     :expected-diagnostics (p15-s23-stage2-sort-values expected)
	     :observed-diagnostics (p15-s23-stage2-sort-values observed)
	     :fixture-count (count records)
	     :mismatch-count (count mismatches)
	     :records records
	     :status (if matches? :complete :failed)}))

	(defn p15-s23-stage2-runtime-kernel-evidence-link-record
	  [plan-emitter-artifact nucleus-artifact runtime-capability-artifact
	   accepted-artifact rejected-artifact]
	  (let [links {:stage2-plan-emitter
	               {:artifact (:kind plan-emitter-artifact)
	                :artifact-id (:artifact-id plan-emitter-artifact)
	                :present?
	                (= :gravity/p15-s23-stage2-plan-emitter-artifact
	                   (:kind plan-emitter-artifact))}
	               :stage2-compiler-nucleus
	               {:artifact (:kind nucleus-artifact)
	                :artifact-id (:artifact-id nucleus-artifact)
	                :present?
	                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
	                   (:kind nucleus-artifact))}
	               :runtime-manifest-and-capability-enforcement-report
	               {:artifact (:kind runtime-capability-artifact)
	                :artifact-id (:artifact-id runtime-capability-artifact)
	                :present?
	                (= :gravity/p15-s23-runtime-manifest-capability-enforcement-artifact
	                   (:kind runtime-capability-artifact))}
	               :accepted-app-execution-proof
	               {:artifact (:kind accepted-artifact)
	                :artifact-id (:artifact-id accepted-artifact)
	                :present?
	                (= :gravity/p15-s23-accepted-app-execution-artifact
	                   (:kind accepted-artifact))}
	               :rejected-app-diagnostic-proof
	               {:artifact (:kind rejected-artifact)
	                :artifact-id (:artifact-id rejected-artifact)
	                :present?
	                (= :gravity/p15-s23-rejected-app-diagnostic-artifact
	                   (:kind rejected-artifact))}}
	        missing (set (for [[k v] links :when (not (:present? v))] k))]
	    {:artifact :gravity/p15-s23-stage2-runtime-kernel-evidence-link-record
	     :present-links links
	     :missing-links (p15-s23-stage2-sort-values missing)
	     :all-required-links-present? (empty? missing)
	     :status (if (empty? missing) :complete :failed)}))

	(defn p15-s23-stage2-runtime-kernel-boundary-record
	  [kernel]
	  (let [claims (:self-hosting-claims kernel)
	        seed-boundary (:seed-boundary kernel)]
	    {:artifact :gravity/p15-s23-stage2-runtime-kernel-boundary-record
	     :implemented-by (:implemented-by kernel)
	     :executed-by (:executed-by kernel)
	     :verified-by (:verified-by kernel)
	     :compiled-by (:compiled-by kernel)
	     :stage2-runtime-kernel-used?
	     (= :gravity-stage2-runtime-kernel (:executed-by kernel))
	     :stage2-runtime-host-replaced?
	     (= :replaced-by-stage2-runtime-kernel
	        (:stage0-runtime-host-boundary seed-boundary))
	     :stage2-runtime-primitives-replaced?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :clojure-stage0-runtime-host?
	     (= :clojure-stage0-runtime-host (:executed-by kernel))
	     :clojure-host-primitive-boundary?
	     (= :clojure-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :gravity-runtime-primitives?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :clojure-stage0-verifier?
	     (= :clojure-stage0 (:verified-by kernel))
	     :clojure-stage0-compiler?
	     (= :clojure-stage0 (:compiled-by kernel))
	     :self-hosted-compiler? false
	     :full-language-compiler-self-hosted?
	     (:full-language-compiler-self-hosted? claims)
	     :clojure-seed-retired? (:clojure-seed-retired? claims)
	     :seed-boundary seed-boundary
	     :next-required-capability (:next-required-capability kernel)
	     :status :complete}))

	(defn p15-s23-stage2-runtime-kernel-diagnostics
	  [source-path candidate]
	  (let [kernel (:kernel-contract candidate)
	        rule-record (:rule-record candidate)
	        accepted-record (:accepted-record candidate)
	        rejected-record (:rejected-record candidate)
	        evidence-link-record (:evidence-link-record candidate)
	        boundary-record (:boundary-record candidate)
	        claims (:self-hosting-claims kernel)
	        preserves (set (:preserves kernel))
	        emits (set (:emits kernel))
	        missing-preserves
	        (set/difference
	         p15-s23-stage2-runtime-kernel-required-preserves
	         preserves)
	        missing-emits
	        (set/difference
	         p15-s23-stage2-runtime-kernel-required-emits
	         emits)]
	    (vec
	     (concat
	      (when-not (and (= :gravity/stage2-runtime-kernel
	                        (:artifact kernel))
	                     (= :p15-s23-stage2-runtime-kernel
	                        (:stage kernel))
	                     (= :gravity-source (:implemented-by kernel))
	                     (= :gravity-stage2-runtime-kernel
	                        (:executed-by kernel))
	                     (= :stage2-instruction-plan (:input kernel))
	                     (= :stage2-runtime-kernel-execution-record
	                        (:output kernel)))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K001" kernel
	          {:missing-fields [:artifact :stage :implemented-by
	                            :executed-by :input :output]})])
	      (when-not (= :complete (:status rule-record))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K002" rule-record
	          {:missing-instructions (:missing-instructions rule-record)
	           :missing-runtime-primitives
	           (:missing-runtime-primitives rule-record)})])
	      (when-not (= :complete (:status accepted-record))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K003" accepted-record
	          {:stage2-runtime-kernel-output
	           (:stage2-runtime-kernel-output accepted-record)
	           :stage0-instruction-runner-output
	           (:stage0-instruction-runner-output accepted-record)
	           :expected-stdout (:expected-stdout accepted-record)})])
	      (when-not (= :complete (:status rejected-record))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K004" rejected-record
	          {:expected-diagnostics (:expected-diagnostics rejected-record)
	           :observed-diagnostics (:observed-diagnostics rejected-record)})])
	      (when-not (= :complete (:status evidence-link-record))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K005" evidence-link-record
	          {:missing-links (:missing-links evidence-link-record)})])
	      (when (or (seq missing-preserves) (seq missing-emits))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K006" kernel
	          {:missing-preserves
	           (p15-s23-stage2-sort-values missing-preserves)
	           :missing-emits
	           (p15-s23-stage2-sort-values missing-emits)})])
	      (when-not (and (= :complete (:status boundary-record))
	                     (true? (:stage2-runtime-kernel-used?
	                             boundary-record))
	                     (true? (:stage2-runtime-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-primitives-replaced?
	                             boundary-record))
	                     (false? (:clojure-stage0-runtime-host?
	                              boundary-record))
	                     (false? (:clojure-host-primitive-boundary?
	                              boundary-record))
	                     (true? (:gravity-runtime-primitives?
	                             boundary-record))
	                     (true? (:clojure-stage0-verifier?
	                             boundary-record))
	                     (true? (:clojure-stage0-compiler?
	                             boundary-record))
	                     (false? (:full-language-compiler-self-hosted?
	                              boundary-record))
	                     (false? (:clojure-seed-retired?
	                              boundary-record)))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K007" boundary-record
	          {:required-boundary [:stage2-runtime-kernel-used
	                               :stage2-runtime-host-replaced
	                               :stage2-runtime-primitives-replaced
	                               :clojure-runtime-host-false
	                               :clojure-primitives-false
	                               :gravity-runtime-primitives
	                               :clojure-verifier-recorded
	                               :clojure-compiler-recorded
	                               :self-hosting-false
	                               :clojure-seed-retired-false]})])
	      (when (or (true? (:full-language-compiler-self-hosted? claims))
	                (true? (:clojure-seed-retired? claims)))
	        [(p15-s23-stage2-runtime-kernel-diagnostic-record
	          source-path "P15S23K008" claims
	          {:full-language-compiler-self-hosted?
	           (:full-language-compiler-self-hosted? claims)
	           :clojure-seed-retired?
	           (:clojure-seed-retired? claims)})])))))

	(defn p15-s23-stage2-runtime-kernel-diagnostic-stream
	  [source-path proof-id]
	  {:artifact :gravity/p15-s23-stage2-runtime-kernel-diagnostic-stream
	   :stage :p15-s23-stage2-runtime-kernel
	   :source-path source-path
	   :proof-id proof-id
	   :diagnostics
	   (mapv (fn [id]
	           {:artifact :gravity/diagnostic
	            :diagnostic-id (str "diag-" (str/lower-case id))
	            :diagnostic id
	            :severity :error
	            :stage :p15-s23-stage2-runtime-kernel
	            :message
	            (get p15-s23-stage2-runtime-kernel-diagnostic-messages
	                 id)})
	         p15-s23-stage2-runtime-kernel-diagnostic-ids)
	   :status :complete})

	(defn p15-s23-stage2-runtime-kernel-rejected-candidates
	  [candidate]
	  [{:fixture :internal-p15-s23-stage2-runtime-kernel-missing-contract
	    :candidate (assoc candidate :kernel-contract {})
	    :expected-diagnostic "P15S23K001"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-rule-gap
	    :candidate (assoc-in candidate [:rule-record :status] :failed)
	    :expected-diagnostic "P15S23K002"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-output-gap
	    :candidate (-> candidate
	                   (assoc-in [:accepted-record :status] :failed)
	                   (assoc-in [:accepted-record
	                              :accepted-output-equivalent?]
	                             false))
	    :expected-diagnostic "P15S23K003"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-rejected-gap
	    :candidate (-> candidate
	                   (assoc-in [:rejected-record :status] :failed)
	                   (assoc-in [:rejected-record :mismatch-count] 1))
	    :expected-diagnostic "P15S23K004"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-evidence-gap
	    :candidate (-> candidate
	                   (assoc-in [:evidence-link-record :status] :failed)
	                   (assoc-in [:evidence-link-record :missing-links]
	                             [:runtime-manifest-and-capability-enforcement-report]))
	    :expected-diagnostic "P15S23K005"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-preservation-gap
	    :candidate (assoc-in candidate [:kernel-contract :preserves] [])
	    :expected-diagnostic "P15S23K006"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-boundary-gap
	    :candidate (-> candidate
	                   (assoc-in [:boundary-record
	                              :stage2-runtime-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage0-runtime-host?]
	                             true))
	    :expected-diagnostic "P15S23K007"}
	   {:fixture :internal-p15-s23-stage2-runtime-kernel-overclaim
	    :candidate (-> candidate
	                   (assoc-in [:kernel-contract :self-hosting-claims
	                              :full-language-compiler-self-hosted?]
	                             true)
	                   (assoc-in [:kernel-contract :self-hosting-claims
	                              :clojure-seed-retired?]
	                             true))
	    :expected-diagnostic "P15S23K008"}])

	(defn p15-s23-stage2-runtime-kernel-rejected-proof-records
	  [source-path candidate]
	  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
	          {:fixture fixture
	           :status :rejected
	           :expected-diagnostic expected-diagnostic
	           :diagnostics
	           (p15-s23-stage2-runtime-kernel-diagnostics source-path
	                                                      candidate)})
	        (p15-s23-stage2-runtime-kernel-rejected-candidates
	         candidate)))

	(defn p15-s23-stage2-runtime-kernel-proof
	  [artifact]
	  (let [diagnostics
	        (set (map :diagnostic
	                  (get-in artifact
	                          [:p15-s23-stage2-runtime-kernel-diagnostic-stream
	                           :diagnostics])))
	        rejected-diagnostics
	        (set (mapcat #(map :diagnostic (:diagnostics %))
	                     (:rejected-p15-s23-stage2-runtime-kernel-fixtures
	                      artifact)))
	        accepted-record (:accepted-record artifact)
	        rejected-record (:rejected-record artifact)
	        boundary-record (:boundary-record artifact)]
	    {:stage2-runtime-kernel-authored-in-gravity? true
	     :status :in-progress
	     :task "P15-S23"
	     :stage2-runtime-kernel-present?
	     (= :gravity/stage2-runtime-kernel
	        (get-in artifact [:kernel-contract :artifact]))
	     :stage2-runtime-kernel-executed?
	     (true? (:stage2-runtime-kernel-executed? accepted-record))
	     :stage2-runtime-host-replaced?
	     (true? (:stage2-runtime-host-replaced? boundary-record))
	     :stage2-runtime-primitives-replaced?
	     (true? (:stage2-runtime-primitives-replaced?
	             boundary-record))
	     :gravity-runtime-primitives-used?
	     (true? (:gravity-runtime-primitives? boundary-record))
	     :accepted-output-equivalent?
	     (true? (:accepted-output-equivalent? accepted-record))
	     :entrypoint-result-equivalent?
	     (true? (:entrypoint-result-equivalent? accepted-record))
	     :instruction-summary-equivalent?
	     (true? (:instruction-summary-equivalent? accepted-record))
	     :effect-summary-equivalent?
	     (true? (:effect-summary-equivalent? accepted-record))
	     :rejected-diagnostics-equivalent?
	     (= :complete (:status rejected-record))
	     :does-not-use-clojure-stage0-runtime-host?
	     (false? (:clojure-stage0-runtime-host? boundary-record))
	     :does-not-use-clojure-runtime-primitives?
	     (false? (:clojure-host-primitive-boundary? boundary-record))
	     :residual-clojure-verifier-recorded?
	     (true? (:clojure-stage0-verifier? boundary-record))
	     :residual-clojure-compiler-recorded?
	     (true? (:clojure-stage0-compiler? boundary-record))
	     :does-not-claim-full-self-hosting?
	     (false? (:full-language-compiler-self-hosted? artifact))
	     :does-not-claim-clojure-seed-retirement?
	     (false? (:clojure-seed-retired? artifact))
	     :rejected-candidates-covered?
	     (= (set p15-s23-stage2-runtime-kernel-diagnostic-ids)
	        rejected-diagnostics)
	     :diagnostics-covered?
	     (= (set p15-s23-stage2-runtime-kernel-diagnostic-ids)
	        diagnostics)
	     :limitations
	     {:full-language-compiler-self-hosted? false
	      :clojure-seed-retired? false
	      :stage2-runtime-kernel-authored-in-gravity? true
	      :stage2-runtime-kernel-executed? true
	      :stage2-runtime-host-replaced? true
	      :stage2-runtime-primitives-replaced? true
	      :gravity-runtime-primitives? true
	      :clojure-stage0-runtime-host? false
	      :clojure-host-primitive-boundary? false
	      :clojure-stage0-verifier? true
	      :clojure-stage0-compiler? true
	      :full-self-hosted-toolchain? false
	      :next-required-capability
	      :implement_whole_language_compiler_stage_without_clojure_seed}}))

	(defn p15-s23-stage2-runtime-kernel-source-artifact*
	  [source-path]
	  (let [source-data (p15-s23-compiler-source-form-record source-path)
	        kernel
	        (p15-s23-compiler-def-value
	         source-path (:forms source-data)
	         'p15-s23-stage2-runtime-kernel)
	        emitter
	        (p15-s23-compiler-def-value
	         source-path (:forms source-data)
	         'p15-s23-stage2-plan-emitter)
	        rule-record
	        (p15-s23-stage2-runtime-kernel-rule-record kernel)
	        accepted-record
	        (p15-s23-stage2-runtime-kernel-accepted-record
	         kernel emitter)
	        rejected-fixture-records
	        (p15-s23-stage2-runtime-kernel-rejected-records
	         kernel emitter)
	        rejected-record
	        (p15-s23-stage2-runtime-kernel-rejected-record
	         rejected-fixture-records)
	        plan-emitter-artifact
	        (p15-s23-stage2-plan-emitter-source-artifact source-path)
	        nucleus-artifact
	        (p15-s23-stage2-compiler-nucleus-source-artifact source-path)
	        runtime-capability-artifact
	        (p15-s23-runtime-manifest-capability-enforcement-source-artifact
	         source-path)
	        accepted-artifact
	        (p15-s23-accepted-app-execution-source-artifact source-path)
	        rejected-artifact
	        (p15-s23-rejected-app-diagnostic-source-artifact source-path)
	        evidence-link-record
	        (p15-s23-stage2-runtime-kernel-evidence-link-record
	         plan-emitter-artifact nucleus-artifact
	         runtime-capability-artifact accepted-artifact
	         rejected-artifact)
	        boundary-record
	        (p15-s23-stage2-runtime-kernel-boundary-record kernel)
	        candidate {:kernel-contract kernel
	                   :rule-record rule-record
	                   :accepted-record accepted-record
	                   :rejected-record rejected-record
	                   :evidence-link-record evidence-link-record
	                   :boundary-record boundary-record}
	        diagnostics
	        (p15-s23-stage2-runtime-kernel-diagnostics source-path
	                                                  candidate)
	        _ (when (seq diagnostics)
	            (p15-s23-stage2-runtime-kernel-fail!
	             (:diagnostic (first diagnostics)) source-path candidate
	             {:diagnostics diagnostics}))
	        proof-id
	        (str "sha256:"
	             (sha256-hex
	              (pr-str {:source-path source-path
	                       :kernel kernel
	                       :stage2-plan-id
	                       (:stage2-plan-id accepted-record)
	                       :runtime-output
	                       (:stage2-runtime-kernel-output
	                        accepted-record)
	                       :rejected-diagnostics
	                       (:observed-diagnostics rejected-record)})))
	        rejected-proof-records
	        (p15-s23-stage2-runtime-kernel-rejected-proof-records
	         source-path candidate)
	        artifact-base
	        {:kind :gravity/p15-s23-stage2-runtime-kernel-artifact
	         :phase "15"
	         :task "P15-S23"
	         :stage :p15-s23-stage2-runtime-kernel
	         :source-path source-path
	         :proof-id proof-id
	         :kernel-contract kernel
	         :rule-record rule-record
	         :accepted-record accepted-record
	         :rejected-record rejected-record
	         :evidence-link-record evidence-link-record
	         :boundary-record boundary-record
	         :linked-artifacts
	         {:stage2-plan-emitter
	          (select-keys plan-emitter-artifact
	                       [:kind :artifact-id :proof-id])
	          :stage2-compiler-nucleus
	          (select-keys nucleus-artifact [:kind :artifact-id :proof-id])
	          :runtime-manifest-and-capability-enforcement-report
	          (select-keys runtime-capability-artifact
	                       [:kind :artifact-id :proof-id])
	          :accepted-app-execution-proof
	          (select-keys accepted-artifact [:kind :artifact-id :proof-id])
	          :rejected-app-diagnostic-proof
	          (select-keys rejected-artifact [:kind :artifact-id :proof-id])}
	         :full-language-compiler-self-hosted?
	         (get-in kernel
	                 [:self-hosting-claims
	                  :full-language-compiler-self-hosted?])
	         :clojure-seed-retired?
	         (get-in kernel [:self-hosting-claims
	                         :clojure-seed-retired?])
	         :accepted-p15-s23-stage2-runtime-kernel-fixtures
	         [{:fixture p15-s23-accepted-app-source-path
	           :status :accepted
	           :stage2-plan-id (:stage2-plan-id accepted-record)
	           :stdout (:stage2-runtime-kernel-output accepted-record)}]
	         :verified-p15-s23-stage2-runtime-kernel-rejected-fixtures
	         rejected-fixture-records
	         :rejected-p15-s23-stage2-runtime-kernel-fixtures
	         rejected-proof-records
	         :p15-s23-stage2-runtime-kernel-diagnostic-stream
	         (p15-s23-stage2-runtime-kernel-diagnostic-stream
	          source-path proof-id)
	         :p15-s23-stage2-runtime-kernel-results
	         {:accepted-fixtures 1
	          :rejected-fixtures (count rejected-fixture-records)
	          :internal-rejected-fixtures (count rejected-proof-records)
	          :diagnostic-count
	          (count p15-s23-stage2-runtime-kernel-diagnostic-ids)
	          :stage2-plan-id (:stage2-plan-id accepted-record)
	          :accepted-output (:stage2-runtime-kernel-output
	                            accepted-record)
	          :rejected-diagnostics (:observed-diagnostics rejected-record)
	          :status :in-progress}
	         :diagnostics []}
	        proof (p15-s23-stage2-runtime-kernel-proof artifact-base)]
	    (assoc artifact-base
	           :capability-based-proof proof
	           :artifact-id
	           (c4-artifact-id
	            (assoc artifact-base :capability-based-proof proof)))))

	(defn p15-s23-stage2-runtime-kernel-source-artifact
	  [source-path]
	  (p15-s23-cached-source-artifact
	   :p15-s23-stage2-runtime-kernel
	   source-path
	   #(p15-s23-stage2-runtime-kernel-source-artifact* source-path)))

	(defn p15-s23-stage2-runtime-kernel-file-artifact
	  [path]
	  (when-not (.isFile (java.io.File. path))
	    (p15-s23-stage2-runtime-kernel-fail!
	     "P15S23K001" path nil {:missing-fields [:compiler-source]}))
	  (p15-s23-stage2-runtime-kernel-source-artifact path))

	(defn p15-s23-stage2-runtime-kernel-evidence
	  []
	  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
	    (when (.isFile (java.io.File. source-path))
	      (try
	        (let [artifact
	              (p15-s23-stage2-runtime-kernel-file-artifact
	               source-path)
	              proof (:capability-based-proof artifact)]
	          {:status :verified
	           :artifact (:kind artifact)
	           :artifact-id (:artifact-id artifact)
	           :proof-id (:proof-id artifact)
	           :source-path source-path
	           :stage2-plan-id
	           (get-in artifact [:accepted-record :stage2-plan-id])
	           :stage2-runtime-kernel-executed?
	           (:stage2-runtime-kernel-executed? proof)
	           :stage2-runtime-host-replaced?
	           (:stage2-runtime-host-replaced? proof)
	           :stage2-runtime-primitives-replaced?
	           (:stage2-runtime-primitives-replaced? proof)
	           :gravity-runtime-primitives-used?
	           (:gravity-runtime-primitives-used? proof)
	           :accepted-output-equivalent?
	           (:accepted-output-equivalent? proof)
	           :rejected-diagnostics-equivalent?
	           (:rejected-diagnostics-equivalent? proof)
	           :does-not-use-clojure-stage0-runtime-host?
	           (:does-not-use-clojure-stage0-runtime-host? proof)
	           :does-not-use-clojure-runtime-primitives?
	           (:does-not-use-clojure-runtime-primitives? proof)
	           :residual-clojure-verifier-recorded?
	           (:residual-clojure-verifier-recorded? proof)
	           :residual-clojure-compiler-recorded?
	           (:residual-clojure-compiler-recorded? proof)
	           :full-language-compiler-self-hosted?
	           (:full-language-compiler-self-hosted? artifact)
	           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
	        (catch Exception _
	          nil)))))

	(defn p15-s23-stage2-runtime-executor-accepted-record
	  [runtime emitter]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        stage2-plan
        (p15-s23-stage2-plan-emitter-compile-source
         emitter source-path source-text)
        runtime-output
        (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
        stage0-output (execute-stage0-compiled-plan stage2-plan)
        expected-stdout (get-in runtime
                                [:accepted-scope :expected-stdout])
        accepted-output-equivalent?
        (and (= (:stdout runtime-output) stage0-output)
             (= (:stdout runtime-output) expected-stdout))
        entrypoint-result-equivalent?
        (nil? (:entrypoint-result runtime-output))
        summary-equivalent?
        (= (:instruction-summary runtime-output)
           (:instruction-summary stage2-plan))
        effect-summary-equivalent?
        (= (:effect-summary runtime-output)
           (:effect-summary stage2-plan))
        equivalent?
        (and accepted-output-equivalent?
             entrypoint-result-equivalent?
             summary-equivalent?
             effect-summary-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-runtime-executor-accepted-record
     :fixture source-path
     :stage2-plan-id (:plan-id stage2-plan)
     :stage2-plan-kind (:kind stage2-plan)
     :entrypoint (:entrypoint stage2-plan)
     :runtime-execution-record runtime-output
     :stage2-runtime-executed? true
     :stage0-instruction-runner-output stage0-output
     :stage2-runtime-output (:stdout runtime-output)
     :expected-stdout expected-stdout
     :entrypoint-result-equivalent? entrypoint-result-equivalent?
     :instruction-summary-equivalent? summary-equivalent?
     :effect-summary-equivalent? effect-summary-equivalent?
     :accepted-output-equivalent? accepted-output-equivalent?
     :status (if equivalent? :complete :failed)}))

(defn p15-s23-stage2-runtime-executor-rejected-plan-fixtures
  [stage2-plan]
  (let [function-arity-plan
        (assoc-in stage2-plan
                  [:functions 'main :instructions]
                  [{:op :function-call
                    :function 'total
                    :args [{:op :literal :value 5}]}])
        builtin-arity-plan
        (assoc-in stage2-plan
                  [:functions 'main :instructions]
                  [{:op :builtin-call
                    :function 'assoc
                    :args [{:op :map-literal :entries []}
                           {:op :quote :value :missing-value}]}])]
    [{:fixture :internal-stage2-runtime-function-arity-plan
      :expected-diagnostic "L2-FUNCTION-ARITY"
      :rejected-design :wrong-user-function-arity
      :plan function-arity-plan}
     {:fixture :internal-stage2-runtime-builtin-arity-plan
      :expected-diagnostic "L2-BUILTIN-ARITY"
      :rejected-design :wrong-builtin-arity
      :plan builtin-arity-plan}]))

(defn p15-s23-stage2-runtime-executor-rejected-records
  [runtime emitter]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        stage2-plan
        (p15-s23-stage2-plan-emitter-compile-source
         emitter source-path source-text)]
    (mapv
     (fn [{:keys [fixture expected-diagnostic rejected-design plan]}]
       (try
         (let [runtime-output
               (p15-s23-stage2-runtime-execute-plan runtime plan)]
           {:fixture fixture
            :rejected-design rejected-design
            :expected-diagnostic expected-diagnostic
            :status :accepted-unexpectedly
            :runtime-output runtime-output
            :plan-id (:plan-id plan)
            :matches-expected? false})
         (catch clojure.lang.ExceptionInfo ex
           (let [data (ex-data ex)
                 diagnostic (:id data)]
             {:fixture fixture
              :rejected-design rejected-design
              :expected-diagnostic expected-diagnostic
              :status :rejected
              :diagnostic diagnostic
              :message (:message data)
              :diagnostic-data data
              :plan-id
              (str "sha256:" (sha256-hex (pr-str plan)))
              :matches-expected?
              (= expected-diagnostic diagnostic)}))))
     (p15-s23-stage2-runtime-executor-rejected-plan-fixtures
      stage2-plan))))

(defn p15-s23-stage2-runtime-executor-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact :gravity/p15-s23-stage2-runtime-executor-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

	(defn p15-s23-stage2-runtime-executor-evidence-link-record
	  [runtime-kernel-artifact plan-emitter-artifact nucleus-artifact
	   accepted-artifact rejected-artifact]
	  (let [links {:stage2-runtime-kernel
	               {:artifact (:kind runtime-kernel-artifact)
	                :artifact-id (:artifact-id runtime-kernel-artifact)
	                :present?
	                (= :gravity/p15-s23-stage2-runtime-kernel-artifact
	                   (:kind runtime-kernel-artifact))}
	               :stage2-plan-emitter
	               {:artifact (:kind plan-emitter-artifact)
	                :artifact-id (:artifact-id plan-emitter-artifact)
                :present?
                (= :gravity/p15-s23-stage2-plan-emitter-artifact
                   (:kind plan-emitter-artifact))}
               :stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :accepted-app-execution-proof
               {:artifact (:kind accepted-artifact)
                :artifact-id (:artifact-id accepted-artifact)
                :present?
                (= :gravity/p15-s23-accepted-app-execution-artifact
                   (:kind accepted-artifact))}
               :rejected-app-diagnostic-proof
               {:artifact (:kind rejected-artifact)
                :artifact-id (:artifact-id rejected-artifact)
                :present?
                (= :gravity/p15-s23-rejected-app-diagnostic-artifact
                   (:kind rejected-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact :gravity/p15-s23-stage2-runtime-executor-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-runtime-executor-boundary-record
  [runtime]
  (let [claims (:self-hosting-claims runtime)
        seed-boundary (:seed-boundary runtime)]
    {:artifact :gravity/p15-s23-stage2-runtime-executor-boundary-record
     :implemented-by (:implemented-by runtime)
     :executed-by (:executed-by runtime)
     :compiled-by (get-in runtime [:lineage :compiled-by])
     :stage0-instruction-runner-replaced? true
     :stage2-runtime-executed? true
	     :stage2-runtime-authored-in-gravity?
	     (= :gravity-source (:implemented-by runtime))
	     :stage2-runtime-kernel-used?
	     (= :gravity-stage2-runtime-kernel (:executed-by runtime))
	     :stage2-runtime-host-replaced?
	     (= :replaced-by-stage2-runtime-kernel
	        (:stage0-runtime-host-boundary seed-boundary))
	     :stage2-runtime-primitives-replaced?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :clojure-instruction-runner? false
	     :clojure-stage0-runtime-host?
	     (= :clojure-stage0-runtime-host (:executed-by runtime))
     :clojure-stage0-rule-runner?
     (= :clojure-stage0-rule-runner
        (:stage0-rule-runner-boundary seed-boundary))
	     :clojure-host-primitive-boundary?
	     (= :clojure-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :gravity-runtime-primitives?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
     :self-hosted-compiler? false
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary seed-boundary
     :next-required-capability (:next-required-capability runtime)
     :status :complete}))

(defn p15-s23-stage2-runtime-executor-diagnostics
  [source-path candidate]
  (let [runtime (:runtime-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims runtime)
        preserves (set (:preserves runtime))
        emits (set (:emits runtime))
        missing-preserves
        (set/difference
         p15-s23-stage2-runtime-executor-required-preserves
         preserves)
        missing-emits
        (set/difference p15-s23-stage2-runtime-executor-required-emits
                        emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-runtime-executor
                        (:artifact runtime))
                     (= :p15-s23-stage2-runtime-executor
                        (:stage runtime))
                     (= :gravity-source (:implemented-by runtime))
	                     (= :gravity-stage2-runtime-kernel
	                        (:executed-by runtime)))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X001" runtime
	          {:missing-fields [:artifact :stage :implemented-by
	                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X002" rule-record
          {:missing-instructions (:missing-instructions rule-record)
           :missing-builtin-functions
           (:missing-builtin-functions rule-record)})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X003" accepted-record
          {:stage2-runtime-output
           (:stage2-runtime-output accepted-record)
           :stage0-instruction-runner-output
           (:stage0-instruction-runner-output accepted-record)
           :expected-stdout (:expected-stdout accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X004" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X005" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X006" runtime
          {:missing-preserves (p15-s23-stage2-sort-values
                               missing-preserves)
           :missing-emits (p15-s23-stage2-sort-values
                           missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage0-instruction-runner-replaced?
                             boundary-record))
	                     (true? (:stage2-runtime-executed?
	                             boundary-record))
	                     (true? (:stage2-runtime-kernel-used?
	                             boundary-record))
	                     (true? (:stage2-runtime-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-primitives-replaced?
	                             boundary-record))
	                     (false? (:clojure-stage0-runtime-host?
	                              boundary-record))
	                     (false? (:clojure-host-primitive-boundary?
	                              boundary-record))
	                     (true? (:gravity-runtime-primitives?
	                             boundary-record))
	                     (true? (:clojure-stage0-rule-runner?
	                             boundary-record))
                     (false? (:clojure-instruction-runner?
                              boundary-record))
                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X007" boundary-record
	          {:required-boundary [:stage0-instruction-runner-replaced
	                               :stage2-runtime-executed
	                               :stage2-runtime-kernel-used
	                               :stage2-runtime-host-replaced
	                               :stage2-runtime-primitives-replaced
	                               :clojure-runtime-host-false
	                               :clojure-primitives-false
	                               :gravity-runtime-primitives
	                               :clojure-stage0-rule-runner
	                               :clojure-instruction-runner-false
                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-runtime-executor-diagnostic-record
          source-path "P15S23X008" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-runtime-executor-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage2-runtime-executor-diagnostic-stream
   :stage :p15-s23-stage2-runtime-executor
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-runtime-executor
            :message
            (get p15-s23-stage2-runtime-executor-diagnostic-messages id)})
         p15-s23-stage2-runtime-executor-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-runtime-executor-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-runtime-executor-missing-contract
    :candidate (assoc candidate :runtime-contract {})
    :expected-diagnostic "P15S23X001"}
   {:fixture :internal-p15-s23-stage2-runtime-executor-rule-gap
