  #{:scan-characters :classify-tokens :build-forms
    :build-syntax-objects :expand-built-in-macros
    :validate-module-contract :emit-front-end-record})

(def p15-s23-stage2-source-front-end-diagnostic-messages
  {"P15S23F001" "P15-S23 stage2 source front-end contract is missing"
   "P15S23F002" "P15-S23 stage2 source front-end rule set is incomplete"
   "P15S23F003" "P15-S23 stage2 source front-end macro expansion is incomplete"
   "P15S23F004" "P15-S23 stage2 source front-end accepted output is not equivalent"
   "P15S23F005" "P15-S23 stage2 source front-end rejected diagnostics are not preserved"
   "P15S23F006" "P15-S23 stage2 source front-end evidence links are incomplete"
   "P15S23F007" "P15-S23 stage2 source front-end preservation or emission contract is incomplete"
   "P15S23F008" "P15-S23 stage2 source front-end boundary record is incomplete"
   "P15S23F009" "P15-S23 stage2 source front-end rejected malformed source or overclaim"})

(def p15-s23-stage2-source-front-end-diagnostic-ids
  ["P15S23F001" "P15S23F002" "P15S23F003" "P15S23F004"
   "P15S23F005" "P15S23F006" "P15S23F007" "P15S23F008"
   "P15S23F009"])

(defn p15-s23-stage2-source-front-end-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-source-front-end-diagnostic-messages
              id
              "P15-S23 stage2 source front-end proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-source-front-end
                 :diagnostic-family :p15-s23-stage2-source-front-end
                 :value value
                 :remediation "Keep the stage2 reader and macro front-end rules authored in Gravity source, execute accepted and rejected fixtures through the declared front-end boundary, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-source-front-end-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-source-front-end
   :source-span {:source source-path}
   :message (get p15-s23-stage2-source-front-end-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_source_front_end})

(defonce p15-s23-source-artifact-cache
  (atom {}))

(defn p15-s23-source-artifact-cache-key
  [kind source-path]
  (let [file (java.io.File. source-path)]
    [kind (.getCanonicalPath file) (.lastModified file) (.length file)]))

(defn p15-s23-cached-source-artifact
  [kind source-path build-fn]
  (let [cache-key (p15-s23-source-artifact-cache-key kind source-path)]
    (if-let [artifact (get @p15-s23-source-artifact-cache cache-key)]
      artifact
      (let [artifact (build-fn)]
        (swap! p15-s23-source-artifact-cache assoc cache-key artifact)
        artifact))))

(defn p15-s23-front-end-state
  [source-path source-text]
  {:source-path source-path
   :source-text source-text
   :idx 0
   :line 1
   :column 1})

(defn p15-s23-front-end-current-char
  [state]
  (let [idx (:idx state)
        text (:source-text state)]
    (when (< idx (count text))
      (nth text idx))))

(defn p15-s23-front-end-advance
  [state]
  (let [ch (p15-s23-front-end-current-char state)
        previous-cr?
        (and (= \newline ch)
             (pos? (:idx state))
             (= \return (.charAt ^String (:source-text state)
                                 (dec (:idx state)))))]
    (cond
      (= \return ch)
      (-> state
          (update :idx inc)
          (assoc :line (inc (:line state)) :column 1))

      (and (= \newline ch) (not previous-cr?))
      (-> state
          (update :idx inc)
          (assoc :line (inc (:line state)) :column 1))

      previous-cr?
      (update state :idx inc)

      :else
      (-> state
          (update :idx inc)
          (update :column inc)))))

(defn p15-s23-front-end-location
  [state]
  {:line (:line state)
   :column (:column state)
   :char (:idx state)
   :byte (utf8-byte-count (subs (:source-text state) 0 (:idx state)))})

(defn p15-s23-front-end-span
  [source-path form-index start-state end-state]
  {:source source-path
   :form-index form-index
   :start (p15-s23-front-end-location start-state)
   :end (p15-s23-front-end-location end-state)
   :byte-start (:byte (p15-s23-front-end-location start-state))
   :byte-end (:byte (p15-s23-front-end-location end-state))})

(defn p15-s23-front-end-reader-error!
  [source-path state data]
  (p15-s23-stage2-source-front-end-fail!
   "P15S23F009" source-path data
   (merge {:reader-state (select-keys state [:idx :line :column])}
          data)))

(defn p15-s23-front-end-skip-comment
  [state]
  (loop [state state]
    (let [ch (p15-s23-front-end-current-char state)]
      (cond
        (nil? ch) state
        (= \return ch)
        (let [advanced (p15-s23-front-end-advance state)]
          (if (= \newline (p15-s23-front-end-current-char advanced))
            (p15-s23-front-end-advance advanced)
            advanced))
        (= \newline ch) (p15-s23-front-end-advance state)
        :else (recur (p15-s23-front-end-advance state))))))

(defn p15-s23-front-end-skip-ignored
  [state]
  (loop [state state]
    (let [ch (p15-s23-front-end-current-char state)]
      (cond
        (nil? ch) state
        (Character/isWhitespace ^Character ch)
        (recur (p15-s23-front-end-advance state))
        (= \, ch)
        (recur (p15-s23-front-end-advance state))
        (= \; ch)
        (recur (p15-s23-front-end-skip-comment state))
        :else state))))

(defn p15-s23-front-end-delimiter?
  [ch]
  (or (nil? ch)
      (Character/isWhitespace ^Character ch)
      (contains? #{\( \) \[ \] \{ \} \" \;} ch)
      (= \, ch)))

(declare p15-s23-front-end-read-form)

(defn p15-s23-front-end-read-string
  [source-path state]
  (let [start state]
    (loop [state (p15-s23-front-end-advance state)
           chars []]
      (let [ch (p15-s23-front-end-current-char state)]
        (cond
          (nil? ch)
          (p15-s23-front-end-reader-error!
           source-path state {:reason :unclosed-string})
          (= \" ch)
          [(apply str chars) (p15-s23-front-end-advance state)]
          (= \\ ch)
          (let [escape-state (p15-s23-front-end-advance state)
                escape (p15-s23-front-end-current-char escape-state)]
            (when (nil? escape)
              (p15-s23-front-end-reader-error!
               source-path escape-state {:reason :unclosed-string-escape}))
            (recur (p15-s23-front-end-advance escape-state)
                   (conj chars
                         (case escape
                           \n \newline
                           \t \tab
                           \r \return
                           \" \"
                           \\ \\
                           escape))))
          :else
          (recur (p15-s23-front-end-advance state)
                 (conj chars ch)))))))

(defn p15-s23-front-end-read-token
  [state]
  (loop [state state
         chars []]
    (let [ch (p15-s23-front-end-current-char state)]
      (if (p15-s23-front-end-delimiter? ch)
        [(apply str chars) state]
        (recur (p15-s23-front-end-advance state) (conj chars ch))))))

(defn p15-s23-front-end-parse-token
  [source-path state token]
  (cond
    (= "nil" token) nil
    (= "true" token) true
    (= "false" token) false
    (str/starts-with? token ":") (keyword (subs token 1))
    (re-matches #"-?[0-9]+" token) (Long/parseLong token)
    (seq token) (symbol token)
    :else
    (p15-s23-front-end-reader-error!
     source-path state {:reason :empty-token})))

(defn p15-s23-front-end-read-coll
  [source-path state form-index close-ch kind]
  (loop [state (p15-s23-front-end-skip-ignored
                (p15-s23-front-end-advance state))
         values []]
    (let [ch (p15-s23-front-end-current-char state)]
      (cond
        (nil? ch)
        (p15-s23-front-end-reader-error!
         source-path state {:reason :unclosed-form :expected close-ch})
        (= close-ch ch)
        (let [end-state (p15-s23-front-end-advance state)]
          [(case kind
             :list (apply list values)
             :vector (vec values)
             :map (do
                    (when (odd? (count values))
                      (p15-s23-front-end-reader-error!
                       source-path state {:reason :odd-map}))
                    (into {} (partition 2 values)))
             :set (set values))
           end-state])
        (contains? #{\) \] \}} ch)
        (p15-s23-front-end-reader-error!
         source-path state {:reason :unexpected-close :found ch})
        :else
        (let [[record next-state]
              (p15-s23-front-end-read-form source-path state form-index)]
          (recur (p15-s23-front-end-skip-ignored next-state)
                 (conj values (:form record))))))))

(defn p15-s23-front-end-read-form
  [source-path state form-index]
  (let [state (p15-s23-front-end-skip-ignored state)
        start-state state
        ch (p15-s23-front-end-current-char state)]
    (when (nil? ch)
      (p15-s23-front-end-reader-error!
       source-path state {:reason :unexpected-eof}))
    (let [[form end-state]
          (case ch
            \( (p15-s23-front-end-read-coll
                source-path state form-index \) :list)
            \[ (p15-s23-front-end-read-coll
                source-path state form-index \] :vector)
            \{ (p15-s23-front-end-read-coll
                source-path state form-index \} :map)
            \" (p15-s23-front-end-read-string source-path state)
            \# (let [dispatch-state (p15-s23-front-end-advance state)
                     dispatch (p15-s23-front-end-current-char dispatch-state)]
                 (if (= \{ dispatch)
                   (p15-s23-front-end-read-coll
                    source-path dispatch-state form-index \} :set)
                   (p15-s23-front-end-reader-error!
                    source-path state
                    {:reason :unsupported-dispatch
                     :dispatch dispatch})))
            (if (contains? #{\) \] \}} ch)
              (p15-s23-front-end-reader-error!
               source-path state {:reason :unexpected-close :found ch})
              (let [[token end-state] (p15-s23-front-end-read-token state)]
                [(p15-s23-front-end-parse-token source-path state token)
                 end-state])))]
      [{:form form
        :span (p15-s23-front-end-span source-path form-index
                                      start-state end-state)
        :metadata {}
        :reader-origin {:kind :stage2-source-front-end
                        :raw-form-kind (form-kind form)
                        :engine :gravity-stage2-reader-rules-v1}
        :generated-origin []}
       end-state])))

(defn p15-s23-stage2-front-end-read-source-form-records
  [front-end source-path source-text]
  (when-not (= :gravity-stage2-reader-rules-v1
               (get-in front-end [:reader-rules :engine]))
    (p15-s23-stage2-source-front-end-fail!
     "P15S23F002" source-path front-end
     {:missing-fields [:reader-rules :engine]}))
  (loop [state (p15-s23-front-end-skip-ignored
                (p15-s23-front-end-state source-path source-text))
         form-index 0
         records []]
    (if (nil? (p15-s23-front-end-current-char state))
      records
      (let [[record next-state]
            (p15-s23-front-end-read-form source-path state form-index)]
        (recur (p15-s23-front-end-skip-ignored next-state)
               (inc form-index)
               (conj records record))))))

(defn p15-s23-stage2-front-end-expand-form
  [front-end syntax]
  (let [form (:form syntax)]
    (if (and (seq? form) (= 'defn (first form)))
      (let [[_ name params & body] form]
        (when-not (and (symbol? name) (vector? params))
          (p15-s23-stage2-source-front-end-fail!
           "P15S23F003" (get-in syntax [:span :source]) form
           {:reason :invalid-defn-shape}))
        (let [expanded (list 'def name (cons 'fn (cons params body)))]
          (-> syntax
              (assoc :form expanded
                     :origin :generated
                     :phase :macro-expanded
                     :macro-namespace 'gravity.core
                     :generated-origin
                     [{:from (:span syntax)
                       :macro 'gravity.core/defn
                       :macro-version "stage2-front-end"
                       :input-hash (str "sha256:"
                                        (sha256-hex (pr-str form)))
                       :output-hash (str "sha256:"
                                         (sha256-hex
                                          (pr-str expanded)))}])
              (update :hygiene conj {:macro 'gravity.core/defn
                                     :policy :hygienic}))))
      (assoc syntax :phase :macro-expanded))))

(defn p15-s23-stage2-front-end-source-module-record
  [front-end source-path source-text]
  (let [records
        (p15-s23-stage2-front-end-read-source-form-records
         front-end source-path source-text)
        forms (mapv :form records)
        _ (validate-ns-syntax! source-path forms)
        module (parse-module source-path forms)
        syntax (syntax-object-stream source-path records module)
        expanded-syntax
        (mapv #(p15-s23-stage2-front-end-expand-form front-end %) syntax)
        body-syntax (subvec expanded-syntax 1)
        expanded-forms (mapv :form body-syntax)
        trace (->> body-syntax
                   (filter #(seq (:generated-origin %)))
                   (mapv (fn [syn]
                           {:macro 'gravity.core/defn
                            :macro-version "stage2-front-end"
                            :caller-namespace (:module module)
                            :caller-profile (:profile module)
                            :call-span (:span syn)
                            :input-syntax-id (:syntax-id syn)
                            :generated-origin (:generated-origin syn)
                            :hygiene-policy :hygienic
                            :diagnostics []})))]
    {:artifact :gravity/p15-s23-stage2-front-end-module-record
     :source-path source-path
     :source-id (str "sha256:" (sha256-hex source-text))
     :records records
     :forms forms
     :module (assoc module :forms expanded-forms)
     :syntax-object-stream syntax
     :expanded-syntax-object-stream expanded-syntax
     :expanded-forms expanded-forms
     :macro-expansion-trace trace
     :status :complete}))

(def p15-s23-stage2-front-end-executor-required-preserves
  #{:source-spans :source-unit-identity :syntax-identity
    :generated-origin :diagnostic-codes :effects :capabilities
    :profile :compiler-lineage :artifact-provenance})

(def p15-s23-stage2-front-end-executor-required-emits
  #{:stage2-front-end-execution-record :stage2-reader-record
    :stage2-macro-expansion-record :module-context
    :expanded-core-forms :accepted-front-end-executor-comparison
    :rejected-diagnostic-comparison
    :stage2-front-end-executor-boundary-record})

(def p15-s23-stage2-front-end-executor-required-steps
  #{:load-front-end-contract :execute-reader-rules
    :execute-syntax-object-builder :execute-built-in-macro-rules
    :validate-module-contract :compare-reference-front-end
    :emit-executor-boundary-record})

(def p15-s23-stage2-front-end-executor-diagnostic-messages
  {"P15S23J001" "P15-S23 stage2 front-end executor contract is missing"
   "P15S23J002" "P15-S23 stage2 front-end executor rule set is incomplete"
   "P15S23J003" "P15-S23 stage2 front-end executor accepted output is not equivalent"
   "P15S23J004" "P15-S23 stage2 front-end executor rejected diagnostics are not preserved"
   "P15S23J005" "P15-S23 stage2 front-end executor evidence links are incomplete"
   "P15S23J006" "P15-S23 stage2 front-end executor preservation or emission contract is incomplete"
   "P15S23J007" "P15-S23 stage2 front-end executor boundary record is incomplete"
   "P15S23J008" "P15-S23 stage2 front-end executor makes an unsupported self-hosting or seed-retirement claim"})

(def p15-s23-stage2-front-end-executor-diagnostic-ids
  ["P15S23J001" "P15S23J002" "P15S23J003" "P15S23J004"
   "P15S23J005" "P15S23J006" "P15S23J007" "P15S23J008"])

(defn p15-s23-stage2-front-end-executor-fail!
  [id source-path value data]
  (fail! id
         (get p15-s23-stage2-front-end-executor-diagnostic-messages
              id
              "P15-S23 stage2 front-end executor proof failed")
         (merge {:source-span {:source source-path}
                 :stage :p15-s23-stage2-front-end-executor
                 :diagnostic-family
                 :p15-s23-stage2-front-end-executor
                 :value value
                 :remediation "Keep the stage2 front-end executor authored in Gravity source, prove accepted and rejected front-end behavior through that executor boundary, and keep full self-hosting claims false."}
                data)))

(defn p15-s23-stage2-front-end-executor-diagnostic-record
  [source-path id value data]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p15-s23-stage2-front-end-executor
   :source-span {:source source-path}
   :message
   (get p15-s23-stage2-front-end-executor-diagnostic-messages id)
   :facts data
   :observed value
   :remediation :repair_stage2_front_end_executor})

(defn p15-s23-stage2-front-end-executor-rule-record
  [executor]
  (let [steps (set (:executor-steps executor))
        missing-steps
        (set/difference
         p15-s23-stage2-front-end-executor-required-steps
         steps)
        complete?
        (and (= :gravity-stage2-front-end-executor-v1
                (:engine executor))
             (= :gravity-source (:implemented-by executor))
             (= :gravity-stage2-runtime-kernel (:executed-by executor))
             (empty? missing-steps))]
    {:artifact :gravity/p15-s23-stage2-front-end-executor-rule-record
     :engine (:engine executor)
     :implemented-by (:implemented-by executor)
     :executed-by (:executed-by executor)
     :executor-steps (p15-s23-stage2-sort-values steps)
     :missing-steps (p15-s23-stage2-sort-values missing-steps)
     :rule-set-complete? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-accepted-record
  [executor front-end emitter runtime]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        front-end-record
        (p15-s23-stage2-front-end-source-module-record
         front-end source-path source-text)
        module (:module front-end-record)
        stage2-plan (p15-s23-stage2-emitted-core-plan
                     emitter source-path source-text module)
        runtime-record
        (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
        reference-macro-artifact
        (macro-source-artifact source-path source-text)
        read-form-parity?
        (= (:forms front-end-record) (read-forms source-path source-text))
        macro-expanded-form-parity?
        (= (:expanded-forms front-end-record)
           (:expanded-forms reference-macro-artifact))
        syntax-count-parity?
        (= (count (:expanded-syntax-object-stream front-end-record))
           (count (:expanded-syntax-object-stream
                   reference-macro-artifact)))
        expected-stdout (get-in executor
                                [:accepted-scope :expected-stdout])
        output-equivalent? (= expected-stdout (:stdout runtime-record))
        complete?
        (and read-form-parity?
             macro-expanded-form-parity?
             syntax-count-parity?
             output-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-front-end-executor-accepted-record
     :fixture source-path
     :executor-engine (:engine executor)
     :front-end-engine (:engine front-end)
     :source-id (:source-id front-end-record)
     :form-count (count (:forms front-end-record))
     :expanded-form-count (count (:expanded-forms front-end-record))
     :macro-expansion-count (count (:macro-expansion-trace
                                    front-end-record))
     :stage2-plan-id (:plan-id stage2-plan)
     :stage2-runtime-execution-record runtime-record
     :stage2-front-end-executor-output (:stdout runtime-record)
     :expected-stdout expected-stdout
     :read-form-parity? read-form-parity?
     :macro-expanded-form-parity? macro-expanded-form-parity?
     :syntax-count-parity? syntax-count-parity?
     :accepted-output-equivalent? output-equivalent?
     :stage2-front-end-record
     (select-keys front-end-record
                  [:artifact :source-path :source-id :status])
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-rejected-records
  [executor front-end emitter runtime]
  (mapv
   (fn [{:keys [fixture expected-diagnostic rejected-design]}]
     (let [diagnostic
           (try
             (let [source-text (slurp fixture)
                   front-end-record
                   (p15-s23-stage2-front-end-source-module-record
                    front-end fixture source-text)
                   module (:module front-end-record)
                   stage2-plan
                   (p15-s23-stage2-emitted-core-plan
                    emitter fixture source-text module)]
               (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
               nil)
             (catch clojure.lang.ExceptionInfo ex
               (:id (ex-data ex))))]
       {:fixture fixture
        :rejected-design rejected-design
        :expected-diagnostic expected-diagnostic
        :status :rejected
        :diagnostic diagnostic
        :matches-expected? (= expected-diagnostic diagnostic)}))
   (:rejected-diagnostic-contract executor)))

(defn p15-s23-stage2-front-end-executor-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact
     :gravity/p15-s23-stage2-front-end-executor-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-evidence-link-record
  [runtime-kernel-artifact nucleus-artifact plan-emitter-artifact
   runtime-artifact pipeline-artifact]
  (let [links {:stage2-runtime-kernel
               {:artifact (:kind runtime-kernel-artifact)
                :artifact-id (:artifact-id runtime-kernel-artifact)
                :present?
                (= :gravity/p15-s23-stage2-runtime-kernel-artifact
                   (:kind runtime-kernel-artifact))}
               :stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :stage2-plan-emitter
               {:artifact (:kind plan-emitter-artifact)
                :artifact-id (:artifact-id plan-emitter-artifact)
                :present?
                (= :gravity/p15-s23-stage2-plan-emitter-artifact
                   (:kind plan-emitter-artifact))}
               :stage2-runtime-executor
               {:artifact (:kind runtime-artifact)
                :artifact-id (:artifact-id runtime-artifact)
                :present?
                (= :gravity/p15-s23-stage2-runtime-executor-artifact
                   (:kind runtime-artifact))}
               :compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact
     :gravity/p15-s23-stage2-front-end-executor-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-front-end-executor-boundary-record
  [executor]
  (let [claims (:self-hosting-claims executor)
        seed-boundary (:seed-boundary executor)]
    {:artifact
     :gravity/p15-s23-stage2-front-end-executor-boundary-record
     :implemented-by (:implemented-by executor)
     :executed-by (:executed-by executor)
     :compiled-by (get-in executor [:lineage :compiled-by])
     :stage2-front-end-executor-used? true
     :stage2-front-end-host-replaced? true
     :stage2-runtime-kernel-used?
     (= :gravity-stage2-runtime-kernel (:executed-by executor))
     :stage2-runtime-host-replaced?
     (= :replaced-by-stage2-runtime-kernel
        (:stage0-runtime-host-boundary seed-boundary))
     :stage2-runtime-primitives-replaced?
     (= :gravity-runtime-primitives
        (:host-primitive-boundary seed-boundary))
     :clojure-stage2-front-end-host? false
     :clojure-stage0-runtime-host?
     (= :clojure-stage0-runtime-host
        (:stage0-runtime-host-boundary seed-boundary))
     :clojure-host-primitive-boundary?
     (= :clojure-runtime-primitives
        (:host-primitive-boundary seed-boundary))
     :gravity-runtime-primitives?
     (= :gravity-runtime-primitives
        (:host-primitive-boundary seed-boundary))
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary seed-boundary
     :next-required-capability (:next-required-capability executor)
     :status :complete}))

(defn p15-s23-stage2-front-end-executor-diagnostics
  [source-path candidate]
  (let [executor (:executor-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims executor)
        preserves (set (:preserves executor))
        emits (set (:emits executor))
        missing-preserves
        (set/difference
         p15-s23-stage2-front-end-executor-required-preserves
         preserves)
        missing-emits
        (set/difference
         p15-s23-stage2-front-end-executor-required-emits
         emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-front-end-executor
                        (:artifact executor))
                     (= :p15-s23-stage2-front-end-executor
                        (:stage executor))
                     (= :gravity-source (:implemented-by executor))
                     (= :gravity-stage2-runtime-kernel
                        (:executed-by executor)))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J001" executor
          {:missing-fields [:artifact :stage :implemented-by
                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J002" rule-record
          {:missing-steps (:missing-steps rule-record)})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J003" accepted-record
          {:expected-stdout (:expected-stdout accepted-record)
           :stage2-front-end-executor-output
           (:stage2-front-end-executor-output accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J004" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J005" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J006" executor
          {:missing-preserves
           (p15-s23-stage2-sort-values missing-preserves)
           :missing-emits
           (p15-s23-stage2-sort-values missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage2-front-end-executor-used?
                             boundary-record))
                     (true? (:stage2-front-end-host-replaced?
                             boundary-record))
                     (true? (:stage2-runtime-kernel-used?
                             boundary-record))
                     (true? (:stage2-runtime-host-replaced?
                             boundary-record))
                     (true? (:stage2-runtime-primitives-replaced?
                             boundary-record))
                     (false? (:clojure-stage2-front-end-host?
                              boundary-record))
                     (false? (:clojure-stage0-runtime-host?
                              boundary-record))
                     (false? (:clojure-host-primitive-boundary?
                              boundary-record))
                     (true? (:gravity-runtime-primitives?
                             boundary-record))
                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J007" boundary-record
          {:required-boundary [:stage2-front-end-executor-used
                               :stage2-front-end-host-replaced
                               :stage2-runtime-kernel-used
                               :stage2-runtime-host-replaced
                               :stage2-runtime-primitives-replaced
                               :clojure-stage2-front-end-host-false
                               :clojure-runtime-host-false
                               :clojure-primitives-false
                               :gravity-runtime-primitives
                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-front-end-executor-diagnostic-record
          source-path "P15S23J008" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-front-end-executor-diagnostic-stream
  [source-path proof-id]
  {:artifact
   :gravity/p15-s23-stage2-front-end-executor-diagnostic-stream
   :stage :p15-s23-stage2-front-end-executor
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-front-end-executor
            :message
            (get p15-s23-stage2-front-end-executor-diagnostic-messages
                 id)})
         p15-s23-stage2-front-end-executor-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-front-end-executor-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-front-end-executor-missing-contract
    :candidate (assoc candidate :executor-contract {})
    :expected-diagnostic "P15S23J001"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-rule-gap
    :candidate (assoc-in candidate [:rule-record :status] :failed)
    :expected-diagnostic "P15S23J002"}
   {:fixture :internal-p15-s23-stage2-front-end-executor-output-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-record :status] :failed)
                   (assoc-in [:accepted-record
                              :accepted-output-equivalent?]
