    :expected-diagnostic "P15S23J008"}])

(defn p15-s23-stage2-front-end-executor-rejected-proof-records
  [source-path candidate]
  (mapv (fn [{:keys [fixture candidate expected-diagnostic]}]
          {:fixture fixture
           :status :rejected
           :expected-diagnostic expected-diagnostic
           :diagnostics
           (p15-s23-stage2-front-end-executor-diagnostics
            source-path candidate)})
        (p15-s23-stage2-front-end-executor-rejected-candidates
         candidate)))

(defn p15-s23-stage2-front-end-executor-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (get-in artifact
                          [:p15-s23-stage2-front-end-executor-diagnostic-stream
                           :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-p15-s23-stage2-front-end-executor-fixtures
                      artifact)))
        accepted-record (:accepted-record artifact)
        rejected-record (:rejected-record artifact)
        boundary-record (:boundary-record artifact)]
    {:stage2-front-end-executor-authored-in-gravity? true
     :status :in-progress
     :task "P15-S23"
     :stage2-front-end-executor-present?
     (= :gravity/stage2-front-end-executor
        (get-in artifact [:executor-contract :artifact]))
     :stage2-front-end-executor-used?
     (true? (:stage2-front-end-executor-used? boundary-record))
	     :stage2-front-end-host-replaced?
	     (true? (:stage2-front-end-host-replaced? boundary-record))
	     :stage2-runtime-kernel-used?
	     (true? (:stage2-runtime-kernel-used? boundary-record))
	     :stage2-runtime-host-replaced?
	     (true? (:stage2-runtime-host-replaced? boundary-record))
	     :stage2-runtime-primitives-replaced?
	     (true? (:stage2-runtime-primitives-replaced?
	             boundary-record))
	     :gravity-runtime-primitives-used?
	     (true? (:gravity-runtime-primitives? boundary-record))
     :does-not-use-clojure-stage2-front-end-host?
     (false? (:clojure-stage2-front-end-host? boundary-record))
     :read-form-parity?
     (true? (:read-form-parity? accepted-record))
     :macro-expanded-form-parity?
     (true? (:macro-expanded-form-parity? accepted-record))
	     :accepted-output-equivalent?
	     (true? (:accepted-output-equivalent? accepted-record))
		     :rejected-diagnostics-equivalent?
		     (= :complete (:status rejected-record))
		     :does-not-use-clojure-stage0-runtime-host?
		     (false? (:clojure-stage0-runtime-host? boundary-record))
	     :does-not-use-clojure-runtime-primitives?
	     (false? (:clojure-host-primitive-boundary? boundary-record))
     :does-not-claim-full-self-hosting?
     (false? (:full-language-compiler-self-hosted? artifact))
     :does-not-claim-clojure-seed-retirement?
     (false? (:clojure-seed-retired? artifact))
     :rejected-candidates-covered?
     (= (set p15-s23-stage2-front-end-executor-diagnostic-ids)
        rejected-diagnostics)
     :diagnostics-covered?
     (= (set p15-s23-stage2-front-end-executor-diagnostic-ids)
        diagnostics)
     :limitations
     {:full-language-compiler-self-hosted? false
      :clojure-seed-retired? false
	      :stage2-front-end-executor-authored-in-gravity? true
	      :stage2-front-end-executor-used? true
	      :stage2-front-end-host-replaced? true
	      :stage2-runtime-kernel-used? true
	      :stage2-runtime-host-replaced? true
	      :stage2-runtime-primitives-replaced? true
	      :gravity-runtime-primitives? true
	      :clojure-stage2-front-end-host? false
	      :clojure-stage0-runtime-host? false
	      :clojure-host-primitive-boundary? false
	      :full-self-hosted-toolchain? false
	      :next-required-capability
	      :implement_whole_language_compiler_stage_without_clojure_seed}}))

(defn p15-s23-stage2-front-end-executor-source-artifact*
  [source-path]
  (let [source-data (p15-s23-compiler-source-form-record source-path)
        executor
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-front-end-executor)
        front-end
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-source-front-end)
        emitter
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-plan-emitter)
        runtime
        (p15-s23-compiler-def-value
         source-path (:forms source-data)
         'p15-s23-stage2-runtime-executor)
        rule-record
        (p15-s23-stage2-front-end-executor-rule-record executor)
        accepted-record
        (p15-s23-stage2-front-end-executor-accepted-record
         executor front-end emitter runtime)
        rejected-fixture-records
        (p15-s23-stage2-front-end-executor-rejected-records
         executor front-end emitter runtime)
	        rejected-record
	        (p15-s23-stage2-front-end-executor-rejected-record
	         rejected-fixture-records)
	        runtime-kernel-artifact
	        (p15-s23-stage2-runtime-kernel-source-artifact source-path)
	        nucleus-artifact
	        (p15-s23-stage2-compiler-nucleus-source-artifact source-path)
	        plan-emitter-artifact
	        (p15-s23-stage2-plan-emitter-source-artifact source-path)
	        runtime-kernel-artifact
	        (p15-s23-stage2-runtime-kernel-source-artifact source-path)
	        runtime-artifact
	        (p15-s23-stage2-runtime-executor-source-artifact source-path)
        pipeline-artifact
        (p15-s23-compiler-pipeline-manifest-source-artifact
         source-path)
	        evidence-link-record
	        (p15-s23-stage2-front-end-executor-evidence-link-record
	         runtime-kernel-artifact nucleus-artifact plan-emitter-artifact
	         runtime-artifact pipeline-artifact)
        boundary-record
        (p15-s23-stage2-front-end-executor-boundary-record executor)
        candidate {:executor-contract executor
                   :rule-record rule-record
                   :accepted-record accepted-record
                   :rejected-record rejected-record
                   :evidence-link-record evidence-link-record
                   :boundary-record boundary-record}
        diagnostics
        (p15-s23-stage2-front-end-executor-diagnostics source-path
                                                       candidate)
        _ (when (seq diagnostics)
            (p15-s23-stage2-front-end-executor-fail!
             (:diagnostic (first diagnostics)) source-path candidate
             {:diagnostics diagnostics}))
        proof-id
        (str "sha256:"
             (sha256-hex
              (pr-str {:source-path source-path
                       :executor executor
                       :stage2-plan-id (:stage2-plan-id accepted-record)
                       :runtime-output
                       (:stage2-front-end-executor-output
                        accepted-record)
                       :rejected-diagnostics
                       (:observed-diagnostics rejected-record)})))
        rejected-proof-records
        (p15-s23-stage2-front-end-executor-rejected-proof-records
         source-path candidate)
        artifact-base
        {:kind :gravity/p15-s23-stage2-front-end-executor-artifact
         :phase "15"
         :task "P15-S23"
         :stage :p15-s23-stage2-front-end-executor
         :source-path source-path
         :proof-id proof-id
         :executor-contract executor
         :rule-record rule-record
         :accepted-record accepted-record
         :rejected-record rejected-record
         :evidence-link-record evidence-link-record
	         :boundary-record boundary-record
	         :linked-artifacts
	         {:stage2-runtime-kernel
	          (select-keys runtime-kernel-artifact
	                       [:kind :artifact-id :proof-id])
	          :stage2-compiler-nucleus
	          (select-keys nucleus-artifact [:kind :artifact-id :proof-id])
          :stage2-plan-emitter
          (select-keys plan-emitter-artifact
                       [:kind :artifact-id :proof-id])
          :stage2-runtime-executor
          (select-keys runtime-artifact [:kind :artifact-id :proof-id])
          :compiler-pipeline-manifest
          (select-keys pipeline-artifact [:kind :artifact-id :proof-id])}
         :full-language-compiler-self-hosted?
         (get-in executor
                 [:self-hosting-claims
                  :full-language-compiler-self-hosted?])
         :clojure-seed-retired?
         (get-in executor [:self-hosting-claims
                           :clojure-seed-retired?])
         :accepted-p15-s23-stage2-front-end-executor-fixtures
         [{:fixture p15-s23-accepted-app-source-path
           :status :accepted
           :stage2-plan-id (:stage2-plan-id accepted-record)
           :stdout (:stage2-front-end-executor-output
                    accepted-record)}]
         :verified-p15-s23-stage2-front-end-executor-rejected-fixtures
         rejected-fixture-records
         :rejected-p15-s23-stage2-front-end-executor-fixtures
         rejected-proof-records
         :p15-s23-stage2-front-end-executor-diagnostic-stream
         (p15-s23-stage2-front-end-executor-diagnostic-stream
          source-path proof-id)
         :p15-s23-stage2-front-end-executor-results
         {:accepted-fixtures 1
          :rejected-fixtures (count rejected-fixture-records)
          :internal-rejected-fixtures (count rejected-proof-records)
          :diagnostic-count
          (count p15-s23-stage2-front-end-executor-diagnostic-ids)
          :stage2-plan-id (:stage2-plan-id accepted-record)
          :accepted-output
          (:stage2-front-end-executor-output accepted-record)
          :rejected-diagnostics (:observed-diagnostics rejected-record)
          :status :in-progress}
         :diagnostics []}
        proof (p15-s23-stage2-front-end-executor-proof artifact-base)]
    (assoc artifact-base
           :capability-based-proof proof
           :artifact-id
           (c4-artifact-id
            (assoc artifact-base :capability-based-proof proof)))))

(defn p15-s23-stage2-front-end-executor-source-artifact
  [source-path]
  (p15-s23-cached-source-artifact
   :p15-s23-stage2-front-end-executor
   source-path
   #(p15-s23-stage2-front-end-executor-source-artifact* source-path)))

(defn p15-s23-stage2-front-end-executor-file-artifact
  [path]
  (when-not (.isFile (java.io.File. path))
    (p15-s23-stage2-front-end-executor-fail!
     "P15S23J001" path nil {:missing-fields [:compiler-source]}))
  (p15-s23-stage2-front-end-executor-source-artifact path))

(defn p15-s23-stage2-front-end-executor-evidence
  []
  (let [source-path "bootstrap/gravity/p15_s23/compiler.gravity"]
    (when (.isFile (java.io.File. source-path))
      (try
        (let [artifact
              (p15-s23-stage2-front-end-executor-file-artifact
               source-path)
              proof (:capability-based-proof artifact)]
          {:status :verified
           :artifact (:kind artifact)
           :artifact-id (:artifact-id artifact)
           :proof-id (:proof-id artifact)
           :source-path source-path
           :stage2-plan-id
           (get-in artifact [:accepted-record :stage2-plan-id])
           :stage2-front-end-executor-used?
           (:stage2-front-end-executor-used? proof)
           :stage2-front-end-host-replaced?
           (:stage2-front-end-host-replaced? proof)
           :does-not-use-clojure-stage2-front-end-host?
           (:does-not-use-clojure-stage2-front-end-host? proof)
           :accepted-output-equivalent?
           (:accepted-output-equivalent? proof)
	           :rejected-diagnostics-equivalent?
	           (:rejected-diagnostics-equivalent? proof)
	           :stage2-runtime-kernel-used?
	           (:stage2-runtime-kernel-used? proof)
	           :stage2-runtime-host-replaced?
	           (:stage2-runtime-host-replaced? proof)
	           :stage2-runtime-primitives-replaced?
	           (:stage2-runtime-primitives-replaced? proof)
	           :gravity-runtime-primitives-used?
	           (:gravity-runtime-primitives-used? proof)
	           :does-not-use-clojure-stage0-runtime-host?
	           (:does-not-use-clojure-stage0-runtime-host? proof)
	           :does-not-use-clojure-runtime-primitives?
	           (:does-not-use-clojure-runtime-primitives? proof)
           :full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? artifact)
           :clojure-seed-retired? (:clojure-seed-retired? artifact)})
        (catch Exception _
          nil)))))

(defn p15-s23-stage2-source-front-end-rule-record
  [front-end]
  (let [steps (set (:front-end-steps front-end))
        missing-steps
        (set/difference p15-s23-stage2-source-front-end-required-steps
                        steps)
        macro-rules (:macro-rules front-end)
        reader-rules (:reader-rules front-end)
        complete?
        (and (= :gravity-stage2-source-front-end-rules-v1
                (:engine front-end))
             (= :gravity-source (:implemented-by front-end))
             (= :gravity-stage2-front-end-executor
                (:executed-by front-end))
             (= :gravity-stage2-reader-rules-v1 (:engine reader-rules))
             (= :gravity-stage2-macro-rules-v1 (:engine macro-rules))
             (contains? (set (:built-in-macros macro-rules)) 'defn)
             (empty? missing-steps))]
    {:artifact :gravity/p15-s23-stage2-source-front-end-rule-record
     :engine (:engine front-end)
     :implemented-by (:implemented-by front-end)
     :executed-by (:executed-by front-end)
     :front-end-steps (p15-s23-stage2-sort-values steps)
     :missing-steps (p15-s23-stage2-sort-values missing-steps)
     :reader-engine (:engine reader-rules)
     :macro-engine (:engine macro-rules)
     :rule-set-complete? complete?
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-source-front-end-accepted-record
  [front-end emitter runtime]
  (let [source-path p15-s23-accepted-app-source-path
        source-text (slurp source-path)
        front-end-record
        (p15-s23-stage2-front-end-source-module-record
         front-end source-path source-text)
        module (:module front-end-record)
        stage2-plan (p15-s23-stage2-emitted-core-plan
                     emitter source-path source-text module)
        runtime-record
        (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
        reference-macro-artifact (macro-source-artifact source-path source-text)
        reference-module
        (assoc (:module reference-macro-artifact)
               :forms (:expanded-forms reference-macro-artifact))
        read-form-parity? (= (:forms front-end-record)
                             (read-forms source-path source-text))
        macro-expanded-form-parity?
        (= (:expanded-forms front-end-record)
           (:expanded-forms reference-macro-artifact))
        module-context-parity?
        (= (select-keys module
                        [:module :profile :target :effects
                         :capabilities :safety])
           (select-keys reference-module
                        [:module :profile :target :effects
                         :capabilities :safety]))
        syntax-count-parity?
        (= (count (:expanded-syntax-object-stream front-end-record))
           (count (:expanded-syntax-object-stream
                   reference-macro-artifact)))
        expected-stdout (get-in front-end
                                [:accepted-scope :expected-stdout])
        output-equivalent? (= expected-stdout (:stdout runtime-record))
        complete?
        (and read-form-parity?
             macro-expanded-form-parity?
             module-context-parity?
             syntax-count-parity?
             output-equivalent?)]
    {:artifact :gravity/p15-s23-stage2-source-front-end-accepted-record
     :fixture source-path
     :front-end-engine (:engine front-end)
     :source-id (:source-id front-end-record)
     :form-count (count (:forms front-end-record))
     :expanded-form-count (count (:expanded-forms front-end-record))
     :macro-expansion-count (count (:macro-expansion-trace
                                    front-end-record))
     :stage2-plan-id (:plan-id stage2-plan)
     :stage2-runtime-execution-record runtime-record
     :stage2-front-end-output (:stdout runtime-record)
     :expected-stdout expected-stdout
     :read-form-parity? read-form-parity?
     :macro-expanded-form-parity? macro-expanded-form-parity?
     :module-context-parity? module-context-parity?
     :syntax-count-parity? syntax-count-parity?
     :accepted-output-equivalent? output-equivalent?
     :stage2-front-end-record
     (select-keys front-end-record
                  [:artifact :source-path :source-id :status])
     :status (if complete? :complete :failed)}))

(defn p15-s23-stage2-source-front-end-rejected-records
  [front-end emitter runtime]
  (mapv
   (fn [{:keys [fixture expected-diagnostic rejected-design]}]
     (let [diagnostic
           (try
             (let [source-text (slurp fixture)
                   front-end-record
                   (p15-s23-stage2-front-end-source-module-record
                    front-end fixture source-text)
                   module (:module front-end-record)
                   stage2-plan
                   (p15-s23-stage2-emitted-core-plan
                    emitter fixture source-text module)]
               (p15-s23-stage2-runtime-execute-plan runtime stage2-plan)
               nil)
             (catch clojure.lang.ExceptionInfo ex
               (:id (ex-data ex))))]
       {:fixture fixture
        :rejected-design rejected-design
        :expected-diagnostic expected-diagnostic
        :status :rejected
        :diagnostic diagnostic
        :matches-expected? (= expected-diagnostic diagnostic)}))
   (:rejected-diagnostic-contract front-end)))

(defn p15-s23-stage2-source-front-end-rejected-record
  [records]
  (let [expected (set (map :expected-diagnostic records))
        observed (set (map :diagnostic records))
        mismatches (remove :matches-expected? records)
        matches? (and (= expected observed) (empty? mismatches))]
    {:artifact :gravity/p15-s23-stage2-source-front-end-rejected-record
     :expected-diagnostics (p15-s23-stage2-sort-values expected)
     :observed-diagnostics (p15-s23-stage2-sort-values observed)
     :fixture-count (count records)
     :mismatch-count (count mismatches)
     :records records
     :status (if matches? :complete :failed)}))

	(defn p15-s23-stage2-source-front-end-evidence-link-record
	  [front-end-executor-artifact nucleus-artifact plan-emitter-artifact
	   runtime-kernel-artifact runtime-artifact pipeline-artifact]
	  (let [links {:stage2-compiler-nucleus
               {:artifact (:kind nucleus-artifact)
                :artifact-id (:artifact-id nucleus-artifact)
                :present?
                (= :gravity/p15-s23-stage2-compiler-nucleus-artifact
                   (:kind nucleus-artifact))}
               :stage2-front-end-executor
               {:artifact (:kind front-end-executor-artifact)
                :artifact-id (:artifact-id front-end-executor-artifact)
                :present?
                (= :gravity/p15-s23-stage2-front-end-executor-artifact
                   (:kind front-end-executor-artifact))}
	               :stage2-plan-emitter
	               {:artifact (:kind plan-emitter-artifact)
                :artifact-id (:artifact-id plan-emitter-artifact)
                :present?
	                (= :gravity/p15-s23-stage2-plan-emitter-artifact
	                   (:kind plan-emitter-artifact))}
	               :stage2-runtime-kernel
	               {:artifact (:kind runtime-kernel-artifact)
	                :artifact-id (:artifact-id runtime-kernel-artifact)
	                :present?
	                (= :gravity/p15-s23-stage2-runtime-kernel-artifact
	                   (:kind runtime-kernel-artifact))}
	               :stage2-runtime-executor
               {:artifact (:kind runtime-artifact)
                :artifact-id (:artifact-id runtime-artifact)
                :present?
                (= :gravity/p15-s23-stage2-runtime-executor-artifact
                   (:kind runtime-artifact))}
               :compiler-pipeline-manifest
               {:artifact (:kind pipeline-artifact)
                :artifact-id (:artifact-id pipeline-artifact)
                :present?
                (= :gravity/p15-s23-compiler-pipeline-manifest-artifact
                   (:kind pipeline-artifact))}}
        missing (set (for [[k v] links :when (not (:present? v))] k))]
    {:artifact :gravity/p15-s23-stage2-source-front-end-evidence-link-record
     :present-links links
     :missing-links (p15-s23-stage2-sort-values missing)
     :all-required-links-present? (empty? missing)
     :status (if (empty? missing) :complete :failed)}))

(defn p15-s23-stage2-source-front-end-boundary-record
  [front-end]
  (let [claims (:self-hosting-claims front-end)
        seed-boundary (:seed-boundary front-end)]
    {:artifact :gravity/p15-s23-stage2-source-front-end-boundary-record
     :implemented-by (:implemented-by front-end)
     :executed-by (:executed-by front-end)
     :compiled-by (get-in front-end [:lineage :compiled-by])
     :stage0-reader-replaced? true
     :stage0-macro-expander-replaced? true
     :stage2-source-front-end-executed? true
     :stage2-front-end-executor-used? true
	     :stage2-front-end-host-replaced?
	     (= :replaced-by-stage2-front-end-executor
	        (:stage2-front-end-host-boundary seed-boundary))
	     :stage2-runtime-kernel-used?
	     (= :p15-s23-stage2-runtime-kernel
	        (:runtime-kernel front-end))
	     :stage2-runtime-host-replaced?
	     (= :replaced-by-stage2-runtime-kernel
	        (:stage0-runtime-host-boundary seed-boundary))
	     :stage2-runtime-primitives-replaced?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :clojure-stage0-reader? false
     :clojure-stage0-macro-expander? false
     :clojure-stage0-front-end-reference?
     (= :clojure-stage0-front-end-reference
        (:stage0-front-end-reference-boundary seed-boundary))
     :clojure-stage2-front-end-host? false
     :clojure-stage0-runtime-host?
     (= :clojure-stage0-runtime-host
        (:stage0-runtime-host-boundary seed-boundary))
	     :clojure-host-primitive-boundary?
	     (= :clojure-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
	     :gravity-runtime-primitives?
	     (= :gravity-runtime-primitives
	        (:host-primitive-boundary seed-boundary))
     :self-hosted-compiler? false
     :full-language-compiler-self-hosted?
     (:full-language-compiler-self-hosted? claims)
     :clojure-seed-retired? (:clojure-seed-retired? claims)
     :seed-boundary seed-boundary
     :next-required-capability (:next-required-capability front-end)
     :status :complete}))

(defn p15-s23-stage2-source-front-end-diagnostics
  [source-path candidate]
  (let [front-end (:front-end-contract candidate)
        rule-record (:rule-record candidate)
        accepted-record (:accepted-record candidate)
        rejected-record (:rejected-record candidate)
        evidence-link-record (:evidence-link-record candidate)
        boundary-record (:boundary-record candidate)
        claims (:self-hosting-claims front-end)
        preserves (set (:preserves front-end))
        emits (set (:emits front-end))
        missing-preserves
        (set/difference
         p15-s23-stage2-source-front-end-required-preserves
         preserves)
        missing-emits
        (set/difference p15-s23-stage2-source-front-end-required-emits
                        emits)]
    (vec
     (concat
      (when-not (and (= :gravity/stage2-source-front-end
                        (:artifact front-end))
                     (= :p15-s23-stage2-source-front-end
                        (:stage front-end))
                     (= :gravity-source (:implemented-by front-end))
                     (= :gravity-stage2-front-end-executor
                        (:executed-by front-end)))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F001" front-end
          {:missing-fields [:artifact :stage :implemented-by
                            :executed-by]})])
      (when-not (= :complete (:status rule-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F002" rule-record
          {:missing-steps (:missing-steps rule-record)})])
      (when-not (= :gravity-stage2-macro-rules-v1
                   (get-in front-end [:macro-rules :engine]))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F003" (:macro-rules front-end)
          {:missing-fields [:macro-rules :engine]})])
      (when-not (= :complete (:status accepted-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F004" accepted-record
          {:expected-stdout (:expected-stdout accepted-record)
           :stage2-front-end-output
           (:stage2-front-end-output accepted-record)})])
      (when-not (= :complete (:status rejected-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F005" rejected-record
          {:expected-diagnostics (:expected-diagnostics rejected-record)
           :observed-diagnostics (:observed-diagnostics rejected-record)})])
      (when-not (= :complete (:status evidence-link-record))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F006" evidence-link-record
          {:missing-links (:missing-links evidence-link-record)})])
      (when (or (seq missing-preserves) (seq missing-emits))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F007" front-end
          {:missing-preserves (p15-s23-stage2-sort-values
                               missing-preserves)
           :missing-emits (p15-s23-stage2-sort-values
                           missing-emits)})])
      (when-not (and (= :complete (:status boundary-record))
                     (true? (:stage0-reader-replaced? boundary-record))
                     (true? (:stage0-macro-expander-replaced?
                             boundary-record))
                     (true? (:stage2-source-front-end-executed?
                             boundary-record))
                     (true? (:stage2-front-end-executor-used?
                             boundary-record))
	                     (true? (:stage2-front-end-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-kernel-used?
	                             boundary-record))
	                     (true? (:stage2-runtime-host-replaced?
	                             boundary-record))
	                     (true? (:stage2-runtime-primitives-replaced?
	                             boundary-record))
	                     (false? (:clojure-stage0-reader? boundary-record))
                     (false? (:clojure-stage0-macro-expander?
                              boundary-record))
	                     (false? (:clojure-stage2-front-end-host?
	                              boundary-record))
	                     (false? (:clojure-stage0-runtime-host?
	                              boundary-record))
	                     (false? (:clojure-host-primitive-boundary?
	                              boundary-record))
	                     (true? (:gravity-runtime-primitives?
	                             boundary-record))
	                     (false? (:full-language-compiler-self-hosted?
                              boundary-record))
                     (false? (:clojure-seed-retired?
                              boundary-record)))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F008" boundary-record
          {:required-boundary [:stage0-reader-replaced
                               :stage0-macro-expander-replaced
                               :stage2-source-front-end-executed
	                               :stage2-front-end-executor-used
	                               :stage2-front-end-host-replaced
	                               :stage2-runtime-kernel-used
	                               :stage2-runtime-host-replaced
	                               :stage2-runtime-primitives-replaced
	                               :clojure-stage0-reader-false
	                               :clojure-stage0-macro-expander-false
	                               :clojure-stage2-front-end-host-false
	                               :clojure-runtime-host-false
	                               :clojure-primitives-false
	                               :gravity-runtime-primitives
	                               :self-hosting-false
                               :clojure-seed-retired-false]})])
      (when (or (true? (:full-language-compiler-self-hosted? claims))
                (true? (:clojure-seed-retired? claims)))
        [(p15-s23-stage2-source-front-end-diagnostic-record
          source-path "P15S23F009" claims
          {:full-language-compiler-self-hosted?
           (:full-language-compiler-self-hosted? claims)
           :clojure-seed-retired?
           (:clojure-seed-retired? claims)})])))))

(defn p15-s23-stage2-source-front-end-diagnostic-stream
  [source-path proof-id]
  {:artifact :gravity/p15-s23-stage2-source-front-end-diagnostic-stream
   :stage :p15-s23-stage2-source-front-end
   :source-path source-path
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p15-s23-stage2-source-front-end
            :message
            (get p15-s23-stage2-source-front-end-diagnostic-messages id)})
         p15-s23-stage2-source-front-end-diagnostic-ids)
   :status :complete})

(defn p15-s23-stage2-source-front-end-rejected-candidates
  [candidate]
  [{:fixture :internal-p15-s23-stage2-source-front-end-missing-contract
    :candidate (assoc candidate :front-end-contract {})
    :expected-diagnostic "P15S23F001"}
   {:fixture :internal-p15-s23-stage2-source-front-end-rule-gap
    :candidate (assoc-in candidate [:rule-record :status] :failed)
    :expected-diagnostic "P15S23F002"}
   {:fixture :internal-p15-s23-stage2-source-front-end-macro-gap
    :candidate (assoc-in candidate
                         [:front-end-contract :macro-rules :engine]
                         :missing)
    :expected-diagnostic "P15S23F003"}
   {:fixture :internal-p15-s23-stage2-source-front-end-output-gap
    :candidate (-> candidate
                   (assoc-in [:accepted-record :status] :failed)
                   (assoc-in [:accepted-record
                              :accepted-output-equivalent?]
                             false))
    :expected-diagnostic "P15S23F004"}
   {:fixture :internal-p15-s23-stage2-source-front-end-rejected-gap
    :candidate (-> candidate
                   (assoc-in [:rejected-record :status] :failed)
                   (assoc-in [:rejected-record :mismatch-count] 1))
    :expected-diagnostic "P15S23F005"}
   {:fixture :internal-p15-s23-stage2-source-front-end-evidence-gap
    :candidate (-> candidate
	                   (assoc-in [:evidence-link-record :status] :failed)
	                   (assoc-in [:evidence-link-record :missing-links]
	                             [:stage2-runtime-kernel]))
    :expected-diagnostic "P15S23F006"}
   {:fixture :internal-p15-s23-stage2-source-front-end-preservation-gap
    :candidate (assoc-in candidate
                         [:front-end-contract :preserves]
                         [])
    :expected-diagnostic "P15S23F007"}
   {:fixture :internal-p15-s23-stage2-source-front-end-boundary-gap
    :candidate (-> candidate
	                   (assoc-in [:boundary-record
	                              :stage2-front-end-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage2-front-end-host?]
	                             true)
	                   (assoc-in [:boundary-record
	                              :stage2-runtime-host-replaced?]
	                             false)
	                   (assoc-in [:boundary-record
	                              :clojure-stage0-runtime-host?]
	                             true))
    :expected-diagnostic "P15S23F008"}
   {:fixture :internal-p15-s23-stage2-source-front-end-overclaim
    :candidate (-> candidate
                   (assoc-in [:front-end-contract :self-hosting-claims
