(def c1-architecture-governing-document
  "docs/phase-06-compiler-architecture/080-c1-compiler-architecture-overview.md")

(def c1-architecture-rejected-designs
  [{:diagnostic "C1-PIPELINE"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-pipeline-order.gravity"
    :rejected-design :hidden-or-noncanonical-stage-order}
   {:diagnostic "C1-PASS-CONTRACT"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-pass-contract.gravity"
    :rejected-design :incomplete-pass-contract}
   {:diagnostic "C1-EVIDENCE-DROP"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-evidence-drop.gravity"
    :rejected-design :silent-metadata-loss}
   {:diagnostic "C1-UNCHECKED-BACKEND"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-unchecked-backend.gravity"
    :rejected-design :backend-from-unchecked-input}
   {:diagnostic "C1-DOMAIN-ANCHOR"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c1-domain-anchor.gravity"
    :rejected-design :unanchored-domain-ir}
   {:diagnostic "C1-MANIFEST"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-manifest-gap.gravity"
    :rejected-design :missing-pipeline-manifest}
   {:diagnostic "C1-SELF-HOST"
    :fixture "bootstrap/clojure/fixtures/rejected/compiler-c1-self-host.gravity"
    :rejected-design :uncomparable-self-hosting-artifact}])

(defn c1-architecture-source-overrides
  [module]
  (get-in module [:metadata :compiler :c1-architecture] {}))

(defn c1-architecture-fail!
  [id source-path subject extra]
  (fail! id
         (case id
           "C1-DOMAIN-ANCHOR" "domain IR lacks a semantic anchor to typed core or MIR"
           "C1-SELF-HOST" "compiler artifact cannot participate in bootstrap comparison"
           "compiler architecture document coverage failed")
         (merge {:source-span (or (:source-span subject)
                                  (source-span source-path 0))
                 :diagnostic-family :c1-compiler-architecture
                 :stage (or (:stage subject) :compiler-architecture)
                 :document-id "C1"
                 :expected-document c1-architecture-governing-document
                 :artifact-id (:artifact-id subject)
                 :domain (:domain subject)
                 :semantic-anchor (:semantic-anchor subject)
                 :remediation "Preserve the C1 pipeline manifest, semantic anchors, verifier gates, provenance graph, diagnostics, and bootstrap comparison inputs as public compiler artifacts."}
                extra)))

(defn c1-architecture-validate-overrides!
  [source-path overrides]
  (case (:fail overrides)
    :domain-anchor
    (c1-architecture-fail!
     "C1-DOMAIN-ANCHOR" source-path
     {:stage :lower-domain-ir
      :artifact-id :gravity/domain-ir
      :domain :efir
      :semantic-anchor nil}
     {:missing-fields [:semantic-anchor]})
    :self-host
    (c1-architecture-fail!
     "C1-SELF-HOST" source-path
     {:stage :record-package-provenance
      :artifact-id :gravity/self-hosting-comparison-inputs}
     {:missing-fields [:stage-outputs-comparable?
                       :compiler-data-gravity-values?]})
    nil))

(defn c1-architecture-artifact-id
  [artifact]
  (str "sha256:"
       (sha256-hex
        (binding [*print-length* 256
                  *print-level* 16]
          (pr-str artifact)))))

(defn c1-architecture-stage-record
  [stage artifact owner-doc]
  {:stage stage
   :owner-doc owner-doc
   :artifact-kind (:kind artifact)
   :artifact-id (c1-architecture-artifact-id artifact)
   :document-set (:document-set artifact)
   :diagnostics (:diagnostics artifact)
   :verifier-result :passed})

(defn c1-architecture-capability-proof
  [artifact]
  (let [contracts (:pass-contract-registry artifact)
        rejected (set (map :diagnostic (:rejected-design-coverage artifact)))
        conformance (:document-conformance artifact)]
    {:pipeline-manifest-emitted?
     (= :gravity/compiler-pipeline (get-in artifact [:pipeline-manifest
                                                     :artifact]))
     :pass-contracts-complete?
     (and (= (count (:canonical-pipeline-order artifact))
             (count contracts))
          (every? #(empty? (compiler-pass-missing-fields
                            % compiler-pass-contract-required-fields))
                  contracts))
     :verifier-gates-executed?
     (every? #(= :passed (:status %)) (:verifier-gate-reports artifact))
     :metadata-preserved?
     (true? (:metadata-preservation-demonstrated? conformance))
     :unchecked-backend-rejected?
     (contains? rejected "C1-UNCHECKED-BACKEND")
     :domain-anchors-linked?
     (true? (:domain-ir-anchors-demonstrated? conformance))
     :invalidation-regeneration-demonstrated?
     (true? (:invalidation-regeneration-demonstrated? conformance))
     :diagnostics-origin-linked?
     (true? (:diagnostics-origin-linked? conformance))
     :bootstrap-comparison-ready?
     (= :ready (get-in artifact [:self-hosting-comparison-inputs :status]))
     :status :complete}))

(defn c1-architecture-validate!
  [source-path artifact]
  (let [proof (c1-architecture-capability-proof artifact)]
    (when-not (:pipeline-manifest-emitted? proof)
      (c1-architecture-fail! "C1-MANIFEST" source-path
                             (:pipeline-manifest artifact)
                             {:missing-fields [:pipeline-manifest]}))
    (when-not (:pass-contracts-complete? proof)
      (c1-architecture-fail! "C1-PASS-CONTRACT" source-path
                             {:stage :pass-contract-registry}
                             {:missing-fields [:pass-contract-registry]}))
    (when-not (:verifier-gates-executed? proof)
      (c1-architecture-fail! "C1-PIPELINE" source-path
                             {:stage :verifier-gates}
                             {:missing-fields [:verifier-gate-reports]}))
    (when-not (:metadata-preserved? proof)
      (c1-architecture-fail! "C1-EVIDENCE-DROP" source-path
                             {:stage :metadata-preservation}
                             {:missing-fields [:metadata-preservation]}))
    (when-not (:unchecked-backend-rejected? proof)
      (c1-architecture-fail! "C1-UNCHECKED-BACKEND" source-path
                             {:stage :lower-target}
                             {:missing-fields [:unchecked-backend-fixture]}))
    (when-not (:domain-anchors-linked? proof)
      (c1-architecture-fail! "C1-DOMAIN-ANCHOR" source-path
                             {:stage :lower-domain-ir}
                             {:missing-fields [:semantic-anchor]}))
    (when-not (:bootstrap-comparison-ready? proof)
      (c1-architecture-fail! "C1-SELF-HOST" source-path
                             {:stage :record-package-provenance}
                             {:missing-fields [:self-hosting-comparison-inputs]})))
  :complete)

(defn compiler-c1-architecture-source-artifact
  [source-path source-text]
  (let [forms (mapv :form (read-source-form-records source-path source-text))
        module (parse-module source-path forms)
        overrides (c1-architecture-source-overrides module)
        _ (c1-architecture-validate-overrides! source-path overrides)
        pass-artifact (compiler-pass-source-artifact source-path source-text)
        checked-artifact (checked-core-source-artifact source-path source-text)
        mir-artifact (mir-source-artifact source-path source-text)
        domain-artifact (domain-ir-source-artifact source-path source-text)
        optimization-artifact (optimization-lowering-source-artifact
                               source-path source-text)
        verification-artifact (compiler-verification-source-artifact
                               source-path source-text)
        stage-records [(c1-architecture-stage-record
                        :compiler-pass-contracts pass-artifact "C1")
                       (c1-architecture-stage-record
                        :checked-core checked-artifact "C1")
                       (c1-architecture-stage-record
                        :mir mir-artifact "C11")
                       (c1-architecture-stage-record
                        :domain-ir domain-artifact "C12")
                       (c1-architecture-stage-record
                        :optimization-lowering optimization-artifact
                        "C13-C14")
                       (c1-architecture-stage-record
                        :compiler-verification verification-artifact
                        "C15-C18")]
        pass-contracts (:pass-contract-registry pass-artifact)
        verifier-gates (mapv (fn [contract]
                               {:stage (:pass contract)
                                :owner-doc (:owner-doc contract)
                                :input (:input contract)
                                :output (:output contract)
                                :status (if (:verifier-gate? contract)
                                          :passed
                                          :not-required)})
                             pass-contracts)
        snapshot-bundle [{:stage :checked-core
                          :artifact-kind (:kind checked-artifact)
                          :artifact-id (c1-architecture-artifact-id
                                        checked-artifact)}
                         {:stage :mir
                          :artifact-kind (:kind mir-artifact)
                          :artifact-id (c1-architecture-artifact-id
                                        mir-artifact)}
                         {:stage :domain-ir
                          :artifact-kind (:kind domain-artifact)
                          :artifact-id (c1-architecture-artifact-id
                                        domain-artifact)}
                         {:stage :optimization-lowering
                          :artifact-kind (:kind optimization-artifact)
                          :artifact-id (c1-architecture-artifact-id
                                        optimization-artifact)}
                         {:stage :compiler-verification
                          :artifact-kind (:kind verification-artifact)
                          :artifact-id (c1-architecture-artifact-id
                                        verification-artifact)}]
        artifact-base
        {:kind :gravity/stage0-c1-compiler-architecture-artifact
         :task "P06-D080"
         :document-set ["C1"]
         :governing-document c1-architecture-governing-document
         :pass {:name :c1-compiler-architecture-document-coverage
                :input :compiler-verification-report
                :output :c1-compiler-architecture-proof
                :requires [:pipeline-manifest :pass-contract-registry
                           :stage-artifacts :diagnostic-stream
                           :provenance-graph :verifier-gates]
                :preserves [:source-spans :syntax-identity :origin-chain
                            :profile :target :types :effects :ownership
                            :capabilities :safety-outcomes :proofs
                            :diagnostics]
                :emits [:c1-document-conformance
                        :c1-capability-proof
                        :self-hosting-comparison-inputs]
                :rejects c1-architecture-diagnostic-ids}
         :source-overrides overrides
         :canonical-pipeline-order (:pipeline-stage-order pass-artifact)
         :pipeline-manifest (:pipeline-manifest pass-artifact)
         :stage-artifact-records stage-records
         :pass-contract-registry pass-contracts
         :evidence-log
         {:artifact :gravity/c1-evidence-log
          :preserved-facts (vec compiler-pass-durable-facts)
          :proofs (concat (:proof-or-certificate-references
                           verification-artifact)
                          (:proof-and-certificate-usage
                           optimization-artifact))
          :invalidations (:invalidated-fact-ledger optimization-artifact)
          :regenerations (mapv :regenerates pass-contracts)
          :status :complete}
         :ir-snapshot-bundle
         {:artifact :gravity/ir-snapshot-bundle
          :snapshots snapshot-bundle
          :status :complete}
         :diagnostic-stream (:diagnostic-stream verification-artifact)
         :artifact-provenance-graph
         {:artifact :gravity/artifact-provenance-graph
          :root (c1-architecture-artifact-id verification-artifact)
          :nodes (mapv #(select-keys % [:stage :artifact-kind
                                         :artifact-id])
                       stage-records)
          :edges [{:from :compiler-pass-contracts :to :checked-core}
                  {:from :checked-core :to :mir}
                  {:from :mir :to :domain-ir}
                  {:from :domain-ir :to :optimization-lowering}
                  {:from :optimization-lowering
                   :to :compiler-verification}]
          :status :complete}
         :verifier-gate-reports verifier-gates
         :self-hosting-comparison-inputs
         {:artifact :gravity/self-hosting-comparison-inputs
          :seed-compiler :gravity-stage0-clojure-bootstrap
          :retirement-objective :replace-with-gravity-self-hosted-compiler
          :public-artifacts (mapv :artifact-kind snapshot-bundle)
          :pass-contracts-loadable-by-package-system? true
          :compiler-data-gravity-values? true
          :stage-outputs-comparable? true
          :status :ready}
         :rejected-design-coverage c1-architecture-rejected-designs
         :document-conformance
         {:pipeline-manifest-emission :complete
          :pass-contract-validation :complete
          :verifier-gate-execution :complete
          :metadata-preservation-demonstrated? true
          :unchecked-backend-rejection :complete
         :domain-ir-anchors-demonstrated?
          (every? #(seq (get-in % [:semantic-anchor :mir-ops]))
                  (:domain-ir-artifacts domain-artifact))
          :invalidation-regeneration-demonstrated?
          (boolean
           (and (seq (:invalidated-fact-ledger optimization-artifact))
                (some seq (map :regenerates pass-contracts))))
          :diagnostics-origin-linked?
          (every? #(or (seq (:origin-chain %))
                       (seq (:related %))
                       (get-in % [:primary :span]))
                  (get-in verification-artifact
                          [:diagnostic-stream :diagnostics]))
          :bootstrap-comparable-artifacts :complete
          :status :complete}
         :diagnostics []}
        _ (c1-architecture-validate! source-path artifact-base)
        capability-proof (c1-architecture-capability-proof artifact-base)
        conformance {:documents ["C1"]
                     :task "P06-D080"
                     :required-diagnostic-ids c1-architecture-diagnostic-ids
                     :pipeline-manifest-status :complete
                     :pass-contract-status :complete
                     :verifier-gate-status :complete
                     :metadata-preservation-status :complete
                     :backend-boundary-status :complete
                     :domain-anchor-status :complete
                     :invalidation-status :complete
                     :diagnostic-origin-status :complete
                     :self-hosting-comparison-status :complete
                     :status :complete}
        artifact (assoc artifact-base
                        :capability-based-proof capability-proof
                        :c1-compiler-architecture-results conformance)]
    (assoc artifact :artifact-id (c1-architecture-artifact-id artifact))))

(defn compiler-c1-architecture-file-artifact
  [path]
  (compiler-c1-architecture-source-artifact path (slurp path)))

