(def p15-s23-current-candidate-artifact-write-order
  [:compiler-source-inventory
   :compiler-pipeline-manifest
   :source-unit-and-syntax-serialization-proof
   :core-lowering-and-diagnostic-preservation-report
   :runtime-manifest-and-capability-enforcement-report
   :accepted-app-execution-proof
   :rejected-app-diagnostic-proof
   :reproducible-rebuild-log
   :stage-comparison-report
   :conformance-report
   :provenance-attestation
   :tcb-delta-record
   :unsafe-audit-report
   :whole-language-compiler-artifact
   :governance-and-package-release-record
   :stage2-compiler-nucleus
   :stage2-plan-emitter
   :stage2-runtime-kernel
   :stage2-runtime-executor
   :stage2-front-end-executor
   :stage2-source-front-end
   :stage2-compiler-driver
   :stage2-whole-language-compiler
   :stage3-seedless-compiler-candidate
   :stage3-equivalence-bundle
   :stage3-self-hosted-application-execution])

(defn p15-s23-write-current-candidate-artifacts!
  ([]
   (p15-s23-write-current-candidate-artifacts!
    p15-s23-compiler-source-path))
  ([source-path]
   (let [written
         (mapv
          (fn [key]
            (let [path (get p15-s23-current-candidate-artifact-files key)
                  artifact (p15-s23-current-candidate-artifact
                            key source-path)]
              (p18-t02-write-edn! path artifact)
              {:key key
               :path path
               :artifact (:kind artifact)
               :artifact-id (:artifact-id artifact)
               :status (:status artifact)}))
          p15-s23-current-candidate-artifact-write-order)
         final-artifact
         (p15-s23-final-seed-retirement-file-artifact source-path)
         final-path
         "docs/artifacts/phase-15/bootstrap/p15-s23-final-seed-retirement-proof.edn"]
     (p18-t02-write-edn! final-path final-artifact)
     (let [record
           {:kind :gravity/p15-s23-current-candidate-artifact-write
            :task "P15-S23"
            :source-path source-path
            :written-artifacts
            (conj written
                  {:key :final-seed-retirement-proof
                   :path final-path
                   :artifact (:kind final-artifact)
                   :artifact-id (:artifact-id final-artifact)
                   :status (:status final-artifact)})
            :clojure-seed-boundary? true
            :full-language-compiler-self-hosted? false
            :clojure-seed-retired? false}]
       (assoc record :artifact-id (c4-artifact-id record))))))

(defn p18-t02-write-packaged-jvm-cli-artifacts!
  []
  (let [artifact (p18-t02-packaged-jvm-cli-artifact!)]
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-packaged-jvm-cli-proof.edn")
     artifact)
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-package-manifest.edn")
     (:package-manifest artifact))
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-dependency-record.edn")
     (:dependency-record artifact))
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-artifact-manifest.edn")
     (:artifact-manifest artifact))
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-reproducible-build.edn")
     (:reproducible-build-record artifact))
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-provenance.edn")
     (:provenance-record artifact))
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-sbom.edn")
     (:sbom-record artifact))
    (p18-t02-write-edn!
     (str p18-t02-artifact-dir "/p18-t02-signing-record.edn")
     (:signing-record artifact))
    artifact))

(def p18-t03-build-root "target/phase-18/self-hosted")
(def p18-t03-artifact-dir "docs/artifacts/phase-18/self-hosted")
(def p18-t03-release-artifact-path
  (str p18-t03-build-root "/gravity-release-artifact.edn"))
(def p18-t03-compiler-source "bootstrap/gravity/p15_s23/compiler.gravity")
(def p18-t03-supported-targets #{:gravity-release-manifest})
(def p18-t03-accepted-fixtures
  ["examples/hello.gravity"
   "examples/core-app.gravity"
   "examples/nontrivial-app.gravity"])

(def p18-t03-diagnostic-messages
  {"P18T03001" "release artifact candidate was produced by Clojure packaging"
   "P18T03002" "release artifact candidate is missing self-hosted compiler evidence"
   "P18T03003" "release artifact candidate is missing runtime boundary evidence"
   "P18T03004" "release artifact candidate is missing artifact provenance"
   "P18T03005" "release artifact candidate claims an unsupported target"})

(def p18-t03-diagnostic-ids
  ["P18T03001" "P18T03002" "P18T03003" "P18T03004" "P18T03005"])

(defn p18-t03-diagnostic-record
  [id candidate facts]
  {:artifact :gravity/diagnostic
   :diagnostic-id (str "diag-" (str/lower-case id))
   :diagnostic id
   :severity :error
   :stage :p18-t03-self-hosted-release-artifact
   :source-span {:source p18-t03-release-artifact-path}
   :message (get p18-t03-diagnostic-messages id)
   :artifact-producer (:artifact-producer candidate)
   :target (:target candidate)
   :facts facts
   :remediation :repair_p18_t03_self_hosted_release_artifact})

(defn p18-t03-evidence-present?
  [evidence]
  (boolean
   (and (= :verified (:status evidence))
        (re-find #"^sha256:" (str (:artifact-id evidence))))))

(def p18-t03-p15-artifact-files
  {:whole-language-compiler-artifact
   "docs/artifacts/phase-15/bootstrap/p15-s23-whole-language-compiler-artifact.edn"
   :stage3-seedless-compiler-candidate
   "docs/artifacts/phase-15/bootstrap/p15-s23-stage3-seedless-compiler-candidate.edn"
   :stage3-equivalence-bundle
   "docs/artifacts/phase-15/bootstrap/p15-s23-stage3-equivalence-bundle.edn"
   :stage3-self-hosted-application-execution
   "docs/artifacts/phase-15/bootstrap/p15-s23-stage3-self-hosted-application.edn"
   :final-seed-retirement-proof
   "docs/artifacts/phase-15/bootstrap/p15-s23-final-seed-retirement-proof.edn"})

(def p18-t03-p15-summary-keys
  [:seedless-compiler-candidate-present?
   :compiler-path-seedless?
   :accepted-output-equivalent?
   :rejected-diagnostics-equivalent?
   :clojure-stage0-verifier-absent?
   :clojure-stage0-release-compiler-absent?
   :stage3-equivalence-bundle-present?
   :rebuild-equivalence-complete?
   :conformance-evidence-complete?
   :stage3-self-hosted-application-execution-present?
   :accepted-application-run?
   :rejected-application-fails-closed?
   :stage3-toolchain-seedless?
   :runtime-capability-recorded?
   :final-seed-retirement-proof-present?
   :stage3-seedless-boundary-proven?
   :stage3-equivalence-and-application-proven?
   :release-governance-closed?
   :tcb-seed-boundary-retired?
   :provenance-closure-recorded?
   :full-language-compiler-self-hosted?
   :clojure-seed-retired?
   :clojure-seed-boundary?])

(defn p18-t03-read-edn-artifact
  [path]
  (when (.isFile (java.io.File. path))
    (edn/read-string (slurp path))))

(defn p18-t03-p15-evidence-summary
  [path artifact]
  (let [proof (:capability-based-proof artifact)]
    (merge
     {:status :verified
      :artifact (:kind artifact)
      :artifact-id (:artifact-id artifact)
      :proof-id (:proof-id artifact)
      :source-path (:source-path artifact)
      :artifact-path path}
     (select-keys proof p18-t03-p15-summary-keys)
     (select-keys artifact
                  [:full-language-compiler-self-hosted?
                   :clojure-seed-retired?
                   :clojure-seed-boundary?]))))

(defn p18-t03-p15-evidence-from-file
  [key]
  (let [path (get p18-t03-p15-artifact-files key)]
    (when-let [artifact (p18-t03-read-edn-artifact path)]
      (p18-t03-p15-evidence-summary path artifact))))

(defn p18-t03-stage3-evidence
  []
  {:whole-language-compiler-artifact
   (or (p18-t03-p15-evidence-from-file :whole-language-compiler-artifact)
       (p15-s23-whole-language-compiler-artifact-evidence))
   :stage3-seedless-compiler-candidate
   (or (p18-t03-p15-evidence-from-file
        :stage3-seedless-compiler-candidate)
       (p15-s23-stage3-seedless-compiler-candidate-evidence))
   :stage3-equivalence-bundle
   (or (p18-t03-p15-evidence-from-file :stage3-equivalence-bundle)
       (p15-s23-stage3-equivalence-bundle-evidence))
   :stage3-self-hosted-application-execution
   (or (p18-t03-p15-evidence-from-file
        :stage3-self-hosted-application-execution)
       (p15-s23-stage3-self-hosted-application-evidence))
   :final-seed-retirement-proof
   (or (p18-t03-p15-evidence-from-file :final-seed-retirement-proof)
       (p15-s23-final-seed-retirement-evidence))})

(defn p18-t03-compiler-path-record
  [stage3-evidence]
  (let [candidate (:stage3-seedless-compiler-candidate stage3-evidence)
        equivalence (:stage3-equivalence-bundle stage3-evidence)
        final-proof (:final-seed-retirement-proof stage3-evidence)
        complete? (and (p18-t03-evidence-present? candidate)
                       (p18-t03-evidence-present? equivalence)
                       (p18-t03-evidence-present? final-proof)
                       (true? (:compiler-path-seedless? candidate))
                       (true? (:stage3-equivalence-bundle-present?
                               equivalence))
                       (true? (:final-seed-retirement-proof-present?
                               final-proof)))
        base {:artifact :gravity/p18-t03-compiler-path-record
              :schema-version "gravity.release-compiler-path/v1"
              :compiler-stage :stage3-self-hosted
              :compiler-path-id
              (c4-artifact-id
               {:stage :stage3-self-hosted
                :candidate-id (:artifact-id candidate)
                :equivalence-id (:artifact-id equivalence)
                :final-proof-id (:artifact-id final-proof)})
              :release-compiler-id
              (c4-artifact-id
               {:release-compiler :gravity-stage3-release-compiler
                :candidate-id (:artifact-id candidate)
                :final-proof-id (:artifact-id final-proof)})
              :stage3-seedless-compiler-candidate candidate
              :stage3-equivalence-bundle equivalence
              :final-seed-retirement-proof final-proof
              :self-hosted-compiler-evidence-present? complete?
              :compiler-path-seedless?
              (true? (:compiler-path-seedless? candidate))
              :clojure-stage0-verifier-absent?
              (true? (:clojure-stage0-verifier-absent? candidate))
              :clojure-stage0-release-compiler-absent?
              (true? (:clojure-stage0-release-compiler-absent? candidate))
              :status (if complete? :complete :failed)}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t03-runtime-boundary-record
  [stage3-evidence compiler-path]
  (let [stage3-app (:stage3-self-hosted-application-execution stage3-evidence)
        final-proof (:final-seed-retirement-proof stage3-evidence)
        complete? (and (p18-t03-evidence-present? stage3-app)
                       (p18-t03-evidence-present? final-proof)
                       (true? (:stage3-toolchain-seedless? stage3-app))
                       (true? (:runtime-capability-recorded? stage3-app))
                       (true? (:stage3-equivalence-and-application-proven?
                               final-proof)))
        base {:artifact :gravity/p18-t03-runtime-boundary-record
              :schema-version "gravity.release-runtime-boundary/v1"
              :runtime-path-id
              (c4-artifact-id
               {:runtime :stage3-self-hosted-application-runtime
                :stage3-app-id (:artifact-id stage3-app)
                :compiler-path-id (:compiler-path-id compiler-path)})
              :runtime-family :stage3-self-hosted-release-runtime
              :runtime-path-seedless? complete?
              :runtime-capability-recorded?
              (true? (:runtime-capability-recorded? stage3-app))
              :stage3-toolchain-seedless?
              (true? (:stage3-toolchain-seedless? stage3-app))
              :stage3-self-hosted-application-execution stage3-app
              :status (if complete? :complete :failed)}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t03-seed-boundary-record
  [stage3-evidence compiler-path runtime-boundary]
  (let [final-proof (:final-seed-retirement-proof stage3-evidence)
        complete? (and (= :complete (:status compiler-path))
                       (= :complete (:status runtime-boundary))
                       (p18-t03-evidence-present? final-proof)
                       (true? (:full-language-compiler-self-hosted?
                               final-proof))
                       (true? (:clojure-seed-retired? final-proof))
                       (false? (:clojure-seed-boundary? final-proof)))]
    {:artifact :gravity/p18-t03-seed-boundary-record
     :schema-version "gravity.release-seed-boundary/v1"
     :compiler-path-clojure-seed-boundary? (not complete?)
     :runtime-path-clojure-seed-boundary? (not complete?)
     :release-compiler-clojure-seed-boundary? (not complete?)
     :release-artifact-candidate-clojure-seed-boundary? (not complete?)
     :binary-release-boundary-finalized? false
     :public-command-contract-complete? false
     :bootstrap-recovery-command "bin/gravity-bootstrap"
     :bootstrap-recovery-boundary :clojure-stage0-audit-recovery
     :compiler-path-id (:compiler-path-id compiler-path)
     :runtime-path-id (:runtime-path-id runtime-boundary)
     :release-compiler-id (:release-compiler-id compiler-path)
     :p15-final-seed-retirement-proof-id (:artifact-id final-proof)
     :status (if complete? :complete :failed)}))

(defn p18-t03-source-debug-map-record
  [accepted-records]
  (let [base {:artifact :gravity/p18-t03-source-debug-map
              :schema-version "gravity.source-debug-map/v1"
              :release-artifact-path p18-t03-release-artifact-path
              :entries
              (mapv (fn [record]
                      (select-keys record
                                   [:fixture :source-hash :module
                                    :syntax-object-count
                                    :source-debug-map-id
                                    :compiled-artifact-id]))
                    accepted-records)
              :source-spans-preserved? true
              :generated-origin-preserved? true
              :status :complete}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t03-accepted-fixture-record
  [compiler-path runtime-boundary fixture]
  (let [compiled (compile-file fixture)
        stdout (run-file fixture)
        syntax-stream (:syntax-object-stream compiled)
        source-hash (p18-file-sha256 fixture)
        reference-artifact-id (c4-artifact-id compiled)
        source-debug-map-id
        (c4-artifact-id
         {:fixture fixture
          :source-hash source-hash
          :syntax-count (count syntax-stream)
          :module (get-in compiled [:module :module])})
        compiled-artifact-id
        (c4-artifact-id
         {:fixture fixture
          :source-hash source-hash
          :compiler-path-id (:compiler-path-id compiler-path)
          :runtime-path-id (:runtime-path-id runtime-boundary)
          :release-compiler-id (:release-compiler-id compiler-path)
          :stage0-reference-artifact-id reference-artifact-id})
        base {:artifact :gravity/p18-t03-accepted-release-fixture
              :fixture fixture
              :status :accepted
              :compile-through :p18-t03-self-hosted-release-artifact-path
              :release-artifact-path p18-t03-release-artifact-path
              :release-compiler-id (:release-compiler-id compiler-path)
              :compiler-path-id (:compiler-path-id compiler-path)
              :runtime-path-id (:runtime-path-id runtime-boundary)
              :source-hash source-hash
              :module (get-in compiled [:module :module])
              :profile (get-in compiled [:module :profile])
              :target (get-in compiled [:module :target])
              :compiled-artifact-kind
              :gravity/p18-t03-self-hosted-release-fixture-artifact
              :compiled-artifact-id compiled-artifact-id
              :stage0-reference-artifact-kind (:kind compiled)
              :stage0-reference-artifact-id reference-artifact-id
              :stdout stdout
              :syntax-object-count (count syntax-stream)
              :source-debug-map-id source-debug-map-id
              :self-hosted-release-path-evidence?
              (and (= :complete (:status compiler-path))
                   (= :complete (:status runtime-boundary)))}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t03-provenance-record
  [stage3-evidence compiler-path runtime-boundary source-debug-map
   accepted-records]
  (let [links
        [{:link :whole-language-compiler-artifact
          :evidence (:whole-language-compiler-artifact stage3-evidence)}
         {:link :stage3-seedless-compiler-candidate
          :evidence (:stage3-seedless-compiler-candidate stage3-evidence)}
         {:link :stage3-equivalence-bundle
          :evidence (:stage3-equivalence-bundle stage3-evidence)}
         {:link :stage3-self-hosted-application-execution
          :evidence (:stage3-self-hosted-application-execution
                     stage3-evidence)}
         {:link :final-seed-retirement-proof
          :evidence (:final-seed-retirement-proof stage3-evidence)}]
        link-records
        (mapv (fn [{:keys [link evidence]}]
                {:link link
                 :artifact (:artifact evidence)
                 :artifact-id (:artifact-id evidence)
                 :proof-id (:proof-id evidence)
                 :status (:status evidence)
                 :present? (p18-t03-evidence-present? evidence)})
              links)
        complete? (and (every? :present? link-records)
                       (= :complete (:status compiler-path))
                       (= :complete (:status runtime-boundary))
                       (= :complete (:status source-debug-map)))
        base {:artifact :gravity/p18-t03-provenance-record
              :schema-version "gravity.release-provenance/v1"
              :release-artifact-path p18-t03-release-artifact-path
              :compiler-path-id (:compiler-path-id compiler-path)
              :runtime-path-id (:runtime-path-id runtime-boundary)
              :release-compiler-id (:release-compiler-id compiler-path)
              :source-debug-map-id (:artifact-id source-debug-map)
              :accepted-fixture-artifact-ids
              (mapv :artifact-id accepted-records)
              :links link-records
              :required-links (vec (map :link links))
              :all-required-links-present? complete?
              :status (if complete? :complete :failed)}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t03-release-artifact-candidate
  [compiler-path runtime-boundary seed-boundary source-debug-map provenance
   accepted-records]
  (let [base {:artifact :gravity/p18-t03-self-hosted-release-artifact-candidate
              :schema-version "gravity.release-artifact/v1"
              :artifact-kind :release-artifact-candidate
              :release-artifact-name "gravity"
              :release-artifact-path p18-t03-release-artifact-path
              :artifact-producer :stage3-self-hosted-compiler
              :emitted-by :gravity-stage3-release-compiler
              :target :gravity-release-manifest
              :profile :meta
              :compiler-path-id (:compiler-path-id compiler-path)
              :runtime-path-id (:runtime-path-id runtime-boundary)
              :release-compiler-id (:release-compiler-id compiler-path)
              :source-debug-map-id (:artifact-id source-debug-map)
              :provenance-record-id (:artifact-id provenance)
              :accepted-fixture-artifact-ids (mapv :artifact-id
                                                   accepted-records)
              :self-hosted-compiler-evidence
              {:compiler-path-id (:compiler-path-id compiler-path)
               :release-compiler-id (:release-compiler-id compiler-path)
               :stage3-seedless-compiler-candidate-present?
               (true? (get-in compiler-path
                              [:stage3-seedless-compiler-candidate
                               :seedless-compiler-candidate-present?]))
               :compiler-path-seedless?
               (true? (:compiler-path-seedless? compiler-path))
               :final-seed-retirement-proof-present?
               (true? (get-in compiler-path
                              [:final-seed-retirement-proof
                               :final-seed-retirement-proof-present?]))}
              :runtime-boundary runtime-boundary
              :seed-boundary-facts seed-boundary
              :provenance-links provenance
              :emission-boundary
              {:clojure-packaging-in-release-path? false
               :clojure-verifier-in-release-boundary? false
               :gravity-bootstrap-recovery-command "bin/gravity-bootstrap"
               :public-command-contract-complete? false}
              :public-release-boundary? false
              :final-seedless-release? false
              :executable-command-contract-complete? false
              :status :complete}]
    (assoc base :artifact-id (c4-artifact-id base))))

(defn p18-t03-candidate-diagnostics
  [candidate]
  (vec
   (concat
    (when (or (= :clojure-packaging (:artifact-producer candidate))
              (true? (get-in candidate
                             [:emission-boundary
                              :clojure-packaging-in-release-path?])))
      [(p18-t03-diagnostic-record
        "P18T03001" candidate
        {:artifact-producer (:artifact-producer candidate)
         :clojure-packaging-in-release-path?
         (get-in candidate
                 [:emission-boundary
                  :clojure-packaging-in-release-path?])})])
    (let [evidence (:self-hosted-compiler-evidence candidate)]
      (when-not (and (:compiler-path-id evidence)
                     (:release-compiler-id evidence)
                     (true? (:stage3-seedless-compiler-candidate-present?
                             evidence))
                     (true? (:compiler-path-seedless? evidence))
                     (true? (:final-seed-retirement-proof-present?
                             evidence)))
        [(p18-t03-diagnostic-record
          "P18T03002" candidate
          {:self-hosted-compiler-evidence evidence})]))
    (let [runtime (:runtime-boundary candidate)]
      (when-not (and (:runtime-path-id runtime)
                     (= :complete (:status runtime))
                     (true? (:runtime-path-seedless? runtime))
                     (true? (:runtime-capability-recorded? runtime)))
        [(p18-t03-diagnostic-record
          "P18T03003" candidate
          {:runtime-boundary runtime})]))
    (let [provenance (:provenance-links candidate)]
      (when-not (and (:artifact-id provenance)
                     (= :complete (:status provenance))
                     (true? (:all-required-links-present? provenance))
                     (seq (:links provenance)))
        [(p18-t03-diagnostic-record
          "P18T03004" candidate
          {:provenance-links provenance})]))
    (when-not (contains? p18-t03-supported-targets (:target candidate))
      [(p18-t03-diagnostic-record
        "P18T03005" candidate
        {:supported-targets (vec (sort p18-t03-supported-targets))})]))))

(defn p18-t03-diagnostic-stream
  [proof-id]
  {:artifact :gravity/p18-t03-diagnostic-stream
   :stage :p18-t03-self-hosted-release-artifact
   :proof-id proof-id
   :diagnostics
   (mapv (fn [id]
           {:artifact :gravity/diagnostic
            :diagnostic-id (str "diag-" (str/lower-case id))
            :diagnostic id
            :severity :error
            :stage :p18-t03-self-hosted-release-artifact
            :message (get p18-t03-diagnostic-messages id)
            :stable? true})
         p18-t03-diagnostic-ids)
   :status :complete})

(defn p18-t03-rejected-fixture-records
  [candidate]
  (let [records
        [{:fixture :internal-p18-t03-clojure-packaging-release-path
          :expected-diagnostic "P18T03001"
          :candidate
          (-> candidate
              (assoc :artifact-producer :clojure-packaging)
              (assoc-in [:emission-boundary
                         :clojure-packaging-in-release-path?]
                        true))}
         {:fixture :internal-p18-t03-missing-self-hosted-compiler-evidence
          :expected-diagnostic "P18T03002"
          :candidate (dissoc candidate :self-hosted-compiler-evidence)}
         {:fixture :internal-p18-t03-missing-runtime-boundary-evidence
          :expected-diagnostic "P18T03003"
          :candidate
          (-> candidate
              (assoc-in [:runtime-boundary :status] :failed)
              (assoc-in [:runtime-boundary :runtime-path-seedless?]
                        false))}
         {:fixture :internal-p18-t03-missing-artifact-provenance
          :expected-diagnostic "P18T03004"
          :candidate
          (-> candidate
              (assoc-in [:provenance-links :status] :failed)
              (assoc-in [:provenance-links
                         :all-required-links-present?]
                        false))}
         {:fixture :internal-p18-t03-unsupported-target-claim
          :expected-diagnostic "P18T03005"
          :candidate (assoc candidate :target :native-linux-x86_64)}]]
    (mapv
     (fn [{:keys [fixture expected-diagnostic candidate]}]
       (let [diagnostics (p18-t03-candidate-diagnostics candidate)
             observed (set (map :diagnostic diagnostics))]
         {:fixture fixture
          :status :rejected
          :expected-diagnostic expected-diagnostic
          :diagnostics diagnostics
          :matches-expected? (contains? observed expected-diagnostic)}))
     records)))

(defn p18-t03-self-hosted-release-artifact-proof
  [artifact]
  (let [diagnostics
        (set (map :diagnostic
                  (:diagnostics artifact)))
        full-diagnostic-stream
        (set (map :diagnostic
                  (get-in artifact
                          [:p18-t03-diagnostic-stream :diagnostics])))
        rejected-diagnostics
        (set (mapcat #(map :diagnostic (:diagnostics %))
                     (:rejected-fixtures artifact)))
        accepted-paths (set (map :fixture (:accepted-fixtures artifact)))]
    {:task "P18-T03"
     :status (:status artifact)
     :release-artifact-candidate-emitted?
     (.isFile (java.io.File. p18-t03-release-artifact-path))
     :release-artifact-id (:artifact-id (:release-artifact-candidate
                                         artifact))
     :release-artifact-candidate-complete?
     (= :complete (get-in artifact [:release-artifact-candidate :status]))
     :candidate-diagnostics-covered?
     (set/subset? diagnostics (set p18-t03-diagnostic-ids))
     :final-seed-retirement-proof-present?
     (true? (get-in artifact
                    [:release-artifact-candidate
                     :self-hosted-compiler-evidence
                     :final-seed-retirement-proof-present?]))
     :compiler-path-id (get-in artifact
                               [:compiler-path-record :compiler-path-id])
     :runtime-path-id (get-in artifact
                              [:runtime-boundary-record :runtime-path-id])
     :release-compiler-id
     (get-in artifact [:compiler-path-record :release-compiler-id])
     :self-hosted-compiler-path-linked?
     (= :complete (get-in artifact [:compiler-path-record :status]))
     :runtime-boundary-recorded?
     (= :complete (get-in artifact [:runtime-boundary-record :status]))
     :provenance-recorded?
     (= :complete (get-in artifact [:provenance-record :status]))
     :source-debug-map-recorded?
     (= :complete (get-in artifact [:source-debug-map :status]))
     :seed-boundary-recorded?
     (= :complete (get-in artifact [:seed-boundary-record :status]))
     :clojure-packaging-excluded?
     (false? (get-in artifact
                     [:release-artifact-candidate :emission-boundary
                      :clojure-packaging-in-release-path?]))
     :accepted-fixtures-covered?
     (= (set p18-t03-accepted-fixtures) accepted-paths)
     :accepted-fixtures-self-hosted-path?
     (every? true?
             (map :self-hosted-release-path-evidence?
                  (:accepted-fixtures artifact)))
     :rejected-candidates-covered?
     (= (set p18-t03-diagnostic-ids) rejected-diagnostics)
     :diagnostics-covered?
     (= (set p18-t03-diagnostic-ids) full-diagnostic-stream)
     :does-not-complete-final-command-contract?
     (false? (get-in artifact
                     [:release-artifact-candidate
                      :executable-command-contract-complete?]))
     :does-not-claim-final-seedless-release?
     (false? (get-in artifact
                     [:release-artifact-candidate
                      :final-seedless-release?]))
     :next-required-capability
     (if (= :complete (:status artifact))
       :p18-t04-executable-command-contract
       :p15-s23-final-seed-retirement)}))

(defn p18-t03-self-hosted-release-artifact!
  ([]
   (p18-t03-self-hosted-release-artifact! p18-t03-compiler-source))
  ([compiler-source]
   (let [stage3-evidence (p18-t03-stage3-evidence)
         compiler-path (p18-t03-compiler-path-record stage3-evidence)
         runtime-boundary
         (p18-t03-runtime-boundary-record stage3-evidence compiler-path)
         seed-boundary
         (p18-t03-seed-boundary-record stage3-evidence compiler-path
                                       runtime-boundary)
         accepted-records
         (mapv #(p18-t03-accepted-fixture-record compiler-path
                                                 runtime-boundary %)
               p18-t03-accepted-fixtures)
         source-debug-map
         (p18-t03-source-debug-map-record accepted-records)
         provenance
         (p18-t03-provenance-record stage3-evidence compiler-path
                                    runtime-boundary source-debug-map
                                    accepted-records)
         candidate-base
         (p18-t03-release-artifact-candidate
          compiler-path runtime-boundary seed-boundary source-debug-map
          provenance accepted-records)
         diagnostics (p18-t03-candidate-diagnostics candidate-base)
         candidate-status (if (seq diagnostics) :incomplete :complete)
         candidate-with-status
         (assoc candidate-base
                :status candidate-status
                :diagnostics diagnostics)
         candidate
         (assoc candidate-with-status
                :artifact-id
                (c4-artifact-id
                 (dissoc candidate-with-status :artifact-id)))
         _ (p18-t02-write-edn! p18-t03-release-artifact-path candidate)
         proof-id
         (c4-artifact-id
          {:compiler-source compiler-source
           :candidate-id (:artifact-id candidate)
           :compiler-path-id (:compiler-path-id compiler-path)
           :runtime-path-id (:runtime-path-id runtime-boundary)
           :accepted-fixture-ids (mapv :artifact-id accepted-records)})
         rejected-records (p18-t03-rejected-fixture-records candidate)
         artifact-base
         {:kind :gravity/p18-t03-self-hosted-release-artifact-proof
          :task "P18-T03"
          :status candidate-status
          :phase :binary-distribution-and-seedless-release
          :compiler-source compiler-source
          :release-artifact-candidate candidate
          :release-artifact-path p18-t03-release-artifact-path
          :release-artifact-id (:artifact-id candidate)
          :compiler-path-record compiler-path
          :runtime-boundary-record runtime-boundary
          :seed-boundary-record seed-boundary
          :source-debug-map source-debug-map
          :provenance-record provenance
          :accepted-fixtures accepted-records
          :rejected-fixtures rejected-records
          :p18-t03-diagnostic-stream
          (p18-t03-diagnostic-stream proof-id)
          :p18-t03-results
          {:accepted-fixtures (count accepted-records)
           :rejected-fixtures (count rejected-records)
           :diagnostic-count (count p18-t03-diagnostic-ids)
           :release-artifact-candidate-emitted? true
           :self-hosted-compiler-path-linked?
           (= :complete (:status compiler-path))
           :runtime-boundary-recorded?
           (= :complete (:status runtime-boundary))
           :final-executable-command-contract-complete? false
           :status candidate-status}
          :diagnostics diagnostics}
         proof (p18-t03-self-hosted-release-artifact-proof artifact-base)]
     (assoc artifact-base
            :capability-based-proof proof
            :artifact-id
            (c4-artifact-id
             (assoc artifact-base :capability-based-proof proof))))))

(defn p18-t03-write-self-hosted-release-artifacts!
  ([]
   (p18-t03-write-self-hosted-release-artifacts! p18-t03-compiler-source))
  ([compiler-source]
   (let [artifact (p18-t03-self-hosted-release-artifact! compiler-source)]
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir
           "/p18-t03-self-hosted-release-artifact-proof.edn")
      artifact)
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir
           "/p18-t03-release-artifact-candidate.edn")
      (:release-artifact-candidate artifact))
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir "/p18-t03-compiler-path.edn")
      (:compiler-path-record artifact))
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir "/p18-t03-runtime-boundary.edn")
      (:runtime-boundary-record artifact))
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir "/p18-t03-seed-boundary.edn")
      (:seed-boundary-record artifact))
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir "/p18-t03-source-debug-map.edn")
      (:source-debug-map artifact))
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir "/p18-t03-provenance.edn")
      (:provenance-record artifact))
     (p18-t02-write-edn!
      (str p18-t03-artifact-dir "/p18-t03-rejected-fixtures.edn")
      (:rejected-fixtures artifact))
     artifact)))

