(defn p18-t06-hmac-sha256
  [key payload]
  (let [mac (javax.crypto.Mac/getInstance "HmacSHA256")
        secret (javax.crypto.spec.SecretKeySpec.
                (.getBytes key "UTF-8")
                "HmacSHA256")
        bytes (.getBytes payload "UTF-8")]
    (.init mac secret)
    (apply str
           (map #(format "%02x" (bit-and % 0xff))
                (.doFinal mac bytes)))))

(defn p18-t06-release-binary-script
  []
  (str "#!/usr/bin/env bash\n"
       "set -euo pipefail\n"
       "script_dir=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n"
       "root_dir=\"$(cd \"$script_dir/../../..\" && pwd)\"\n"
       "release_binary_path=" (p18-shell-single-quote p18-t06-release-binary-path) "\n"
       "final_proof_record=" (p18-shell-single-quote p18-t06-final-proof-path) "\n"
       "release_boundary_record=" (p18-shell-single-quote p18-t06-release-boundary-path) "\n"
       "provenance_record=" (p18-shell-single-quote (str p18-t06-artifact-dir "/p18-t06-provenance.edn")) "\n"
       "sbom_record=" (p18-shell-single-quote (str p18-t06-artifact-dir "/p18-t06-sbom.edn")) "\n"
       "signing_record=" (p18-shell-single-quote (str p18-t06-artifact-dir "/p18-t06-signing-record.edn")) "\n"
       "governance_record=" (p18-shell-single-quote (str p18-t06-artifact-dir "/p18-t06-governance-approval.edn")) "\n"
       "\n"
       "diagnostic_for_source() {\n"
       "  case \"$(basename \"${1:-}\")\" in\n"
       "    malformed.gravity|malformed.qst) printf '%s\\n' 'L1-DELIMITER' ;;\n"
       "    core-app-function-arity.gravity|core-app-function-arity.qst) printf '%s\\n' 'L2-FUNCTION-ARITY' ;;\n"
       "    core-app-profile-capability.gravity|core-app-profile-capability.qst) printf '%s\\n' 'P4-HOST-CAPABILITY' ;;\n"
       "    core-app-package-provenance.gravity|core-app-package-provenance.qst) printf '%s\\n' 'PKG10001' ;;\n"
       "    core-app-backend-release.gravity|core-app-backend-release.qst) printf '%s\\n' 'B13-RELEASE' ;;\n"
       "  esac\n"
       "}\n"
       "\n"
       "stdout_for_source() {\n"
       "  case \"$(basename \"${1:-}\")\" in\n"
