(defn -main
  [& args]
    (try
    (let [[command path] args]
      (case command
        "help" (print (p18-cli-help-text))
        "--help" (print (p18-cli-help-text))
        "-h" (print (p18-cli-help-text))
        "--version" (prn (p18-cli-version-record))
